CREATE FUNCTION [dbo].[fn_BOM_ExplosionForShortage] (@ProductCode varchar(20), @ReturnType varchar(1), @BranchID varchar(3), @CompID varchar(3))  

RETURNS @ItemStructure TABLE
	(ParentCode		varchar(20),
	ItemCode		varchar(20),
	ItemType		char(1),			/* P for Product; S for Stage; C for Child */
	Qty			float,			/* Norms */
	PQty			float,			/* Norms with related to Parent*/
	ExpPerc		float,			/* Explodable Percentage */
	PExpPerc		float,			/* Explodable Perc related to Parent*/
	PExpPercCum		float,			/* Cumulative Explodable Perc related to Parent*/
	StructureLevel		int,			/* Level From the Given Product Level starts from 0 */
	OperationSeq		int,
	BranchID		varchar(3),
	CompID			varchar(3))

AS  

BEGIN 

	/*@ReturnType 		'C' : Bottom most child in each branch
				'E' : Explodable Items		
	*/
		Declare @Level int
		Select @Level=0
 
		Declare @Success bit
		Select @Success = Convert(bit, '1')


		--Inserting the Initial Product in Temp Table for further processing
		Insert into @ItemStructure values (@ProductCode, @ProductCode, 'P', 1, 1, 0, 0, 0, 0, 0, @BranchID, @CompID)


		--Initially checking stages and insert it
		Select @Level = @Level + 1

		If Exists (Select * from BOM_MPS_Master a Left Outer Join 
				(Select * from BOM_MPS_Master where StageCode=@ProductCode and BranchID=@BranchID and CompId=@CompID) b
			On a.ItemCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID
			Where a.OperationSequence <= b.OperationSequence and a.BranchID = @BranchID and a.CompID = @CompID)

			Begin
				Insert into @ItemStructure
					Select a.ItemCode, a.StageCode, 'S', 1, 0, 0, 0, 0, @Level, Isnull(a.OperationSequence, b.OperationSequence) OperationSequence, @BranchID, @CompID
					from (Select ItemCode, StageCode, Case When OperationSequence=0 then 99999 else OperationSequence end as OperationSequence
						from  BOM_MPS_Master where BranchID=@BranchID and CompId=@CompID) a
					 Left Outer Join 
						(Select ItemCode, Case When OperationSequence=0 then 99999 else OperationSequence end as OperationSequence from BOM_MPS_Master where StageCode=@ProductCode and BranchID=@BranchID and CompId=@CompID) b
					On a.ItemCode=b.ItemCode
					Where a.OperationSequence <= b.OperationSequence 
			
				Select @Success = Convert(bit, 1)
			End
		Else
			Begin
				Select @Success = Convert(bit, 0)
			End


 












		While @Success = Convert(bit, '1')
			Begin
				Select @Level = @Level + 1

				If (@Level % 2 = 1)		--If Level is Odd No. then Search Stages else Search Childs
					Begin
						If Exists (Select * from BOM_MPS_Master
							Where ItemCode in 	(Select ItemCode from @ItemStructure
										Where StructureLevel = @Level-1 and BranchID=@BranchID and CompID=@CompID)
								and BranchID=@BranchID and CompID=@CompID)
							Begin
			
								Insert into @ItemStructure
									Select  m.ItemCode, m.StageCode, 'S', 1, n.PQty, 0, 0, n.PExpPercCum, @Level, m.OperationSequence, @BranchID, @CompID
									from BOM_MPS_Master m Inner Join 
										(Select * from @ItemStructure
										Where StructureLevel = @Level-1 and BranchID=@BranchID and CompID=@CompID)  n
									On m.ItemCode=n.ItemCode and m.BranchID=n.BranchID and m.CompID=n.CompID
									Where m.BranchID=@BranchID and m.CompID=@CompID
			
								Select @Success = Convert(bit, 1)
							End
						Else
							Begin
								Select @Success = Convert(bit, 0)
							End
					End	 
				Else
					Begin
						If Exists (Select * from BOM_Structure_Dtl
							Where Priority = 1 and ParentCode in 	(Select ItemCode from @ItemStructure
										Where StructureLevel = @Level-1 and BranchID=@BranchID and CompID=@CompID)
								and BranchID=@BranchID and CompID=@CompID)
			
							Begin
			
								Insert into @ItemStructure
									Select m.ParentCode, m.ChildCode, 'C', m.Qty, m.Qty*n.PQty, m.Percentage, 
										Round((((100.00-n.PExpPercCum)*m.Percentage)/100.00), 2), 
										(n.PExpPercCum+Round((((100.00-n.PExpPercCum)*m.Percentage)/100.00), 2)),
										@Level, 0, @BranchID, @CompID
									from BOM_Structure_Dtl m Inner Join
									 	(Select * from @ItemStructure
										Where StructureLevel = @Level-1 and BranchID=@BranchID and CompID=@CompID) n
									On  m.ParentCode=n.ItemCode and m.BranchID=n.BranchID and m.CompID=n.CompID
									Where m.Priority = 1 and m.BranchID = @BranchID and m.CompID = @CompID
								Select @Success = Convert(bit, 1)
							End
						Else
							Begin
								Select @Success = Convert(bit, 0)
							End
					End	
			End


		If (@ReturnType='C')	--Bottom Most Childs
			Begin
				--Other than Actual required child item are deleted
				Delete @ItemStructure
				Where ParentCode + ' - ' + ItemCode  Not in
					(Select ParentCode + ' - ' + ItemCode  from @ItemStructure a
					where a.itemtype='C' and a.BranchID=@BranchID and a.CompID=@CompID  
						and a.ItemCode Not in	(Select c.ParentCode from @ItemStructure c
									Where c.ParentCode=a.ItemCode and c.ItemType = a.ItemType and c.BranchID=a.BranchID and c.CompID=a.CompID 
									)
					)
			End
		Else
			If (@ReturnType='E')
				Begin
					--Other than Explodable Percentage Items are deleted
					Delete @ItemStructure
					Where ExpPerc=0
				End


			---To Delete the Product
			/*Delete From @ItemStructure
			Where ItemType = 'P' and BranchID = @BranchID and CompID = @CompID*/

			--- To Delete the DuplicateItem as Stage
			/*Delete From @ItemStructure
			Where ItemType = 'S' and BranchID = @BranchID and CompID = @CompID
			and ItemCode in
				(Select ItemCode From @ItemStructure
				Where   BranchID = @BranchID and CompID = @CompID
				Group By ItemCode
				Having count(ItemCode) >1)*/



	Return

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_BOM_Get_RawMaterial]    Script Date: 17/06/2026 11:38:41 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_BOM_Get_RawMaterial](@ItemCode varchar(30), @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3))    
/* Created on 2025-05-13 by Anandh.S for Get rawmaterial list for passed stagecode */    
RETURNS @RawMaterialList TABLE    
(    
 RMCode varchar(30),    
 RMItemID bigint,  
 Norms numeric(10, 5),    
 BranchID varchar(3),    
 CompID varchar(3)    
)    
AS    
BEGIN    
 Insert into @RawMaterialList    
 Select bom.ItemCode as RMCode, m.ItemID, bom.PQty, bom.BranchID, bom.CompID    
 From [dbo].[fn_COM_Product_BOM](@ItemCode, 'C', @AsOnDate, @RptDate, @BranchID, @CompID) bom  
 Left Outer Join fn_BOM_Material_Master('A', @AsOnDate, @RptDate, @BranchID, @CompID) m  
  On bom.ItemCode=m.ItemCode and bom.BranchID=m.BranchID and bom.CompID=m.CompID;    
    
 RETURN;    
END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_BOM_GetBottomMostChild]    Script Date: 17/06/2026 11:38:42 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO



CREATE FUNCTION [dbo].[fn_BOM_GetBottomMostChild] (@ProductCode varchar(20), @BranchID varchar(3), @CompID varchar(3))  

RETURNS @ItemStructure TABLE
	(ParentCode	varchar(20),
	ItemCode	varchar(20),
	ItemType	char(1),			/* P for Product; S for Stage; C for Child */
	Qty		float,			/* Norms */
	ExplodablePerc	float,
	StructureLevel	int,			/* Level From the Given Product Level starts from 0 */
	BranchID	varchar(3),
	CompID		varchar(3))

AS  

BEGIN 

		Declare @Level int
		Select @Level=0
 
		Declare @Success bit
		Select @Success = Convert(bit, '1')


		--Inserting the Initial Product in Temp Table for further processing
		Insert into @ItemStructure values (@ProductCode, @ProductCode, 'P', 0, 0, 0, @BranchID, @CompID)

		While @Success = Convert(bit, '1')
			Begin
				Select @Level = @Level + 1

				If (@Level % 2 = 1)		--If Level is Odd No. then Search Stages else Search Childs
					Begin
						If Exists (Select * from BOM_MPS_Master
							Where ItemCode in 	(Select ItemCode from @ItemStructure
										Where StructureLevel = @Level-1 and BranchID=@BranchID and CompID=@CompID))
			
							Begin
			
								Insert into @ItemStructure
									Select  ItemCode, StageCode, 'S', 1, 0, @Level, @BranchID, @CompID
									from BOM_MPS_Master
									Where ItemCode in 	(Select ItemCode from @ItemStructure
												Where StructureLevel = @Level-1 and BranchID=@BranchID and CompID=@CompID)
			
								Select @Success = Convert(bit, 1)
							End
						Else
							Begin
								Select @Success = Convert(bit, 0)
							End
					End	
				Else
					Begin
						If Exists (Select * from BOM_Structure_Dtl
							Where priority = 1 and ParentCode in 	(Select ItemCode from @ItemStructure
										Where StructureLevel = @Level-1 and BranchID=@BranchID and CompID=@CompID))
			
							Begin
			
								Insert into @ItemStructure
									Select ParentCode, ChildCode, 'C', Qty, Percentage, @Level, @BranchID, @CompID
									from BOM_Structure_Dtl
									Where priority = 1 and ParentCode in 	(Select ItemCode from @ItemStructure
												Where StructureLevel = @Level-1 and BranchID=@BranchID and CompID=@CompID)
			
								Select @Success = Convert(bit, 1)
							End
						Else
							Begin
								Select @Success = Convert(bit, 0)
							End
			
				
					End	


			End
		--Now the Table @ItemStructure has the tree structure of the product explosion

		Declare @Norms float

		Declare @Parent varchar(20)
		Declare @Child varchar(20)
		Declare @Item varchar(20)
		Declare @Qty float

		--Here we open the bottom most child items only
		Declare curItemList Cursor for		
			Select ParentCode, ItemCode, Qty from @ItemStructure a
			where a.itemtype='C' and a.BranchID=@BranchID and a.CompID=@CompID 
				and Not Exists
					(Select * from @ItemStructure b
					Where b.ParentCode in (Select c.ItemCode from @ItemStructure c
								Where c.ParentCode=a.ItemCode and c.BranchID=a.BranchID and c.CompID=a.CompID)
						and b.BranchID=a.BranchID and b.CompID=a.CompID
					)

		Open curItemList

		FETCH NEXT FROM curItemList into @Parent, @Child, @Qty 
	
		WHILE @@FETCH_STATUS = 0
			Begin
				Select @Item=@Parent
				Select @Norms = @Qty
				
				--here we select the parent item norms and multiply it with current item norms
				While Exists (Select * from @ItemStructure
						Where ItemCode=(Select ParentCode from @ItemStructure
								  Where ItemCode=@Item and ItemType='S' and BranchID=@BranchID and CompID=@CompID)
						and ItemType='C')

					Begin
						Select @Item=ParentCode, @Qty=Qty from @ItemStructure
						Where ItemCode=(Select ParentCode from @ItemStructure
								  Where ItemCode=@Item and ItemType='S' and BranchID=@BranchID and CompID=@CompID)
						and ItemType='C'

						Select @Norms = @Norms * @Qty

					End
				--Updating Norms
				Update @ItemStructure Set Qty=@Norms
				Where ParentCode=@Parent and ItemCode=@Child and ItemType='C' and BranchID=@BranchID and CompID=@CompID


				FETCH NEXT FROM curItemList into @Parent, @Child, @Qty 

			End


		Close curItemList
		Deallocate curItemList
		
		--Other than Actual required child item are deleted

		Delete @ItemStructure
		Where ParentCode + ' - ' + ItemCode  Not in
			(Select ParentCode + ' - ' + ItemCode  from @ItemStructure a
			where a.itemtype='C' and a.BranchID=@BranchID and a.CompID=@CompID  
				and a.ItemCode Not in	(Select c.ParentCode from @ItemStructure c
							Where c.ParentCode=a.ItemCode  and c.BranchID=a.BranchID and c.CompID=a.CompID 
							)
			)


	Return

END




















GO

/****** Object:  UserDefinedFunction [dbo].[fn_BOM_HSNNo_Master_Grp]    Script Date: 17/06/2026 11:38:42 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [dbo].[fn_BOM_HSNNo_Master_Grp] (@ForOperation varchar(1), @AsOnDate datetime, @BranchID varchar(3), @CompID varchar(3))      
   
RETURNS  @RetTbl TABLE    
 (
	HSNId		int,    
	RevNo		int,    
	RevDate		datetime,    
	EffStatus	char(2),     
	EffDate		datetime,    
	BranchID	varchar(3),     
	CompID		varchar(3),    
	TranStamp  datetime,    
	MinEffDate datetime    
 )    
    
 BEGIN     
	Insert into @RetTbl    
		Select m.HSNId, h.RevNo, h.RevDate, h.EffStatus, h.EffDate, @BranchID, @CompID, m.TranStamp, m.MinEffDate    
		From    
		(    
			Select h.HSNId, Min(h.EffDate) As MinEffDate, Max(h.TranStamp) As TranStamp      
			From BOM_HSNNo_Master h    
			Where h.TranStamp<=@AsOnDate and h.BranchID=@BranchID and h.CompID=@CompID    
			Group by h.HSNId  
		) m    
		Left Outer Join BOM_HSNNo_Master h     
			On m.HSNId=h.HSNId and m.TranStamp=h.TranStamp and h.BranchID=@BranchID and h.CompID=@CompID    
      
	-- Delete based on FormOperation   
	Delete From @RetTbl        
	Where ( (@ForOperation='M' AND EffStatus Like '[AHX]%')    
			OR (@ForOperation='E' AND (EffStatus Like '[NME]%' OR (EffStatus LIKE 'A%' AND  EffStatus Like '_[DX]')))    
			OR (@ForOperation='A' AND EffStatus Like '[AX]%')    
		  )    
    
	Return     
    
 END 
GO

/****** Object:  UserDefinedFunction [dbo].[fn_BOM_Process]    Script Date: 17/06/2026 11:38:42 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_BOM_Process] (@BranchID varchar(3), @CompID varchar(3))  

RETURNS @Process TABLE
	(ParentCode	varchar(20),
	StageCode	varchar(20),
	Norms		float,			/* Norms */
	OperationCode	int,
	OperationSequence	int,
	BranchID	varchar(3),
	CompID		varchar(3))

AS  

BEGIN 
	Declare @ParentCode varchar(20)
	
	Declare curRec cursor for

	Select Distinct ItemCode from MPsMaster where Status=1 and Branchid=@BranchID and Compid=@CompID

	open curRec
	
	Fetch next from curRec into @ParentCode

	while @@Fetch_Status=0

		Begin
			Insert into @Process
			select @ParentCode,ItemCode,Qty,OperationCode,OperationSeq,@BranchID,@CompID
			 from dbo.fn_BOM_ProductExplosion (@ParentCode,@BranchID, @CompID) a
			where  OperationCode=(Select max(OperationCode) from dbo.fn_BOM_ProductExplosion (@ParentCode,@BranchID, @CompID)
						where ParentCode=a.ParentCode and ItemCode=a.ITemCode and Branchid=a.Branchid and Compid=a.Compid)
			           --and OperationSeq<>99999
				 order by StructureLevel,OperationSeq,ItemType

			Fetch next from curRec into @ParentCode

		End



	Close curRec
	Deallocate curRec

	RETURN 

END








GO

/****** Object:  UserDefinedFunction [dbo].[fn_BOM_ProductExplosion]    Script Date: 17/06/2026 11:38:42 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_BOM_ProductExplosion] (@ProductCode varchar(20), @BranchID varchar(3), @CompID varchar(3))  
RETURNS @ItemStructure TABLE
	(ParentCode	varchar(20),
	ItemCode	varchar(20),
	ItemType	char(1),			/* P for Product; S for Stage; C for Child */
	Qty		float,			/* Norms */
	ExplodablePerc	float,
	StructureLevel	int,			/* Level From the Given Product Level starts from 0 */
	OperationCode	int,
	OperationSeq	int,
	BranchID	varchar(3),
	CompID		varchar(3))
AS  
BEGIN 
	Declare @Level int
	Select @Level=0
 
	Declare @Success bit
	Select @Success = Convert(bit, '1')

	--Inserting the Initial Product in Temp Table for further processing
	Insert into @ItemStructure values (@ProductCode, @ProductCode, 'P', 0, 0, 0, 0,0, @BranchID, @CompID)
		
	--Initially checking stages and insert it
	Select @Level = @Level + 1

	If Exists (Select * From BOM_MPS_Master a 
						Left Outer Join (	Select * From BOM_MPS_Master b
															where b.StageCode=@ProductCode and b.BranchID=@BranchID 
																		and b.CompId=@CompID
						) b
							On a.ItemCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID
						Where a.OperationSequence<=b.OperationSequence and a.BranchID=@BranchID and a.CompID=@CompID
		)
		Begin
			Insert into @ItemStructure
				Select a.ItemCode, a.StageCode, 'S', 1, 0, @Level, a.OperationCode, Isnull(a.OperationSequence, 
							b.OperationSequence) As OperationSequence, @BranchID, @CompID 
				From( Select mp1.ItemCode, mp1.StageCode, mp1.OperationCode, 
									(Case When mp1.OperationSequence=0 Then 99999 Else mp1.OperationSequence End) As OperationSequence
							From BOM_MPS_Master mp1
							Where mp1.BranchID=@BranchID and mp1.CompId=@CompID
						) a
					Left Outer Join( Select mp2.ItemCode, (Case When mp2.OperationSequence=0 Then 99999 Else mp2.OperationSequence End) As OperationSequence 
													From BOM_MPS_Master mp2
													where mp2.StageCode=@ProductCode and mp2.BranchID=@BranchID and mp2.CompId=@CompID
					) b
					On a.ItemCode=b.ItemCode
				Where a.OperationSequence<=b.OperationSequence 			
			Select @Success = Convert(bit, 1)
		End
	Else
		Begin
			Select @Success = Convert(bit, 0)
		End
	While @Success = Convert(bit, '1')
		Begin
			Select @Level = @Level + 1

			If (@Level % 2 = 1)		--If Level is Odd No. then Search Stages else Search Childs
				Begin
					If Exists (	Select * From BOM_MPS_Master a
											Where a.ItemCode In(Select s1.ItemCode From @ItemStructure s1
																Where s1.StructureLevel=@Level-1 and s1.BranchID=@BranchID and s1.CompID=@CompID
															 )
										and a.BranchID=@BranchID and a.CompID=@CompID
							)
						Begin
							Insert into @ItemStructure
								Select Distinct a.ItemCode, a.StageCode, 'S', 1, 0, @Level, a.OperationCode, 
											a.OperationSequence, @BranchID, @CompID
								From BOM_MPS_Master a
								Where a.ItemCode In(Select ItemCode from @ItemStructure s1
											Where s1.StructureLevel=@Level-1 and s1.BranchID=@BranchID and s1.CompID=@CompID
											)
								and a.BranchID=@BranchID and a.CompID=@CompID
			
							Select @Success = Convert(bit, 1)
						End
					Else
						Begin
							Select @Success = Convert(bit, 0)
						End
				End	
			Else
				Begin
					If Exists (Select * From BOM_Structure_Dtl a
										Where Priority = 1 and ParentCode In(Select s1.ItemCode From @ItemStructure s1
													Where s1.StructureLevel=@Level-1 and s1.BranchID=@BranchID and s1.CompID=@CompID
													)
										and a.BranchID=@BranchID and a.CompID=@CompID
							)			
						Begin
							Insert into @ItemStructure
								Select a.ParentCode, a.ChildCode, 'C', a.Qty, a.Percentage, @Level, 0,-1, @BranchID, @CompID
								From BOM_Structure_Dtl a
								Where a.Priority=1 and a.ParentCode In(Select s1.ItemCode From @ItemStructure s1
											Where s1.StructureLevel=@Level-1 and s1.BranchID=@BranchID and s1.CompID=@CompID
											)
								and a.BranchID=@BranchID and a.CompID=@CompID
			
							Select @Success = Convert(bit, 1)
						End
					Else
						Begin
							Select @Success = Convert(bit, 0)
						End
				End	
		End
	Return
END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_BOM_ProductExplosion_Child]    Script Date: 17/06/2026 11:38:42 ******/
