/****** Object:  UserDefinedFunction [dbo].[fn_BOM_ProductExplosion_Rate]    Script Date: 17/06/2026 11:38:42 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_BOM_ProductExplosion_Rate] (@ProductCode varchar(20), @FromDate  datetime, @ToDate  datetime,   
 @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(15))        
RETURNS @ItemStructure TABLE    
 (ProductCode varchar(20),    
 ParentCode varchar(20),    
 ItemCode varchar(20),    
 ItemType char(1),   /* P for Product; S for Stage; C for Child */    
 Seq  int,    
 Qty  float,   /* Norms */    
 Rate  float,    
 CumRate float,     
 ExplodablePerc float,    
 StructureLevel int,   /* Level From the Given Product Level starts from 0 */    
 BranchID varchar(3),    
 CompID  varchar(3))      
AS        
BEGIN     
    
  Declare @Level int    
  Select @Level=0    
     
  Declare @Success bit    
  Select @Success = Convert(bit, '1')    
  
  --Inserting the Initial Product in Temp Table for further processing    
  Insert into @ItemStructure values (@ProductCode, @ProductCode, @ProductCode, 'P', 0, 0, 0, 0, 0, 0, @BranchID, @CompID)    
    
  While @Success = Convert(bit, '1')    
   Begin    
    Select @Level = @Level + 1    
    
    If (@Level % 2 = 1)  --If Level is Odd No. then Search Stages else Search Childs    
     Begin    
      If Exists (Select * from BOM_MPS_Master    
       Where ItemCode in (Select ItemCode from @ItemStructure    
          Where StructureLevel = @Level-1 and BranchID=@BranchID and CompID=@CompID)    
        and BranchID=@BranchID and CompID=@CompID)    
       Begin    
        Insert into @ItemStructure    
         Select  @ProductCode, ItemCode, StageCode, 'S', Case when a1.OperationSequence=0 then 9999 else a1.OperationSequence end, 1,
			IsNull((Select Distinct OperationCost from BOM_ItemwiseMachinewiseCycleTime a2    
				 Where a2.ItemCode=a1.StageCode and a2.Priority=1
					and a2.TranStamp=(Select Max(a3.TranStamp) From BOM_ItemwiseMachinewiseCycleTime a3
										Where a3.ItemCode=a2.ItemCode and a3.Priority=a2.Priority 
											and a3.BranchID=a2.BranchID and a3.CompID=a2.CompID 
									 )				 
					and a2.BranchID=a1.BranchID and a2.CompID=a1.CompID 							  
			), 0) as OprCost, 
          --IsNull((Select Distinct OperationCost from BOM_ItemwiseMachinewiseCycleTime a2    
          --Where a2.ItemCode=a1.StageCode and a2.BranchID=a1.BranchID and a2.CompID=a1.CompID and a2.Priority=1), 0) as OprCost,    
          0, 0, @Level, @BranchID, @CompID    
         from BOM_MPS_Master a1    
         Where ItemCode in  (Select ItemCode from @ItemStructure    
            Where StructureLevel = @Level-1 and BranchID=@BranchID and CompID=@CompID)    
          and BranchID=@BranchID and CompID=@CompID    
       
        Select @Success = Convert(bit, 1)    
       End    
      Else    
       Begin    
        Select @Success = Convert(bit, 0)    
       End    
     End     
    Else     
     Begin    
      If Exists (Select * from BOM_Structure_Dtl    
       Where Priority = 1 and ParentCode in  (Select ItemCode from @ItemStructure    
          Where StructureLevel = @Level-1 and BranchID=@BranchID and CompID=@CompID)    
        and BranchID=@BranchID and CompID=@CompID)    
       
       Begin    
        Insert into @ItemStructure    
         Select @ProductCode, ParentCode, ChildCode, 'C', -1, Qty,     
          Case when Exists (Select * from BOM_MPS_Master where ItemCode=ChildCode and BranchID=@BranchID and CompID=@CompID)     
           then 0    
           else dbo.fn_WtAvgRate (ChildCode, @FromDate,  @ToDate, @BranchID, @CompID, @Finyear) End ,             
          0, Percentage, @Level, @BranchID, @CompID    
         from BOM_Structure_Dtl b1    
         Where Priority = 1 and  ParentCode in  (Select ItemCode from @ItemStructure    
            Where StructureLevel = @Level-1 and BranchID=@BranchID and CompID=@CompID)    
          and BranchID=@BranchID and CompID=@CompID    
    
        Select @Success = Convert(bit, 1)    
       End    
      Else    
       Begin    
        Select @Success = Convert(bit, 0)    
       End             
     End     
   End    
  
  Select @Level=Max(StructureLevel) From @ItemStructure  
       
  While @Level > 0      
   Begin    
    If (@Level % 2 = 0)    
     Begin  --Child    
      Update @ItemStructure Set CumRate=Rate    
      from @ItemStructure a    
      Where Not Exists (Select * from @ItemStructure b Where b.StructureLevel=a.StructureLevel+1 and b.ParentCode=a.ItemCode)    
       and StructureLevel=@Level    
          
    
      Update @ItemStructure Set CumRate = Rate + c.CRate    
      From @ItemStructure a Inner Join     
       (Select ParentCode, ItemCode from @ItemStructure m    
       Where m.StructureLevel=@Level-1     
        and m.Seq=(Select Min(Seq) from @ItemStructure n    
          Where n.StructureLevel=m.StructureLevel and n.ParentCode=m.ParentCode Group by n.ParentCode)    
       ) b    
      On a.ParentCode=b.ParentCode    
      Left Outer Join (Select ParentCode, isNull(Sum(CumRate * Qty), 0) as CRate from @ItemStructure    
        Where StructureLevel=@Level Group by ParentCode    
        ) c    
      On b.ItemCode=c.ParentCode    
      Where a.StructureLevel=@Level-1    
    
     End    
    
    Else    
     Begin  --Stage    
      -- Add Operation Cost and update the stage level    
      Update @ItemStructure Set CumRate = CumRate + isNull((Select Sum(Rate) from @ItemStructure b     
             Where b.Seq<a.Seq and b.ParentCode=a.ParentCode and b.StructureLevel=a.StructureLevel), 0)    
      From @ItemStructure a    
      Where a.StructureLevel=@Level    
          
      -- Update FG Rate to the Child Rate of Next Level    
      Update @ItemStructure Set CumRate = Rate + isNull((Select CumRate from @ItemStructure b    
            Where b.ParentCode=b.ItemCode and b.StructureLevel=a.StructureLevel+1 and b.ParentCode=a.ItemCode), 0)    
      From @ItemStructure a     
      Where a.StructureLevel=@Level-1    
    
     End    
    
   Select @Level=@Level-1    
    
    --if @Level=1    
     --Select @Level=-1    
   End    
    
 /* Delete Data */  
  Delete From @ItemStructure Where ItemType='P'  
  
 Return      
END 
GO

/****** Object:  UserDefinedFunction [dbo].[fn_BOM_ProductExplosion_TreeView]    Script Date: 17/06/2026 11:38:42 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_BOM_ProductExplosion_TreeView] (@ProductCode varchar(20), @BranchID varchar(3), @CompID varchar(3))  

RETURNS @ItemStructure TABLE
	(ParentCode	varchar(20),
	ItemCode	varchar(20),
	ItemType	char(1),			/* P for Product; S for Stage; C for Child */
	Qty		float,			/* Norms */
	ExplodablePerc	float,
	StructureLevel	int,			/* Level From the Given Product Level starts from 0 */
	OperationSeq	int,
	IWidth		varchar(3),
	IRoute		varchar(66),
	BranchID	varchar(3),
	CompID		varchar(3))

AS  

BEGIN 

		Declare @Level int
		Select @Level=0
 
		Declare @Success bit
		Select @Success = Convert(bit, '1')


		--Inserting the Initial Product in Temp Table for further processing
		Insert into @ItemStructure values (@ProductCode, @ProductCode, 'P', 0, 0, 0, 0, '', '', @BranchID, @CompID)
		
		--Initially checking stages and insert it
		Select @Level = @Level + 1

		If Exists (Select * from BOM_MPS_Master a Left Outer Join 
				(Select * from BOM_MPS_Master where StageCode=@ProductCode and BranchID=@BranchID and CompId=@CompID) b
			On a.ItemCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID
			Where a.OperationSequence <= b.OperationSequence and a.BranchID = @BranchID and a.CompID = @CompID)

			Begin
				Insert into @ItemStructure
					Select a.ItemCode, a.StageCode, 'S', 1, 0, @Level, Isnull(a.OperationSequence, b.OperationSequence) OperationSequence,  '', '', @BranchID, @CompID 
					from (Select ItemCode, StageCode, Case When OperationSequence=0 then 99999 else OperationSequence end as OperationSequence
						from  BOM_MPS_Master where BranchID=@BranchID and CompId=@CompID) a
					 Left Outer Join 
						(Select ItemCode, Case When OperationSequence=0 then 99999 else OperationSequence end as OperationSequence from BOM_MPS_Master where StageCode=@ProductCode and BranchID=@BranchID and CompId=@CompID) b
					On a.ItemCode=b.ItemCode
					Where a.OperationSequence <= b.OperationSequence 
			
				Select @Success = Convert(bit, 1)
			End
		Else
			Begin
				Select @Success = Convert(bit, 0)
			End



		While @Success = Convert(bit, '1')
			Begin
				Select @Level = @Level + 1

				If (@Level % 2 = 1)		--If Level is Odd No. then Search Stages else Search Childs
					Begin
						If Exists (Select * from BOM_MPS_Master
							Where ItemCode in 	(Select ItemCode from @ItemStructure
										Where StructureLevel = @Level-1 and BranchID=@BranchID and CompID=@CompID)
							and BranchID = @BranchID and CompID = @CompID)
							Begin
								Insert into @ItemStructure
									Select ItemCode, StageCode, 'S', 1, 0, @Level, OperationSequence, '', '', @BranchID, @CompID
									from BOM_MPS_Master
									Where ItemCode in 	(Select ItemCode from @ItemStructure
												Where StructureLevel = @Level-1 and BranchID=@BranchID and CompID=@CompID)
									and BranchID = @BranchID and CompID = @CompID
			
								Select @Success = Convert(bit, 1)
							End
						Else
							Begin
								Select @Success = Convert(bit, 0)
							End
					End	
				Else
					Begin
						If Exists (Select * from BOM_Structure_Dtl
							Where Priority = 1 and ParentCode in 	(Select ItemCode from @ItemStructure
										Where StructureLevel = @Level-1 and BranchID=@BranchID and CompID=@CompID)
							and BranchID = @BranchID and CompID = @CompID
							)
			
							Begin
								Insert into @ItemStructure
									Select ParentCode, ChildCode, 'C', Qty, Percentage, @Level, -1, '', '', @BranchID, @CompID
									from BOM_Structure_Dtl
									Where Priority = 1 and ParentCode in 	(Select ItemCode from @ItemStructure
												Where StructureLevel = @Level-1 and BranchID=@BranchID and CompID=@CompID)
									and BranchID = @BranchID and CompID = @CompID
			
								Select @Success = Convert(bit, 1)
							End
						Else
							Begin
								Select @Success = Convert(bit, 0)
							End			
				
					End	
			End


			Declare @Parent varchar(20)
			Declare @Item varchar(20)
			Declare @StLevel int
			Declare @SLvl int
			Declare @IType char(1)
			
			Declare curWidth Cursor For

			Select distinct ParentCode, StructureLevel from @ItemStructure 
			Where BranchID = @BranchID and CompID = @CompID and StructureLevel > 0
			Order by StructureLevel
		
			Open curWidth
			FETCH NEXT FROM curWidth into @Parent, @SLvl			
				
			WHILE @@FETCH_STATUS =  0 
				Begin 
					Declare curItem Cursor For

					Select distinct a.ItemCode, a.StructureLevel, a.ItemType  from @ItemStructure a  
						Left Outer join (Select * From @ItemStructure Where BranchID = @BranchID and CompID = @CompID)b						
						On a.ParentCode = b.ItemCode
					Where a.ParentCode =  @Parent and a.BranchID = @BranchID and a.CompID = @CompID
					Order by a.StructureLevel
					
		
					Open curItem
					FETCH NEXT FROM curItem into @Item, @StLevel, @IType 	
						
					WHILE @@FETCH_STATUS = 0 
						Begin 
					
							Update @ItemStructure 
								Set IRoute = isNull(b.IRoute, '')+isNull(b.IWidth, ''),  --Isnull((Case When b.IRoute = '' Then b.IWidth Else (b.IRoute+b.IWidth) End),''),
								IWidth = dbo.fn_FAS_Get_Width(Convert(varchar, isNull((Select Max(IWidth) from @ItemStructure c 
												where c.ParentCode= @Parent and c.StructureLevel=@StLevel and c.BranchID = @BranchID and c.CompID = @CompID), 0) ), 1, 3)
							from @ItemStructure a 
								Left Outer join (Select * From @ItemStructure Where StructureLevel=@StLevel-1 and BranchID = @BranchID and CompID = @CompID)b
								On a.ParentCode = b.ItemCode
							 where a.Parentcode = @Parent and a.ItemCode= @Item 
								and a.StructureLevel = @StLevel and a.ItemType = @IType
								and a.BranchID = @BranchID and a.CompID = @CompID and a.ItemType<>'P'

							
						--Print @Item
							FETCH NEXT FROM curItem into @Item , @StLevel, @IType
							
						End

						Close curItem
						Deallocate curItem					

					--Print @Parent
					FETCH NEXT FROM curWidth into @Parent, @SLvl 	
									
				End
					
				Close curWidth
				Deallocate curWidth								
				
/*
				Delete @ItemStructure				
				Where ParentCode = ItemCode and BranchID = @BranchID and CompID = @CompID and ItemType <> 'P'
*/

	
	Return

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_BOM_ProductImplosion]    Script Date: 17/06/2026 11:38:42 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_BOM_ProductImplosion] (@ChildCode varchar(20),  @ReturnType char(1),  
	@FromDate  datetime, @ToDate  datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(15))    
  
RETURNS @ItemStructure TABLE  
 (ProductCode varchar(20),  
 ParentCode varchar(20),  
 ItemCode varchar(20),  
 ItemType char(1),   /* P for Product; S for Stage; C for Child */  
 Seq  int,  
 Rate  float,  
 StructureLevel int,   /* Level From the Given Product Level starts from 0 */  
 BranchID varchar(3),  
 CompID  varchar(3))    
AS       
BEGIN     
  Declare @Level int  
  Declare @InitialLevel int  
  Select @Level=0  
   
  Declare @Continue bit  
  Declare @Success bit  
  
  Select @Continue = Convert(bit, '1')  
   
  Declare @Product varchar(20)  
  
  If Exists (Select * from BOM_Structure_Dtl a  
    Where ChildCode = @ChildCode and BranchID = @BranchID and CompID = @CompID and Priority=1  
    and RevisionNo = (Select Max(RevisionNo) From Bom_Structure_Dtl b  
       Where a.ParentCode=b.ParentCode and ChildCode = @ChildCode and BranchID = @BranchID and CompID = @CompID)  
   )  
  
   Begin                  
    Select @Level=2  
    Select @InitialLevel=2  
   End      
  Else  
   Begin  
    
    If Exists (Select * from BOM_MPS_Master  
      Where StageCode = @ChildCode and BranchID=@BranchID and CompID=@CompID  
      and RevisionNo = (Select Max(RevisionNo) From BOM_Mps_Master  
         Where StageCode = @ChildCode and BranchID = @BranchID and CompID = @CompID)  
     )  
     Begin     
      Select @Level=1  
      Select @InitialLevel=1                   
     End         
    Else  
     Select @Continue = Convert(bit, '0')    
   End  
      
  If @Continue=Convert(bit, '1')  
   Begin  
    --Here we going to find the implosion structure for the given child traverse from child to product  
    Select @Success = Convert(bit, '1')  
  
    --Inserting the Initial Product in Temp Table for further processing  
    Insert into @ItemStructure values (@ChildCode, @ChildCode, @ChildCode, 'T', 0, 0, @Level-1, @BranchID, @CompID)  
    
    While @Success = Convert(bit, '1')  
     Begin  
      If (@Level % 2 = 1)  --If Level is Odd No. then Search Stages else Search Childs  
       Begin  
        If Exists (Select * from BOM_MPS_Master  
          Where StageCode in (Select ParentCode from @ItemStructure  
            Where StructureLevel = @Level-1 and BranchID=@BranchID and CompID=@CompID))  
         Begin  
          Insert into @ItemStructure  
           Select  '', ItemCode, StageCode, 'T', Case when a1.OperationSequence=0 then 9999 else a1.OperationSequence end, 0, @Level, @BranchID, @CompID  
           from BOM_MPS_Master a1  
           Where StageCode  in  (Select ParentCode from @ItemStructure  
              Where StructureLevel = @Level-1 and BranchID=@BranchID and CompID=@CompID)  
       
          Select @Success = Convert(bit, 1)  
         End  
        Else  
         Begin  
          Select @Success = Convert(bit, 0)  
         End  
       End   
      Else   
       Begin  
        If Exists (Select * from BOM_Structure_Dtl  
         Where ChildCode in  (Select ParentCode from @ItemStructure  
            Where StructureLevel = @Level-1 and BranchID=@BranchID and CompID=@CompID))  
       
         Begin  
          Insert into @ItemStructure  
           Select '', ParentCode, ChildCode, 'T', -1, 0, @Level, @BranchID, @CompID  
           from BOM_Structure_Dtl b1  
           Where ChildCode in  (Select ParentCode from @ItemStructure  
              Where StructureLevel = @Level-1 and BranchID=@BranchID and CompID=@CompID)  
       
          Select @Success = Convert(bit, 1)  
         End  
        Else  
         Begin  
          Select @Success = Convert(bit, 0)  
         End             
       End       

      Select @Level = @Level + 1      
     End  
 
   --Now we have ProductCodes for the given child and use those product codes we insert product structure using product explosion function  
  
   Declare curItem Cursor For  
   Select ParentCode from @ItemStructure a  
   Where Not Exists (Select * from @ItemStructure b where b.ItemCode=a.ParentCode)      
  
   Open curItem      
  
   FETCH NEXT FROM curItem into @Product   
  
   Declare @Parent varchar(20)  
   Select @Parent = @Product  
  
    WHILE @@FETCH_STATUS = 0      
     Begin  
         
       --Insert into @ItemStructure  
       --Select @Product, '', '', '', 0, 0, 0, '', ''   
  
       ----Insert into @ItemStructure From ProductExplosion Rate  
       Insert into @ItemStructure  
        Select ProductCode, ParentCode, ItemCode, ItemType, Seq, CumRate, StructureLevel, BranchID, CompID  
        From dbo.fn_Bom_ProductExplosion_Rate (@Product, @FromDate, @ToDate, @BranchID, @CompID, @Finyear)        
         
       --Delete higher level structure if the argument is Same Level or Branch Only  
       IF @ReturnType = 'S' or @ReturnType = 'B'  
        Begin   
         Delete @ItemStructure  
           Where '[' + ProductCode + '][' + Convert(Varchar, StructureLevel) + ']'  
             in (Select '[' + ProductCode + '][' + Convert(Varchar, StructureLevel) + ']'   
             From @ItemStructure b  
             Where b.BranchID =@BranchID and b.CompID =@CompID  
              and ItemType<>'T' and StructureLevel > (Select StructureLevel From @ItemStructure c  
             Where c.ProductCode = b.ProductCode and c.ItemCode = @ChildCode  
				and c.ItemType<>'T' and c.BranchID = @BranchID and c.CompID = @CompID)  
               )
				and BranchID=@BranchID and CompID=@CompID          
        End  
   
       Fetch Next From curItem into @Product  
  
       Select @Parent = @Product  
                   Select @Level=@InitialLevel  
       Select @Continue = Convert(bit, '1')    
     End  
        
    Close curItem  
    Deallocate curItem       
      
    --Delete if it is  Branch Only  
    IF  @ReturnType = 'B'  
     Begin  
      Declare @ItemChild varchar(20)   
      Declare @ItemParent varchar(20)         
  
      Declare curItemList Cursor For  
      Select distinct ProductCode From @ItemStructure where ItemType<>'T'  
   
      Open curItemList  
   
      FETCH NEXT FROM curItemList into @Product        
      
      While @@Fetch_Status=0  
       Begin  
       
        Select @Level=Max(StructureLevel) from @ItemStructure       
        Where ProductCode = @Product and ItemType<>'T'   
          
        Select @ItemChild = @ChildCode    
    
        While @Level > 1  
         Begin  
          Select @ItemParent = ParentCode From @ItemStructure   
          Where ProductCode = @Product and ItemCode = @ItemChild and StructureLevel = @Level and ItemType<>'T'     
    
          If @Level % 2 = 1  
           Begin   
            Delete @ItemStructure  
            Where ProductCode=@Product and ParentCode <> @ItemParent  and StructureLevel = @Level  and ItemType<>'T'                       
           End  
          Else  
           Begin   
            Delete @ItemStructure  
            Where ProductCode=@Product and ItemCode <> @ItemChild  and StructureLevel = @Level and ItemType<>'T'                                  
           End  
    
          Select @ItemChild = @ItemParent  
          Select @Level = @Level - 1  
    
          --If (@Product='AP0' and @Level=3) or (@Product<>'AP0' and @Level=5)  
           --Select @Level=0  
         End  
  
        FETCH NEXT FROM curItemList into @Product  
       End  
  
      Close curItemList  
      Deallocate curItemList                   
     End   
      
    Delete @ItemStructure where ITemType='T'      
   End   
  
 Return    
END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_BOM_Structure]    Script Date: 17/06/2026 11:38:42 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_BOM_Structure] (@ParentCode varchar(20) ,@EffectiveDate datetime, @Branchid varchar(3), @Compid varchar(3))  

RETURNS @Structure TABLE
	(ParentCode	varchar(20),
	ChildCode	varchar(20),
	Qty		float,	
	RevisionNo	int,
	Explodable 	bit,
	Percentage 	float,
	Priority		int,
	BaseQty	int,
	EffectiveDate	datetime)
		
AS  

BEGIN 

	Insert into @Structure		

		Select a.ParentCode, a.ChildCode, a.Qty, a.RevisionNo, a.Explodable, a.Percentage, a.Priority, isNull(d.BaseQty,1) BaseQty,  d.EffectiveDate 
		from BOM_Structure_Dtl a left outer join BOM_Structure_Hdr d 
				on a.ParentCode = d.ParentCode and a.RevisionNo = d.RevisionNo and a.Branchid = d.Branchid and a.Compid = d.Compid 
		where a.ParentCode = @ParentCode and d.EffectiveDate <= @EffectiveDate and d.Status = '1' and a.Branchid = @Branchid and a.Compid = @Compid 
			and a.RevisionNo = (select Max(b.RevisionNo) from BOM_Structure_Dtl b 
						where b.ParentCode = a.ParentCode and b.Branchid = a.Branchid and b.Compid = a.Compid) 
			and a.Priority = (select Min(c.Priority) from BOM_Structure_Dtl c 
						where c.ParentCode = a.ParentCode and c.ItemGroupKey = a.ItemGroupKey and c.Branchid = a.Branchid and c.Compid = a.Compid) 
 
	Return

END








GO

/****** Object:  UserDefinedFunction [dbo].[fn_COM_CalculateExpression]    Script Date: 17/06/2026 11:38:42 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_COM_CalculateExpression] (@DTKey varchar(36), @ModuleCode int, @FrmID int, @UserID varchar(10), @BranchID varchar(3), @CompID varchar(3))  

RETURNS @ExprBlockSeq TABLE
	(ExprSeq		int,
	BlockSeq		int,
	BlockType		varchar(30),
	Block			varchar(30),			
	ValueUsed		float,			
	isValueEditable		bit,
	isTypePercentage	bit,			
	IsTypeEditable		bit,
	KeyCol			varchar(50),
	MultiSeq		int)

AS  

BEGIN 
	
	Insert into @ExprBlockSeq

	Select * 
	from 
		(Select a.ExprSeq, a.BlockSeq, a.BlockType, a.Block, isNull(c.ValueUsed, a.ValueUsed) as ValueUsed, 
			isNull(c.isValueEditable, a.isValueEditable) as isValueEditable, isNull(c.isTypePercentage, a.IsTypePercentage) as isTypePercentage, 
			isNull(c.isTypeEditable, a.IsTypeEditable) as IsTypeEditable, isNull(c.KeyCol, '') as KeyCol, 0 as MultiSeq 
		from Com_FormulaMast_Block_Dtl a Left outer Join Com_FrmParamMast_Hdr b 
		On Convert(int, a.Block)=b.ParamID and a.ModuleCode=b.ModuleCode and a.BranchID=b.BranchID and a.CompID=b.CompID 
		Left Outer Join 
			(Select x.* from

				(Select c1.FrmID, c1.Block, c1.isTypePercentage, c1.isTypeEditable, c1.ValueUsed, c1.isValueEditable, c1.KeyCol
				from Com_tmpFormulaCalc_Dtl c1 
				where c1.DTKey=@DTKey and c1.UserID=@UserID and c1.BlockType='Param' and c1.ModuleCode=@ModuleCode and c1.BranchID=@BranchID and c1.CompID=@CompID
				) x

				 Inner Join

				(Select Distinct * from
					(Select c2.KeyCol
					from Com_tmpFormulaCalc_Dtl c2 Inner Join Com_FrmParamMast_Hdr c3 On c2.Block=c3.ParamID and c2.ModuleCode=c3.ModuleCode and c2.BranchID=c3.BranchID and c2.CompID=c3.CompID
					where c3.ValInputMethod='SC' and c2.DTKey=@DTKey and c2.UserID=@UserID and c2.BlockType='Param' and c2.ModuleCode=@ModuleCode and c2.BranchID=@BranchID and c2.CompID=@CompID
			
					Union All
	
					Select ''
					) y1
				) y

				On x.KeyCol=y.KeyCol
			) c
		On a.Block=c.Block 
		Where a.FrmID=@FrmID and a.BlockType='Param' and a.ModuleCode=@ModuleCode and a.BranchID=@BranchID and a.CompID=@CompID 
		
		Union All 
		
		Select a1.ExprSeq, a1.BlockSeq, a1.BlockType, a1.Block, a1.ValueUsed, '',  '', '', '', 0
		from Com_FormulaMast_Block_Dtl a1 
		Where a1.FrmID=@FrmID and a1.BlockType<>'Param' and a1.ModuleCode=@ModuleCode and a1.BranchID=@BranchID and a1.CompID=@CompID
		) m 


		
	Update @ExprBlockSeq Set MultiSeq = (Select Count(*) from @ExprBlockSeq b 
						Where b.KeyCol <= a.KeyCol and b.ExprSeq=a.ExprSeq and b.BlockSeq=a.BlockSeq
						Group by b.ExprSeq, b.BlockSeq, b.BlockType, b.Block)
	from @ExprBlockSeq a
	Where a.BlockType='Param' and a.KeyCol<>''

	Return

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_COM_CountProcess_PURDCSRTran_ItemGroupKey]    Script Date: 17/06/2026 11:38:42 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_COM_CountProcess_PURDCSRTran_ItemGroupKey](@CountNo int, @ItemCode varchar(50)='', 
@AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))    
RETURNS  @RetTbl TABLE  
 (  
		DCSRType varchar(3),
		DCSRNo int,
		DCSRDate datetime,
		RefType varchar(3),
		RefNo int,
		RefDate datetime,
		ItemGroupKey int,
		IGKCnt int,
		SentItemCode varchar(20),
		Qty float,
		Norms float,
		Mode varchar(2),
		SchDate datetime,
		Status char(1),
		CreatedDate	datetime,	
		UserID varchar(10),
		BranchID varchar(3),
		CompID varchar(3),
		Finyear varchar(20),
		TranStamp datetime
	)
 BEGIN   

	Declare @TblTmp_ItemGroupKey As Table
	(
		ItemGroupKey varchar(25),
		IGKCnt int,
		BranchID varchar(3),
		CompID varchar(3),	
		Finyear varchar(20)		
	)

	/* Insert Data Into Temp Table */
	If @Finyear<>''
	 Begin
		Insert Into @TblTmp_ItemGroupKey

			Select a.ItemGroupKey, Count(a.ItemGroupKey) As IGKCnt, a.BranchID, a.CompID, a.Finyear 
			From PUR_DCSR_Tran a
			Where a.BranchID=@BranchID and a.CompID=@CompID
			Group by a.ItemGroupKey, a.BranchID, a.CompID, a.Finyear
			Having Count(a.ItemGroupKey)>@CountNo

		/* Output (Result) */
		Insert into @RetTbl  

		Select a.DCSRType, a.DCSRNo, a.DCSRDate, a.RefType, a.RefNo, a.RefDate, a.ItemGroupKey, b.IGKCnt, 
				a.SentItemCode, a.Qty, a.Norms, a.Mode, a.SchDate, a.Status, a.CreatedDate, 
				a.UserID, a.BranchID, a.CompID, a.Finyear, a.TranStamp 
		From PUR_DCSR_Tran a
		Left Outer Join @TblTmp_ItemGroupKey b
			On a.ItemGroupKey=b.ItemGroupKey and a.BranchID=b.BranchID and a.CompID=b.CompID and a.Finyear=b.Finyear
		Where Exists( Select * From @TblTmp_ItemGroupKey t1
									Where a.ItemGroupKey=t1.ItemGroupKey and t1.BranchID=@BranchID and t1.CompID=@CompID and t1.Finyear=@Finyear
								)
			and (@ItemCode='' or (a.SentItemCode<>'' and a.SentItemCode=@ItemCode))
			and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear
	 End
	Else
	 Begin
		Insert Into @TblTmp_ItemGroupKey

			Select a.ItemGroupKey, Count(a.ItemGroupKey) As IGKCnt, a.BranchID, a.CompID, a.Finyear
			From PUR_DCSR_Tran a
			Where a.BranchID=@BranchID and a.CompID=@CompID
			Group by a.ItemGroupKey, a.BranchID, a.CompID, a.Finyear
			Having Count(a.ItemGroupKey)>@CountNo

		/* Output (Result) */
		Insert into @RetTbl  

		Select a.DCSRType, a.DCSRNo, a.DCSRDate, a.RefType, a.RefNo, a.RefDate, a.ItemGroupKey, b.IGKCnt,
				a.SentItemCode, a.Qty, a.Norms, a.Mode, a.SchDate, a.Status, a.CreatedDate, 
				a.UserID, a.BranchID, a.CompID, a.Finyear, a.TranStamp 
		From PUR_DCSR_Tran a
		Left Outer Join @TblTmp_ItemGroupKey b
			On a.ItemGroupKey=b.ItemGroupKey and a.BranchID=b.BranchID and a.CompID=b.CompID and a.Finyear=b.Finyear
		Where Exists( Select * From @TblTmp_ItemGroupKey t1
									Where a.ItemGroupKey=t1.ItemGroupKey and t1.BranchID=@BranchID and  t1.CompID=@CompID
								)
			and (@ItemCode='' or (a.SentItemCode<>'' and a.SentItemCode=@ItemCode))
			and a.BranchID=@BranchID and a.CompID=@CompID
	 End

 Return   
END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_COM_CountryCity_Master_Grp]    Script Date: 17/06/2026 11:38:42 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE  FUNCTION [dbo].[fn_COM_CountryCity_Master_Grp] (@isCity bit, @ForOperation varchar(1), @AsOnDate datetime)            
          
RETURNS  @RetTbl TABLE          
 (          
  ParentCode int,          
  ChildCode int,          
  RevNo  int,          
  RevDate  datetime,          
  EffStatus char(2),           
  EffDate  datetime,            
  TranStamp  datetime,          
  MinEffDate datetime            
 )          
          
 BEGIN           
  Insert into @RetTbl          
          
   Select m.ParentCode, m.ChildCode, --h.RevNo, h.RevDate, h.EffStatus, h.EffDate,  m.TranStamp, m.MinEffDate          
              
    IsNull(i.RevNo,h.RevNo) as RevNo, IsNull(i.RevDate,h.RevDate) as RevDate, IsNull(i.EffStatus,h.EffStatus) as EffStatus,           
    IsNull(i.EffDate,h.EffDate) as EffDate,  m.TranStamp, m.MinEffDate          
          
   From          
    (          
    --Header          
          
     Select h.ParentCode, h.ChildCode, Min(h.EffDate) As MinEffDate, Max(h.TranStamp) As TranStamp            
     From COM_CountryCity_Master h          
     Where h.TranStamp<=@AsOnDate and ((@isCity='0' AND h.ParentCode=0) OR (@isCity='1' AND h.ParentCode<>0))          
     Group by h.ParentCode, h.ChildCode          
    ) m          
   Left Outer Join COM_CountryCity_Master h           
    On m.ParentCode=h.ParentCode and m.ChildCode=h.ChildCode and m.TranStamp=h.TranStamp          
   Left Outer Join COM_CountryCity_Master i          
    On m.ChildCode=i.ParentCode  and i.ParentCode<>0          
           
 /* Delete based on FormOperation */          
  Delete from @RetTbl              
  Where ( (@ForOperation='M' AND EffStatus Like '[AHX]%')          
    OR (@ForOperation='E' AND (EffStatus Like '[NME]%' OR (EffStatus LIKE 'A%' AND  EffStatus Like '_[DX]')))          
    OR (@ForOperation='A' AND EffStatus Like '[AX]%')          
             )          
          
 Return           
          
 END
GO

