 CREATE FUNCTION [dbo].[fn_COM_EInvoiceJSONFile] (@AsOnDate datetime, @RptDate datetime,     
@BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))        
RETURNS @RetTable TABLE      
 (        
  DocType  Varchar(3),      
  DocNo  int,      
  DocDate  datetime,     
 FileContent  nvarchar(max),     
 IsCancel  bit,        
  Status  bit,      
  UserID  int,      
  BranchID Varchar(3),      
  CompID  Varchar(3),      
  Finyear  Varchar(20),      
  Transtamp  datetime      
 )      
       
 AS        
        
BEGIN       
 Insert @RetTable      
  Select * From COM_EInvoiceJSONFile a      
   Where a.TranStamp =       
    (      
     Select Max(b.TranStamp)       
     From COM_EInvoiceJSONFile b       
     Where b.TranStamp <= @AsOnDate and b.DocNo=a.DocNo /*and b.DocDate=a.DocDate*/     
     and b.DocType=a.DocType and b.BranchID=a.BranchID and b.CompID=a.CompID -- Finyear=a.Finyear       
    )      
   and a.BranchID=@BranchID and a.CompID=@CompID  -- Finyear=@Finyear     
 Return       
END      
