GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_COM_ERP_Options] ( @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3))  

RETURNS @RetTable TABLE
	(OptionCode		int,
	ModuleCode	int,
	OptionDesc	varchar(250),
	OptionValue	varchar(50),
	MinValue	varchar(50),
	MaxValue	varchar(50),
	OptionType	varchar(15),
	EffStatus	bit,
	EffDate		datetime,
	CreatedDate	datetime,
	Userid		varchar(10),
	Branchid	varchar(3),
	Compid		varchar(3),
	TranStamp	datetime
	)


 AS  

BEGIN 
	Insert @RetTable
		Select * from COM_ERP_Options a
		Where a.CreatedDate = (Select Max(b.CreatedDate) from COM_ERP_Options b where b.CreatedDate <= @AsOnDate 
			and b.ModuleCode=a.ModuleCode and b.OptionDesc=a.OptionDesc
			and b.BranchID=a.BranchID and b.CompID=a.CompID
			)
		and ((a.EffStatus='1' and a.EffDate <= @RptDate) or (a.EffStatus='0' and a.EffDate >= @RptDate))
			and a.BranchID=@BranchID and a.CompID=@CompID

	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_COM_Get_FinYearStartEnd]    Script Date: 17/06/2026 11:38:42 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION  [dbo].[fn_COM_Get_FinYearStartEnd](@TranDate datetime)        
RETURNS @FinYearList Table (FinStart datetime, FinEnd datetime)       
AS        
BEGIN       
 Declare @FinStart datetime, @FinEnd datetime;      
       
 If Month(@TranDate)<=3      
  BEGIN      
   SET @FinStart = Convert(datetime, Convert(varchar(4), Year(@TranDate)-1)+'0401');      
   SET @FinEnd = Convert(datetime, Convert(varchar(4), Year(@TranDate))+'0331');      
  END      
 Else      
  BEGIN      
   SET @FinStart = Convert(datetime, Convert(varchar(4), Year(@TranDate))+'0401');      
   SET @FinEnd = Convert(datetime, Convert(varchar(4), Year(@TranDate)+1)+'0331');      
  END      
       
 Insert into @FinYearList      
  Select @FinStart, @FinEnd;      
        
 RETURN;       
END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_COM_Get_HeatNo_Multi]    Script Date: 17/06/2026 11:38:42 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_COM_Get_HeatNo_Multi] (@DocType Varchar(3), @DocNo int, @DocDate datetime, @BranchID varchar(3),  @CompID varchar(3), @Finyear Varchar(20))        
RETURNS @HeatNoList Table       
(  
 ItemCode Varchar(20),      
 LotId bigInt,      
 SubLotID int,      
 HeatNo Varchar(20),      
 ManufactureDate datetime,      
 ShelfLifeDays int,    
 Qty float    
)      
AS          
BEGIN         
 Insert into @HeatNoList      
 Select a.TransactionItem, b.LotID, b.SubLotID, IsNull(c.HeatNo,'') as HeatNo, c.ManufactureDate,     
  IsNull(c.ShelfLifeDays, '') as ShelfLifeDays, b.Qty --IsNull(d.ShelfLifeDays, IsNull(c.ShelfLifeDays, '')) as ShelfLifeDays,     
 From         
 (        
  Select * From INV_MaterialTran_Dtl a                      
  Where a.DocType=@DocType and a.DocNo=@DocNo and a.DocDate=@DocDate and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear        
        
  Union All        
        
  Select TranDocId, -(ICode), DOCType, DOCNo, DOCDate, TransactionDate, TransactionTime, TransactionItem, TransactionQty, Norms,   
   FromWarehouseCode, FromRackBinCode, ToWarehouseCode, ToRackBinCode, ItemGroupKey, FromItem, ToItem, Justification, LIFO, FIFO, WA,   
   Userid, Branchid, Compid, Finyear         
  From INV_WIPTRAN_DTL a             
  Where a.DocType=@DocType and a.DocNo=@DocNo and a.DocDate=@DocDate and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear                           
   and not exists        
   (        
    Select * From INV_MaterialTran_Dtl s        
    Where s.DocNo=a.DocNo and s.DocDate=a.DocDate and s.DocType=a.DocType and s.TransactionDate=a.TransactionDate         
     and s.TransactionTime=a.TransactionTime and s.TransactionItem=a.TransactionItem and s.FromwarehouseCode=a.FromWarehouseCode        
     and s.FromRackBinCode=a.FromRackBinCode and s.TowarehouseCode=a.TowarehouseCode and s.ToRackBinCode=a.ToRackBinCode         
     and s.ItemGroupKey=a.ItemGroupKey and s.FromItem=a.FromItem and s.ToItem=a.ToItem         
     and s.BranchID=a.BranchID and s.CompID=a.CompID and s.Finyear=a.Finyear        
   )         
 )a          
 Left Outer Join COM_Trace_MaterialTran_TmpQty b        
  On a.ICode=b.TranID and a.BranchID=b.BranchID and a.CompID=b.CompID and a.Finyear=b.Finyear        
 Inner Join COM_Trace_LotMaster_TmpQty c        
  On b.LotID=c.LotID and b.BranchID=c.BranchID and b.CompID=c.CompID        
 --Left Outer Join REC_ReceiptEntry_dtl_Trace d      
  --On d.ReceiptEntryType=c.DocType and d.ReceiptEntryNo=c.DocNo and d.ReceiptEntryDate=c.DocDate       
   -- and d.ItemCode=c.ItemCode and d.BranchID=c.BranchID and d.CompID=c.CompID       
 Where a.DocType=@DocType and a.DocNo=@DocNo and a.DocDate=@DocDate       
  and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear  
    
 RETURN         
END 
GO

/****** Object:  UserDefinedFunction [dbo].[fn_COM_Get_MultiHeatNo_Qty]    Script Date: 17/06/2026 11:38:42 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_COM_Get_MultiHeatNo_Qty] (@DocType Varchar(3), @DocNo int, @DocDate datetime, 
	@BranchID varchar(3),  @CompID varchar(3), @Finyear Varchar(20))                
RETURNS @HeatNoList Table               
(
	ItemCode Varchar(20),              
	LotId bigInt,              
	SubLotID int,              
	HeatNo Varchar(20),              
	ManufactureDate datetime,              
	ShelfLifeDays int,            
	Qty float            
)              
AS                  
BEGIN                 
	/* Used following function for avoiding exponential values - convert(numeric(38,0), cast(b.Qty AS float)) as Qty */        

	Insert into @HeatNoList              
	Select a.TransactionItem, IsNull(b.LotID, 0) as LotID, IsNull(b.SubLotID, IsNull(d.SublotID, 1)) as SublotID, 
		IsNull(c.HeatNo,IsNull(d.HeatNo, '')) as HeatNo, IsNull(c.ManufactureDate, IsNull(d.ManufactureDate, '')) as ManufactureDate,    
		IsNull(c.ShelfLifeDays, IsNull(d.ShelfLifeDays, '')) as ShelfLifeDays, convert(numeric(38,0), cast(b.Qty AS float)) as Qty 
		--IsNull(d.ShelfLifeDays, IsNull(c.ShelfLifeDays, '')) as ShelfLifeDays,             
	From                 
	(                
	Select a1.TranDocId, a1.ICode, a1.DOCType, a1.DOCNo, a1.DOCDate, a1.TransactionDate, a1.TransactionTime,
			a1.TransactionItem, a1.TransactionQty, a1.Norms, a1.FromWarehouseCode, a1.FromRackBinCode, a1.ToWarehouseCode,
			a1.ToRackBinCode, a1.ItemGroupKey, a1.FromItem, a1.ToItem, a1.Justification, a1.LIFO, a1.FIFO, a1.WA, 
			a1.Userid, a1.Branchid, a1.Compid, a1.Finyear 
	From INV_MaterialTran_Dtl a1                              
		Where a1.DocType=@DocType and a1.DocNo=@DocNo and a1.DocDate=@DocDate and a1.BranchID=@BranchID 
			and a1.CompID=@CompID and a1.Finyear=@Finyear                
                
		Union All                
                
		Select a2.TranDocId, -(a2.ICode), a2.DOCType, a2.DOCNo, a2.DOCDate, a2.TransactionDate, a2.TransactionTime, 
			a2.TransactionItem, a2.TransactionQty, a2.Norms, a2.FromWarehouseCode, a2.FromRackBinCode, a2.ToWarehouseCode, 
			a2.ToRackBinCode, a2.ItemGroupKey, a2.FromItem, a2.ToItem, a2.Justification, a2.LIFO, a2.FIFO, a2.WA, 
			a2.Userid, a2.Branchid, a2.Compid, a2.Finyear                 
		From INV_WIPTRAN_DTL a2                     
		Where a2.DocType=@DocType and a2.DocNo=@DocNo and a2.DocDate=@DocDate and a2.BranchID=@BranchID 
			and a2.CompID=@CompID and a2.Finyear=@Finyear                                   
			and not exists                
			(                
				Select * From INV_MaterialTran_Dtl s                
				Where s.DocNo=a2.DocNo and s.DocDate=a2.DocDate and s.DocType=a2.DocType and s.TransactionDate=a2.TransactionDate                 
					and s.TransactionTime=a2.TransactionTime and s.TransactionItem=a2.TransactionItem and s.FromwarehouseCode=a2.FromWarehouseCode                
					and s.FromRackBinCode=a2.FromRackBinCode and s.TowarehouseCode=a2.TowarehouseCode and s.ToRackBinCode=a2.ToRackBinCode                 
					and s.ItemGroupKey=a2.ItemGroupKey and s.FromItem=a2.FromItem and s.ToItem=a2.ToItem                 
					and s.BranchID=a2.BranchID and s.CompID=a2.CompID and s.Finyear=a2.Finyear                
			)                 
	) a                  
	Left Outer Join COM_Trace_MaterialTran_TmpQty b                
		On a.ICode=b.TranID and a.BranchID=b.BranchID and a.CompID=b.CompID and a.Finyear=b.Finyear                
	Inner Join COM_Trace_LotMaster_TmpQty c                
		On b.LotID=c.LotID and b.BranchID=c.BranchID and b.CompID=c.CompID                
	Left Outer Join REC_ReceiptEntry_dtl_Trace d              
		On d.ReceiptEntryType=c.DocType and d.ReceiptEntryNo=c.DocNo and d.ReceiptEntryDate=c.DocDate               
			and d.ItemCode=c.ItemCode and d.BranchID=c.BranchID and d.CompID=c.CompID               
	Where a.DocType=@DocType and a.DocNo=@DocNo and a.DocDate=@DocDate and convert(numeric(38,0), cast(b.Qty AS float))>0           
		and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear 

	---------------------
	/* -- Previous Query:
	Insert into @HeatNoList              
	Select a.TransactionItem, IsNull(b.LotID, 0) as LotID, IsNull(b.SubLotID, IsNull(d.SublotID, 1)) as SublotID, 
		IsNull(c.HeatNo,IsNull(d.HeatNo, '')) as HeatNo, IsNull(c.ManufactureDate, IsNull(d.ManufactureDate, '')) as ManufactureDate,    
		IsNull(c.ShelfLifeDays, IsNull(d.ShelfLifeDays, '')) as ShelfLifeDays, convert(numeric(38,0), cast(b.Qty AS float)) as Qty 
		--IsNull(d.ShelfLifeDays, IsNull(c.ShelfLifeDays, '')) as ShelfLifeDays,             
	From                 
	(                
		Select * From INV_MaterialTran_Dtl a                              
		Where a.DocType=@DocType and a.DocNo=@DocNo and a.DocDate=@DocDate and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear                
                
		Union All                
                
		Select -(ICode), DOCType, DOCNo, DOCDate, TransactionDate, TransactionTime, TransactionItem, TransactionQty, Norms, 
			FromWarehouseCode, FromRackBinCode, ToWarehouseCode, ToRackBinCode, ItemGroupKey, FromItem, ToItem, Justification, LIFO, FIFO, WA, 
			Userid, Branchid, Compid, Finyear                 
		From INV_WIPTRAN_DTL a                     
		Where a.DocType=@DocType and a.DocNo=@DocNo and a.DocDate=@DocDate and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear                                   
			and not exists                
			(                
				Select * From INV_MaterialTran_Dtl s                
				Where s.DocNo=a.DocNo and s.DocDate=a.DocDate and s.DocType=a.DocType and s.TransactionDate=a.TransactionDate                 
					and s.TransactionTime=a.TransactionTime and s.TransactionItem=a.TransactionItem and s.FromwarehouseCode=a.FromWarehouseCode                
					and s.FromRackBinCode=a.FromRackBinCode and s.TowarehouseCode=a.TowarehouseCode and s.ToRackBinCode=a.ToRackBinCode                 
					and s.ItemGroupKey=a.ItemGroupKey and s.FromItem=a.FromItem and s.ToItem=a.ToItem                 
					and s.BranchID=a.BranchID and s.CompID=a.CompID and s.Finyear=a.Finyear                
			)                 
	)a                  
	Left Outer Join COM_Trace_MaterialTran_TmpQty b                
		On a.ICode=b.TranID and a.BranchID=b.BranchID and a.CompID=b.CompID and a.Finyear=b.Finyear                
	Inner Join COM_Trace_LotMaster_TmpQty c                
		On b.LotID=c.LotID and b.BranchID=c.BranchID and b.CompID=c.CompID                
	Left Outer Join REC_ReceiptEntry_dtl_Trace d              
		On d.ReceiptEntryType=c.DocType and d.ReceiptEntryNo=c.DocNo and d.ReceiptEntryDate=c.DocDate               
			and d.ItemCode=c.ItemCode and d.BranchID=c.BranchID and d.CompID=c.CompID               
	Where a.DocType=@DocType and a.DocNo=@DocNo and a.DocDate=@DocDate and convert(numeric(38,0), cast(b.Qty AS float))>0           
		and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear        
	*/           
	RETURN                 
END 
GO

/****** Object:  UserDefinedFunction [dbo].[fn_COM_Get_MultiHeatNo_ReceiptEntry]    Script Date: 17/06/2026 11:38:42 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_COM_Get_MultiHeatNo_ReceiptEntry] (@DocType Varchar(3), @DocNo int, @DocDate datetime, @BranchID varchar(3),  @CompID varchar(3), @Finyear Varchar(20))                
RETURNS @HeatNoList Table               
(
	ItemCode Varchar(20),              
	LotId bigInt,              
	SubLotID int,              
	HeatNo Varchar(20),              
	ManufactureDate datetime,              
	ShelfLifeDays int,            
	Qty float            
)              
AS                  
BEGIN                 
	/* Used following function for avoiding exponential values - convert(numeric(38,0), cast(b.Qty AS float)) as Qty */        
	Insert into @HeatNoList     
	Select a.ItemCode, 0 as LotID, IsNull(a.SubLotID, '') as SublotID, IsNull(a.HeatNo, '') as HeatNo, IsNull(a.ManufactureDate, '') as ManufactureDate,    
		IsNull(a.ShelfLifeDays, '') as ShelfLifeDays, convert(numeric(38,0), cast(a.Qty AS float)) as Qty  
	From REC_ReceiptEntry_dtl_Trace a             
	Where a.ReceiptEntryType=@DocType and a.ReceiptEntryNo=@DocNo and a.ReceiptEntryDate=@DocDate            
		and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear            
	Order by a.Seq   
	
	RETURN                 
END 
GO

/****** Object:  UserDefinedFunction [dbo].[fn_COM_Get_NumberSeries]    Script Date: 17/06/2026 11:38:42 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_COM_Get_NumberSeries](@SeriesMin decimal(13, 3), @SeriesMax decimal(13, 3), @SeriesIncr decimal(13, 3), @StartingNo decimal(13, 3), @EndEqualsStart bit)     
RETURNS @Series TABLE (SeqNo int, SeriesValue decimal(13, 3))    
AS    
BEGIN    
     
    DECLARE @Series_Tbl TABLE (SeqNo int, SeriesValue decimal(13, 3))    
    
    ;WITH Seq_CTE AS    
    (    
        SELECT 1 AS ID     
        UNION ALL     
        SELECT t.ID + 1 FROM Seq_CTE t    
        WHERE t.ID < (Convert(int, (@SeriesMax - @SeriesMin) / @SeriesIncr) + 1)    
    )    
    , Series_CTE AS    
    (     
        Select ID as SeqNo, @SeriesMin + ((ID-1)*@SeriesIncr) as SeriesValue     
        from Seq_CTE    
    )    
    INSERT INTO @Series_Tbl    
        SELECT SeqNo, SeriesValue From Series_CTE    
    
    DECLARE @SeqCnt int;    
    SELECT @SeqCnt=Count(*) From @Series_Tbl;    
    
    DECLARE @SeriesMinSeq int, @SeriesMaxSeq int;    
    SELECT @SeriesMinSeq=Min(SeqNo) From @Series_Tbl Where SeriesValue>=@StartingNo    
    SET @SeriesMaxSeq = @SeriesMinSeq + @SeqCnt - CASE WHEN @EndEqualsStart = 1 THEN 0 ELSE 1 END    
    
    INSERT INTO @Series_Tbl    
        SELECT SeqNo+@SeqCnt, SeriesValue From @Series_Tbl    
    
    INSERT INTO @Series    
        SELECT SeqNo-@SeriesMinSeq+1, SeriesValue From @Series_Tbl    
        WHERE SeqNo Between @SeriesMinSeq and @SeriesMaxSeq    
    
 RETURN     
END 
GO

/****** Object:  UserDefinedFunction [dbo].[fn_COM_GetExprResults]    Script Date: 17/06/2026 11:38:42 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_COM_GetExprResults] (@ModuleCode int, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(15))  

RETURNS @ExprResults TABLE
	(DocType	varchar(3),
	DocNo		int,
	DocDate	datetime,
	FrmID		int,
	ExprSeq	int,
	ExprName	varchar(50),
	GrandTotalFlag	int,
	ResultValue	money,
	PostingAc	int,
	ModuleCode	int,
	BranchID	varchar(3),
	CompID		varchar(3),
	Finyear		varchar(15)
	)	
	
AS  

BEGIN 

	Insert into @ExprResults		
		Select distinct a.DocType, a.DocNo, a.DocDate, a.FrmID, a.ExprSeq, b.ExprName, a.GrandTotalFlag, a.Resultvalue, a.PostingAc,
			 a.ModuleCode, a.BranchID, a.CompID, a.Finyear 
		from COM_FormulaCalc_Hdr a Left outer join 
				(Select c.FrmID, c.ExprSeq, Case when c.ExprRoute < 0 then 'SUB TOTAL' When c.ExprRoute='0001' Then 'TOTAL GST' else d.ExprGroupName End ExprName,
					c.PostingAc, c.ModuleCode, c.BranchID, c.CompID 
				from COM_FORMULAMAST_DTL c Left Outer Join COM_FormulaExpr_Group d
					On c.ModuleCode=d.ModuleCode and c.ExprRoute=d.Route+d.Width and c.BranchID=d.BranchID and c.CompID=d.CompID
				) b
		On a.ModuleCode=b.ModuleCode and a.FrmId=b.FrmId and a.ExprSeq=b.ExprSeq and a.BranchID=b.BranchID and a.CompID=b.CompID
		Where a.ModuleCode=@ModuleCode and a.BranchID=@BranchID and a.CompID= @CompID and b.ExprName<>'TOTAL GST'
                          and  a.Finyear=@Finyear	
/*		and a.Finyear=@Finyear		*/


		--To Insert roundoff Entry
		Insert into @ExprResults
		
		Select DocType, DocNo, DocDate, FrmID, isNull((Select Max(f.ExprSeq) from @ExprResults f where f.FrmID=e.FrmID), 0)+1 as ExprSeq, 
				'ROUNDOFF', Case When (GrandTotal > RoundedValue) Then -1 Else 1 End,
				(Case When (GrandTotal > RoundedValue) Then (GrandTotal - RoundedValue) Else (RoundedValue - GrandTotal) End  * Case When (GrandTotal > RoundedValue) Then -1 Else 1 End),
				 PostingAc, @ModuleCode, @BranchID, @CompID, @Finyear
		from		
			(Select c.DocType, c.DocNo, c.DocDate, c.FrmID, c.GrandTotal, 
					Convert(money, dbo.fn_RoundOff (c.GrandTotal, c.RoundOffValue, 2, c.RoundOff)) as RoundedValue, c.PostingAc
			from
				(Select  a.DocType, a.DocNo, a.DocDate, a.FrmID, Sum(a.ResultValue*a.GrandTotalFlag) as GrandTotal, 
					b.RoundOff, b.RoundOffValue, b.PostingAc 
				from @ExprResults a Left Outer Join COM_FormulaMast_Hdr b 
				On a.FrmID=b.FrmID and a.ModuleCode=b.ModuleCode and a.BranchID=b.BranchID and a.CompID=b.CompID
				Where b.RoundOff <> 'N' and b.ModuleCode=@ModuleCode and b.BranchID=@BranchID and b.CompID= @CompID
				Group by a.DocType, a.DocNo, a.DocDate, a.FrmID, b.RoundOff, b.RoundOffValue, b.PostingAc
				) c
			) e
		Where e.GrandTotal<>e.RoundedValue

		
		--To Insert Total Entry
		Insert into @ExprResults
		
		Select DocType, DocNo, DocDate, FrmID, isNull((Select Max(f.ExprSeq) from @ExprResults f where f.FrmID=a.FrmID), 0)+1 as ExprSeq, 
				'GRAND TOTAL', 0, Sum(a.ResultValue) as GrandTotal, 0, @ModuleCode, @BranchID, @CompID, @Finyear
		from  @ExprResults a 
				Where a.GrandTotalFlag <> 0 and a.ModuleCode=@ModuleCode and a.BranchID=@BranchID and a.CompID= @CompID
				Group by a.DocType, a.DocNo, a.DocDate, a.FrmID

	Return

END
GO

