CREATE FUNCTION [dbo].[fn_COM_GetExprResults_Saved] (@Doctype varchar(3), @DocNo int, @DocDate datetime, @ModuleCode int, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(15))  

