/****** Object:  UserDefinedFunction [dbo].[fn_COM_GetExprResults_Temp]    Script Date: 17/06/2026 11:38:42 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_COM_GetExprResults_Temp] (@UserKey varchar(36), @ModuleCode int, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(15))            
  
RETURNS @ExprResults TABLE          
 (UserKey varchar(36),          
 FrmID  int,          
 ExprSeq int,          
 ExprName varchar(50),          
 GrandTotalFlag int,          
 ResultValue money,          
 PostingAc int,          
 ModuleCode int,     
 BranchID varchar(3),          
 CompID  varchar(3),          
 Finyear  varchar(15)          
 )           
           
AS        
       
BEGIN           
 Insert into @ExprResults           
           
 Select Distinct @UserKey, a.FrmID, a.ExprSeq, b.ExprName, a.GrandTotalFlag, a.Result, b.PostingAc,           
   a.ModuleCode, a.BranchID, a.CompID, a.Finyear           
 From COM_tmpFormulaCalc_Hdr a           
 Left outer join ( Select c.FrmID, c.ExprSeq, --Case When c.ExprRoute < 0 Then 'Sub Total' Else d.ExprGroupName End ExprName,
						Case When c.ExprRoute < 0 then 'Sub Total' When c.ExprRoute='0001' Then 'TOTAL GST' else d.ExprGroupName End as ExprName,           
						c.PostingAc, c.ModuleCode, c.BranchID, c.CompID           
					From COM_FormulaMast_Dtl c           
					Left Outer Join COM_FormulaExpr_Group d          
					 On c.ModuleCode=d.ModuleCode and c.ExprRoute=(d.Route+d.Width) and c.BranchID=d.BranchID and c.CompID=d.CompID         
				   Where c.BranchID=@BranchID and c.CompID= @CompID         
           ) b          
    On a.ModuleCode=b.ModuleCode and a.FrmId=b.FrmId and a.ExprSeq=b.ExprSeq and a.BranchID=b.BranchID and a.CompID=b.CompID          
 Where a.DTKey=@UserKey and a.ModuleCode=@ModuleCode and a.BranchID=@BranchID and a.CompID= @CompID --and a.Finyear=@Finyear          
 /* To Insert RoundOff Entry */          
 Declare @FrmID int          
 Select Top 1 @FrmID=FrmID from @ExprResults          
           
 If Exists (Select * From COM_FormulaMast_Hdr Where ModuleCode=@ModuleCode and FrmID=@FrmID and RoundOff<>'N' )          
  BEGIN          
             
   Declare @ResValue money, @PostingAc int, @RoundOffValue money, @RoundOff varchar(1)          
             
   Select @ResValue=Sum(a.ResultValue*a.GrandTotalFlag), @RoundOffValue=b.RoundOffValue, @RoundOff=b.RoundOff,           
     @PostingAc=b.PostingAc          
    from @ExprResults a           
    Left Outer Join COM_FormulaMast_Hdr b          
     On a.FrmID=b.FrmID and a.ModuleCode=b.ModuleCode and a.BranchID=b.BranchID and a.CompID=b.CompID          
    Where b.RoundOff <> 'N' and b.ModuleCode=@ModuleCode and b.BranchID=@BranchID and b.CompID= @CompID          
    Group by b.FrmID, b.RoundOffValue, b.RoundOff, b.PostingAc          
                
   Declare @RoundResValue money          
   Select @RoundResValue = dbo.fn_RoundOff (@ResValue, @RoundOffValue, 2, @RoundOff)          
             
   If (@RoundResValue <> @ResValue)          
    BEGIN          
              
     Declare @ExprSeq int          
     Select @ExprSeq = isNull((Select Max(ExprSeq) from @ExprResults), 0) + 1          
     Insert into @ExprResults          
      Select @UserKey, @FrmID, @ExprSeq, 'ROUNDOFF',           
       Case When (@ResValue > @RoundResValue) Then -1 Else 1 End, Abs(@ResValue-@RoundResValue),           
       @PostingAc, @ModuleCode, @BranchID, @CompID, @Finyear           
              
    END          
             
  END          
 Return          
END

GO

/****** Object:  UserDefinedFunction [dbo].[fn_COM_PeriodSplit]    Script Date: 17/06/2026 11:38:42 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_COM_PeriodSplit](@FromDate datetime, @ToDate datetime, @PeriodSplitType char(1),     
    @FixedPeriodUOM varchar(1), @FixedPeriodSplitValue int, @isReturnWithTime bit)          
        /* @PeriodSplitType= T-Daily with Time; D-Daily; W-Weekly; M-Monthly; Y-Yearly; F-Fixed Period; */          
            /* Week Starts on determined by Regional Settings; Month Starts on 1st; Year Starts on 1st April; */          
        /* @FixedPeriodUOM (applicable only if @PeriodSplitType='F') = D-Days; W-Weeks; M-Months; Y-Years; else-Days*/          
        /* @@FixedPeriodSplitValue (applicable only if @PeriodSplitType='F') = No of FixedPeriodUOM per Split */          
RETURNS @PeriodTable TABLE     
                        (    
                        PrSeq       int,          
                        FromDate    datetime,          
                        ToDate      datetime          
                        )                                           
As                                          
          
BEGIN          
                                      
    Declare @PrStart datetime          
    Declare @PrEnd datetime          
    Declare @tmpFrom datetime          
    Declare @tmpStr varchar(20)          
              
    Declare @Seq int          
          
    If (@PeriodSplitType in ('Y', 'M', 'W', 'D', 'F'))          
        BEGIN          
            If (@PeriodSplitType='Y')       /* Split Financial Year wise */          
                BEGIN          
                    If (Month(@FromDate)<=3)          
                        Select @tmpStr=Year(@FromDate)-1          
                    Else          
                        Select @tmpStr=Year(@FromDate)          
                              
                    Select @tmpFrom=Convert(datetime, @tmpStr + '-04-01', 120)          
                              
                    Select @PrStart=@FromDate          
                              
                    Select @Seq = 0          
                              
                    WHILE (@PrStart<=@ToDate)          
                    BEGIN          
                        Select @PrEnd=DateAdd(dd, -1, DateAdd(yy, 1, @tmpFrom))          
                                  
                        If (@PrEnd > @ToDate)          
                            Select @PrEnd=@ToDate          
                              
                        Select @Seq=@Seq+1          
                                  
                        Insert into @PeriodTable          
                            Select @Seq, @PrStart, @PrEnd          
                                  
                        Select @PrStart=DateAdd(dd, 1, @PrEnd)          
                        Select @tmpFrom=@PrStart          
                    END          
                END          
            Else If (@PeriodSplitType='M')      /* Split Month wise */          
                BEGIN          
                              
                    Select @tmpStr=Convert(varchar(8), @FromDate, 120)          
          
                    Select @tmpFrom=Convert(datetime, @tmpStr + '01', 120)          
                              
                    Select @PrStart=@FromDate          
                              
                    Select @Seq = 0          
                              
                    WHILE (@PrStart<=@ToDate)          
                    BEGIN          
                        Select @PrEnd=DateAdd(dd, -1, DateAdd(mm, 1, @tmpFrom))          
                                  
                        If (@PrEnd > @ToDate)          
                            Select @PrEnd=@ToDate          
                              
                        Select @Seq=@Seq+1          
                                  
                        Insert into @PeriodTable          
                            Select @Seq, @PrStart, @PrEnd          
                                  
                        Select @PrStart=DateAdd(dd, 1, @PrEnd)          
                  Select @tmpFrom=@PrStart          
                    END          
                END          
            Else If (@PeriodSplitType='W')  /* Split Week (started weekday determined by regional setting) wise */          
                BEGIN          
                              
                    Select @tmpFrom=DateAdd(dd, -(DatePart(dw, @FromDate)-1), @FromDate)          
                              
                    Select @PrStart=@FromDate          
                              
                    Select @Seq = 0          
                              
                    WHILE (@PrStart<=@ToDate)          
                    BEGIN          
                Select @PrEnd=DateAdd(dd, 6, @tmpFrom)          
                                  
                        If (@PrEnd > @ToDate)          
                            Select @PrEnd=@ToDate          
                              
                        Select @Seq=@Seq+1          
                                  
                        Insert into @PeriodTable          
                            Select @Seq, @PrStart, @PrEnd          
                                  
                        Select @PrStart=DateAdd(dd, 1, @PrEnd)          
                        Select @tmpFrom=@PrStart          
                    END          
                END          
            Else If (@PeriodSplitType='D')      /* Split Day wise */          
                BEGIN          
                              
                    Select @tmpStr=Convert(varchar(10), @FromDate, 120)          
          
                    Select @tmpFrom=Convert(datetime, @tmpStr, 120)          
                              
                    Select @PrStart=@tmpFrom          
                              
                    Select @Seq = 0          
                              
                    WHILE (@PrStart<=@ToDate)          
                    BEGIN          
                        Select @PrEnd=@PrStart          
                                  
                        Select @Seq=@Seq+1          
                                  
                        Insert into @PeriodTable          
                            Select @Seq, @PrStart, @PrEnd          
                                  
                        Select @PrStart=DateAdd(dd, 1, @PrEnd)          
                        Select @tmpFrom=@PrStart          
                    END          
                END          
            Else If (@PeriodSplitType='F') AND (@FixedPeriodUOM in ('D', 'W', 'M', 'Y')) AND (@FixedPeriodSplitValue>0)      /* Split Fixed Period wise */          
                BEGIN          
          
                    Select @tmpFrom=@FromDate          
                              
                    Select @PrStart=@FromDate          
                              
                    Select @Seq = 0          
  
                    Declare @Interval int;  
                    if (@isReturnWithTime='1')  
                        SET @Interval=0;  
                    else  
                        SET @Interval=-1;  
                              
                    WHILE (@PrStart<=@ToDate)          
                    BEGIN          
                        If (@FixedPeriodUOM='Y')          
                            Select @PrEnd=DateAdd(dd, @Interval, DateAdd(yy, @FixedPeriodSplitValue, @tmpFrom))          
                        Else If (@FixedPeriodUOM='M')          
                            Select @PrEnd=DateAdd(dd, @Interval, DateAdd(mm, @FixedPeriodSplitValue, @tmpFrom))          
                        Else If (@FixedPeriodUOM='W')          
                            Select @PrEnd=DateAdd(dd, @Interval, DateAdd(ww, @FixedPeriodSplitValue, @tmpFrom))          
                        Else          
                            Select @PrEnd=DateAdd(dd, @Interval, DateAdd(dd, @FixedPeriodSplitValue, @tmpFrom))          
                                  
                        If (@PrEnd > @ToDate)          
                            Select @PrEnd=@ToDate          
                              
                        Select @Seq=@Seq+1          
                                  
                        Insert into @PeriodTable          
                            Select @Seq, @PrStart, @PrEnd          
                                  
                        if (@isReturnWithTime='1')  
                            Select @PrStart=@PrEnd  
                        else  
                            Select @PrStart=DateAdd(dd, 1, @PrEnd)          
                        Select @tmpFrom=@PrStart          
                    END          
                END        
            Else     /* No Split Return as it is */          
                BEGIN          
                    Select @Seq = 1          
                              
                    Insert into @PeriodTable          
                        Select @Seq, @FromDate, @ToDate          
                END    
            
            If (@isReturnWithTime=Convert(bit, '1') and Exists (Select * from @PeriodTable))    
                BEGIN    
                    Update @PeriodTable Set @ToDate=DateAdd(ss, -1, DateAdd(dd, 1, @tmpFrom))    
                END           
                          
        END    
            
    RETURN          
END 
GO

/****** Object:  UserDefinedFunction [dbo].[fn_COM_Product_BOM]    Script Date: 17/06/2026 11:38:42 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_COM_Product_BOM] (@ProductCode varchar(30), @ReturnType varchar(1), @AsOnDate datetime, 
	@RptDate datetime, @BranchID varchar(3), @CompID varchar(3))  
/* Created on 2025-05-02 by Anandh.S for BOM list for passed stagecode with option to return bottom most child too */  
RETURNS @ItemStructure TABLE      
 (ProductCode Varchar(30),      
  ParentCode  varchar(30),      
  ItemCode  varchar(30),      
  ItemType  char(1),   /* P for Product; S for Stage; C for Child */      
  Qty   float,   /* Norms */      
  PQty   float,   /* Norms with related to Parent*/      
  StructureLevel  int,   /* Level From the Given Product Level starts from 0 */      
  OperationSeq  int,      
  BranchID  varchar(3),      
  CompID  varchar(3))      
AS        
BEGIN       
 /*@ReturnType   'C' : Bottom most child in each branch;  All Other return full BOM List */      
    
 Declare @MPS_Master Table(ItemCode varchar(30), StageCode varchar(30), OperationSeq int);    
 Declare @Structure_dtl Table(ParentCode varchar(30), ChildCode varchar(30), Qty numeric(10, 5), Explodable bit, [Percentage] numeric(5, 2), [Priority] int)    
    
 Insert into @MPS_Master    
 Select ItemCode, StageCode, OperationSequence As OperationSeq From dbo.fn_BOM_MPS_Master('A', @AsonDate, @RptDate, @BranchID, @CompID);    
 --Select ItemCode, StageCode, OperationSeq From Test_MPS_Master;    
    
 Insert into @Structure_dtl    
 Select ParentCode, ChildCode, Qty, Explodable, [Percentage], [Priority] From dbo.fn_BOM_Structure_Dtl('A', @AsonDate, @RptDate, @BranchID, @CompID);    
 --Select ParentCode, ChildCode, Qty, Explodable, [Percentage], [Priority] from Test_Structure_Dtl;    
  
 DECLARE @ProductItemCode varchar(30);  
 Select Top 1 @ProductItemCode = ItemCode  
 From @MPS_Master  
 Where @ProductCode in (ItemCode, StageCode);  
  
 If (@ProductItemCode is Null) AND Exists (Select * From @Structure_dtl Where ChildCode=@ProductCode)  
 BEGIN  
  --Inserting the passed Product in Temp Table as Raw Material       
  Insert into @ItemStructure values (@ProductCode, @ProductCode, @ProductCode, 'C', 1, 1, 0, 0, @BranchID, @CompID);  
 END  
 ELSE If (@ProductItemCode is Null)  
  --Inserting the passed Product in Temp Table as Raw Material       
  Insert into @ItemStructure values (@ProductCode, '', '', 'P', 1, 1, 0, 0, @BranchID, @CompID);   
 ELSE  
 BEGIN  
  Declare @Level int      
  Select @Level=0      
       
  Declare @Success bit      
  Select @Success = Convert(bit, '1')      
  Declare @ParentCode varchar(20)      
      
  --Inserting the Initial Product in Temp Table for further processing      
  Insert into @ItemStructure values (@ProductItemCode, @ProductItemCode, @ProductItemCode, 'P', 1, 1, 0, 0, @BranchID, @CompID);     
      
  While @Success = Convert(bit, '1') --and @Level<7    
  Begin      
   Select @Level = @Level + 1      
      
   If (@Level % 2 = 1)  --If Level is Odd No. then Search Stages else Search Childs      
   Begin      
    If Exists (Select * From @MPS_Master      
     Where ItemCode in  (Select ItemCode From @ItemStructure      
      Where ProductCode = @ProductItemCode and StructureLevel = @Level-1 and BranchID=@BranchID and CompID=@CompID))      
    Begin      
         
     Insert into @ItemStructure      
      Select @ProductItemCode, m.ItemCode, m.StageCode, 'S', 1, n.PQty, @Level, m.OperationSeq, @BranchID, @CompID      
      from @MPS_Master m       
      Inner Join       
      (  
       Select * from @ItemStructure      
       Where ProductCode = @ProductItemCode and  StructureLevel = @Level-1 and BranchID=@BranchID and CompID=@CompID  
      )  n      
      On m.ItemCode=n.ItemCode --and m.BranchID=n.BranchID and m.CompID=n.CompID      
         
     Select @Success = Convert(bit, 1)      
    End      
    Else      
    Begin      
     Select @Success = Convert(bit, 0)      
    End      
   End        
   Else      
   Begin      
    If Exists (Select * From @Structure_dtl      
     Where ParentCode in (Select ItemCode From @ItemStructure      
      Where ProductCode = @ProductItemCode and StructureLevel = @Level-1 and BranchID=@BranchID and CompID=@CompID)      
    )       
    Begin      
     Insert into @ItemStructure      
     Select @ProductItemCode, m.ParentCode, m.ChildCode, 'C', m.Qty, m.Qty*n.PQty,    
      @Level, 0, @BranchID, @CompID      
     From @Structure_dtl m      
     Inner Join      
     (  
      Select * From @ItemStructure      
      Where ProductCode = @ProductItemCode and StructureLevel = @Level-1 and BranchID=@BranchID and CompID=@CompID  
     ) n      
      On  m.ParentCode=n.ItemCode --and m.BranchID=n.BranchID and m.CompID=n.CompID      
     Where m.[Priority]=1      
         
     Select @Success = Convert(bit, 1)      
    End      
    Else      
    Begin      
     Select @Success = Convert(bit, 0)      
    End      
   End       
  End      
      
  If (@ReturnType='C') --Bottom Most Childs      
  Begin      
   --Other than Actual required child item are deleted      
   Delete @ItemStructure      
   Where (ItemType<>'C' Or (ItemType='C'     
    and ItemCode in      
    (    
     Select ItemCode  from @ItemStructure a      
     where a.Itemtype='S' and a.BranchID=@BranchID and a.CompID=@CompID       
    )))    
  End      
    END  
  
 Return;        
END 
GO

/****** Object:  UserDefinedFunction [dbo].[fn_COM_Trace_AsOnDate_Stock]    Script Date: 17/06/2026 11:38:42 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_COM_Trace_AsOnDate_Stock] (@ItemCode Varchar(30), @StockDate datetime, @AsonDate datetime, @RptDate datetime, @BranchID varchar(3),  @CompID varchar(3),  @Finyear varchar(20))      
RETURNS @RetTable TABLE                    
	(
		[ItemCode]			[varchar] (30),                     
		[WarehouseCode]		[varchar] (6),                   
		[WarehouseNature]	[varchar] (20),                 
		[RackBinCode]		[varchar] (10),              
		[LotID]				[int],                
		[CBQty]				[float],                    
		[BranchID]			[varchar] (3),                    
		[CompID]			[varchar] (3)    
		-- , RunningTotal [float]  
	)                    
AS                      
BEGIN    
	
	DECLARE @PrevFinyear Varchar(20)
		Select @PrevFinyear = '04-' + Convert(Varchar,RIGHT(RTRIM(LTRIM( LEFT(@Finyear,CHARINDEX(' ', @Finyear)))),4) - 1)  
                            + ' ' + '03-' + Convert(Varchar,RIGHT(RTRIM(LTRIM(RIGHT(@Finyear,CHARINDEX(' ', REVERSE(@Finyear))))),4) - 1)

	DECLARE @TraceReImportFinStart Varchar(20)
		Select @TraceReImportFinStart='04-2024 03-2025'

	;WITH ItemList_CTE    
	AS               
	(    
		Select * , ROW_NUMBER() OVER(ORDER BY a.LotID) as Seq --CONVERT(DECIMAL(15,5),SUM(CbQty) OVER(ORDER BY LotID ROWS UNBOUNDED PRECEDING)) AS RunningTotal    
		From    
		(    
			Select b.TransactionItem as ItemCode, c.WarehouseCode, c.WarehouseNature, c.RackBinCode, IsNull(d.LotID,0) as LotID,                    
				IsNull(Sum(Case When (b.ToWarehouseCode = c.WarehouseCode and b.ToRackBinCode=c.RackBinCode) Then d.Qty                
				When (b.FromWarehouseCode = c.WarehouseCode and b.FromRackBinCode=c.RackBinCode) Then -d.Qty      
				Else 0 End), 0) as CbQty,                  
				b.BranchID, b.CompID 
			From                          
			(
				
				Select '0' as ReverseEntryFlg, ICode, DOCType, DOCNo, DOCDate, Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) as TransactionDate, 
                    TransactionItem, TransactionQty, Norms, FromWarehouseCode, FromRackBinCode, ToWarehouseCode, ToRackBinCode, ItemGroupKey, 
                    FromItem, ToItem, Justification, LIFO, FIFO, WA, Userid, Branchid, Compid, Finyear 
                From INV_MaterialTran_Dtl a              
				Where a.TransactionItem=@ItemCode and Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) <= @StockDate                    
					and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear>=@TraceReImportFinStart	--and a.Finyear = @Finyear     

                Union All

                Select a.ReverseEntryFlg, a.TranID as ICode, 'DUM' as DOCType, 1 as DOCNo, Convert(Varchar(10),a.Transtamp,121) as DOCDate, a.Transtamp as TransactionDate, 
                    a.ItemCode as TransactionItem, a.Qty as TransactionQty, 1 as Norms, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode, 0 as ItemGroupKey, 
                    a.ItemCode as FromItem, a.ItemCode as ToItem, 'DUMMY' as Justification, 0 as LIFO, 0 as FIFO, 0 as WA, a.Userid, a.Branchid, a.Compid, a.Finyear
                From 
                    (
                        Select a.ReverseEntryFlg, a.TranID, a.Transtamp, a.ItemCode,  Sum(a.Qty) as Qty, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode,
							a.Userid, a.Branchid, a.Compid, a.Finyear   
						From COM_Trace_MaterialTran_TmpQty a       
                        Where a.ItemCode=@ItemCode and a.Transtamp <= @StockDate                
			                and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear>=@TraceReImportFinStart	--and a.Finyear = @Finyear  
							and IsNumeric(a.FromWarehouseCode)='1' and a.ToWarehouseCode='DUM'    
						Group by a.ReverseEntryFlg, a.TranID, a.Transtamp, a.ItemCode, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode,
							a.Userid, a.Branchid, a.Compid, a.Finyear 
 
                        Union   

                        Select a.ReverseEntryFlg, a.TranID, a.Transtamp, a.ItemCode,  Sum(a.Qty) as Qty, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode,
							a.Userid, a.Branchid, a.Compid, a.Finyear   
						From COM_Trace_MaterialTran_TmpQty a       
                        Where a.ItemCode=@ItemCode and a.Transtamp <= @StockDate                  
                            and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear>=@TraceReImportFinStart	--and a.Finyear = @Finyear 
							and a.FromWarehouseCode='DUM'  and IsNumeric(a.ToWarehouseCode)='1'
						Group by a.ReverseEntryFlg, a.TranID, a.Transtamp, a.ItemCode, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode,
							a.Userid, a.Branchid, a.Compid, a.Finyear 

                    )a

                Union All

                Select a.ReverseEntryFlg, a.TranID as ICode, 'OPB' as DOCType, 1 as DOCNo, '2024-04-01' as DOCDate, '2024-03-31 23:59:59' as TransactionDate, a.ItemCode as TransactionItem, 
                    a.Qty, 1 as Norms, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode, 0 as ItemGroupKey, 
                    a.ItemCode as FromItem, a.ItemCode as ToItem, 'Opening Balance' as Justification, 0 as LIFO, 0 as FIFO, 0 as WA, a.Userid, a.Branchid, a.Compid, a.Finyear
                From COM_Trace_MaterialTran_TmpQty a  
                Where  a.ItemCode=@ItemCode and a.Transtamp <= @StockDate  and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear>=@TraceReImportFinStart	--and a.Finyear = @Finyear   
                    and a.FromWarehouseCode='OPB' and a.ReverseEntryFlg='1' --and IsNumeric(a.ToWarehouseCode)='1'

				Union All

				Select '0' as ReverseEntryFlg, -(ICode), DOCType, DOCNo, DOCDate, Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) as TransactionDate, 
                    TransactionItem, TransactionQty, Norms, FromWarehouseCode, FromRackBinCode, ToWarehouseCode, ToRackBinCode, ItemGroupKey, 
                    FromItem, ToItem, Justification, LIFO, FIFO, WA, Userid, Branchid, Compid, Finyear 
				From INV_WIPTRAN_DTL a              
				Where a.TransactionItem=@ItemCode and Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) <= @StockDate                    
					and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear>=@TraceReImportFinStart	--and a.Finyear = @Finyear        
					and not exists
						(
							Select * From INV_MaterialTran_Dtl s
							Where s.DocNo=a.DocNo and s.DocDate=a.DocDate and s.DocType=a.DocType and s.TransactionDate=a.TransactionDate 
								and s.TransactionTime=a.TransactionTime and s.TransactionItem=a.TransactionItem and s.FromwarehouseCode=a.FromWarehouseCode
								and s.FromRackBinCode=a.FromRackBinCode and s.TowarehouseCode=a.TowarehouseCode and s.ToRackBinCode=a.ToRackBinCode 
								and s.ItemGroupKey=a.ItemGroupKey and s.FromItem=a.FromItem and s.ToItem=a.ToItem 
								and s.BranchID=a.BranchID and s.CompID=a.CompID and s.Finyear=a.Finyear
						) 
			)b
			Left Outer Join COM_Trace_MaterialTran_TmpQty d          
				On b.ICode=d.TranID and b.ReverseEntryFlg=d.ReverseEntryFlg and b.BranchID=d.BranchID and b.CompID=d.CompID and b.Finyear=d.Finyear        
                  
			Full Outer Join 
				(
					Select WarehouseCode, '' as RackBinCode, WarehouseNature, BranchID, CompID
					From INV_Warehouse_Master_All c   
		
					Union all

                    Select 'DUM' as WarehouseCode, '' as RackBinCode, 'DUMMY' as WarehouseNature, @BranchID as BranchID, @CompID as CompID

					Union all

					Select Convert(Varchar,LedgerCode), '' as RackBinCode, 'Ledger' as WarehouseNature, @BranchID as BranchID, @CompID as CompID
					From FAS_LedgerMaster_AuthTbl
					Where Left(LrRoute,4) in ('0303', '0206') and CompCode=@CompID+@BranchID              
				)c 
				On c.BranchID = b.BranchID and c.CompID = b.CompID                    
                    
			Where b.TransactionItem=@ItemCode     
				and c.WarehouseCode in (b.FromWarehouseCode, b.ToWarehouseCode)                    
				and b.TransactionDate <= @StockDate                    
				and b.BranchID = @BranchID and b.CompID = @CompID and b.Finyear>=@TraceReImportFinStart	--and b.Finyear = @Finyear 
				--and c.WarehouseCode=@WarehouseCode         
			group by b.TransactionItem, c.WarehouseCode, c.WarehouseNature, c.RackBinCode, d.LotID, b.BranchID, b.CompID                    
		) a    
		Where a.CBQty>0    
	)    
    
    INSERT INTO @RetTable  -- Select * from ItemList_CTE     
		Select ItemCode, WarehouseCode, WarehouseNature, RackBinCode, LotID,      
			CBQty, BranchID, CompID
		From ItemList_CTE    
    
	RETURN;    
END 
GO

/****** Object:  UserDefinedFunction [dbo].[fn_COM_Trace_AsOnDate_Stock_ItemWHS_DocTran]    Script Date: 17/06/2026 11:38:42 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_COM_Trace_AsOnDate_Stock_ItemWHS_DocTran] (@ItemCode Varchar(30), @WarehouseCode Varchar(6), @ReqQty decimal(15, 5), @StockDate datetime, @AsonDate datetime, @RptDate datetime, @BranchID varchar(3),  @CompID varchar(3),  @Finyear varchar(20))        
RETURNS @RetTable TABLE                      
(
	[ItemCode]		[varchar] (30),                                     
    [TranDocID]		[bigint], 
	[LotID]			[bigint], 
    [CBQty]			[float],                      
    [BranchID]		[varchar] (3),                      
    [CompID]		[varchar] (3)      
    -- , RunningTotal [float]    
)                      
AS                        
BEGIN  
	 
	--Declare @ItemCode Varchar(30), @WarehouseCode Varchar(6), @ReqQty decimal(15, 5), @StockDate datetime, @AsonDate datetime, @RptDate datetime, @BranchID varchar(3),  @CompID varchar(3),  @Finyear varchar(20)
	--	Select @ItemCode='1U0201100H', @WarehouseCode='WIP', @ReqQty = 200, @StockDate='2025-04-01 11:20:19.000', @AsonDate='2025-04-01 11:20:19.000', @RptDate='2025-04-01 11:20:19.000',
	--		@BranchID='00', @CompID='02', @Finyear='04-2025 03-2026'

    Declare @TblItem Table (ItemCode Varchar(30), TranDocID bigint, LotID bigint, CBQty Float, Seq int)     
	Insert into @TblItem
		Select ItemCode, TranDocID, LotID, CBQty, ROW_NUMBER() OVER(ORDER BY a.TranDocID) as Seq
		From
		(
			Select ItemCode, TranDocID, LotID, Sum(Qty) as CBQty
			From
			(
				Select ItemCode, Qty, LotID, ToTranDocID as TranDocID 
				From COM_Trace_DocTran_Trial a
				Where a.ItemCode=@ItemCode and a.Transtamp <=  @StockDate                      
					and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear = @Finyear                       
					and a.ToWarehouseCode=@WarehouseCode         


				Union All

				Select ItemCode, -Qty, LotID, FromTranDocID  
				From COM_Trace_DocTran_Trial a
				Where a.ItemCode=@ItemCode and a.Transtamp <=  @StockDate                      
					and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear = @Finyear                       
					and a.FromWarehouseCode=@WarehouseCode        

			)a
			Group by ItemCode, TranDocID, LotID
		)a
		Where a.CBQty>0    
  
	Declare @TblTmp Table (ItemCode varchar(30), TranDocID bigint, LotID bigint, CBQty Float, RunningTotal Float, Seq int)
	Insert into @TblTmp
		Select a.ItemCode, a.TranDocID, a.LotID, a.CBQty, IsNull(Sum(b.CbQty),0) as RunningTotal, a.Seq   
		From @TblItem a    
		Left Outer Join @TblItem b    
			On a.Seq>=b.Seq
		Group by a.ItemCode, a.TranDocID, a.LotID, a.CBQty, a.Seq    

	IF Exists (Select Top 1 TranDocID From @TblTmp Where RunningTotal>=@ReqQty Order By RunningTotal)
		BEGIN
			INSERT INTO @RetTable    
				Select @ItemCode as ItemCode, TranDocID, LotID,
					Case When RunningTotal<@ReqQty Then CBQty Else CBQty-(RunningTotal-@ReqQty) End as CBQty, @BranchID as BranchID, @CompID as CompID -- , RunningTotal    
				From @TblTmp      
				Where Seq<=(Select Top 1 Seq From @TblTmp Where RunningTotal>=@ReqQty Order By RunningTotal)      
		END
	ELSE
		BEGIN
			INSERT INTO @RetTable    	
				Select @ItemCode as ItemCode, TranDocID, LotID,
					Case When RunningTotal<@ReqQty Then CBQty Else CBQty-(RunningTotal-@ReqQty) End as CBQty, @BranchID as BranchID, @CompID as CompID -- , RunningTotal    
				From @TblTmp     
		END

    RETURN;      
END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_COM_Trace_AsOnDate_Stock_ItemWHS_DocTran_TranDocID]    Script Date: 17/06/2026 11:38:42 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_COM_Trace_AsOnDate_Stock_ItemWHS_DocTran_TranDocID] (@ItemCode Varchar(30), @TranDocId bigint, @WarehouseCode Varchar(6), @ReqQty decimal(15, 5), @StockDate datetime, @AsonDate datetime, @RptDate datetime, @BranchID varchar(3),  @CompID varchar(3),  @Finyear varchar(20))        
RETURNS @RetTable TABLE                      
(
	[ItemCode]		[varchar] (30),                                     
    [TranDocID]		[bigint], 
	[LotID]			[bigint], 
    [CBQty]			[float],                      
    [BranchID]		[varchar] (3),                      
    [CompID]		[varchar] (3)          
)                      
AS                        
BEGIN  
	 
	--Declare @ItemCode Varchar(30), @WarehouseCode Varchar(6), @ReqQty decimal(15, 5), @StockDate datetime, @AsonDate datetime, @RptDate datetime, @BranchID varchar(3),  @CompID varchar(3),  @Finyear varchar(20)
	--	Select @ItemCode='1U0201100H', @WarehouseCode='WIP', @ReqQty = 200, @StockDate='2025-04-01 11:20:19.000', @AsonDate='2025-04-01 11:20:19.000', @RptDate='2025-04-01 11:20:19.000',
	--		@BranchID='00', @CompID='02', @Finyear='04-2025 03-2026'

    Declare @TblItem Table (ItemCode Varchar(30), TranDocID bigint, LotID bigint, CBQty Float, Seq int)     
	Insert into @TblItem
		Select ItemCode, TranDocID, LotID, CBQty, ROW_NUMBER() OVER(ORDER BY a.TranDocID) as Seq
		From
		(
			Select ItemCode, TranDocID, LotID, Sum(Qty) as CBQty
			From
			(
				Select ItemCode, Qty, LotID, ToTranDocID as TranDocID 
				From COM_Trace_DocTran_Trial a
				Where a.ItemCode=@ItemCode and a.Transtamp <=  @StockDate                      
					and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear = @Finyear                       
					and a.ToWarehouseCode=@WarehouseCode and a.ToTranDocID=@TranDocID         


				Union All

				Select ItemCode, -Qty, LotID, FromTranDocID  
				From COM_Trace_DocTran_Trial a
				Where a.ItemCode=@ItemCode and a.Transtamp <=  @StockDate                      
					and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear = @Finyear                       
					and a.FromWarehouseCode=@WarehouseCode and a.FromTranDocID=@TranDocID        

			)a
			Group by ItemCode, TranDocID, LotID
		)a
		Where a.CBQty>0    
  
	Declare @TblTmp Table (ItemCode varchar(30), TranDocID bigint, LotID bigint, CBQty Float, RunningTotal Float, Seq int)
	Insert into @TblTmp
		Select a.ItemCode, a.TranDocID, a.LotID, a.CBQty, IsNull(Sum(b.CbQty),0) as RunningTotal, a.Seq   
		From @TblItem a    
		Left Outer Join @TblItem b    
			On a.Seq>=b.Seq
		Group by a.ItemCode, a.TranDocID, a.LotID, a.CBQty, a.Seq    

	IF Exists (Select Top 1 TranDocID From @TblTmp Where RunningTotal>=@ReqQty Order By RunningTotal)
		BEGIN
			INSERT INTO @RetTable    
				Select @ItemCode as ItemCode, TranDocID, LotID,
					Case When RunningTotal<@ReqQty Then CBQty Else CBQty-(RunningTotal-@ReqQty) End as CBQty, @BranchID as BranchID, @CompID as CompID -- , RunningTotal    
				From @TblTmp      
				Where Seq<=(Select Top 1 Seq From @TblTmp Where RunningTotal>=@ReqQty Order By RunningTotal)      
		END
	ELSE
		BEGIN
			INSERT INTO @RetTable    	
				Select @ItemCode as ItemCode, TranDocID, LotID,
					Case When RunningTotal<@ReqQty Then CBQty Else CBQty-(RunningTotal-@ReqQty) End as CBQty, @BranchID as BranchID, @CompID as CompID -- , RunningTotal    
				From @TblTmp     
		END

    RETURN;      
END
GO

