CREATE FUNCTION [dbo].[fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotQty] (@ItemCode Varchar(30), @WarehouseCode Varchar(6), @ReqQty decimal(15, 5), @StockDate datetime,    
																	    @AsonDate datetime, @RptDate datetime, @BranchID varchar(3),  @CompID varchar(3),  @Finyear varchar(20))      
RETURNS @RetTable TABLE                    
	(
		[ItemCode]			[varchar] (30),                     
		[WarehouseCode]		[varchar] (6),                   
		[WarehouseNature]	[varchar] (20),                 
		[RackBinCode]		[varchar] (10),              
		[LotID]				[int],                
		[CBQty]				[float],                    
		[BranchID]			[varchar] (3),                    
		[CompID]			[varchar] (3)    
		-- , RunningTotal [float]  
	)                    
AS                      
BEGIN    
	
	DECLARE @PrevFinyear Varchar(20)
		Select @PrevFinyear = '04-' + Convert(Varchar,RIGHT(RTRIM(LTRIM( LEFT(@Finyear,CHARINDEX(' ', @Finyear)))),4) - 1)  
                            + ' ' + '03-' + Convert(Varchar,RIGHT(RTRIM(LTRIM(RIGHT(@Finyear,CHARINDEX(' ', REVERSE(@Finyear))))),4) - 1)

	DECLARE @TraceReImportFinStart Varchar(20)
		Select @TraceReImportFinStart='04-2024 03-2025'

	;WITH ItemList_CTE    
	AS               
	(    
		Select * , ROW_NUMBER() OVER(ORDER BY a.LotID) as Seq --CONVERT(DECIMAL(15,5),SUM(CbQty) OVER(ORDER BY LotID ROWS UNBOUNDED PRECEDING)) AS RunningTotal    
		From    
		(    
			Select b.TransactionItem as ItemCode, c.WarehouseCode, c.WarehouseNature, c.RackBinCode, IsNull(d.LotID,0) as LotID,                    
				IsNull(Sum(Case When (b.ToWarehouseCode = c.WarehouseCode and b.ToRackBinCode=c.RackBinCode) Then d.Qty                
				When (b.FromWarehouseCode = c.WarehouseCode and b.FromRackBinCode=c.RackBinCode) Then -d.Qty      
				Else 0 End), 0) as CbQty,                  
				b.BranchID, b.CompID 
			From                          
			(
				
				Select '0' as ReverseEntryFlg, ICode, DOCType, DOCNo, DOCDate, Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) as TransactionDate, 
                    TransactionItem, TransactionQty, Norms, FromWarehouseCode, FromRackBinCode, ToWarehouseCode, ToRackBinCode, ItemGroupKey, 
                    FromItem, ToItem, Justification, LIFO, FIFO, WA, Userid, Branchid, Compid, Finyear 
                From INV_MaterialTran_Dtl a              
				Where a.TransactionItem=@ItemCode and Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) <= @StockDate                    
					and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear>=@TraceReImportFinStart	--and a.Finyear = @Finyear     

                Union All

                Select a.ReverseEntryFlg, a.TranID as ICode, 'DUM' as DOCType, 1 as DOCNo, Convert(Varchar(10),a.Transtamp,121) as DOCDate, a.Transtamp as TransactionDate, 
                    a.ItemCode as TransactionItem, a.Qty as TransactionQty, 1 as Norms, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode, 0 as ItemGroupKey, 
                    a.ItemCode as FromItem, a.ItemCode as ToItem, 'DUMMY' as Justification, 0 as LIFO, 0 as FIFO, 0 as WA, a.Userid, a.Branchid, a.Compid, a.Finyear
                From 
                    (
                        Select a.ReverseEntryFlg, a.TranID, a.Transtamp, a.ItemCode,  Sum(a.Qty) as Qty, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode,
							a.Userid, a.Branchid, a.Compid, a.Finyear   
						From COM_Trace_MaterialTran_TmpQty a       
                        Where a.ItemCode=@ItemCode and a.Transtamp <= @StockDate                
			                and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear>=@TraceReImportFinStart	--and a.Finyear = @Finyear  
							and IsNumeric(a.FromWarehouseCode)='1' and a.ToWarehouseCode='DUM'    
						Group by a.ReverseEntryFlg, a.TranID, a.Transtamp, a.ItemCode, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode,
							a.Userid, a.Branchid, a.Compid, a.Finyear 
 
                        Union   

                        Select a.ReverseEntryFlg, a.TranID, a.Transtamp, a.ItemCode,  Sum(a.Qty) as Qty, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode,
							a.Userid, a.Branchid, a.Compid, a.Finyear   
						From COM_Trace_MaterialTran_TmpQty a       
                        Where a.ItemCode=@ItemCode and a.Transtamp <= @StockDate                  
                            and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear>=@TraceReImportFinStart	--and a.Finyear = @Finyear 
							and a.FromWarehouseCode='DUM'  and IsNumeric(a.ToWarehouseCode)='1'
						Group by a.ReverseEntryFlg, a.TranID, a.Transtamp, a.ItemCode, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode,
							a.Userid, a.Branchid, a.Compid, a.Finyear 

                    )a

                Union All

                Select a.ReverseEntryFlg, a.TranID as ICode, 'OPB' as DOCType, 1 as DOCNo, '2024-04-01' as DOCDate, '2024-03-31 23:59:59' as TransactionDate, a.ItemCode as TransactionItem, 
                    a.Qty, 1 as Norms, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode, 0 as ItemGroupKey, 
                    a.ItemCode as FromItem, a.ItemCode as ToItem, 'Opening Balance' as Justification, 0 as LIFO, 0 as FIFO, 0 as WA, a.Userid, a.Branchid, a.Compid, a.Finyear
                From COM_Trace_MaterialTran_TmpQty a  
                Where  a.ItemCode=@ItemCode and a.Transtamp <= @StockDate  and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear>=@TraceReImportFinStart	--and a.Finyear = @Finyear   
                    and a.FromWarehouseCode='OPB' and a.ReverseEntryFlg='1' --and IsNumeric(a.ToWarehouseCode)='1'

				Union All

				Select '0' as ReverseEntryFlg, -(ICode), DOCType, DOCNo, DOCDate, Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) as TransactionDate, 
                    TransactionItem, TransactionQty, Norms, FromWarehouseCode, FromRackBinCode, ToWarehouseCode, ToRackBinCode, ItemGroupKey, 
                    FromItem, ToItem, Justification, LIFO, FIFO, WA, Userid, Branchid, Compid, Finyear 
				From INV_WIPTRAN_DTL a              
				Where a.TransactionItem=@ItemCode and Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) <= @StockDate                    
					and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear>=@TraceReImportFinStart	--and a.Finyear = @Finyear        
					and not exists
						(
							Select * From INV_MaterialTran_Dtl s
							Where s.DocNo=a.DocNo and s.DocDate=a.DocDate and s.DocType=a.DocType and s.TransactionDate=a.TransactionDate 
								and s.TransactionTime=a.TransactionTime and s.TransactionItem=a.TransactionItem and s.FromwarehouseCode=a.FromWarehouseCode
								and s.FromRackBinCode=a.FromRackBinCode and s.TowarehouseCode=a.TowarehouseCode and s.ToRackBinCode=a.ToRackBinCode 
								and s.ItemGroupKey=a.ItemGroupKey and s.FromItem=a.FromItem and s.ToItem=a.ToItem 
								and s.BranchID=a.BranchID and s.CompID=a.CompID and s.Finyear=a.Finyear
						) 
			)b
			Left Outer Join COM_Trace_MaterialTran_TmpQty d          
				On b.ICode=d.TranID and b.ReverseEntryFlg=d.ReverseEntryFlg and b.BranchID=d.BranchID and b.CompID=d.CompID and b.Finyear=d.Finyear        
                  
			Full Outer Join 
				(
					Select WarehouseCode, '' as RackBinCode, WarehouseNature, BranchID, CompID
					From INV_Warehouse_Master_All c   
		
					Union all

                    Select 'DUM' as WarehouseCode, '' as RackBinCode, 'DUMMY' as WarehouseNature, @BranchID as BranchID, @CompID as CompID

					Union all

					Select Convert(Varchar,LedgerCode), '' as RackBinCode, 'Ledger' as WarehouseNature, @BranchID as BranchID, @CompID as CompID
					From FAS_LedgerMaster_AuthTbl
					Where Left(LrRoute,4) in ('0303', '0206') and CompCode=@CompID+@BranchID              
				)c 
				On c.BranchID = b.BranchID and c.CompID = b.CompID                    
                    
			Where b.TransactionItem=@ItemCode     
				and c.WarehouseCode in (b.FromWarehouseCode, b.ToWarehouseCode)                    
				and b.TransactionDate <= @StockDate                    
				and b.BranchID = @BranchID and b.CompID = @CompID and b.Finyear>=@TraceReImportFinStart	--and b.Finyear = @Finyear 
				and c.WarehouseCode=@WarehouseCode         
			group by b.TransactionItem, c.WarehouseCode, c.WarehouseNature, c.RackBinCode, d.LotID, b.BranchID, b.CompID                    
		) a    
		Where a.CBQty>0    
	)    
    ,Item_CTE
	As
	(
		Select a.ItemCode, a.WarehouseCode, a.WarehouseNature, a.RackBinCode, a.LotID, 
			CONVERT(DECIMAL(15,5),a.CBQty) as CBQty, CONVERT(DECIMAL(15,5),IsNull(Sum(b.CbQty),0)) as RunningTotal, a.BranchID, a.CompID
		From ItemList_CTE a
		Left Outer Join ItemList_CTE b
			On a.Seq>=b.Seq and a.BranchID=b.BranchID and a.CompID=b.CompID
		Group by a.ItemCode, a.WarehouseCode, a.WarehouseNature, a.RackBinCode, a.LotId, a.CbQty, a.BranchID, a.CompID, a.Seq
	)

	INSERT INTO @RetTable  -- Select * from ItemList_CTE     
		Select ItemCode, WarehouseCode, WarehouseNature, RackBinCode, LotID,      
			Case When RunningTotal<@ReqQty Then CBQty Else CBQty-(RunningTotal-@ReqQty) End as CBQty, BranchID, CompID -- , RunningTotal  
		From Item_CTE    
		Where LotID<=(Select Top 1 LotID From Item_CTE Where RunningTotal>=@ReqQty Order By RunningTotal)    
    
	RETURN;    
END 

GO

/****** Object:  UserDefinedFunction [dbo].[fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty]    Script Date: 17/06/2026 11:38:42 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty] (@ItemCode Varchar(30), @WarehouseCode Varchar(6), @ReqQty decimal(15, 5), @StockDate datetime,        
                        @AsonDate datetime, @RptDate datetime, @BranchID varchar(3),  @CompID varchar(3),  @Finyear varchar(20))          
RETURNS @RetTable TABLE                        
 (    
  [ItemCode]   [varchar] (30),                         
  [WarehouseCode]  [varchar] (6),                       
  [WarehouseNature] [varchar] (20),                     
  [RackBinCode]  [varchar] (10),                  
  [LotID]    [bigint],      
  [SubLotID]    [int],                    
  [CBQty]    [float],        
  [Seq]		[int],                
  [BranchID]   [varchar] (3),                        
  [CompID]   [varchar] (3)        
  -- , RunningTotal [float]      
 )                        
AS                          
BEGIN                         
 
 /*
 IF (@ItemCode In ('1U0201100H','2U020531T0','2U020532T0','2U020533T0','2U020534T0','2U020530T0'))
	BEGIN
		INSERT INTO @RetTable 
			Select * From fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty_BleedScrew(@ItemCode, @WarehouseCode, @ReqQty, @StockDate, @AsonDate, @RptDate,
																					@BranchID, @CompID, @Finyear)
	END
ELSE
*/
	BEGIN
	 DECLARE @PrevFinyear Varchar(20)
			Select @PrevFinyear = '04-' + Convert(Varchar,RIGHT(RTRIM(LTRIM( LEFT(@Finyear,CHARINDEX(' ', @Finyear)))),4) - 1)  
									+ ' ' + '03-' + Convert(Varchar,RIGHT(RTRIM(LTRIM(RIGHT(@Finyear,CHARINDEX(' ', REVERSE(@Finyear))))),4) - 1)

	DECLARE @TraceReImportFinStart Varchar(20)
		Select @TraceReImportFinStart='04-2024 03-2025'

	 ;WITH ItemList_CTE        
	 AS                   
	 (        
	  Select * , ROW_NUMBER() OVER(ORDER BY a.LotID, a.SubLotId) as Seq --CONVERT(DECIMAL(15,5),SUM(CbQty) OVER(ORDER BY LotID ROWS UNBOUNDED PRECEDING)) AS RunningTotal        
	  From        
	  (        
	   Select b.TransactionItem as ItemCode, c.WarehouseCode, c.WarehouseNature, c.RackBinCode, IsNull(d.LotID,0) as LotID,  IsNull(d.SubLotID,0) as SubLotID,                     
		CONVERT(DECIMAL(15,5),IsNull(Sum(Case When (b.ToWarehouseCode = c.WarehouseCode and b.ToRackBinCode=c.RackBinCode) Then d.Qty                    
		When (b.FromWarehouseCode = c.WarehouseCode and b.FromRackBinCode=c.RackBinCode) Then -d.Qty          
		Else 0 End), 0)) as CbQty,                      
		b.BranchID, b.CompID     
	   From                              
	   (    
        
					Select '0' as ReverseEntryFlg, ICode, DOCType, DOCNo, DOCDate, Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) as TransactionDate,     
									TransactionItem, TransactionQty, Norms, FromWarehouseCode, FromRackBinCode, ToWarehouseCode, ToRackBinCode, ItemGroupKey,     
									FromItem, ToItem, Justification, LIFO, FIFO, WA, Userid, Branchid, Compid, Finyear     
								From INV_MaterialTran_Dtl a                  
					Where a.TransactionItem=@ItemCode and Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) <= @StockDate                        
					 and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear>=@TraceReImportFinStart  --and a.Finyear in (@PrevFinyear,@Finyear)        
    
					Union All    
    
					Select a.ReverseEntryFlg, a.TranID as ICode, 'DUM' as DOCType, 1 as DOCNo, Convert(Varchar(10),a.Transtamp,121) as DOCDate, a.Transtamp as TransactionDate,     
						a.ItemCode as TransactionItem, a.Qty as TransactionQty, 1 as Norms, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode, 0 as ItemGroupKey,     
						a.ItemCode as FromItem, a.ItemCode as ToItem, 'DUMMY' as Justification, 0 as LIFO, 0 as FIFO, 0 as WA, a.Userid, a.Branchid, a.Compid, a.Finyear    
					From     
						(    
							Select a.ReverseEntryFlg, a.TranID, a.Transtamp, a.ItemCode,  Sum(a.Qty) as Qty, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode,
								a.Userid, a.Branchid, a.Compid, a.Finyear  
							From COM_Trace_MaterialTran_TmpQty a           
							Where a.ItemCode=@ItemCode and a.Transtamp <= @StockDate       
						   and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear>=@TraceReImportFinStart  and IsNumeric(a.FromWarehouseCode)='1' and a.ToWarehouseCode='DUM'        
							Group by a.ReverseEntryFlg, a.TranID, a.Transtamp, a.ItemCode, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode,
								a.Userid, a.Branchid, a.Compid, a.Finyear 

							Union       
    
							Select a.ReverseEntryFlg, a.TranID, a.Transtamp, a.ItemCode,  Sum(a.Qty) as Qty, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode,
								a.Userid, a.Branchid, a.Compid, a.Finyear  
							From COM_Trace_MaterialTran_TmpQty a           
							Where a.ItemCode=@ItemCode and a.Transtamp <= @StockDate                      
								and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear>=@TraceReImportFinStart and a.FromWarehouseCode='DUM'  and IsNumeric(a.ToWarehouseCode)='1'
							Group by a.ReverseEntryFlg, a.TranID, a.Transtamp, a.ItemCode, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode,
								a.Userid, a.Branchid, a.Compid, a.Finyear 
						)a    
    
					Union All    
    
					Select a.ReverseEntryFlg, a.TranID as ICode, 'OPB' as DOCType, 1 as DOCNo, '2024-04-01' as DOCDate, '2024-03-31 23:59:59' as TransactionDate, a.ItemCode as TransactionItem,     
						a.Qty, 1 as Norms, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode, 0 as ItemGroupKey,     
						a.ItemCode as FromItem, a.ItemCode as ToItem, 'Opening Balance' as Justification, 0 as LIFO, 0 as FIFO, 0 as WA, a.Userid, a.Branchid, a.Compid, a.Finyear    
					From COM_Trace_MaterialTran_TmpQty a      
					Where  a.ItemCode=@ItemCode and a.Transtamp <= @StockDate  and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear>=@TraceReImportFinStart       
						and a.FromWarehouseCode='OPB' and a.ReverseEntryFlg='1' --and IsNumeric(a.ToWarehouseCode)='1'    
    
		Union All    
    
		Select '0' as ReverseEntryFlg, -(ICode), DOCType, DOCNo, DOCDate, Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) as TransactionDate,     
						TransactionItem, TransactionQty, Norms, FromWarehouseCode, FromRackBinCode, ToWarehouseCode, ToRackBinCode, ItemGroupKey,     
						FromItem, ToItem, Justification, LIFO, FIFO, WA, Userid, Branchid, Compid, Finyear     
		From INV_WIPTRAN_DTL a                  
		Where a.TransactionItem=@ItemCode and Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) <= @StockDate                        
		 and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear>=@TraceReImportFinStart           
		 and not exists    
		  (    
		   Select * From INV_MaterialTran_Dtl s    
		   Where s.DocNo=a.DocNo and s.DocDate=a.DocDate and s.DocType=a.DocType and s.TransactionDate=a.TransactionDate     
			and s.TransactionTime=a.TransactionTime and s.TransactionItem=a.TransactionItem and s.FromwarehouseCode=a.FromWarehouseCode    
			and s.FromRackBinCode=a.FromRackBinCode and s.TowarehouseCode=a.TowarehouseCode and s.ToRackBinCode=a.ToRackBinCode     
			and s.ItemGroupKey=a.ItemGroupKey and s.FromItem=a.FromItem and s.ToItem=a.ToItem     
			and s.BranchID=a.BranchID and s.CompID=a.CompID and s.Finyear=a.Finyear    
		  ) 
	  

	  		Union All    

			Select a.ReverseEntryFlg, a.TranID as ICode, 'OPB' as DOCType, -3 as DOCNo, Convert(Varchar(10),a.Transtamp,121) as DOCDate, a.Transtamp as TransactionDate, a.ItemCode as TransactionItem,     
				a.Qty, 1 as Norms, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode, 0 as ItemGroupKey,     
				a.ItemCode as FromItem, a.ItemCode as ToItem, 'Missing Stock' as Justification, 0 as LIFO, 0 as FIFO, 0 as WA, a.Userid, a.Branchid, a.Compid, a.Finyear    
			From COM_Trace_MaterialTran_TmpQty a		--TEST20240716_COM_Trace_MaterialTran_TmpQty
			Where  a.ItemCode=@ItemCode and a.Transtamp <= @StockDate  and a.BranchID = @BranchID and a.CompID = @CompID  and a.Finyear>=@TraceReImportFinStart
				and a.FromWarehouseCode='SV' and a.ReverseEntryFlg='1' and a.UserID=-3  

	   )b    
	   Left Outer Join COM_Trace_MaterialTran_TmpQty d              
		On b.ICode=d.TranID and b.ReverseEntryFlg=d.ReverseEntryFlg and b.BranchID=d.BranchID and b.CompID=d.CompID and b.Finyear=d.Finyear            
                      
	   Full Outer Join     
		(    
			Select WarehouseCode, RackBinCode, WarehouseNature, BranchID, CompID		--'' as RackBinCode
			From fn_INV_Warehouse_Master_Get_All('1',@AsonDate,@RptDate,@BranchID,@CompID,@Finyear)c	--INV_Warehouse_Master_All c       
          
      
		 Union all    
    
						Select 'DUM' as WarehouseCode, '' as RackBinCode, 'DUMMY' as WarehouseNature, @BranchID as BranchID, @CompID as CompID    
    
		 Union all    
    
		 Select Convert(Varchar,LedgerCode), '' as RackBinCode, 'Ledger' as WarehouseNature, @BranchID as BranchID, @CompID as CompID    
		 From FAS_LedgerMaster_AuthTbl    
		 Where Left(LrRoute,4) in ('0303', '0206') and CompCode=@CompID+@BranchID                  
		)c     
		On c.BranchID = b.BranchID and c.CompID = b.CompID                        
                        
	   Where b.TransactionItem=@ItemCode         
		and c.WarehouseCode in (b.FromWarehouseCode, b.ToWarehouseCode)                        
		and b.TransactionDate <= @StockDate                        
		and b.BranchID = @BranchID and b.CompID = @CompID and b.Finyear>=@TraceReImportFinStart     
		and c.WarehouseCode=@WarehouseCode             
	   group by b.TransactionItem, c.WarehouseCode, c.WarehouseNature, c.RackBinCode, d.LotID, d.SubLotID, b.BranchID, b.CompID                        
	  ) a        
	  Where a.CBQty>0        
	 )        
		,Item_CTE    
	 As    
	 (    
	  Select a.ItemCode, a.WarehouseCode, a.WarehouseNature, a.RackBinCode, a.LotID, a.SubLotID, 
		a.CBQty, IsNull(Sum(b.CbQty),0) as RunningTotal, a.BranchID, a.CompID, a.Seq    
	  From ItemList_CTE a    
	  Left Outer Join ItemList_CTE b    
	   On a.Seq>=b.Seq and a.BranchID=b.BranchID and a.CompID=b.CompID    
	  Group by a.ItemCode, a.WarehouseCode, a.WarehouseNature, a.RackBinCode, a.LotId, a.SubLotID, a.CbQty, a.BranchID, a.CompID, a.Seq    
	 )    
    
	 INSERT INTO @RetTable  -- Select * from ItemList_CTE         
	  Select ItemCode, WarehouseCode, WarehouseNature, RackBinCode, LotID, SubLotID,        
	   Case When RunningTotal<@ReqQty Then CBQty Else CBQty-(RunningTotal-@ReqQty) End as CBQty, Seq,  BranchID, CompID  -- , RunningTotal      
	  From Item_CTE        
	  Where LotID<=(Select Top 1 LotID From Item_CTE Where RunningTotal>=@ReqQty Order By RunningTotal)        
	END
	
 RETURN;        
END     
GO

/****** Object:  UserDefinedFunction [dbo].[fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty_BleedScrew]    Script Date: 17/06/2026 11:38:42 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty_BleedScrew] (@ItemCode Varchar(30), @WarehouseCode Varchar(6), @ReqQty decimal(15, 5), @StockDate datetime, @AsonDate datetime, @RptDate datetime, @BranchID varchar(3),  @CompID varchar(3),  @Finyear varchar(20))          
RETURNS @RetTable TABLE                        
 (    
  [ItemCode]   [varchar] (30),                         
  [WarehouseCode]  [varchar] (6),                       
  [WarehouseNature] [varchar] (20),                     
  [RackBinCode]  [varchar] (10),                  
  [LotID]    [bigint],      
  [SubLotID]    [int],                    
  [CBQty]    [float],        
  [Seq]		[int],                
  [BranchID]   [varchar] (3),                        
  [CompID]   [varchar] (3)        
  -- , RunningTotal [float]      
 )                        
AS                          
BEGIN                         

 
 ;WITH ItemList_CTE        
 AS                   
(   
	Select LotID, 0 as SubLotID, ItemCode, CBQty, WarehouseCode, '' as RackBinCode, -ROW_NUMBER() OVER(ORDER BY a.LotID desc) as Seq
	From dbo.fn_INV_AsOnDate_Stock_WithLotID(@StockDate,@BranchID,@CompID,@Finyear) a
	Where a.ItemCode=@ItemCode and a.LotId is not null and CBQty > 0  and WarehouseCode=@WarehouseCode  
)

    ,Item_CTE    
 As    
 (    
  Select a.ItemCode, a.WarehouseCode, '' WarehouseNature, a.RackBinCode, a.LotID, a.SubLotID, 
	a.CBQty, IsNull(Sum(b.CbQty),0) as RunningTotal, a.Seq    
  From ItemList_CTE a    
  Left Outer Join ItemList_CTE b    
   On a.Seq>=b.Seq  
  Group by a.ItemCode, a.WarehouseCode,  a.RackBinCode, a.LotId, a.SubLotID, a.CbQty, a.Seq    
 )    
     

INSERT INTO @RetTable   
  Select ItemCode, WarehouseCode, WarehouseNature, RackBinCode, LotID, SubLotID,        
   Case When RunningTotal<@ReqQty Then CBQty Else CBQty-(RunningTotal-@ReqQty) End as CBQty, Seq, @BranchID as BranchID, @CompID as CompID  -- , RunningTotal      
  From Item_CTE        
  Where LotID<=(Select Top 1 LotID From Item_CTE Where RunningTotal>=@ReqQty Order By RunningTotal)        
        
 RETURN;        
END     
GO

/****** Object:  UserDefinedFunction [dbo].[fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty_Trial]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty_Trial] (@ItemCode Varchar(30), @WarehouseCode Varchar(6), @ReqQty decimal(15, 5), @StockDate datetime, @AsonDate datetime, @RptDate datetime, @BranchID varchar(3),  @CompID varchar(3),  @Finyear varchar(20))          
RETURNS @RetTable TABLE                        
 (    
  [ItemCode]   [varchar] (30),                         
  [WarehouseCode]  [varchar] (6),                       
  [WarehouseNature] [varchar] (20),                     
  [RackBinCode]  [varchar] (10),                  
  [LotID]    [bigint],      
  [SubLotID]    [int],                    
  [CBQty]    [float],        
  [Seq]		[int],                
  [BranchID]   [varchar] (3),                        
  [CompID]   [varchar] (3)        
  -- , RunningTotal [float]      
 )                        
AS                          
BEGIN                         
 
 /*
 IF (@ItemCode In ('1U0201100H','2U020531T0','2U020532T0','2U020533T0','2U020534T0','2U020530T0'))
	BEGIN
		INSERT INTO @RetTable 
			Select * From fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty_BleedScrew(@ItemCode, @WarehouseCode, @ReqQty, @StockDate, @AsonDate, @RptDate,
																					@BranchID, @CompID, @Finyear)
	END
ELSE
*/
	BEGIN
	 DECLARE @PrevFinyear Varchar(20)
			Select @PrevFinyear = '04-' + Convert(Varchar,RIGHT(RTRIM(LTRIM( LEFT(@Finyear,CHARINDEX(' ', @Finyear)))),4) - 1)  
									+ ' ' + '03-' + Convert(Varchar,RIGHT(RTRIM(LTRIM(RIGHT(@Finyear,CHARINDEX(' ', REVERSE(@Finyear))))),4) - 1)

	DECLARE @TraceReImportFinStart Varchar(20)
		Select @TraceReImportFinStart='04-2024 03-2025'

	Declare @TblItem Table (ItemCode varchar(30), WarehouseCode varchar(6), WarehouseNature varchar(20), RackBinCode varchar(10), LotID int, SubLotID int, CBQty Float, Seq int)

	Insert into @TblItem        
	  Select ItemCode, WarehouseCode, WarehouseNature, RackBinCode, LotID, SubLotID, CBQty, ROW_NUMBER() OVER(ORDER BY a.LotID, a.SubLotId) as Seq --CONVERT(DECIMAL(15,5),SUM(CbQty) OVER(ORDER BY LotID ROWS UNBOUNDED PRECEDING)) AS RunningTotal        
	  From        
	  (        
		   Select b.TransactionItem as ItemCode, c.WarehouseCode, c.WarehouseNature, c.RackBinCode, IsNull(d.LotID,0) as LotID,  IsNull(d.SubLotID,0) as SubLotID,                     
				CONVERT(DECIMAL(15,5),IsNull(Sum(Case When (b.ToWarehouseCode = c.WarehouseCode and b.ToRackBinCode=c.RackBinCode) Then d.Qty                    
				When (b.FromWarehouseCode = c.WarehouseCode and b.FromRackBinCode=c.RackBinCode) Then -d.Qty          
				Else 0 End), 0)) as CbQty,                      
				b.BranchID, b.CompID     
		   From                              
		   (    
        
					Select '0' as ReverseEntryFlg, ICode, DOCType, DOCNo, DOCDate, Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) as TransactionDate,     
						TransactionItem, TransactionQty, Norms, FromWarehouseCode, FromRackBinCode, ToWarehouseCode, ToRackBinCode, ItemGroupKey,     
						FromItem, ToItem, Justification, LIFO, FIFO, WA, Userid, Branchid, Compid, Finyear     
					From INV_MaterialTran_Dtl_LotTrial a                  
					Where a.TransactionItem=@ItemCode and Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) <= @StockDate                        
					 and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear>=@TraceReImportFinStart  --and a.Finyear in (@PrevFinyear,@Finyear)        
    
					Union All    
    
					Select a.ReverseEntryFlg, a.TranID as ICode, 'DUM' as DOCType, 1 as DOCNo, Convert(Varchar(10),a.Transtamp,121) as DOCDate, a.Transtamp as TransactionDate,     
						a.ItemCode as TransactionItem, a.Qty as TransactionQty, 1 as Norms, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode, 0 as ItemGroupKey,     
						a.ItemCode as FromItem, a.ItemCode as ToItem, 'DUMMY' as Justification, 0 as LIFO, 0 as FIFO, 0 as WA, a.Userid, a.Branchid, a.Compid, a.Finyear    
					From     
						(    
							Select a.ReverseEntryFlg, a.TranID, a.Transtamp, a.ItemCode,  Sum(a.Qty) as Qty, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode,
								a.Userid, a.Branchid, a.Compid, a.Finyear  
							From COM_Trace_MaterialTran_TmpQty_Trial a           
							Where a.ItemCode=@ItemCode and a.Transtamp <= @StockDate       
						   and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear>=@TraceReImportFinStart  and IsNumeric(a.FromWarehouseCode)='1' and a.ToWarehouseCode='DUM'        
							Group by a.ReverseEntryFlg, a.TranID, a.Transtamp, a.ItemCode, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode,
								a.Userid, a.Branchid, a.Compid, a.Finyear 

							Union       
    
							Select a.ReverseEntryFlg, a.TranID, a.Transtamp, a.ItemCode,  Sum(a.Qty) as Qty, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode,
								a.Userid, a.Branchid, a.Compid, a.Finyear  
							From COM_Trace_MaterialTran_TmpQty_Trial a           
							Where a.ItemCode=@ItemCode and a.Transtamp <= @StockDate                      
								and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear>=@TraceReImportFinStart and a.FromWarehouseCode='DUM'  and IsNumeric(a.ToWarehouseCode)='1'
							Group by a.ReverseEntryFlg, a.TranID, a.Transtamp, a.ItemCode, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode,
								a.Userid, a.Branchid, a.Compid, a.Finyear 
						)a    
    
					Union All    
    
					Select a.ReverseEntryFlg, a.TranID as ICode, 'OPB' as DOCType, 1 as DOCNo, '2025-04-01' as DOCDate, '2025-03-31 23:59:59' as TransactionDate, a.ItemCode as TransactionItem,     
						a.Qty, 1 as Norms, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode, 0 as ItemGroupKey,     
						a.ItemCode as FromItem, a.ItemCode as ToItem, 'Opening Balance' as Justification, 0 as LIFO, 0 as FIFO, 0 as WA, a.Userid, a.Branchid, a.Compid, a.Finyear    
					From COM_Trace_MaterialTran_TmpQty_Trial a      
					Where  a.ItemCode=@ItemCode and a.Transtamp <= @StockDate  and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear>=@TraceReImportFinStart       
						and a.FromWarehouseCode='OPB' and a.ReverseEntryFlg='1' --and IsNumeric(a.ToWarehouseCode)='1'    
    
					Union All    
    
					Select '0' as ReverseEntryFlg, -(ICode), DOCType, DOCNo, DOCDate, Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) as TransactionDate,     
									TransactionItem, TransactionQty, Norms, FromWarehouseCode, FromRackBinCode, ToWarehouseCode, ToRackBinCode, ItemGroupKey,     
									FromItem, ToItem, Justification, LIFO, FIFO, WA, Userid, Branchid, Compid, Finyear     
					From INV_WIPTRAN_DTL_LotTrial a                  
					Where a.TransactionItem=@ItemCode and Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) <= @StockDate                        
					 and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear>=@TraceReImportFinStart           
					 and not exists    
					  (    
					   Select * From INV_MaterialTran_Dtl_LotTrial s    
					   Where s.DocNo=a.DocNo and s.DocDate=a.DocDate and s.DocType=a.DocType and s.TransactionDate=a.TransactionDate     
						and s.TransactionTime=a.TransactionTime and s.TransactionItem=a.TransactionItem and s.FromwarehouseCode=a.FromWarehouseCode    
						and s.FromRackBinCode=a.FromRackBinCode and s.TowarehouseCode=a.TowarehouseCode and s.ToRackBinCode=a.ToRackBinCode     
						and s.ItemGroupKey=a.ItemGroupKey and s.FromItem=a.FromItem and s.ToItem=a.ToItem     
						and s.BranchID=a.BranchID and s.CompID=a.CompID and s.Finyear=a.Finyear    
					  ) 
	  

	  				Union All    

					Select a.ReverseEntryFlg, a.TranID as ICode, 'OPB' as DOCType, -3 as DOCNo, Convert(Varchar(10),a.Transtamp,121) as DOCDate, a.Transtamp as TransactionDate, a.ItemCode as TransactionItem,     
						a.Qty, 1 as Norms, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode, 0 as ItemGroupKey,     
						a.ItemCode as FromItem, a.ItemCode as ToItem, 'Missing Stock' as Justification, 0 as LIFO, 0 as FIFO, 0 as WA, a.Userid, a.Branchid, a.Compid, a.Finyear    
					From COM_Trace_MaterialTran_TmpQty_Trial a		--TEST20240716_COM_Trace_MaterialTran_TmpQty
					Where  a.ItemCode=@ItemCode and a.Transtamp <= @StockDate  and a.BranchID = @BranchID and a.CompID = @CompID  and a.Finyear>=@TraceReImportFinStart
						and a.FromWarehouseCode='SV' and a.ReverseEntryFlg='1' and a.UserID=-3  

		)b    
	   Left Outer Join COM_Trace_MaterialTran_TmpQty_Trial d              
		On b.ICode=d.TranID and b.ReverseEntryFlg=d.ReverseEntryFlg and b.BranchID=d.BranchID and b.CompID=d.CompID and b.Finyear=d.Finyear            
                      
	   Full Outer Join     
		(    
			Select WarehouseCode, RackBinCode, WarehouseNature, BranchID, CompID		--'' as RackBinCode
			From fn_INV_Warehouse_Master_Get_All('1',@AsonDate,@RptDate,@BranchID,@CompID,@Finyear)c	--INV_Warehouse_Master_All c       
          
      
			Union all    
    
			Select 'DUM' as WarehouseCode, '' as RackBinCode, 'DUMMY' as WarehouseNature, @BranchID as BranchID, @CompID as CompID    
    
			 Union all    
    
			 Select Convert(Varchar,LedgerCode), '' as RackBinCode, 'Ledger' as WarehouseNature, @BranchID as BranchID, @CompID as CompID    
			 From FAS_LedgerMaster_AuthTbl    
			 Where Left(LrRoute,4) in ('0303', '0206') and CompCode=@CompID+@BranchID                  
		)c     
		On c.BranchID = b.BranchID and c.CompID = b.CompID                        
                        
	   Where b.TransactionItem=@ItemCode         
		and c.WarehouseCode in (b.FromWarehouseCode, b.ToWarehouseCode)                        
		and b.TransactionDate <= @StockDate                        
		and b.BranchID = @BranchID and b.CompID = @CompID and b.Finyear>=@TraceReImportFinStart     
		and c.WarehouseCode=@WarehouseCode             
	   group by b.TransactionItem, c.WarehouseCode, c.WarehouseNature, c.RackBinCode, d.LotID, d.SubLotID, b.BranchID, b.CompID                        
	  ) a        
	  Where a.CBQty>0        
	        

	Declare @TblTmp Table (ItemCode varchar(30), WarehouseCode varchar(6), WarehouseNature varchar(20), RackBinCode varchar(10), LotID bigint, SubLotID bigint, 
								CBQty Float, RunningTotal Float, Seq int)   
	Insert into @TblTmp
		Select a.ItemCode, a.WarehouseCode, a.WarehouseNature, a.RackBinCode, a.LotID, a.SubLotID, 
			a.CBQty, IsNull(Sum(b.CbQty),0) as RunningTotal, a.Seq    
		From @TblItem a    
		Left Outer Join @TblItem b    
			On a.Seq>=b.Seq   
		Group by a.ItemCode, a.WarehouseCode, a.WarehouseNature, a.RackBinCode, a.LotId, a.SubLotID, a.CbQty, a.Seq    
	    
	 IF Exists (Select Top 1 LotID From @TblTmp Where RunningTotal>=@ReqQty Order By RunningTotal)
		BEGIN
			INSERT INTO @RetTable  -- Select * from ItemList_CTE         
				Select ItemCode, WarehouseCode, WarehouseNature, RackBinCode, LotID, SubLotID,        
					Case When RunningTotal<@ReqQty Then CBQty Else CBQty-(RunningTotal-@ReqQty) End as CBQty, Seq,  @BranchID as BranchID, @CompID as CompID        
				From @TblTmp        
				Where LotID<=(Select Top 1 LotID From @TblTmp Where RunningTotal>=@ReqQty Order By RunningTotal)  
		END
	ELSE
		BEGIN
			INSERT INTO @RetTable     
				Select ItemCode, WarehouseCode, WarehouseNature, RackBinCode, LotID, SubLotID,        
					Case When RunningTotal<@ReqQty Then CBQty Else CBQty-(RunningTotal-@ReqQty) End as CBQty, Seq, @BranchID as BranchID, @CompID as CompID    
				From @TblTmp 
		END
	END
	
 RETURN;        
END     
GO

/****** Object:  UserDefinedFunction [dbo].[fn_COM_Trace_RefTranDocId]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_COM_Trace_RefTranDocId] (@DocType Varchar(3), @DocNo int, @DocDate datetime, @ItemCode Varchar(30), @FromWarehouseCode Varchar(6), @ToWarehouseCode Varchar(6), @ReqQty decimal(15, 5), @StockDate datetime, @AsonDate datetime, @RptDate datetime, @BranchID varchar(3),  @CompID varchar(3),  @Finyear varchar(20))        
RETURNS @RetTable TABLE                      
(
    [RefICode]				[int],
	[RefTranDocId]			[bigint],  
	[RefLotID]				[bigint], 
	[RefDocType]			[varchar] (3),
	[RefDocNo]				[int],
	[RefDocDate]			[datetime],
	[RefItemCode]			[varchar](30),  
	[CBQty]					[float],
	[RefNorms]				[float],
	[IsRefDocAvailable]		[bit],
    [BranchID]				[varchar] (3),                      
    [CompID]				[varchar] (3)      
)                      
AS                        
BEGIN 

	Declare @PrevDocType Varchar(3), @PrevDocNo int, @PrevDocDate datetime, @PrevItemCode Varchar(30), @PrevNorms float, @PrevToWarehouseCode Varchar(6);
	Declare @PrevTranDocId bigint, @PrevLotId bigint, @IsRefDocAvailable bit;

	Select @PrevNorms=1, @PrevToWarehouseCode=@FromWarehouseCode, @IsRefDocAvailable='1'

	IF Exists (Select * From COM_DocumentType_Master
				Where PertainingTo = 'R' and ModuleName='REC' and DocumentType=@DocType and @ToWarehouseCode='UI' and BranchID=@BranchID and CompID=@CompID )	/* RR - Receipt Entry*/
		BEGIN
			Select @PrevDocType=a.DocType, @PrevDocNo=a.DocNo, @PrevDocDate=a.DocDate, @PrevItemCode=a.TransactionItem,
				@PrevNorms=Case When c.InwardType in ('D','E') Then 1 Else a.Norms End	--, a.ToWarehouseCode
			From INV_MaterialTran_Dtl_LotTrial a  
			Outer Apply
				(
					Select s.ReceiptEntryType, s.ReceiptEntryNo, s.ReceiptEntryDate, s2.VendorCode, s2.InwardType 
					From Rec_ReceiptEntry_Dtl s
					Left Outer Join Rec_ReceiptEntry_Hdr s2	
						On s.ReceiptEntryNo=s2.ReceiptEntryNo and s.ReceiptEntryDate=s2.ReceiptEntryDate and s.ReceiptEntryType=s2.ReceiptEntryType and s.BranchID=s2.BranchID and s.CompID=s2.CompID 
					Where s.RefNo=a.DocNo and s.RefDate=a.DocDate and s.RefType=a.DocType and s.BranchID=a.BranchID and s.CompID=a.CompID                            
						and s.ReceiptEntryType=@DocType and s.ReceiptEntryNo=@DocNo and s.ReceiptEntryDate=@DocDate                            
						and s.ItemCode= Case When a.ToItem ='' Then a.TransactionItem Else Case When s2.InwardType in ('D','E') Then a.TransactionItem Else a.ToItem End End
						and Case When a.ToItem ='' Then a.TransactionItem Else Case When s2.InwardType in ('D','E') Then a.TransactionItem Else a.ToItem End End = @ItemCode
						and s.BranchID=a.BranchID and s.CompID=a.CompID
				)c
				Where c.ReceiptEntryType is Not Null and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear 
										
		END

	Else IF Exists (Select * From COM_DocumentType_Master
						Where PertainingTo = 'R' and ModuleName='REC' and DocumentType=@DocType and @FromWarehouseCode='UI' and BranchID=@BranchID and CompID=@CompID)	/* RR - Acceptance Update */
		BEGIN
			Select @PrevDocType=@DocType, @PrevDocNo=@DocNo, @PrevDocDate=@DocDate, @PrevItemCode=@Itemcode
		END
	ELSE
		BEGIN
			Select @IsRefDocAvailable = '0'
		END

	IF @IsRefDocAvailable='1'
		BEGIN
			Insert into @RetTable
				Select a.ICode as PrevICode, a.TranDocId as PrevTranDocId, b.LotID as RefLotID, a.DocType as PrevDocType, a.DocNo as PrevDocNo, a.DocDate as PrevDocDate,
					a.TransactionItem as PrevItemCode, IsNull(b.CBQty,0) as CBQty, @PrevNorms as PrevNorms, @IsRefDocAvailable as IsRefDocAvailable, a.BranchID, a.CompID
				From INV_MaterialTran_Dtl_LotTrial a
				Outer Apply
					(
						Select o.ItemCode, o.TranDocID, o.LotID, o.CBQty
						From fn_COM_Trace_AsOnDate_Stock_ItemWHS_DocTran_TranDocID(a.TransactionItem, a.TranDocId, @PrevToWarehouseCode, @ReqQty, @AsOnDate, @AsOnDate, @RptDate, @BranchID, @CompID, @Finyear)o
					)b	
				Where a.DocType=@PrevDocType and a.DocNo=@PrevDocNo and a.DocDate=@PrevDocDate and a.TransactionItem=@PrevItemCode and a.ToWarehouseCode=@PrevToWarehouseCode 
					and a.BranchID=@BranchID and a.CompID=@CompID
			
		END
	ELSE
		BEGIN
			Insert into @RetTable 
				Select 0 as ICode, TranDocID,  LotID, '', 0, Null, ItemCode, CBQty, @PrevNorms as Norms, @IsRefDocAvailable as IsRefDocAvailable, @BranchID as BranchID, @CompID as CompID
				From fn_COM_Trace_AsOnDate_Stock_ItemWHS_DocTran(@ItemCode, @PrevToWarehouseCode, @ReqQty, @AsOnDate, @AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) v                

		END

    RETURN;      
END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_Customer_ItemGroupKey]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE Function [dbo].[fn_Customer_ItemGroupKey](@ToItemCode varchar(20),@Branchid varchar(3),@compid varchar(3))

Returns @RetTbl Table
		(ItemGroupKey int,
		FromCode varchar(8000),
		ToCode varchar(20),
		Branchid varchar(3),
		Compid varchar(3)
		)
as
begin

	Declare @ItemGroupKey int
	Declare	@ToCode varchar(20)
	Declare	@FromCode varchar(20)
	Declare	@strFromCode varchar(20)
	
	
		if @ToItemCode<>'ALL' 	
		    Begin
			Declare curRec cursor for
				select distinct  ItemGroupKey,SentITemCode from SAL_Jobwork_ItemMaster where  SentITemCode=@ToItemCode and 
				Branchid=@Branchid and Compid=@compid
				group by ItemGroupKEy,SentITemCode order by ItemGroupKey
		    end
		else
		   Begin
			Declare curRec cursor for
				select distinct  ItemGroupKey,SentITemCode from SAL_Jobwork_ItemMaster where 
				Branchid=@Branchid and Compid=@compid
				group by ItemGroupKEy,SentITemCode order by ItemGroupKey
		  end

	open curRec
	
	Fetch next from curRec into @ItemGroupKey,@ToCode
	
	while @@Fetch_Status=0
		begin
			Declare curFrom cursor for

				select distinct ReceivedItemCode from SAL_Jobwork_ItemMaster where ItemGroupKey=@ItemGroupKey
				order by ReceivedItemCode

			open curFrom

				Fetch next from curFrom into @FromCode
				select @strFromCode=''
				while @@Fetch_Status=0
					begin
						select @strFromCode=@strFromCode+@FromCode
						Fetch next from curFrom into @FromCode
					end
				close curFrom
				Deallocate curFrom
				
			insert into @RetTbl (ItemGroupKey,FromCode,ToCode,Branchid,Compid)
									values (@ItemGroupKey,@strFromCode,@ToCode,@Branchid,@compid)

			Fetch next from curRec into @ItemGroupKey,@ToCode
		end
		
    Close curRec
    Deallocate curRec
 
	return
end
GO

/****** Object:  UserDefinedFunction [dbo].[fn_DD_KPI_ProductionPlanItem_Stock_BasedOnNorms]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_DD_KPI_ProductionPlanItem_Stock_BasedOnNorms] (@FromDate datetime,  @ToDate datetime, @AsonDate datetime, @RptDate datetime, @BranchID varchar(3),  @CompID varchar(3),  @Finyear varchar(20))                  
RETURNS @RetTable TABLE                
 ([ItemCode]     [varchar] (30),  
  [WarehouseCode]    [varchar] (6),  
  [OBQtyBasedOnNorms]   [float]                       
 )                
AS                  
BEGIN  
  
 Declare @TblPlanItemWithStage TABLE               
    (              
            ItemCode  [varchar] (30),              
            StageCode       [varchar] (30),         
            Norms   [float],              
            OperationCode [int],        
            OperationSeq [int]        
         
    )        
                
 Insert into @TblPlanItemWithStage        
  Select a.ItemCode, c.StageCode, c.Norms, c.OperationCode , c.OperationSequence                
  From fn_PPC_ProductionPlan_Dtl_V2(@AsonDate, @RptDate, @BranchID, @CompID, @Finyear) a  
  Left Outer Join fn_BOM_Process(@BranchID, @CompID) b  
   On a.ItemCode=b.StageCode   
  Left Outer Join fn_BOM_Process(@BranchID, @CompID) c  
   On b.ParentCode=c.ParentCode             
  Where a.PlanFor=2 and PlanPeriod Between Convert(Varchar(10),@FromDate,121) and Convert(Varchar(10),@ToDate,121) --and a.ItemCode='20520110B0'  
   
 Declare @TblStockItem TABLE         
 (              
            ItemCode  [varchar] (30),              
            WarehouseCode   [varchar] (6),         
            OBQty   [float]              
    )       
  
 Insert into @TblStockItem  
  Select a.ItemCode, a.WarehouseCode, StockOBQty as OBQty  
  From  
  (  
   Select m.ItemCode, m.WarehouseCode,        
    Sum(Case When m.TransactionDate < @FromDate Then CbQty Else 0 End) as StockOBQty,  
    Sum(Case When m.TransactionDate >= @FromDate And CBQty >=0 Then CbQty Else 0 End) as StockReceiptQty,        
    Sum(Case When m.TransactionDate >= @FromDate And CBQty <0 Then -CbQty Else 0 End) as StockIssueQty           
   From        
    (             
     Select b.TransactionDate, b.TransactionItem as ItemCode,           
      Case When (b.ToWarehouseCode = c.WarehouseCode) Then b.ToWarehouseCode Else b.FromWarehouseCode End as WarehouseCode,     
      IsNull((Case When b.ToWarehouseCode = c.WarehouseCode Then b.TransactionQty   
              
          When (b.FromWarehouseCode = c.WarehouseCode) Then -b.TransactionQty            
          Else 0 End), 0) as CbQty  
                                   
     From Inv_MaterialTran_Dtl b            
     Left Outer Join dbo.fn_INV_Warehouse_Master_Get_All('1', @AsonDate,@RptDate, @BranchID, @CompID,  @Finyear) c             
      On c.WarehouseCode in (b.FromWarehouseCode, b.ToWarehouseCode)  and b.BranchID=c.BranchID and b.CompID=c.CompID            
     Where c.WarehouseCode in ('WIP', 'RMS')  and b.TransactionDate <= @ToDate    
      and b.BranchID = @BranchID and b.CompID = @CompID  and b.Finyear = @Finyear   
      and  Exists  
       (  
        Select * From @TblPlanItemWithStage s  
        Where s.StageCode=(b.TransactionItem)  
       )  
    ) m              
   group by m.ItemCode,  m.WarehouseCode  
  )a  
  Where StockOBQty>0  
  
  
 Insert @RetTable  
  Select a.RawMaterialCode, b.WarehouseCode, Sum(b.OBQty* Case When a.ItemCode=a.RawMaterialCode Then 1 Else a.Norms End) as OBQtyBasedOnNorms  
  From  
  (  
   Select distinct a.StageCode as ItemCode, c.StageCode as RawMaterialCode, c.Norms  
   From @TblPlanItemWithStage a  
   Left Outer Join @TblPlanItemWithStage c  
     On a.ItemCode=c.ItemCode and c.OperationCode=0 and c.OperationSeq=0   
  )a  
  Left Outer Join @TblStockItem b --fn_INV_AsOnDate_Stock_WHS('WIP', @FromDate, @AsonDate, @RptDate, @BranchID, @CompID, @Finyear)b  
   On a.ItemCode=b.ItemCode   
  Where b.WarehouseCode='WIP'  
  Group by a.RawMaterialCode, b.WarehouseCode   
   
 Insert @RetTable  
  Select a.ItemCode, a.WarehouseCode, a.OBQty  
  From @TblStockItem a  
  Where a.WarehouseCode='RMS'  
  
 --Insert @RetTable  
 -- Select a.ItemCode, 'RMS' as WarehouseCode, a.CBQty as OBQty  
 -- From fn_INV_AsOnDate_Stock_WHS('RMS', @FromDate, @AsonDate, @RptDate, @BranchID, @CompID, @Finyear)a  
 -- Where Exists  
 --  (  
 --   Select * From @TblPlanItemWithStage s  
 --   Where s.StageCode=a.ItemCode  
 --  )  
         
 RETURN;                 
                
END  
  

GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_AbstractSalesRegister]    Script Date: 17/06/2026 11:38:43 ******/
