/****** Object:  UserDefinedFunction [dbo].[fn_FAS_AllOpBalance]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_AllOpBalance] (@OBDate datetime, @isRealisedAmtOnly bit, @isMakePLEntryZero bit, @CmCode varchar(12))      
RETURNS @Ledger TABLE      
(      
 LedgerCode int,      
 LedgerName varchar(50),      
 Alias varchar(50),      
 LrRoute varchar(42),      
 isBillwise bit,      
 CreditDays int,      
 OpBalance money,      
 isCostCentreApplicable bit,      
 --isActive bit,      
 CompCode varchar(12)      
)      
      
AS      
BEGIN      
      
 Insert into @Ledger      
  Select LedgerCode, LedgerName, Alias, LrRoute, isBillwise, Creditdays,      
   OpBalance, isCostCentreApplicable, CompCode      
  From      
   (      
    Select a.LedgerCode, a.LedgerName, a.Alias, a.LrRoute, a.isBillwise, a.Creditdays,      
     Case When a.LrRoute like '0205%' Then isNull(c.OpeningStock, 0)      
      Else a.OpBalance+isNull(Sum(b.DrAmt-b.CrAmt), 0) End as OpBalance,      
     a.isCostCentreApplicable, a.CompCode      
    From FAS_LedgerMaster_AuthTbl a      
    Left Outer Join FAS_VoucherTranSub b      
     On a.LedgerCode=b.LrCode and a.CompCode=b.CompCode and b.DocDate<@OBDate      
    Left Outer Join dbo.fn_FAS_StockValue(@OBDate, @OBDate, @CmCode) c      
     On a.LedgerCode=c.LedgerCode      
    Where a.CompCode=@CmCode --and a.EffStatus='AA'      
    Group By a.LedgerCode, a.LedgerName, a.Alias, a.LrRoute, a.isBillwise, a.Creditdays,      
     a.OpBalance, c.OpeningStock, a.isCostCentreApplicable, a.CompCode, a.EffStatus      
   ) x      
      
 If @isMakePLEntryZero='1'      
 BEGIN      
  /* Profit & Loss A/c Ledger Update */      
  Declare @FinStart datetime, @PrEnd datetime, @Amt money      
     
	/* Get Minimum Date */
  Select @FinStart=Min(DocDate) 
  From FAS_VoucherTranMast 
  Where DocDate<@OBDate and CompCode=@CmCode      
      
  SET @FinStart=isNull(@FinStart, @OBDate)   
  
  /* Set -1 Date Add */
  SET @PrEnd=DateAdd(day, -1, @OBDate)   
            
  If @FinStart < @OBDate      
  BEGIN      
   If Month(@FinStart) <= 3      
    SET @FinStart=Convert(datetime, Convert(varchar, Year(@FinStart)-1)+'-04-01', 120)      
   Else      
    SET @FinStart=Convert(datetime, Convert(varchar, Year(@FinStart))+'-04-01', 120)      
      
   SET @Amt=dbo.fn_FAS_Profit_Loss_Period(@FinStart, @PrEnd, @CmCode)      
      
	/* Update OpeningBalance + Amount */
   Update @Ledger Set OpBalance=OpBalance+@Amt      
   From @Ledger a      
   Where LedgerCode=2      
  END      
      
  /* Update Opening Balance */
  Update @Ledger Set OpBalance=0      
  From @Ledger a      
  Left Outer Join FAS_GroupMaster d      
   On a.LrRoute=d.GrRoute+d.GrWidth and a.CompCode=d.CompCode      
  Where d.Master in ('02', '03')      
 END      
      
 RETURN;      
END 
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_AllOpBalance_Test]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_AllOpBalance_Test] (@OBDate datetime, @isRealisedAmtOnly bit, @isMakePLEntryZero bit, @CmCode varchar(12))  

RETURNS @Ledger TABLE
	(LedgerCode	int,
	LedgerName	varchar(50),
	Alias		varchar(50),
	LrRoute		varchar(42),
	isBillwise	bit,	
	CreditDays 	int,
	OpBalance	money,
	isCostCentreApplicable	bit,
	isActive 	bit,
	CompCode	varchar(12))
		
AS  

BEGIN 

	Insert into @Ledger		

		Select a.LedgerCode, a.LedgerName, a.Alias, a.LrRoute, a.isBillwise, a.Creditdays, 
			Case When LrRoute like '0205%' Then isNull(c.OpeningStock, 0)  Else a.OpBalance+isNull(b.TranAmt, 0) End as OpBalance,
			a.isCostCentreApplicable, a.isActive, a.CompCode
		from FAS_LedgerMaster a Left Outer Join (Select a.LrCode, Sum(Case When @isRealisedAmtOnly='1' and b.DocNo is Not Null and b.BankDate is Null Then 0 Else DrAmt-CrAmt End) as TranAmt 
							from FAS_VoucherTranSub a Left Outer Join FAS_VoucherTranPay b
							On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode
							Where a.DocDate < @OBDate and a.CompCode=@CmCode
							Group by a.LrCode) b
		On a.LedgerCode=b.LrCode
		Left Outer Join dbo.fn_FAS_StockValue(@OBDate, @OBDate, @CmCode) c On a.LedgerCode=c.LedgerCode		
		Where a.CompCode=@CmCode

	If @isMakePLEntryZero='1'
		BEGIN
			Update @Ledger Set OpBalance=0
			From @Ledger a 
			Left Outer Join FAS_GroupMaster d On a.LrRoute=d.GrRoute+d.GrWidth and a.CompCode=d.CompCode
			Where d.Master in ('02', '03')

			Declare @FinStart datetime, @PrEnd datetime, @Amt money
			SET @PrEnd=DateAdd(day, -1, @OBDate)

			Select @FinStart=Min(DocDate) From FAS_VoucherTranMast Where DocDate<@OBDate and CompCode=@CmCode

			SET @FinStart=isNull(@FinStart, @OBDate)


			If  @FinStart >= @OBDate
				SET @Amt=0
			Else
				BEGIN
					If Month(@FinStart) <= 3 
						SET @FinStart=Convert(datetime, Convert(varchar, Year(@FinStart)-1)+'-04-01', 120)
					Else
						SET @FinStart=Convert(datetime, Convert(varchar, Year(@FinStart))+'-04-01', 120)

					SET @Amt=dbo.fn_FAS_Profit_Loss_Period(@FinStart, @PrEnd, @CmCode)
				END

			Update  @Ledger Set OpBalance=OpBalance+@Amt
			From @Ledger a 
			Where LedgerCode=2
			
		END
	Return

END

GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_AllPendingBills]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [dbo].[fn_FAS_AllPendingBills] (@RptDate datetime, @isRealisedAmtOnly bit, @CmCode varchar(12))  

RETURNS @Bills TABLE
	(DocType	varchar(3),
	DocNo		int,
	DocDate	datetime,
	VTSNo		int,
	VrRoute		varchar(42),
	LrCode		int,
	BillIndex		int,
	Type		varchar(8),
	RefNo		varchar(20),
	RefDate	datetime,
	Amount		money,
	CreditDays	int,
	CompCode	varchar(12))
		
AS  

BEGIN 

	Insert into @Bills	

		Select 'OPB', 0, null, 1, 'OpBal', LrCode, 0, 'New Ref', RefNo, RefDate,  Amount, CreditDays, @CmCode
		from 
			(Select LrCode, RefNo, RefDate, isNull(CreditDays, 0) as CreditDays, DateAdd(dd, isNull(CreditDays, 0),  RefDate) as DueDate,  Amount
				from 
					(Select isNull(y.LrCode, z.LrCode) as LrCode, isNull(y.RefNo, z.RefNo) as RefNo, 
						isNull(y.RefDate, (Select Min(x.RefDate) from FAS_BillDetails x where x.RefNo=z.RefNo and x.RefDate <= @RptDate and x.LrCode=isNull(y.LrCode, z.LrCode) and x.CompCode=@CmCode)) as RefDate, 
						isNull(y.CreditDays, 0) CreditDays, z.Amount 
					from 
						(Select LrCode, RefNo, RefDate, CreditDays from fas_billdetails where Type in ('New Ref', 'Advance') and CompCode=@CmCode
						) y 
					Right Outer Join
						(Select LrCode, RefNo, Sum(Amount) as Amount from fas_billdetails
						where Type <> 'On Acct' and RefDate <= @RptDate and CompCode=@CmCode
						group by LrCode, RefNo having sum(Amount) <> 0 ) z 
					On y.LrCode=z.LrCode and y.RefNo=z.RefNo 
					) d
	
			) b
		Order by RefDate, RefNo

	Update @Bills Set BillIndex = (Select Count(*) from @Bills b Where b.RefDate <= a.RefDate and b.RefNo <= a.RefNo and b.CompCode=a.CompCode)
	from @Bills a


	Return

END

GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_BRS_Cleared]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [dbo].[fn_FAS_BRS_Cleared] (@BankCode int, @RptDate datetime, @isAnyFromDate bit, @FromDate datetime, @isAnyToDate bit, @ToDate datetime, @RestrictDate tinyint, @CmCode varchar(12))
					
RETURNS @Bank TABLE
	([SortOrder] 	int,
	[ChqNo] 	varchar(10),
	[CDate] 		datetime,
	[PayType] 	varchar (10),
	[Amount] 	money,
	[ChqFavor]	varchar(50),
	[DocNo] 	int,
	[VrRoute] 	varchar(42),
	[DocDate] 	datetime,
	[ChqDate]	datetime,
	[BankDate]	datetime)


 AS  

BEGIN 
--	--@RestrictDate  0 - Issued/Deposited Date; 1 - Voucher Date;  2 - Cheque Date; 3 - Bank Date

	
	Declare @FDate datetime, @TDate datetime

	Select @FDate=@FromDate
	Select @TDate=@ToDate

	


	If @RestrictDate=0		--Issued/Deposited Date

		Begin
			If @isAnyFromDate='1' 
				Select @FDate=Min(MDate) from
					(
					Select isNull((Select Min(DocDate) from FAS_VoucherTranPay where ChqBank=Convert(varchar, @BankCode) and BankDate <= @RptDate and CompCode=@CmCode), @FromDate) as MDate
					Union All
					Select isNull((Select Min(ChqDate) from FAS_VoucherTranPay where ChqBank=Convert(varchar, @BankCode) and BankDate <= @RptDate and CompCode=@CmCode), @FromDate) as MDate
					) x

			If @isAnyToDate='1' 
				Select @TDate=Max(MDate) from
					(
					Select isNull((Select Max(DocDate) from FAS_VoucherTranPay where ChqBank=Convert(varchar, @BankCode) and BankDate <= @RptDate and CompCode=@CmCode), @ToDate) as MDate
					Union All
					Select isNull((Select Max(ChqDate) from FAS_VoucherTranPay where ChqBank=Convert(varchar, @BankCode) and BankDate <= @RptDate and CompCode=@CmCode), @ToDate) as MDate
					) x


			Insert into @Bank
				Select * from dbo.fn_FAS_BRS_Cleared_IssDep (@BankCode, @RptDate, @FromDate, @ToDate, @CmCode)
		End 

	Else
		Begin
			If @RestrictDate=1	--Voucher Date
				Begin
					If @isAnyFromDate='1' 
						Select @FDate = isNull((Select Min(DocDate) from FAS_VoucherTranPay where ChqBank=Convert(varchar, @BankCode) and BankDate <= @RptDate and CompCode=@CmCode), @FromDate)
		
					If @isAnyToDate='1' 
						Select @TDate = isNull((Select Max(DocDate) from FAS_VoucherTranPay where ChqBank=Convert(varchar, @BankCode) and BankDate <= @RptDate and CompCode=@CmCode), @ToDate)
	
					Insert into @Bank
						Select * from dbo.fn_FAS_BRS_Cleared_Voucher (@BankCode, @RptDate, @FDate, @TDate, @CmCode)
				End 
	
			Else			
	
				If @RestrictDate=2	--Cheque Date
			
					Begin
						If @isAnyFromDate='1' 
							Select @FDate = isNull((Select Min(ChqDate) from FAS_VoucherTranPay where ChqBank=Convert(varchar, @BankCode) and BankDate <= @RptDate and CompCode=@CmCode), @FromDate)
			
						If @isAnyToDate='1' 
							Select @TDate = isNull((Select Max(ChqDate) from FAS_VoucherTranPay where ChqBank=Convert(varchar, @BankCode) and BankDate <= @RptDate and CompCode=@CmCode), @ToDate)
		
						Insert into @Bank
							Select * from dbo.fn_FAS_BRS_Cleared_Cheque (@BankCode, @RptDate, @FDate, @TDate, @CmCode)
					End 
				Else			--Bank Date
					Begin
						If @isAnyFromDate='1' 
							Select @FDate = isNull((Select Min(BankDate) from FAS_VoucherTranPay where ChqBank=Convert(varchar, @BankCode) and BankDate <= @RptDate and CompCode=@CmCode), @FromDate)
			
						If @isAnyToDate='1' 
							Select @TDate = isNull((Select Max(BankDate) from FAS_VoucherTranPay where ChqBank=Convert(varchar, @BankCode) and BankDate <= @RptDate and CompCode=@CmCode), @ToDate)
		
						Insert into @Bank
							Select * from dbo.fn_FAS_BRS_Cleared_Bank (@BankCode, @RptDate, @FDate, @TDate, @CmCode)
					End 
		End

	Delete From @Bank Where SortOrder=3
	
	Declare @Amt as money

	Select @Amt = Sum(Case PayType When 'Issue' Then -1 Else 1 End * Amount) from @Bank Where SortOrder=1

	If @Amt > 0
		Begin
			Delete From @Bank Where SortOrder=1 and PayType='Rcpt'
			Update @Bank Set Amount = 0 Where  SortOrder=1 and PayType='Issue'
		End
	Else
		Begin
			Delete From @Bank Where SortOrder=1 and PayType='Issue'
			Update @Bank Set Amount = 0 Where  SortOrder=1 and PayType='Rcpt'
		End

	Return 

END












GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_BRS_Cleared_Bank]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_BRS_Cleared_Bank] (@BankCode int, @RptDate datetime, @FromDate datetime, @ToDate datetime, @CmCode varchar(12))  
       
RETURNS @Bank TABLE  
 ([SortOrder]  int,  
 [ChqNo]  varchar(10),  
 [CDate]   datetime,  
 [PayType]  varchar (10),  
 [Amount]  money,  
 [ChqFavor] varchar(50),  
 [DocNo]  int,  
 [VrRoute]  varchar(42),  
 [DocDate]  datetime,  
 [ChqDate] datetime,  
 [BankDate] datetime)  
  
  
 AS    
  
BEGIN   
  
  Insert into @Bank  
   
   Select 1 as SortOrder, '0' as ChqNo, Null as CDate, PayType,  Sum(Amount) as Amount, 'Opening Balance' as ChqFavor, 0 as DocNo, '' as VrRoute, Null as DocDate, Null as ChqDate, Null as BankDate  
   from  
    (Select Case b.DrAmt When 0 then 'Issue' Else 'Rcpt' End as PayType,  
      Case b.DrAmt When 0 Then  isNull(b.CrAmt, 0) Else  isNull(b.DrAmt, 0) End as Amount  
    from FAS_VoucherTranPay a   
    Left Outer Join FAS_Voucher_vw b  
     On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode   
    Where a.DocNo<>0 and b.LrCode=@BankCode and Left(a.CompCode, 4)=@CmCode and a.BankDate <= @RptDate and a.BankDate < @FromDate  
     
    Union All  
      
    Select Case a.isReceipt When 0 then 'Issue' Else 'Rcpt' End as PayType, a.ChqAmount as Amount  
     from FAS_VoucherTranPay a  
    Where DocNo=0 and VrRoute = 'OpBal-'+Convert(varchar, @BankCode) and CompCode=@CmCode  
     and a.BankDate <= @RptDate and a.BankDate < @FromDate  
    ) x  
   Group by PayType  
  
  
  
  Insert into @Bank  
  
   Select * from (  
    Select 2 as SortOrder, a.ChqNo, Case b.DrAmt When 0 then a.ChqDate Else b.DocDate End as CDate,   
      Case isNull(b.DrAmt, 0) When 0 then   
         Case When isNull(b.CrAmt, 0)=0 then   
          Case When a.isReceipt='1' then 'Rcpt' Else 'Issue' end   
         Else 'Issue' End   
      Else 'Rcpt' End  as PayType,  
  
      Case isNull(b.DrAmt, 0) When 0 Then   
         Case When isNull(b.CrAmt, 0)=0 Then a.ChqAmount Else isNull(b.CrAmt, 0) End  
      Else isNull(b.DrAmt, 0)  End as Amount,  
  
      Case a.isLrCode When 1 then (Select LedgerName from FAS_LedgerMaster Where LedgerCode=a.ChqFavor and CompCode=@CmCode)           
        Else a.ChqFavor End as ChqFavor, a.DocNo, a.VrRoute,   
      b.DocDate, a.ChqDate, a.BankDate  
    from FAS_VoucherTranPay a   
    Left Outer Join FAS_Voucher_vw b  
     On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode   
    Where isNull(Convert(varchar, b.LrCode), a.ChqBank)=Convert(varchar, @BankCode)  and a.CompCode=@CmCode and a.BankDate <= @RptDate  
    ) x  
    where (BankDate Between @FromDate and @ToDate)  
  
  
  Insert into @Bank  
   
  Select 3 as SortOrder, '0' as ChqNo, Null as CDate,  PayType, Sum(Amount) as Amount, 'Closing Balance' as ChqFavor, 0 as DocNo, '' as VrRoute, Null as DocDate, Null as ChqDate, Null as BankDate  
  from  
   (Select Case b.DrAmt When 0 then 'Issue' Else 'Rcpt' End as PayType,  
     Case b.DrAmt When 0 Then  isNull(b.CrAmt, 0) Else  isNull(b.DrAmt, 0) End as Amount  
   from FAS_VoucherTranPay a   
   Left Outer Join FAS_Voucher_vw b  
    On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode   
   Where b.LrCode=@BankCode and a.CompCode=@CmCode and a.BankDate <= @RptDate and a.BankDate > @ToDate  
   ) y  
  Group by PayType  
   
   
 Return   
  
END   
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_BRS_Cleared_Cheque]    Script Date: 17/06/2026 11:38:43 ******/
