CREATE FUNCTION [dbo].[fn_FAS_BRS_Cleared_Voucher] (@BankCode int, @RptDate datetime, @FromDate datetime, @ToDate datetime, @CmCode varchar(12))
					
RETURNS @Bank TABLE
	([SortOrder] 	int,
	[ChqNo] 	varchar(10),
	[CDate] 		datetime,
	[PayType] 	varchar (10),
	[Amount] 	money,
	[ChqFavor]	varchar(50),
	[DocNo] 	int,
	[VrRoute] 	varchar(42),
	[DocDate] 	datetime,
	[ChqDate]	datetime,
	[BankDate]	datetime)


 AS  

BEGIN 

		Insert into @Bank
	
			Select 1 as SortOrder, '0' as ChqNo, Null as CDate, PayType,  Sum(Amount) as Amount, 'Opening Balance' as ChqFavor, 0 as DocNo, '' as VrRoute, Null as DocDate, Null as ChqDate, Null as BankDate
			from
				(Select Case b.DrAmt When 0 then 'Issue' Else 'Rcpt' End as PayType,
						Case b.DrAmt When 0 Then  isNull(b.CrAmt, 0) Else  isNull(b.DrAmt, 0) End as Amount
				from FAS_VoucherTranPay a 
				Left Outer Join FAS_Voucher_vw b
					On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
				Where a.DocNo<>0 and b.LrCode=@BankCode and Left(a.CompCode, 4)=@CmCode and a.BankDate <= @RptDate and b.DocDate < @FromDate
			
				Union All
				
				Select Case a.isReceipt When 0 then 'Issue' Else 'Rcpt' End as PayType, a.ChqAmount as Amount
					from FAS_VoucherTranPay a
				Where DocNo=0 and Convert(int, Substring(VrRoute, 7, Len(VrRoute)-6))=@BankCode and CompCode=@CmCode
					and a.BankDate <= @RptDate
				) x
			Group by PayType



		Insert into @Bank

			Select * from (
				Select 2 as SortOrder, a.ChqNo, Case b.DrAmt When 0 then a.ChqDate Else b.DocDate End as CDate, 

						Case isNull(b.DrAmt, 0) When 0 then 
									Case When isNull(b.CrAmt, 0)=0 then 
										Case When a.isReceipt='1' then 'Rcpt' Else 'Issue' end 
									Else 'Issue' End 
						Else 'Rcpt' End  as PayType,

						Case isNull(b.DrAmt, 0) When 0 Then 
									Case When isNull(b.CrAmt, 0)=0 Then a.ChqAmount Else isNull(b.CrAmt, 0) End
						Else isNull(b.DrAmt, 0)  End as Amount,

						Case a.isLrCode When 1 then (Select LedgerName from FAS_LedgerMaster Where LedgerCode=a.ChqFavor and CompCode=@CmCode) 								
								Else a.ChqFavor End as ChqFavor, a.DocNo, a.VrRoute, 
						b.DocDate, a.ChqDate, a.BankDate
				from FAS_VoucherTranPay a 
				Left Outer Join FAS_Voucher_vw b
					On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
				Where isNull(b.LrCode, a.ChqBank)=@BankCode and a.CompCode=@CmCode and a.BankDate <= @RptDate
				) x
				where (DocDate Between @FromDate and @ToDate)


		Insert into @Bank
	
		Select 3 as SortOrder, '0' as ChqNo, Null as CDate,  PayType, Sum(Amount) as Amount, 'Closing Balance' as ChqFavor, 0 as DocNo, '' as VrRoute, Null as DocDate, Null as ChqDate, Null as BankDate
		from
			(Select Case b.DrAmt When 0 then 'Issue' Else 'Rcpt' End as PayType,
					Case b.DrAmt When 0 Then  isNull(b.CrAmt, 0) Else  isNull(b.DrAmt, 0) End as Amount
			from FAS_VoucherTranPay a 
			Left Outer Join FAS_Voucher_vw b
				On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
			Where b.LrCode=@BankCode and a.CompCode=@CmCode and a.BankDate <= @RptDate and b.DocDate > @ToDate
			) y
