/****** Object:  UserDefinedFunction [dbo].[fn_FAS_BRS_Dtl]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [dbo].[fn_FAS_BRS_Dtl] (@BankCode int, @AsOnDate datetime, @ClearedStatus char(1), @RestrictDateType char(1), @isAnyFromDate bit, @RptFromDate datetime, @isAnyToDate bit, @RptToDate datetime, @PrStart datetime, @PrEnd datetime, @FinStart datetime, @CmCode varchar(12))
		--@RestictDateType is 'B'-BankDate; 'C'-Cheque Date; 'V'-VoucherDate; 'D'-Deposited or Issued Date
		--@ClearedStatus is 'B'-Both; 'C'-Cleared; 'N'-NotCleared;

RETURNS @Bank TABLE
	([SortOrder] 	int,
	[ChqNo] 	varchar(10),
	[CDate] 		datetime,
	[PayType] 	varchar (10),
	[Amount] 	money,
	[ChqFavor]	varchar(50),
	[DocNo] 	int,
	[VrRoute] 	varchar(42),
	[DocDate] 	datetime,
	[ChqDate]	datetime,
	[BankDate]	datetime)

 AS  

BEGIN

	--Insert all Transactions First
	Insert into @Bank

		Select 2 as SortOrder, a.ChqNo, Case b.DrAmt When 0 Then a.ChqDate Else b.DocDate End as IssDepDate, 
			Case isNull(b.DrAmt, 0) When 0 then 'Issue' Else 'Rcpt' End  as PayType,
			Case isNull(b.DrAmt, 0) When 0 Then isNull(b.CrAmt, 0) Else b.DrAmt End as Amount,
			Case a.isLrCode When 1 then isNull((Select LedgerName from FAS_LedgerMaster Where LedgerCode=a.ChqFavor and CompCode=@CmCode), '')								
						Else a.ChqFavor 
			End as ChqFavor, 
			a.DocNo, a.VrRoute, b.DocDate, a.ChqDate, a.BankDate
		from FAS_VoucherTranSub b
		Left Outer Join (Select * from FAS_VoucherTranPay where (VrRoute Not Like  'OpBal-%') and CompCode=@CmCode) a 
			On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode
		Where  b.DocDate <= @AsOnDate and b.LrCode=@BankCode and a.CompCode=@CmCode

		Union All

		Select 2 as SortOrder, a.ChqNo, a.ChqDate as CDate, Case When a.isReceipt='1' then 'Rcpt' else 'Issue' End as PayType, a.ChqAmount,
				Case a.isLrCode When 1 then (Select LedgerName from FAS_LedgerMaster Where LedgerCode=a.ChqFavor and CompCode=@CmCode) 								
						Else a.ChqFavor End as ChqFavor, a.DocNo, a.VrRoute, a.DocDate, a.ChqDate, a.BankDate
		from FAS_VoucherTranPay a 
		Where a.DocNo=0 and VrRoute= 'OpBal-'+Convert(varchar, @BankCode) and CompCode=@CmCode

	
	--Delete the Unwanted Records
	If @ClearedStatus='C'		--Cleared Cheques Only
		Delete From @Bank Where BankDate is Null or BankDate > @AsOnDate
	Else
		If @ClearedStatus='N'	--Not Cleared Only
			Delete From @Bank Where BankDate <= @AsOnDate

	--Define FromDate and ToDate
	Declare @FromDate datetime, @ToDate datetime

	If @isAnyFromDate = '0' 
		Select @FromDate=@RptFromDate
	Else
		If @RestrictDateType = 'B'			--BankDate
			Select @FromDate=Min(BankDate) from @Bank
		Else
			If @RestrictDateType='C'		--Cheque Date
				Select @FromDate=Min(ChqDate) from @Bank
			Else
				If @RestrictDateType='V'	--Voucher Date
					Select @FromDate=Min(DocDate) from @Bank
				Else				--Deposited / Issued Date
					Select @FromDate=Min(CDate) from @Bank

	If @isAnyToDate = '0' 
		Select @ToDate=@RptToDate
	Else
		If @RestrictDateType = 'B'			--BankDate
			Select @ToDate=Max(BankDate) from @Bank
		Else
			If @RestrictDateType='C'		--Cheque Date
				Select @ToDate=Max(ChqDate) from @Bank
			Else
				If @RestrictDateType='V'	--Voucher Date
					Select @ToDate=Max(DocDate) from @Bank
				Else				--Deposited / Issued Date
					Select @ToDate=Max(CDate) from @Bank


	If @RestrictDateType = 'B'
		Delete From @Bank Where Not (BankDate Between @FromDate and @ToDate)
	Else
		If @RestrictDateType='C'
			Delete From @Bank Where Not (ChqDate Between @FromDate and @ToDate)
		Else
			If @RestrictDateType='V'
				If @FromDate=DateAdd(day, -1, @FinStart) or @ToDate=DateAdd(day, -1, @FinStart)
					Delete From @Bank Where Not (VrRoute like 'OpBal%')
				Else
					Delete From @Bank Where Not (DocDate Between @FromDate and @ToDate)
			Else
				Delete From @Bank Where Not (CDate Between @FromDate and @ToDate)


	Return 

END

















GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_BRS_MinMaxDate]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_BRS_MinMaxDate](@BankCode int, @RptDate datetime, @isAnyFromDate bit, @FromDate datetime, @isAnyToDate bit, @ToDate datetime, @RestrictDate tinyint, @isCleared bit, @CmCode varchar(12))
	/* @RestrictDate  0 - Issued/Deposited Date; 1 - Voucher Date; > 1 - Cheque Date;  @isCleared 0 - Cleared Cheques; 1 - Uncleared Cheques  */
RETURNS @DateLimit TABLE
	(
		MinDate datetime,
		MaxDate datetime
	)
AS
BEGIN
	Declare @FDate datetime, @TDate datetime

	Select @FDate=@FromDate
	Select @TDate=@ToDate

	DECLARE @MinDocDate datetime, @MaxDocDate datetime;
	DECLARE @MinChqDate datetime, @MaxChqDate datetime;
	DECLARE @MinRecChqDate datetime, @MaxRecChqDate datetime;

	Select @MinDocDate=Min(DocDate), @MaxDocDate=Max(DocDate)
	From FAS_Voucher_vw a
	Where a.LrCode=@BankCode and a.CompCode=@CmCode and a.PayMode not in ('', 'Cash', 'Draft')

	Select @MinChqDate=Min(ChqDate), @MaxChqDate=Max(ChqDate)
	From FAS_VoucherTranPay a
	Where a.ChqBank=Convert(varchar, @BankCode) and a.CompCode=@CmCode
		and ((@isCleared='1' AND a.BankDate is Not Null) OR (@isCleared='0' AND (a.BankDate is Null or a.BankDate > @RptDate)))

	Select @MinRecChqDate=Min(ChqDate), @MaxRecChqDate=Max(ChqDate)
	From FAS_VoucherTranPay a
	Where a.CompCode=@CmCode
		and ((@isCleared='1' AND a.BankDate is Not Null) OR (@isCleared='0' AND (a.BankDate is Null or a.BankDate > @RptDate)))
		and Exists (Select * from FAS_VoucherTranSub b
					Where b.LrCode=@BankCode and b.CompCode=@CmCode)
				
	
	If @RestrictDate=0		--Issued/Deposited Date
		Begin
			If @isAnyFromDate='1'
				Select @FDate=isNull(Case When @MinDocDate<@MinChqDate Then @MinDocDate Else @MinChqDate End, @FromDate)
			 
			If @isAnyToDate='1' 
				Select @ToDate=isNull(Case When @MaxDocDate>@MaxChqDate Then @MaxDocDate Else @MaxChqDate End, @ToDate)
		End 

	Else If @RestrictDate=1	--Voucher Date
			Begin
				If @isAnyFromDate='1' 
					Select @FDate=isNull(@MinDocDate, @FromDate)
	
				If @isAnyToDate='1' 
					Select @TDate=isNull(@MaxDocDate, @ToDate)
			End 

	Else			--Cheque Date
		Begin
			If @isAnyFromDate='1' 
				Select @FDate=isNull(Case When @MinChqDate<@MinRecChqDate Then @MinChqDate Else @MinRecChqDate End, @FromDate)
	
			If @isAnyToDate='1' 
				Select @TDate=isNull(Case When @MaxChqDate<@MaxRecChqDate Then @MaxChqDate Else @MaxRecChqDate End, @ToDate)
		End 

	Insert into @DateLimit Select @FDate, @TDate

	Return 
END
GO

