					Union All
					Select isNull((Select Min(ChqDate) from FAS_VoucherTranPay where ChqBank=Convert(varchar, @BankCode) and (BankDate is Null or BankDate > @RptDate) and CompCode=@CmCode), @FromDate) as MDate
					) x

			If @isAnyToDate='1' 
				Select @TDate=Max(MDate) from
					(
					Select isNull((Select Max(DocDate) from FAS_VoucherTranPay where ChqBank=Convert(varchar, @BankCode) and (BankDate is Null or BankDate > @RptDate) and CompCode=@CmCode), @ToDate) as MDate
					Union All
					Select isNull((Select Max(ChqDate) from FAS_VoucherTranPay where ChqBank=Convert(varchar, @BankCode) and (BankDate is Null or BankDate > @RptDate) and CompCode=@CmCode), @ToDate) as MDate
					) x


			Insert into @Bank
				Select * from dbo.fn_FAS_BRS_NotCleared_IssDep (@BankCode, @RptDate, @FDate, @TDate, @CmCode)
		End 

	Else

		If @RestrictDate=1	--Voucher Date
			Begin
				If @isAnyFromDate='1' 
					Select @FDate = isNull((Select Min(DocDate) from FAS_VoucherTranPay where ChqBank=Convert(varchar, @BankCode) and (BankDate is Null or BankDate > @RptDate) and CompCode=@CmCode), @FromDate)
	
				If @isAnyToDate='1' 
					Select @TDate = isNull((Select Max(DocDate) from FAS_VoucherTranPay where ChqBank=Convert(varchar, @BankCode) and (BankDate is Null or BankDate > @RptDate) and CompCode=@CmCode), @ToDate)

				Insert into @Bank
					Select * from dbo.fn_FAS_BRS_NotCleared_Voucher (@BankCode, @RptDate, @FDate, @TDate, @CmCode)
			End 

		Else			--Cheque Date

			Begin
				If @isAnyFromDate='1' 
					Select @FDate = isNull((Select Min(ChqDate) from FAS_VoucherTranPay where ChqBank=Convert(varchar, @BankCode) and (BankDate is Null or BankDate > @RptDate) and CompCode=@CmCode), @FromDate)
	
				If @isAnyToDate='1' 
					Select @TDate = isNull((Select Max(ChqDate) from FAS_VoucherTranPay where ChqBank=Convert(varchar, @BankCode) and (BankDate is Null or BankDate > @RptDate) and CompCode=@CmCode), @ToDate)

				Insert into @Bank
					Select * from dbo.fn_FAS_BRS_NotCleared_Cheque (@BankCode, @RptDate, @FDate, @TDate, @CmCode)
