/****** Object:  UserDefinedFunction [dbo].[fn_FAS_BRS_NotCleared_Cheque]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_BRS_NotCleared_Cheque] (@BankCode int, @RptDate datetime, @FromDate datetime, @ToDate datetime, @CmCode varchar(12))
					
RETURNS @Bank TABLE
	([SortOrder] 	int,
	[ChqNo] 	varchar(10),
	[CDate] 		datetime,
	[PayType] 	varchar (10),
	[Amount] 	money,
	[ChqFavor]	varchar(50),
	[DocNo] 	int,
	[VrRoute] 	varchar(42),
	[DocDate] 	datetime,
	[ChqDate]	datetime)


 AS  

BEGIN

	Insert into @Bank

		Select 1 as SortOrder, '0' as ChqNo, Null as CDate, PayType,  Sum(Amount) as Amount, 'Opening Balance' as ChqFavor, 0 as DocNo, '' as VrRoute, Null as DocDate, Null as ChqDate
		from
			(Select Case b.DrAmt When 0 then 'Issue' Else 'Rcpt' End as PayType,
					Case b.DrAmt When 0 Then  isNull(b.CrAmt, 0) Else  isNull(b.DrAmt, 0) End as Amount
			from FAS_VoucherTranPay a 
			Left Outer Join FAS_Voucher_vw b
				On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
			Where a.DocNo<>0 and b.LrCode=@BankCode and Left(a.CompCode, 4)=@CmCode and (a.BankDate is Null or a.BankDate > @RptDate) and a.ChqDate < @FromDate
		
			Union All
			
			Select Case a.isReceipt When 0 then 'Issue' Else 'Rcpt' End as PayType, a.ChqAmount as Amount
				from FAS_VoucherTranPay a
			Where DocNo=0 and Convert(int, Substring(VrRoute, 7, Len(VrRoute)-6))=@BankCode and CompCode=@CmCode
				and (a.BankDate is Null or a.BankDate > @RptDate)
			) x
		Group by PayType


	Insert into @Bank

		Select * from (
			Select 2 as SortOrder, a.ChqNo, Case b.DrAmt When 0 then a.ChqDate Else b.DocDate End as CDate, 
					Case b.DrAmt When 0 then 'Issue' Else 'Rcpt' End  as PayType,
					Case b.DrAmt When 0 Then isNull(b.CrAmt, 0) Else   isNull(b.DrAmt, 0) End  as Amount,
					Case a.isLrCode When 1 then (Select LedgerName from FAS_LedgerMaster Where LedgerCode=a.ChqFavor and CompCode=@CmCode) 								
							Else a.ChqFavor End as ChqFavor, a.DocNo, a.VrRoute, 
					b.DocDate, a.ChqDate
			from (Select * from FAS_VoucherTranPay where Left(VrRoute, 6) <> 'OpBal-' and CompCode=@CmCode) a 
			Left Outer Join FAS_Voucher_vw b
				On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
			Where isNull(b.LrCode, Convert(int, a.ChqBank))=@BankCode and a.CompCode=@CmCode and (a.BankDate is Null or a.BankDate > @RptDate) 
			) x
			where (CDate Between @FromDate and @ToDate)

		Union All

		Select * from (
			Select 2 as SortOrder, a.ChqNo, a.ChqDate as CDate, Case When a.isReceipt='1' then 'Rcpt' else 'Issue' End as PayType, a.ChqAmount,
					Case a.isLrCode When 1 then (Select LedgerName from FAS_LedgerMaster Where LedgerCode=a.ChqFavor and CompCode=@CmCode) 								
							Else a.ChqFavor End as ChqFavor, a.DocNo, a.VrRoute, a.DocDate, a.ChqDate
			from FAS_VoucherTranPay a 
			Where a.DocNo=0 and Convert(int, Substring(VrRoute, 7, Len(VrRoute)-6))=@BankCode and CompCode=@CmCode and (a.BankDate is Null or a.BankDate > @RptDate)
			) x
			where (ChqDate Between @FromDate and @ToDate)

	Insert into @Bank

		Select 3 as SortOrder, '0' as ChqNo, Null as CDate,  PayType, Sum(Amount) as Amount, 'Closing Balance' as ChqFavor, 0 as DocNo, '' as VrRoute, Null as DocDate, Null as ChqDate
		from
			(Select Case b.DrAmt When 0 then 'Issue' Else 'Rcpt' End as PayType,
					Case b.DrAmt When 0 Then  isNull(b.CrAmt, 0) Else  isNull(b.DrAmt, 0) End as Amount
			from FAS_VoucherTranPay a 
			Left Outer Join FAS_Voucher_vw b
				On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
			Where b.LrCode=@BankCode and a.CompCode=@CmCode and (a.BankDate is Null or a.BankDate > @RptDate) and a.ChqDate > @ToDate
			) y
		Group by PayType



	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_BRS_NotCleared_IssDep]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS ON
