CREATE FUNCTION [dbo].[fn_FAS_BRS_NotCleared_Voucher] (@BankCode int, @RptDate datetime, @FromDate datetime, @ToDate datetime, @CmCode varchar(12))
					
RETURNS @Bank TABLE
	([SortOrder] 	int,
	[ChqNo] 	varchar(10),
	[CDate] 		datetime,
	[PayType] 	varchar (10),
	[Amount] 	money,
	[ChqFavor]	varchar(50),
	[DocNo] 	int,
	[VrRoute] 	varchar(42),
	[DocDate] 	datetime,
	[ChqDate]	datetime)


 AS  

BEGIN 

		Insert into @Bank
	
			Select 1 as SortOrder, '0' as ChqNo, Null as CDate, PayType,  Sum(Amount) as Amount, 'Opening Balance' as ChqFavor, 0 as DocNo, '' as VrRoute, Null as DocDate, Null as ChqDate
			from
				(Select Case b.DrAmt When 0 then 'Issue' Else 'Rcpt' End as PayType,
						Case b.DrAmt When 0 Then  isNull(b.CrAmt, 0) Else  isNull(b.DrAmt, 0) End as Amount
				from FAS_VoucherTranPay a 
				Left Outer Join FAS_Voucher_vw b
					On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
				Where a.DocNo<>0 and b.LrCode=@BankCode and Left(a.CompCode, 4)=@CmCode and (a.BankDate is Null or a.BankDate > @RptDate) and b.DocDate < @FromDate
			
				Union All
				
				Select Case a.isReceipt When 0 then 'Issue' Else 'Rcpt' End as PayType, a.ChqAmount as Amount
					from FAS_VoucherTranPay a
				Where DocNo=0 and Convert(int, Substring(VrRoute, 7, Len(VrRoute)-6))=@BankCode and CompCode=@CmCode
					and (a.BankDate is Null or a.BankDate > @RptDate)
				) x
			Group by PayType



		Insert into @Bank

			Select * from (
				Select 2 as SortOrder, a.ChqNo, Case b.DrAmt When 0 then a.ChqDate Else b.DocDate End as CDate, 
						Case b.DrAmt When 0 then 'Issue' Else 'Rcpt' End  as PayType,
						Case b.DrAmt When 0 Then isNull(b.CrAmt, 0) Else   isNull(b.DrAmt, 0) End  as Amount,
						Case a.isLrCode When 1 then (Select LedgerName from FAS_LedgerMaster Where LedgerCode=a.ChqFavor and CompCode=@CmCode) 								
								Else a.ChqFavor End as ChqFavor, a.DocNo, a.VrRoute, 
						b.DocDate, a.ChqDate
				from FAS_VoucherTranPay a 
				Left Outer Join FAS_Voucher_vw b
					On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
				Where isNull(b.LrCode, a.ChqBank)=@BankCode and a.CompCode=@CmCode and (a.BankDate is Null or a.BankDate > @RptDate) 
				) x
				where (DocDate Between @FromDate and @ToDate)


		Insert into @Bank
	
		Select 3 as SortOrder, '0' as ChqNo, Null as CDate,  PayType, Sum(Amount) as Amount, 'Closing Balance' as ChqFavor, 0 as DocNo, '' as VrRoute, Null as DocDate, Null as ChqDate
		from
			(Select Case b.DrAmt When 0 then 'Issue' Else 'Rcpt' End as PayType,
					Case b.DrAmt When 0 Then  isNull(b.CrAmt, 0) Else  isNull(b.DrAmt, 0) End as Amount
			from FAS_VoucherTranPay a 
			Left Outer Join FAS_Voucher_vw b
				On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
			Where b.LrCode=@BankCode and a.CompCode=@CmCode and (a.BankDate is Null or a.BankDate > @RptDate) and b.DocDate > @ToDate
			) y
		Group by PayType
	
	
	Return 

END



GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_BRS_Sum]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [dbo].[fn_FAS_BRS_Sum] (@BankCode int, @AsOnDate datetime, @FinStart datetime, @CmCode varchar(12))

RETURNS @Bank TABLE
	([SortOrder] 	int,
	[Particulars]	varchar(50),
	[PayType] 	varchar (10),
	[Amount] 	money)

 AS  

BEGIN

	--Insert Opening Balances
	Insert into @Bank

		Select 1 as SortOrder, 'Opening Balance' as Particulars, '' as PayType, Sum(OpBalance)
		From FAS_LedgerMaster Where LedgerCode=@BankCode and CompCode=@CmCode

	If @AsOnDate >= @FinStart
		Update @Bank Set Amount = Amount + (Select Sum(DrAmt-CrAmt) VrAmt From FAS_VoucherTranSub Where LrCode=@BankCode and DocDate<@AsOnDate and CompCode=@CmCode)
		Where SortOrder = 1


	Insert into @Bank

		Select 2 as SortOrder, 'NotCleared' as Particulars, PayType, isNull(Sum(Amount) , 0)
		from (
			Select Case a.DrAmt When 0 then 'Issue' Else 'Rcpt' End as PayType,
				Case  When a.DrAmt=0 Then  a.CrAmt Else  a.DrAmt End as Amount
			from  FAS_VoucherTranSub a Left Outer Join FAS_VoucherTranPay b
			On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
			Where a.LrCode=@BankCode and a.CompCode=@CmCode and (b.BankDate is Null or b.BankDate > @AsOnDate) and a.DocDate <= @AsOnDate 
		
			Union All
	
			Select Case isReceipt When 0 then 'Issue' Else 'Rcpt' End as PayType, ChqAmount as Amount
			from FAS_VoucherTranPay
			Where VrRoute = 'OpBal-'+Convert(varchar, @BankCode) and CompCode=@CmCode and (BankDate is Null or BankDate > @AsOnDate)
		) x 
		Group by PayType

	Return 

END


GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Budget_AllOpBalance]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Budget_AllOpBalance] (@OBDate datetime, @ActualsCutOff datetime, @isRealisedAmtOnly bit, @isMakePLEntryZero bit, @CmCode varchar(12))  

RETURNS @Ledger TABLE
	(LedgerCode	int,
	LedgerName	varchar(50),
	Alias		varchar(50),
	LrRoute		varchar(42),
	isBillwise	bit,	
	CreditDays 	int,
	OpBalance	money,
	isCostCentreApplicable	bit,
	isActive 	bit,
	CompCode	varchar(12))
		
AS  

BEGIN 
	
	Declare @UpTo datetime
	Select @UpTo = DateAdd(day, -1, @OBDate)
	
		
	/* Data Insert from Voucher Transaction Based on Actuals Cut Off Date AND Balance From Budget Data */	
	Insert into @Ledger		

		Select a.LedgerCode, a.LedgerName, a.Alias, a.LrRoute, a.isBillwise, a.Creditdays, 
			Case When LrRoute like '0205%' Then isNull(c.ClosingStock, 0)  Else a.OpBalance+isNull(b.TranAmt, 0) End as OpBalance,
			a.isCostCentreApplicable, a.isActive, a.CompCode
		from FAS_Budget_LedgerMaster a 
		Left Outer Join 
						(Select a.LrCode, Sum(Case When @isRealisedAmtOnly='1' and b.DocNo is Not Null and b.BankDate is Null Then 0 Else DrAmt-CrAmt End) as TranAmt 
						from dbo.fn_FAS_Budget_VoucherTranSub_UpTo(@UpTo, @ActualsCutOff, @CmCode) a Left Outer Join FAS_VoucherTranPay b
						On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode
						Group by a.LrCode) b
			On a.LedgerCode=b.LrCode
		Left Outer Join dbo.fn_FAS_Budget_StockValue(@UpTo, @UpTo, @ActualsCutOff, @CmCode) c 
			On a.LedgerCode=c.LedgerCode	
		Where a.CompCode=@CmCode


	If @isMakePLEntryZero='1'
		BEGIN
			Update @Ledger Set OpBalance=0
			From @Ledger a 
			Left Outer Join FAS_GroupMaster d On a.LrRoute=d.GrRoute+d.GrWidth and a.CompCode=d.CompCode
			Where d.Master in ('02', '03')

			Declare @FinStart datetime, @PrEnd datetime, @Amt money
			SET @PrEnd=DateAdd(day, -1, @OBDate)

			Select @FinStart=Min(DocDate) From dbo.fn_FAS_Budget_VoucherTranMast_UpTo(@UpTo, @ActualsCutOff, @CmCode)

			SET @FinStart=isNull(@FinStart, @OBDate)


			If  @FinStart >= @OBDate
				SET @Amt=0
			Else
				BEGIN
					If Month(@FinStart) <= 3 
						SET @FinStart=Convert(datetime, Convert(varchar, Year(@FinStart)-1)+'-04-01', 120)
					Else
						SET @FinStart=Convert(datetime, Convert(varchar, Year(@FinStart))+'-04-01', 120)

					SET @Amt=dbo.fn_FAS_Budget_Profit_Loss_Period(@FinStart, @PrEnd, @ActualsCutOff, @CmCode)
				END

			Update @Ledger Set OpBalance=OpBalance+@Amt
			From @Ledger a 
			Where LedgerCode=2
			
		END

	Return

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Budget_AllOpBalance_Compare]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Budget_AllOpBalance_Compare] (@OBDate datetime, @ActualsCutOff datetime, @isRealisedAmtOnly bit, @isMakePLEntryZero bit, @CmCode varchar(12))  

RETURNS @Ledger TABLE
	(LedgerCode            int,
	LedgerName             varchar(50),
	Alias                  varchar(50),
	LrRoute                varchar(42),
	isBillwise             bit,
	CreditDays             int,
	OpBalance_Act          money,
	OpBalance_Bud          money,
	isCostCentreApplicable bit,
	isActive               bit,
	CompCode               varchar(12))
		
AS  

BEGIN 
	
	Declare @UpTo datetime
	Select @UpTo = DateAdd(day, -1, @OBDate)
	
		
	/* Data Insert from Voucher Transaction Based on Actuals Cut Off Date AND Balance From Budget Data */	
	Insert into @Ledger		

		Select a.LedgerCode, a.LedgerName, a.Alias, a.LrRoute, a.isBillwise, a.Creditdays, 
			Case When LrRoute like '0205%' Then isNull(d.ClosingStock, 0)  Else a.OpBalance+isNull(b.TranAmt, 0) End as OpBalance_Act,
			Case When LrRoute like '0205%' Then isNull(e.ClosingStock, 0)  Else a.OpBalance+isNull(c.TranAmt, 0) End as OpBalance_Bud,
			a.isCostCentreApplicable, a.isActive, a.CompCode
		from FAS_Budget_LedgerMaster a 
		Left Outer Join
							(Select a.LrCode, Sum(Case When @isRealisedAmtOnly='1' and b.DocNo is Not Null and b.BankDate is Null Then 0 Else DrAmt-CrAmt End) as TranAmt 
							from FAS_VoucherTranSub a Left Outer Join FAS_VoucherTranPay b
							On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode
							Where a.DocDate<@OBDate and a.CompCode=@CmCode
							Group by a.LrCode) b
			On a.LedgerCode=b.LrCode
		Left Outer Join 
						(Select a.LrCode, Sum(Case When @isRealisedAmtOnly='1' and b.DocNo is Not Null and b.BankDate is Null Then 0 Else DrAmt-CrAmt End) as TranAmt 
						from dbo.fn_FAS_Budget_VoucherTranSub_UpTo(@UpTo, @ActualsCutOff, @CmCode) a Left Outer Join FAS_VoucherTranPay b
						On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode
						Group by a.LrCode) c
			On a.LedgerCode=c.LrCode
		Left Outer Join dbo.fn_FAS_StockValue(@UpTo, @UpTo, @CmCode) d 
			On a.LedgerCode=d.LedgerCode	
		Left Outer Join dbo.fn_FAS_Budget_StockValue(@UpTo, @UpTo, @ActualsCutOff, @CmCode) e 
			On a.LedgerCode=e.LedgerCode	
		Where a.CompCode=@CmCode


	If @isMakePLEntryZero='1'
		BEGIN
			Update @Ledger Set OpBalance_Act=0, OpBalance_Bud=0
			From @Ledger a 
			Left Outer Join FAS_GroupMaster d On a.LrRoute=d.GrRoute+d.GrWidth and a.CompCode=d.CompCode
			Where d.Master in ('02', '03')

			Declare @PrEnd datetime, @FinStart datetime, @FinStartAct datetime, @FinStartBud datetime, @AmtAct money, @AmtBud money
			SET @PrEnd=DateAdd(day, -1, @OBDate)

			Select @FinStartBud=Min(DocDate) From dbo.fn_FAS_Budget_VoucherTranMast_UpTo(@UpTo, @ActualsCutOff, @CmCode)

			SET @FinStartBud=isNull(@FinStartBud, @OBDate)

			If (@FinStartBud>@ActualsCutOff)
				Select @FinStartAct=Min(DocDate) From FAS_VoucherTranMast Where DocDate<=@UpTo and CompCode=@CmCode
			
			If @FinStartBud > @FinStartAct
				SET @FinStart=@FinStartAct
			Else
				SET @FinStart=@FinStartBud
				
			If  @FinStart >= @OBDate
				BEGIN
					SET @AmtAct=0
					SET @AmtBud=0
				END
			Else
				BEGIN
					If Month(@FinStart) <= 3 
						SET @FinStart=Convert(datetime, Convert(varchar, Year(@FinStart)-1)+'-04-01', 120)
					Else
						SET @FinStart=Convert(datetime, Convert(varchar, Year(@FinStart))+'-04-01', 120)

					SET @AmtBud=dbo.fn_FAS_Budget_Profit_Loss_Period(@FinStart, @PrEnd, @ActualsCutOff, @CmCode)
					
					If @OBDate>=@ActualsCutOff
						SET @AmtAct=@AmtBud
					Else
						SET @AmtAct=dbo.fn_FAS_Profit_Loss_Period(@FinStart, @PrEnd, @CmCode)
					
				END

			Update @Ledger Set OpBalance_Act=OpBalance_Act+@AmtAct, OpBalance_Bud=OpBalance_Bud+@AmtBud
			From @Ledger a 
			Where LedgerCode=2
			
		END

	Return

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Budget_Dis_BalanceSheet]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Budget_Dis_BalanceSheet] (@isVertical bit,  @RptType int, @Start datetime, @End datetime, @ActualsCutOff datetime, @CmCode varchar(12)) 
/*  @isVertical = 0-Horizontal Representation; 1-Vertical Representation */	
/*  @RptType = 0 refers Abstract-only groups; 1 refers expand to single level; 2 refer Subgroup with all ledgers*/

RETURNS @RetTable TABLE
	([Master] 	[varchar](10),
	[Path] 		[varchar](42),
	[Type] 		[varchar] (10),	
	[Code] 		[int],
	[Particulars] 	[varchar] (100),
	[SubAmount] 	[money],
	[TotalAmount] 	[money],
	[SortOrder] 	[int]
	)
AS  

BEGIN 

	Declare @CallTrialBalanceType char(1)
/*
	If @isSummary='1'
		Select @CallTrialBalanceType='A'
	Else
		Select @CallTrialBalanceType='S'
*/

	If @RptType='0'
		Select @CallTrialBalanceType='A'--Abstract Only Group
	if @RptType='1'
		Select @CallTrialBalanceType='S' -- Groups and 1st level Ledgers
	if @RptType='2'
		Select @CallTrialBalanceType='M'  --SubGroup with All Ledger


	Insert into @RetTable

		Select Master, Path, Type, Code,
				Case Type when 'Group' then Space(Len(Path)) + Particulars
		                           	when 'Ledger' then space(Len(Path))+'    '+Particulars End as Particulars,
							
					Case When Type='Ledger' or (Len(Path) > 2 and Type='Group') then Amount Else 0 End as SubAmt,	
					Case When Len(Path)=2 and Type='Group' then Amount Else 0 End as TotAmt, 0
	
		From     (
				Select Master, Path, Type, Code, Particulars, (ClosingBalance) as Amount  
				from dbo.fn_FAS_Budget_Rpt_TrialBalance(@CallTrialBalanceType, @Start, @End, @ActualsCutOff, @CmCode)
				Where Left(Path, 2) in ('01', '02', '03', '04', '09', '0A', '0B', '0C', '0F', 'ZZ')  and (Path Not Like '0205%')
				
				Union All
		
				Select '00', '0205' as Path, 'Group' as Type,  9999 as Code, 'Closing Stock'  as Particulars, Sum(ClosingStock)
				from dbo.fn_FAS_Budget_StockValue (@Start, @End, @ActualsCutOff, @CmCode)
		
				Union All
		
				Select '00', '0205', 'Ledger' as Type,  9999 as Code, isNull(b.LedgerName, '')   as Particulars, ClosingStock
				from dbo.fn_FAS_Budget_StockValue (@Start, @End, @ActualsCutOff, @CmCode) a 
				Left Outer Join FAS_LedgerMaster b 
				On a.LedgerCode=b.LedgerCode and a.CompCode=b.CompCode
				Where ClosingStock<>0
	
			)M

			Order by Path, Type	

			--To reduce the default OpeningStock added in Current Assets and Add the Closing Stock
			Update @RetTable Set TotalAmount=TotalAmount+(Select Sum(ClosingStock-OpeningStock) 
			From  dbo.fn_FAS_Budget_StockValue (@Start, @End, @ActualsCutOff, @CmCode))
			Where Path='02' and Type='Group'

			
			If @RptType = '0' --Groupwise Summary
				Begin 
					Delete @RetTable
						Where  Not (Type='Group' and Len(Path) = 2)	
				End

			if @RptType = '1'
				Begin
					Delete @RetTable
						Where  (Type = 'Ledger'  and Len(Path) > 2) or (Type='Group' and Len(Path) > 4)	
				End


			--To insert Profit & Loss A/c Details
			Declare @Amount money, @isPL_GroupRequired bit

			Select @isPL_GroupRequired = '0'

			--To Insert P&L Opening Balance
			Select @Amount=isNull(dbo.fn_FAS_Budget_Profit_Loss_OB(@Start, @ActualsCutOff, @CmCode) , 0)

			If @Amount<>0
				Begin
					Insert into @RetTable			
						Select '', '00PO', 'Ledger', -3, '    Opening Balance', @Amount as Amount, 0, 0

					Select @isPL_GroupRequired='1'
				End

			--To Insert P&L Current Period
			Select @Amount=isNull(dbo.fn_FAS_Budget_Profit_Loss_Period(@Start, @End, @ActualsCutOff, @CmCode), 0)

			If @Amount<>0

				Begin
					Insert into @RetTable		
						Select '', '00PC', 'Ledger', -2, '    Current Period', @Amount as Amount, 0, 0
			
					Select @isPL_GroupRequired='1'
				End
				

			--To Insert P&L Transfered Amount
			Select @Amount= (sum(DrAmt)-sum(CrAmt))
			from dbo.fn_FAS_Budget_VoucherTranSub_Period_Lr(2, @Start, @End, @ActualsCutOff, @CmCode) 

			If isNull(@Amount, 0)<>0
				Begin			
					Insert into @RetTable	
						Select '', '00PT', 'Ledger', -1, '    Less Transfered', isNull(@Amount, 0) as Amount, 0, 0
				
					Select @isPL_GroupRequired='1'
				End


			--To Insert P&L Group
			If @isPL_GroupRequired='1'

				Begin
					Select @Amount=Sum(SubAmount) from @RetTable Where Path like '00%'

					If isNull(@Amount, 0)<>0				
						Insert into @RetTable			
							Select '', '00', 'Group', 0, '  PROFIT & LOSS A/C', 0, isNull(@Amount, 0), 0
					Else
						Delete from @RetTable Where Path like '00%'
				End


/*
			--To insert Profit & Loss A/c Details

			Insert into @RetTable
			
				Select '', '00PO', 'Ledger', -3, '    Opening Balance', dbo.fn_FAS_Profit_Loss_OB(@Start, @CmCode) as Amount, 0, 0
		
			Insert into @RetTable			
		
				Select '', '00PC', 'Ledger', -2, '    Current Period', dbo.fn_FAS_Profit_Loss_Period(@Start, @End, @CmCode) as Amount, 0, 0
			
				UNION ALL
			
				Select '', '00PT', 'Ledger', -1, '    Less Transfered', isnull((sum(DrAmt)-sum(CrAmt)), 0) as Amount, 0, 0
				from FAS_Voucher_Vw 
				where DocDate between @Start and  @End and LrCode=2 and Compcode = @CmCode	

			Insert into @RetTable
			
				Select '', '00', 'Group', 0, '  PROFIT & LOSS A/C', 0, Sum(SubAmount), 0
				from @RetTable
				where Path like '00%'
*/




/*  Update  SortOrder To Groups */

			Update @RetTable Set SortOrder =
				Case Path
					When '01' Then 101 
					When '0B' Then 102 
					When '03' Then 103
					When '09' Then 104
					When '0A' Then 105
					When '02' Then 106
					When '04' Then 107
					When '0C' Then 108
					When '0F' Then 109
					When '00' Then Case When TotalAmount < 0 Then 190 Else 290 End
					When 'ZZ' Then Case When TotalAmount < 0 Then 191 Else 291 End
				End
			Where Type='Group' and Len(Path) = 2 

/* Update SortOrder To SubGroups and Ledgers */

			Update @RetTable Set SortOrder=b.SortOrder
			from @RetTable a Left Outer Join (Select * from @RetTable Where Type='Group' and Len(Path) = 2) b
			On Left(a.Path, 2)=b.Path
			Where Not (a.Type='Group' and Len(a.Path) = 2)				

			If @isVertical='1'		--These are no need for horizontal representation

				Begin

					Update @RetTable Set SortOrder=SortOrder + 100
					Where Left(Path, 2) in ('09', '0A', '02', '0C')

					Update @RetTable Set SubAmount=-SubAmount, TotalAmount=-TotalAmount
--					Where SortOrder Between 201 and 299
					Where Left(Path, 2) in ('01', '03', '0B', '04', '0F')


					Update @RetTable Set SubAmount=Case When TotalAmount>0 Then SubAmount Else -SubAmount End
					Where Left(Path, 2) in ('00', 'ZZ')

					Update @RetTable Set TotalAmount =  ABS(TotalAmount) 
					Where Left(Path, 2) in ('00', 'ZZ')

					-- Initial Stage
					Insert into @RetTable  Select '',  'SF', 'Group', 0, 'SOURCE OF FUNDS', 0 , 0, 0
					Insert into @RetTable  Select '',  'AF', 'Group', 0, 'APPLICATION OF FUNDS', 0 , 0,  200
					Insert into @RetTable  Select '',  'ST', 'Group', 0, 'TOTAL', 0 , 0, 199
					Insert into @RetTable  Select '',  'AT', 'Group', 0, 'TOTAL', 0 , 0,  300

					Update @RetTable Set TotalAmount=(Select Sum(TotalAmount) from @RetTable Where SortOrder < 199)
					Where SortOrder=199

					Update @RetTable Set TotalAmount=(Select Sum(TotalAmount) from @RetTable Where SortOrder > 200)
					Where SortOrder=300

				End

	Return


END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Budget_Dis_GroupLedgers_CashBank]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Budget_Dis_GroupLedgers_CashBank] (@PrStart datetime, @PrEnd datetime, @ActualsCutOff datetime, @CmCode varchar(12))  

RETURNS @RetTable TABLE
	([Master] [varchar](10),
	[Path] [varchar](42),
	[Type] [varchar] (10),
	[Code] [int],
	[Particulars] [varchar] (100),
	[OpBalance] [money],
	[DrAmt] [money],
	[CrAmt] [money],
	[ClosingBalance] [money]	
	)

 AS  

BEGIN 
	
	Insert into @RetTable
		Select Master, Path, Type, Code, Particulars, OpBalance, DrAmt, CrAmt, ClosingBalance
		from [dbo].[fn_FAS_Budget_Group_SubGroupLedger_CashBank_CB] (@PrStart, @PrStart, @PrEnd, @ActualsCutOff, @CmCode)  
		Where ((Type='Ledger' and Len(Path)=4 ) or (Type='Group' and Len(Path)=6))
		Order by Type, Particulars


	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Budget_Dis_GroupLedgers_GroupSummary]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Budget_Dis_GroupLedgers_GroupSummary] (@Route varchar(42), @isAsPerBalanceSheet bit, @PrStart datetime, @PrEnd datetime, @ActualsCutOff datetime, @CmCode varchar(12))  

RETURNS @RetTable TABLE
	([Master] [varchar](10),
	[Path] [varchar](42),
	[Type] [varchar] (10),
	[Code] [int],
	[Particulars] [varchar] (100),
	[OpBalance] [money],
	[DrAmt] [money],
	[CrAmt] [money],
	[ClosingBalance] [money]
	)

 AS  

BEGIN 

	If  @isAsPerBalanceSheet = '1' and (@Route='02' or @Route like '0205%')
		Begin
			Insert into @RetTable
		
				Select Master, Path, Type, Code, Particulars, OpBalance, DrAmt, CrAmt, ClosingBalance									
				From (
						Select Master, Path, Type, Code, Particulars, OpBalance, DrAmt, CrAmt, ClosingBalance
						from [dbo].[fn_FAS_Budget_Group_SubGroupLedger_CB] (@Route, @PrStart, @PrStart, @PrEnd, @ActualsCutOff, @CmCode)  
						Where ((Type='Ledger' and Len(Path)=Len(@Route)) or (Type='Group' and Len(Path)=Len(@Route)+2))
							and ClosingBalance <> 0 and Left(Path, 2) in ('02')  and (Path Not Like '0205%')
						
						Union All
				
						Select '00', '0205' as Path, 'Group' as Type,  9999 as Code, 'STOCK-IN-HAND'  as Particulars, Sum(OpeningStock), 0, 0,  Sum(ClosingStock) --Sum(-ClosingStock)
						from dbo.fn_FAS_Budget_StockValue (@PrStart, @PrEnd, @ActualsCutOff, @CmCode)
				
						Union All
				
						Select '00', '0205', 'Ledger' as Type,  9999 as Code, isNull(b.LedgerName, '')   as Particulars, OpeningStock, 0, 0, ClosingStock    --  (-ClosingStock)
						from dbo.fn_FAS_Budget_StockValue (@PrStart, @PrEnd, @ActualsCutOff, @CmCode) a Left Outer Join FAS_LedgerMaster b On a.LedgerCode=b.LedgerCode and a.CompCode=b.CompCode
						where ClosingStock<>0
			
					)M
				Where ((Type='Ledger' and Len(Path)=Len(@Route)) or (Type='Group' and Len(Path)=Len(@Route)+2))
				Order by Type, Particulars
		
					--To reduce the default OpeningStock added in Current Assets and Add the Closing Stock
					Update @RetTable Set ClosingBalance= ClosingBalance+(Select Sum(ClosingStock-OpeningStock) from  dbo.fn_FAS_StockValue (@PrStart, @PrEnd, @CmCode))
					Where Path='02' and Type='Group'
		End
	Else
	
		Insert into @RetTable
			
			Select Master, Path, Type, Code, Particulars, OpBalance, DrAmt, CrAmt, ClosingBalance
			from [dbo].[fn_FAS_Budget_Group_SubGroupLedger_CB] (@Route, @PrStart, @PrStart, @PrEnd, @ActualsCutOff, @CmCode)  
			Where ((Type='Ledger' and Len(Path)=Len(@Route)) or (Type='Group' and Len(Path)=Len(@Route)+2))
			and ClosingBalance <> 0
			Order by Type, Particulars
				

	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Budget_Dis_ProfitAndLoss]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Budget_Dis_ProfitAndLoss] (@isVertical bit,  @RptType int, @Start datetime, @End datetime, @ActualsCutOff datetime, @CmCode varchar(12))
/* @isVertical= 0 - Horizontal Representation; 1 - Vertical Representation */	
/*  @isSummary - 1 refers Abstract-only groups, 0 refers expand to single level */

RETURNS @RetTable TABLE
	([Master] 	[varchar](10),
	[Path] 		[varchar](42),
	[Type] 		[varchar] (10),	
	[Code] 		int,
	[Particulars] 	[varchar] (100),
	[SubAmount] 	[money],
	[TotalAmount] 	[money],
	[SortOrder] 	int
	)
AS  

BEGIN 

	Declare @CallTrialBalanceType char(1)
/*
	If @isSummary='1'
		Select @CallTrialBalanceType='A'
	Else
		Select @CallTrialBalanceType='S'
*/

	If @RptType='0'
		Select @CallTrialBalanceType='A'--Abstract Only Group
	if @RptType='1'
		Select @CallTrialBalanceType='S' -- Groups and 1st level Ledgers
	if @RptType='2'
		Select @CallTrialBalanceType='M'  --SubGroup with All Ledger


	Insert into @RetTable

		Select Master, Path, Type, Code,
				Case Type when 'Group' then Space(Len(Path)) + Particulars
		                           	when 'Ledger' then space(Len(Path))+'    '+Particulars End as Particulars,
							
					Case When Type='Ledger' or (Len(Path) > 2 and Type='Group') then Amount Else 0 End as SubAmt,	
					Case When Len(Path)=2 and Type='Group' then Amount Else 0 End as TotAmt, 0
	
		From (
				Select Master, Path, Type, Code, Particulars, (DrAmt-CrAmt) as Amount  
				from dbo.fn_FAS_Budget_Rpt_TrialBalance(@CallTrialBalanceType, @Start, @End, @ActualsCutOff, @CmCode)
				where Left(Path, 2) in ('0E', '0D', '05', '06', '07', '08')   
				
				Union All
		
				Select '00', '21' as Path, 'Group' as Type, 9999 as Code,  'Opening Stock'  as Particulars, Sum(OpeningStock) 
				from dbo.fn_FAS_Budget_StockValue (@Start, @End, @ActualsCutOff, @CmCode)
		
				Union All
		
				Select '00', '31' as Path, 'Group' as Type,  9999 as Code, 'Closing Stock'  as Particulars, Sum(-ClosingStock)
				from dbo.fn_FAS_Budget_StockValue (@Start,@End, @ActualsCutOff, @CmCode)

				Union All

				Select '00', '21', 'Ledger' as Type,  9999 as Code, isNull(b.LedgerName, '')  as Particulars, OpeningStock
				from dbo.fn_FAS_Budget_StockValue (@Start, @End, @ActualsCutOff, @CmCode) a Left Outer Join FAS_LedgerMaster b On a.LedgerCode=b.LedgerCode and a.CompCode=b.CompCode
				where OpeningStock<>0
		
				Union All
		
				Select '00', '31', 'Ledger' as Type,  9999 as Code, isNull(b.LedgerName, '')   as Particulars, -ClosingStock
				from dbo.fn_FAS_Budget_StockValue (@Start, @End, @ActualsCutOff, @CmCode) a Left Outer Join FAS_LedgerMaster b On a.LedgerCode=b.LedgerCode and a.CompCode=b.CompCode
				where ClosingStock<>0
	
			)M
			Order by Path, Type	

/*
			If @isSummary = '1' --Groupwise Summary
				Begin 
					Delete @RetTable
						Where  Not (Type='Group' and Len(Path) = 2)	
				End
			Else
				Begin
					Delete @RetTable
						Where  (Type = 'Ledger'  and Len(Path) > 2) or (Type='Group' and Len(Path) > 4)	
				End
*/
			If @RptType = '0' --Groupwise Summary
				Begin 
					Delete @RetTable
						Where  Not (Type='Group' and Len(Path) = 2)	
				End

			if @RptType = '1'
				Begin
					Delete @RetTable
						Where  (Type = 'Ledger'  and Len(Path) > 2) or (Type='Group' and Len(Path) > 4)	
				End


			Insert into @RetTable 
				Select '00' as Master, 'GP' as Path, 'Group' as Type,  0 as Code, Case When TotalAmount > 0 Then 'GROSS PROFIT'  Else 'GROSS LOSS' End as Particulars, 
					0 as SubAmount,  TotalAmount, 150 as SortOrder
				From 
					(Select -Sum(TotalAmount) as TotalAmount
					From @RetTable
					Where Left(Path, 2) in ('0E', '06', '31', '21', '0D', '05')
					)x				

			Insert into @RetTable
				Select '00' as Master, 'NP' as Path, 'Group' as Type,  0 as Code, Case When TotalAmount > 0 Then 'NET PROFIT'  Else 'NET LOSS' End as Particulars, 
					0 as SubAmount, TotalAmount, 200 as SortOrder
				From 
					(Select -Sum(TotalAmount) as TotalAmount
					From @RetTable
					Where Left(Path, 2) in ('0E', '06', '31', '08', '21', '0D', '05', '07')
					)x


/*  Update  SortOrder To Groups */

			Update @RetTable Set SortOrder =
				Case Path
					When '0E' Then 101 		
					When '21' Then 112
					When '0D' Then 113
					When '31' Then 114
					
					When '05' Then 125
					When '06' Then 126
	
					When '07' Then 197
					When '08' Then 198
				End
			Where Type='Group' and Len(Path) = 2 and Path not in ('GP', 'NP')

/* Update SortOrder To SubGroups and Ledgers		 */

			Update @RetTable Set SortOrder=b.SortOrder
			from @RetTable a Left Outer Join (Select * from @RetTable Where Type='Group' and Len(Path) = 2) b
			On Left(a.Path, 2)=b.Path
			Where Not (a.Type='Group' and Len(a.Path) = 2)				

			If @isVertical='1'		--These are no need for horizontal representation
				Begin
					Update @RetTable Set SubAmount=-SubAmount, TotalAmount=-TotalAmount
					Where Left(Path, 2) in ('0E', '06', '08', '31')

					Update @RetTable Set TotalAmount=Abs(TotalAmount)
					Where Left(Path, 2) in ('GP', 'NP')
		
					-- Initial Stage
					Insert into @RetTable  Select '00',  'TA', 'Group', 0, 'TRADING AMOUNT', 0 , 0, 0
					Insert into @RetTable  Select '00',  'CS', 'Group', 0, 'COST OF SALES', 0 , 0,  110
					Insert into @RetTable  Select '00',  'IS', 'Group', 0, 'INCOME STATEMENT', 0, 0, 160

				End
	Return


END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Budget_Dis_Vouchers_Ledgers]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Budget_Dis_Vouchers_Ledgers] (@LrCode int, @MnCode varchar(6), @PrStart datetime, @PrEnd datetime, @ActualsCutOff datetime, @CmCode varchar(12))  

RETURNS @RetTable TABLE
	([DocDate] [datetime],
	[DocNo] [int],
	[RefNo] [varchar] (30),	
	[VrRoute] [varchar] (42),	
	[VoucherName] [varchar] (50),
	[Particulars] [varchar] (50),	
	[Debit] [money],
	[Credit] [money],
	[ClosingBalance] [money]
	)

 AS  

BEGIN 
		
	Declare @OPBal money
	Select @OPBal=0 	--=dbo.fn_FAS_LedgerOpBalance(@LrCode,  Convert(datetime, @MnCode+'01', 112), '0', @CmCode)

	Declare @RptStart datetime, @RptEnd datetime
	Select @RptStart = Convert(datetime, @MnCode+'01', 112)
	Select @RptEnd = DateAdd(day, -1, DateAdd(month, 1, @RptStart))

	Insert into @RetTable

		Select n.DocDate,  n.DocNo, n.RefNo, n.VrRoute, n.VoucherName, n1.LedgerName as Particulars, n.Debit, n.Credit, 0.0 as ClosingBalance
--			Case When CB < 0 then Convert(varchar, -CB) + ' Cr' When CB > 0 then Convert(varchar, CB) + ' Dr' Else ' ' End Closing_Balance
		from
		
			(Select m.VrRoute, m.DocDate, m.VoucherName, m.DocNo, m.RefNo, 
				isNull((Select Top 1 m1.LrCode from dbo.fn_FAS_Budget_VoucherTranSub(@ActualsCutOff, @CmCode) m1 
							Where m1.DocNo=m.DocNo and m1.VrRoute=m.VrRoute and m1.LrCode<>m.LrCode and m1.CompCode=@CmCode), m.LrCode) as Particulars,
				m.Debit, m.Credit, m.LrCode--,
/*				isNull((Select Sum(DrAmt-CrAmt)  from FAS_VoucherTranSub d 
					Where d.LrCode=m.LrCode and Convert(varchar(6), d.DocDate, 112)=@MnCode
						and ((d.docDate < m.DocDate) or ((d.DocDate=m.DocDate) and (d.VrRoute < m.VrRoute or (d.VrRoute=m.VrRoute and d.DocNo<=m.DocNo))))
						 and d.CompCode=m.CompCode
				), 0)  + @OpBal as CB	*/
			from	
				(Select top 100 Percent  a.VrRoute, a.DocDate, c.VoucherName, a.DocNo,
					isNull(Case When LTrim(RTrim(a2.Ref))='' then b.RefType+':'+Convert(varchar, b.RefNo) else a2.Ref end, '') as RefNo,  
					a.DrAmt as Debit, a.CrAmt as Credit, a.LrCode, a.CompCode
				from dbo.fn_FAS_Budget_VoucherTranSub_Period_Lr(@LrCode, @RptStart, @RptEnd, @ActualsCutOff, @CmCode) a
				Left Outer Join dbo.fn_FAS_Budget_VoucherTranMast_Period_Lr(@LrCode, @RptStart, @RptEnd, @ActualsCutOff, @CmCode) a2
				On a.VrRoute=a2.VrRoute and a.DocDate=a2.DocDate and a.DocNo=a2.DocNo and a.CompCode=a2.CompCode
				Left Outer Join FAS_VoucherTranRef b
				On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode
				Left Outer Join FAS_Budget_VoucherMaster c On a.VrRoute=c.VrRoute+c.VrWidth and a.CompCode=c.CompCode
				Order by a.DocDate,  a.DocNo
				)  m 
			) n 
		Left Outer Join FAS_Budget_LedgerMaster n1 On n.Particulars=n1.LedgerCode 
		Where n1.CompCode=@CmCode
		Order by DocDate, VrRoute, DocNo					

	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Budget_Dis_Vouchers_Ledgers_Period]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Budget_Dis_Vouchers_Ledgers_Period] (@LrCode varchar(42), @Start datetime, @End datetime, @ActualsCutOff datetime, @CmCode varchar(12))  

RETURNS @RetTable TABLE
	([DocDate] [datetime],
	[DocNo] [int],
	[RefNo] [varchar] (30),	
	[VrRoute] [varchar] (42),	
	[VoucherName] [varchar] (50),
	[Particulars] [varchar] (50),	
	[Debit] [money],
	[Credit] [money],
	[ClosingBalance] [money]
	)


 AS  

BEGIN 
		
	Declare @OPBal money
	Select @OPBal=dbo.fn_FAS_Budget_LedgerOpBalance(@LrCode, @Start, @ActualsCutOff, '0', @CmCode)

	Insert into @RetTable

		Select DocDate,  DocNo, RefNo, VrRoute, VoucherName, n1.LedgerName as Particulars, Debit, Credit, CB as ClosingBalance
		from
		
			(Select m.VrRoute, m.DocDate, m.VoucherName, m.DocNo, m.RefNo, 
				isNull((Select Top 1 m1.LrCode from dbo.fn_FAS_Budget_VoucherTranSub(@ActualsCutOff, @CmCode) m1 
							Where m1.DocDate=m1.DocDate and m1.DocNo=m.DocNo and m1.VrRoute=m.VrRoute and m1.LrCode<>m.LrCode), m.LrCode) as Particulars,
				m.Debit, m.Credit, m.LrCode,
				isNull((Select Sum(DrAmt-CrAmt) from dbo.fn_FAS_Budget_VoucherTranSub_Lr(@LrCode, @ActualsCutOff, @CmCode) d 
					Where (d.DocDate Between @Start and @End)
						and ((d.docDate < m.DocDate) or ((d.DocDate=m.DocDate) and (d.VrRoute < m.VrRoute or (d.VrRoute=m.VrRoute and d.DocNo<=m.DocNo))))
						 and d.CompCode=m.CompCode
				), 0)  + @OpBal as CB
			from	
				(Select top 100 Percent  a.VrRoute, a.DocDate, c.VoucherName, a.DocNo,
					Case When LTrim(RTrim(a2.Ref))='' then b.RefType+':'+Convert(varchar, b.RefNo) else a2.Ref end as RefNo,  
					a.DrAmt as Debit, a.CrAmt as Credit, a.LrCode, a.CompCode
				from dbo.fn_FAS_Budget_VoucherTranSub_Period_Lr(@LrCode, @Start, @End, @ActualsCutOff, @CmCode) a
				Left Outer Join dbo.fn_FAS_Budget_VoucherTranMast_Period_Lr(@LrCode, @Start, @End, @ActualsCutOff, @CmCode) a2
				On a.VrRoute=a2.VrRoute and a.DocDate=a2.DocDate and a.DocNo=a2.DocNo and a.CompCode=a2.CompCode
				Left Outer Join FAS_VoucherTranRef b
				On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode and a.DocDate=b.DocDate and a.DocType=b.DocType
				Left Outer Join FAS_Budget_VoucherMaster c On a.VrRoute=c.VrRoute+c.VrWidth and a.CompCode=c.CompCode
				Order by a.DocDate,  a.DocNo
				)  m
			) n
		Left Outer Join FAS_Budget_LedgerMaster n1 On n.Particulars=n1.LedgerCode 
		Where n1.CompCode=@CmCode
		Order by DocDate, VrRoute, DocNo					

	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Budget_Dis_Vouchers_Vouchers]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Budget_Dis_Vouchers_Vouchers] (@Route varchar(42), @IncludeSubVouchers bit, @FromDate datetime, @ToDate datetime, @PrStart datetime, @PrEnd datetime, @ActualsCutOff datetime, @CmCode varchar(12))  

RETURNS @RetTable TABLE
	([VrRoute] [varchar] (42),	
	[DocDate] [datetime],
	[Particulars] [varchar] (50),	
	[RefNo] [varchar] (50),	
	[VrNo] [int],	
	[TranAmt] [money]
	)

 AS  

BEGIN 	
	
	If Len(@Route)=0  or @Route = '0'
		Begin
		Insert into @RetTable
			Select a.VrRoute, a.DocDate, Case When a2.isCancelled='1' Then 'CANCELLED' Else b.LedgerName End as Particulars,
				isNull(a2.Ref, '') as RefNo, a.DocNo as VrNo, isNull(Sum(a.DrAmt), 0) as TranAmt
			From dbo.fn_FAS_Budget_VoucherTranMast_Period(@FromDate, @ToDate, @ActualsCutOff, @CmCode) a2
			Left Outer Join dbo.fn_FAS_Budget_VoucherTranSub_Period(@FromDate, @ToDate, @ActualsCutOff, @CmCode) a
				On a.DocNo=a2.DocNo and a.DocDate=a2.DocDate and a.VrRoute=a2.VrRoute and a.VTSNo=1
			Left Outer Join FAS_Budget_LedgerMaster b
				On a.LrCode=b.LedgerCode and a.CompCode=b.CompCode
			Where (a.DocDate between @PrStart and @PrEnd)
			Group by a.VrRoute, a.DocDate, a.DocNo, a2.Ref, b.LedgerName, a2.isCancelled 
			--Order by a2.DocDate, VrNo
		End
	Else
		If @Route='07'
			Begin
				Insert into @RetTable
					Select a.VrRoute, a.DocDate, 
						Case When a.isCancelled='1' Then 'CANCELLED' Else c.LedgerName End as Particulars,
							a.Ref as RefNo, a.DocNo as VrNo, isNull(Sum(b.DrAmt), 0) as TranAmt
					From FAS_MEM_VoucherTranMast a 
					Left Outer Join FAS_MEM_VoucherTranSub b
						On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode and b.VTSNo=1
					Left Outer Join FAS_LedgerMaster c
						On b.LrCode=c.LedgerCode and a.CompCode=c.CompCode
					Where (a.DocDate between @FromDate and @ToDate) and (a.DocDate between @PrStart and @PrEnd) and a.CompCode=@CmCode
					Group by a.VrRoute, a.DocDate, a.DocNo, a.Ref, a.isCancelled, c.LedgerName
					--Order by a.DocDate, a.DocNo
			End	
		Else
			Begin
				If @IncludeSubVouchers = '1'
					Begin
						Insert into @RetTable
							Select a.VrRoute, a.DocDate, Case When a2.isCancelled='1' Then 'CANCELLED' Else b.LedgerName End as Particulars,
									isNull(a2.Ref, '') as RefNo, a.DocNo as VrNo, isNull(Sum(a.DrAmt), 0) as TranAmt
							From dbo.fn_FAS_Budget_VoucherTranMast_Period_VrSub(@Route, @FromDate, @ToDate, @ActualsCutOff, @CmCode) a2
							Left Outer Join dbo.fn_FAS_Budget_VoucherTranSub_Period_VrSub(@Route, @FromDate, @ToDate, @ActualsCutOff, @CmCode) a 
								On a.DocNo=a2.DocNo and a.DocDate=a2.DocDate and a.VrRoute=a2.VrRoute and a.VTSNo=1
							Left Outer Join FAS_Budget_LedgerMaster b
								On a.LrCode=b.LedgerCode and a.CompCode=b.CompCode
							Where (a.DocDate between @PrStart and @PrEnd)
							Group by a.VrRoute, a.DocDate, a.DocNo, a2.Ref, a2.isCancelled, b.LedgerName
							--Order by DocDate, VrNo
					End		
				Else
					Begin
						Insert into @RetTable
							Select a.VrRoute, a.DocDate, Case When a2.isCancelled='1' Then 'CANCELLED' Else b.LedgerName End as Particulars,
								isNull(a2.Ref, '') as RefNo, a.DocNo as VrNo, isNull(Sum(a.DrAmt), 0) as TranAmt
							From dbo.fn_FAS_Budget_VoucherTranMast_Period_Vr(@Route, @FromDate, @ToDate, @ActualsCutOff, @CmCode) a2
							Left Outer Join dbo.fn_FAS_Budget_VoucherTranSub_Period_Vr(@Route, @FromDate, @ToDate, @ActualsCutOff, @CmCode) a 
								On a.DocNo=a2.DocNo and a.DocDate=a2.DocDate and a.VrRoute=a2.VrRoute and a.VTSNo=1
							Left Outer Join FAS_Budget_LedgerMaster b
								On a.LrCode=b.LedgerCode and a.CompCode=b.CompCode
							Where (a.DocDate between @PrStart and @PrEnd)
							Group by a.VrRoute, a.DocDate, a.DocNo, a2.Ref, a2.isCancelled, b.LedgerName
							--Order by DocDate, VrNo
					End	

			End
	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Budget_Group_SubGroupLedger_CashBank_CB]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Budget_Group_SubGroupLedger_CashBank_CB] (@PrStart datetime, @Start datetime, @End datetime, @ActualsCutOff datetime, @CmCode varchar(12))  

RETURNS @RetTable TABLE
	([Master] [varchar](10),
	[Path] [varchar](42),
	[Type] [varchar] (10),
	[Code] [int],
	[Particulars] [varchar] (100),
	[OpBalance] [money],
	[DrAmt] [money],
	[CrAmt] [money],
	[ClosingBalance] [money]
	)

 AS  

BEGIN 
	
	Insert into @RetTable

		Select '', a.LrRoute, 'Ledger', a.LedgerCode, a.LedgerName, a.OpBalance as OBAmt, isNull(b.TranDrAmt, 0) as DrAmt, isNull(b.TranCrAmt, 0) as CrAmt,
			(a.OpBalance + isNull(b.TranDrAmt, 0) - isNull(b.TranCrAmt, 0)) as CBAmt
		from dbo.fn_FAS_Budget_AllOpBalance(@Start, @ActualsCutOff, '0', '1',  @CmCode) a Left Outer Join
			(Select LrCode, Sum(DrAmt) as TranDrAmt, Sum(CrAmt) as TranCrAmt, CompCode
			from dbo.fn_FAS_VoucherTranSub_Period(@Start, @End, @ActualsCutOff, @CmCode)
			Group by LrCode, CompCode) b
		On a.LedgerCode=b.LrCode
		Where Left(a.LrRoute, 4) in ('0201', '0202', '0B01') and a.CompCode=@CmCode


	Insert into @RetTable

		Select '', a.GrRoute+a.GrWidth, 'Group', a.GroupCode, a.GroupName, isNull(Sum(b.OpBalance), 0) as OBAmt,
			 isNull(Sum(b.DrAmt), 0) as DrAmt, isNull(Sum(b.CrAmt), 0) as CrAmt, isNull(Sum(ClosingBalance), 0) as CBAmt
		from FAS_GroupMaster a Left Outer Join @RetTable b
		On a.GrRoute+a.GrWidth = Left(b.Path, Len(a.GrRoute+a.GrWidth))
		Where Left(a.GrRoute+a.GrWidth, 4) in ('0201', '0202', '0B01') and a.CompCode=@CmCode
		Group by a.GrRoute+a.GrWidth, a.GroupName, a.GroupCode


	Delete @RetTable
	Where OpBalance=0 and DrAmt=0 and CrAmt=0 and ClosingBalance=0

	Update @RetTable Set Master=Case When Left(Path, 2)  in ('02', '09', '0A', '0C') Then '00' When Left(Path, 2) in ('01', '03', '04', '0B', '0F') Then '01'
						When Left(Path, 2) in ('06', '08', '0E') Then '02' When Left(Path, 2) in ('05', '07', '0D') Then '03' Else '04' End


	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Budget_Group_SubGroupLedger_CB]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Budget_Group_SubGroupLedger_CB] (@GrPath varchar(42), @PrStart datetime, @Start datetime, @End datetime, @ActualsCutOff datetime, @CmCode varchar(12))  

RETURNS @RetTable TABLE
	([Master] [varchar](10),
	[Path] [varchar](42),
	[Type] [varchar] (10),
	[Code] [int],
	[Particulars] [varchar] (100),
	[OpBalance] [money],
	[DrAmt] [money],
	[CrAmt] [money],
	[ClosingBalance] [money]
	)

 AS  

BEGIN 
	
	Insert into @RetTable

		Select '', a.LrRoute, 'Ledger', a.LedgerCode, a.LedgerName, a.OpBalance as OBAmt, isNull(b.TranDrAmt, 0) as DrAmt, isNull(b.TranCrAmt, 0) as CrAmt,
			(a.OpBalance + isNull(b.TranDrAmt, 0) - isNull(b.TranCrAmt, 0)) as CBAmt
		from dbo.fn_FAS_Budget_AllOpBalance(@Start, @ActualsCutOff, '0',  '1', @CmCode) a Left Outer Join
			(Select LrCode, Sum(DrAmt) as TranDrAmt, Sum(CrAmt) as TranCrAmt, CompCode
			from dbo.fn_FAS_Budget_VoucherTranSub_Period(@Start, @End, @ActualsCutOff, @CmCode)
			Group by LrCode, CompCode) b
		On a.LedgerCode=b.LrCode
		Where Left(a.LrRoute, Len(@GrPath))=@GrPath and a.CompCode=@CmCode


	Insert into @RetTable

		Select '', a.GrRoute+a.GrWidth, 'Group', a.GroupCode, a.GroupName, isNull(Sum(b.OpBalance), 0) as OBAmt,
			 isNull(Sum(b.DrAmt), 0) as DrAmt, isNull(Sum(b.CrAmt), 0) as CrAmt, isNull(Sum(ClosingBalance), 0) as CBAmt
		from FAS_GroupMaster a Left Outer Join @RetTable b
		On a.GrRoute+a.GrWidth = Left(b.Path, Len(a.GrRoute+a.GrWidth))
		Where Left(a.GrRoute+a.GrWidth, Len(@GrPath))=@GrPath and a.CompCode=@CmCode
		Group by a.GrRoute+a.GrWidth, a.GroupName, a.GroupCode


	Delete @RetTable
	Where OpBalance=0 and DrAmt=0 and CrAmt=0 and ClosingBalance=0

	Update @RetTable Set Master=Case When Left(Path, 2)  in ('02', '09', '0A', '0C') Then '00' When Left(Path, 2) in ('01', '03', '04', '0B', '0F') Then '01'
						When Left(Path, 2) in ('06', '08', '0E') Then '02' When Left(Path, 2) in ('05', '07', '0D') Then '03' Else '04' End


	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Budget_GroupClosingBalance_All]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Budget_GroupClosingBalance_All] (@PrStart datetime, @RptDate datetime, @ActualsCutOff datetime, @IncludeSubGroups bit, @CmCode varchar(12))  

RETURNS @RetTable TABLE
	([Master] [varchar](10),
	[Path] [varchar](42),
	[Type] [varchar] (10),
	[Code] [int],
	[Particulars] [varchar] (100),
	[ClosingBalance] [money]
	)

 AS  

BEGIN 

	Insert into @RetTable

		Select '', a.LrRoute, 'Ledger', a.LedgerCode, a.LedgerName, (a.OpBalance+isNull(b.TranCBAmt, 0)) as CBAmt
		from FAS_Budget_LedgerMaster a Left Outer Join
			(Select LrCode, Sum(DrAmt-CrAmt) as TranCBAmt, CompCode
			from dbo.fn_FAS_Budget_VoucherTranSub_UpTo(@RptDate, @ActualsCutOff, @CmCode)
			Group by LrCode, CompCode) b
		On a.LedgerCode=b.LrCode
		Where a.CompCode=@CmCode and Left(a.LrRoute, 4)<>'0205'


	Insert into @RetTable
		
		Select '', '0205', 'Ledger', 0, 'Closing Stock', Sum(ClosingStock)
		from dbo.fn_FAS_Budget_StockValue(@PrStart, @RptDate, @ActualsCutOff, @CmCode)


	if @IncludeSubGroups='1'
		Begin

			Insert into @RetTable
		
				Select '', a.GrRoute+a.GrWidth, 'Group', a.GroupCode, a.GroupName,  isNull(Sum(ClosingBalance), 0) as CBAmt
				from FAS_GroupMaster a Left Outer Join @RetTable b
				On a.GrRoute+a.GrWidth = Left(b.Path, Len(a.GrRoute+a.GrWidth))
				Where a.CompCode=@CmCode
				Group by a.GrRoute+a.GrWidth, a.GroupName, a.GroupCode
		End
	else
		Begin

			Insert into @RetTable
		
				Select '', a.GrRoute+a.GrWidth, 'Group', a.GroupCode, a.GroupName, isNull(Sum(ClosingBalance), 0) as CBAmt
				from FAS_GroupMaster a Left Outer Join @RetTable b
				On a.GrRoute+a.GrWidth = b.Path
				Where a.CompCode=@CmCode
				Group by a.GrRoute+a.GrWidth, a.GroupName, a.GroupCode
		End

	Delete @RetTable
	Where (Type='Ledger' or ClosingBalance=0)


	Update @RetTable Set Master=Case When Left(Path, 2)  in ('02', '09', '0A', '0C') Then '00' When Left(Path, 2) in ('01', '03', '04', '0B', '0F') Then '01'
						When Left(Path, 2) in ('06', '08', '0E') Then '02' When Left(Path, 2) in ('05', '07', '0D') Then '03' Else '04' End


	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Budget_Rpt_GroupLedgers]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Budget_Rpt_GroupLedgers] (@RptType char(1), @CmCode varchar(12))  
--@RptType Takes Value 'M' for Expand to All Levels, 'S' for Single Level,  'L' for Ledgers only, All Other for Abstract - only top level groups - you may use 'A'
-- 'T' for Expand All Ledgers with Top Level Groups Only

RETURNS @RetTable TABLE
	([Path] [varchar](42),
	[Type] [varchar] (10),
	[Code] [int],
	[Particulars] [varchar] (100)
	)

 AS  

BEGIN 
	
	If @RptType='L'	--For Ledgers Only options no need to update the groups

		Begin

			Insert into @RetTable
	
				Select LrRoute Path, 'Ledger' as Type, LedgerCode, LedgerName Particulars
				From FAS_Budget_LedgerMaster 	
				Where CompCode=@CmCode
		End

	Else

		Begin

			Insert into @RetTable

				Select Path, Type, Code, Particulars
	  		From FAS_Budget_GroupLedgers
		  	Where CompCode=@CmCode

	
			If @RptType='S'		--Single Level Expand
				Begin
					Delete @RetTable
					Where  (Type = 'Ledger'  and Len(Path) > 2) or (Type='Group' and Len(Path) > 4)	
				End
			Else
				If @RptType<>'M'	--If it is not multi level expand then it should be Abstract Report
					Begin 
						Delete @RetTable
							Where  Not ((Type='Group' and Len(Path) = 2) or (Type='Ledger' and Path in ('00', 'ZZ')))
					End
		
		End

	Insert into @RetTable

		Select 'ZZ', 'Group', 0, 'Diff. in Opening Balance'
		
	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Budget_Rpt_GroupsLedgers_TrialBalance]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Budget_Rpt_GroupsLedgers_TrialBalance] (@RptType char(1), @isZeroCB bit, @PrStart datetime, @PrEnd datetime, @ActualsCutOff datetime, @CmCode varchar(12))  
	
/*  @RptType - G refers Group Only, L refers Ledger Only, D refers Single Level Expansion, E refers All level Expansion */

RETURNS @RetTable TABLE
	([Master] [varchar](10),
	[Path] [varchar](42),
	[Type] [varchar] (10),
	[Code] [int],
	[Particulars] [varchar] (100),
	[OB_Dr] [varchar](20),
	[OB_Cr] [varchar](20),
	[Tran_Dr] [varchar](20),
	[Tran_Cr] [varchar](20),
	[CB_Dr] [varchar](20),
	[CB_Cr] [varchar](20)
	)
AS  

BEGIN 

	Declare @CallTrialBalanceType char(1)
	If @RptType='G'
		Select @CallTrialBalanceType='A'
	Else
		If @RptType='D'
			Select @CallTrialBalanceType='S'
		Else
			If @RptType='L'
				Select @CallTrialBalanceType='L'
			Else
				Select @CallTrialBalanceType='M'

	Insert into @RetTable

		Select Master, Path, Type, Code, Particulars, OB_Dr, OB_Cr, Tran_Dr, Tran_Cr,  CB_Dr, CB_Cr
		From 
			(Select Master, Path, Type, Code, Case @RptType When 'L' Then Particulars Else Case Type when 'Master' then Particulars
			 				        when 'Group' then Space(Len(Path)) + Particulars
			                                                             when 'Ledger' then space(Len(Path))+'    '+Particulars End End as Particulars,
/*
					Case sign(OpBalance) When 1 Then OpBalance Else 0 End as OB_Dr,
					Case sign(OpBalance) When -1 Then -OpBalance Else 0 End as OB_Cr,

					Case sign(DrAmt) When 0 Then 0 Else DrAmt  End as Tran_Dr, 
					Case sign(CrAmt) When 0 Then 0 Else CrAmt End as Tran_Cr, 
	
					Case sign(ClosingBalance) When 1 Then  ClosingBalance Else 0 End as CB_Dr, 
					Case sign(ClosingBalance) When -1 Then  -ClosingBalance Else 0 End as CB_Cr
*/

					Case When OpBalance > 1  Then Convert(varchar, OpBalance) Else '' End as OB_Dr, 
					Case When OpBalance < 1  Then Convert(varchar, -OpBalance) Else '' End as OB_Cr, 
					
					Case When DrAmt = 0  Then '' Else Convert(varchar, DrAmt)  End as Tran_Dr, 
					Case When CrAmt = 0  Then '' Else Convert(varchar, CrAmt) End as Tran_Cr, 
					
					Case When ClosingBalance > 0  Then Convert(varchar, ClosingBalance) Else '' End as CB_Dr, 
					Case When ClosingBalance < 0  Then Convert(varchar, -ClosingBalance) Else '' End as CB_Cr
			
			From [dbo].[fn_FAS_Budget_Rpt_TrialBalance] (@CallTrialBalanceType, @PrStart, @PrEnd, @ActualsCutOff, @CmCode) 
			
			)x  Order by Master, Path, Type, Particulars
/*	
			if @RptType = 'G' --Groupwise Summary
				Delete @RetTable
					Where Type = 'Ledger' 			
*/
			if @RptType = 'L' --Ledgerwise Summary
				Delete @RetTable
					Where Type =  'Group'  

			if @isZeroCB = '0' --Zero balance	
				Delete @RetTable
					 Where (CB_Cr+ CB_Dr) = ''		
			

		
	Return


END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Budget_Rpt_GroupSummary]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Budget_Rpt_GroupSummary] (@GrRoute varchar(42), @RptType varchar(1), @isAsPerBalanceSheet bit, @Start datetime, @End datetime, @ActualsCutOff datetime, @CmCode varchar(12))  
--@RptType Takes Value 'M' for Expand to All Levels, 'S' for Single Level,  'L' for Ledgers only, All Other for Abstract - only top level groups - you may use 'A'
-- 'T' for Expand All Ledgers with Top Level Groups Only

RETURNS @RetTable TABLE
	([Master] [varchar](10),
	[Path] [varchar](42),
	[Type] [varchar] (10),
	[Code] [int],
	[Particulars] [varchar] (100),
	[OpBalance] [money],
	[DrAmt] [money],
	[CrAmt] [money],
	[ClosingBalance] [money]
	)
 AS  

BEGIN 
	
	Declare @RouteLn int
	Select @RouteLn=Len(@GrRoute)


	If  @isAsPerBalanceSheet = '1' and (@GrRoute='02' or @GrRoute like '0205%')
		Begin
			Insert into @RetTable
		
				Select Master, Path, Type, Code, Particulars, OpBalance, DrAmt, CrAmt, Amount									
				From (
						Select Master, Path, Type, Code, Particulars, OpBalance, DrAmt, CrAmt, ClosingBalance as Amount  
						from dbo.fn_FAS_Budget_Rpt_TrialBalance('M', @Start, @End, @ActualsCutOff, @CmCode)
						where Left(Path, 2) in ('02')  and (Path Not Like '0205%')
						
						Union All
				
						Select '00', '0205' as Path, 'Group' as Type,  9999 as Code, 'STOCK-IN-HAND'  as Particulars, Sum(OpeningStock), 0, 0,  Sum(-ClosingStock)
						from dbo.fn_FAS_Budget_StockValue (@Start, @End, @ActualsCutOff, @CmCode)
				
						Union All
				
						Select '00', '0205', 'Ledger' as Type,  9999 as Code, isNull(b.LedgerName, '')   as Particulars, OpeningStock, 0, 0, -ClosingStock
						From dbo.fn_FAS_Budget_StockValue (@Start, @End, @ActualsCutOff, @CmCode) a 
						Left Outer Join FAS_LedgerMaster b On a.LedgerCode=b.LedgerCode and a.CompCode=b.CompCode
						where ClosingStock<>0
			
					)M
					Order by Path, Type	
		
					--To reduce the default OpeningStock added in Current Assets and Add the Closing Stock
					Update @RetTable Set ClosingBalance= ClosingBalance+(Select Sum(ClosingStock-OpeningStock) 
					From  dbo.fn_FAS_Budget_StockValue (@Start, @End, @ActualsCutOff, @CmCode))
					Where Path='02' and Type='Group'
		End
	Else
		Begin
			Insert into @RetTable
		
				Select * from dbo.fn_FAS_Budget_Rpt_TrialBalance('M', @Start, @End, @ActualsCutOff, @CmCode)
		End

/*
	Delete @RetTable
	Where OpBalance=0 and DrAmt=0 and CrAmt=0 and ClosingBalance=0
*/

	Delete @RetTable
		Where (Path not like @GrRoute+'%')	


	If @RptType='L'		--For Ledgers Only options no need to update the groups
		Begin
			Delete @RetTable
				Where  (Type='Group') 
		End
	Else
		If @RptType='S'		--Single Level Expand
			Begin
				Delete @RetTable
				Where  (Type = 'Ledger'  and Len(Path) > @RouteLn) or (Type='Group' and Len(Path) > @RouteLn+2)
			End
		Else
			If @RptType='T'		--All Ledgers with Top Level Groups Only
				Begin
					Delete @RetTable
						Where  (Type='Group' and Path <> @GrRoute) 
				End

			Else
				If @RptType<>'M'	--If it is not multi level expand then it should be Abstract Report
					Begin 
						Delete @RetTable
							Where Not (Type='Group' and Path=@GrRoute)
					End
				
	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Budget_Rpt_TrialBalance]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Budget_Rpt_TrialBalance] (@RptType char(1), @Start datetime, @End datetime, @ActualsCutOff datetime, @CmCode varchar(12))  
--@RptType Takes Value 'M' for Expand to All Levels, 'S' for Single Level,  'L' for Ledgers only, All Other for Abstract - only top level groups - you may use 'A'
-- 'T' for Expand All Ledgers with Top Level Groups Only

RETURNS @RetTable TABLE
	([Master] [varchar](10),
	[Path] [varchar](42),
	[Type] [varchar] (10),
	[Code] [int],
	[Particulars] [varchar] (100),
	[OpBalance] [money],
	[DrAmt] [money],
	[CrAmt] [money],
	[ClosingBalance] [money]
	)

 AS  

BEGIN 
	

	Insert into @RetTable

		Select '', LrRoute, 'Ledger', LedgerCode, LedgerName, OBAmt, DrAmt, CrAmt, (OBAmt+DrAmt-CrAmt) as CBAmt
		from
			(Select a.LrRoute, a.LedgerCode, a.LedgerName, a.OpBalance as OBAmt, 
			isNull(Sum(DrAmt), 0) as DrAmt, isNull(Sum(CrAmt), 0) as CrAmt
			From dbo.fn_FAS_Budget_AllOpBalance(@Start, @ActualsCutOff, '0', '1', @CmCode) a 
			Left Outer Join dbo.fn_FAS_Budget_VoucherTranSub_Period(@Start, @End, @ActualsCutOff, @CmCode) b
			On a.LedgerCode=b.LrCode and a.CompCode=b.CompCode
			Group by a.LrRoute, a.LedgerCode, a.LedgerName, a.OpBalance
			) x

/*
	Delete @RetTable
	Where OpBalance=0 and DrAmt=0 and CrAmt=0 and ClosingBalance=0
*/

	If @RptType<>'L'	--For Ledgers Only options no need to update the groups
		Begin

			If @RptType='T'		--For this Option Group Total will be the sum of direct ledgers only
				Begin
					Insert into @RetTable
			
						Select '', a.GrRoute+a.GrWidth, 'Group', a.GroupCode, a.GroupName, isNull(Sum(b.OpBalance), 0) as OBAmt,
							 isNull(Sum(b.DrAmt), 0) as DrAmt, isNull(Sum(b.CrAmt), 0) as CrAmt, isNull(Sum(ClosingBalance), 0) as CBAmt
						from FAS_GroupMaster a Left Outer Join @RetTable b
						On a.GrRoute+a.GrWidth = b.Path
						Where a.CompCode=@CmCode
						Group by a.GrRoute+a.GrWidth, a.GroupName, a.GroupCode
				End
			Else
				Begin
					Insert into @RetTable
				
						Select '', a.GrRoute+a.GrWidth, 'Group', a.GroupCode, a.GroupName, isNull(Sum(b.OpBalance), 0) as OBAmt,
							 isNull(Sum(b.DrAmt), 0) as DrAmt, isNull(Sum(b.CrAmt), 0) as CrAmt, isNull(Sum(ClosingBalance), 0) as CBAmt
						from FAS_GroupMaster a Left Outer Join @RetTable b
						On a.GrRoute+a.GrWidth = Left(b.Path, Len(a.GrRoute+a.GrWidth))
						Where a.CompCode=@CmCode
						Group by a.GrRoute+a.GrWidth, a.GroupName, a.GroupCode
				End
		/*	
			Delete @RetTable
			Where OpBalance=0 and DrAmt=0 and CrAmt=0 and ClosingBalance=0
		*/


			If @RptType='S'		--Single Level Expand
				Begin
					Delete @RetTable
					Where  (Type = 'Ledger'  and Len(Path) > 2) or (Type='Group' and Len(Path) > 4)	
				End
			Else
				If @RptType<>'M'	--If it is not multi level expand then it should be Abstract Report
					Begin 
						Delete @RetTable
							Where  Not ((Type='Group' and Len(Path) = 2) or (Type='Ledger' and Path in ('00', 'ZZ')))
					End
		
		End

	Insert into @RetTable

		Select '', 'ZZ', 'Group', 0, 'Diff. in Opening Balance', Isnull(-Sum(OpBalance), 0) as Amt1, 0, 0, IsNull(-Sum(OpBalance), 0)
		from dbo.fn_FAS_Budget_AllOpBalance(@Start, @ActualsCutOff, '0', '1', @CmCode) 

/*
	Delete @RetTable
	Where OpBalance=0 and DrAmt=0 and CrAmt=0 and ClosingBalance=0
*/



	Update @RetTable Set Master=Case When Left(Path, 2)  in ('02', '09', '0A', '0C') Then '00' When Left(Path, 2) in ('01', '03', '04', '0B', '0F') Then '01'
						When Left(Path, 2) in ('06', '08', '0E') Then '02' When Left(Path, 2) in ('05', '07', '0D') Then '03' Else '04' End


	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Budget_StockValue]    Script Date: 17/06/2026 11:38:43 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Budget_StockValue] (@PrStart datetime, @RptDate datetime, @ActualsCutOff datetime, @CmCode varchar(12))  

RETURNS @Stock TABLE
	(LedgerCode	int,
	OpeningStock	money,
	ClosingStock	money,
	CompCode	varchar(12))
		
AS  

BEGIN 

	Insert into @Stock		
/*
		Select LedgerCode, Case When OpStock=0 and ClStock > 0 Then ClStock Else OpStock End, Case When ClStock=0 and OpStock > 0 Then OpStock Else ClStock End, @CmCode
		From
			(		*/
			Select isNull(m.LedgerCode, n.LedgerCode) as LedgerCode, isNull(m.StockValue, 0) as OpStock, isNull(n.StockValue, isNull(m.StockValue, 0)) as ClStock, @CmCode
			from
				(Select a.LedgerCode, a.StockValue, a.CompCode
				from dbo.fn_FAS_Budget_StockEntry(@ActualsCutOff, @CmCode) a
				Inner Join
					(Select LedgerCode,  Max(StockDate) as StockDate, CompCode
					from dbo.fn_FAS_Budget_StockEntry(@ActualsCutOff, @CmCode) 
					Where StockDate < @PrStart and CompCode=@CmCode
					Group by LedgerCode, CompCode
					) b
				On a.LedgerCode=b.LedgerCode and a.StockDate=b.StockDate and a.CompCode=b.CompCode
				Where a.CompCode=@CmCode
				) m
		
			Full Outer Join
		
				(Select a.LedgerCode, a.StockValue, a.CompCode
				from dbo.fn_FAS_Budget_StockEntry(@ActualsCutOff, @CmCode) a
				Inner Join
					(Select LedgerCode,  Max(StockDate) as StockDate, CompCode
					from dbo.fn_FAS_Budget_StockEntry(@ActualsCutOff, @CmCode)  
					Where StockDate <= @RptDate and CompCode=@CmCode
					Group by LedgerCode, CompCode
					) b
				On a.LedgerCode=b.LedgerCode and a.StockDate=b.StockDate and a.CompCode=b.CompCode
				Where a.CompCode=@CmCode
				) n
		
			On m.LedgerCode=n.LedgerCode and m.CompCode=n.CompCode
--		) x

	Return

END
GO

