CREATE    FUNCTION [dbo].[fn_FAS_BudgetPlan_Dtl] (@AsOnDate datetime, @RptDate datetime, @CompCode Varchar(12))  


RETURNS @RetTable TABLE

	(	
	PlanPeriod	datetime,
	PlanFor		int,
	PlanStart	datetime,	
	IsSales		bit,
	IsPurchase	bit,
	isDepreciation	bit,
	UserID		varchar(10),
	CompCode	varchar(12),
	Transtamp	datetime
	)


 AS  

BEGIN 



	Insert @RetTable
		
		Select * From FAS_BudgetPlan_Dtl a
		Where a.TranStamp  =  (Select Max(b.Transtamp) From FAS_BudgetPlan_Dtl b
						 Where b.Transtamp<=@AsOndate and a.PlanPeriod=b.PlanPeriod and a.PlanFor=b.PlanFor 
					           		and a.PlanStart=b.PlanStart and a.CompCode=b.CompCode						
					)
			and CompCode=@CompCode


	Return




/*
	Insert @RetTable

		Select * From FAS_Budget_Hdr a
		Where a.RevNo = (Select Max(b.RevNo) From FAS_Budget_Hdr b Where b.CreatedDate <= @AsOnDate 			
			and a.PlanFor = b.PlanFor and a.PlanPeriod = b.PlanPeriod and a.PeriodSplit = b.PeriodSplit
			and a.CompCode = b.CompCode		
			)
		and ((a.EffStatus='1' and a.EffDate <= @RptDate) or (a.EffStatus='0' and a.EffDate >= @RptDate))
			 and a.CompCode = @CompCode

	Return 
*/




END
GO

