CREATE FUNCTION [dbo].[fn_FAS_CentralExcise] (@ItemCode Varchar(20), @FromDate datetime, @ToDate datetime, @AsonDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear Varchar(20))  

RETURNS @CentralExcise TABLE
	(InvType	varchar(3),
	 InvNo		int,
	 Invdate 	datetime, 
	 ItemCode 	varchar(20),
	 ItemDesc	varchar(50),
	 UOMdecimal	 int,
	 Rate		float,
	 OBQty		float,
	 InvQty		float,
	 ED		float, 
	 ValueUsed	float, 
 	 CBQty 		float, 
	 Seq		int,
	 BranchID	varchar(3),
	 CompID	varchar(3))

AS  

BEGIN 
	
	Insert into @CentralExcise

		Select a.InvoiceType, a.InvoiceNo, a.InvoiceDate, b.ItemCode, d.ItemDesc as ItemDescription, d.UOMDecimal, b.Rate, 0 as OBQty, 
			b.InvoiceQty InvQty, (f.ResultValue) ED, g.ValueUsed, 0 as CBQty, IsNUll(h.Sequence,0)Seq, @BranchID, @CompID 
		From COM_FormulaMast_Dtl e 
		Inner Join FAS_CentralExcise_Option h 
			On e.ExprRoute = h.ExprRoute and e.ModuleCode = h.ModuleCode and (e.CompID+e.BranchID)= h.CompCode 
		Left Outer Join COM_FormulaCalc_Hdr f 
			On e.FrmID = f.FrmID and e.ExprSeq = f.ExprSeq and e.BranchID = f.BranchID and e.CompID = f.CompID 
		Left Outer Join   (	Select Distinct FrmID, ExprSeq, ModuleCode, ValueUsed, BranchID, CompID 
					From com_formulamast_block_dtl 
					Where ModuleCode = 4 and BlockType = 'Param' and BranchID = @BranchiD and CompID= @CompID
				)g 

			On f.ModuleCode = g.ModuleCode and f.FrmID = g.FrmID and f.ExprSeq = g.ExprSeq and f.BranchID = g.BranchID and f.CompID = g.CompID 
		Left Outer Join SAL_Invoice_Hdr a 
			On f.DocType = a.InvoiceType and f.DocNo = a.InvoiceNo and f.DocDate = a.InvoiceDate and f.FrmID = a.FormulaCode and f.BranchID = a.BranchID and f.CompID = a.CompID 
		Left Outer Join SAL_Invoice_Dtl b 
			On b.InvoiceDate = a.InvoiceDate and b.InvoiceNo = a.InvoiceNo and b.InvoiceType = a.InvoiceType and b.BranchID = a.BranchID and b.CompID = a.CompID 
		Left Outer Join dbo.fn_BOM_Get_Material_Inv('A',@AsonDate, @RptDate,@BranchID,@CompID)d 
			On d.ItemCode = b.ItemCode and d.BranchID = b.BranchID and d.CompID = b.CompID 
		Where e.ModuleCode = 4  and a.InvoiceDate between @FromDate and @ToDate
			and b.ItemCode = @ItemCode and e.BranchID = @BranchID and e.CompID = @CompID


		/* Declare variables for Cursor */

		Declare @cInvType Varchar(3)
		Declare @cInvNo Int
		Declare @cInvDate datetime
		Declare @cPrevInvDate datetime

		Declare curList Cursor For

		Select InvType, InvNo, InvDate, DateAdd(d, -1, InvDate) PrevInvDate
		From @CentralExcise 
		Where ItemCode = @ItemCode and BranchID = @BranchiD and CompID = @CompID	

		Open curList

		FETCH NEXT FROM curList into @cInvType, @cInvNo, @cInvDate, @cPrevInvDate

		WHILE @@FETCH_STATUS = 0		

		
			Begin

				/* Update OBQty */

				Update @CentralExcise Set OBQty =(Select Sum(CBQty) From dbo.fn_INV_AsOnDate_Stock_Item(@ItemCode, @cPrevInvDate, @RptDate,@BranchiD,@CompID,@Finyear))
				From @CentralExcise
				Where ItemCode = @ItemCode and InvDate = @cInvDate and InvType=@cInvType and InvNo=@cInvNo and BranchiD = @BranchiD and CompID = @CompID
			

				/* Update CBQty */

				Update @CentralExcise Set CBQty = (Select Sum(CBQty) From dbo.fn_INV_AsOnDate_Stock_Item(@ItemCode, @cInvDate, @RptDate,@BranchiD,@CompID,@Finyear))
				From @CentralExcise
				Where ItemCode = @ItemCode and InvDate = @cInvDate and InvType=@cInvType and InvNo=@cInvNo and BranchiD = @BranchiD and CompID = @CompID	

				Fetch Next From curList into @cInvType, @cInvNo, @cInvDate, @cPrevInvDate


			End


			Close curList
			Deallocate curList 



	
/*		Declare @PrevInvDate datetime
		Declare @InvDate datetime
	
		Declare curRec cursor for

		Select InvDate-1, InvDate From @CentralExcise Where ItemCode = @ItemCode and BranchID = @BranchiD and CompID = @CompID	
	
		open curRec

		Fetch next from curRec into @PrevInvDate, @InvDate



			While @@Fetch_Status=0

				Begin
					
					--OBQty
					Update @CentralExcise Set OBQty =(Select Sum(CBQty) From dbo.fn_INV_AsOnDate_Stock_Item(@ItemCode, @PrevInvDate, @RptDate,@BranchiD,@CompID,@Finyear))
					From @CentralExcise
					Where ItemCode = @ItemCode and InvDate = @PrevInvDate and BranchiD = @BranchiD and CompID = @CompID
				
					---CBQty
					Update @CentralExcise Set CBQty = (Select Sum(CBQty) From dbo.fn_INV_AsOnDate_Stock_Item(@ItemCode, @InvDate, @RptDate,@BranchiD,@CompID,@Finyear))
					From @CentralExcise
					Where ItemCode = @ItemCode and InvDate = @InvDate and BranchiD = @BranchiD and CompID = @CompID	
				
		
					Fetch next from curRec into @PrevInvDate, @InvDate
		
				End


		Close curRec
		Deallocate curRec

*/

	RETURN 



END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Dis_AgeingAnalysis]    Script Date: 17/06/2026 11:38:44 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Dis_AgeingAnalysis] (@LrRoute varchar(42),  @RptType char(1), @RptDate datetime, @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))  

RETURNS @RetTable TABLE
	(LrCode 	int,
	Particulars	[Varchar] (100),
	LrRoute		[Varchar](42),
	Less1		[money],
	Amount1to30	[money],
	Amount31to60	[money],
	Amount61to90	[money],
	Amount90	[money],
	PendingAmt	[money],
	AdvAmt		[money],
	TotAmt		[money],
	Type		[Varchar](10)
	)
AS  

BEGIN 

	Insert into @RetTable

			Select LrCode, Particulars, LrRoute, Less1,  Amount1to30,  Amount31to60,  Amount61to90,  Amount90,   (Less1+Amount1to30+Amount31to60+Amount61to90+Amount90) PendingAmt,  
				0, 0, 'Ledger' as Type
				--AdvAmt, (Less1+Amount1to30+Amount31to60+Amount61to90+Amount90+AdvAmt) TotAmt, 'Ledger' as Type

	From

	(	Select m.LrCode, n.LedgerName  as Particulars,  LrRoute, 
			Sum(Less1) as Less1, Sum(Amount1to30) as Amount1to30, Sum(Amount31to60) as Amount31to60, Sum(Amount61to90) as Amount61to90,
			Sum(Amount90) as Amount90--,  Sum(AdvAmt) as AdvAmt
		From FAS_LedgerMaster n

		Right Outer Join
		 (
			Select b.LrCode,  Case when Overdue < 1 then Amount else 0 End as Less1,
			  Case when Overdue between 1 and 30 then Amount else 0 End as Amount1to30,
			  Case when Overdue between 31 and 60 then Amount else 0 End as Amount31to60,
			  Case when Overdue between 61 and 90 then Amount else 0 End as Amount61to90,
			  Case when Overdue > 90 then Amount else 0 End as Amount90 --, AdvAmt
			from  
				(
					Select d.LrCode, RefNo as [Invoice No], Convert(Datetime,  RefDate, 105) as [Invoice Date], Convert(Datetime,  Dateadd(day, isNull(CreditDays, 0), RefDate) , 105) as [Due Date], 
					Amount, --AdvAmt,
					DateDiff(day, Dateadd(day, isNull(CreditDays, 0), RefDate), @RptDate) as OverDue
					from 
						(
							Select isNull(y.LrCode, z.LrCode) LrCode, isNull(y.RefNo, z.RefNo) as RefNo, 
								isNull(y.RefDate, (Select Min(x.RefDate) from FAS_BillDetails x where x.RefNo=z.RefNo and x.LrCode = z.LrCode and x.RefDate <= @RptDate and x.DocDate <= @RptDate and x.CompCode=@CmCode)) as RefDate, 
								isNull(y.CreditDays, 0) CreditDays, z.Amount--,  z.AdvAmt
							from 
								(Select LrCode, RefNo, RefDate, CreditDays from fas_billdetails 
									where Type in ('New Ref', 'Advance') and RefDate <= @RptDate and DocDate <= @RptDate and CompCode=@CmCode
								) y 
							Right Outer Join
								(Select LrCode, RefNo, Sum(Amount) as Amount
								from fas_billdetails
								where RefDate <= @RptDate and DocDate <= @RptDate and Type<>'On Acct' and CompCode=@CmCode
								group by LrCode, RefNo having sum(Amount) <> 0 ) z 
							On y.RefNo=z.RefNo and y.LrCode = z.LrCode
							Left Outer Join FAS_LedgerMaster x
							On isNull(y.LrCode, z.LrCode)=x.LedgerCode and x.CompCode=@CmCode
							Where x.isBillwise='1'
						) d
				) b		
			)m

			On n.LedgerCode = m.LrCode 	
			Where n.LrRoute Like @LrRoute+'%' and n.CompCode = @CmCode
			group by m.LrCode, LedgerName, LrRoute
		)k
		Order by LrRoute, Particulars

		Update @RetTable Set TotAmt=(Select (a.OpBalance+isNull(Sum(b.DrAmt-b.CrAmt), 0))
									From FAS_LedgerMaster a
									Left Outer Join FAS_VoucherTranSub b On a.LedgerCode=b.LrCode and a.CompCode=b.CompCode and b.DocDate<=@RptDate
									Where a.LedgerCode=m.LrCode and a.CompCode=@CmCode
									Group By a.LedgerCode, a.OpBalance) /* - PendingAmt  */
		From @RetTable m
		
		Update @RetTable Set AdvAmt=TotAmt - PendingAmt
		From @RetTable m
		

		if @RptType = 'C' -- Credit only display
			begin 
				Delete @RetTable
					Where TotAmt > 0						
			end

		if @RptType = 'D' -- Debit only display
			begin 
				Delete @RetTable
					Where TotAmt < 0						
			end
	

	Insert into @RetTable
		Select GroupCode as LrCode, GroupName as Particulars, GrRoute+GrWidth as LrRoute, 0 as Less1, 0 as Amount1to30, 0 as Amount31to60,  
			0 as Amount61to90, 0 as Amount90,  0 as PendingAmt, 0 as AdvAmt, 0 as TotAmt, 'Group' as Type 
		From FAS_GroupMaster a		
		Where Exists (Select * From @RetTable b Where a.GrRoute+a.GrWidth = b.LrRoute ) and CompCode=@CmCode 
		Order by GroupName


	Return


END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Dis_AgeingAnalysis_New]    Script Date: 17/06/2026 11:38:44 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [dbo].[fn_FAS_Dis_AgeingAnalysis_New] (@LrRoute varchar(42),  @RptType char(1), @RptDate datetime, @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))  

RETURNS @RetTable TABLE
	(LrCode 	int,
	Particulars	[Varchar] (100),
	LrRoute		[Varchar](42),
	Less1		[money],
	Amount1to30	[money],
	Amount31to60	[money],
	Amount61to90	[money],
	Amount90	[money],
	PendingAmt	[money],
	AdvAmt		[money],
	TotAmt		[money],
	Type		[Varchar](10)
	)
AS  

BEGIN 

	Declare @Sql Varchar(1000)

/*	Select @Sql = N'Insert into @RetTable

			Select LrCode, Particulars, LrRoute, Less1,  Amount1to30,  Amount31to60,  Amount61to90,  Amount90,   (Less1+Amount1to30+Amount31to60+Amount61to90+Amount90) PendingAmt,  AdvAmt, 
	 (Less1+Amount1to30+Amount31to60+Amount61to90+Amount90+AdvAmt) TotAmt, ''Ledger'' as Type

	From

	(	Select m.LrCode, n.LedgerName  as Particulars,  LrRoute, '

		/*Sum(Less1) as Less1, Sum(Amount1to30) as Amount1to30, Sum(Amount31to60) as Amount31to60, Sum(Amount61to90) as Amount61to90,
			Sum(Amount90) as Amount90,  Sum(AdvAmt) as AdvAmt*/

	sql = 	N'From FAS_LedgerMaster n
		Right Outer Join
		 ('
			/*Select b.LrCode,  AdvAmt, Case when Overdue < 1 then Amount else 0 End as Less1,
			  Case when Overdue between 1 and 30 then Amount else 0 End as Amount1to30,
			  Case when Overdue between 31 and 60 then Amount else 0 End as Amount31to60,
			  Case when Overdue between 61 and 90 then Amount else 0 End as Amount61to90,
			  Case when Overdue > 90 then Amount else 0 End as Amount90*/

		sql=	N'from  
				(
					Select d.LrCode, --RefNo as [Invoice No], Convert(Datetime,  RefDate, 105) as [Invoice Date], Convert(Datetime,  Dateadd(day, isNull(CreditDays, 0), RefDate) , 105) as [Due Date], 
					Amount, AdvAmt,
					DateDiff(day, Dateadd(day, isNull(CreditDays, 0), RefDate), @RptDate) as OverDue
					from 
						(
							Select isNull(y.LrCode, z.LrCode) LrCode, isNull(y.RefNo, z.RefNo) as RefNo, 
								isNull(y.RefDate, (Select Min(x.RefDate) from FAS_BillDetails x where x.RefNo=z.RefNo and x.LrCode = z.LrCode and x.RefDate <= @RptDate and x.CompCode=@CmCode)) as RefDate, 
								isNull(y.CreditDays, 0) CreditDays, z.Amount,  z.AdvAmt
							from 
								(Select LrCode, RefNo, RefDate, CreditDays from fas_billdetails where Type in (''New Ref'', ''Advance'') and CompCode=@CmCode
								) y 
							Right Outer Join
								(Select LrCode, RefNo, Case When Type=''On Acct'' then Sum(Amount) Else 0 End as AdvAmt,
										           Case When Type<>''On Acct'' then Sum(Amount) Else 0 End as Amount 
								from fas_billdetails
								where RefDate <= @RptDate and CompCode=@CmCode
								group by LrCode, RefNo, Type having sum(Amount) <> 0 ) z 
							On y.RefNo=z.RefNo and y.LrCode = z.LrCode
							Left Outer Join FAS_LedgerMaster x
							On isNull(y.LrCode, z.LrCode)=x.LedgerCode and x.CompCode=@CmCode
							Where x.isBillwise=''1''
						) d
				) b		
			)m

			On n.LedgerCode = m.LrCode 	
			Where n.LrRoute Like @LrRoute+''%'' and n.CompCode = @CmCode
			group by m.LrCode, LedgerName, LrRoute
		)k
		Order by LrRoute, Particulars'

*/

		if @RptType = 'C' -- Credit only display
			begin 
				Delete @RetTable
					Where TotAmt > 0						
			end

		if @RptType = 'D' -- Debit only display
			begin 
				Delete @RetTable
					Where TotAmt < 0						
			end
	

	Insert into @RetTable
		Select GroupCode as LrCode, GroupName as Particulars, GrRoute+GrWidth as LrRoute, 0 as Less1, 0 as Amount1to30, 0 as Amount31to60,  
			0 as Amount61to90, 0 as Amount90,  0 as PendingAmt, 0 as AdvAmt, 0 as TotAmt, 'Group' as Type 
		From FAS_GroupMaster a		
		Where Exists (Select * From @RetTable b Where a.GrRoute+a.GrWidth = b.LrRoute ) and CompCode=@CmCode 
		Order by GroupName


	Return


END



GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Dis_AgeingAnalysis_tmp]    Script Date: 17/06/2026 11:38:44 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Dis_AgeingAnalysis_tmp] (@LrRoute varchar(42),  @isByDueDate bit,  @RptType char(1), @RptDate datetime, @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))      
    
    
RETURNS @RetTable TABLE    
 (LrCode  int,    
 Particulars [Varchar] (100),    
 LrRoute  [Varchar](42),    
 Less30  [money],    
 Amount31to60 [money],    
 Amount61to90 [money],    
 Amount91to180 [money],    
 Amount180 [money],    
 PendingAmt [money],    
 AdvAmt  [money],    
 TotAmt  [money],    
 Type  [Varchar](10)    
 )    
AS      
    
BEGIN     
    
 Insert into @RetTable    
    
  Select LrCode, Particulars, LrRoute, Less30, Amount31to60,  Amount61to90,  Amount91to180, Amount180,   (Less30+Amount31to60+Amount61to90+Amount91to180+Amount180) PendingAmt,     
   -- 0, (Less30+Amount31to60+Amount61to90+Amount91to180+Amount180) TotAmt, 'Ledger' as Type    
   (TotAmt - (Less30+Amount31to60+Amount61to90+Amount91to180+Amount180)) as AdvAmt, TotAmt, 'Ledger' as Type    
    
 From    
    
 ( Select m.LrCode, m.Particulars,  m.LrRoute,  m.OpBalance+isNull(n.VrAmt, 0) as TotAmt,     
   Sum(Less30) as Less30, Sum(Amount31to60) as Amount31to60, Sum(Amount61to90) as Amount61to90, Sum(Amount91to180) as Amount91to180,     
   Sum(Amount180) as Amount180    
  From     
    (    
      Select b.LrCode, b.Particulars, b.LrRoute, b.OpBalance,    
      Case when OverDue <= 30 then BillAmt else 0 End as Less30,    
      Case when OverDue between 31 and 60 then BillAmt else 0 End as Amount31to60,    
      Case when OverDue between 61 and 90 then BillAmt else 0 End as Amount61to90,    
      Case when OverDue between 91 and 180 then BillAmt else 0 End as Amount91to180,    
      Case when OverDue > 180 then BillAmt else 0 End as Amount180    
      from      
    (    
     Select d.LrCode, d.Particulars, d.LrRoute, d.OpBalance, d.BillAmt,     
     DateDiff(day, Case When @isByDueDate='1' Then Dateadd(day, isNull(CreditDays, 0), RefDate) Else RefDate End, @RptDate) as OverDue    
     from     
      (    
       Select x.LedgerCode as LrCode, x.LedgerName as Particulars, x.LrRoute, x.OpBalance, isNull(y.RefNo, z.RefNo) as RefNo,     
        isNull(y.RefDate, (Select Min(x.RefDate) from FAS_BillDetails x where x.RefNo=z.RefNo and x.LrCode = z.LrCode and x.RefDate <= @RptDate and x.CompCode=@CmCode)) as RefDate,     
        isNull(y.CreditDays, 0) CreditDays, Case x.isBillwise When '1' Then z.Amount Else 0 End as BillAmt    
       from FAS_LedgerMaster x    
    
       Left Outer Join    
        (Select LrCode, RefNo, Sum(Amount) as Amount     
        from fas_billdetails    
        where DocDate <= @RptDate and CompCode=@CmCode and Type<>'On Acct'    
        group by LrCode, RefNo having sum(Amount) <> 0 ) z     
       On x.LedgerCode=z.LrCode     
    
       Full Outer Join    
        (Select LrCode, RefNo, RefDate, CreditDays from fas_billdetails m1     
        where Type in ('New Ref', 'Advance') and CompCode=@CmCode) y     
       On y.RefNo=z.RefNo and y.LrCode = z.LrCode    
    
       Where x.LrRoute Like @LrRoute+'%'  and x.CompCode=@CmCode     
      ) d    
    ) b      
   )m    
    
   Left Outer Join (Select LrCode, Sum(DrAmt-CrAmt) as VrAmt From FAS_VoucherTranSub p1    
      Where DocDate<=@RptDate and CompCode=@CmCode    
     and Exists (Select * from FAS_LedgerMaster p2 Where p1.LrCode=p2.LedgerCode and p2.CompCode=p1.CompCode and p2.LrRoute like @LrRoute+'%' )    
     Group by LrCode) n    
    On m.LrCode=n.LrCode    
       
   Group by m.LrCode, m.Particulars, m.LrRoute, m.OpBalance, n.VrAmt    
  )k    
  Where TotAmt<>0    
  Order by LrRoute, Particulars    
      
/*      
  Update @RetTable Set AdvAmt=(Select (a.OpBalance+isNull(Sum(b.DrAmt-b.CrAmt), 0))    
         From FAS_LedgerMaster a    
         Left Outer Join    
          (Select LrCode, Sum(Amount) as BillAmt From FAS_BillDetails Where Type<>'On Acct' and DocDate<=@RptDate and CompCode=@CmCode Group by LrCode) c    
         On a.LedgerCode=c.LrCode    
         Left Outer Join FAS_VoucherTranSub b On a.LedgerCode=b.LrCode and a.CompCode=b.CompCode and b.DocDate<=@RptDate    
         Where m.LrCode=a.LedgerCode and a.CompCode=@CmCode    
         Group By a.LedgerCode, a.OpBalance, c.BillAmt)-TotAmt    
  From @RetTable m    
      
  Update @RetTable Set TotAmt=TotAmt+AdvAmt    
  From @RetTable m    
*/      
      
--  Delete From @RetTable Where (PendingAmt=0 AND AdvAmt=0)    
    
  if @RptType = 'C' -- Credit only display    
   begin     
    Delete @RetTable    
     Where TotAmt > 0          
   end    
    
  if @RptType = 'D' -- Debit only display    
   begin     
    Delete @RetTable    
     Where TotAmt < 0          
   end    
     
    
 Insert into @RetTable    
  Select GroupCode as LrCode, GroupName as Particulars, GrRoute+GrWidth as LrRoute, 0 as Less1, 0 as Amount1to30, 0 as Amount31to60,      
   0 as Amount61to90, 0 as Amount90,  0 as PendingAmt, 0 as AdvAmt, 0 as TotAmt, 'Group' as Type     
  From FAS_GroupMaster a      
  Where Exists (Select * From @RetTable b Where a.GrRoute+a.GrWidth = b.LrRoute ) and CompCode=@CmCode     
  Order by GroupName    
    
    
 Return    
     
END    
    
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Dis_BalanceSheet]    Script Date: 17/06/2026 11:38:44 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Dis_BalanceSheet] (@isVertical bit,  @RptType int, @Start datetime, @End datetime, @CmCode varchar(12)) 
/*  @isVertical = 0-Horizontal Representation; 1-Vertical Representation */	
/*  @RptType = 0 refers Abstract-only groups; 1 refers expand to single level; 2 refer Subgroup with all ledgers*/

RETURNS @RetTable TABLE
	([Master] 	[varchar](10),
	[Path] 		[varchar](42),
	[Type] 		[varchar] (10),	
	[Code] 		[int],
	[Particulars] 	[varchar] (100),
	[SubAmount] 	[money],
	[TotalAmount] 	[money],
	[SortOrder] 	[int]
	)
AS  

BEGIN 

	Declare @CallTrialBalanceType char(1)
/*
	If @isSummary='1'
		Select @CallTrialBalanceType='A'
	Else
		Select @CallTrialBalanceType='S'
*/

	If @RptType='0'
		Select @CallTrialBalanceType='A'--Abstract Only Group
	if @RptType='1'
		Select @CallTrialBalanceType='S' -- Groups and 1st level Ledgers
	if @RptType='2'
		Select @CallTrialBalanceType='M'  --SubGroup with All Ledger


	Insert into @RetTable

		Select Master, Path, Type, Code,
				Case Type when 'Group' then Space(Len(Path)) + Particulars
		                           	when 'Ledger' then space(Len(Path))+'    '+Particulars End as Particulars,
							
					Case When Type='Ledger' or (Len(Path) > 2 and Type='Group') then Amount Else 0 End as SubAmt,	
					Case When Len(Path)=2 and Type='Group' then Amount Else 0 End as TotAmt, 0
	
		From     (
				Select Master, Path, Type, Code, Particulars, (ClosingBalance) as Amount  
				from dbo.fn_FAS_Rpt_TrialBalance(@CallTrialBalanceType, @Start, @End, @CmCode)
				Where Left(Path, 2) in ('01', '02', '03', '04', '09', '0A', '0B', '0C', '0F', 'ZZ')  and (Path Not Like '0205%')
				
				Union All
		
				Select '00', '0205' as Path, 'Group' as Type,  9999 as Code, 'Closing Stock'  as Particulars, Sum(ClosingStock)
				from dbo.fn_FAS_StockValue (@Start, @End, @CmCode)
		
				Union All
		
				Select '00', '0205', 'Ledger' as Type,  9999 as Code, isNull(b.LedgerName, '')   as Particulars, ClosingStock
				from dbo.fn_FAS_StockValue (@Start, @End, @CmCode) a 
				Left Outer Join FAS_LedgerMaster b 
				On a.LedgerCode=b.LedgerCode and a.CompCode=b.CompCode
				Where ClosingStock<>0
	
			)M

			Order by Path, Type	

			--To reduce the default OpeningStock added in Current Assets and Add the Closing Stock
			Update @RetTable Set TotalAmount=TotalAmount+(Select Sum(ClosingStock-OpeningStock) from  dbo.fn_FAS_StockValue (@Start, @End, @CmCode))
			Where Path='02' and Type='Group'

			
			If @RptType = '0' --Groupwise Summary
				Begin 
					Delete @RetTable
						Where  Not (Type='Group' and Len(Path) = 2)	
				End

			if @RptType = '1'
				Begin
					Delete @RetTable
						Where  (Type = 'Ledger'  and Len(Path) > 2) or (Type='Group' and Len(Path) > 4)	
				End


			--To insert Profit & Loss A/c Details
			Declare @Amount money, @isPL_GroupRequired bit

			Select @isPL_GroupRequired = '0'

			--To Insert P&L Opening Balance
			Select @Amount=isNull(dbo.fn_FAS_Profit_Loss_OB(@Start, @CmCode) , 0)

			If @Amount<>0
				Begin
					Insert into @RetTable			
						Select '', '00PO', 'Ledger', -3, '    Opening Balance', @Amount as Amount, 0, 0

					Select @isPL_GroupRequired='1'
				End

			--To Insert P&L Current Period
			Select @Amount=isNull(dbo.fn_FAS_Profit_Loss_Period(@Start, @End, @CmCode), 0)

			If @Amount<>0

				Begin
					Insert into @RetTable		
						Select '', '00PC', 'Ledger', -2, '    Current Period', @Amount as Amount, 0, 0
			
					Select @isPL_GroupRequired='1'
				End
				

			--To Insert P&L Transfered Amount
			Select @Amount= (sum(DrAmt)-sum(CrAmt))
			from FAS_VoucherTranSub 
			where DocDate between @Start and  @End and LrCode=2 and Compcode = @CmCode


			If isNull(@Amount, 0)<>0
				Begin			
					Insert into @RetTable	
						Select '', '00PT', 'Ledger', -1, '    Less Transfered', isNull(@Amount, 0) as Amount, 0, 0
				
					Select @isPL_GroupRequired='1'
				End


			--To Insert P&L Group
			If @isPL_GroupRequired='1'

				Begin
					Select @Amount=Sum(SubAmount) from @RetTable Where Path like '00%'

					If isNull(@Amount, 0)<>0				
						Insert into @RetTable			
							Select '', '00', 'Group', 0, '  PROFIT & LOSS A/C', 0, isNull(@Amount, 0), 0
					Else
						Delete from @RetTable Where Path like '00%'
				End


/*
			--To insert Profit & Loss A/c Details

			Insert into @RetTable
			
				Select '', '00PO', 'Ledger', -3, '    Opening Balance', dbo.fn_FAS_Profit_Loss_OB(@Start, @CmCode) as Amount, 0, 0
		
			Insert into @RetTable			
		
				Select '', '00PC', 'Ledger', -2, '    Current Period', dbo.fn_FAS_Profit_Loss_Period(@Start, @End, @CmCode) as Amount, 0, 0
			
				UNION ALL
			
				Select '', '00PT', 'Ledger', -1, '    Less Transfered', isnull((sum(DrAmt)-sum(CrAmt)), 0) as Amount, 0, 0
				from FAS_Voucher_Vw 
				where DocDate between @Start and  @End and LrCode=2 and Compcode = @CmCode	

			Insert into @RetTable
			
				Select '', '00', 'Group', 0, '  PROFIT & LOSS A/C', 0, Sum(SubAmount), 0
				from @RetTable
				where Path like '00%'
*/




/*  Update  SortOrder To Groups */

			Update @RetTable Set SortOrder =
				Case Path
					When '01' Then 101 
					When '0B' Then 102 
					When '03' Then 103
					When '09' Then 104
					When '0A' Then 105
					When '02' Then 106
					When '04' Then 107
					When '0C' Then 108
					When '0F' Then 109
					When '00' Then Case When TotalAmount < 0 Then 190 Else 290 End
					When 'ZZ' Then Case When TotalAmount < 0 Then 191 Else 291 End
				End
			Where Type='Group' and Len(Path) = 2 

/* Update SortOrder To SubGroups and Ledgers */

			Update @RetTable Set SortOrder=b.SortOrder
			from @RetTable a Left Outer Join (Select * from @RetTable Where Type='Group' and Len(Path) = 2) b
			On Left(a.Path, 2)=b.Path
			Where Not (a.Type='Group' and Len(a.Path) = 2)				

			If @isVertical='1'		--These are no need for horizontal representation

				Begin

					Update @RetTable Set SortOrder=SortOrder + 100
					Where Left(Path, 2) in ('09', '0A', '02', '0C')

					Update @RetTable Set SubAmount=-SubAmount, TotalAmount=-TotalAmount
--					Where SortOrder Between 201 and 299
					Where Left(Path, 2) in ('01', '03', '0B', '04', '0F')


					Update @RetTable Set SubAmount=Case When TotalAmount>0 Then SubAmount Else -SubAmount End
					Where Left(Path, 2) in ('00', 'ZZ')

					Update @RetTable Set TotalAmount =  ABS(TotalAmount) 
					Where Left(Path, 2) in ('00', 'ZZ')

					-- Initial Stage
					Insert into @RetTable  Select '',  'SF', 'Group', 0, 'SOURCE OF FUNDS', 0 , 0, 0
					Insert into @RetTable  Select '',  'AF', 'Group', 0, 'APPLICATION OF FUNDS', 0 , 0,  200
					Insert into @RetTable  Select '',  'ST', 'Group', 0, 'TOTAL', 0 , 0, 199
					Insert into @RetTable  Select '',  'AT', 'Group', 0, 'TOTAL', 0 , 0,  300

					Update @RetTable Set TotalAmount=(Select Sum(TotalAmount) from @RetTable Where SortOrder < 199)
					Where SortOrder=199

					Update @RetTable Set TotalAmount=(Select Sum(TotalAmount) from @RetTable Where SortOrder > 200)
					Where SortOrder=300

				End

	Return


END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Dis_BalanceSheet_Hor]    Script Date: 17/06/2026 11:38:44 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Dis_BalanceSheet_Hor] (@RptType char(1), @RptDate datetime, @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))  
/*  Horizontal Representation BalanceSheet */	
/*  @RptType - S refers Group Only  and D refers Detailed or Both Ledger and Group */

RETURNS @RetTable TABLE
	([Master] [varchar](2),
	[Path] [varchar](42),
	[Type] [varchar] (10),	
	[Code] int,
	[Particulars] [varchar] (100),
	[SubAmt] [money],
	[TotalAmt] [money],	
	[SortOrder] int
	)
AS  

BEGIN 

	Insert into @RetTable

			Select Master, Path, Type, Code, Case Type when 'Group' then Space(Len(Path)) + Particulars
	                                                             	when 'Ledger' then space(Len(Path))+'    '+Particulars End as Particulars,
						
						Case When Type='Ledger' or (Len(Path) > 2 and Type='Group') then Amt1 Else 0 End as SubAmt,	
						Case When Len(Path)=2 and Type='Group' then Amt1 Else 0 End as TotAmt, 0
			From
		
				(Select Master, Type, Particulars, isNull(ClosingBalance, 0) as Amt1, Path, Code
				from dbo.fn_FAS_LedgersClosingBalance(@PrStart, @PrStart,@RptDate, @CmCode) 
				Where Left(Path, 2) in ('00', '01', '02', '03', '04', '09', '0A', '0B', '0C', '0F', 'ZZ')
				) N 
			Order by Path, Type				

	
			if @RptType = 'S' --Groupwise Summary
				begin 
					Delete @RetTable
						Where (Type = 'Ledger' and Left(Path, 2) not in ('00', 'ZZ')) or (Type='Group' and Len(Path)>2)			
				end
	
/*  Update  SortOrder To Groups */

			Update @RetTable Set SortOrder =
				Case Path 
							When '01' Then Case When TotalAmt < 0 Then 1 Else 101 End
							When '0B' Then Case When TotalAmt < 0 Then 2 Else 102 End
							When '03' Then Case When TotalAmt < 0 Then 3 Else 103 End
							When '09' Then Case When TotalAmt < 0 Then 4 Else 104 End
							When '0A' Then Case When TotalAmt < 0 Then 5 Else 105 End
							When '02' Then Case When TotalAmt < 0 Then 6 Else 106 End
							When '04' Then Case When TotalAmt < 0 Then 7 Else 107 End
							When '0C' Then Case When TotalAmt < 0 Then 8 Else 108 End
							When '0F' Then Case When TotalAmt < 0 Then 9 Else 109 End
							When '00' Then Case When TotalAmt < 0 Then 97 Else 197 End
							When '0F' Then Case When TotalAmt < 0 Then 98 Else 198 End
 							When 'ZZ' Then Case When TotalAmt < 0 Then 99 Else 199 End
							 
				End
			Where Type='Group' and Len(Path) = 2

/* Update SortOrder To SubGroups and Ledgers		 */

			Update @RetTable Set SortOrder=b.SortOrder
			from @RetTable a Left Outer Join (Select * from @RetTable Where Type='Group' and Len(Path) = 2) b
			On Left(a.Path, 2)=b.Path
			Where Not (a.Type='Group' and Len(a.Path) = 2)

					
	Return


END

/*
	If (@PrStart=@Start)
		Begin
			Insert into @RetTable
		
				Select '', '00PO', 'Ledger', -3, 'Opening Balance', OpBalance  as Amount
				from FAS_LedgerMaster
				where LedgerCode=2 and CompCode=@CmCode
		End
	Else
		Begin
			Insert into @RetTable
		
				Select '', '00PO', 'Ledger', -3, 'Opening Balance', OpBalance + dbo.fn_FAS_Profit_Loss_Period(@PrStart, @tmpDate, @CmCode) as Amount
				from FAS_LedgerMaster
				where LedgerCode=2 and CompCode=@CmCode
		End
				

	Insert into @RetTable			

		Select '', '00PC', 'Ledger', -2, 'Current Period', dbo.fn_FAS_Profit_Loss_Period(@PrStart, @End, @CmCode) as Amount
	
		UNION ALL
	
		Select '', '00PT', 'Ledger', -1, 'Less Transfered', -isnull((sum(DrAmt)-sum(CrAmt)), 0) as Amount
		from FAS_Voucher_Vw 
		where DocDate between @PrStart and  @End and LrCode=2 and Compcode = @CmCode	
*/
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Dis_BalanceSheet_Ver]    Script Date: 17/06/2026 11:38:44 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Dis_BalanceSheet_Ver] (@RptType char(1), @RptDate datetime, @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))  
/*  Vertical Representation BalanceSheet */	
/*  @RptType - S refers Group Only  and D refers Detailed or Both Ledger and Group */

RETURNS @RetTable TABLE
	([Master] [varchar](10),
	[Path] [varchar](42),
	[Type] [varchar] (10),	
	[Code] int,
	[Particulars] [varchar] (100),
	[SubAmount] [money],
	[TotalAmount] [money],
	[SortOrder] int
	)
AS  

BEGIN 


	Insert into @RetTable

			Select Master, Path, Type, Code, Case Type when 'Group' then Space(Len(Path)) + Particulars
	                                                             	when 'Ledger' then space(Len(Path))+'    '+Particulars End as Particulars,
						Case When Type='Ledger' or (Len(Path) > 2 and Type='Group') then
							Case When Path in ('09', '02', '0C', '04', '0A') then Amt1 Else Amt1 End
						Else 0 End as SubAmt,	
						Case When Len(Path)=2 and Type='Group' then
							Case When Path in ('09', '02', '0C', '04', '0A') then Amt1 Else Amt1 End
						Else 0 End as TotAmt, 0


			From
		
				(Select Master, Type, Particulars, isNull(ClosingBalance, 0) as Amt1, Path, Code
				from dbo.fn_FAS_LedgersClosingBalance(@PrStart, @PrStart,@RptDate, @CmCode) 
				Where Left(Path, 2) in ('00', '01', '02', '03', '04', '09', '0A', '0B', '0C', '0F')
				) N Order by Path, Type				


				


	
			if @RptType = 'S' --Groupwise Summary
				begin 
					Delete @RetTable
						Where Type = 'Ledger' 			
				end
--			Else  		
				
				--Display All Data
			


			Update @RetTable Set SortOrder =
				Case Path 
							When '01' Then 1 When '0B' Then 2   
							When '09' Then 101 When '02' Then 102 When '03' Then 103 
							When '0C' Then 104 When '04' Then 105	When '0A' Then 106
							When '00' Then Case When TotalAmount < 0 Then 197 Else 97 End
							When '0F' Then Case When TotalAmount < 0 Then 198 Else 98 End
 							When 'ZZ' Then Case When TotalAmount < 0 Then 199 Else 99 End
							 
				End
			Where Type='Group' and Len(Path) = 2

			Update @RetTable Set SortOrder=b.SortOrder
			from @RetTable a Left Outer Join (Select * from @RetTable Where Type='Group' and Len(Path) = 2) b
			On Left(a.Path, 2)=b.Path
			Where Not (a.Type='Group' and Len(a.Path) = 2)

				-- Initial Stage
			Insert into @RetTable  Select '',  'SF', 'Group', 0, 'SOURCE OF FUNDS', 0 , 0, 0
			Insert into @RetTable  Select '',  'AF', 'Group', 0, 'APPLICATION OF FUNDS', 0 , 0,  100

					
	Return


END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Dis_CostCentre_Monthwise]    Script Date: 17/06/2026 11:38:44 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Dis_CostCentre_Monthwise] (@CostCode int, @LrCode int, @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))  

RETURNS @RetTable TABLE
	([MnCode] [int],		
	[MthName] [varchar](10),
	[DrAmt] [money],
	[CrAmt] [money]
	)

 AS  

BEGIN 	
	
	Insert into @RetTable

		Select MnCode, Datename(month, convert(datetime, Convert(varchar, h.MnCode)+'01', 112 )) as DMonth, DrAmt, CrAmt
			From 
			(Select h1.MnCode, h2.DrAmt, h2.CrAmt
			from
				(Select Convert(varchar(6), Monthdate, 112) MnCode from dbo.fn_FAS_Months(@PrStart, @PrEnd)) h1 
			Left Outer Join
				(Select Convert(varchar(6), c.Docdate, 112) MnCode, Sum(Case When c.Amount > 0 Then c.Amount Else 0 End) as DrAmt, Sum(Case When c.Amount < 0 Then c.Amount Else 0 End) as CrAmt
				 from FAS_VoucherTranCostCentre c 
					Left Outer Join FAS_VoucherTranSub b
						On c.DocNo = b.DocNo and c.DocDate = b.DocDate and c.VTSNo = b.VTSNo and c.VrRoute = b.VrRoute
							and c.CompCode = b.CompCode
				Where c.CostCentreCode=@CostCode and c.LrCode= @LrCode and (c.DocDate between @PrStart and @PrEnd) and c.CompCode = @CmCode
				Group by Convert(varchar(6), c.Docdate, 112)
				) h2
			On h1.MnCode=h2.MnCode
			)h			
			Order by MnCode

	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Dis_GroupLedgers_GroupSummary]    Script Date: 17/06/2026 11:38:44 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [dbo].[fn_FAS_Dis_GroupLedgers_GroupSummary] (@Route varchar(42), @isAsPerBalanceSheet bit, @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))  

RETURNS @RetTable TABLE
	([Master] [varchar](10),
	[Path] [varchar](42),
	[Type] [varchar] (10),
	[Code] [int],
	[Particulars] [varchar] (100),
	[OpBalance] [money],
	[DrAmt] [money],
	[CrAmt] [money],
	[ClosingBalance] [money]
	)


 AS  

BEGIN 

	If  @isAsPerBalanceSheet = '1' and (@Route='02' or @Route like '0205%')
		Begin
			Insert into @RetTable
		
				Select Master, Path, Type, Code, Particulars, OpBalance, DrAmt, CrAmt, ClosingBalance									
				From (
						Select Master, Path, Type, Code, Particulars, OpBalance, DrAmt, CrAmt, ClosingBalance
						from [dbo].[fn_FAS_Group_SubGroupLedger_CB] (@Route, @PrStart, @PrStart, @PrEnd, @CmCode)  
						Where ((Type='Ledger' and Len(Path)=Len(@Route)) or (Type='Group' and Len(Path)=Len(@Route)+2))
							and ClosingBalance <> 0 and Left(Path, 2) in ('02')  and (Path Not Like '0205%')
						
						Union All
				
						Select '00', '0205' as Path, 'Group' as Type,  9999 as Code, 'STOCK-IN-HAND'  as Particulars, Sum(OpeningStock), 0, 0,  Sum(ClosingStock) --Sum(-ClosingStock)
						from dbo.fn_FAS_StockValue (@PrStart, @PrEnd, @CmCode)
				
						Union All
				
						Select '00', '0205', 'Ledger' as Type,  9999 as Code, isNull(b.LedgerName, '')   as Particulars, OpeningStock, 0, 0, ClosingStock    --  (-ClosingStock)
						from dbo.fn_FAS_StockValue (@PrStart, @PrEnd, @CmCode) a Left Outer Join FAS_LedgerMaster b On a.LedgerCode=b.LedgerCode and a.CompCode=b.CompCode
						where ClosingStock<>0
			
					)M
				Where ((Type='Ledger' and Len(Path)=Len(@Route)) or (Type='Group' and Len(Path)=Len(@Route)+2))
				Order by Type, Particulars
		
					--To reduce the default OpeningStock added in Current Assets and Add the Closing Stock
					Update @RetTable Set ClosingBalance= ClosingBalance+(Select Sum(ClosingStock-OpeningStock) from  dbo.fn_FAS_StockValue (@PrStart, @PrEnd, @CmCode))
					Where Path='02' and Type='Group'
		End
	Else
	
		Insert into @RetTable
			
			Select Master, Path, Type, Code, Particulars, OpBalance, DrAmt, CrAmt, ClosingBalance
			from [dbo].[fn_FAS_Group_SubGroupLedger_CB] (@Route, @PrStart, @PrStart, @PrEnd, @CmCode)  
			Where ((Type='Ledger' and Len(Path)=Len(@Route)) or (Type='Group' and Len(Path)=Len(@Route)+2))
			and ClosingBalance <> 0
			Order by Type, Particulars
				

	Return 

END

GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Dis_OutstandingBills]    Script Date: 17/06/2026 11:38:44 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Dis_OutstandingBills] (@LrRoute varchar(42),  @RptType char(1), @RptDate datetime, @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))  

RETURNS @RetTable TABLE
	([LrCode] int,
	[Particulars] [Varchar] (100),
	[Amount] [money],
	[OnAcct] [money],
	[TotAmt] [money],
	[LrRoute] [varchar](42),
	[Type] [Varchar](10)
	)
AS  

BEGIN 

	Insert into @RetTable

		Select * 
		From
			(Select LrCode, Particulars, BillAmt, (OpBalance + VrAmt - BillAmt) as OnAcct, (OpBalance+VrAmt) as TotAmt, LrRoute, 'Ledger' as Type
			From
				(Select n.LedgerCode as LrCode, n.LedgerName as Particulars, n.OpBalance, n.LrRoute as LrRoute, 
					isNull(p.VrAmt, 0) as VrAmt, isNull(m.BillAmt, 0) as BillAmt
				from FAS_LedgerMaster n
					Left Outer Join (Select LrCode, Sum(DrAmt-CrAmt) as VrAmt From FAS_VoucherTranSub
							 Where DocDate<=@RptDate and CompCode=@CmCode
							and LrCode in (Select LedgerCode from FAS_LedgerMaster Where LrRoute like @LrRoute+'%' and CompCode=@CmCode)
							Group by LrCode) p
						On n.LedgerCode=p.LrCode
					Left Outer Join (Select LrCode, Sum(Amount) as BillAmt From FAS_BillDetails
							 Where RefDate<=@RptDate and DocDate<=@RptDate and Type<>'On Acct' and CompCode=@CmCode
							and LrCode in (Select LedgerCode from FAS_LedgerMaster Where LrRoute like @LrRoute+'%' and CompCode=@CmCode)
							Group by LrCode) m
						On m.LrCode=n.LedgerCode
				Where n.CompCode=@CmCode and LrRoute like @LrRoute+'%' and isBillwise='1'
				) q
			) r
		Where r.TotAmt<>0

	
			if @RptType = 'C' -- Credit only display
				begin 
					Delete @RetTable
						Where TotAmt > 0
						
				end

			if @RptType = 'D' -- Debit only display
				begin 
					Delete @RetTable
						Where TotAmt < 0
						
				end	

		Insert into @RetTable
			Select LrCode, Particulars, 0 as Amount, 0 as OnAcct, TotAmt, LrRoute, 'Group' as Type  		
			From 
			        (Select GroupCode as LrCode, GroupName as Particulars,  Sum(TotAmt) as TotAmt, GrRoute+GrWidth as LrRoute
				From FAS_GroupMaster a		
				Left Outer Join @RetTable c
					On c.LrRoute = a.GrRoute+ a.GrWidth 
				Where Exists (Select * From @RetTable b Where a.GrRoute+a.GrWidth = b.LrRoute ) and CompCode=@CmCode 
				group by GroupCode, GroupName, GrRoute+GrWidth 
			         )x
			Order By LrCode

	Return


END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Dis_PrincipleGroups]    Script Date: 17/06/2026 11:38:44 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [dbo].[fn_FAS_Dis_PrincipleGroups] (@PrStart datetime, @PrEnd datetime, @CmCode varchar(12))  

RETURNS @RetTable TABLE
	([SortOrder] [int],
	[Master] [varchar](10),
	[Path] [varchar](42),
	[Type] [varchar] (10),
	[Code] [int],
	[Particulars] [varchar] (100),	
	[ClosingBalance] [money]
	)

 AS  

BEGIN 

		Insert into @RetTable
			Select Case Path when '0202'  then 2 when '0201' then 3 when '0B01' then 4 when '0206' then 5 when '0303' then 6
					when '0E' then 7 when '0D' then 8 when '0205' then 9 when '00' then 10 When '02' Then 13 When '03' Then 14 End as SortOrder,
					Master, Path, Type, Code, Particulars, ClosingBalance 
			From dbo.fn_FAS_LedgersClosingBalance(@PrStart, @PrStart, @PrEnd, @CmCode) 
			Where  Path in ('00', '02', '0201', '0202', '0205', '0206', '03', '0303', '0B01', '0D', '0E') and Type = 'Group' 

		Insert into @RetTable
			Select SortOrder, Master, Path, Type, Code, Particulars, (CurrentAsset-CurrentLiability) as ClosingBalance
			From 
			(	Select 1 as SortOrder, '00' as Master,  'WC' as Path, 'Group' as Type, '9999' as Code, 'WORKING CAPITAL' as Particulars, 
					Sum(IsNull((Case Path When '02' Then ClosingBalance End), 0)) as CurrentAsset,
					Sum(IsNull((Case Path When '03' Then ClosingBalance End), 0)) as CurrentLiability
				From @RetTable		
				Where Path in ('02', '03')		
			)m
	

		Insert into @RetTable
			Select SortOrder, Master, Path, Type, Code, Particulars, (SalesAc/(CurrentAsset-CurrentLiability)) as ClosingBalance
			From 
			(	Select 11 as SortOrder, '00' as Master,  'WT' as Path, 'Group' as Type, '9999' as Code,  'WORKING CAPITAL TURNOVER' as Particulars, 
					Sum(IsNull((Case Path When '0E' Then ClosingBalance End ) , 0)) as SalesAc,
					Sum(IsNull((Case Path When '02' Then ClosingBalance End), 0)) as CurrentAsset,
					Sum(IsNull((Case Path When '03' Then ClosingBalance End), 0)) as CurrentLiability
				From @RetTable
				Where  Path in('0E', '02', '03') and Type = 'Group'			
			)n

			
		Insert into @RetTable
			Select SortOrder, Master, Path, Type, Code, Particulars, (SalesAc/ClStock) as ClosingBalance
			From 			
			(	Select 12 as SortOrder, '00' as Master,  'IT' as Path, 'Group' as Type, '9999' as Code,  'INVENTORY TURNOVER' as Particulars, 
					Sum(IsNull((Case Path When '0E' Then ClosingBalance End ) , 0)) as SalesAc,
					(Select Sum(ClosingStock) as ClosingStock From dbo.fn_FAS_StockValue (@PrStart, @PrEnd, @CmCode) ) as ClStock
				From @RetTable
				Where  Path in('0E') 
			)p


		Delete From @RetTable 
			Where SortOrder > 12


	Return

END




GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Dis_PrincipleRatio]    Script Date: 17/06/2026 11:38:44 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [dbo].[fn_FAS_Dis_PrincipleRatio] (@PrStart datetime, @PrEnd datetime, @CmCode varchar(12))  

RETURNS @RetTable TABLE
	([SortOrder] [int],
	[Master] [varchar](10),
	[Path] [varchar](42),
	[Type] [varchar] (10),
	[Code] [int],
	[Particulars] [varchar] (100),	
	[ClosingBalance] [money],
	[OutputValue] [varchar](50)
	)


 AS  

BEGIN 

		Insert into @RetTable
			Select SortOrder, Master, Path, Type, Code, Particulars, ClosingBalance , '' as OutputValue
			From
				(Select 0 as SortOrder, Master, Path, Type, Code, Particulars, ClosingBalance 
				From dbo.fn_FAS_LedgersClosingBalance(@PrStart, @PrStart, @PrEnd, @CmCode) 
				Where Path in ('00', '02', '0102', '0201', '0202', '0205', '0206', '03', '0303', '05', '06', '07', '08', '0B', '0B01', '0D', '0E') and Type = 'Group' 
		
				Union All

				Select 0 as SortOrder, '00' as Master, 'OS' as Path, 'Group' as Type,  '21' as Code,  'Opening Stock'  as Particulars, Sum(OpeningStock) as ClosingBalance
				from dbo.fn_FAS_StockValue (@PrStart, @PrEnd, @CmCode)

				Union All

				Select 0 as SortOrder, '00' as Master, 'CS' as Path, 'Group' as Type,  '31' as Code,  'Closing Stock'  as Particulars, Sum(ClosingStock) as ClosingBalance
				from dbo.fn_FAS_StockValue (@PrStart, @PrEnd, @CmCode)
				)l
		
		
		Insert into @RetTable
			Select SortOrder, Master, Path, Type, Code, Particulars, (CurrentAsset/CurrentLiability) as ClosingBalance, ' :1' as OutputValue
				From 
				(	Select 21 as SortOrder, '00' as Master,  'CR' as Path, 'Group' as Type, '9999' as Code, 'CURRENT RATIO' as Particulars,
						Sum(IsNull((Case Path When '02' Then ClosingBalance End), 0)) as CurrentAsset,
						Sum(IsNull((Case Path When '03' Then ClosingBalance End), 0)) as CurrentLiability
					From @RetTable
				)m


		Insert into @RetTable
			Select SortOrder, Master, Path, Type, Code, Particulars, ((CurrentAsset-Stockinhand)/CurrentLiability) as ClosingBalance, ' :1' as OutputValue
				From 
				(	Select 22 as SortOrder, '00' as Master,  'QR' as Path, 'Group' as Type, '9999' as Code, 'QUICK RATIO' as Particulars, 
						Sum(IsNull((Case Path When '02' Then ClosingBalance End), 0)) as CurrentAsset,
						Sum(IsNull((Case Path When '0205' Then ClosingBalance End), 0)) as Stockinhand,
						Sum(IsNull((Case Path When '03' Then ClosingBalance End), 0)) as CurrentLiability
					From @RetTable
				)n



		Insert into @RetTable
			Select SortOrder, Master, Path, Type, Code, Particulars, (LoanLiability/(ShareCapital+NetProfit)) * 100 as ClosingBalance, ' :1' as OutputValue
				From 
				(	Select 23 as SortOrder, '00' as Master,  'ER' as Path, 'Group' as Type, '9999' as Code, 'DEBIT/EQUITY RATIO' as Particulars, 
						Sum(IsNull((Case Path When '0B' Then ClosingBalance End), 0)) as LoanLiability,
						Sum(IsNull((Case Path When '0102' Then ClosingBalance End), 0)) as ShareCapital,
						Case Sign(Sum(IsNull((Case Path When '00' Then ClosingBalance End), 0))) When 1 Then Sum(IsNull((Case Path When '00' Then ClosingBalance End), 0)) Else 0 End as NetProfit
					From @RetTable
				)o



		Insert into @RetTable
			Select SortOrder, Master, Path, Type, Code, Particulars, ((GrossProfit/SalesAc)*100*(-1)) as ClosingBalance, ' %'  as OutputValue
				From 
				(	Select 24 as SortOrder, '00' as Master,  'GP' as Path, 'Group' as Type, '9999' as Code, 'GROSS PROFIT' as Particulars, 
						Sum(IsNull((Case Path When '0E' Then ClosingBalance End), 0)) as SalesAc,
						Sum(IsNull((Case Path When '00' Then ClosingBalance End), 0)) as GrossProfit
					From @RetTable
				)p

		Insert into @RetTable
			Select SortOrder, Master, Path, Type, Code, Particulars, ((NetProfit/SalesAc)*100*(-1)) as ClosingBalance, ' %' as OutputValue
				From 
				(	Select 25 as SortOrder, '00' as Master,  'NP' as Path, 'Group' as Type, '9999' as Code, 'NET PROFIT %' as Particulars, 
						Sum(IsNull((Case Path When '0E' Then ClosingBalance End), 0)) as SalesAc,
						Sum(IsNull((Case Path When '00' Then ClosingBalance End), 0)) as NetProfit
					From @RetTable
				)q


		Insert into @RetTable
			Select SortOrder, Master, Path, Type, Code, Particulars, (((OpStock+PurchaseAc-ClStock+DirectExp+InDirectExp-DirectIncome-InDirectIncome)/SalesAc)*100*(-1))  as ClosingBalance, ' %' as OutputValue
				From  
				(	Select 26 as SortOrder, '00' as Master,  'OC' as Path, 'Group' as Type, '9999' as Code, 'OPERATING COST %' as Particulars,
					 	Sum(IsNull((Case Path When 'OS' Then ClosingBalance End), 0)) as OpStock,
						Sum(IsNull((Case Path When '0D' Then ClosingBalance End), 0)) as PurchaseAc,
						Sum(IsNull((Case Path When '05' Then ClosingBalance End), 0)) as DirectExp,
						Sum(IsNull((Case Path When '06' Then ClosingBalance End), 0)) as DirectIncome,
						Sum(IsNull((Case Path When '07' Then ClosingBalance End), 0)) as InDirectExp,
						Sum(IsNull((Case Path When '08' Then ClosingBalance End), 0)) as InDirectIncome,
					 	Sum(IsNull((Case Path When 'OS' Then ClosingBalance End), 0)) as ClStock,
						Sum(IsNull((Case Path When '0E' Then ClosingBalance End), 0)) as SalesAc
					From @RetTable
				)r

		Insert into @RetTable
			Select 27 as SortOrder, '00' as Master,  'RT' as Path, 'Group' as Type, '9999' as Code, 'RECEIVING TURNOVER IN DAYS %' as Particulars,  0.00 as ClosingBalance, ' %' as OutputValue


		Insert into @RetTable
			Select SortOrder, Master, Path, Type, Code, Particulars, ((NetProfit/(ShareCapital+NetProfit))*100) as ClosingBalance, ' %' as OutputValue
				From 
				(	Select 28 as SortOrder, '00' as Master,  'RI' as Path, 'Group' as Type, '9999' as Code, 'RETURN ON INVESMENT %' as Particulars, 
						Sum(IsNull((Case Path When '0102' Then ClosingBalance End), 0)) as ShareCapital,
						Sum(IsNull((Case Path When '00' Then ClosingBalance End), 0)) as NetProfit
					From @RetTable
				)s
	

		Insert into @RetTable
			Select SortOrder, Master, Path, Type, Code, Particulars, ((NetProfit/(CurrentAsset-CurrentLiability)) * 100) as ClosingBalance, ' %' as OutputValue
				From 
				(	Select 29 as SortOrder, '00' as Master,  'RW' as Path, 'Group' as Type, '9999' as Code, 'RETURN ON WORKING CAPITAL %' as Particulars, 
						Sum(IsNull((Case Path When '02' Then ClosingBalance End), 0)) as CurrentAsset,
						Sum(IsNull((Case Path When '03' Then ClosingBalance End), 0)) as CurrentLiability,
						Sum(IsNull((Case Path When '00' Then ClosingBalance End), 0)) as NetProfit
					From @RetTable
				)m


		Delete From @RetTable 
			Where (SortOrder = 0 and Code <> 9999) or (SortOrder <=20)

	Return


END














GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Dis_ProfitAndLoss]    Script Date: 17/06/2026 11:38:44 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Dis_ProfitAndLoss] (@isVertical bit,  @RptType int, @Start datetime, @End datetime, @CmCode varchar(12))  --@isSummary bit,  
/*  Horizontal Representation ProfitAndLoss */   
/*  @RptType - 0 refers Abstract-only groups, 1 refers expand to single level , 2 refers expand to all level*/  
  
RETURNS @RetTable TABLE  
 ([Master]  [varchar](10),  
 [Path]   [varchar](42),  
 [Type]   [varchar] (10),   
 [Code]   int,  
 [Particulars]  [varchar] (100),  
 [SubAmount]  [money],  
 [TotalAmount]  [money],  
 [SortOrder]  int  
 )  
AS    
  
BEGIN   
  
 Declare @CallTrialBalanceType char(1)  
/*  
 If @isSummary='1'  
  Select @CallTrialBalanceType='A'  
 Else  
  Select @CallTrialBalanceType='S'  
*/  
  
 If @RptType='0'  
  Select @CallTrialBalanceType='A'--Abstract Only Group  
 if @RptType='1'  
  Select @CallTrialBalanceType='S' -- Groups and 1st level Ledgers  
 if @RptType='2'  
  Select @CallTrialBalanceType='M'  --SubGroup with All Ledger  
  
  
 Insert into @RetTable  
  
  Select Master, Path, Type, Code,  
    Case Type when 'Group' then Space(Len(Path)) + Particulars  
                              when 'Ledger' then space(Len(Path))+'    '+Particulars End as Particulars,  
         
     Case When Type='Ledger' or (Len(Path) > 2 and Type='Group') then Amount Else 0 End as SubAmt,   
     Case When Len(Path)=2 and Type='Group' then Amount Else 0 End as TotAmt, 0  
   
  From (  
    Select Master, Path, Type, Code, Particulars, (DrAmt-CrAmt) as Amount    
    From dbo.fn_FAS_Rpt_TrialBalance_PL(@CallTrialBalanceType, @Start, @End, @CmCode)  
    Where Path Not Like '0205%'  
    --Where Left(Path, 2) in ('0E', '0D', '05', '06', '07', '08')     
      
    Union All
/*    
    Select '00', '21' as Path, 'Group' as Type, 9999 as Code,  'Opening Stock'  as Particulars, Sum(OpeningStock)   
    From [dbo].[fn_FAS_StockValue_Tmp] (@UserKey, @Start, @End, @CmCode)        
    
    Union All  
  
    Select '00', '31' as Path, 'Group' as Type,  9999 as Code, 'Closing Stock'  as Particulars, Sum(-ClosingStock)  
    From [dbo].[fn_FAS_StockValue_Tmp] (@UserKey, @Start, @End, @CmCode)        
  
    Union All  
  
    Select '00', '21', 'Ledger' as Type,  9999 as Code, isNull(b.LedgerName, '')  as Particulars, OpeningStock  
    From [dbo].[fn_FAS_StockValue_Tmp] (@UserKey, @Start, @End, @CmCode)  a   
    Left Outer Join FAS_LedgerMaster_AuthTbl  b  
      On a.LedgerCode=b.LedgerCode and a.CompCode=b.CompCode and b.EffStatus='AA'  
    Where OpeningStock<>0  
    
    Union All  
    
    Select '00', '31', 'Ledger' as Type,  9999 as Code, isNull(b.LedgerName, '')   as Particulars, -ClosingStock  
    From [dbo].[fn_FAS_StockValue_Tmp] (@UserKey, @Start, @End, @CmCode)  a  
    Left Outer Join  FAS_LedgerMaster_AuthTbl b  
     On a.LedgerCode=b.LedgerCode and a.CompCode=b.CompCode and b.EffStatus='AA'  
    Where ClosingStock<>0    
*/    
    Select '00', '21' as Path, 'Group' as Type, 9999 as Code,  'Opening Stock'  as Particulars, Sum(OpeningStock)   
    from dbo.fn_FAS_StockValue (@Start, @End, @CmCode)  
    
    Union All  
    
    Select '00', '31' as Path, 'Group' as Type,  9999 as Code, 'Closing Stock'  as Particulars, Sum(-ClosingStock)  
    from dbo.fn_FAS_StockValue (@Start,@End, @CmCode)  
  
    Union All  
  
    Select '00', '21', 'Ledger' as Type,  9999 as Code, isNull(b.LedgerName, '')  as Particulars, OpeningStock  
    from dbo.fn_FAS_StockValue (@Start, @End, @CmCode) a 
    Left Outer Join FAS_LedgerMaster b 
    	On a.LedgerCode=b.LedgerCode and a.CompCode=b.CompCode  
    where OpeningStock<>0  
    
    Union All  
    
    Select '00', '31', 'Ledger' as Type,  9999 as Code, isNull(b.LedgerName, '')   as Particulars, -ClosingStock  
    from dbo.fn_FAS_StockValue (@Start, @End, @CmCode) a 
    Left Outer Join FAS_LedgerMaster b 
    	On a.LedgerCode=b.LedgerCode and a.CompCode=b.CompCode  
    where ClosingStock<>0  

   
   )M  
   Order by Path, Type   
  
/*  
   If @isSummary = '1' --Groupwise Summary  
    Begin   
     Delete @RetTable  
      Where  Not (Type='Group' and Len(Path) = 2)   
    End  
   Else  
    Begin  
     Delete @RetTable  
      Where  (Type = 'Ledger'  and Len(Path) > 2) or (Type='Group' and Len(Path) > 4)   
    End  
*/  
   If @RptType = '0' --Groupwise Summary  
    Begin   
     Delete @RetTable  
      Where  Not (Type='Group' and Len(Path) = 2)   
    End  
  
   if @RptType = '1'  
    Begin  
     Delete @RetTable  
      Where  (Type = 'Ledger'  and Len(Path) > 2) or (Type='Group' and Len(Path) > 4)   
    End  
  
  
   Insert into @RetTable   
    Select '00' as Master, 'GP' as Path, 'Group' as Type,  0 as Code, Case When TotalAmount > 0 Then 'GROSS PROFIT'  Else 'GROSS LOSS' End as Particulars,   
     0 as SubAmount,  TotalAmount, 150 as SortOrder  
    From   
     (Select -Sum(TotalAmount) as TotalAmount  
     From @RetTable  
     Where Left(Path, 2) in ('0E', '06', '31', '21', '0D', '05')  
     )x      
  
   Insert into @RetTable  
    Select '00' as Master, 'NP' as Path, 'Group' as Type,  0 as Code, Case When TotalAmount > 0 Then 'NET PROFIT'  Else 'NET LOSS' End as Particulars,   
     0 as SubAmount, TotalAmount, 200 as SortOrder  
    From   
     (Select -Sum(TotalAmount) as TotalAmount  
     From @RetTable  
     Where Left(Path, 2) in ('0E', '06', '31', '08', '21', '0D', '05', '07')  
     )x  
  
/*  Update  SortOrder To Groups */  
  
   Update @RetTable Set SortOrder =  
    Case Path  
     When '0E' Then 101     
     When '21' Then 112  
     When '0D' Then 113  
     When '31' Then 114  
       
     When '05' Then 125  
     When '06' Then 126  
   
     When '07' Then 197  
     When '08' Then 198  
    End  
   Where Type='Group' and Len(Path) = 2 and Path not in ('GP', 'NP')  
  
/* Update SortOrder To SubGroups and Ledgers   */  
  
   Update @RetTable Set SortOrder=b.SortOrder  
   from @RetTable a Left Outer Join (Select * from @RetTable Where Type='Group' and Len(Path) = 2) b  
   On Left(a.Path, 2)=b.Path  
   Where Not (a.Type='Group' and Len(a.Path) = 2)      
  
   If @isVertical='1'  --These are no need for horizontal representation  
    Begin  
     Update @RetTable Set SubAmount=-SubAmount, TotalAmount=-TotalAmount  
     Where Left(Path, 2) in ('0E', '06', '08', '31')  
  
     Update @RetTable Set TotalAmount=Abs(TotalAmount)  
     Where Left(Path, 2) in ('GP', 'NP')  
    
     -- Initial Stage  
     Insert into @RetTable  Select '00',  'TA', 'Group', 0, 'TRADING AMOUNT', 0 , 0, 0  
     Insert into @RetTable  Select '00',  'CS', 'Group', 0, 'COST OF SALES', 0 , 0,  110  
     Insert into @RetTable  Select '00',  'IS', 'Group', 0, 'INCOME STATEMENT', 0, 0, 160  
  
    End
    
    RETURN
END  
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Dis_ProfitAndLoss_Contrib]    Script Date: 17/06/2026 11:38:44 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Dis_ProfitAndLoss_Contrib] (@Start datetime, @End datetime, @CmCode varchar(12))  
RETURNS @RetTable TABLE  
(
    [SeqNo] [int],
    [Master]  [varchar](10),  
    [Path]   [varchar](42),  
    [Type]   [varchar] (10),   
    [Code]   int,  
    [Particulars]  [varchar] (100),  
    [SubAmount1] [money],
    [SubAmount]  [money],  
    [TotalAmount]  [money],  
    [SortOrder]  int 
)  
AS    
BEGIN   
    DECLARE @isVertical bit, @RptType int; 
    SET @isVertical='1'; 
    SET @RptType=2; /* All Levels */
  
    Insert into @RetTable
        Select ROW_NUMBER()OVER(ORDER BY SortOrder, [Type], [Particulars] ) as SeqNo, [Master], [Path], [Type], 
            Code, Particulars, 0 as SubAmount1, SubAmount, TotalAmount, SortOrder 
         From dbo.fn_FAS_Dis_ProfitAndLoss (@isVertical, @RptType, @Start, @End, @CmCode) 
         Where TotalAmount <> 0 or SubAmount <> 0 Order By SortOrder, Type, Path , Particulars

         ;With VrTran
         AS
         (
            Select a.DocType, a.DocNo, a.DocDate, a.VTSNo, a.VrRoute, a.LrCode, a.DrAmt, a.CrAmt
            from FAS_VoucherTranSub a
            Where (a.DocDate between @Start and @End) and a.CompCode=@CmCode
            and Exists 
                (
                    Select * 
                    From FAS_VoucherTranSub m
                    Left Outer Join FAS_LedgerMaster_AuthTbl n
                        On m.LrCode=n.LedgerCode and m.CompCode=n.CompCode
                    Where (m.DocDate between @Start and @End) and m.CompCode=@CmCode
                        and Left(n.LrRoute, 2) in ('0E', '0D', '05', '06', '07', '08')  
                        and m.DocNo=a.DocNo and m.DocDate=a.DocDate and m.VrRoute=a.VrRoute and m.CompCode=a.CompCode
                )
         )
         , VrTranMax
         AS
         (
            Select m.DocNo, m.DocDate, m.VrRoute, Sum(m.DrLrCode) as DrLrCode, Sum(m.DrAmt) as DrAmt,
                Sum(m.CrLrCode) as CrLrCode, Sum(m.CrAmt) as CrAmt
            From
            (
                Select j.DocNo, j.DocDate, j.VrRoute, 
                    Case When j.DrAmt>0 Then j.LrCode Else 0 End as DrLrCode, j.DrAmt, 
                    Case When j.DrAmt>0 Then 0 Else j.LrCode End as CrLrCode, j.CrAmt
                From VrTran j
                Inner Join
                (
                    Select g.DocNo, g.DocDate, g.VrRoute, Min(g.VTSNo) as VTSNoMin, g.DrAmt, g.CrAmt 
                    From VrTran g
                    Inner Join
                    (
                        Select DocType, DocNo, DocDate, VrRoute, Max(DrAmt) as DrAmtMax, Max(CrAmt) as CrAmtMax
                        From VrTran
                        Group By DocType, DocNo, DocDate, VrRoute
                    ) h
                        On g.DocNo=h.DocNo and g.DocDate=h.DocDate and g.VrRoute=h.VrRoute and (g.DrAmt=h.DrAmtMax OR g.CrAmt=h.CrAmtMax)
                    Group By g.DocNo, g.DocDate, g.VrRoute, g.DrAmt, g.CrAmt
                ) k
                    On j.DocNo=k.DocNo and j.DocDate=k.DocDate and j.VrRoute=k.VrRoute and j.VTSNo=k.VTSNoMin
            ) m
            Group By m.DocNo, m.DocDate, m.VrRoute
         )

    Insert into @RetTable
        Select p.SeqNo, p.[Master], p.[Path], 'LrAgainst' as [Type], q.LrCodeAgainst as Code, 
            Space(Len(p.[Path])+8)+r.LedgerName as Particulars,
            q.VrLrAmt as SubAmount1, 0 as SubAmount, 0 as TotalAmount, p.SortOrder
         From @RetTable p
         Left Outer Join
         (
            Select m.LrCode, Sum(m.VrLrAmt) as VrLrAmt, m.LrCodeAgainst 
            From
            (
                 Select j.*, Case When j.VrLrAmt>0 Then k.CrLrCode Else k.DrLrCode End as LrCodeAgainst
                 From 
                 (
                    Select DocNo, DocDate, VrRoute, LrCode, Sum(DrAmt-CrAmt) as VrLrAmt
                    From VrTran
                    Group By DocNo, DocDate, VrRoute, LrCode
                 ) j
                 Left Outer Join VrTranMax k
                    On j.DocNo=k.DocNo and j.DocDate=k.DocDate and j.VrRoute=k.VrRoute
            ) m
            Group By m.LrCode, m.LrCodeAgainst
         ) q
            On p.Code=q.LrCode
         Left Outer Join FAS_LedgerMaster_AuthTbl r
            On q.LrCodeAgainst=r.LedgerCode 
        Where p.[Type]='Ledger' and r.CompCode=@CmCode

 --Select * from @PLDetail Order By SortOrder, SeqNo, [Type], [Particulars]
 
    RETURN  
END  
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Dis_ProfitAndLoss_Hor]    Script Date: 17/06/2026 11:38:44 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Dis_ProfitAndLoss_Hor] (@RptType char(1), @RptDate datetime, @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))  
/*  Horizontal Representation ProfitAndLoss */	
/*  @RptType - S refers Group Only  and D refers Detailed or Both Ledger and Group */

RETURNS @RetTable TABLE
	([Master] 	[varchar](10),
	[Path] 		[varchar](42),
	[Type] 		[varchar] (10),	
	[Code] 		int,
	[Particulars] 	[varchar] (100),
	[SubAmount] 	[money],
	[TotalAmount] 	[money],
	[SortOrder] 	int
	)
AS  

BEGIN 


	Insert into @RetTable

		Select Master, Path, Type, Code,
				Case Type when 'Group' then Space(Len(Path)) + Particulars
		                           	when 'Ledger' then space(Len(Path))+'    '+Particulars End as Particulars,
							
					Case When Type='Ledger' or (Len(Path) > 2 and Type='Group') then Amount Else 0 End as SubAmt,	
					Case When Len(Path)=2 and Type='Group' then Amount Else 0 End as TotAmt, 0
	
		From (
				Select Master, Path, Type, Code, Particulars, ClosingBalance as Amount  
				from dbo.fn_FAS_Rpt_TrialBalance(@PrStart, @PrStart,@RptDate, @CmCode)
				where Left(Path, 2) in ('0E', '0D', '05', '06', '07', '08')   
				
				Union All
		
				Select '00', '21' as Path, 'Group' as Type, 9999 as Code,  'Opening Stock'  as Particulars, Sum(OpeningStock) 
				from dbo.fn_FAS_StockValue (@PrStart,@RptDate, @CmCode)
		
				Union All
		
				Select '00', '31' as Path, 'Group' as Type,  9999 as Code, 'Closing Stock'  as Particulars, Sum(-ClosingStock)
				from dbo.fn_FAS_StockValue (@PrStart,@RptDate, @CmCode)

				Union All

				Select '00', '21', 'Ledger' as Type,  9999 as Code, isNull(b.LedgerName, '')  as Particulars, OpeningStock
				from dbo.fn_FAS_StockValue (@PrStart, @PrEnd, @CmCode) a Left Outer Join FAS_LedgerMaster b On a.LedgerCode=b.LedgerCode and a.CompCode=b.CompCode
				where OpeningStock<>0
		
				Union All
		
				Select '00', '31', 'Ledger' as Type,  9999 as Code, isNull(b.LedgerName, '')   as Particulars, -ClosingStock
				from dbo.fn_FAS_StockValue (@PrStart, @PrEnd, @CmCode) a Left Outer Join FAS_LedgerMaster b On a.LedgerCode=b.LedgerCode and a.CompCode=b.CompCode
				where ClosingStock<>0
	
			)M
			Order by Path, Type	


			If @RptType = 'S' --Groupwise Summary
				Begin 
					Delete @RetTable
						Where  Not (Type='Group' and Len(Path) = 2)	
				End
			Else
				Begin
					Delete @RetTable
						Where  (Type = 'Ledger'  and Len(Path) > 2) or (Type='Group' and Len(Path) > 4)	
				End

			Insert into @RetTable 
				Select '00' as Master, 'GP' as Path, 'Group' as Type,  0 as Code, Case When TotalAmount > 0 Then 'GROSS PROFIT'  Else 'GROSS LOSS' End as Particulars, 0 as SubAmount, TotalAmount, 150 as SortOrder
				From 
					(Select -Sum(TotalAmount) as TotalAmount
					From @RetTable
					Where Left(Path, 2) in ('0E', '06', '31', '21', '0D', '05')
					)x				

			Insert into @RetTable
				Select '00' as Master, 'NP' as Path, 'Group' as Type,  0 as Code, Case When TotalAmount > 0 Then 'NET PROFIT'  Else 'NET LOSS' End as Particulars, 0 as SubAmount, TotalAmount, 200 as SortOrder
				From 
					(Select -Sum(TotalAmount) as TotalAmount
					From @RetTable
					Where Left(Path, 2) in ('0E', '06', '31', '08', '21', '0D', '05', '07')
					)x


/*  Update  SortOrder To Groups */

			Update @RetTable Set SortOrder =
				Case Path 		
					When '21' Then 101
					When '0D' Then 102
					When '31' Then 103
					When '0E' Then 104
					When '05' Then 105
					When '06' Then 106
	
					When '07' Then 197
					When '08' Then 198
				End
			Where Type='Group' and Len(Path) = 2 and Path not in ('GP', 'NP')

/* Update SortOrder To SubGroups and Ledgers		 */

			Update @RetTable Set SortOrder=b.SortOrder
			from @RetTable a Left Outer Join (Select * from @RetTable Where Type='Group' and Len(Path) = 2) b
			On Left(a.Path, 2)=b.Path
			Where Not (a.Type='Group' and Len(a.Path) = 2)				

	
	Return


END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Dis_ProfitAndLoss_Old]    Script Date: 17/06/2026 11:38:44 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Dis_ProfitAndLoss_Old] (@isVertical bit,  @RptType int, @Start datetime, @End datetime, @CmCode varchar(12))  --@isSummary bit,  
/*  Horizontal Representation ProfitAndLoss */   
/*  @RptType - 0 refers Abstract-only groups, 1 refers expand to single level , 2 refers expand to all level*/  
  
RETURNS @RetTable TABLE  
 ([Master]  [varchar](10),  
 [Path]   [varchar](42),  
 [Type]   [varchar] (10),   
 [Code]   int,  
 [Particulars]  [varchar] (100),  
 [SubAmount]  [money],  
 [TotalAmount]  [money],  
 [SortOrder]  int  
 )  
AS    
  
BEGIN   
  
 Declare @CallTrialBalanceType char(1)  
/*  
 If @isSummary='1'  
  Select @CallTrialBalanceType='A'  
 Else  
  Select @CallTrialBalanceType='S'  
*/  
  
 If @RptType='0'  
  Select @CallTrialBalanceType='A'--Abstract Only Group  
 if @RptType='1'  
  Select @CallTrialBalanceType='S' -- Groups and 1st level Ledgers  
 if @RptType='2'  
  Select @CallTrialBalanceType='M'  --SubGroup with All Ledger  
  
  
 Insert into @RetTable  
  
  Select Master, Path, Type, Code,  
    Case Type when 'Group' then Space(Len(Path)) + Particulars  
                              when 'Ledger' then space(Len(Path))+'    '+Particulars End as Particulars,  
         
     Case When Type='Ledger' or (Len(Path) > 2 and Type='Group') then Amount Else 0 End as SubAmt,   
     Case When Len(Path)=2 and Type='Group' then Amount Else 0 End as TotAmt, 0  
   
  From (  
    Select Master, Path, Type, Code, Particulars, (DrAmt-CrAmt) as Amount    
    from dbo.fn_FAS_Rpt_TrialBalance(@CallTrialBalanceType, @Start, @End, @CmCode)  
    where Left(Path, 2) in ('0E', '0D', '05', '06', '07', '08')     
      
    Union All  
    
    Select '00', '21' as Path, 'Group' as Type, 9999 as Code,  'Opening Stock'  as Particulars, Sum(OpeningStock)   
    from dbo.fn_FAS_StockValue (@Start, @End, @CmCode)  
    
    Union All  
    
    Select '00', '31' as Path, 'Group' as Type,  9999 as Code, 'Closing Stock'  as Particulars, Sum(-ClosingStock)  
    from dbo.fn_FAS_StockValue (@Start,@End, @CmCode)  
  
    Union All  
  
    Select '00', '21', 'Ledger' as Type,  9999 as Code, isNull(b.LedgerName, '')  as Particulars, OpeningStock  
    from dbo.fn_FAS_StockValue (@Start, @End, @CmCode) a Left Outer Join FAS_LedgerMaster b On a.LedgerCode=b.LedgerCode and a.CompCode=b.CompCode  
    where OpeningStock<>0  
    
    Union All  
    
    Select '00', '31', 'Ledger' as Type,  9999 as Code, isNull(b.LedgerName, '')   as Particulars, -ClosingStock  
    from dbo.fn_FAS_StockValue (@Start, @End, @CmCode) a Left Outer Join FAS_LedgerMaster b On a.LedgerCode=b.LedgerCode and a.CompCode=b.CompCode  
    where ClosingStock<>0  
   
   )M  
   Order by Path, Type   
  
/*  
   If @isSummary = '1' --Groupwise Summary  
    Begin   
     Delete @RetTable  
      Where  Not (Type='Group' and Len(Path) = 2)   
    End  
   Else  
    Begin  
     Delete @RetTable  
      Where  (Type = 'Ledger'  and Len(Path) > 2) or (Type='Group' and Len(Path) > 4)   
    End  
*/  
   If @RptType = '0' --Groupwise Summary  
    Begin   
     Delete @RetTable  
      Where  Not (Type='Group' and Len(Path) = 2)   
    End  
  
   if @RptType = '1'  
    Begin  
     Delete @RetTable  
      Where  (Type = 'Ledger'  and Len(Path) > 2) or (Type='Group' and Len(Path) > 4)   
    End  
  
  
   Insert into @RetTable   
    Select '00' as Master, 'GP' as Path, 'Group' as Type,  0 as Code, Case When TotalAmount > 0 Then 'GROSS PROFIT'  Else 'GROSS LOSS' End as Particulars,   
     0 as SubAmount,  TotalAmount, 150 as SortOrder  
    From   
     (Select -Sum(TotalAmount) as TotalAmount  
     From @RetTable  
     Where Left(Path, 2) in ('0E', '06', '31', '21', '0D', '05')  
     )x      
  
   Insert into @RetTable  
    Select '00' as Master, 'NP' as Path, 'Group' as Type,  0 as Code, Case When TotalAmount > 0 Then 'NET PROFIT'  Else 'NET LOSS' End as Particulars,   
     0 as SubAmount, TotalAmount, 200 as SortOrder  
    From   
     (Select -Sum(TotalAmount) as TotalAmount  
     From @RetTable  
     Where Left(Path, 2) in ('0E', '06', '31', '08', '21', '0D', '05', '07')  
     )x  
  
  
/*  Update  SortOrder To Groups */  
  
   Update @RetTable Set SortOrder =  
    Case Path  
     When '0E' Then 101     
     When '21' Then 112  
     When '0D' Then 113  
     When '31' Then 114  
       
     When '05' Then 125  
     When '06' Then 126  
   
     When '07' Then 197  
     When '08' Then 198  
    End  
   Where Type='Group' and Len(Path) = 2 and Path not in ('GP', 'NP')  
  
/* Update SortOrder To SubGroups and Ledgers   */  
  
   Update @RetTable Set SortOrder=b.SortOrder  
   from @RetTable a Left Outer Join (Select * from @RetTable Where Type='Group' and Len(Path) = 2) b  
   On Left(a.Path, 2)=b.Path  
   Where Not (a.Type='Group' and Len(a.Path) = 2)      
  
   If @isVertical='1'  --These are no need for horizontal representation  
    Begin  
     Update @RetTable Set SubAmount=-SubAmount, TotalAmount=-TotalAmount  
     Where Left(Path, 2) in ('0E', '06', '08', '31')  
  
     Update @RetTable Set TotalAmount=Abs(TotalAmount)  
     Where Left(Path, 2) in ('GP', 'NP')  
    
     -- Initial Stage  
     Insert into @RetTable  Select '00',  'TA', 'Group', 0, 'TRADING AMOUNT', 0 , 0, 0  
     Insert into @RetTable  Select '00',  'CS', 'Group', 0, 'COST OF SALES', 0 , 0,  110  
     Insert into @RetTable  Select '00',  'IS', 'Group', 0, 'INCOME STATEMENT', 0, 0, 160  
  
    End
    
    RETURN  
END  
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Dis_ProfitAndLoss_Ver]    Script Date: 17/06/2026 11:38:44 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Dis_ProfitAndLoss_Ver] (@RptType char(1), @RptDate datetime, @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))  
/*  Horizontal Representation ProfitAndLoss */	
/*  @RptType - S refers Group Only  and D refers Detailed or Both Ledger and Group */

RETURNS @RetTable TABLE
	([Master] 	[varchar](10),
	[Path] 		[varchar](42),
	[Type] 		[varchar] (10),	
	[Code] 		int,
	[Particulars] 	[varchar] (100),
	[SubAmount] 	[money],
	[TotalAmount] 	[money],
	[SortOrder] 	int
	)
AS  

BEGIN 


	Insert into @RetTable

		Select Master, Path, Type, Code,
				Case Type when 'Group' then Space(Len(Path)) + Particulars
		                           	when 'Ledger' then space(Len(Path))+'    '+Particulars End as Particulars,
							
					Case When Type='Ledger' or (Len(Path) > 2 and Type='Group') then Amount Else 0 End as SubAmt,	
					Case When Len(Path)=2 and Type='Group' then Amount Else 0 End as TotAmt, 0
	
		From (
				Select Master, Path, Type, Code, Particulars, ClosingBalance as Amount  
				from dbo.fn_FAS_Rpt_TrialBalance(@PrStart, @PrStart,@RptDate, @CmCode)
				where Left(Path, 2) in ('0E', '0D', '05', '06', '07', '08')   
				
				Union All
		
				Select '00', '21' as Path, 'Group' as Type, 9999 as Code,  'Opening Stock'  as Particulars, Sum(OpeningStock) 
				from dbo.fn_FAS_StockValue (@PrStart,@RptDate, @CmCode)
		
				Union All
		
				Select '00', '31' as Path, 'Group' as Type,  9999 as Code, 'Closing Stock'  as Particulars, Sum(-ClosingStock)
				from dbo.fn_FAS_StockValue (@PrStart,@RptDate, @CmCode)

				Union All

				Select '00', '21', 'Ledger' as Type,  9999 as Code, isNull(b.LedgerName, '')  as Particulars, OpeningStock
				from dbo.fn_FAS_StockValue (@PrStart, @PrEnd, @CmCode) a Left Outer Join FAS_LedgerMaster b On a.LedgerCode=b.LedgerCode and a.CompCode=b.CompCode
				where OpeningStock<>0
		
				Union All
		
				Select '00', '31', 'Ledger' as Type,  9999 as Code, isNull(b.LedgerName, '')   as Particulars, -ClosingStock
				from dbo.fn_FAS_StockValue (@PrStart, @PrEnd, @CmCode) a Left Outer Join FAS_LedgerMaster b On a.LedgerCode=b.LedgerCode and a.CompCode=b.CompCode
				where ClosingStock<>0
	
			)M
			Order by Path, Type	


			If @RptType = 'S' --Groupwise Summary
				Begin 
					Delete @RetTable
						Where  Not (Type='Group' and Len(Path) = 2)	
				End
			Else
				Begin
					Delete @RetTable
						Where  (Type = 'Ledger'  and Len(Path) > 2) or (Type='Group' and Len(Path) > 4)	
				End

			Insert into @RetTable 
				Select '00' as Master, 'GP' as Path, 'Group' as Type,  0 as Code, Case When TotalAmount > 0 Then 'GROSS PROFIT'  Else 'GROSS LOSS' End as Particulars, 
					0 as SubAmount,  Abs(TotalAmount) as TotalAmount, 150 as SortOrder
				From 
					(Select -Sum(TotalAmount) as TotalAmount
					From @RetTable
					Where Left(Path, 2) in ('0E', '06', '31', '21', '0D', '05')
					)x				

			Insert into @RetTable
				Select '00' as Master, 'NP' as Path, 'Group' as Type,  0 as Code, Case When TotalAmount > 0 Then 'NET PROFIT'  Else 'NET LOSS' End as Particulars, 
					0 as SubAmount, Abs(TotalAmount) as TotalAmount, 200 as SortOrder
				From 
					(Select -Sum(TotalAmount) as TotalAmount
					From @RetTable
					Where Left(Path, 2) in ('0E', '06', '31', '08', '21', '0D', '05', '07')
					)x


/*  Update  SortOrder To Groups */

			Update @RetTable Set SortOrder =
				Case Path
					When '0E' Then 101 		
					When '21' Then 112
					When '0D' Then 113
					When '31' Then 114
					
					When '05' Then 125
					When '06' Then 126
	
					When '07' Then 197
					When '08' Then 198
				End
			Where Type='Group' and Len(Path) = 2 and Path not in ('GP', 'NP', 'TA', 'CS')

/* Update SortOrder To SubGroups and Ledgers		 */

			Update @RetTable Set SortOrder=b.SortOrder
			from @RetTable a Left Outer Join (Select * from @RetTable Where Type='Group' and Len(Path) = 2) b
			On Left(a.Path, 2)=b.Path
			Where Not (a.Type='Group' and Len(a.Path) = 2)				


			Update @RetTable Set SubAmount=-SubAmount, TotalAmount=-TotalAmount
			Where Left(Path, 2) in ('0E', '06', '08', '31')

			-- Initial Stage
			Insert into @RetTable  Select '00',  'TA', 'Group', 0, 'TRADING AMOUNT', 0 , 0, 0
			Insert into @RetTable  Select '00',  'CS', 'Group', 0, 'COST OF SALES', 0 , 0,  110
			Insert into @RetTable  Select '00',  'IS', 'Group', 0, 'INCOME STATEMENT', 0, 0, 160

	
	Return


END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Dis_RatioAnalysis]    Script Date: 17/06/2026 11:38:44 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [dbo].[fn_FAS_Dis_RatioAnalysis] (@Type char(1), @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))  

RETURNS @RetTable TABLE
	([SortOrder] [int],
	[Master] [varchar](10),
	[Path] [varchar](42),
	[Type] [varchar] (10),
	[Code] [int],
	[Particulars] [varchar] (100),	
	[ClosingBalance] [money],
	[OutputValue] [Varchar] (50),
	[PrincipleType][Char](2)
	)

 AS  

BEGIN 

	Insert into @RetTable
	
		Select SortOrder, Master, Path, Type, Code, Particulars, ClosingBalance, OutputValue, PrincipleType
		From
		(
			Select SortOrder, Master, Path, Type, Code, Particulars, ClosingBalance, '' as OutputValue, 'G' as PrincipleType
			From dbo.fn_FAS_Dis_PrincipleGroups (@PrStart, @PrEnd, @CmCode) 
	
			Union All
	
			Select SortOrder, Master, Path, Type, Code, Particulars, ClosingBalance, OutputValue, 'R' as PricipleType
			From dbo.fn_FAS_Dis_PrincipleRatio (@PrStart, @PrEnd, @CmCode) 
		)x
--		Where (SortOrder <= 12 AND @Type='G')  OR (SortOrder >= 21 AND @Type='R')

	/* Added on 25-10-2007 */	
	If @Type = 'G'
		Delete @RetTable Where SortOrder>12	
	
	If @Type = 'R'
		Delete @RetTable Where SortOrder<21

	Return
END




GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Dis_TreeView]    Script Date: 17/06/2026 11:38:44 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [dbo].[fn_FAS_Dis_TreeView] (@CmCode varchar(12))  

RETURNS @RetTable TABLE
	([Master] [varchar](10),
	[Path] [varchar](42),
	[Type] [varchar] (10),
	[Code] [int],
	[Particulars] [varchar] (100)	
	)
AS  

BEGIN 
	
	Declare @MastCmCode varchar(4)
	Select @MastCmCode = Left(@CmCode, 4)

	Insert into @RetTable

		Select '', a.LrRoute, 'Ledger', a.LedgerCode, a.LedgerName From FAS_LedgerMaster a 
		Where a.CompCode = @MastCmCode


	Insert into @RetTable

		Select '', a.GrRoute+a.GrWidth, 'Group', a.GroupCode, a.GroupName
		from FAS_GroupMaster a
		Where a.CompCode=@MastCmCode
		Group by a.GrRoute+a.GrWidth, a.GroupName, a.GroupCode

	--Update Classified the Master
	Update @RetTable Set Master=Case When Left(Path, 2)  in ('02', '09', '0A', '0C') Then '00' When Left(Path, 2) in ('01', '03', '04', '0B', '0F') Then '01'
						When Left(Path, 2) in ('06', '08', '0E') Then '02' When Left(Path, 2) in ('05', '07', '0D') Then '03' Else '04' End


	Return 

END





GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Dis_Vouchers_Ledgers_Period]    Script Date: 17/06/2026 11:38:44 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Dis_Vouchers_Ledgers_Period] (@LrCode varchar(42), @Start datetime, @End datetime, @CmCode varchar(12))  

RETURNS @RetTable TABLE
	([DocDate] [datetime],
	[DocNo] [int],
	[RefNo] [varchar] (30),	
	[VrRoute] [varchar] (42),	
	[VoucherName] [varchar] (50),
	[Particulars] [varchar] (50),	
	[Debit] [money],
	[Credit] [money],
	[ClosingBalance] [money]
	)


 AS  

BEGIN 
	
	
		
	Declare @OPBal money
	Select @OPBal=dbo.fn_FAS_LedgerOpBalance(@LrCode,  @Start,  '0', @CmCode)

	Insert into @RetTable

		Select DocDate,  DocNo, RefNo, VrRoute, VoucherName, n1.LedgerName as Particulars, Debit, Credit, CB as ClosingBalance
		from
		
			(Select m.VrRoute, m.DocDate, m.VoucherName, m.DocNo, m.RefNo, 
				isNull((Select Top 1 m1.LrCode from FAS_VoucherTranSub m1 
						Where m1.DocNo=m.DocNo and m1.VrRoute=m.VrRoute and m1.LrCode<>m.LrCode 
							and ((m1.DrAmt=0 AND m.Debit>0) OR (m1.CrAmt=0 AND m.Credit>0)) and m1.CompCode=@CmCode), m.LrCode) as Particulars,
				m.Debit, m.Credit, m.LrCode,
				isNull((Select Sum(DrAmt-CrAmt)  from FAS_VoucherTranSub d 
					Where d.LrCode=m.LrCode and (d.DocDate Between @Start and @End)
						and ((d.docDate < m.DocDate) or ((d.DocDate=m.DocDate) and (d.VrRoute < m.VrRoute or (d.VrRoute=m.VrRoute and d.DocNo<=m.DocNo))))
						 and d.CompCode=m.CompCode
				), 0)  + @OpBal as CB
			from	
				(Select top 100 Percent  a.VrRoute, a.DocDate, c.VoucherName, a.DocNo,
					Case When LTrim(RTrim(a.Ref))='' then b.RefType+':'+Convert(varchar, b.RefNo) else a.Ref end as RefNo,  
					a.DrAmt as Debit, a.CrAmt as Credit, a.LrCode, a.CompCode
				from FAS_Voucher_vw a Left Outer Join FAS_VoucherTranRef b
				On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode and a.DocDate=b.DocDate and a.DocType=b.DocType
				Left Outer Join FAS_VoucherMaster c On a.VrRoute=c.VrRoute+c.VrWidth and a.CompCode=c.CompCode
				Where a.LrCode = @LrCode and (a.DocDate Between @Start and @End) and a.CompCode=@CmCode 
				Order by a.DocDate,  a.DocNo
				)  m
			) n
		Left Outer Join FAS_LedgerMaster n1 On n.Particulars=n1.LedgerCode 
		Where n1.CompCode=@CmCode
		Order by DocDate, VrRoute, DocNo					

	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Dis_Vouchers_Vouchers]    Script Date: 17/06/2026 11:38:44 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Dis_Vouchers_Vouchers] (@Route varchar(42), @IncludeSubVouchers bit, @FromDate datetime, @ToDate datetime, @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))  

RETURNS @RetTable TABLE
	([VrRoute] [varchar] (42),	
	[DocDate] [datetime],
	[Particulars] [varchar] (50),	
	[RefNo] [varchar] (50),	
	[VrNo] [int],	
	[TranAmt] [money]
	)

 AS  

BEGIN 	
	
	If Len(@Route)=0  or @Route = '0'
		Begin
		Insert into @RetTable
			Select a.VrRoute, a.DocDate, 
				Case When a.isCancelled='1' Then 'CANCELLED' Else b.LedgerName End as Particulars,
				isNull(a.Ref, '') as RefNo, a.DocNo as VrNo, isNull(Sum(a.DrAmt), 0) as TranAmt
			from FAS_Voucher_vw a 
			Left Outer Join FAS_LedgerMaster b
			On a.LrCode=b.LedgerCode and a.CompCode=b.CompCode
			Where (a.DocDate between @FromDate and @ToDate)  and (a.DocDate between @PrStart and @PrEnd) and isNull(a.VTSNo, 1)=1 and a.CompCode=@CmCode
			Group by a.VrRoute, a.DocDate, a.DocNo, a.Ref, a.isCancelled, b.LedgerName 
			Order by DocDate, VrNo
		End
	Else
		If @Route='07'
			Begin
				Insert into @RetTable
					Select a.VrRoute, a.DocDate, 
						Case When a.isCancelled='1' Then 'CANCELLED' Else c.LedgerName End as Particulars,
							a.Ref as RefNo, a.DocNo as VrNo, isNull(Sum(b.DrAmt), 0) as TranAmt
					From FAS_MEM_VoucherTranMast a 
					Left Outer Join FAS_MEM_VoucherTranSub b
						On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode and b.VTSNo=1
					Left Outer Join FAS_LedgerMaster c
						On b.LrCode=c.LedgerCode and a.CompCode=b.CompCode
					Where (a.DocDate between @FromDate and @ToDate) and (a.DocDate between @PrStart and @PrEnd) and a.CompCode=@CmCode
					Group by a.VrRoute, a.DocDate, a.DocNo, a.Ref, a.isCancelled, c.LedgerName
					Order by a.DocDate, a.DocNo
			End	
		Else
			Begin
				If @IncludeSubVouchers = '1'
					Begin
						Insert into @RetTable
							Select a.VrRoute, a.DocDate, 
								Case When a.isCancelled='1' Then 'CANCELLED' Else b.LedgerName End as Particulars,
									a.Ref as RefNo, a.DocNo as VrNo, isNull(Sum(a.DrAmt), 0) as TranAmt
							from FAS_Voucher_vw a 
							Left Outer Join FAS_LedgerMaster b
								On a.LrCode=b.LedgerCode and a.CompCode=b.CompCode
							Where a.VrRoute like @Route+'%'  and (a.DocDate between @FromDate and @ToDate) and (a.DocDate between @PrStart and @PrEnd) 
								and isNull(a.VTSNo, 1)=1  and a.CompCode=@CmCode
							Group by a.VrRoute, a.DocDate, a.DocNo, a.Ref, a.isCancelled, b.LedgerName 
							Order by DocDate, VrNo
					End		
				Else
					Begin
						Insert into @RetTable
							Select a.VrRoute, a.DocDate, 
								Case When a.isCancelled='1' Then 'CANCELLED' Else b.LedgerName End as Particulars,
								a.Ref as RefNo, a.DocNo as VrNo, isNull(Sum(a.DrAmt), 0) as TranAmt
							From FAS_Voucher_vw a 
							Left Outer Join FAS_LedgerMaster b
								On a.LrCode=b.LedgerCode and a.CompCode=b.CompCode
							Where a.VrRoute = @Route  and (a.DocDate between @FromDate and @ToDate)  and (a.DocDate between @PrStart and @PrEnd) 
								and isNull(a.VTSNo, 1)=1  and a.CompCode=@CmCode
							Group by a.VrRoute, a.DocDate, a.DocNo, a.Ref, a.isCancelled, b.LedgerName 
							Order by DocDate, VrNo
					End	

			End
	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Get_ExpenseBudget_Ledgers]    Script Date: 17/06/2026 11:38:44 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Get_ExpenseBudget_Ledgers] (@StartDate datetime, @EndDate datetime,  @CmCode varchar(12))

RETURNS @RetTable TABLE
	(LrCode		int,
	ActualAmt	money
	)


 AS  

BEGIN 
		
	Insert into @RetTable

		Select a.LrCode, Sum(a.DrAmt-a.CrAmt) as ActualAmt
		From FAS_VoucherTranSub a
		Left Outer Join FAS_LedgerMaster b On b.LedgerCode = a.LrCode and b.CompCode = a.CompCode 
		Left Outer Join FAS_GroupMaster c On b.LrRoute = c.GrRoute+c.GrWidth and b.CompCode = c.CompCode 
		Where c.Master = '03' and (a.DocDate between @StartDate and @EndDate) and a.CompCode = @CmCode 
		Group By LrCode
		Order By LrCode

	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Group_SubGroupLedger_CashBank_CB]    Script Date: 17/06/2026 11:38:44 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Group_SubGroupLedger_CashBank_CB] (@PrStart datetime, @Start datetime, @End datetime, @CmCode varchar(12))  

RETURNS @RetTable TABLE
	([Master] [varchar](10),
	[Path] [varchar](42),
	[Type] [varchar] (10),
	[Code] [int],
	[Particulars] [varchar] (100),
	[OpBalance] [money],
	[DrAmt] [money],
	[CrAmt] [money],
	[ClosingBalance] [money]
	)

 AS  

BEGIN 
	
	Insert into @RetTable

		Select '', a.LrRoute, 'Ledger', a.LedgerCode, a.LedgerName, a.OpBalance as OBAmt, isNull(b.TranDrAmt, 0) as DrAmt, isNull(b.TranCrAmt, 0) as CrAmt,
			(a.OpBalance + isNull(b.TranDrAmt, 0) - isNull(b.TranCrAmt, 0)) as CBAmt
		from dbo.fn_FAS_AllOpBalance(@Start, '0', '1',  @CmCode) a Left Outer Join
			(Select LrCode, Sum(DrAmt) as TranDrAmt, Sum(CrAmt) as TranCrAmt, CompCode
			from FAS_VoucherTranSub
			Where DocDate between @Start and @End and CompCode=@CmCode
			Group by LrCode, CompCode) b
		On a.LedgerCode=b.LrCode
		Where Left(a.LrRoute, 4) in ('0201', '0202', '0B01') and a.CompCode=@CmCode


	Insert into @RetTable

		Select '', a.GrRoute+a.GrWidth, 'Group', a.GroupCode, a.GroupName, isNull(Sum(b.OpBalance), 0) as OBAmt,
			 isNull(Sum(b.DrAmt), 0) as DrAmt, isNull(Sum(b.CrAmt), 0) as CrAmt, isNull(Sum(ClosingBalance), 0) as CBAmt
		from FAS_GroupMaster a Left Outer Join @RetTable b
		On a.GrRoute+a.GrWidth = Left(b.Path, Len(a.GrRoute+a.GrWidth))
		Where Left(a.GrRoute+a.GrWidth, 4) in ('0201', '0202', '0B01') and a.CompCode=@CmCode
		Group by a.GrRoute+a.GrWidth, a.GroupName, a.GroupCode


	Delete @RetTable
	Where OpBalance=0 and DrAmt=0 and CrAmt=0 and ClosingBalance=0

	Update @RetTable Set Master=Case When Left(Path, 2)  in ('02', '09', '0A', '0C') Then '00' When Left(Path, 2) in ('01', '03', '04', '0B', '0F') Then '01'
						When Left(Path, 2) in ('06', '08', '0E') Then '02' When Left(Path, 2) in ('05', '07', '0D') Then '03' Else '04' End


	Return 

END
GO

