CREATE FUNCTION [dbo].[fn_FAS_Group_SubGroupLedger_CB] (@GrPath varchar(42), @PrStart datetime, @Start datetime, @End datetime, @CmCode varchar(12))  

RETURNS @RetTable TABLE
	([Master] [varchar](10),
	[Path] [varchar](42),
	[Type] [varchar] (10),
	[Code] [int],
	[Particulars] [varchar] (100),
	[OpBalance] [money],
	[DrAmt] [money],
	[CrAmt] [money],
	[ClosingBalance] [money]
	)

 AS  

BEGIN 
	
	Insert into @RetTable

		Select '', a.LrRoute, 'Ledger', a.LedgerCode, a.LedgerName, a.OpBalance as OBAmt, isNull(b.TranDrAmt, 0) as DrAmt, isNull(b.TranCrAmt, 0) as CrAmt,
			(a.OpBalance + isNull(b.TranDrAmt, 0) - isNull(b.TranCrAmt, 0)) as CBAmt
		from dbo.fn_FAS_AllOpBalance(@Start, '0',  '1', @CmCode) a Left Outer Join
			(Select LrCode, Sum(DrAmt) as TranDrAmt, Sum(CrAmt) as TranCrAmt, CompCode
			from FAS_VoucherTranSub
			Where DocDate between @Start and @End and CompCode=@CmCode
			Group by LrCode, CompCode) b
		On a.LedgerCode=b.LrCode
		Where Left(a.LrRoute, Len(@GrPath))=@GrPath and a.CompCode=@CmCode


	Insert into @RetTable

		Select '', a.GrRoute+a.GrWidth, 'Group', a.GroupCode, a.GroupName, isNull(Sum(b.OpBalance), 0) as OBAmt,
			 isNull(Sum(b.DrAmt), 0) as DrAmt, isNull(Sum(b.CrAmt), 0) as CrAmt, isNull(Sum(ClosingBalance), 0) as CBAmt
		from FAS_GroupMaster a Left Outer Join @RetTable b
		On a.GrRoute+a.GrWidth = Left(b.Path, Len(a.GrRoute+a.GrWidth))
		Where Left(a.GrRoute+a.GrWidth, Len(@GrPath))=@GrPath and a.CompCode=@CmCode
		Group by a.GrRoute+a.GrWidth, a.GroupName, a.GroupCode


	Delete @RetTable
	Where OpBalance=0 and DrAmt=0 and CrAmt=0 and ClosingBalance=0

	Update @RetTable Set Master=Case When Left(Path, 2)  in ('02', '09', '0A', '0C') Then '00' When Left(Path, 2) in ('01', '03', '04', '0B', '0F') Then '01'
						When Left(Path, 2) in ('06', '08', '0E') Then '02' When Left(Path, 2) in ('05', '07', '0D') Then '03' Else '04' End


	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_GroupClosingBalance_All]    Script Date: 17/06/2026 11:38:44 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [dbo].[fn_FAS_GroupClosingBalance_All] (@PrStart datetime, @RptDate datetime, @IncludeSubGroups bit, @CmCode varchar(12))  

RETURNS @RetTable TABLE
	([Master] [varchar](10),
	[Path] [varchar](42),
	[Type] [varchar] (10),
	[Code] [int],
	[Particulars] [varchar] (100),
	[ClosingBalance] [money]
	)

 AS  

BEGIN 

	Insert into @RetTable

		Select '', a.LrRoute, 'Ledger', a.LedgerCode, a.LedgerName, (a.OpBalance+isNull(b.TranCBAmt, 0)) as CBAmt
		from FAS_LedgerMaster a Left Outer Join
			(Select LrCode, Sum(DrAmt-CrAmt) as TranCBAmt, CompCode
			from FAS_VoucherTranSub
			Where DocDate <= @RptDate and CompCode=@CmCode
			Group by LrCode, CompCode) b
		On a.LedgerCode=b.LrCode
		Where a.CompCode=@CmCode and Left(a.LrRoute, 4)<>'0205'


	Insert into @RetTable
		
		Select '', '0205', 'Ledger', 0, 'Closing Stock', Sum(ClosingStock)
		from dbo.fn_FAS_StockValue(@PrStart, @RptDate, @CmCode)


	if @IncludeSubGroups='1'
		Begin

			Insert into @RetTable
		
				Select '', a.GrRoute+a.GrWidth, 'Group', a.GroupCode, a.GroupName,  isNull(Sum(ClosingBalance), 0) as CBAmt
				from FAS_GroupMaster a Left Outer Join @RetTable b
				On a.GrRoute+a.GrWidth = Left(b.Path, Len(a.GrRoute+a.GrWidth))
				Where a.CompCode=@CmCode
				Group by a.GrRoute+a.GrWidth, a.GroupName, a.GroupCode
		End
	else
		Begin

			Insert into @RetTable
		
				Select '', a.GrRoute+a.GrWidth, 'Group', a.GroupCode, a.GroupName, isNull(Sum(ClosingBalance), 0) as CBAmt
				from FAS_GroupMaster a Left Outer Join @RetTable b
				On a.GrRoute+a.GrWidth = b.Path
				Where a.CompCode=@CmCode
				Group by a.GrRoute+a.GrWidth, a.GroupName, a.GroupCode
		End

	Delete @RetTable
	Where (Type='Ledger' or ClosingBalance=0)


	Update @RetTable Set Master=Case When Left(Path, 2)  in ('02', '09', '0A', '0C') Then '00' When Left(Path, 2) in ('01', '03', '04', '0B', '0F') Then '01'
						When Left(Path, 2) in ('06', '08', '0E') Then '02' When Left(Path, 2) in ('05', '07', '0D') Then '03' Else '04' End


	Return 

END








GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_GroupClosingBalance_Single]    Script Date: 17/06/2026 11:38:44 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [dbo].[fn_FAS_GroupClosingBalance_Single] (@GrPath varchar(42), @RptDate datetime, @IncludeSubGroups bit, @ReturnSubGroups bit, @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))  

RETURNS @RetTable TABLE
	([Master] [varchar](10),
	[Path] [varchar](42),
	[Type] [varchar] (10),
	[Code] [int],
	[Particulars] [varchar] (100),
	[ClosingBalance] [money]
	)


 AS  

BEGIN 
	
	Insert into @RetTable

		Select '', a.LrRoute, 'Ledger', a.LedgerCode, a.LedgerName, (a.OpBalance+isNull(b.TranCBAmt, 0)) as CBAmt
		from FAS_LedgerMaster a Left Outer Join
			(Select LrCode, Sum(DrAmt-CrAmt) as TranCBAmt, CompCode
			from FAS_VoucherTranSub
			Where DocDate <= @RptDate and CompCode=@CmCode
			Group by LrCode, CompCode) b
		On a.LedgerCode=b.LrCode
		Where Left(a.LrRoute, Len(@GrPath))=@GrPath and a.CompCode=@CmCode and Left(a.LrRoute,4) <>'0205'


	Insert into @RetTable
		
		Select '', '0205', 'Ledger', 0, 'Closing Stock', Sum(ClosingStock)
		from dbo.fn_FAS_StockValue(@PrStart, @RptDate, @CmCode)


	if @IncludeSubGroups='1'
		Begin

			Insert into @RetTable
		
				Select '', a.GrRoute+a.GrWidth, 'Group', a.GroupCode, a.GroupName,  isNull(Sum(ClosingBalance), 0) as CBAmt
				from FAS_GroupMaster a Left Outer Join @RetTable b
				On a.GrRoute+a.GrWidth = Left(b.Path, Len(a.GrRoute+a.GrWidth))
				Where Left(a.GrRoute+a.GrWidth, Len(@GrPath))=@GrPath and a.CompCode=@CmCode
				Group by a.GrRoute+a.GrWidth, a.GroupName, a.GroupCode
		End
	else
		Begin

			Insert into @RetTable
		
				Select '', a.GrRoute+a.GrWidth, 'Group', a.GroupCode, a.GroupName, isNull(Sum(ClosingBalance), 0) as CBAmt
				from FAS_GroupMaster a Left Outer Join @RetTable b
				On a.GrRoute+a.GrWidth = b.Path
				Where Left(a.GrRoute+a.GrWidth, Len(@GrPath))=@GrPath and a.CompCode=@CmCode
				Group by a.GrRoute+a.GrWidth, a.GroupName, a.GroupCode
		End

	Delete @RetTable
	Where (Type='Ledger' or ClosingBalance=0)

	if @ReturnSubGroups='0'
		Begin
			Delete @RetTable
			Where Path<>@GrPath
		End

	Update @RetTable Set Master=Case When Left(Path, 2)  in ('02', '09', '0A', '0C') Then '00' When Left(Path, 2) in ('01', '03', '04', '0B', '0F') Then '01'
						When Left(Path, 2) in ('06', '08', '0E') Then '02' When Left(Path, 2) in ('05', '07', '0D') Then '03' Else '04' End


	Return 

END








GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Ledger_LockDate]    Script Date: 17/06/2026 11:38:44 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [dbo].[fn_FAS_Ledger_LockDate] (@LrCode int,  @CmCode varchar(12))
					
RETURNS @RetTable TABLE

	([LDate] [datetime])

 AS  

BEGIN 
	
	
	/*  Retrieve Ledger LockDate */	
	
	Insert into @RetTable		
		Select  LockDate From FAS_EntriesLock 
		Where Code = @LrCode and LockType = 'L' and CompCode = @CmCode
	
	/*  Retrieve Group LockDate */		
	Declare @Route varchar(42)
	Select @Route=LrRoute from FAS_LedgerMaster Where LedgerCode=@LrCode and CompCode=@CmCode

	While Len(@Route) >= 2
	Begin
		Insert @RetTable
			Select  LockDate From FAS_EntriesLock 
			Where  Route = @Route and LockType = 'G' and CompCode = @CmCode
				
			Select @Route =Left(@Route, Len(@Route)-2)
	End


	Delete @RetTable
		Where LDate <> (Select Max(LDate)  From @RetTable)


	Return

END




















































GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_LedgerClosingBalance_Sel]    Script Date: 17/06/2026 11:38:44 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_LedgerClosingBalance_Sel] (@LrUserKey varchar(36)='', @LrCode int, @GrPath varchar(42), @NoSubGroups bit, @CBDate datetime, @CmCode varchar(12))        
       
RETURNS   
    @Ledger TABLE      
    (  
        LedgerCode int,      
        LedgerName varchar(50),      
        Alias  varchar(50),      
        LrRoute  varchar(42),      
        isBillwise bit,       
        CreditDays  int,      
        ClosingBalance money,      
        isCostCentreApplicable bit,      
        CompCode varchar(12)  
    )      
        
AS        
      
BEGIN  
    Declare @OBForDate datetime  
    Select @OBForDate=DateAdd(day, 1, @CBDate)  
  
      
    Declare @ResultGroupString varchar(43)  
    If @NoSubGroups=Convert(bit, '1')  
        Select @ResultGroupString=@GrPath  
    Else  
        Select @ResultGroupString=@GrPath+'%'  
          
    
    Insert into @Ledger        
    Select a.LedgerCode, a.LedgerName, a.Alias, a.LrRoute, a.isBillwise, a.Creditdays, a.OpBalance+isNull(b.TranAmt, 0) as OpBalance,      
        a.isCostCentreApplicable, a.CompCode      
    From FAS_LedgerMaster_AuthTbl a  
           
    Left Outer Join (Select LrCode, Sum(DrAmt-CrAmt) as TranAmt from FAS_VoucherTranSub     
                    Where DocDate<@OBForDate and CompCode=@CmCode    
                    Group By LrCode) b    
        On a.LedgerCode=b.LrCode  
            
    Where a.CompCode=@CmCode    
        and (  
                (@LrCode<>0 AND a.LedgerCode=@LrCode)  
                OR  
                (@LrCode=0 AND (@LrUserKey='' OR     
                                Exists (Select * From COM_SelectList s1    
                                        Where s1.UserKey=@LrUserKey and s1.SelectInt=a.LedgerCode    
                                        )  
                                )    
                )  
            )    
        and (@GrPath='' OR a.LrRoute Like @ResultGroupString)  
  
      
    If Exists (Select * From @Ledger Where LrRoute Like '0205%')  
    BEGIN  
        Update @Ledger Set ClosingBalance=isNull(c.OpeningStock, 0)  
        From @Ledger a  
          
        Left Outer Join dbo.fn_FAS_StockValue(@OBForDate, @OBForDate, @CmCode) c       
            On a.LedgerCode=c.LedgerCode  
              
        Where a.LrRoute Like '0205%'     
      
    END  
              
 RETURN      
      
END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_LedgersClosingBalance]    Script Date: 17/06/2026 11:38:45 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [dbo].[fn_FAS_LedgersClosingBalance] (@PrStart datetime, @Start datetime, @End datetime, @CmCode varchar(12))  

RETURNS @RetTable TABLE
	([Master] [varchar](10),
	[Path] [varchar](42),
	[Type] [varchar] (10),
	[Code] [int],
	[Particulars] [varchar] (100),
	[ClosingBalance] [money]
	)
 AS  

BEGIN 
	
	Declare @tmpDate datetime
	Select @tmpDate = DateAdd(day, -1, @Start)

	Insert into @RetTable

		Select '', a.LrRoute, 'Ledger', a.LedgerCode, a.LedgerName, 
			Case When a.LrRoute like '0205' Then c.ClosingStock Else(a.OpBalance + isNull(b.TranDrAmt, 0) - isNull(b.TranCrAmt, 0)) End as CBAmt
		from dbo.fn_FAS_AllOpBalance(@PrStart, '0', '0', @CmCode) a 
		Left Outer Join
			(Select LrCode, Sum(TranDrAmt) as TranDrAmt, Sum(TranCrAmt) as TranCrAmt
			from
				(Select LrCode, Case When DocDate between @Start and @End Then (DrAmt) Else 0 End as TranDrAmt,
						Case When DocDate between @Start and @End Then (CrAmt) Else 0 End as TranCrAmt, CompCode
				from FAS_VoucherTranSub
				Where DocDate between @PrStart and @End and CompCode=@CmCode) x
			Group by LrCode, CompCode) b
		On a.LedgerCode=b.LrCode
			Left Outer Join dbo.fn_FAS_StockValue (@Start, @End, @CmCode) c
			On a.LedgerCode=c.LedgerCode
		Where a.CompCode=@CmCode and a.LedgerCode<>2
/*
	Insert into @RetTable

		Select '', '0205',  'Ledger' as Type, 0,  WHSCode, ClosingStock
		from dbo.fn_FAS_StockValue (@Start, @End, @CmCode)
		where ClosingStock<>0
*/

	If (@PrStart=@Start)
		Begin
			Insert into @RetTable
		
				Select '', '00PO', 'Ledger', -3, 'Opening Balance', OpBalance  as Amount
				from FAS_LedgerMaster
				where LedgerCode=2 and CompCode=@CmCode
		End
	Else
		Begin
			Insert into @RetTable
		
				Select '', '00PO', 'Ledger', -3, 'Opening Balance', OpBalance + dbo.fn_FAS_Profit_Loss_Period(@PrStart, @tmpDate, @CmCode) as Amount
				from FAS_LedgerMaster
				where LedgerCode=2 and CompCode=@CmCode
		End
				

	Insert into @RetTable			

		Select '', '00PC', 'Ledger', -2, 'Current Period', dbo.fn_FAS_Profit_Loss_Period(@PrStart, @End, @CmCode) as Amount
	
		UNION ALL
	
		Select '', '00PT', 'Ledger', -1, 'Less Transfered', -isnull((sum(DrAmt)-sum(CrAmt)), 0) as Amount
		from FAS_Voucher_Vw 
		where DocDate between @PrStart and  @End and LrCode=2 and Compcode = @CmCode	



/*
	Delete @RetTable
	Where OpBalance=0 and DrAmt=0 and CrAmt=0 and ClosingBalance=0
*/

	Insert into @RetTable

		Select '', a.Path, 'Group', a.GroupCode, a.GroupName, isNull(Sum(ClosingBalance), 0) as CBAmt
		from 
			(Select GroupCode, GroupName, GrRoute+GrWidth as Path, CompCode from FAS_GroupMaster 

			Union All

			Select 0, 'PROFIT & LOSS A/C', '00', @CmCode			
			) a 

			Left Outer Join @RetTable b
			On a.Path = Left(b.Path, Len(a.Path))
			Where a.CompCode=@CmCode
			Group by a.Path, a.GroupName, a.GroupCode

/*	
	Delete @RetTable
	Where OpBalance=0 and DrAmt=0 and CrAmt=0 and ClosingBalance=0
*/

	Insert into @RetTable

		Select '', 'ZZ', 'Group', 0, 'Diff. in Opening Balance', IsNull(-Sum(OpBalance), 0)
		from dbo.fn_FAS_AllOpBalance(@PrStart, '0', '0', @CmCode) 
		Where Compcode = @CmCode


	Delete @RetTable
	Where ClosingBalance=0

	Update @RetTable Set Master=Case When Left(Path, 2)  in ('02', '09', '0A', '0C') Then '00' When Left(Path, 2) in ('01', '03', '04', '0B', '0F') Then '01'
						When Left(Path, 2) in ('06', '08', '0E') Then '02' When Left(Path, 2) in ('05', '07', '0D') Then '03' Else '04' End


	Return 

END

GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Months]    Script Date: 17/06/2026 11:38:45 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [dbo].[fn_FAS_Months] (@StartDate datetime, @EndDate datetime)  

RETURNS @RetTable TABLE
	([MonthDate] [datetime]
	)

 AS  

BEGIN 

	Declare @StDate datetime
	Select @StDate = Convert(datetime, Convert(varchar(6), @StartDate, 112) + '01', 112)

	Declare @MnCnt int
	Select @MnCnt = Datediff(mm, @StartDate, @EndDate) + 1

	Declare @Cnt int
	Select @Cnt = 0

	While @Cnt < @MnCnt
		Begin
			Insert @RetTable
				Select DateAdd(mm, @Cnt, @StDate)

			Select @Cnt = @Cnt + 1
		End

	Return 

END

GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_OutstandingBills]    Script Date: 17/06/2026 11:38:45 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [dbo].[fn_FAS_OutstandingBills] (@LrRoute varchar(42), @AsOnDate datetime, @CmCode varchar(12))  

RETURNS @Outstanding TABLE
	(LedgerCode	int,
	LedgerName	varchar(50),
	LrRoute		varchar(42),
	VrName		varchar(50),
	VrAlias		varchar(10),
	VrDate		datetime,	
	VrNo		varchar(50),
	RefNo		varchar(50),
	RefDate	datetime,
	InitialAmt	money,
	BalanceAmt	money,
	DueDate	datetime,
	SortOrder	int,
	CompCode	varchar(12))
		
AS  

BEGIN 
	--On Acct data insert
	Insert into @Outstanding		
		Select LrCode, '' as LedgerName, '' as LrRoute, '' as VrName, '' as VrAlias, Null as VrDate, 0 as VrNo, '' as RefNo, Null as RefDate, Sum(Amount) as InitialAmt, 0 as BalanceAmt, @AsOnDate as DueDate, 999999 as SortOrder, @CmCode as CompCode
		From FAS_BillDetails a
		Where Type = 'On Acct' and RefDate <= @AsOnDate and CompCode=@CmCode
			and Exists (Select * from FAS_LedgerMaster b Where a.LrCode=b.LedgerCode and b.LrRoute like @LrRoute+'%' and a.CompCode=b.CompCode)
		Group by LrCode
		Having Sum(Amount) <> 0

	--Balance Amount Updated
	Update @Outstanding Set BalanceAmt=InitialAmt

	--New Ref Bill Data Insert
	Insert into @Outstanding		
		Select LrCode, '' as LedgerName, '' as LrRoute, VrRoute as VrName, '' as VrAlias, DocDate as VrDate, DocNo as VrNo, RefNo, RefDate, Amount, 0 as BalanceAmt, DateAdd(day, CreditDays, RefDate) as DueDate, 0 as SortOrder, @CmCode as CompCode
		From FAS_BillDetails a
		Where Type = 'New Ref' and RefDate <= @AsOnDate and CompCode=@CmCode
			and Exists (Select * from FAS_LedgerMaster b Where a.LrCode=b.LedgerCode and b.LrRoute like @LrRoute+'%' and a.CompCode=b.CompCode)

	--New Ref Data missing but Agst Ref available - data Insert
	Insert into @Outstanding		
		Select LrCode, '' as LedgerName, '' as LrRoute, VrRoute as VrName, '' as VrAlias, DocDate as VrDate, DocNo as VrNo, RefNo, RefDate, Amount, 0 as BalanceAmt, DateAdd(day, CreditDays, RefDate) as DueDate, 0 as SortOrder, @CmCode as CompCode
		From FAS_BillDetails a
		Where Type = 'Agst Ref' and RefDate <= @AsOnDate and CompCode=@CmCode
			and Not Exists (Select * From FAS_BillDetails b Where a.RefNo=b.RefNo and a.LrCode=b.LrCode and a.CompCode=b.CompCode)
			and RefDate=(Select Min(RefDate) from FAS_BillDetails c Where a.RefNo=c.RefNo and a.LrCode=c.LrCode and a.CompCode=c.CompCode)
			and Exists (Select * from FAS_LedgerMaster b Where a.LrCode=b.LedgerCode and b.LrRoute like @LrRoute+'%' and a.CompCode=b.CompCode)

	--Advance data Insert
	Insert into @Outstanding		
		Select LrCode, '' as LedgerName, '' as LrRoute, VrRoute as VrName, '' as VrAlias, DocDate as VrDate, DocNo as VrNo, RefNo, RefDate, Amount, 0 as BalanceAmt, DateAdd(day, CreditDays, RefDate) as DueDate, 0 as SortOrder, @CmCode as CompCode
		From FAS_BillDetails a
		Where Type = 'Advance' and RefDate <= @AsOnDate and CompCode=@CmCode
			and RefDate=(Select Min(RefDate) from FAS_BillDetails c Where a.RefNo=c.RefNo and a.LrCode=c.LrCode and a.CompCode=c.CompCode)
			and Exists (Select * from FAS_LedgerMaster b Where a.LrCode=b.LedgerCode and b.LrRoute like @LrRoute+'%' and a.CompCode=b.CompCode)


	--Balance Amount Updated
	Update @Outstanding Set BalanceAmt=(Select Sum(InitialAmt) from @Outstanding b Where a.RefNo=b.RefNo and a.LedgerCode=b.LedgerCode and a.CompCode=b.CompCode)
		From @Outstanding a 

	--Delete Completed Bills
	Delete From @Outstanding Where BalanceAmt=0

	--Ledger Details Updated
	Update @Outstanding Set LedgerName=b.LedgerName, LrRoute=b.LrRoute
		From @Outstanding a Left Outer Join FAS_LedgerMaster b
			On a.LedgerCode=b.LedgerCode and a.CompCode=b.CompCode

	--Delete Non-Interested Ledgers
	Delete From @Outstanding Where Not (LrRoute like @LrRoute+'%')

	--Voucher Details Updated
	Update @Outstanding Set VrName=b.VoucherName, VrAlias=b.Alias, VrNo=b.Prefix+a.VrNo+b.Suffix
		From @Outstanding a Left Outer Join FAS_VoucherMaster b
			On a.VrName=b.VrRoute+b.VrWidth and a.CompCode=b.CompCode

	Return

END



GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Return_StartEndDates_SplitUp]    Script Date: 17/06/2026 11:38:45 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Return_StartEndDates_SplitUp] 
							(@PrStart datetime, @PrEnd datetime, @isSplitUpRequired bit, @SplitUpAs varchar(5), 
								@isTakeConventionalStartEnd bit, @isExtendBeyondStart bit, @isExtendBeyondEnd bit, 
								@isConventionYearStartFinyear bit, @isConventionWeekStartDate bit, @isWeekMerge_5thWeek_With_4thWeek bit)  

/* @isSplitUpRequired = '0' The Output returns only initial start & final End; otherwise return all the splitup start and end dates */
/* @SplitUpAs = 'Year', 'Month', 'Week', 'Day'; Other values or treated as 'Day' */

/* @isConventionYearStartFinyear = '1' - 1st April; '0' - 1st January 
		(Applicable only when @SplitUpAs='Year') */

/* @isConventionWeekStartDate = '1' - 1st, 8th, 15th, 22st, 29th; '0' - Monday Dates 
		(Applicable only when @SplitUpAs='Week') */

/* @isWeekMerge_5thWeek_With_4thWeek = '1' - 1st, 8th, 15th, 22st (29-31 merge in 22-28); '0' - 1st, 8th, 15th, 22st, 29th 
		(Applicable only when @SplitUpAs='Week' and isConventionWeekStartDate='1') */

/* Example Data for below Arguements @PrStart='2010-03-19', @PrEnd='2010-04-09', @SplitUpAs='Week' */

/* @isTakeConventionalStartEnd = '1'; '19th - 21nd', '22nd - 28th', '29th - 4th', '5th - 9th' (taking Monday as WeekStart) */
/* @isTakeConventionalStartEnd = '0'; '19th - 25th', '26th - 1st', '2nd - 8th', '9th - 9th' (taking Monday as WeekStart) */

/* @isExtendBeyondStart is Applicable only when @isTakeConventionalStartEnd = '1' */
/* @isExtendBeyondStart = '1' & @isTakeConventionalStartEnd = '1' then Series Starts with '15th-21nd' etc */
/* @isExtendBeyondEnd = '1' & @isTakeConventionalStartEnd = '1' then Series Ends with '5th-11th' etc */


RETURNS @PrSplit TABLE
	(
	PrStart	datetime,
	PrEnd	datetime
	)
		
AS  

BEGIN 

	Declare @tmp int

	Declare @InitialStart datetime
	Declare @FinalEnd datetime
	
	/* To find Initial Start Date */
	If (@isExtendBeyondStart = '1' AND @isTakeConventionalStartEnd = '1')
		BEGIN
			If (@SplitUpAs = 'YEAR')
 				If (@isConventionYearStartFinyear='1')
					If (Month(@PrStart)<=3)
						Select @InitialStart = Convert(datetime, Convert(varchar, Year(@PrStart)-1) + '0401', 112)
					Else
						Select @InitialStart = Convert(datetime, Convert(varchar, Year(@PrStart)) + '0401', 112)
				Else
					Select @InitialStart = Convert(datetime, Convert(varchar, Year(@PrStart)) + '0101', 112)
							
			Else				
			If (@SplitUpAs =  'MONTH')
				Select @InitialStart = Convert(datetime, Convert(varchar(6), @PrStart, 112) + '01', 112)
			
			Else		
			If (@SplitUpAs = 'WEEK')
				If (@isConventionWeekStartDate='1')
					If (@isWeekMerge_5thWeek_With_4thWeek='1') AND (Day(@PrStart) >= 29)
						Select @InitialStart = Convert(datetime, Convert(varchar(6), @PrStart, 112) + '22', 112)
					Else
						BEGIN
							Select @tmp = (Convert(int, (Day(@PrStart)-1)/7) * 7) + 1
							Select @InitialStart = Convert(datetime, Convert(varchar(6), @PrStart, 112) + Case When @tmp<10 Then '0' Else '' End + Convert(varchar, @tmp), 112)
						END
				Else
					BEGIN
						Select @tmp=DatePart(weekday, @PrStart)
						Select @tmp=Case When @tmp=1 Then 7 Else @tmp-1 End
						
						Select @InitialStart = DateAdd(day, (1-@tmp), @PrStart)
					END
					
			Else	/* Day */
					Select @InitialStart = @PrStart
			
		END
	Else
		Select @InitialStart = @PrStart
		

	/* To find Final End Date */
	If (@isExtendBeyondEnd = '1' AND @isTakeConventionalStartEnd = '1')
		If (@SplitUpAs = 'YEAR')
			If (@isConventionYearStartFinyear='1')
				If (Month(@PrEnd)<=3)
					Select @FinalEnd = Convert(datetime, Convert(varchar, Year(@PrEnd)) + '0331', 112)
				Else
					Select @FinalEnd = Convert(datetime, Convert(varchar, Year(@PrEnd)+1) + '0331', 112)
			Else
				Select @FinalEnd = Convert(datetime, Convert(varchar, Year(@PrEnd)) + '1231', 112)
						
		Else
		If (@SplitUpAs = 'MONTH')
			Select @FinalEnd = DateAdd(day, -1, DateAdd(month, 1, Convert(datetime, Convert(varchar(6), @PrEnd, 112) + '01', 112)))
					
		Else
		If (@SplitUpAs = 'WEEK')
			If (@isConventionWeekStartDate='1')
				If (@isWeekMerge_5thWeek_With_4thWeek='1') AND (Day(@PrEnd) >= 29)
					Select @FinalEnd = Convert(datetime, Convert(varchar(6), @PrEnd, 112) + '28', 112)
				Else
					BEGIN
						Select @tmp = (Convert(int, (Day(@PrEnd)-1)/7) + 1) * 7
						If (@tmp > 28)
							Select @FinalEnd = DateAdd(day, -1, DateAdd(month, 1, Convert(datetime, Convert(varchar(6), @PrEnd, 112) + '01', 112)))
						Else
							Select @FinalEnd = Convert(datetime, Convert(varchar(6), @PrEnd, 112) + Case When @tmp<10 Then '0' Else '' End + Convert(varchar, @tmp), 112)
					END
			Else
				BEGIN
					Select @tmp=DatePart(weekday, @PrEnd)
					Select @tmp=Case When @tmp=1 Then 7 Else @tmp-1 End
					
					Select @FinalEnd = DateAdd(day, (7-@tmp), @PrEnd)
				END
				
			Else	/* Day */
				Select @FinalEnd = @PrEnd
		
	Else
		Select @FinalEnd = @PrEnd

	
	If (@isSplitUpRequired=Convert(bit, '1'))
		BEGIN
			Declare @tmpStart datetime
			Declare @tmpEnd datetime
			
			Select @tmpStart = @InitialStart
			
			WHILE (@tmpStart <= @FinalEnd)
				BEGIN
					Select @tmpEnd = 
									CASE @SplitUpAs
										WHEN 'YEAR' THEN DateAdd(day, -1, DateAdd(year, 1, @tmpStart))
										WHEN 'MONTH' THEN DateAdd(day, -1, DateAdd(month, 1, @tmpStart))
										WHEN 'WEEK' THEN DateAdd(day, 6, @tmpStart)
										ELSE @tmpStart
									END
					
					If (@tmpEnd > @FinalEnd)
						Select @tmpEnd = @FinalEnd
						
					Insert into @PrSplit 
						Select @tmpStart, @tmpEnd
						
					Select @tmpStart = DateAdd(day, 1, @tmpEnd)
				END
		END
	Else
		Insert into @PrSplit 
						Select @InitialStart, @FinalEnd
	Return

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Rpt_Ageing_Detail]    Script Date: 17/06/2026 11:38:45 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE function [dbo].[fn_FAS_Rpt_Ageing_Detail] (@UserKey varchar(36), @isByDueDate bit, @RptType Char(1), @RptDate Datetime, @Start datetime, @End datetime, @CmCode varchar(12)) 
	--@RptType means Credit/Debit/Both 'C'/'D'  --@isByDueDate if 1 then DueDate else BillDate
Returns @RetTable Table
	(	DocNo 		int,
		DocDate 	datetime,
		RefNo 		Varchar(50),	
		RefDate	datetime,		
		LrCode		int,
		LrRoute 	Varchar(42),
		VrRoute 	Varchar(42),
		VrName  	Varchar(50),		
		InitialAmt 	money,
		BalanceAmt	 money,
		Amt_1		money,
		Amt_2		money,
		Amt_3		money,
		Amt_4		money,
		Amt_5		money,
		DueDate	datetime,
		OverDue	int)
		
AS

Begin	
	
	Declare @BranchID varchar(2)
	Select @BranchID = substring(@CmCode, 3, 2)

	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)

/*
	Declare @From datetime, @To datetime
	Select @From=Case Left(@Status, 1) when '0' then (Select Min(Refdate) from Fas_BillDetails where CompCode=@CmCode) Else @Start End 
	Select @To=Case Right(@Status, 1) when '0' then (Select Max(Refdate) from Fas_BillDetails where CompCode=@CmCode) Else @End End
*/

	Insert into @RetTable
		Select 0, Null, RefNo, (Select Min(RefDate) from FAS_BillDetails m1 Where m1.RefNo=m.RefNo 
											--and m1.RefDate>'1900-01-01'		--Need to Uncomment after finalize
											and m1.LrCode=m.LrCode and m1.CompCode=@CmCode) as RefDate, 
			LrCode, '', '', '', 0, BalanceAmt, 0, 0, 0, 0, 0, Null, 0
		from
			(Select a.LrCode, a.RefNo, Sum(a.Amount)as BalanceAmt
			from fas_billdetails a 
			Where a.LrCode in (Select selectInt From Com_SelectList Where UserKey = @UserKey
										and BranchID = @BranchID and CompID = @CompID) 
				and a.Type <> 'On Acct' and a.DocDate <= @RptDate and a.CompCode=@CmCode
			group by a.LrCode, a.RefNo 
			having Sum(a.Amount)<>0
			) m


	if @RptType = 'C' -- Credit only display
			Begin 
				Delete @RetTable Where BalanceAmt > 0						
			End

		if @RptType = 'D' -- Debit only display
			Begin 
				Delete @RetTable Where BalanceAmt < 0						
			End

	Update @RetTable Set DocNo=p.DocNo, DocDate=p.DocDate, VrRoute=p.VrRoute, VrName= isNull(q.VoucherName, 'OpBal'),
				InitialAmt=p.Amount, DueDate=DateAdd(day, p.CreditDays, p.RefDate), OverDue=(DateDiff(day, p.RefDate, @RptDate) - p.CreditDays),
				LrRoute=r.LrRoute
	From @RetTable n
		Left Outer Join FAS_BillDetails p 
			On n.RefNo=p.RefNo and n.RefDate=p.RefDate and n.LrCode=p.LrCode and p.CompCode=@CmCode
		Left Outer Join FAS_VoucherMaster q
			On (q.VrRoute+q.VrWidth)=p.VrRoute and q.CompCode=p.CompCode
		Left Outer Join Fas_LedgerMaster r
			On n.LrCode=r.LedgerCode and r.CompCode=p.CompCode


	/*Update @RetTable Set DocNo=p.DocNo, DocDate=p.DocDate, VrRoute=p.VrRoute, VrName= isNull(q.VoucherName, 'OpBal'),
				InitialAmt=p.Amount, DueDate=DateAdd(day, p.CreditDays, p.RefDate), OverDue=(DateDiff(day, p.RefDate, @RptDate) - p.CreditDays)
	From @RetTable n
		Left Outer Join FAS_BillDetails p 
			On n.RefNo=p.RefNo and n.RefDate=p.RefDate and n.LrCode=p.LrCode and p.CompCode=@CmCode
		Left Outer Join FAS_VoucherMaster q
			On (q.VrRoute+q.VrWidth)=p.VrRoute and q.CompCode=p.CompCode
		Left Outer Join Fas_LedgerMaster r
			On n.LrCode=r.LedgerCode and r.CompCode=p.CompCode



	Update @RetTable Set LrRoute=r.LrRoute, VrName= isNull(q.VoucherName, 'OpBal')
	From @RetTable n
		Left Outer Join FAS_BillDetails p 
			On n.RefNo=p.RefNo and n.RefDate=p.RefDate and n.LrCode=p.LrCode and p.CompCode=@CmCode
		Left Outer Join FAS_VoucherMaster q
			On (q.VrRoute+q.VrWidth)=p.VrRoute and q.CompCode=p.CompCode
		Left Outer Join Fas_LedgerMaster r
			On n.LrCode=r.LedgerCode and r.CompCode=p.CompCode*/



	Update @RetTable Set	 Amt_1=isNull(Case When DateDiff(day, Case When @isByDueDate='1' Then DueDate Else RefDate End, @RptDate) <=
							(Select StartValue from FAS_AgeingReport_Option_tmp Where Sequence=1 and UserKey=@UserKey and CompCode=@CmCode)
						Then a.BalanceAmt  Else 0 End, 0),

				Amt_2=isNull(Case When DateDiff(day, Case When @isByDueDate='1' Then DueDate Else RefDate End, @RptDate) Between
							(Select StartValue from FAS_AgeingReport_Option_tmp Where Sequence=1 and UserKey=@UserKey and CompCode=@CmCode)+1 And
							(Select EndValue from FAS_AgeingReport_Option_tmp Where Sequence=1 and UserKey=@UserKey and CompCode=@CmCode)
						Then a.BalanceAmt  Else 0 End, 0),

				Amt_3=isNull(Case When DateDiff(day, Case When @isByDueDate='1' Then DueDate Else RefDate End, @RptDate) Between
							(Select StartValue from FAS_AgeingReport_Option_tmp Where Sequence=2 and UserKey=@UserKey and CompCode=@CmCode)+1 And
							(Select EndValue from FAS_AgeingReport_Option_tmp Where Sequence=2 and UserKey=@UserKey and CompCode=@CmCode)
						Then a.BalanceAmt  Else 0 End, 0),


				Amt_4=isNull(Case When DateDiff(day, Case When @isByDueDate='1' Then DueDate Else RefDate End, @RptDate) Between
							(Select StartValue from FAS_AgeingReport_Option_tmp Where Sequence=3 and UserKey=@UserKey and CompCode=@CmCode)+1 And
							(Select EndValue from FAS_AgeingReport_Option_tmp Where Sequence=3 and UserKey=@UserKey and CompCode=@CmCode)
						Then a.BalanceAmt  Else 0 End, 0),

				Amt_5=isNull(Case When DateDiff(day, Case When @isByDueDate='1' Then DueDate Else RefDate End, @RptDate) >
							(Select EndValue from FAS_AgeingReport_Option_tmp Where Sequence=3 and UserKey=@UserKey and CompCode=@CmCode) 
						Then a.BalanceAmt  Else 0 End, 0)

	From @RetTable a


Return

End
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Rpt_Ageing_Summary]    Script Date: 17/06/2026 11:38:45 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Rpt_Ageing_Summary] (@UserKey Varchar(36), @isByDueDate bit,  @RptType Char(1), @RptDate Datetime, @Start datetime, @End datetime, @CmCode varchar(12))   
 --@RptType means Credit/Debit/Both 'C'/'D'  --@isByDueDate if 1 then DueDate else BillDate  
RETURNS @RetTable TABLE  
 ([LrCode] int,  
 [LrName] [Varchar] (100),  
 [Amount] [money],  
 [OnAcct] [money],  
 [Amt_1] [money],  
 [Amt_2] [money],  
 [Amt_3] [money],  
 [Amt_4] [money],  
 [Amt_5] [money],  
 [LrRoute] [varchar](42)  
 )  
AS  
  
Begin  
   
/*   
 Insert into @RetTable  
  Select LrCode, '', Sum(BalanceAmt), 0, Sum(Amt_1), Sum(Amt_2), Sum(Amt_3), Sum(Amt_4), Sum(Amt_5), LrRoute  
  From [dbo].[fn_FAS_Rpt_Ageing_Detail] (@UserKey, @isByDueDate,  @RptType, @RptDate, @Start, @End, @CmCode)   
  Group By LrCode, LrRoute  
*/  

    Insert into @RetTable                 
        Select a.LedgerCode as LrCode, a.LedgerName as LrName, isNull(b.PendingAmt, 0) as BillAmt,                
            a.ClosingBalance-isNull(b.PendingAmt, 0) as OnAcct,     -- 0 as OnAcct,   
            isNull(b.Amt_1, 0) as Amt_1, isNull(b.Amt_2, 0) as Amt_2,               
            isNull(b.Amt_3, 0) as Amt_3, isNull(b.Amt_4, 0) as Amt_4, isNull(b.Amt_5, 0) as Amt_5, a.LrRoute                  
        From dbo.fn_FAS_LedgerClosingBalance_Sel(@UserKey, 0, '', '0', @RptDate, @CmCode) a      
                      
        Left Outer Join                  
            (Select LrCode, Sum(BalanceAmt) as PendingAmt, Sum(Amt_1) as Amt_1, Sum(Amt_2) as Amt_2, Sum(Amt_3) as Amt_3, Sum(Amt_4) as Amt_4, Sum(Amt_5) as Amt_5                   
              From [dbo].[fn_FAS_Rpt_Ageing_Detail](@UserKey, @isByDueDate,  @RptType, @RptDate, @Start, @End, @CmCode)                  
              Group By LrCode                  
            ) b              
            On a.LedgerCode=b.LrCode


/*  
 Update @RetTable Set OnAcct=b.OnAcct, LrName=b.LedgerName  
 From @RetTable a  
  Left Outer Join   
   ( Select a.LedgerCode as LrCode, a.LedgerName, (a.OpBalance+isNull(Sum(b.DrAmt-b.CrAmt), 0)-isNull(c.BillAmt, 0)) as OnAcct   
    From FAS_LedgerMaster a    
   Left Outer Join (Select LrCode, Sum(Amount) as BillAmt From FAS_BillDetails Where Type<>'On Acct'   
   and DocDate<=@RptDate and CompCode=@CmCode Group by LrCode) c   
   On a.LedgerCode=c.LrCode   
   Left Outer Join FAS_VoucherTranSub b   
    On a.LedgerCode=b.LrCode and a.CompCode=b.CompCode and b.DocDate<=@RptDate   
   Where Left(a.LrRoute, 4) in ('0206', '0303') and a.CompCode=@CmCode  
   Group By a.LedgerCode, a.LedgerName,a.OpBalance, c.BillAmt) b  
  On a.LrCode=b.LrCode  
  */
 Return  
  
END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Rpt_Budget_TrialBalance]    Script Date: 17/06/2026 11:38:45 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Rpt_Budget_TrialBalance] (@RptType char(1), @Start datetime, @End datetime, @ActualsCutOff datetime, @CmCode varchar(12))  
/* @RptType Takes Value 'M' for Expand to All Levels, 'S' for Single Level,  'L' for Ledgers only, All Other for Abstract - only top level groups - you may use 'A' */
/* 'T' for Expand All Ledgers with Top Level Groups Only */
/* @ActualsCutOff - Only Applicable for Balance Sheet */

RETURNS @RetTable TABLE
	([Master] [varchar](10),
	[Path] [varchar](42),
	[Type] [varchar] (10),
	[Code] [int],
	[Particulars] [varchar] (100),
	[OpBalance] [money],
	[DrAmt] [money],
	[CrAmt] [money],
	[ClosingBalance] [money]
	)

 AS  

BEGIN 
	
	Declare @VrTranStartDate datetime
	Declare @VrTranEndDate datetime
	
	Declare @BtTranStartDate datetime
	Declare @BtTranEndDate datetime
	
	If (@Start > @ActualsCutOff)
		BEGIN
			Select @BtTranStartDate = @Start
			Select @VrTranEndDate = DateAdd(day, -1, @Start)
		END
	Else
	If (@End < @ActualsCutOff)
		BEGIN
			Select @BtTranStartDate = DateAdd(day, 1, @End)
			Select @VrTranEndDate = @End
		END
	Else
		BEGIN
			Select @BtTranStartDate = DateAdd(day, 1, @ActualsCutOff)
			Select @VrTranEndDate = @ActualsCutOff
		END
	
	Select @VrTranStartDate = @Start	
	Select @BtTranEndDate = @End	/* When @BtTranStartDate < @BtTranEndDate Then the BudgetAmount will be zero */



	Insert into @RetTable

		Select '', LrRoute, 'Ledger', LedgerCode, LedgerName, OBAmt, DrAmt, CrAmt, (OBAmt+DrAmt-CrAmt) as CBAmt
		from
			(Select a.LrRoute, a.LedgerCode, a.LedgerName, a.OpBalance as OBAmt, 
			isNull(Sum(b.DrAmt), 0)+isNull(Sum(c.DrAmt), 0) as DrAmt, isNull(Sum(b.CrAmt), 0)+isNull(Sum(c.CrAmt), 0) as CrAmt
			from dbo.fn_FAS_Budget_AllOpBalance(@Start, @ActualsCutOff, '0', '1', @CmCode) a 
			Left Outer Join FAS_VoucherTranSub b
				On a.LedgerCode=b.LrCode and a.CompCode=b.CompCode and b.DocDate between @VrTranStartDate and @VrTranEndDate
			Left Outer Join FAS_Budget_LrOnly_Vw c
				On a.LedgerCode=c.SLCode and a.CompCode Like c.CompCode+'%' and c.PlanFor=2 /* Hard Coded for Testing */
					and c.PlanDate Between @BtTranStartDate and @BtTranEndDate
			Group by a.LrRoute, a.LedgerCode, a.LedgerName, a.OpBalance
			) x
/*
	/* Updating Opening Balance to zero for P & L Entries */
	Update @RetTable Set OpBalance=0, ClosingBalance=(DrAmt-CrAmt)
	From @RetTable a
	Where Exists (Select * from FAS_LedgerMaster b Left Outer Join FAS_GroupMaster c 
					On b.LrRoute=c.GrRoute+c.GrWidth and b.CompCode=c.CompCode
					Where b.LedgerCode=a.Code and b.CompCode=@CmCode and c.Master in ('02', '03'))
*/	

/*
	Delete @RetTable
	Where OpBalance=0 and DrAmt=0 and CrAmt=0 and ClosingBalance=0
*/

	If @RptType<>'L'	--For Ledgers Only options no need to update the groups
		Begin

			If @RptType='T'		--For this Option Group Total will be the sum of direct ledgers only
				Begin
					Insert into @RetTable
			
						Select '', a.GrRoute+a.GrWidth, 'Group', a.GroupCode, a.GroupName, isNull(Sum(b.OpBalance), 0) as OBAmt,
							 isNull(Sum(b.DrAmt), 0) as DrAmt, isNull(Sum(b.CrAmt), 0) as CrAmt, isNull(Sum(ClosingBalance), 0) as CBAmt
						from FAS_GroupMaster a Left Outer Join @RetTable b
						On a.GrRoute+a.GrWidth = b.Path
						Where a.CompCode=@CmCode
						Group by a.GrRoute+a.GrWidth, a.GroupName, a.GroupCode
				End
			Else
				Begin
					Insert into @RetTable
				
						Select '', a.GrRoute+a.GrWidth, 'Group', a.GroupCode, a.GroupName, isNull(Sum(b.OpBalance), 0) as OBAmt,
							 isNull(Sum(b.DrAmt), 0) as DrAmt, isNull(Sum(b.CrAmt), 0) as CrAmt, isNull(Sum(ClosingBalance), 0) as CBAmt
						from FAS_GroupMaster a Left Outer Join @RetTable b
						On a.GrRoute+a.GrWidth = Left(b.Path, Len(a.GrRoute+a.GrWidth))
						Where a.CompCode=@CmCode
						Group by a.GrRoute+a.GrWidth, a.GroupName, a.GroupCode
				End
		/*	
			Delete @RetTable
			Where OpBalance=0 and DrAmt=0 and CrAmt=0 and ClosingBalance=0
		*/


			If @RptType='S'		--Single Level Expand
				Begin
					Delete @RetTable
					Where  (Type = 'Ledger'  and Len(Path) > 2) or (Type='Group' and Len(Path) > 4)	
				End
			Else
				If @RptType<>'M'	--If it is not multi level expand then it should be Abstract Report
					Begin 
						Delete @RetTable
							Where  Not ((Type='Group' and Len(Path) = 2) or (Type='Ledger' and Path in ('00', 'ZZ')))
					End
		
		End

	Insert into @RetTable

		Select '', 'ZZ', 'Group', 0, 'Diff. in Opening Balance', Isnull(-Sum(OpBalance), 0) as Amt1, 0, 0, IsNull(-Sum(OpBalance), 0)
		from dbo.fn_FAS_Budget_AllOpBalance(@Start, @ActualsCutOff, '0', '1', @CmCode)

/*
	Delete @RetTable
	Where OpBalance=0 and DrAmt=0 and CrAmt=0 and ClosingBalance=0
*/



	Update @RetTable Set Master=Case When Left(Path, 2)  in ('02', '09', '0A', '0C') Then '00' When Left(Path, 2) in ('01', '03', '04', '0B', '0F') Then '01'
						When Left(Path, 2) in ('06', '08', '0E') Then '02' When Left(Path, 2) in ('05', '07', '0D') Then '03' Else '04' End


	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Rpt_CashFlow]    Script Date: 17/06/2026 11:38:45 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Rpt_CashFlow] (@RptType int, @Start datetime, @End datetime, @CmCode varchar(12))  
--@RptType Takes Value 'M' for Expand to All Levels, 'S' for Single Level,  'L' for Ledgers only, All Other for Abstract - only top level groups - you may use 'A'
-- 'T' for Expand All Ledgers with Top Level Groups Only

RETURNS @RetTable TABLE
	([Master]	 [varchar](10),
	[Path]		 [varchar](42),
	[Type] 		 [varchar] (10),
	[Code] 		 [int],
	[Particulars] 	 [varchar] (100),
	[OpBalance] 	 [money],
	[DrAmt] 		 [money],
	[CrAmt] 		 [money],
	[ClosingBalance] [money]
	)

 AS  

BEGIN 

	
		Declare @CallType char(1)

		If @RptType='0'
			Select @CallType='A'--Abstract Only Group
		if @RptType='1'
			Select @CallType='S' -- Groups and 1st level Ledgers
		if @RptType='2'
			Select @CallType='M'  --SubGroup with All Ledger

		
		/* Insert Ledgers, Except Journal and Contra Vouchers*/
		Insert into @RetTable

			Select '', LrRoute, 'Ledger', LedgerCode, LedgerName, OBAmt, DrAmt, CrAmt, (OBAmt+DrAmt-CrAmt) as CBAmt
			from
				(Select a.LrRoute, a.LedgerCode, a.LedgerName, a.OpBalance as OBAmt, 
				isNull(Sum(DrAmt), 0) as DrAmt, isNull(Sum(CrAmt), 0) as CrAmt
				from dbo.fn_FAS_AllOpBalance(@Start, '0', '1', @CmCode) a Left Outer Join FAS_VoucherTranSub b
				On a.LedgerCode=b.LrCode and a.CompCode=b.CompCode and b.DocDate between @Start and @End
				Where Left(LrRoute, 2) in ('01', '02', '03', '04', '09', '0A', '0B', '0C', '0F')  and (LrRoute Not Like '0205%')
					and Left(VrRoute, 2) not in ('01', '06')   
				Group by a.LrRoute, a.LedgerCode, a.LedgerName, a.OpBalance
				) x



		/* Insert Groups and sum of the Amount*/					
		Insert into @RetTable
				
			Select '', a.GrRoute+a.GrWidth, 'Group', a.GroupCode, a.GroupName, isNull(Sum(b.OpBalance), 0) as OBAmt,
				 isNull(Sum(b.DrAmt), 0) as DrAmt, isNull(Sum(b.CrAmt), 0) as CrAmt, isNull(Sum(ClosingBalance), 0) as CBAmt
			from FAS_GroupMaster a Left Outer Join @RetTable b
			On a.GrRoute+a.GrWidth = Left(b.Path, Len(a.GrRoute+a.GrWidth))
			Where a.CompCode=@CmCode and Left((a.GrRoute+a.GrWidth), 2) in ('01', '02', '03', '04', '09', '0A', '0B', '0C', '0F')
			Group by a.GrRoute+a.GrWidth, a.GroupName, a.GroupCode


		

		/* Insert ClosingStock and Stock in Hand */
		Insert into @RetTable		
	
			Select  * From	
			(
				Select '00' Master, '0205' as Path, 'Group' as Type,  9999 as Code, 'Closing Stock'  as Particulars, 0 OBAmt, 0 DrAmt, 0 CrAmt,  Sum(ClosingStock) CBAmt
				from dbo.fn_FAS_StockValue (@Start, @End, @CmCode)
	
				Union All
	
				Select '00' Master, '0205' Path, 'Ledger' as Type,  9999 as Code, isNull(b.LedgerName, '')   as Particulars, 0 OBAmt, 0 DrAmt, 0 CrAmt,  ClosingStock
				from dbo.fn_FAS_StockValue (@Start, @End, @CmCode) a 
				Left Outer Join FAS_LedgerMaster b 
				On a.LedgerCode=b.LedgerCode and a.CompCode=b.CompCode
				Where ClosingStock<>0
			) x

		
		--To reduce the default OpeningStock added in Current Assets and Add the Closing Stock
		Update @RetTable Set ClosingBalance=ClosingBalance+(Select Sum(ClosingStock-OpeningStock) from  dbo.fn_FAS_StockValue (@Start, @End, @CmCode))
		Where Path='02' and Type='Group'
	

		If @CallType='S'		--Single Level Expand
			Begin
				Delete @RetTable				
				Where  (Type = 'Ledger'  and Len(Path) > 2) or (Type='Group' and Len(Path) > 4)	
			End
		Else
			If @CallType<>'M'	--If it is not multi level expand then it should be Abstract Report
				Begin 
					Delete @RetTable
						Where  Not ((Type='Group' and Len(Path) = 2) or (Type='Ledger' and Path in ('00', 'ZZ')))
				End

		
		/* Diff. in Opening Balance */
		Insert into @RetTable			
			Select '', 'ZZ', 'Group', 0, 'Diff. in Opening Balance', Isnull(-Sum(OpBalance), 0) as Amt1, 0, 0, IsNull(-Sum(OpBalance), 0)
			from dbo.fn_FAS_AllOpBalance(@Start, '0', '1', @CmCode) 
		

										
		/* Update Masters with Path*/	
		Update @RetTable Set Master=Case When Left(Path, 2)  in ('02', '09', '0A', '0C') Then '00' When Left(Path, 2) in ('01', '03', '04', '0B', '0F') Then '01'  End
			
			
		

			



	Return 




End
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Rpt_CostCentre_Monthwise]    Script Date: 17/06/2026 11:38:45 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [dbo].[fn_FAS_Rpt_CostCentre_Monthwise] (@Type Char(1), @Code int, @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))  

RETURNS @RetTable TABLE
	([MnCode] [int],		
	[MthName] [varchar](10),
	[DrAmt] [money],
	[CrAmt] [money],
	[ClosingBalance] [money]
	)

 AS  

BEGIN 	
	
	

		If @Type = 'L'
			Begin

				Insert into @RetTable
					Select MnCode, Datename(month, convert(datetime, Convert(varchar, h.MnCode)+'01', 112 )) as DMonth, isNull(DrAmt, 0), isNull(CrAmt, 0), 0
						--dbo.fn_FAS_LedgerOpBalance(@Code, DateAdd(mm, 1, Convert(datetime, h.MnCode+'01', 112)), '0', @CmCode) as CB
						From 
						(Select h1.MnCode, h2.DrAmt, h2.CrAmt
						from
							(Select Convert(varchar(6), Monthdate, 112) MnCode from dbo.fn_FAS_Months(@PrStart, @PrEnd)) h1 
						Left Outer Join
							(Select Convert(varchar(6), c.Docdate, 112) MnCode, Sum(b.DrAmt) as DrAmt, Sum(b.CrAmt) as CrAmt
							 from FAS_VoucherTranCostCentre c 
								Left Outer Join FAS_VoucherTranSub b
									On c.DocNo = b.DocNo and c.DocDate = b.DocDate and c.VTSNo = b.VTSNo and c.VrRoute = b.VrRoute
										and c.CompCode = b.CompCode
							Where c.LrCode= @Code and (c.DocDate between @PrStart and @PrEnd) and c.CompCode = @CmCode
							Group by Convert(varchar(6), c.Docdate, 112)
							) h2
						On h1.MnCode=h2.MnCode
						)h			
						Order by MnCode
		
				Update @RetTable Set ClosingBalance=(Select Sum(DrAmt-CrAmt) from @RetTable b Where b.MnCode<=a.MnCode)
				from @RetTable a

			End

		Else

			If @Type = 'G'

				Begin
					Insert into @RetTable
						Select MnCode, Datename(month, convert(datetime, Convert(varchar, h.MnCode)+'01', 112 )) as DMonth, DrAmt, CrAmt,
						dbo.fn_FAS_LedgerOpBalance(@Code, DateAdd(mm, 1, Convert(datetime, h.MnCode+'01', 112)), '0', @CmCode) as CB
						From 
						(Select h1.MnCode, h2.DrAmt, h2.CrAmt
						from
							(Select Convert(varchar(6), Monthdate, 112) MnCode from dbo.fn_FAS_Months(@PrStart, @PrEnd)) h1 
						Left Outer Join
							(Select Convert(varchar(6), c.Docdate, 112) MnCode, Sum(b.DrAmt) as DrAmt, Sum(b.CrAmt) as CrAmt
							 from FAS_VoucherTranCostCentre c 
								Left Outer Join FAS_VoucherTranSub b
									On c.DocNo = b.DocNo and c.DocDate = b.DocDate and c.VTSNo = b.VTSNo and c.VrRoute = b.VrRoute
										and c.CompCode = b.CompCode
							Where c.LrCode= @Code and (c.DocDate between @PrStart and @PrEnd) and c.CompCode = @CmCode
							Group by Convert(varchar(6), c.Docdate, 112)
							) h2
						On h1.MnCode=h2.MnCode
						)h			
						Order by MnCode
		
		
					Update @RetTable Set ClosingBalance=(Select Sum(DrAmt-CrAmt) from @RetTable b Where b.MnCode<=a.MnCode)
					from @RetTable a
				End

	Return 

END

GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Rpt_CostCentre_SubGroupLedger]    Script Date: 17/06/2026 11:38:45 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [dbo].[fn_FAS_Rpt_CostCentre_SubGroupLedger] (@Route varchar(42), @CostCode int, @RptDate datetime, @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))  


RETURNS @RetTable TABLE
	([Path] [varchar](42),
	[Type] [varchar] (10),
	[Code] [int],
	[Particulars] [varchar] (100),
	[DrAmt] [money], --CostCentre DrAmt
	[CrAmt] [money] --CostCentre CrAmt
	)
 AS  

BEGIN 
	
	Insert into @RetTable	
		Select Path, Type, Code, Particulars, Debit, Credit From
			(
				Select distinct a.LrCode as Code, c.LedgerName as Particulars, 
					Sum(Case When a.Amount > 0 then a.Amount Else 0 End) as Debit, 
					Sum(Case When a.Amount < 0 then -a.Amount Else 0 End) as Credit,
					c.LrRoute as Path, 'Ledger' as Type
				From FAS_VoucherTranCostCentre a
				Left Outer Join FAS_VoucherTranSub b
					On a.DocNo = b.DocNo and a.DocDate = b.DocDate and a.VTSNo = b.VTSNo and a.VrRoute = b.VrRoute
						and a.CompCode = b.CompCode
				Left Outer Join FAS_LedgerMaster c
					On a.LrCode = c.LedgerCode and a.CompCode = c.CompCode
				Where a.CompCode = @CmCode and a.DocDate between @PrStart and @Rptdate
					and LrRoute like @Route +'%' and a.Amount <> 0 and a.CostCentreCode =  @CostCode
				Group By a.LrCode, c.LedgerName, c.LrRoute

				Union all
	
				Select distinct d.GroupCode as Code, d.GroupName as Particulars, 
					Sum(Case When a.Amount > 0 then a.Amount Else 0 End) as Debit, 
					Sum(Case When a.Amount < 0 then -a.Amount Else 0 End) as Credit,
					d.GrRoute+d.Grwidth as Path, 'Group' as Type
				From FAS_VoucherTranCostCentre a
				Left Outer Join FAS_VoucherTranSub b
					On a.DocNo = b.DocNo and a.DocDate = b.DocDate and a.VTSNo = b.VTSNo and a.VrRoute = b.VrRoute
						and a.CompCode = b.CompCode
				Left Outer Join FAS_LedgerMaster c
					On a.LrCode = c.LedgerCode and a.CompCode = c.CompCode
				Left Outer Join FAS_GroupMaster d
					On c.LrRoute = (d.GrRoute+d.Grwidth) and c.CompCode = d.CompCode
				Where a.CompCode = @CmCode and a.DocDate between @PrStart and @Rptdate
					and (d.GrRoute+d.Grwidth) Like @Route +'%'  and a.Amount <> 0 and a.CostCentreCode =  @CostCode				
				Group by d.GroupCode, d.GroupName, d.GrRoute+d.Grwidth
			)x
		Where (Type = 'Group' and Path like @Route +'%' and Len(Path) = Len(@Route) +2)
				Or (Type = 'Ledger' and Path = @Route)
	
				
	Return 

END










GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Rpt_ExtractRegister]    Script Date: 17/06/2026 11:38:45 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [dbo].[fn_FAS_Rpt_ExtractRegister] (@VrRoute as Char(2), @PrStart datetime, @Start datetime, @End datetime, @CmCode varchar(12))  

RETURNS @RetTable TABLE
	([Master] [varchar](10),
	[Path] [varchar](42),
	[Type] [varchar] (10),
	[Code] [int],
	[Particulars] [varchar] (100),
	[ClosingBalance] [money],
	[SortOrder] [int]
	)
 AS  

BEGIN 	
	Declare @TmpDate as datetime
	Select @TmpDate = dateadd(d, 1, @End)

	
	Insert into @RetTable
		Select '', isNull(b.LrRoute, ''), 'Ledger', a.LrCode, isNull(b.LedgerName, 0), Sum(DrAmt+CrAmt) as CBAmt, 0
		from FAS_VoucherTranSub a Inner Join FAS_LedgerMaster b
		On a.LrCode=b.LedgerCode and a.CompCode=b.CompCode
		Where (a.DocDate between @Start and @End) and a.VrRoute like @VrRoute+'%'
			and Not (b.LrRoute like '04%') and Left(b.LrRoute, 4) not in ( '0206', '0303')
			and  a.CompCode=@CmCode		
		Group by b.LrRoute, a.LrCode, b.LedgerName

	
		/* Update  Path like '0301'  because of CB Sum */
		Update 	@RetTable Set Path = '0301'	
		Where Path like '0301%' 

	Insert into @RetTable
		
		Select '', a.Path, 'Group', a.GroupCode, a.GroupName, isNull(Sum(ClosingBalance), 0) as CBAmt, 0
		from 	(Select GroupCode, GroupName, GrRoute+GrWidth as Path,  CompCode 
			From FAS_GroupMaster 
			Where CompCode=@CmCode and (Len(GrRoute+GrWidth)=2 or GrRoute+GrWidth like '0301%')) a 
			Inner Join @RetTable b
			On a.Path like b.Path+'%' and a.CompCode=@CmCode 
			Group by a.Path, a.GroupName, a.GroupCode

		Delete @RetTable 
		Where (Type = 'Group' and Len(Path)>4) or ClosingBalance = 0


		
		
/*		Select '', Path, Type, Code, Particulars, Sum(ClosingBalance) as CBAmt
		From @RetTable 
		Group by Path, Type
*/
--	If @VrRoute = '0K'
--		Begin
--			Delete @RetTable Where ClosingBalance = 0
		
			Update @RetTable Set SortOrder = Case When Path like '0E%' Then 1 When Path like '0D%' Then 1  When Path like '08%' Then 2  When Path like '07%' Then 3   When Path like '0301%' Then 4 
					   	 Else 5  End			
--		End

			



/*	If @VrRoute = '0B'

		begin

			Delete @RetTable Where ClosingBalance = 0

			Update @RetTable Set SortOrder = Case When Path like '0D%' Then 1  When Path like '08%' Then 2  When Path like '07%' Then 3   When Path like '0301%' Then 4 
					   	 When Path like '03%' Then 5  End	
		
			Update @RetTable Set SortOrder = Case Path When '0D' Then 1  
						When '0301' Then 2  End		

		end
*/
	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Rpt_GrLedgers]    Script Date: 17/06/2026 11:38:45 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [dbo].[fn_FAS_Rpt_GrLedgers] (@Userkey varchar(46),  @FinStart datetime, @Start datetime, @End datetime, @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))  

RETURNS @RetTable TABLE
	([Master] [varchar](10),
	[Path] [varchar](42),
	[Type] [varchar] (10),
	[Code] [int],
	[Particulars] [varchar] (100),
	[AcCode][int],
	[AcMonth] [varchar] (15),
	[OpBalance] [money],
	[DrAmt] [money], 
	[CrAmt] [money],
	[ClosingBalance] [money]
	)

AS  

BEGIN 

	Declare @BranchID varchar(2)
	Select @BranchID = SubString(@CmCode, 3, 2)
	
	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)

/*
	Insert into @RetTable

	Select '', a.LrRoute, 'Ledger', a.LedgerCode, a.LedgerName, a.MnCode, IsNull(Datename(month, Convert(datetime, Convert(varchar, a.MnCode)+'01', 112 )), 'A-OB') as Mth, 
			(a.OpBalance+isNull(b.OBAmt, 0)) as OBAmt, IsNull(b.TranDrAmt, 0) DrAmt, IsNull(b.TranCrAmt, 0) CrAmt, 
			(a.OpBalance+isNull(b.OBAmt, 0) + isNull(b.TranDrAmt, 0) - isNull(b.TranCrAmt, 0)) as CBAmt
		From (Select s.OpBalance, s.LedgerCode, s.LedgerName, h.SelectStr as LrRoute, h.MnCode, h.CompCode 
				From (Select q.SelectStr, r.MnCode, q.CompCode
					From (Select SelectStr, @CmCode as CompCode
						From Com_SelectList Where Userkey = @Userkey
							and BranchID =@BranchID and CompID = @CompID) q
						Full Outer Join 
							(Select Convert(varchar(6), Monthdate, 112) MnCode, @CmCode as CompCode 
							from dbo.fn_FAS_Months(@Start,  @End)) r
						On q.CompCode = r.CompCode 
				          )h
				Left Outer Join Fas_LedgerMaster s
				On s.LrRoute = h.SelectStr and s.CompCode = h.CompCode
		         )a

		Left Outer  Join (Select LrCode, MnCode, Sum(OBAmt) as OBAmt, Sum(TranDrAmt) as TranDrAmt, Sum(TranCrAmt) as TranCrAmt, CompCode
			from
				(Select distinct LrCode, Convert(varchar(6), Docdate, 112) MnCode, Case When DocDate < @Start Then (CrAmt-DrAmt) Else 0 End as OBAmt,
					Case When DocDate between @Start and @End Then (DrAmt) Else 0 End as TranDrAmt,
					Case When DocDate between @Start and @End Then (CrAmt) Else 0 End as TranCrAmt, m.CompCode
				from FAS_VoucherTranSub m
				Full Outer Join (Select Convert(varchar(6), Monthdate, 112) MnCode, @CmCode as CompCode from dbo.fn_FAS_Months(@Start, @End)) n
				On m.CompCode=n.CompCode
				Where DocDate between @Start and @End and m.CompCode=@CmCode) x
			Group by LrCode, MnCode, CompCode) b
		On a.LedgerCode=b.LrCode and a.CompCode = b.CompCode
		Where a.CompCode= @CmCode and Left(a.LrRoute, 2) in (Select SelectStr From Com_SelectList Where Userkey = @Userkey
			and BranchID = @BranchID and CompID =  @CompID)
*/

	Insert into @RetTable

	Select '', a.LrRoute, 'Ledger', a.LedgerCode, a.LedgerName, MnCode,  IsNull(Datename(month, Convert(datetime, Convert(varchar, MnCode)+'01', 112 )), 'A-OB') as Mth, (a.OpBalance+isNull(b.OBAmt, 0)) as OBAmt, 
				isNull(b.TranDrAmt, 0) as DrAmt, isNull(b.TranCrAmt, 0) as CrAmt,
			(a.OpBalance+isNull(b.OBAmt, 0) + isNull(b.TranDrAmt, 0) - isNull(b.TranCrAmt, 0)) as CBAmt
		From FAS_LedgerMaster a Left Outer Join
		
			(Select LrCode, MnCode, Sum(OBAmt) as OBAmt, Sum(TranDrAmt) as TranDrAmt, Sum(TranCrAmt) as TranCrAmt
			from
				(Select distinct LrCode, Convert(varchar(6), Docdate, 112) MnCode, Case When DocDate < @Start Then (DrAmt-CrAmt) Else 0 End as OBAmt,
					Case When DocDate between @Start and @End Then (DrAmt) Else 0 End as TranDrAmt,
					Case When DocDate between @Start and @End Then (CrAmt) Else 0 End as TranCrAmt, m.CompCode
				from FAS_VoucherTranSub m
				Full Outer Join (Select Convert(varchar(6), Monthdate, 112) MnCode, @CmCode as CompCode from dbo.fn_FAS_Months(@Start, @End)) n
				On m.CompCode=n.CompCode
				Where DocDate between @Start and @End and m.CompCode=@CmCode) x
			Group by LrCode, MnCode, CompCode) b
		On a.LedgerCode=b.LrCode
		Where a.CompCode=@CmCode and a.LrRoute in (Select SelectStr From Com_SelectList Where Userkey = @Userkey 
					and BranchID = @BranchID and CompID = @CompID)



	Insert into @RetTable

		Select distinct '', a.GrRoute+a.GrWidth, 'Group', a.GroupCode, a.GroupName, AcCode, IsNull(b.AcMonth, 'A-OB') as AcMonth,  isNull(Sum(b.OpBalance), 0) as OBAmt,
			 isNull(Sum(b.DrAmt), 0) as DrAmt, isNull(Sum(b.CrAmt), 0) as CrAmt, isNull(Sum(ClosingBalance), 0) as CBAmt
		from FAS_GroupMaster a 
		Left Outer Join @RetTable b
		On a.GrRoute+a.GrWidth = Left(b.Path, Len(a.GrRoute+a.GrWidth)) and a.CompCode = @CmCode
		
		Where a.CompCode=@CmCode  and  (a.GrRoute+a.GrWidth) in (Select SelectStr From Com_SelectList Where Userkey = @Userkey 
					and BranchID = @BranchID and CompID = @CompID)
		Group by a.GrRoute+a.GrWidth, a.GroupName, b.AcCode, b.AcMonth,  a.GroupCode
	

		
		--Insert OpBalance

		Delete @RetTable
		Where OpBalance=0 and DrAmt=0 and CrAmt=0 and ClosingBalance=0

		Update @RetTable Set Master=Case When Left(Path, 2)  in ('02', '09', '0A', '0C') Then '00' When Left(Path, 2) in ('01', '03', '04', '0B', '0F') Then '01'
						When Left(Path, 2) in ('06', '08', '0E') Then '02' When Left(Path, 2) in ('05', '07', '0D') Then '03' Else '04' End

	
	Return 



END



















GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Rpt_GroupsLedgers_TrialBalance]    Script Date: 17/06/2026 11:38:45 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Rpt_GroupsLedgers_TrialBalance] (@RptType char(1), @isZeroCB bit, @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))    
   
/*  @RptType - G refers Group Only, L refers Ledger Only, D refers Single Level Expansion, E refers All level Expansion */  
  
RETURNS @RetTable TABLE  
 ([Master] [varchar](10),  
 [Path] [varchar](42),  
 [Type] [varchar] (10),  
 [Code] [int],  
 [Particulars] [varchar] (100),  
 [OB_Dr] [varchar](20),  
 [OB_Cr] [varchar](20),  
 [Tran_Dr] [varchar](20),  
 [Tran_Cr] [varchar](20),  
 [CB_Dr] [varchar](20),  
 [CB_Cr] [varchar](20)  
 )  
AS    
  
BEGIN   
  
 Declare @CallTrialBalanceType char(1)  
 If @RptType='G'  
  Select @CallTrialBalanceType='A'  
 Else  
  If @RptType='D'  
   Select @CallTrialBalanceType='S'  
  Else  
   If @RptType='L'  
    Select @CallTrialBalanceType='L'  
   Else  
    Select @CallTrialBalanceType='M'  
  
 Insert into @RetTable  
  
  Select Master, Path, Type, Code, Particulars, OB_Dr, OB_Cr, Tran_Dr, Tran_Cr,  CB_Dr, CB_Cr  
  From   
   (Select Master, Path, Type, Code, Case @RptType When 'L' Then Particulars Else Case Type when 'Master' then Particulars  
                when 'Group' then Space(Len(Path)) + Particulars  
                                                                when 'Ledger' then space(Len(Path))+'    '+Particulars End End as Particulars,  
/*  
     Case sign(OpBalance) When 1 Then OpBalance Else 0 End as OB_Dr,  
     Case sign(OpBalance) When -1 Then -OpBalance Else 0 End as OB_Cr,  
  
     Case sign(DrAmt) When 0 Then 0 Else DrAmt  End as Tran_Dr,   
     Case sign(CrAmt) When 0 Then 0 Else CrAmt End as Tran_Cr,   
   
     Case sign(ClosingBalance) When 1 Then  ClosingBalance Else 0 End as CB_Dr,   
     Case sign(ClosingBalance) When -1 Then  -ClosingBalance Else 0 End as CB_Cr  
*/  
  
     Case When OpBalance > 0  Then Convert(varchar, OpBalance) Else '' End as OB_Dr,   
     Case When OpBalance < 0  Then Convert(varchar, -OpBalance) Else '' End as OB_Cr,   
       
     Case When DrAmt = 0  Then '' Else Convert(varchar, DrAmt)  End as Tran_Dr,   
     Case When CrAmt = 0  Then '' Else Convert(varchar, CrAmt) End as Tran_Cr,   
       
     Case When ClosingBalance > 0  Then Convert(varchar, ClosingBalance) Else '' End as CB_Dr,   
     Case When ClosingBalance < 0  Then Convert(varchar, -ClosingBalance) Else '' End as CB_Cr  
     
   From [dbo].[fn_FAS_Rpt_TrialBalance] (@CallTrialBalanceType, @PrStart, @PrEnd, @CmCode)   
     
   )x  Order by Master, Path, Type, Particulars  
/*   
   if @RptType = 'G' --Groupwise Summary  
    Delete @RetTable  
     Where Type = 'Ledger'      
*/  
   if @RptType = 'L' --Ledgerwise Summary  
    Delete @RetTable  
     Where Type =  'Group'    
  
   if @isZeroCB = '0' --Zero balance   
    Delete @RetTable  
      Where (OB_Dr='' AND OB_Cr='' AND Tran_Dr='' AND Tran_Cr='' AND CB_Cr='' AND CB_Dr='')   
     

 Return  
  
  
END  
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Rpt_GroupSummary]    Script Date: 17/06/2026 11:38:45 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO


--CREATE FUNCTION [dbo].[fn_FAS_Rpt_GroupSummary] (@GrRoute varchar(42), @RptType varchar(1), @Start datetime, @End datetime, @CmCode varchar(12))  
CREATE FUNCTION [dbo].[fn_FAS_Rpt_GroupSummary] (@GrRoute varchar(42), @RptType varchar(1), @isAsPerBalanceSheet bit, @Start datetime, @End datetime, @CmCode varchar(12))  
--@RptType Takes Value 'M' for Expand to All Levels, 'S' for Single Level,  'L' for Ledgers only, All Other for Abstract - only top level groups - you may use 'A'
-- 'T' for Expand All Ledgers with Top Level Groups Only

RETURNS @RetTable TABLE
	([Master] [varchar](10),
	[Path] [varchar](42),
	[Type] [varchar] (10),
	[Code] [int],
	[Particulars] [varchar] (100),
	[OpBalance] [money],
	[DrAmt] [money],
	[CrAmt] [money],
	[ClosingBalance] [money]
	)
 AS  

BEGIN 
	
	Declare @RouteLn int
	Select @RouteLn=Len(@GrRoute)


	If  @isAsPerBalanceSheet = '1' and (@GrRoute='02' or @GrRoute like '0205%')
		Begin
			Insert into @RetTable
		
				Select Master, Path, Type, Code, Particulars, OpBalance, DrAmt, CrAmt, Amount									
				From (
						Select Master, Path, Type, Code, Particulars, OpBalance, DrAmt, CrAmt, ClosingBalance as Amount  
						from dbo.fn_FAS_Rpt_TrialBalance('M', @Start, @End, @CmCode)
						where Left(Path, 2) in ('02')  and (Path Not Like '0205%')
						
						Union All
				
						Select '00', '0205' as Path, 'Group' as Type,  9999 as Code, 'STOCK-IN-HAND'  as Particulars, Sum(OpeningStock), 0, 0,  Sum(-ClosingStock)
						from dbo.fn_FAS_StockValue (@Start, @End, @CmCode)
				
						Union All
				
						Select '00', '0205', 'Ledger' as Type,  9999 as Code, isNull(b.LedgerName, '')   as Particulars, OpeningStock, 0, 0, -ClosingStock
						from dbo.fn_FAS_StockValue (@Start, @End, @CmCode) a Left Outer Join FAS_LedgerMaster b On a.LedgerCode=b.LedgerCode and a.CompCode=b.CompCode
						where ClosingStock<>0
			
					)M
					Order by Path, Type	
		
					--To reduce the default OpeningStock added in Current Assets and Add the Closing Stock
					Update @RetTable Set ClosingBalance= ClosingBalance+(Select Sum(ClosingStock-OpeningStock) from  dbo.fn_FAS_StockValue (@Start, @End, @CmCode))
					Where Path='02' and Type='Group'
		End
	Else
		Begin
			Insert into @RetTable
		
				Select * from dbo.fn_FAS_Rpt_TrialBalance('M', @Start, @End, @CmCode)
		End

/*
	Delete @RetTable
	Where OpBalance=0 and DrAmt=0 and CrAmt=0 and ClosingBalance=0
*/

	Delete @RetTable
		Where (Path not like @GrRoute+'%')	


	If @RptType='L'		--For Ledgers Only options no need to update the groups
		Begin
			Delete @RetTable
				Where  (Type='Group') 
		End
	Else
		If @RptType='S'		--Single Level Expand
			Begin
				Delete @RetTable
				Where  (Type = 'Ledger'  and Len(Path) > @RouteLn) or (Type='Group' and Len(Path) > @RouteLn+2)
			End
		Else
			If @RptType='T'		--All Ledgers with Top Level Groups Only
				Begin
					Delete @RetTable
						Where  (Type='Group' and Path <> @GrRoute) 
				End

			Else
				If @RptType<>'M'	--If it is not multi level expand then it should be Abstract Report
					Begin 
						Delete @RetTable
							Where Not (Type='Group' and Path=@GrRoute)
					End
				
	Return 

END








GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Rpt_GST_Purchase]    Script Date: 17/06/2026 11:38:45 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Rpt_GST_Purchase](@StartDate datetime, @EndDate datetime, @AsonDate datetime, @RptDate datetime, @CompCode Varchar(12))      
RETURNS @GSTPurchaseTable TABLE                                           
(                                          
   VrRoute varchar(42),                                         
   VoucherType varchar(50),                                    
   TaxName varchar(20),                                         
   LrCode int,                                         
   LedgerName varchar(50),                                         
   GSTRegNo varchar(50),           
   IsUnRegisterDealer bit,                                    
   DocNo int ,                                         
   DocDate datetime,                                           
   InvoiceType varchar(3),                                         
   InvoiceNo int,                                         
   InvoiceDate datetime,                                
   --HSNNO varchar(10),                                
   --ItemCode Varchar(20),                                 
   --ItemDesc Varchar(50),                                 
   --ItemCount int,                                     
   --UOMDesc Varchar(50),                                
   --UOMDecimal int,                                 
   --InvoiceQty Float,                                             
   --Rate Float,                              
   --GoodsValue money,                                     
   InvoiceValue money,                                         
   PlaceOfSupply varchar(60),                                         
   ReverseCharge Char(1),                                         
   TypeOfInvoice varchar(50),                                         
   ECommerceGSTRegNo varchar(20),                                         
   TaxRate money,                                         
   TaxableValue money,                                     
   CGSTTAxAmount money,                                         
   SGSTTAxAmount money,                                         
   IGSTTAxAmount money,                                         
   OtherTaxAmount money,                                        
   CessAmount money,                                         
   IsImportPurchase bit,                       
   RefNo Varchar(50),                
   RefDate datetime,                                 
   TranCompCode varchar(12),                                        
   CompCode varchar(12)                                         
)                                            
As    
BEGIN                                                                            
                                          
 /* Following Reports addressed,                                    
   Inter State Register Dealer,                                     
   Intra State Register Dealer,                                     
   Inter State UnRegister Dealer,                                     
   Intra State UnRegister Dealer,                                      
   Credit Note Register and Unregister Dealer also Inter and Intra state,                                      
   Debit Note Register and Unregister also Inter and Intra state using this procedure                                   
   HSN summary                                
 */                                        
 /* Help */                                        
 /* VrRoute    : Purchase = '0B', CreditNote = '02', DebitNote = '03', Journal = '06' , Payment = '09' */                                        
 /* LedgerRoute: Purchase = '0303' */                                        
 /* Sales   : GroupFlg='INPUT'*/                                        
 /* TaxName   : WithInState = Intrastate, OtherState = Interstate */                                        
 /* Posting Ledger for Tax : TypeFlg='Tax' */                                        
 /* Posting Ledger for GoodsValue :  TypeFlg='AVGV' */          
 /* CGST + SGST called As IntraState. So @NoOfTaxRate multiply into two to show the Cumulative TaxRate in Report for Intrastate */                                        
                                        
 Declare @NoofTaxRate int                                        
 SET @NoofTaxRate=2                                         
                                                                        
 Declare @CompID As Varchar(3)                                        
 Declare @BranchID As Varchar(3)                            
                                        
 Set @CompID=Left(@CompCode, 2);                                        
 Set @BranchID=Substring(@CompCode, 3, 2);                                       
                                   
 ;With DocList_CTE (/*TVID,*/ VrRoute, DocNo, DocDate, InvoiceAmount, CurrencyCode, TranCompCode, CompCode)                                        
 As                                        
  (                                        
   Select /*a.TVID,*/ a.VrRoute, a.DocNo, a.DocDate, a.Amount As InvoiceAmount, '' As CurrencyCode, a.CompCode As TranCompCode, a.CompCode                                        
   From FAS_VoucherTranMast a                                               
   Where a.CompCode=Left(@CompCode, 4) and (a.DocDate Between @StartDate and @EndDate)                                         
   and (a.VrRoute Like '0B%' OR a.VrRoute Like '02%' OR a.VrRoute Like '03%' OR a.VrRoute Like '06%' OR a.VrRoute Like '09%')    
  and a.isCancelled='0'                                        
  ),                          
 InPutInvoiceList_CTE (/*TVID,*/  VrRoute, DocNo, DocDate, LrRoute, LrCode, LedgerName, IsUnRegisterDealer, InvoiceType, InvoiceNo, InvoiceDate, CompCode)                                        
 As                                        
 (                               
  Select /*a.TVID,*/  a.VrRoute, a.DocNo, a.DocDate, b.LrRoute, b.LedgerCode As LrCode, b.LedgerName,     
   b.IsUnRegisterDealer, c.RefType, c.RefNo, c.RefDate, a.CompCode                                         
  From DocList_CTE a                                        
  Left Outer Join(Select b2.LrRoute, b2.LedgerCode, b2.LedgerName, '0' As IsUnRegisterDealer, /*c2.TVID,*/  c2.DocNo, c2.DocDate, c2.VrRoute, b2.CompCode    
          From FAS_LedgerMaster_AuthTbl b2                                           
          Inner Join FAS_VoucherTranSub c2                                          
          On b2.LedgerCode=c2.LrCode and b2.CompCode=c2.CompCode      
           and (c2.VrRoute Like '0B%' OR c2.VrRoute Like '02%' OR c2.VrRoute Like '03%'     
             OR c2.VrRoute Like '06%' OR c2.VrRoute Like '09%')                                        
          Where (b2.LrRoute like '0206%' OR b2.LrRoute like '0303%') and b2.CompCode=Left(@CompCode, 4)     
           and (c2.DocDate between @StartDate and @EndDate)                                          
  ) b                                          
   On /*a.TVID=b.TVID*/ a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute    
   and a.CompCode=b.CompCode                                      
  Left Outer Join FAS_VoucherTranRef c                                        
   On /*a.TVID=c.TVID*/ a.DocNo=c.DocNo and a.DocDate=c.DocDate and a.VrRoute=c.VrRoute     
    and a.CompCode=c.CompCode                                        
 ),     
 InPutTaxLedger_CTE(TaxLrCode, TaxName, TaxRate, TypeFlg, CompCode)                                          
  As                                          
   (                                          
  Select LrCode As TaxLrCode, TaxName, TaxRate, TypeFlg, CompCode                                        
  From dbo.fn_FAS_LedgerMaster_Tax('A', getdate(), getdate(), Left(@CompCode, 4))                                            
  Where CompCode=Left(@CompCode, 4) and GroupFlg in ('INPUT','OUTPUT')            
   ),     
 InPutTaxList_CTE(/*TVID,*/ VrRoute, DocNo, DocDate, TaxName, TaxRate,  CGSTTaxAmount, SGSTTaxAmount, IGSTTaxAmount, CompCode)    --TaxName, TaxRate,                                      
  As                                          
 (    
  Select /*TVID,*/ VrRoute, DocNo, DocDate, TaxName, Sum(TaxRate) As TaxRate,     
   Sum(CGSTTaxAmount) As CGSTTaxAmount, Sum(SGSTTaxAmount) As SGSTTaxAmount,     
   Sum(IGSTTaxAmount) As IGSTTaxAmount, CompCode                                      
  From                                       
   (                                      
   Select distinct /*s1.TVID,*/ s1.VrRoute, s1.DocNo, s1.DocDate,  --s1.VTSNo As TaxVTSNo, s2.TaxLrCode,                                       
    Case When s2.TaxName in ('CGST', 'SGST') Then 'IntraState' Else 'InterState' End As TaxName, s2.TaxRate,                                       
    --Sum(s2.TaxRate) As TaxRate,                                       
    Case s2.TaxName When 'CGST' then (s1.DrAmt-s1.CrAmt) Else 0 End As CGSTTaxAmount,                                          
    Case s2.TaxName When 'SGST' then (s1.DrAmt-s1.CrAmt) Else 0 End As SGSTTaxAmount,                                          
    Case s2.TaxName When 'IGST' then (s1.DrAmt-s1.CrAmt) Else 0 End As IGSTTaxAmount, s1.CompCode                                         
   From FAS_VoucherTranSub s1                                              
   Left Outer Join InPutInvoiceList_CTE s3                                        
    On /*s3.TVID=s1.TVID*/ s3.DocNo=s1.DocNo and s3.DocDate=s1.DocDate and s3.VrRoute=s1.VrRoute    
     and s3.CompCode=s1.CompCode                                          
   Inner Join InPutTaxLedger_CTE s2         
    On s2.TaxLrCode=s1.LrCode and s2.TypeFlg='Tax'  and s2.CompCode=s1.CompCode                                        
   Where s1.CompCode=Left(@CompCode, 4) and (s1.DocDate Between @StartDate and @EndDate) and s1.LrCode<>s3.LrCode                                        
    and (s1.VrRoute Like '0B%' OR s1.VrRoute Like '02%' OR s1.VrRoute Like '03%' OR s1.VrRoute Like '06%' OR s1.VrRoute Like '09%')                                        
    /* Group By s1.VrRoute, s1.DocNo, s1.DocDate,  s2.TaxName, s1.CrAmt, s1.DrAmt, s1.CompCode */                                      
  ) x                                        
  Group By /*TVID,*/ VrRoute, DocNo, DocDate,  TaxName,  CompCode                                      
 ),     
  InPutGVTaxList_CTE(/*TVID,*/ VrRoute, DocNo, DocDate, ASSGVAmount, CompCode)                                          
  AS                                          
   (                                      
   Select Distinct /*s1.TVID,*/ s1.VrRoute, s1.DocNo, s1.DocDate, Sum(s1.DrAmt-s1.CrAmt) As ASSGVAmount,     
     s1.CompCode                                         
   From FAS_VoucherTranSub s1                                              
   Left Outer Join InPutInvoiceList_CTE s3                                        
    On /*s3.TVID=s1.TVID*/ s3.DocNo=s1.DocNo and s3.DocDate=s1.DocDate and s3.VrRoute=s1.VrRoute and s3.CompCode=s1.CompCode                                      
   Where s1.VTSNo< (Select  Min(l.VTSNo) From FAS_VoucherTranSub a                                    
   Outer Apply (Select /*TVID,*/ DocNo, DocDate, VrRoute, VTSNo, CompCode         
   From FAS_VoucherTranSub n         
   Where /*a.TVID=n.TVID and*/ a.LrCode=n.LrCode /*and a.DocNo=n.DocNo and a.DocDate=n.DocDate and a.VrRoute=n.VrRoute*/ and a.Compcode=n.CompCode                                     
    and Exists (Select * From InPutTaxLedger_CTE m Where TypeFlg='Tax' and m.TaxLrCode=n.LrCode and m.CompCode=n.CompCode)                                    
    --Group By n.DocNo, n.DocDate, n.VrRoute, n.CompCode                                    
  ) l                                    
  Where /*s1.TVID=l.TVID*/ s1.DocNo=l.DocNo and s1.DocDate=l.DocDate and s1.VrRoute=l.VrRoute  and s1.Compcode=l.CompCode    
 )                                    
     and s1.CompCode=Left(@CompCode, 4) and (s1.DocDate Between @StartDate and @EndDate) and s1.LrCode<>s3.LrCode                                        
   and (s1.VrRoute Like '0B%' OR s1.VrRoute Like '02%' OR s1.VrRoute Like '03%' OR s1.VrRoute Like '06%' OR s1.VrRoute Like '09%')                                       
   Group By /*s1.TVID,*/ s1.DocNo, s1.DocDate, s1.VrRoute, s1.CompCode                                      
 ),     
  /* Assumed VTSNo 1 = Party Amount, VTSNo2 = TaxableValue, OtherTaxAmount fetched except GoodsValue and Tax i.e., Freight, Insurance and Packing and forwarding Whatever parameter taken for calculating tax portion expect Party, GoodsValue and Tax Ledgers
  
For HSN Summary Itemwise Report */                            
 InPutOtherTaxList_CTE(/*TVID,*/ VrRoute, DocNo, DocDate, OtherTaxAmount, CompCode)                                                  
 AS                                                  
 (                                              
   Select distinct /*s1.TVID,*/ s1.VrRoute, s1.DocNo, s1.DocDate, Sum(s1.CrAmt-s1.DrAmt) As OtherTaxAmount, s1.CompCode      
   From FAS_VoucherTranSub s1                                                      
   Left Outer Join InPutInvoiceList_CTE s3                                                
    On /*s3.TVID=s1.TVID*/ s3.DocNo=s1.DocNo and s3.DocDate=s1.DocDate and s3.VrRoute=s1.VrRoute  and s3.CompCode=s1.CompCode     
   Where s1.VTSNo>2 and s1.VTSNo< (Select  Min(l.VTSNo) From FAS_VoucherTranSub a                        
   Outer Apply (Select /*TVID,*/ DocNo, DocDate, VrRoute, VTSNo, CompCode         
          From FAS_VoucherTranSub n         
          Where /*a.TVID=n.TVID and*/ a.LrCode=n.LrCode and a.DocNo=n.DocNo and a.DocDate=n.DocDate and a.VrRoute=n.VrRoute and a.Compcode=n.CompCode    
             and Exists( Select * From InPutTaxLedger_CTE m     
Where TypeFlg='Tax' and m.TaxLrCode=n.LrCode and m.CompCode=n.CompCode)    
          /* Group By n.DocNo, n.DocDate, n.VrRoute, n.CompCode */    
   ) l                                           
   Where /*s1.TVID=l.TVID*/ s1.DocNo=l.DocNo and s1.DocDate=l.DocDate and s1.VrRoute=l.VrRoute and s1.Compcode=l.CompCode    
    )                                            
     and s1.CompCode=Left(@CompCode, 4) and (s1.DocDate Between @StartDate and @EndDate) and s1.LrCode<>s3.LrCode                                                
        and (s1.VrRoute Like '0K%' OR s1.VrRoute Like '02%' OR s1.VrRoute Like '03%'   OR s1.VrRoute Like '06%'  OR s1.VrRoute Like '09%')   
                                                    
  Group By /*s1.TVID,*/ s1.DocNo, s1.DocDate, s1.VrRoute, s1.CompCode                                              
 ),     
 InPutGSTR_CTE (/*TVID,*/ VrRoute, VoucherType, TaxName,  LrCode, LedgerName, GSTRegNo,  IsUnRegisterDealer, DocNo, DocDate, InvoiceType, InvoiceNo, InvoiceDate, InvoiceValue,    
   PlaceOfSupply, ReverseCharge, TypeOfInvoice, ECommerceGSTRegNo, TaxRate, TaxableValue, CGSTTaxAmount, SGSTTaxAmount, IGSTTaxAmount, CessAmount, IsImportPurchase,  
 /* HSNNo, ItemCode, ItemDesc, ItemCount, UOMDesc, UOMDecimal, InvoiceQty, Rate, GoodsValue, */                      
  OtherTaxAmount, RefNo, RefDate, TranCompCode, Compcode )                                        
  As                                                     
   ( Select /*a.TVID,*/ a.VrRoute, f.VoucherName As VoucherType, c.TaxName, b.LrCode, b.LedgerName,     
   IsNull(d.GSTRegNo, '') As GSTRegNo, b.IsUnRegisterDealer, a.DocNo, a.DocDate, b.InvoiceType,     
   b.InvoiceNo, b.InvoiceDate, a.InvoiceAmount As InvoiceValue,                                          
   Case When IsNull(e.TypeCode, '') <> '' and  Isnull(d.State, '') <> '' Then (e.TypeCode + '-'+  Upper(d.State))                                        
   When IsNull(e.TypeCode, '') <> '' and  Isnull(d.State, '') = '' Then e.TypeCode                                         
   When IsNull(e.TypeCode, '') = '' and  Isnull(d.State, '') <> '' Then Upper(d.State)                                        
   End As PlaceOfSupply,                     
   Case When IsNull(d.GSTRegNo, '')<> '' Then 'N' Else 'Y' End As ReverseCharge,     
   'Regular' As TypeOfInvoice, '' As ECommerceGSTRegNo, c.TaxRate,                                        
   /* Case When c.TaxName='IntraState' Then (@NoOfTaxRate * c.TaxRate) Else c.TaxRate End As CumTaxRate, */                                        
   c1.ASSGVAmount As TaxableValue, c.CGSTTaxAmount, c.SGSTTaxAmount, c.IGSTTaxAmount, 0 As CessAmount,     
   Case When a.CurrencyCode='INR' then 0 Else 1 End As IsImportPurchase,                               
   /* g.HSNNo, e1.ItemCode, g.ItemDesc, h.ItemCount, g.PurchaseUOMDesc As UOMDesc,     
    g.PurchaseUOMDecimal As UOMDecimal, isNull(SUM(e1.Qty),0) As InvoiceQty, isNull(e1.Rate, 0) As Rate,       
    isNull((SUM(e1.Qty)*e1.Rate), 0) As GoodsValue, */    
   g1.OtherTaxAmount, g2.RefNo, g2.RefDate, a.TranCompcode, a.Compcode                                   
   From DocList_CTE a                                         
   Left Outer Join InPutInvoiceList_CTE b                                        
  On /*a.TVID=b.TVID*/ a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode                                        
   Left Outer join InPutTaxList_CTE  c                                        
  On /*a.TVID=c.TVID*/ a.DocNo=c.DocNo and a.DocDate=c.DocDate and a.VrRoute=c.VrRoute and a.CompCode=c.CompCode                                        
   Left Outer join InPutGVTaxList_CTE c1                                        
  On /*a.TVID=c1.TVID*/ a.DocNo=c1.DocNo and a.DocDate=c1.DocDate and a.VrRoute=c1.VrRoute and a.CompCode=c1.CompCode                                        
   Left Outer join FAS_LrAddress d      --FAS_LrAddress_AuthTbl d                                        
  On b.LrCode=d.LrCode and b.CompCode=d.CompCode -- and AddressType In('CL','CA')    
   Left Outer Join dbo.fn_Com_CountryCity_Master ('A',  @AsonDate, @RptDate, @BranchID, @CompID) e                                        
  On d.State=e.ChildName                       
   Left Outer Join FAS_VoucherMaster f                                    
  On a.VrRoute=f.VrRoute+f.VrWidth and a.CompCode=f.CompCode                         
   Left Outer Join InPutOtherTaxList_CTE g1                             
  On /*a.TVID=g1.TVID*/ a.DocNo=g1.DocNo and a.DocDate=g1.DocDate and a.VrRoute=g1.VrRoute     
   and a.CompCode=g1.CompCode                  
   Left Outer Join FAS_BillDetails g2   --FAS_VoucherTranBills g2                             
  On /*a.TVID=g2.TVID*/ a.DocNo=g2.DocNo and a.DocDate=g2.DocDate and a.VrRoute=g2.VrRoute    
   and a.CompCode=g2.CompCode                     
   Where a.CompCode=Left(@CompCode, 4) and IsNull(e.TypeCode, '') <> ''      
 )                  
 Insert into @GSTPurchaseTable                                            
   Select VrRoute, VoucherType, TaxName, LrCode, LedgerName, GSTRegNo, IsUnRegisterDealer,    
   DocNo, DocDate, InvoiceType, InvoiceNo, InvoiceDate,                               
   /* HSNNo, ItemCode, ItemDesc, ItemCount, UOMDesc, UOMDecimal, InvoiceQty, Rate, GoodsValue, */    
   InvoiceValue, IsNull(PlaceOfSupply, '') As PlaceOfSupply, ReverseCharge, TypeOfInvoice,     
   ECommerceGSTRegNo,  IsNull(TaxRate, 0) As TaxRate, Abs(IsNull(TaxableValue, 0)) As TaxableValue,                                  
   Abs(IsNull(CGSTTaxAmount, 0)) As CGSTTaxAmount, Abs(IsNull(SGSTTaxAmount, 0)) As SGSTTaxAmount,     
   Abs(IsNull(IGSTTaxAmount, 0)) As IGSTTaxAmount, Abs(IsNull(OtherTaxAmount, 0)) As OtherTaxAmount,                             
   CessAmount, IsImportPurchase, RefNo, RefDAte, TranCompCode, CompCode                                       
   From INPutGSTR_CTE  
     
   RETURN;                                                                                    
END    
                                      
  
  
  
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Rpt_GST_Purchase_HSNSummary]    Script Date: 17/06/2026 11:38:45 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Rpt_GST_Purchase_HSNSummary](@StartDate datetime, @EndDate datetime, 
	@AsonDate datetime, @RptDate datetime, @CompCode Varchar(12))                                
RETURNS @GSTPurchaseHSNTable TABLE                 
 (                 
  LedgerName Varchar(50),              
  GSTRegNo varchar(20),      
  IsUnRegisterDealer bit,                
  VrRoute varchar(42),             
  HSNNO varchar(10),                        
  ItemCode Varchar(20),                         
  ItemDesc Varchar(50),                           
  UOMDesc Varchar(50),                        
  UOMDecimal int,                         
  InvoiceQty Float,                            
  GoodsValue money,                   
  InvoiceValue money,                                  
  TaxableValue money,                             
  CGSTTAxAmount money,                                     
  SGSTTAxAmount money,                                     
  IGSTTAxAmount money,              
  CessAmount money,              
  IsExportSales bit,                 
  CompCode varchar(12)               
 )                  
As                                          
BEGIN                 
/*                      
		a.VrRoute, a.TaxName, a.Lrcode, a.LedgerName, a.GSTRegNo, a.DocNo, a.DocDate, a.InvoiceType, a.InvoiceNo, 
		a.InvoiceDate, a.InvoiceValue, a.PlaceOfSupply, a.ReverseCharge, a.TypeOfInvoice, a.ECommerceGSTRegNo,               
		a.TaxRate, a.TaxableValue, a.CESSAmount, a.IsExportSales, a.TranCompCode, a.CompCode              
*/                         	
/*	10. hsn:
		HSN wise summary of goods /services supplied during the tax period               
		HSN Description UQC Total Quantity Total Value Taxable Value Integrated Tax Amount 
		Central Tax Amount State/UT Tax Amount Cess Amount            
            
		--HSNNo, ItemCode, ItemDesc, ItemCount, UOMDesc, UOMDecimal, InvoiceQty, Rate, GoodsValue,             
*/
-----------------------------------
	/* Insert Data Into Temp Table */              
	Insert Into @GSTPurchaseHSNTable              
		Select x.LedgerName, x.GSTRegNo, x.IsUnRegisterDealer, x.VrRoute, x.HSNNo, x.ItemCode, x.ItemDesc, x.UOMDesc, x.UOMDecimal, 
			x.InvoiceQty, x.GoodsValue, x.InvoiceValue,              
			Case When (x.IGSTTaxAmount+x.CGSTTaxAmount+x.SGSTTaxAmount)>0 then (x.GoodsValue+IsNull(x.OtherTaxableValue,0)) Else 0 End As TaxableValue,              
			Case When x.CGSTTaxAmount>0	Then (((x.GoodsValue+IsNull(x.OtherTaxableValue,0))/100) * x.TaxRate) Else 0 End  CGSTTaxAmount,                     
			Case When x.SGSTTaxAmount>0 Then (((x.GoodsValue+IsNull(x.OtherTaxableValue,0))/100) * x.TaxRate) Else 0 End  SGSTTaxAmount,               
			Case When x.IGSTTaxAmount>0 Then (((x.GoodsValue+IsNull(x.OtherTaxableValue,0))/100) * x.TaxRate) Else 0 End  IGSTTaxAmount,                       
			-- x.CGSTTaxAmount, x.SGSTTaxAmount, x.IGSTTaxAmount,             
			x.CESSAmount, x.IsImportPurchase, x.CompCode             
		From            
		(            
		 Select a.LedgerName, a.GSTRegNo, IsUnRegisterDealer, a.VrRoute, a.InvoiceType, a.InvoiceNo, a.InvoiceDate, 
				IsNull(c.HSNNo,'') As HSNNo, b.ItemCode, c.ItemDesc, h.ItemCount, c.PurchaseUOMDesc As UOMDesc, 
				c.PurchaseUOMDecimal As UOMDecimal, IsNull((b.Qty), 0) As InvoiceQty, IsNull(b.Rate, 0) As Rate,             
				IsNull(((b.Qty)*b.Rate), 0) As GoodsValue, a.InvoiceValue, 
				Case When a.TaxName='InterState' Then a.TaxRate Else (a.TaxRate/2) End As TaxRate, 
				(a.OtherTaxAmount/h.ItemCount) As OtherTaxableValue,                   
				a.CGSTTaxAmount, a.SGSTTaxAmount, a.IGSTTaxAmount, a.CESSAmount, a.IsImportPurchase, a.CompCode              
		 From dbo.fn_FAS_Rpt_GST_Purchase(@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode) a              
		 Left Outer Join PurchaseInvoice b                            
			On b.DocType=a.InvoiceType and b.DocNo=a.InvoiceNo and b.DocDate=a.InvoiceDate and Left(a.TranCompCode, 4)=(b.CompID+b.BranchID)                            
		 Outer Apply dbo.fn_BOM_Get_Material_Master_HSNSummary('M', b.ItemCode, @AsonDate, @RptDate, b.BranchID, b.CompID)c    
			/* OUTER APPLY fn_BOM_Get_Material_Master_Item('M', b.ItemCode, @AsonDate, @RptDate, b.BranchID, b.CompID)c */
		 Left Outer Join (Select DocType, DocNo, DocDate, count(ItemCode) As ItemCount, BranchID, CompID                     
												From PUR_PurchaseInvoice_Dtl                    
												Where CompID+BranchID=Left(@CompCode, 4) --DocDate between @StartDate and @EndDate                    
												Group By DocType, DocNo, DocDate, BranchID, CompID                    
			 ) h                    
		 On h.DocType=b.DocType and h.DocNo=b.DocNo and h.DocDate=b.DocDate and h.BranchID=b.BranchID and h.CompID=b.CompID            
		 Where a.VrRoute Like '0B%'       --and a.GSTRegNo <> ''       
		) x            
		Order By x.LedgerName            
                
	RETURN;              
END 
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Rpt_GST_Purchase_Old]    Script Date: 17/06/2026 11:38:45 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Rpt_GST_Purchase_Old](@StartDate datetime, @EndDate datetime,   
 @AsonDate datetime, @RptDate datetime, @CompCode Varchar(12))                                                                  
RETURNS @GSTPurchaseTable TABLE                                         
(                                        
   VrRoute varchar(42),                                       
   VoucherType varchar(50),                                  
   TaxName varchar(20),                                       
   LrCode int,                                       
   LedgerName varchar(50),                                       
   GSTRegNo varchar(50),         
   IsUnRegisterDealer bit,                                  
   DocNo int ,                                       
   DocDate datetime,                                         
   InvoiceType varchar(3),                                       
   InvoiceNo int,                                       
   InvoiceDate datetime,                              
   --HSNNO varchar(10),                              
   --ItemCode Varchar(20),                               
   --ItemDesc Varchar(50),                               
   --ItemCount int,                                   
   --UOMDesc Varchar(50),                              
   --UOMDecimal int,                               
   --InvoiceQty Float,                                           
   --Rate Float,                            
   --GoodsValue money,                                   
   InvoiceValue money,                                       
   PlaceOfSupply varchar(60),                                       
   ReverseCharge Char(1),                                       
   TypeOfInvoice varchar(50),                                       
   ECommerceGSTRegNo varchar(20),                                       
   TaxRate money,                                       
   TaxableValue money,                                   
   CGSTTAxAmount money,                                       
   SGSTTAxAmount money,                                       
   IGSTTAxAmount money,                                       
   OtherTaxAmount money,                                      
   CessAmount money,                                       
   IsImportPurchase bit,                     
   RefNo Varchar(50),              
   RefDate datetime,                               
   TranCompCode varchar(12),                                      
   CompCode varchar(12)                                       
)                                          
As  
BEGIN                                                                          
                                        
 /* Following Reports addressed,                                  
   Inter State Register Dealer,                                   
   Intra State Register Dealer,                                   
   Inter State UnRegister Dealer,                                   
   Intra State UnRegister Dealer,                                    
   Credit Note Register and Unregister Dealer also Inter and Intra state,                                    
   Debit Note Register and Unregister also Inter and Intra state using this procedure                                 
   HSN summary                              
 */                                      
                                                
 /* Help */                                      
 /* VrRoute    : Purchase = '0B', CreditNote = '02', DebitNote = '03', Journal = '06' , Payment = '09' */                                      
 /* LedgerRoute: Purchase = '0303' */                                      
 /* Sales   : GroupFlg='INPUT'*/                                      
 /* TaxName   : WithInState = Intrastate, OtherState = Interstate */                                      
 /* Posting Ledger for Tax : TypeFlg='Tax' */                                      
 /* Posting Ledger for GoodsValue :  TypeFlg='AVGV' */                                      
 /* CGST + SGST called As IntraState. So @NoOfTaxRate multiply into two to show the Cumulative TaxRate in Report for Intrastate */                                      
                                      
 Declare @NoofTaxRate int                                      
 SET @NoofTaxRate=2                                       
                                                                      
 Declare @CompID As Varchar(3)                                      
 Declare @BranchID As Varchar(3)                          
                                      
 Set @CompID=Left(@CompCode, 2);                                      
 Set @BranchID=Substring(@CompCode, 3, 2);                                     
                                 
 ;With DocList_CTE (/*TVID,*/ VrRoute, DocNo, DocDate, InvoiceAmount, CurrencyCode, TranCompCode, CompCode)                                      
 As                                      
  (                                      
   Select /*a.TVID,*/ a.VrRoute, a.DocNo, a.DocDate, a.Amount As InvoiceAmount, '' As CurrencyCode, a.CompCode As TranCompCode, a.CompCode                                      
   From FAS_VoucherTranMast a                                             
   Where a.CompCode=Left(@CompCode, 4) and (a.DocDate Between @StartDate and @EndDate)                                       
   and (a.VrRoute Like '0B%' OR a.VrRoute Like '02%' OR a.VrRoute Like '03%' OR a.VrRoute Like '06%' OR a.VrRoute Like '09%')  
   and a.isCancelled='0'                                      
  ),                        
 InPutInvoiceList_CTE (/*TVID,*/  VrRoute, LrRoute, DocNo, DocDate, LrCode, LedgerName, IsUnRegisterDealer, InvoiceType, InvoiceNo, InvoiceDate, CompCode)                                      
 As                                      
 (                             
  Select /*a.TVID,*/  a.VrRoute, b.LrRoute, a.DocNo, a.DocDate, b.LedgerCode As LrCode, b.LedgerName,   
   b.IsUnRegisterDealer, c.RefType, c.RefNo, c.RefDate, a.CompCode                                       
  From DocList_CTE a                                      
  Left Outer Join(Select c2.VrRoute, b2.LrRoute, /*c2.TVID,*/ c2.DocType, c2.DocNo, c2.DocDate, b2.LedgerCode,   
           b2.LedgerName, '0' As IsUnRegisterDealer, b2.CompCode                                        
          From FAS_LedgerMaster_AuthTbl b2                                         
          Inner Join FAS_VoucherTranSub c2                                        
          On b2.LedgerCode=c2.LrCode and b2.CompCode=c2.CompCode    
           and (c2.VrRoute Like '0B%' OR c2.VrRoute Like '02%' OR c2.VrRoute Like '03%'   
             OR c2.VrRoute Like '06%' OR c2.VrRoute Like '09%')                                      
          Where (b2.LrRoute like '0206%' OR b2.LrRoute like '0303%') and b2.CompCode=Left(@CompCode, 4)   
           and (c2.DocDate between @StartDate and @EndDate)                                        
  ) b                                        
   On /*a.TVID=b.TVID*/ a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute  
   and a.CompCode=b.CompCode                                    
  Left Outer Join FAS_VoucherTranRef c                                      
   On /*a.TVID=c.TVID*/ a.DocNo=c.DocNo and a.DocDate=c.DocDate and a.VrRoute=c.VrRoute   
    and a.CompCode=c.CompCode                                      
 ),   
 InPutTaxLedger_CTE(TaxLrCode, TaxName, TaxRate, TypeFlg, CompCode)                                        
  As                                        
   (                                        
  Select LrCode As TaxLrCode, TaxName, TaxRate, TypeFlg, CompCode                                      
  From dbo.fn_FAS_LedgerMaster_Tax('A', getdate(), getdate(), Left(@CompCode, 4))                                          
  Where CompCode=Left(@CompCode, 4) and GroupFlg in ('INPUT','OUTPUT')          
   ),   
 InPutTaxList_CTE(/*TVID,*/ VrRoute, DocNo, DocDate, TaxName, TaxRate,  CGSTTaxAmount, SGSTTaxAmount, IGSTTaxAmount, CompCode)    --TaxName, TaxRate,                                    
  As                                        
 (  
  Select /*TVID,*/ VrRoute, DocNo, DocDate, TaxName, Sum(TaxRate) As TaxRate,   
   Sum(CGSTTaxAmount) As CGSTTaxAmount, Sum(SGSTTaxAmount) As SGSTTaxAmount,   
   Sum(IGSTTaxAmount) As IGSTTaxAmount, CompCode                                    
  From                                     
   (                                    
   Select distinct /*s1.TVID,*/ s1.VrRoute, s1.DocNo, s1.DocDate,  --s1.VTSNo As TaxVTSNo, s2.TaxLrCode,                                     
    Case When s2.TaxName in ('CGST', 'SGST') Then 'IntraState' Else 'InterState' End As TaxName, s2.TaxRate,                                     
    --Sum(s2.TaxRate) As TaxRate,                                     
    Case s2.TaxName When 'CGST' then (s1.DrAmt-s1.CrAmt) Else 0 End As CGSTTaxAmount,                                        
    Case s2.TaxName When 'SGST' then (s1.DrAmt-s1.CrAmt) Else 0 End As SGSTTaxAmount,                                        
    Case s2.TaxName When 'IGST' then (s1.DrAmt-s1.CrAmt) Else 0 End As IGSTTaxAmount, s1.CompCode                                       
   From FAS_VoucherTranSub s1                                            
   Left Outer Join InPutInvoiceList_CTE s3                                      
    On /*s3.TVID=s1.TVID*/ s3.DocNo=s1.DocNo and s3.DocDate=s1.DocDate and s3.VrRoute=s1.VrRoute  
     and s3.CompCode=s1.CompCode                                        
   Inner Join InPutTaxLedger_CTE s2       
    On s2.TaxLrCode=s1.LrCode and s2.TypeFlg='Tax'  and s2.CompCode=s1.CompCode                                      
   Where s1.CompCode=Left(@CompCode, 4) and (s1.DocDate Between @StartDate and @EndDate) and s1.LrCode<>s3.LrCode                                      
    and (s1.VrRoute Like '0B%' OR s1.VrRoute Like '02%' OR s1.VrRoute Like '03%' OR s1.VrRoute Like '06%' OR s1.VrRoute Like '09%')                                      
    /* Group By s1.VrRoute, s1.DocNo, s1.DocDate,  s2.TaxName, s1.CrAmt, s1.DrAmt, s1.CompCode */                                    
  ) x                                      
  Group By /*TVID,*/ VrRoute, DocNo, DocDate,  TaxName,  CompCode                                    
 ),   
  InPutGVTaxList_CTE(/*TVID,*/ VrRoute, DocNo, DocDate, ASSGVAmount, CompCode)                                        
  AS                                        
   (                                    
   Select Distinct /*s1.TVID,*/ s1.VrRoute, s1.DocNo, s1.DocDate, Sum(s1.DrAmt-s1.CrAmt) As ASSGVAmount,   
     s1.CompCode                                       
   From FAS_VoucherTranSub s1                                            
   Left Outer Join InPutInvoiceList_CTE s3                                      
    On /*s3.TVID=s1.TVID*/ s3.DocNo=s1.DocNo and s3.DocDate=s1.DocDate and s3.VrRoute=s1.VrRoute and s3.CompCode=s1.CompCode                                    
   Where s1.VTSNo< (Select  Min(l.VTSNo) From FAS_VoucherTranSub a                                  
   Outer Apply (Select /*TVID,*/ DocNo, DocDate, VrRoute, VTSNo, CompCode       
   From FAS_VoucherTranSub n       
   Where /*a.TVID=n.TVID and*/ a.LrCode=n.LrCode /*and a.DocNo=n.DocNo and a.DocDate=n.DocDate and a.VrRoute=n.VrRoute*/ and a.Compcode=n.CompCode                                   
    and Exists (Select * From InPutTaxLedger_CTE m Where TypeFlg='Tax' and m.TaxLrCode=n.LrCode and m.CompCode=n.CompCode)                                  
    --Group By n.DocNo, n.DocDate, n.VrRoute, n.CompCode                                  
  ) l                                  
  Where /*s1.TVID=l.TVID*/ s1.DocNo=l.DocNo and s1.DocDate=l.DocDate and s1.VrRoute=l.VrRoute   
   and s1.Compcode=l.CompCode                                   
 )                                  
     and s1.CompCode=Left(@CompCode, 4) and (s1.DocDate Between @StartDate and @EndDate) and s1.LrCode<>s3.LrCode                                      
   and (s1.VrRoute Like '0B%' OR s1.VrRoute Like '02%' OR s1.VrRoute Like '03%' OR s1.VrRoute Like '06%' OR s1.VrRoute Like '09%')                                     
   Group By /*s1.TVID,*/ s1.DocNo, s1.DocDate, s1.VrRoute, s1.CompCode                                    
 ),   
 InPutOtherTaxList_CTE(/*TVID,*/ VrRoute, DocNo, DocDate, OtherTaxAmount, CompCode)                                                
 AS                                                
 (                                            
   Select distinct /*s1.TVID,*/ s1.VrRoute, s1.DocNo, s1.DocDate, Sum(s1.CrAmt-s1.DrAmt) As OtherTaxAmount,   
    s1.CompCode                                               
   From FAS_VoucherTranSub s1                                                    
   Left Outer Join InPutInvoiceList_CTE s3                                              
    On /*s3.TVID=s1.TVID*/ s3.DocNo=s1.DocNo and s3.DocDate=s1.DocDate and s3.VrRoute=s1.VrRoute   
     and s3.CompCode=s1.CompCode                                            
   Where s1.VTSNo>2 and s1.VTSNo< (Select  Min(l.VTSNo) From FAS_VoucherTranSub a                      
   Outer Apply (Select /*TVID,*/ DocNo, DocDate, VrRoute, VTSNo, CompCode       
          From FAS_VoucherTranSub n       
          Where /*a.TVID=n.TVID and*/ a.LrCode=n.LrCode and a.DocNo=n.DocNo and a.DocDate=n.DocDate and a.VrRoute=n.VrRoute   
           and a.Compcode=n.CompCode  and Exists( Select * From InPutTaxLedger_CTE m   
                              Where TypeFlg='Tax' and m.TaxLrCode=n.LrCode and m.CompCode=n.CompCode  
                             )                                          
          /* Group By n.DocNo, n.DocDate, n.VrRoute, n.CompCode */  
   ) l                                         
   Where /*s1.TVID=l.TVID*/ s1.DocNo=l.DocNo and s1.DocDate=l.DocDate and s1.VrRoute=l.VrRoute  
    and s1.Compcode=l.CompCode                                           
    )                                          
     and s1.CompCode=Left(@CompCode, 4) and (s1.DocDate Between @StartDate and @EndDate) and s1.LrCode<>s3.LrCode                                              
        and (s1.VrRoute Like '0K%' OR s1.VrRoute Like '02%' OR s1.VrRoute Like '03%'   
      OR s1.VrRoute Like '06%'  OR s1.VrRoute Like '09%')                                             
  Group By /*s1.TVID,*/ s1.DocNo, s1.DocDate, s1.VrRoute, s1.CompCode                                            
 ),   
 InPutGSTR_CTE (/*TVID,*/ VrRoute, VoucherType, TaxName,  LrCode, LedgerName, GSTRegNo,   
   IsUnRegisterDealer, DocNo, DocDate, InvoiceType, InvoiceNo, InvoiceDate, InvoiceValue,   
   PlaceOfSupply, ReverseCharge, TypeOfInvoice, ECommerceGSTRegNo, TaxRate, TaxableValue,   
   CGSTTaxAmount, SGSTTaxAmount, IGSTTaxAmount, CessAmount, IsImportPurchase,                     
   /* HSNNo, ItemCode, ItemDesc, ItemCount, UOMDesc, UOMDecimal, InvoiceQty, Rate, GoodsValue, */                    
  OtherTaxAmount, RefNo, RefDate, TranCompCode, Compcode  
 )                                      
  As                                                   
   ( Select /*a.TVID,*/ a.VrRoute, f.VoucherName As VoucherType, c.TaxName, b.LrCode, b.LedgerName,   
   IsNull(d.GSTRegNo, '') As GSTRegNo, b.IsUnRegisterDealer, a.DocNo, a.DocDate, b.InvoiceType,   
   b.InvoiceNo, b.InvoiceDate, a.InvoiceAmount As InvoiceValue,                                        
   Case When IsNull(e.TypeCode, '') <> '' and  Isnull(d.State, '') <> '' Then (e.TypeCode + '-'+  Upper(d.State))                                      
   When IsNull(e.TypeCode, '') <> '' and  Isnull(d.State, '') = '' Then e.TypeCode                                       
   When IsNull(e.TypeCode, '') = '' and  Isnull(d.State, '') <> '' Then Upper(d.State)                                      
   End As PlaceOfSupply,                                       
   Case When IsNull(d.GSTRegNo, '')<> '' Then 'N' Else 'Y' End As ReverseCharge,   
   'Regular' As TypeOfInvoice, '' As ECommerceGSTRegNo, c.TaxRate,                                      
   /* Case When c.TaxName='IntraState' Then (@NoOfTaxRate * c.TaxRate) Else c.TaxRate End As CumTaxRate, */                                      
   c1.ASSGVAmount As TaxableValue, c.CGSTTaxAmount, c.SGSTTaxAmount, c.IGSTTaxAmount, 0 As CessAmount,   
   Case When a.CurrencyCode='INR' then 0 Else 1 End As IsImportPurchase,                             
   /* g.HSNNo, e1.ItemCode, g.ItemDesc, h.ItemCount, g.PurchaseUOMDesc As UOMDesc,   
    g.PurchaseUOMDecimal As UOMDecimal, isNull(SUM(e1.Qty),0) As InvoiceQty, isNull(e1.Rate, 0) As Rate,     
    isNull((SUM(e1.Qty)*e1.Rate), 0) As GoodsValue, */  
   g1.OtherTaxAmount, g2.RefNo, g2.RefDate, a.TranCompcode, a.Compcode                                 
   From DocList_CTE a                                       
   Left Outer Join InPutInvoiceList_CTE b                                      
  On /*a.TVID=b.TVID*/ a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode                                      
   Left Outer join InPutTaxList_CTE  c                                      
  On /*a.TVID=c.TVID*/ a.DocNo=c.DocNo and a.DocDate=c.DocDate and a.VrRoute=c.VrRoute and a.CompCode=c.CompCode                                      
   Left Outer join InPutGVTaxList_CTE c1                                      
  On /*a.TVID=c1.TVID*/ a.DocNo=c1.DocNo and a.DocDate=c1.DocDate and a.VrRoute=c1.VrRoute and a.CompCode=c1.CompCode                                      
   Left Outer join FAS_LrAddress d      --FAS_LrAddress_AuthTbl d                                      
  On b.LrCode=d.LrCode and b.CompCode=d.CompCode -- and AddressType In('CL','CA')  
   Left Outer Join dbo.fn_Com_CountryCity_Master ('A',  @AsonDate, @RptDate, @BranchID, @CompID) e                                      
  On d.State=e.ChildName                     
   Left Outer Join FAS_VoucherMaster f                                  
  On a.VrRoute=f.VrRoute+f.VrWidth and a.CompCode=f.CompCode                       
   Left Outer Join InPutOtherTaxList_CTE g1                           
  On /*a.TVID=g1.TVID*/ a.DocNo=g1.DocNo and a.DocDate=g1.DocDate and a.VrRoute=g1.VrRoute   
   and a.CompCode=g1.CompCode                
   Left Outer Join FAS_BillDetails g2   --FAS_VoucherTranBills g2                           
  On /*a.TVID=g2.TVID*/ a.DocNo=g2.DocNo and a.DocDate=g2.DocDate and a.VrRoute=g2.VrRoute  
   and a.CompCode=g2.CompCode                   
   Where a.CompCode=Left(@CompCode, 4)   
 )                                                                          
                              
 Insert into @GSTPurchaseTable                                          
   Select VrRoute, VoucherType, TaxName, LrCode, LedgerName, GSTRegNo, IsUnRegisterDealer,  
   DocNo, DocDate, InvoiceType, InvoiceNo, InvoiceDate,                             
   /* HSNNo, ItemCode, ItemDesc, ItemCount, UOMDesc, UOMDecimal, InvoiceQty, Rate, GoodsValue, */  
   InvoiceValue, IsNull(PlaceOfSupply, '') As PlaceOfSupply, ReverseCharge, TypeOfInvoice,   
   ECommerceGSTRegNo,  IsNull(TaxRate, 0) As TaxRate, Abs(IsNull(TaxableValue, 0)) As TaxableValue,                                
   Abs(IsNull(CGSTTaxAmount, 0)) As CGSTTaxAmount, Abs(IsNull(SGSTTaxAmount, 0)) As SGSTTaxAmount,   
   Abs(IsNull(IGSTTaxAmount, 0)) As IGSTTaxAmount, Abs(IsNull(OtherTaxAmount, 0)) As OtherTaxAmount,                           
   CessAmount, IsImportPurchase, RefNo, RefDAte, TranCompCode, CompCode                                     
   From INPutGSTR_CTE   
---------------------  
/* Previous Query:  
  RETURNS @GSTPurchaseTable TABLE                                         
  (                                        
   VrRoute varchar(42),                                       
   VoucherType varchar(50),                                  
   TaxName varchar(20),                                       
   LrCode int,                                       
   LedgerName varchar(50),                                       
   GSTRegNo varchar(50),         
   IsUnRegisterDealer bit,                                  
   DocNo int ,                                       
   DocDate datetime,                                         
   InvoiceType varchar(3),                                       
   InvoiceNo int,                                       
   InvoiceDate datetime,                              
   --HSNNO varchar(10),                              
   --ItemCode Varchar(20),                               
   --ItemDesc Varchar(50),                               
   --ItemCount int,                                   
   --UOMDesc Varchar(50),                              
   --UOMDecimal int,                               
   --InvoiceQty Float,                                           
   --Rate Float,                            
   --GoodsValue money,                                   
   InvoiceValue money,                                       
   PlaceOfSupply varchar(60),                                       
   ReverseCharge Char(1),                                       
   TypeOfInvoice varchar(50),                                       
   ECommerceGSTRegNo varchar(20),                                       
   TaxRate money,                                       
   TaxableValue money,                                   
   CGSTTAxAmount money,                                       
   SGSTTAxAmount money,                                       
   IGSTTAxAmount money,                                       
   OtherTaxAmount money,                                      
   CessAmount money,                                       
   IsImportPurchase bit,                     
   RefNo Varchar(50),              
   RefDate datetime,                               
   TranCompCode varchar(12),                                      
   CompCode varchar(12)                                       
  )                                          
                                                                  
BEGIN                                                                          
                                        
 /* Following Reports addressed,                                  
   Inter State Register Dealer,                                   
   Intra State Register Dealer,                                   
   Inter State UnRegister Dealer,                                   
   Intra State UnRegister Dealer,                                    
   Credit Note Register and Unregister Dealer also Inter and Intra state,                                    
   Debit Note Register and Unregister also Inter and Intra state using this procedure                                 
   HSN summary                              
 */                                      
                                                
 /* Help */                                      
 /* VrRoute    : Purchase = '0B', CreditNote = '02', DebitNote = '03', Journal = '06' , Payment = '09' */                                      
 /* LedgerRoute: Purchase = '0303' */                                      
 /* Sales   : GroupFlg='INPUT'*/                                      
 /* TaxName   : WithInState = Intrastate, OtherState = Interstate */                                      
 /* Posting Ledger for Tax : TypeFlg='Tax' */                                      
 /* Posting Ledger for GoodsValue :  TypeFlg='AVGV' */                                      
 /* CGST + SGST called As IntraState. So @NoOfTaxRate multiply into two to show the Cumulative TaxRate in Report for Intrastate */                                      
                                      
 Declare @NoofTaxRate int                                      
 SET @NoofTaxRate=2                                       
                                                                      
 Declare @CompID As Varchar(3)                                      
 Declare @BranchID As Varchar(3)                          
                                      
 Set @CompID=Left(@CompCode, 2);                 
 Set @BranchID=Substring(@CompCode, 3, 2);                                     
                                 
 ; With DocList_CTE (TVID, VrRoute, DocNo, DocDate, InvoiceAmount, CurrencyCode, TranCompCode, CompCode)                                      
 As                                      
  (                                      
   Select a.TVID, a.VrRoute, a.DocNo, a.DocDate, a.VrAmt As InvoiceAmount, a.CurrencyCode, a.TranCompCode, a.CompCode                                      
   From FAS_VoucherTranMast a                                             
   Where a.CompCode=Left(@CompCode, 4) and (a.DocDate Between @StartDate and @EndDate)                                       
   and (a.VrRoute Like '0B%' OR a.VrRoute Like '02%' OR a.VrRoute Like '03%' OR a.VrRoute Like '06%' OR a.VrRoute Like '09%') and a.isCancelled='0'                                      
  )                                      
                                        
                                 
 /*                                     
; With DocListExceptPayment_CTE (VrRoute, DocNo, DocDate, InvoiceAmount, CurrencyCode, TranCompCode, CompCode)                                      
As                                      
 (                                      
 Select a.VrRoute, a.DocNo, a.DocDate, a.VrAmt As InvoiceAmount, a.CurrencyCode, a.TranCompCode, a.CompCode                                      
 From FAS_VoucherTranMast a                                          
 Where a.CompCode=Left(@CompCode, 4) and (a.DocDate Between @StartDate and @EndDate)                                       
 and (a.VrRoute Like '0B%' OR a.VrRoute Like '02%' OR a.VrRoute Like '03%' OR a.VrRoute Like '06%' ) and a.isCancelled='0'                                      
 )                                      
                                      
,  DocListPayment_CTE (VrRoute, DocNo, DocDate, InvoiceAmount, CurrencyCode, TranCompCode, CompCode)                                      
As                                      
 (                                      
 Select a.VrRoute, a.DocNo, a.DocDate, a.VrAmt As InvoiceAmount, a.CurrencyCode, a.TranCompCode, a.CompCode                                      
 From FAS_VoucherTranMast a                                          
 Where a.CompCode=Left(@CompCode, 4) and (a.DocDate Between @StartDate and @EndDate)                                       
 and a.VrRoute Like '09%' and a.isCancelled='0'                                  
  and Exists (Select * from FAS_VoucherTranSub m                                 
     Outer Apply (Select * From FAS_VoucherTranSub Where a.LrCode=n.LrCode and a.DocNo=n.DocNo and a.DocDate=n.DocDate and a.VrRoute=n.VrRoute and a.Compcode=n.CompCode                                 
         and Exists (Select * From FAS_LedgerMaster_AuthTbl Where  LrRoute like '0202%' and CompCode=@CompCode ) n                                
     )                                
 )                                  
                                
 ,  DocList_CTE (VrRoute, DocNo, DocDate, InvoiceAmount, CurrencyCode, TranCompCode, CompCode)                                      
As                                      
 (                                      
      Select * From DocListExceptPayment_CTE                                
   Union All                                
   Select * From DocListPayment_CTE                                
 )                                  
 */                                
                                
, InPutInvoiceList_CTE (TVID, VrRoute, DocNo, DocDate, LrRoute, LrCode, LedgerName, IsUnRegisterDealer, InvoiceType, InvoiceNo, InvoiceDate, CompCode)                                      
 As                                      
  (                             
  Select a.TVID, a.VrRoute, a.DocNo, a.DocDate, b.LrRoute, b.LedgerCode As LrCode, b.LedgerName, b.IsUnRegisterDealer, c.RefType, c.RefNo, c.RefDate, a.CompCode                                       
  From DocList_CTE a                                      
  Left Outer Join                                       
   (Select b2.LrRoute, b2.LedgerCode, b2.LedgerName, b2.IsUnRegisterDealer, c2.TVID, c2.DocNo, c2.DocDate, c2.VrRoute, b2.CompCode                                        
    From FAS_LedgerMaster_AuthTbl b2                                         
    Inner Join FAS_VoucherTranSub c2                                        
    On b2.LedgerCode=c2.LrCode and b2.CompCode=c2.CompCode  and (c2.VrRoute Like '0B%' OR c2.VrRoute Like '02%' OR c2.VrRoute Like '03%' OR c2.VrRoute Like '06%' OR c2.VrRoute Like '09%')                                      
    Where (b2.LrRoute like '0206%' OR b2.LrRoute like '0303%') and b2.CompCode=Left(@CompCode, 4) and (c2.DocDate between @StartDate and @EndDate)                                        
   ) b                                        
  On a.TVID=b.TVID /*a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute*/ and a.CompCode=b.CompCode                                    
  Left Outer Join FAS_VoucherTranRef c                                      
  On a.TVID=c.TVID /*a.DocNo=c.DocNo and a.DocDate=c.DocDate and a.VrRoute=c.VrRoute*/  and a.CompCode=c.CompCode                                      
  )                                      
                                         
 , InPutTaxLedger_CTE(TaxLrCode, TaxName, TaxRate, TypeFlg, CompCode)                                        
  As                                        
   (                                        
  Select LrCode As TaxLrCode, TaxName, TaxRate, TypeFlg, CompCode                                      
  From fn_FAS_LedgerMaster_Tax ('A', getdate(), getdate(), Left(@CompCode, 4))                                          
  Where CompCode=Left(@CompCode, 4) and GroupFlg in ('INPUT','OUTPUT')          
          
   )                                        
                                       
  , InPutTaxList_CTE(TVID, VrRoute, DocNo, DocDate, TaxName, TaxRate,  CGSTTaxAmount, SGSTTaxAmount, IGSTTaxAmount, CompCode)    --TaxName, TaxRate,                                    
  As                                        
 (                                         
                                    
  Select TVID, VrRoute, DocNo, DocDate, TaxName, Sum(TaxRate) As TaxRate, Sum(CGSTTaxAmount) As CGSTTaxAmount, Sum(SGSTTaxAmount) As SGSTTaxAmount, Sum(IGSTTaxAmount) As IGSTTaxAmount, CompCode                                    
  From                                     
   (                                    
    Select distinct s1.TVID, s1.VrRoute, s1.DocNo, s1.DocDate,  --s1.VTSNo As TaxVTSNo, s2.TaxLrCode,                                     
    Case When s2.TaxName in ('CGST', 'SGST') Then 'IntraState' Else 'InterState' End As TaxName, s2.TaxRate,                                     
   --Sum(s2.TaxRate) As TaxRate,                                     
    Case s2.TaxName When 'CGST' then (s1.DrAmt-s1.CrAmt) Else 0 End As CGSTTaxAmount,                                        
    Case s2.TaxName When 'SGST' then (s1.DrAmt-s1.CrAmt) Else 0 End As SGSTTaxAmount,                                        
    Case s2.TaxName When 'IGST' then (s1.DrAmt-s1.CrAmt) Else 0 End As IGSTTaxAmount, s1.CompCode                                       
    From FAS_VoucherTranSub s1                                            
    Left Outer Join InPutInvoiceList_CTE s3                                      
    On s3.TVID=s1.TVID /*s3.DocNo=s1.DocNo and s3.DocDate=s1.DocDate and s3.VrRoute=s1.VrRoute*/ and s3.CompCode=s1.CompCode                                        
    Inner Join InPutTaxLedger_CTE s2       
    On s2.TaxLrCode=s1.LrCode and s2.TypeFlg='Tax'  and s2.CompCode=s1.CompCode                                      
    Where s1.CompCode=Left(@CompCode, 4) and (s1.DocDate Between @StartDate and @EndDate) and s1.LrCode<>s3.LrCode                                      
    and (s1.VrRoute Like '0B%' OR s1.VrRoute Like '02%' OR s1.VrRoute Like '03%' OR s1.VrRoute Like '06%' OR s1.VrRoute Like '09%')                                      
    --Group By s1.VrRoute, s1.DocNo, s1.DocDate,  s2.TaxName, s1.CrAmt, s1.DrAmt, s1.CompCode                                      
    )x                                      
    Group By TVID, VrRoute, DocNo, DocDate,  TaxName,  CompCode                                   
                                   
 /*                                  
   Select distinct s1.VrRoute, s1.DocNo, s1.DocDate,  TaxMaxVTSNo,  s2.TaxLrCode, (s1.CrAmt-s1.DrAmt) As TaxAmount,   --s2.TaxName,                                      
  Case When s2.TaxName in ('CGST', 'SGST') Then 'IntraState' Else 'InterState' End As TaxName,                                       
   s2.TaxRate, s1.CompCode                                       
   From FAS_VoucherTranSub s1                                            
   Left Outer Join InPutInvoiceList_CTE s3                                      
   On s3.DocNo=s1.DocNo and s3.DocDate=s1.DocDate and s3.VrRoute=s1.VrRoute and s3.CompCode=s1.CompCode                                        
   Inner Join InPutTaxLedger_CTE s2 On s2.TaxLrCode=s1.LrCode and s2.TypeFlg='Tax'  and s2.CompCode=s1.CompCode                                        
   Where s1.CompCode=Left(@CompCode, 4) and (s1.DocDate Between @StartDate and @EndDate) and s1.LrCode<>s3.LrCode                                      
  and (s1.VrRoute Like '0B%' OR s1.VrRoute Like '02%' OR s1.VrRoute Like '03%' OR a.VrRoute Like '06%')                                      
     */                                      
 )                                      
                                     
--, InputTaxMinVTSNo_CTE ()                                  
--AS                               
--( Select distinct a.DocNo, a.DocDate, a.VrRoute, MaxVTSNo As TaxMaxVTSNo                                  
-- From FAS_VoucherTranSub a                                  
-- Outer Apply (Select DocNo, DocDate, VrRoute, Max(VTSNo) As MaxVTSNo From FAS_VoucherTranSub n Where a.DocNo=n.DocNo and a.DocDate=n.DocDate and a.VrRoute=n.VrRoute and a.Compcode=n.CompCode                                   
-- and Exists (Select * From FAS_LedgerMaster_Tax m Where TypeFlg='Tax' and m.LrCode=n.LrCode and m.CompCode=n.CompCode)                                  
-- Group By n.DocNo, n.DocDate, n.VrRoute                                  
-- )x                                  
--)                                    
                                       
 --, InPutGVTaxList_CTE(VrRoute, DocNo, DocDate, GVTaxVTSNo, GVTaxLrcode, ASSGVAmount, TaxName, TaxRate, CompCode)                                        
 --AS                                    
 -- (                                        
   --Select distinct s1.VrRoute, s1.DocNo, s1.DocDate, s1.VTSNo As GVTaxVTSNo, s2.TaxLrCode As GVTaxLrcode, (s1.CrAmt-s1.DrAmt) As ASSGVAmount, s2.TaxName, s2.TaxRate, s1.CompCode                                       
   --From FAS_VoucherTranSub s1                                            
   --Left Outer Join InPutInvoiceList_CTE s3                           
   --On s3.DocNo=s1.DocNo and s3.DocDate=s1.DocDate and s3.VrRoute=s1.VrRoute and s3.CompCode=s1.CompCode                                        
 --  Inner Join InPutTaxLedger_CTE s2 On s2.TaxLrCode=s1.LrCode and s2.TypeFlg='AVGV' and s2.CompCode=s1.CompCode                                      
  -- Where s1.CompCode=Left(@CompCode, 4) and (s1.DocDate Between @StartDate and @EndDate) and s1.LrCode<>s3.LrCode                                      
  --and (s1.VrRoute Like '0B%' OR s1.VrRoute Like '02%' OR s1.VrRoute Like '03%' OR a.VrRoute Like '06%')                                       
 -- )                   
                                       
 , InPutGVTaxList_CTE(TVID, VrRoute, DocNo, DocDate, ASSGVAmount, CompCode)                                        
  As                                        
   (                                    
  Select distinct s1.TVID, s1.VrRoute, s1.DocNo, s1.DocDate, Sum(s1.DrAmt-s1.CrAmt) As ASSGVAmount, s1.CompCode                                       
  From FAS_VoucherTranSub s1                                            
  Left Outer Join InPutInvoiceList_CTE s3                                      
  On s3.TVID=s1.TVID /*s3.DocNo=s1.DocNo and s3.DocDate=s1.DocDate and s3.VrRoute=s1.VrRoute*/ and s3.CompCode=s1.CompCode                                    
  Where s1.VTSNo< (Select  Min(l.VTSNo) From FAS_VoucherTranSub a                                  
  Outer Apply (Select TVID, DocNo, DocDate, VrRoute, VTSNo, CompCode       
   From FAS_VoucherTranSub n       
   Where a.TVID=n.TVID and a.LrCode=n.LrCode /*and a.DocNo=n.DocNo and a.DocDate=n.DocDate and a.VrRoute=n.VrRoute*/ and a.Compcode=n.CompCode                                   
  and Exists (Select * From InPutTaxLedger_CTE m Where TypeFlg='Tax' and m.TaxLrCode=n.LrCode and m.CompCode=n.CompCode)                                  
   --Group By n.DocNo, n.DocDate, n.VrRoute, n.CompCode                                  
     )l                                  
  Where s1.TVID=l.TVID /*s1.DocNo=l.DocNo and s1.DocDate=l.DocDate and s1.VrRoute=l.VrRoute*/ and s1.Compcode=l.CompCode                                   
    )                                  
     and s1.CompCode=Left(@CompCode, 4) and (s1.DocDate Between @StartDate and @EndDate) and s1.LrCode<>s3.LrCode                                      
   and (s1.VrRoute Like '0B%' OR s1.VrRoute Like '02%' OR s1.VrRoute Like '03%' OR s1.VrRoute Like '06%' OR s1.VrRoute Like '09%')                                     
   Group By s1.TVID, s1.DocNo, s1.DocDate, s1.VrRoute, s1.CompCode                                    
 )                                  
  /* Assumed VTSNo 1 = Party Amount, VTSNo2 = TaxableValue, OtherTaxAmount fetched except GoodsValue and Tax i.e., Freight, Insurance and Packing and forwarding Whatever parameter taken for calculating tax portion expect Party, GoodsValue and Tax Ledgers
  
For HSN Summary Itemwise Report */                            
  , InPutOtherTaxList_CTE(TVID, VrRoute, DocNo, DocDate, OtherTaxAmount, CompCode)                                                
  As                                                
   (                                            
  Select distinct s1.TVID, s1.VrRoute, s1.DocNo, s1.DocDate, Sum(s1.CrAmt-s1.DrAmt) As OtherTaxAmount, s1.CompCode                                               
  From FAS_VoucherTranSub s1                                                    
  Left Outer Join InPutInvoiceList_CTE s3                                              
  On s3.TVID=s1.TVID /*s3.DocNo=s1.DocNo and s3.DocDate=s1.DocDate and s3.VrRoute=s1.VrRoute*/ and s3.CompCode=s1.CompCode                                            
  Where s1.VTSNo>2 and s1.VTSNo< (Select  Min(l.VTSNo) From FAS_VoucherTranSub a                      
  Outer Apply (Select TVID, DocNo, DocDate, VrRoute, VTSNo, CompCode       
   From FAS_VoucherTranSub n       
   Where a.TVID=n.TVID and a.LrCode=n.LrCode /*and a.DocNo=n.DocNo and a.DocDate=n.DocDate and a.VrRoute=n.VrRoute*/ and a.Compcode=n.CompCode                                           
   and Exists (Select * From InPutTaxLedger_CTE m Where TypeFlg='Tax' and m.TaxLrCode=n.LrCode and m.CompCode=n.CompCode)                                          
   --Group By n.DocNo, n.DocDate, n.VrRoute, n.CompCode                                          
     )l                                         
  Where s1.TVID=l.TVID /*s1.DocNo=l.DocNo and s1.DocDate=l.DocDate and s1.VrRoute=l.VrRoute*/ and s1.Compcode=l.CompCode                                           
    )                                          
     and s1.CompCode=Left(@CompCode, 4) and (s1.DocDate Between @StartDate and @EndDate) and s1.LrCode<>s3.LrCode                                              
        and (s1.VrRoute Like '0K%' OR s1.VrRoute Like '02%' OR s1.VrRoute Like '03%' OR s1.VrRoute Like '06%'  OR s1.VrRoute Like '09%')                             
  Group By s1.TVID, s1.DocNo, s1.DocDate, s1.VrRoute, s1.CompCode                                            
 )                                        
                                  
 , InPutGSTR_CTE (TVID,VrRoute, VoucherType, TaxName,  LrCode, LedgerName, GSTRegNo, IsUnRegisterDealer, DocNo, DocDate, InvoiceType, InvoiceNo, InvoiceDate, InvoiceValue, PlaceOfSupply, ReverseCharge, TypeOfInvoice, ECommerceGSTRegNo, TaxRate, TaxableVa
l  
ue, CGSTTaxAmount, SGSTTaxAmount, IGSTTaxAmount, CessAmount, IsImportPurchase,                     
 --HSNNo, ItemCode, ItemDesc, ItemCount, UOMDesc, UOMDecimal, InvoiceQty, Rate, GoodsValue,                     
OtherTaxAmount, RefNo, RefDate, TranCompCode, Compcode)                                      
  As                                                   
   (                                      
   Select a.TVID, a.VrRoute, f.VoucherName As VoucherType, c.TaxName, b.LrCode, b.LedgerName, IsNull(d.GSTRegNo, '') As GSTRegNo, b.IsUnRegisterDealer, a.DocNo, a.DocDate, b.InvoiceType, b.InvoiceNo, b.InvoiceDate, a.InvoiceAmount As InvoiceValue,        
  
                          
        
   Case When IsNull(e.TypeCode, '') <> '' and  Isnull(d.State, '') <> '' then (e.TypeCode + '-'+  Upper(d.State))                                      
   When IsNull(e.TypeCode, '') <> '' and  Isnull(d.State, '') = '' then e.TypeCode                                       
   When IsNull(e.TypeCode, '') = '' and  Isnull(d.State, '') <> '' then Upper(d.State)                                      
   End As PlaceOfSupply,                                       
   Case When IsNull(d.GSTRegNo, '')<> '' Then 'N' Else 'Y' End As ReverseCharge, 'Regular' As TypeOfInvoice, '' As ECommerceGSTRegNo, c.TaxRate,                                      
   --Case When c.TaxName='IntraState' Then (@NoOfTaxRate * c.TaxRate) Else c.TaxRate End As CumTaxRate,                                      
   c1.ASSGVAmount As TaxableValue, c.CGSTTaxAmount, c.SGSTTaxAmount, c.IGSTTaxAmount, 0 As CessAmount, Case When a.CurrencyCode='INR' then 0 Else 1 End As IsImportPurchase,                             
   --g.HSNNo, e1.ItemCode, g.ItemDesc, h.ItemCount, g.PurchaseUOMDesc As UOMDesc, g.PurchaseUOMDecimal As UOMDecimal, isNull(SUM(e1.Qty),0) As InvoiceQty, isNull(e1.Rate, 0) As Rate,   isNull((SUM(e1.Qty)*e1.Rate), 0) As GoodsValue,                       
 
   g1.OtherTaxAmount, g2.RefNo, g2.RefDate, a.TranCompcode, a.Compcode                                 
   From DocList_CTE a                                       
   Left Outer Join InPutInvoiceList_CTE b                                      
   On a.TVID=b.TVID /*a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute */ and a.CompCode=b.CompCode                                      
   Left Outer join InPutTaxList_CTE  c                                      
   On a.TVID=c.TVID /*a.DocNo=c.DocNo and a.DocDate=c.DocDate and a.VrRoute=c.VrRoute */ and a.CompCode=c.CompCode                                      
   Left Outer join InPutGVTaxList_CTE c1                                      
   On a.TVID=c1.TVID /*a.DocNo=c1.DocNo and a.DocDate=c1.DocDate and a.VrRoute=c1.VrRoute*/ and a.CompCode=c1.CompCode                                      
   Left Outer join FAS_LrAddress_AuthTbl d                                      
   On b.LrCode=d.LrCode and b.CompCode=d.CompCode and d.AddressType in ('CL', 'CA')                                      
   Left Outer Join dbo.fn_Com_CountryCity_Master ('A',  @AsonDate, @RptDate, @BranchID, @CompID) e                                      
   On d.State=e.ChildName                     
   Left Outer Join FAS_VoucherMaster f                                  
   On a.VrRoute=f.VrRoute+f.VrWidth and a.CompCode=f.CompCode                       
   Left Outer Join InPutOtherTaxList_CTE g1                           
   On a.TVID=g1.TVID /*a.DocNo=g1.DocNo and a.DocDate=g1.DocDate and a.VrRoute=g1.VrRoute*/ and a.CompCode=g1.CompCode                
   Left Outer Join FAS_VoucherTranBills g2                           
   On a.TVID=g2.TVID  /*a.DocNo=g2.DocNo and a.DocDate=g2.DocDate and a.VrRoute=g2.VrRoute */ and a.CompCode=g2.CompCode               
                              
   /*  Left Outer Join PurchaseInvoice e1                                
    On e1.DocType=b.InvoiceType and e1.DocNo=b.InvoiceNo and e1.DocDate=b.InvoiceDate and Left(a.TranCompCode, 4)=(e1.CompID+e1.BranchID)                                
    OUTER APPLY fn_BOM_Get_Material_Master_Item('A', e1.ItemCode, @AsonDate, @RptDate, e1.BranchID, e1.CompID)g                                 
    Left Outer Join (Select DocType, DocNo, DocDate, count(ItemCode) As ItemCount, BranchID, CompID                             
   from PurchaseInvoice                            
   Where DocDate between @StartDate and @EndDate                            
   Group By DocType, DocNo, DocDate, BranchID, CompID                            
    )h                            
  On h.DocType=b.InvoiceType and h.DocNo=b.InvoiceNo and h.DocDate=b.InvoiceDate and Left(a.TranCompCode, 4)=(h.CompID+h.BranchID)                          
  */                             
   Where a.CompCode=Left(@CompCode, 4)                         
 /*Group By a.VrRoute, f.VoucherName, c.TaxName, b.LrCode, b.LedgerName, IsNull(d.GSTRegNo, ''), a.DocNo, a.DocDate, b.InvoiceType, b.InvoiceNo, b.InvoiceDate, a.InvoiceAmount,                                          
 e.TypeCode, d.State, d.GSTRegNo, c.TaxRate, c1.ASSGVAmount, c.CGSTTaxAmount, c.SGSTTaxAmount, c.IGSTTaxAmount, a.CurrencyCode, g.HSNNo, e1.ItemCode, g.ItemDesc, h.ItemCount,                     
 g.PurchaseUOMDesc, g.PurchaseUOMDecimal, e1.Rate,                          
 g1.OtherTaxAmount, a.TranCompCode, a.Compcode                      
 */                        
    --Order By b.InvoiceDate, b.InvoiceNo                                       
  )                                      
                                      
/*                                  
 --Select * From CTE_DocList                                                                          
 --Select * From InPutTaxLedger_CTE                                                                          
 --Select * From InPutTaxList_CTE                                                                         
 --Select * From InPutInvoiceList                                                                          
 --Select * From InPutGVTaxList_CTE                                      
 --Order by DocNo, DocDate                                                                          
*/                                      
                                      
 Insert into @GSTPurchaseTable                                          
   Select VrRoute, VoucherType, TaxName, LrCode, LedgerName, GSTRegNo, IsUnRegisterDealer, DocNo, DocDate, InvoiceType, InvoiceNo, InvoiceDate,                             
    --HSNNo, ItemCode, ItemDesc, ItemCount, UOMDesc, UOMDecimal, InvoiceQty, Rate, GoodsValue,                     
 InvoiceValue, IsNull(PlaceOfSupply, '') As PlaceOfSupply, ReverseCharge, TypeOfInvoice, ECommerceGSTRegNo,  IsNull(TaxRate, 0) As TaxRate, Abs(IsNull(TaxableValue, 0)) As TaxableValue,                                
    Abs(IsNull(CGSTTaxAmount, 0)) As CGSTTaxAmount, Abs(IsNull(SGSTTaxAmount, 0)) As SGSTTaxAmount, Abs(IsNull(IGSTTaxAmount, 0)) As IGSTTaxAmount, Abs(IsNull(OtherTaxAmount, 0)) As OtherTaxAmount,                           
    CessAmount, IsImportPurchase, RefNo, RefDAte, TranCompCode, CompCode                                     
   From INPutGSTR_CTE                    
*/                                        
  RETURN;                                                                                  
END  
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Rpt_GST_Sales]    Script Date: 17/06/2026 11:38:45 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Rpt_GST_Sales](@StartDate datetime, @EndDate datetime, @AsonDate datetime, 
@RptDate datetime, @CompCode Varchar(12))                      
             
RETURNS @GSTSalesTable TABLE                       
 (                      
  VrRoute varchar(42),                     
  VoucherType varchar(50),                    
  TaxName varchar(20),                     
  LrCode int,                     
  LedgerName varchar(50),                     
  GSTRegNo varchar(20),                     
  DocNo int ,                     
  DocDate datetime,                       
  InvoiceType varchar(3),                     
  InvoiceNo int,                     
  InvoiceDate datetime,                   
  --HSNNO varchar(10),              
  --ItemCode Varchar(20),               
  --ItemDesc Varchar(50),               
  --ItemCount int,                 
  --UOMDesc Varchar(50),              
  --UOMDecimal int,               
  --InvoiceQty Float,              
  --Rate Float,        
  --GoodsValue money,               
  InvoiceValue money,                     
  PlaceOfSupply varchar(60),                     
  ReverseCharge Char(1),                     
  TypeOfInvoice varchar(50),                     
  ECommerceGSTRegNo varchar(20),                     
  TaxRate money,                     
  TaxableValue money,                   
  CGSTTAxAmount money,                           
  SGSTTAxAmount money,                           
  IGSTTAxAmount money,          
  OtherTaxAmount money,                  
  CessAmount money,                     
  IsExportSales bit,                    
  TranCompCode varchar(12) ,                    
  CompCode varchar(12)                     
 )                        
                                                
BEGIN                                                        
                      
  /* We can Take Report for B2B, B2Cl, B2Cs, CDNR, CDNUR, EXP using this procedure */                    
                    
                     
                    
  /* Help */                    
  /* VrRoute    : Sales = '0K', CreditNote = '02', DebitNote = '03' */                    
  /* LedgerRoute: Sales = '0206', Purchase = '0303' */                    
  /* Sales   : GroupFlg='OUTPUT'*/                    
  /* TaxName   : WithInState = Intrastate, OtherState = Interstate */                    
  /* Posting Ledger for Tax : TypeFlg='Tax' */                    
  /* Posting Ledger for GoodsValue :  TypeFlg='AVGV' */                    
  /* CGST + SGST called as IntraState. So @NoOfTaxRate multiply into two to show the Cumulative TaxRate in Report */                    
                    
  Declare @NoofTaxRate int                    
  SET @NoofTaxRate=2                     
         
  Declare @CompID as Varchar(3)                    
  Declare @BranchID as Varchar(3)                            
   Set @CompID=Left(@CompCode, 2);                    
   Set @BranchID=Substring(@CompCode, 3, 2);                    
                    
                                    
 ; With DocList_CTE (VrRoute, DocNo, DocDate, InvoiceAmount, CurrencyCode, TranCompCode, CompCode)                    
 As                    
  (                    
   Select a.VrRoute, a.DocNo, a.DocDate, a.Amount as InvoiceAmount, 'INR' as CurrencyCode, a.CompCode as TranCompCode, a.CompCode                    
   From FAS_VoucherTranMast a                        
   Where a.CompCode=Left(@CompCode, 4) and (a.DocDate Between @StartDate and @EndDate)                     
    and (a.VrRoute Like '0K%' OR a.VrRoute Like '02%' OR a.VrRoute Like '03%') and a.isCancelled='0'                    
  )                    
                    
 , OutPutInvoiceList_CTE (VrRoute, DocNo, DocDate, LrRoute, LrCode, LedgerName, InvoiceType, InvoiceNo, InvoiceDate, CompCode)                    
 As                    
  (   
   Select a.VrRoute, a.DocNo, a.DocDate, b.LrRoute,  b.LedgerCode as LrCode, b.LedgerName,  c.RefType, c.RefNo, c.RefDate, a.CompCode                     
   From DocList_CTE a                    
   Left Outer Join                     
    (  
     Select b2.LrRoute, b2.LedgerCode, b2.LedgerName, c2.DocNo, c2.DocDate, c2.VrRoute, b2.CompCode                  
     From FAS_LedgerMaster_AuthTbl b2                       
     Inner Join FAS_VoucherTranSub c2                      
     On b2.LedgerCode=c2.LrCode and b2.CompCode=c2.CompCode  and (c2.VrRoute Like '0K%' OR c2.VrRoute Like '02%' OR c2.VrRoute Like '03%')                    
     Where (b2.LrRoute like '0206%' OR b2.LrRoute like '0303%') and b2.CompCode=Left(@CompCode, 4) and (c2.DocDate between @StartDate and @EndDate)                   
    ) b                      
    On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode                    
   Left Outer Join FAS_VoucherTranRef c                    
    On a.DocNo=c.DocNo and a.DocDate=c.DocDate and a.VrRoute=c.VrRoute  and a.CompCode=c.CompCode                    
  )                    
                       
 , OutPutTaxLedger_CTE(TaxLrCode, TaxName, TaxRate, TypeFlg, CompCode)              
 AS                      
  (                      
   Select LrCode as TaxLrCode, TaxName, TaxRate, TypeFlg, CompCode                    
   From FAS_LedgerMaster_Tax                       
   Where CompCode=@CompCode and GroupFlg='OUTPUT'                       
  )                      
                     
 , OutPutTaxList_CTE(VrRoute, DocNo, DocDate, TaxName, TaxRate, CGSTTaxAmount, SGSTTaxAmount, IGSTTaxAmount, CompCode)                      
 AS                      
 (                        
  Select VrRoute, DocNo, DocDate, TaxName, Sum(TaxRate) as TaxRate, Sum(CGSTTaxAmount) as CGSTTaxAmount, Sum(SGSTTaxAmount) as SGSTTaxAmount, Sum(IGSTTaxAmount) as IGSTTaxAmount, CompCode                        
  From                         
   (                        
    Select distinct s1.VrRoute, s1.DocNo, s1.DocDate,  --s1.VTSNo as TaxVTSNo, s2.TaxLrCode,                         
     Case When s2.TaxName in ('CGST', 'SGST') Then 'IntraState' Else 'InterState' End as TaxName, s2.TaxRate,                         
     --Sum(s2.TaxRate) as TaxRate,                         
     Case s2.TaxName When 'CGST' then (s1.DrAmt-s1.CrAmt) Else 0 End As CGSTTaxAmount,                            
     Case s2.TaxName When 'SGST' then (s1.DrAmt-s1.CrAmt) Else 0 End As SGSTTaxAmount,                            
     Case s2.TaxName When 'IGST' then (s1.DrAmt-s1.CrAmt) Else 0 End As IGSTTaxAmount, s1.CompCode                           
    From FAS_VoucherTranSub s1                                
    Left Outer Join OutPutInvoiceList_CTE s3                          
     On s3.DocNo=s1.DocNo and s3.DocDate=s1.DocDate and s3.VrRoute=s1.VrRoute and s3.CompCode=s1.CompCode                            
    Inner Join OutPutTaxLedger_CTE s2   
     On s2.TaxLrCode=s1.LrCode and s2.TypeFlg='Tax'  and s2.CompCode=s1.CompCode                          
    Where s1.CompCode=Left(@CompCode, 4) and (s1.DocDate Between @StartDate and @EndDate) and s1.LrCode<>s3.LrCode                          
     and (s1.VrRoute Like '0K%' OR s1.VrRoute Like '02%' OR s1.VrRoute Like '03%')                          
    --Group By s1.VrRoute, s1.DocNo, s1.DocDate,  s2.TaxName, s1.CrAmt, s1.DrAmt, s1.CompCode                          
   )x                           
  Group By VrRoute, DocNo, DocDate,  TaxName,  CompCode                                                     
 )                    
                 
  , OutPutGVTaxList_CTE(VrRoute, DocNo, DocDate, ASSGVAmount, CompCode)                            
 AS                            
 (                        
  Select distinct s1.VrRoute, s1.DocNo, s1.DocDate, Sum(s1.CrAmt-s1.DrAmt) as ASSGVAmount, s1.CompCode                           
  From FAS_VoucherTranSub s1                                
  Left Outer Join OutPutInvoiceList_CTE s3                          
   On s3.DocNo=s1.DocNo and s3.DocDate=s1.DocDate and s3.VrRoute=s1.VrRoute and s3.CompCode=s1.CompCode            
  Where s1.VTSNo<   
   (  
    Select  Min(l.VTSNo)   
    From FAS_VoucherTranSub a                      
    Outer Apply   
     (  
      Select DocNo, DocDate, VrRoute, VTSNo, CompCode   
      From FAS_VoucherTranSub n   
      Where a.LrCode=n.LrCode and a.DocNo=n.DocNo and a.DocDate=n.DocDate and a.VrRoute=n.VrRoute and a.Compcode=n.CompCode                       
       and Exists (Select * From OutPutTaxLedger_CTE m Where TypeFlg='Tax' and m.TaxLrCode=n.LrCode and m.CompCode=n.CompCode)                      
      --Group By n.DocNo, n.DocDate, n.VrRoute, n.CompCode                      
     )l                      
    Where s1.DocNo=l.DocNo and s1.DocDate=l.DocDate and s1.VrRoute=l.VrRoute and s1.Compcode=l.CompCode                       
   )                      
   and s1.CompCode=Left(@CompCode, 4) and (s1.DocDate Between @StartDate and @EndDate) and s1.LrCode<>s3.LrCode                          
   and (s1.VrRoute Like '0K%' OR s1.VrRoute Like '02%' OR s1.VrRoute Like '03%')                         
  Group By s1.DocNo, s1.DocDate, s1.VrRoute, s1.CompCode                        
 )                      
          
  /* Assumed VTSNo 1 = Party Amount, VTSNo2 = TaxableValue, OtherTaxAmount fetched except GoodsValue and Tax i.e., Freight, Insurance and Packing and forwarding Whatever parameter taken for calculating tax portion expect Party, GoodsValue and Tax Ledgers 
  
   
   
 For HSN Summary Itemwise Report */          
  , OutPutOtherTaxList_CTE(VrRoute, DocNo, DocDate, OtherTaxAmount, CompCode)                            
 AS                            
 (                        
   Select distinct s1.VrRoute, s1.DocNo, s1.DocDate, Sum(s1.CrAmt-s1.DrAmt) as OtherTaxAmount, s1.CompCode                           
   From FAS_VoucherTranSub s1                                
   Left Outer Join OutPutInvoiceList_CTE s3                          
    On s3.DocNo=s1.DocNo and s3.DocDate=s1.DocDate and s3.VrRoute=s1.VrRoute and s3.CompCode=s1.CompCode                        
   Where s1.VTSNo>2 and s1.VTSNo< (  
           Select  Min(l.VTSNo) From FAS_VoucherTranSub a           
           Outer Apply   
            (  
             Select DocNo, DocDate, VrRoute, VTSNo, CompCode   
             From FAS_VoucherTranSub n   
             Where a.LrCode=n.LrCode and a.DocNo=n.DocNo and a.DocDate=n.DocDate and a.VrRoute=n.VrRoute and a.Compcode=n.CompCode                       
             and Exists   
              (  
               Select * From OutPutTaxLedger_CTE m Where TypeFlg='Tax' and m.TaxLrCode=n.LrCode and m.CompCode=n.CompCode  
              )                      
              --Group By n.DocNo, n.DocDate, n.VrRoute, n.CompCode                
            )l                      
            Where s1.DocNo=l.DocNo and s1.DocDate=l.DocDate and s1.VrRoute=l.VrRoute and s1.Compcode=l.CompCode                       
           )                      
   and s1.CompCode=Left(@CompCode, 4) and (s1.DocDate Between @StartDate and @EndDate) and s1.LrCode<>s3.LrCode                          
   and (s1.VrRoute Like '0K%' OR s1.VrRoute Like '02%' OR s1.VrRoute Like '03%')                         
  Group By s1.DocNo, s1.DocDate, s1.VrRoute, s1.CompCode                        
 )                        
                 
 , OutPutGSTR_CTE (VrRoute, VoucherType, TaxName,  LrCode, LedgerName, GSTRegNo, DocNo, DocDate, InvoiceType, InvoiceNo, InvoiceDate, InvoiceValue, PlaceOfSupply, ReverseCharge, TypeOfInvoice, ECommerceGSTRegNo, TaxRate,     
 TaxableValue, CGSTTaxAmount, SGSTTaxAmount, IGSTTaxAmount, CessAmount, IsExportSales,OtherTaxAmount, TranCompCode, Compcode)                    
 As                    
 (                    
  Select a.VrRoute, f1.VoucherName as VoucherType, c.TaxName, b.LrCode, b.LedgerName, IsNull(d.GSTRegNo, '') as GSTRegNo, a.DocNo, a.DocDate, b.InvoiceType, b.InvoiceNo, b.InvoiceDate, a.InvoiceAmount as InvoiceValue,                    
   Case When IsNull(e.TypeCode, '') <> '' and  Isnull(d.State, '') <> '' then (e.TypeCode + '-'+  Upper(d.State))                    
   When IsNull(e.TypeCode, '') <> '' and  Isnull(d.State, '') = '' then e.TypeCode                     
   When IsNull(e.TypeCode, '') = '' and  Isnull(d.State, '') <> '' then Upper(d.State)                    
   End as PlaceOfSupply,                     
   Case When IsNull(d.GSTRegNo, '')<> '' Then 'N' Else 'Y' End as ReverseCharge, 'Regular' as TypeOfInvoice, '' as ECommerceGSTRegNo,  IsNull(c.TaxRate, 1) as TaxRate,                     
   --Case When c.TaxName='IntraState' Then (@NoOfTaxRate * c.TaxRate) Else c.TaxRate End as CumTaxRate,                    
   c1.ASSGVAmount as TaxableValue,  c.CGSTTaxAmount, c.SGSTTaxAmount, c.IGSTTaxAmount, 0 as CessAmount, Case When a.CurrencyCode='INR' then 0 Else 1 End as IsExportSales,               
   --f.HSNNo, e1.ItemCode, f.ItemDesc, h.ItemCount, f.UOMDesc, f.UOMDecimal, isNull(SUM(e1.InvoiceQty),0) As InvoiceQty, isNull(e1.Rate, 0) as Rate, isNull((SUM(e1.InvoiceQty)*e1.Rate), 0) as GoodsValue,    
   g.OtherTaxAmount, a.TranCompcode, a.Compcode             
           
  From DocList_CTE a                     
  Left Outer Join OutPutInvoiceList_CTE b                    
   On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode                    
  Left Outer join OutPutTaxList_CTE  c                    
   On a.DocNo=c.DocNo and a.DocDate=c.DocDate and a.VrRoute=c.VrRoute and a.CompCode=c.CompCode                    
  Left Outer join OutPutGVTaxList_CTE c1                    
   On a.DocNo=c1.DocNo and a.DocDate=c1.DocDate and a.VrRoute=c1.VrRoute and a.CompCode=c1.CompCode                    
  Left Outer join FAS_LrAddress d                    
   On b.LrCode=d.LrCode and b.CompCode=d.CompCode                    
  Left Outer Join dbo.fn_Com_CountryCity_Master ('A',  @AsonDate, @RptDate, @BranchID, @CompID) e                    
   On d.State=e.ChildName and e.ParentCode<>0  
   and e.ParentCode NOT IN     
   (  
    Select ChildCode   
    From fn_COM_CountryCity_MAster('A', @AsOnDate, @RptDate, @BranchID, @CompID)   
    Where ParentCode <> 0 and ParentCode<>e.ChildCode  
   )       
                      
  Left Outer Join FAS_VoucherMaster f1                    
   On a.VrRoute=f1.VrRoute+f1.VrWidth and a.CompCode=f1.CompCode       
  Left Outer Join OutPutOtherTaxList_CTE g        
   On a.DocNo=g.DocNo and a.DocDate=g.DocDate and a.VrRoute=g.VrRoute and a.CompCode=g.CompCode       
  Where a.CompCode=Left(@CompCode, 4)                    
 )                 
             
                     
 /*Select * From CTE_DocList                    
                    
 Select * From OutPutTaxLedger_CTE                    
                    
 Select * From OutPutTaxList_CTE                    
                    
 Select * From OutPutInvoiceList                    
                    
 Select * From OutPutGVTaxList_CTE                    
 Order by DocNo, DocDate  */                  
                   
                    
 Insert into @GSTSalesTable                      
  Select VrRoute,  VoucherType, TaxName, LrCode, LedgerName, GSTRegNo, DocNo, DocDate, InvoiceType, InvoiceNo, InvoiceDate, --HSNNo, ItemCode, ItemDesc, ItemCount, UOMDesc, UOMDecimal, InvoiceQty, Rate, GoodsValue,           
   IsNull(InvoiceValue, 0) as InvoiceValue, PlaceOfSupply, ReverseCharge, TypeOfInvoice, ECommerceGSTRegNo, IsNull(TaxRate, 0) as TaxRate, Abs(IsNull(TaxableValue, 0)) as TaxableValue,             
   Abs(IsNull(CGSTTaxAmount, 0)) as CGSTTaxAmount, Abs(IsNull(SGSTTaxAmount, 0)) as SGSTTaxAmount, Abs(IsNull(IGSTTaxAmount, 0)) as IGSTTaxAmount, Abs(IsNull(OtherTaxAmount, 0)) as OtherTaxAmount,        
   CessAmount, IsExportSales, TranCompCode, CompCode                        
  From OutPutGSTR_CTE                        
                        
 RETURN;                                                  
END     
           
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Rpt_GST_Sales_tmp]    Script Date: 17/06/2026 11:38:46 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Rpt_GST_Sales_tmp](@StartDate datetime, @EndDate datetime, @AsonDate datetime,   
	@RptDate datetime, @CompCode Varchar(12))                        
RETURNS @GSTSalesTable TABLE                         
	(                        
		VrRoute varchar(42),                       
		VoucherType varchar(50),                      
		TaxName varchar(20),                       
		LrCode int,                       
		LedgerName varchar(50),                       
		GSTRegNo varchar(20),                       
		DocNo int ,                       
		DocDate datetime,                         
		InvoiceType varchar(3),                       
		InvoiceNo int,                       
		InvoiceDate datetime,                     
		--HSNNO varchar(10),                
		--ItemCode Varchar(20),                 
		--ItemDesc Varchar(50),                 
		--ItemCount int,                   
		--UOMDesc Varchar(50),                
		--UOMDecimal int,                 
		--InvoiceQty Float,                
		--Rate Float,          
		--GoodsValue money,                 
		InvoiceValue money,                       
		PlaceOfSupply varchar(60),                       
		ReverseCharge Char(1),                       
		TypeOfInvoice varchar(50),                       
		ECommerceGSTRegNo varchar(20),                       
		TaxRate money,                       
		TaxableValue money,                     
		CGSTTAxAmount money,                             
		SGSTTAxAmount money,                             
		IGSTTAxAmount money,            
		OtherTaxAmount money,                    
		CessAmount money,                       
		IsExportSales bit,                      
		TranCompCode varchar(12) ,                      
		CompCode varchar(12)                       
	)                          
BEGIN                                                          
                        
  /* We can Take Report for B2B, B2Cl, B2Cs, CDNR, CDNUR, EXP using this procedure */                      
                      
  /* Help */                      
  /* VrRoute    : Sales = '0K', CreditNote = '02', DebitNote = '03' */                      
  /* LedgerRoute: Sales = '0206', Purchase = '0303' */                      
  /* Sales   : GroupFlg='OUTPUT'*/                      
  /* TaxName   : WithInState = Intrastate, OtherState = Interstate */                      
  /* Posting Ledger for Tax : TypeFlg='Tax' */                      
  /* Posting Ledger for GoodsValue :  TypeFlg='AVGV' */                      
  /* CGST + SGST called as IntraState. So @NoOfTaxRate multiply into two to show the Cumulative TaxRate in Report */                      
                      
  Declare @NoofTaxRate int                      
  SET @NoofTaxRate=2                       
           
  Declare @CompID as Varchar(3), @BranchID as Varchar(3), @CompCodeCurrent as varchar(4);                              
   Set @CompID=Left(@CompCode, 2);                      
   Set @BranchID=Substring(@CompCode, 3, 2);
	 Set @CompCodeCurrent = Left(@CompCode, 4);
                      
                                      
	; With DocList_CTE (VrRoute, DocNo, DocDate, InvoiceAmount, CurrencyCode, TranCompCode, CompCode)                      
	As                      
	(                      
		Select a.VrRoute, a.DocNo, a.DocDate, a.Amount as InvoiceAmount, 'INR' as CurrencyCode, a.CompCode as TranCompCode, a.CompCode                      
		From FAS_VoucherTranMast a                          
		Where (a.DocDate Between @StartDate and @EndDate) and a.CompCode=@CompCodeCurrent            
			and (a.VrRoute Like '0K%' OR a.VrRoute Like '02%' OR a.VrRoute Like '03%') and a.isCancelled='0'                      
	)                      
                      
	, OutPutInvoiceList_CTE (VrRoute, DocNo, DocDate, LrRoute, LrCode, LedgerName, InvoiceType, InvoiceNo, InvoiceDate, CompCode)                      
	As                      
	(     
		Select a.VrRoute, a.DocNo, a.DocDate, b.LrRoute,  b.LedgerCode as LrCode, b.LedgerName,  c.RefType, c.RefNo, c.RefDate, a.CompCode                       
		From DocList_CTE a                      
		Left Outer Join                       
		(    
			Select b2.LrRoute, b2.LedgerCode, b2.LedgerName, c2.DocNo, c2.DocDate, c2.VrRoute, b2.CompCode                    
			From FAS_LedgerMaster_AuthTbl b2                         
			Inner Join FAS_VoucherTranSub c2                        
				On b2.LedgerCode=c2.LrCode and (c2.DocDate between @StartDate and @EndDate) and b2.CompCode=c2.CompCode 
					and (b2.LrRoute like '0206%' OR b2.LrRoute like '0303%') 
					and (c2.VrRoute Like '0K%' OR c2.VrRoute Like '02%' OR c2.VrRoute Like '03%')                      
					and b2.CompCode=@CompCodeCurrent                     
		) b                        
			On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode                      
		Left Outer Join FAS_VoucherTranRef c                      
			On a.DocNo=c.DocNo and a.DocDate=c.DocDate and a.VrRoute=c.VrRoute  and a.CompCode=c.CompCode                      
	)                      
                         
	, OutPutTaxLedger_CTE(TaxLrCode, TaxName, TaxRate, TypeFlg, CompCode)                
	AS                        
	(                        
		Select LrCode as TaxLrCode, TaxName, TaxRate, TypeFlg, CompCode                      
		From FAS_LedgerMaster_Tax                         
		Where CompCode=@CompCodeCurrent and GroupFlg='OUTPUT'                         
	)                        
                       
	, OutPutTaxList_CTE(VrRoute, DocNo, DocDate, TaxName, TaxRate, CGSTTaxAmount, SGSTTaxAmount, IGSTTaxAmount, CompCode)                        
	AS                        
	(                          
		Select VrRoute, DocNo, DocDate, TaxName, Sum(TaxRate) as TaxRate, 
			Sum(CGSTTaxAmount) as CGSTTaxAmount, Sum(SGSTTaxAmount) as SGSTTaxAmount, 
			Sum(IGSTTaxAmount) as IGSTTaxAmount, CompCode                          
		From                           
		(                          
			Select distinct s1.VrRoute, s1.DocNo, s1.DocDate,  --s1.VTSNo as TaxVTSNo, s2.TaxLrCode,                           
				Case When s2.TaxName in ('CGST', 'SGST') Then 'IntraState' Else 'InterState' End as TaxName, s2.TaxRate,                           
				--Sum(s2.TaxRate) as TaxRate,                           
				Case s2.TaxName When 'CGST' then (s1.DrAmt-s1.CrAmt) Else 0 End As CGSTTaxAmount,                              
				Case s2.TaxName When 'SGST' then (s1.DrAmt-s1.CrAmt) Else 0 End As SGSTTaxAmount,                              
				Case s2.TaxName When 'IGST' then (s1.DrAmt-s1.CrAmt) Else 0 End As IGSTTaxAmount, s1.CompCode                             
			From FAS_VoucherTranSub s1                                  
			Left Outer Join OutPutInvoiceList_CTE s3                            
				On s3.DocNo=s1.DocNo and s3.DocDate=s1.DocDate and s3.VrRoute=s1.VrRoute and s3.CompCode=s1.CompCode                              
			Inner Join OutPutTaxLedger_CTE s2     
				On s2.TaxLrCode=s1.LrCode and s2.TypeFlg='Tax'  and s2.CompCode=s1.CompCode                            
			Where (s1.DocDate Between @StartDate and @EndDate) and s1.LrCode<>s3.LrCode 
				and (s1.VrRoute Like '0K%' OR s1.VrRoute Like '02%' OR s1.VrRoute Like '03%')
				and s1.CompCode=@CompCodeCurrent
			--Group By s1.VrRoute, s1.DocNo, s1.DocDate,  s2.TaxName, s1.CrAmt, s1.DrAmt, s1.CompCode                            
		)x                             
		Group By VrRoute, DocNo, DocDate,  TaxName,  CompCode                                                       
	)                      
                   
	, OutPutGVTaxList_CTE(VrRoute, DocNo, DocDate, ASSGVAmount, CompCode)                              
	AS                              
	(                          
		Select distinct s1.VrRoute, s1.DocNo, s1.DocDate, Sum(s1.CrAmt-s1.DrAmt) as ASSGVAmount, s1.CompCode               
		From FAS_VoucherTranSub s1                                  
		Left Outer Join OutPutInvoiceList_CTE s3                            
			On s3.DocNo=s1.DocNo and s3.DocDate=s1.DocDate and s3.VrRoute=s1.VrRoute and s3.CompCode=s1.CompCode              
		Where s1.VTSNo<     
		(    
			Select  Min(l.VTSNo)     
			From FAS_VoucherTranSub a                        
			Outer Apply     
			(    
				Select DocNo, DocDate, VrRoute, VTSNo, CompCode     
				From FAS_VoucherTranSub n     
				Where a.DocNo=n.DocNo and a.DocDate=n.DocDate and a.VrRoute=n.VrRoute and a.LrCode=n.LrCode and a.Compcode=n.CompCode                         
					and Exists (Select * From OutPutTaxLedger_CTE m Where TypeFlg='Tax' and m.TaxLrCode=n.LrCode and m.CompCode=n.CompCode)                        
				--Group By n.DocNo, n.DocDate, n.VrRoute, n.CompCode                        
			)l                        
			Where s1.DocNo=l.DocNo and s1.DocDate=l.DocDate and s1.VrRoute=l.VrRoute and s1.Compcode=l.CompCode                         
		)                        
			and (s1.DocDate Between @StartDate and @EndDate) and s1.LrCode<>s3.LrCode                            
			and (s1.VrRoute Like '0K%' OR s1.VrRoute Like '02%' OR s1.VrRoute Like '03%')
			and s1.CompCode=@CompCodeCurrent
		Group By s1.DocNo, s1.DocDate, s1.VrRoute, s1.CompCode                          
	)                        
            
  /* Assumed VTSNo 1 = Party Amount, VTSNo2 = TaxableValue, OtherTaxAmount fetched except GoodsValue and Tax i.e., Freight, Insurance and Packing and forwarding Whatever parameter taken for calculating tax portion expect Party, GoodsValue and Tax Ledgers
   
     
	For HSN Summary Itemwise Report */            
	, OutPutOtherTaxList_CTE(VrRoute, DocNo, DocDate, OtherTaxAmount, CompCode)                              
	AS                              
	(                          
		Select distinct s1.VrRoute, s1.DocNo, s1.DocDate, Sum(s1.CrAmt-s1.DrAmt) as OtherTaxAmount, s1.CompCode                             
		From FAS_VoucherTranSub s1                                  
		Left Outer Join OutPutInvoiceList_CTE s3                            
			On s3.DocNo=s1.DocNo and s3.DocDate=s1.DocDate and s3.VrRoute=s1.VrRoute and s3.CompCode=s1.CompCode                          
		Where s1.VTSNo>2 and s1.VTSNo < (    
			Select  Min(l.VTSNo) From FAS_VoucherTranSub a             
			Outer Apply     
			(    
				Select DocNo, DocDate, VrRoute, VTSNo, CompCode     
				From FAS_VoucherTranSub n     
				Where a.LrCode=n.LrCode and a.DocNo=n.DocNo and a.DocDate=n.DocDate and a.VrRoute=n.VrRoute and a.Compcode=n.CompCode                         
					and Exists     
					(    
						Select * From OutPutTaxLedger_CTE m Where TypeFlg='Tax' and m.TaxLrCode=n.LrCode and m.CompCode=n.CompCode    
					)                        
				--Group By n.DocNo, n.DocDate, n.VrRoute, n.CompCode                  
			)l                        
			Where s1.DocNo=l.DocNo and s1.DocDate=l.DocDate and s1.VrRoute=l.VrRoute and s1.Compcode=l.CompCode                         
		)                        
			and (s1.DocDate Between @StartDate and @EndDate) and s1.LrCode<>s3.LrCode                            
			and (s1.VrRoute Like '0K%' OR s1.VrRoute Like '02%' OR s1.VrRoute Like '03%')
			and s1.CompCode=@CompCodeCurrent 
		Group By s1.DocNo, s1.DocDate, s1.VrRoute, s1.CompCode                          
	)                          
                   
	, OutPutGSTR_CTE (VrRoute, VoucherType, TaxName,  LrCode, LedgerName, GSTRegNo, DocNo, DocDate, InvoiceType, InvoiceNo, InvoiceDate, InvoiceValue, PlaceOfSupply, ReverseCharge, TypeOfInvoice, ECommerceGSTRegNo, TaxRate,       
		TaxableValue, CGSTTaxAmount, SGSTTaxAmount, IGSTTaxAmount, CessAmount, IsExportSales,OtherTaxAmount, TranCompCode, Compcode)                      
	As             
	(                      
		Select a.VrRoute, f1.VoucherName as VoucherType, c.TaxName, b.LrCode, b.LedgerName, IsNull(d.GSTRegNo, '') as GSTRegNo, a.DocNo, a.DocDate, b.InvoiceType, b.InvoiceNo, b.InvoiceDate, a.InvoiceAmount as InvoiceValue,                      
			Case When IsNull(e.TypeCode, '') <> '' and  Isnull(d.State, '') <> '' then (e.TypeCode + '-'+  Upper(d.State))                      
			When IsNull(e.TypeCode, '') <> '' and  Isnull(d.State, '') = '' then e.TypeCode                       
			When IsNull(e.TypeCode, '') = '' and  Isnull(d.State, '') <> '' then Upper(d.State)                      
			End as PlaceOfSupply,                       
			Case When IsNull(d.GSTRegNo, '')<> '' Then 'N' Else 'Y' End as ReverseCharge, 'Regular' as TypeOfInvoice, '' as ECommerceGSTRegNo,  IsNull(c.TaxRate, 1) as TaxRate,                       
			--Case When c.TaxName='IntraState' Then (@NoOfTaxRate * c.TaxRate) Else c.TaxRate End as CumTaxRate,                      
			c1.ASSGVAmount as TaxableValue,  c.CGSTTaxAmount, c.SGSTTaxAmount, c.IGSTTaxAmount, 0 as CessAmount, Case When a.CurrencyCode='INR' then 0 Else 1 End as IsExportSales,                 
			--f.HSNNo, e1.ItemCode, f.ItemDesc, h.ItemCount, f.UOMDesc, f.UOMDecimal, isNull(SUM(e1.InvoiceQty),0) As InvoiceQty, isNull(e1.Rate, 0) as Rate, isNull((SUM(e1.InvoiceQty)*e1.Rate), 0) as GoodsValue,      
			g.OtherTaxAmount, a.TranCompcode, a.Compcode               
             
		From DocList_CTE a                       
		Left Outer Join OutPutInvoiceList_CTE b                      
			On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode                      
		Left Outer join OutPutTaxList_CTE  c                      
			On a.DocNo=c.DocNo and a.DocDate=c.DocDate and a.VrRoute=c.VrRoute and a.CompCode=c.CompCode                      
		Left Outer join OutPutGVTaxList_CTE c1                      
			On a.DocNo=c1.DocNo and a.DocDate=c1.DocDate and a.VrRoute=c1.VrRoute and a.CompCode=c1.CompCode                      
		Left Outer join FAS_LrAddress d                      
			On b.LrCode=d.LrCode and b.CompCode=d.CompCode                      
		Left Outer Join dbo.fn_Com_CountryCity_Master ('A',  @AsonDate, @RptDate, @BranchID, @CompID) e                      
			On d.State=e.ChildName and e.ParentCode<>0    
				and e.ParentCode NOT IN       
				(    
					Select ChildCode     
					From fn_COM_CountryCity_MAster('A', @AsOnDate, @RptDate, @BranchID, @CompID)     
					Where ParentCode <> 0 and ParentCode<>e.ChildCode    
				)         
                        
		Left Outer Join FAS_VoucherMaster f1                      
			On a.VrRoute=f1.VrRoute+f1.VrWidth and a.CompCode=f1.CompCode         
		Left Outer Join OutPutOtherTaxList_CTE g          
			On a.DocNo=g.DocNo and a.DocDate=g.DocDate and a.VrRoute=g.VrRoute and a.CompCode=g.CompCode         
		Where a.CompCode=@CompCodeCurrent                      
	)                   
               
                       
 /*Select * From CTE_DocList                      
                      
 Select * From OutPutTaxLedger_CTE                      
                      
 Select * From OutPutTaxList_CTE                      
                      
 Select * From OutPutInvoiceList                      
                      
 Select * From OutPutGVTaxList_CTE                      
 Order by DocNo, DocDate  */                    
                     
                      
	Insert into @GSTSalesTable                        
	Select VrRoute,  VoucherType, TaxName, LrCode, LedgerName, GSTRegNo, DocNo, DocDate, InvoiceType, InvoiceNo, InvoiceDate, --HSNNo, ItemCode, ItemDesc, ItemCount, UOMDesc, UOMDecimal, InvoiceQty, Rate, GoodsValue,             
		IsNull(InvoiceValue, 0) as InvoiceValue, PlaceOfSupply, ReverseCharge, TypeOfInvoice, ECommerceGSTRegNo, IsNull(TaxRate, 0) as TaxRate, Abs(IsNull(TaxableValue, 0)) as TaxableValue,               
		Abs(IsNull(CGSTTaxAmount, 0)) as CGSTTaxAmount, Abs(IsNull(SGSTTaxAmount, 0)) as SGSTTaxAmount, Abs(IsNull(IGSTTaxAmount, 0)) as IGSTTaxAmount, Abs(IsNull(OtherTaxAmount, 0)) as OtherTaxAmount,          
		CessAmount, IsExportSales, TranCompCode, CompCode                          
	From OutPutGSTR_CTE                          
                          
	RETURN;                                                    
END       
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Rpt_Outstanding_Detail]    Script Date: 17/06/2026 11:38:46 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE function [dbo].[fn_FAS_Rpt_Outstanding_Detail] (@UserKey varchar(36), @RptType Char(1), @RptDate Datetime, @Start datetime, @End datetime, @Status varchar(2),  @CmCode varchar(12)) 
-- 'C' for Credit Balance Bills Only; 'D' for Debit Balance Bills Only, Other for All Bills
Returns @RetTable Table
 ( DocNo   int,
  DocDate  datetime,
  BillIndex  int,
  RefNo   Varchar(50), 
  RefDate datetime,  
  LrCode  int,
  LrRoute  Varchar(42),
  VrRoute  Varchar(42),
  VrName   Varchar(50),  
  InitialAmt  money,
  BalanceAmt  money,
  DueDate datetime,
  OverDue int)
  
AS

Begin 
 
 Declare @BranchID varchar(2)
 Select @BranchID = substring(@CmCode, 3, 2)

 Declare @CompID varchar(2)
 Select @CompID = Left(@CmCode, 2)

 Declare @From datetime, @To datetime
 Select @From=Case Left(@Status, 1) when '0' then (Select Min(Refdate) from Fas_BillDetails where CompCode=@CmCode and DocDate<=@RptDate) Else @Start End 
 Select @To=Case Right(@Status, 1) when '0' then (Select Max(Refdate) from Fas_BillDetails where CompCode=@CmCode and DocDate<=@RptDate) Else @End End
 If @To > @RptDate
	SET @To=@RptDate
 
 Insert into @RetTable

  Select 0, n.DocDate, 0, n.RefNo, Null, n.LrCode, r.LrRoute, '',  '',  0, n.BalanceAmt, Null, Null   
  from
   (Select m.LrCode, m.RefNo, m.BalanceAmt, 
     (Select Min(DocDate) from FAS_BillDetails m1 
     Where m1.RefNo=m.RefNo and m1.LrCode=m.LrCode and m1.CompCode=@CmCode) as DocDate
   from
    (Select a.LrCode, a.RefNo, Sum(a.Amount)as BalanceAmt
    from fas_billdetails a 
    Where a.LrCode in (Select selectInt From Com_SelectList Where UserKey = @UserKey
           and BranchID = @BranchID and CompID = @CompID) 
     and a.Type <> 'On Acct' and a.DocDate <= @RptDate and a.CompCode=@CmCode
    group by a.LrCode, a.RefNo 
    having Sum(a.Amount)<>0
    ) m
   ) n
   Left Outer Join Fas_LedgerMaster r
    On n.LrCode=r.LedgerCode and r.CompCode=@CmCode

 
 if @RptType = 'C' -- Credit only display
   begin 
    Delete @RetTable
     Where BalanceAmt > 0      
   end
 else
  if @RptType = 'D' -- Debit only display
   begin 
    Delete @RetTable
     Where BalanceAmt < 0      
   end


 Update @RetTable Set DocNo=p.DocNo, RefDate=p.RefDate, VrRoute=p.VrRoute, InitialAmt=p.Amount, 
     DueDate=DateAdd(day, p.CreditDays, p.RefDate), OverDue=(DateDiff(day, p.RefDate, @RptDate) - p.CreditDays)
  from @RetTable n
  Left Outer Join FAS_BillDetails p 
   On n.RefNo=p.RefNo and n.DocDate=p.DocDate and n.LrCode=p.LrCode and p.Type='New Ref' and p.CompCode=@CmCode 

 Update @RetTable Set DocNo=p.DocNo, RefDate=p.RefDate, VrRoute=p.VrRoute, InitialAmt=p.Amount, 
     DueDate=DateAdd(day, p.CreditDays, p.RefDate), OverDue=(DateDiff(day, p.RefDate, @RptDate) - p.CreditDays)
  from @RetTable n
  Left Outer Join FAS_BillDetails p 
   On n.RefNo=p.RefNo and n.DocDate=p.DocDate and n.LrCode=p.LrCode and p.CompCode=@CmCode 
  Where n.RefDate is Null


 Update @RetTable Set VrName=isNull(q.VoucherName, 'OpBal')
  from @RetTable n
  Left Outer Join FAS_VoucherMaster q
   On (q.VrRoute+q.VrWidth)=n.VrRoute and q.CompCode=@CmCode


 Update @RetTable Set BillIndex=(Select Count(*) from @RetTable b 
     Where a.LrCode=b.LrCode and b.RefNo<=a.RefNo )
 From @RetTable a

 Return

End
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Rpt_OutStandingBills]    Script Date: 17/06/2026 11:38:46 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [dbo].[fn_FAS_Rpt_OutStandingBills] (@UserKey Varchar(36),  @RptType Char(1), @RptDate Datetime, @Start datetime, @End datetime, @CmCode varchar(12)) 

RETURNS @RetTable TABLE
	([LrCode] int,
	[Particulars] [Varchar] (100),
	[Amount] [money],
	[OnAcct] [money],
	[TotAmt] [money],
	[LrRoute] [varchar](42)
	)
AS

Begin
	
	Declare @BranchID varchar(2)
	select @BranchID = substring(@CmCode, 3, 2)	

	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)



	Insert into @RetTable

		Select * 
		From
			(Select LrCode, Particulars, BillAmt, (OpBalance + VrAmt - BillAmt) as OnAcct, (OpBalance+VrAmt) as TotAmt, LrRoute
			From
				(Select n.LedgerCode as LrCode, n.LedgerName as Particulars, n.OpBalance, n.LrRoute as LrRoute, 
					isNull(p.VrAmt, 0) as VrAmt, isNull(m.BillAmt, 0) as BillAmt
				from FAS_LedgerMaster n
					Left Outer Join (Select LrCode, Sum(DrAmt-CrAmt) as VrAmt From FAS_VoucherTranSub
							 Where DocDate<=@RptDate and CompCode=@CmCode
							and LrCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchID = @BranchID and CompID = @CompID)
							Group by LrCode) p
						On n.LedgerCode=p.LrCode
					Left Outer Join (Select LrCode, Sum(Amount) as BillAmt From FAS_BillDetails
							 Where DocDate<=@RptDate and Type<>'On Acct' and CompCode=@CmCode
							and LrCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchID = @BranchID and CompID = @CompID)
							Group by LrCode) m
						On m.LrCode=n.LedgerCode
				Where n.CompCode=@CmCode and LedgerCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchID = @BranchID and CompID = @CompID)
				) q
			) r
		Where r.TotAmt<>0


/*
		Select n.LedgerCode as LrCode, n.LedgerName as Particulars, m.BillAmt as Amount, m.AdvAmt as OnAcct,  (m.BillAmt+m.AdvAmt) as TotAmt, n.LrRoute as LrRoute
		from FAS_LedgerMaster n Right Outer Join 
				(Select p.LrCode, Sum(p.AdvAmt) as AdvAmt, Sum(p.BillAmt) as BillAmt
				from
					(Select LrCode, Case When Type='On Acct' then Amount Else 0 End as AdvAmt,
						Case When Type<>'On Acct' then Amount Else 0 End as BillAmt
					from FAS_BillDetails
					where DocDate <=@RptDate and CompCode=@CmCode
					) p 
				group by p.Lrcode) m
			On m.LrCode=n.LedgerCode
			Where (m.BillAmt+m.AdvAmt) <> 0
				and m.LrCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchID = @BranchID and CompID = @CompID)
				and n.CompCode=@CmCode
			order by n.LrRoute, n.LedgerName
*/		
		
			if @RptType = 'C' -- Credit only display
				begin 
					Delete @RetTable
						Where TotAmt > 0
						
				end

			if @RptType = 'D' -- Debit only display
				begin 
					Delete @RetTable
						Where TotAmt < 0
						
				end	
	Return

END




GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Rpt_PerformanceAnalysis]    Script Date: 17/06/2026 11:38:46 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Rpt_PerformanceAnalysis] (@Type  as char(1), @RptDate datetime, @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))  

RETURNS @RetTable TABLE
	([Type]	 	[varchar] (10),
	[Path] 		[varchar](42),	
	[Code] 		[int],	
	[Particulars] 	[varchar] (100),
	[OBAmt]		money,
	[DayDr] 		money,
	[DayCr] 		money,
	[MonthDr] 	money,
	[MonthCr]	money,
	[YearDr]		money,
	[YearCr] 	money
	)

 AS  

BEGIN 
	
	Declare @DayPlAmt as money
	Declare @MthPlAmt as money
	Declare @YearPlAmt as money		

	Declare @tmpDate datetime

--	Select @tmpDate=Convert(datetime, (Convert(varchar(7), @RptDate, 105)+'-01'), 105)
	Select @tmpDate = Convert(datetime, (Convert(varchar(7), @RptDate, 111)+'-01'), 111)



	/*  Insert Ledgers*/
	Insert into @RetTable 

		Select 'Ledger', a.LrRoute, a.LedgerCode, a.LedgerName, a.OpBalance as OBAmt, 
			Sum(Case When DocDate=@RptDate Then DrAmt Else 0 End) as DayDr,
			Sum(Case When DocDate=@RptDate Then CrAmt Else 0 End) as DayCr,
			Sum(Case When Convert(varchar(6), DocDate, 112)=Convert(varchar(6), @RptDate, 112) and (DocDate<@RptDate) Then DrAmt Else 0 End) as MonthDr,
			Sum(Case When Convert(varchar(6), DocDate, 112)=Convert(varchar(6), @RptDate, 112) and (DocDate<@RptDate) Then CrAmt Else 0 End) as MonthCr,

			Sum(DrAmt) as YearDr, Sum(CrAmt) as YearCr
		From dbo.fn_FAS_AllOpBalance(@PrStart, '0', '0', @CmCode) a 
		Left Outer Join FAS_VoucherTranSub b
		On a.LedgerCode=b.LrCode and a.CompCode=b.CompCode 
		Where  b.DocDate <= @RptDate 
			and (Left(a.LrRoute, 2) in ('0B', '0E', '0D', '05', '06', '07', '08', '01', '02', '03') or Left(a.LrRoute, 4) in ('0201', '0202', '0B01', '0206', '0303'))
		Group by a.LrRoute, a.LedgerCode, a.LedgerName, a.OpBalance

	/*  Insert Groups*/
	Insert into @RetTable
				
		Select 'Group', a.GrRoute+a.GrWidth, a.GroupCode, a.GroupName, 
			isNull(Sum(OBAmt), 0) as OBAmt, 
			isNull(Sum(DayDr), 0) as DayDr, isNull(Sum(DayCr), 0) as DayCr, 
			isNull(Sum(MonthDr), 0) as MonthDr, isNull(Sum(MonthCr), 0) as MonthCr, 
			isNull(Sum(YearDr), 0) as YearDr, isNull(Sum(YearCr), 0) as YearCr
		from FAS_GroupMaster a Left Outer Join @RetTable b
		On a.GrRoute+a.GrWidth = Left(b.Path, Len(a.GrRoute+a.GrWidth))
		Where a.CompCode=@CmCode
		Group by a.GrRoute+a.GrWidth, a.GroupName, a.GroupCode

	/* Delete Ledgers*/
	Delete from @RetTable
		Where Type='Ledger'
			or Not (Path in ('0B', '0E', '0D', '05', '06', '07', '08', '01', '02', '03') or Path in ('0201',  '0202', '0B01', '0206', '0303'))

	/*  Bank Account*/
	Update @RetTable Set Path = 'BA', ObAmt = (a.ObAmt+b.ObAmt),
					DayDr=(a.DayDr+b.DayDr), DayCr = (a.DayCr+b.DayCr), 
					MonthDr = (a.MonthDr+b.MonthDr), MonthCr = (a.MonthCr+b.MonthCr), 
					YearDr = (a.YearDr+b.YearDr), YearCr = (a.YearCr+b.YearCr) 	
		From @RetTable a
		Left Outer Join  (Select * From @RetTable Where Path = '0B01')b
		On a.Type = b.Type
	Where a.Path = '0201'


	/* Bank OD A/C*/
	Delete @RetTable 
	Where Type = 'Group' and Code = 17 

	/*  Working Capital*/
	Insert into @RetTable Select 'Group', 'WC',  9999, 'Working Capital',  Sum(OBAmt) as OBAmt, Sum(DayDr), Sum(DayCr), Sum(MonthDr), Sum(MonthCr), Sum(YearDr), Sum(YearCr)
				From @RetTable Where Path in ('02', '03')

	If @Type = 'R'
		
		Begin
			/*  Gross Profit*/
			Select @DayPlAmt  = dbo.fn_FAS_GrossProfit_Loss_Period(@RptDate, @RptDate, @CmCode)
			Select @MthPlAmt  = dbo.fn_FAS_GrossProfit_Loss_Period(@tmpDate, @RptDate, @CmCode)
			Select @YearPlAmt = dbo.fn_FAS_GrossProfit_Loss_Period(@PrStart, @RptDate, @CmCode)
			
			Insert into @RetTable
				Select 'Group', 'GP', 9990, 'Gross Profit', OpBalance as OBAmt, @DayPlAmt as DayDr, 0 DayCr, @MthPlAmt as MonthDr, 0 as MonthCr,
					 @YearPlAmt as YearDr, 0 as YearCr				
				From FAS_LedgerMaster
				Where LedgerCode = 2 and CompCode = @CmCode
			
			/*  Nett Profit*/
			Select @DayPlAmt  = dbo.fn_FAS_Profit_Loss_Period(@RptDate, @RptDate, @CmCode)
			Select @MthPlAmt  = dbo.fn_FAS_Profit_Loss_Period(@tmpDate, @RptDate, @CmCode)
			Select @YearPlAmt = dbo.fn_FAS_Profit_Loss_Period(@PrStart, @RptDate, @CmCode)
			
			Insert into @RetTable
				Select 'Group', 'NP', 9991, 'Nett Profit', OpBalance as OBAmt, @DayPlAmt as DayDr, 0 DayCr, @MthPlAmt as MonthDr, 0 as MonthCr,
					 @YearPlAmt as YearDr, 0 as YearCr				
				From FAS_LedgerMaster
				Where LedgerCode = 2 and CompCode = @CmCode			

			
			/*   Operation Ratio   Total Expense - Total Income*/
			/*   Operation Cost   (Total Expense - Total Income) Sales Accounts*/
			Insert into @RetTable
				Select distinct a.Type, 'OR',  9993, 'Operation Ratio', (Sum(a.OBAmt) - cOBAmt) aOBAmt, (Sum(a.DayDr)- cDayDr) aDayDr, (Sum(a.DayCr)- cDayCr) aDayCr, 
						(Sum(a.MonthDr)-cMonthDr) aMonthDr, (Sum(a.MonthCr)-cMonthCr) aMonthCr, 
						(Sum(a.YearDr)-cYearDr) aYearDr, (Sum(a.YearCr)-cYearCr) aYearCr
				From @RetTable a
				Left Outer Join
					(	Select Type, Sum(OBAmt) cOBAmt, Sum(DayDr) cDayDr, Sum(DayCr) cDayCr, Sum(MonthDr) cMonthDr, 
						Sum(MonthCr) cMonthCr, Sum(YearDr) cYearDr, Sum(YearCr) cYearCr 
								From @RetTable c
				 		Where Path in ('06', '08') Group by Type
					) b
				On a.Type = b.Type
				Where a.Path in ('05', '07')
				Group by a.Type, cOBAmt, cDayDr, cDayCr, cMonthDr, cMonthCr, cYearDr, cYearCr

			/* Liquid Asset  (CurrentAsset-Stock)*/

			Select @DayPlAmt  = (Select Sum(ClosingStock) from dbo.fn_FAS_StockValue (@RptDate, @RptDate, @CmCode))
			Select @MthPlAmt  = (Select Sum(ClosingStock) from dbo.fn_FAS_StockValue (@tmpDate, @RptDate, @CmCode))
			Select @YearPlAmt = (Select Sum(ClosingStock) from dbo.fn_FAS_StockValue (@PrStart, @RptDate, @CmCode))

			Declare @OBStk as money
			Select @OBStk = (Select Sum(OpeningStock) from dbo.fn_FAS_StockValue (@PrStart, @PrStart, @CmCode))
			
			Insert into @RetTable
				Select Type,  'LA', 9995, 'Liquid Asset',  (a.OBAmt-@OBStk) as OBAmt, 
					Case Sign(@DayPlAmt) When 1 then (a.DayDr-@DayPlAmt) Else 0 end DayDr, 
					Case Sign(@DayPlAmt) When -1 then (a.DayCr-@DayPlAmt) Else 0 end DayCr, 

					Case Sign(@MthPlAmt) When 1 then (a.MonthDr-@MthPlAmt) Else 0 end MonthDr, 
					Case Sign(@MthPlAmt) When -1 then (a.MonthCr-@MthPlAmt) Else 0 end MonthCr, 

					Case Sign(@YearPlAmt) When 1 then (a.YearDr-@YearPlAmt) Else 0 end YearDr, 
					Case Sign(@YearPlAmt) When -1 then (a.YearCr-@YearPlAmt) Else 0 end YearCr
				From @RetTable a				
				 Where a.Path = '02'

		End

	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Rpt_ProfitAndLoss]    Script Date: 17/06/2026 11:38:46 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [dbo].[fn_FAS_Rpt_ProfitAndLoss] (@isVertical bit,  @RptType int, @Start datetime, @End datetime, @CmCode varchar(12))  
/*  Horizontal Representation ProfitAndLoss */	
/*  @RptType - 0 refers Abstract-only groups, 1 refers expand to single level, 2 refers Sub group with all ledgers */

RETURNS @RetTable TABLE
	([Master] 	[varchar](10),
	[Path] 		[varchar](42),
	[Type] 		[varchar] (10),	
	[Code] 		int,
	[Particulars] 	[varchar] (100),
	[SubAmount] 	[money],
	[TotalAmount] 	[money],
	[SortOrder] 	int
	)
AS  

BEGIN 

	Declare @CallTrialBalanceType char(1)

	If @RptType='0'
		Select @CallTrialBalanceType='A'--Abstract Only Group
	if @RptType='1'
		Select @CallTrialBalanceType='S' -- Groups and 1st level Ledgers
	if @RptType='2'
		Select @CallTrialBalanceType='W'  --SubGroup with All Ledger



	Insert into @RetTable

		Select Master, Path, Type, Code,
				Case Type when 'Group' then Space(Len(Path)) + Particulars
		                           	when 'Ledger' then space(Len(Path))+'    '+Particulars End as Particulars,
							
					Case When Type='Ledger' or (Len(Path) > 2 and Type='Group') then Amount Else 0 End as SubAmt,	
					Case When Len(Path)=2 and Type='Group' then Amount Else 0 End as TotAmt, 0
	
		From (
				Select Master, Path, Type, Code, Particulars, (DrAmt-CrAmt) as Amount  
				from dbo.fn_FAS_Rpt_TrialBalance(@CallTrialBalanceType, @Start, @End, @CmCode)
				where Left(Path, 2) in ('0E', '0D', '05', '06', '07', '08')   
				
				Union All
		
				Select '00', '21' as Path, 'Group' as Type, 9999 as Code,  'Opening Stock'  as Particulars, Sum(OpeningStock) 
				from dbo.fn_FAS_StockValue (@Start, @End, @CmCode)
		
				Union All
		
				Select '00', '31' as Path, 'Group' as Type,  9999 as Code, 'Closing Stock'  as Particulars, Sum(-ClosingStock)
				from dbo.fn_FAS_StockValue (@Start,@End, @CmCode)

				Union All

				Select '00', '21', 'Ledger' as Type,  9999 as Code, isNull(b.LedgerName, '')  as Particulars, OpeningStock
				from dbo.fn_FAS_StockValue (@Start, @End, @CmCode) a Left Outer Join FAS_LedgerMaster b On a.LedgerCode=b.LedgerCode and a.CompCode=b.CompCode
				where OpeningStock<>0
		
				Union All
		
				Select '00', '31', 'Ledger' as Type,  9999 as Code, isNull(b.LedgerName, '')   as Particulars, -ClosingStock
				from dbo.fn_FAS_StockValue (@Start, @End, @CmCode) a Left Outer Join FAS_LedgerMaster b On a.LedgerCode=b.LedgerCode and a.CompCode=b.CompCode
				where ClosingStock<>0
	
			)M
			Order by Path, Type	


			If @RptType = '0' --Groupwise Summary
				Begin 
					Delete @RetTable
						Where  Not (Type='Group' and Len(Path) = 2)	
				End
			if @RptType = '1'
				Begin
					Delete @RetTable
						Where  (Type = 'Ledger'  and Len(Path) > 2) or (Type='Group' and Len(Path) > 4)	
				End

			Insert into @RetTable 
				Select '00' as Master, 'GP' as Path, 'Group' as Type,  0 as Code, Case When TotalAmount > 0 Then 'GROSS PROFIT'  Else 'GROSS LOSS' End as Particulars, 
					0 as SubAmount,  TotalAmount, 150 as SortOrder
				From 
					(Select -Sum(TotalAmount) as TotalAmount
					From @RetTable
					Where Left(Path, 2) in ('0E', '06', '31', '21', '0D', '05')
					)x				

			Insert into @RetTable
				Select '00' as Master, 'NP' as Path, 'Group' as Type,  0 as Code, Case When TotalAmount > 0 Then 'NET PROFIT'  Else 'NET LOSS' End as Particulars, 
					0 as SubAmount, TotalAmount, 200 as SortOrder
				From 
					(Select -Sum(TotalAmount) as TotalAmount
					From @RetTable
					Where Left(Path, 2) in ('0E', '06', '31', '08', '21', '0D', '05', '07')
					)x


/*  Update  SortOrder To Groups */

			Update @RetTable Set SortOrder =
				Case Path
					When '0E' Then 101 		
					When '21' Then 112
					When '0D' Then 113
					When '31' Then 114
					
					When '05' Then 125
					When '06' Then 126
	
					When '07' Then 197
					When '08' Then 198
				End
			Where Type='Group' and Len(Path) = 2 and Path not in ('GP', 'NP')

/* Update SortOrder To SubGroups and Ledgers		 */

			Update @RetTable Set SortOrder=b.SortOrder
			from @RetTable a Left Outer Join (Select * from @RetTable Where Type='Group' and Len(Path) = 2) b
			On Left(a.Path, 2)=b.Path
			Where Not (a.Type='Group' and Len(a.Path) = 2)				

			If @isVertical='1'		--These are no need for horizontal representation
				Begin
					Update @RetTable Set SubAmount=-SubAmount, TotalAmount=-TotalAmount
					Where Left(Path, 2) in ('0E', '06', '08', '31')

					Update @RetTable Set TotalAmount=Abs(TotalAmount)
					Where Left(Path, 2) in ('GP', 'NP')
		
					-- Initial Stage
					Insert into @RetTable  Select '00',  'TA', 'Group', 0, 'TRADING AMOUNT', 0 , 0, 0
					Insert into @RetTable  Select '00',  'CS', 'Group', 0, 'COST OF SALES', 0 , 0,  110
					Insert into @RetTable  Select '00',  'IS', 'Group', 0, 'INCOME STATEMENT', 0, 0, 160

				End
	Return


END











GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Rpt_SCH_TrialBalance]    Script Date: 17/06/2026 11:38:46 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Rpt_SCH_TrialBalance] (@RptType char(1), @Start datetime, @End datetime, @CmCode varchar(12))  
/* @RptType Takes Value 'M' for Expand to All Levels, 'S' for Single Level,  'L' for Ledgers only, All Other for Abstract - only top level groups - you may use 'A' */
/* 'T' for Expand All Ledgers with Top Level Groups Only */


RETURNS @RetTable TABLE
	([Master] [varchar](10),
	[Path] [varchar](42),
	[Type] [varchar] (10),
	[Code] [int],
	[Particulars] [varchar] (100),
	[OpBalance] [money],
	[DrAmt] [money],
	[CrAmt] [money],
	[ClosingBalance] [money]
	)

 AS  

BEGIN 
	
	Insert into @RetTable

		Select '', LrRoute, 'Ledger', LedgerCode, LedgerName, OBAmt, DrAmt, CrAmt, (OBAmt+DrAmt-CrAmt) as CBAmt
		from
			(Select a.LrRoute, a.LedgerCode, a.LedgerName, a.OpBalance as OBAmt, 
			isNull(Sum(b.DrAmt), 0)+isNull(Sum(c.DrAmt), 0) as DrAmt, isNull(Sum(b.CrAmt), 0)+isNull(Sum(c.CrAmt), 0) as CrAmt
			from dbo.fn_FAS_AllOpBalance(@Start, '0', '1', @CmCode) a 
			Left Outer Join FAS_VoucherTranSub b
				On a.LedgerCode=b.LrCode and a.CompCode=b.CompCode and b.DocDate between @Start and @End
			Left Outer Join FAS_Budget_LrOnly_Vw c
				On a.LedgerCode=c.SLCode and a.CompCode Like c.CompCode+'%' and c.PlanFor=2 /* Hard Coded for Testing */
					and c.PlanDate Between @Start and @End
			Group by a.LrRoute, a.LedgerCode, a.LedgerName, a.OpBalance
			) x

/*
	Delete @RetTable
	Where OpBalance=0 and DrAmt=0 and CrAmt=0 and ClosingBalance=0
*/

	If @RptType<>'L'	--For Ledgers Only options no need to update the groups
		Begin

			If @RptType='T'		--For this Option Group Total will be the sum of direct ledgers only
				Begin
					Insert into @RetTable
			
						Select '', a.GrRoute+a.GrWidth, 'Group', a.GroupCode, a.GroupName, isNull(Sum(b.OpBalance), 0) as OBAmt,
							 isNull(Sum(b.DrAmt), 0) as DrAmt, isNull(Sum(b.CrAmt), 0) as CrAmt, isNull(Sum(ClosingBalance), 0) as CBAmt
						from FAS_GroupMaster a Left Outer Join @RetTable b
						On a.GrRoute+a.GrWidth = b.Path
						Where a.CompCode=@CmCode
						Group by a.GrRoute+a.GrWidth, a.GroupName, a.GroupCode
				End
			Else
				Begin
					Insert into @RetTable
				
						Select '', a.GrRoute+a.GrWidth, 'Group', a.GroupCode, a.GroupName, isNull(Sum(b.OpBalance), 0) as OBAmt,
							 isNull(Sum(b.DrAmt), 0) as DrAmt, isNull(Sum(b.CrAmt), 0) as CrAmt, isNull(Sum(ClosingBalance), 0) as CBAmt
						from FAS_GroupMaster a Left Outer Join @RetTable b
						On a.GrRoute+a.GrWidth = Left(b.Path, Len(a.GrRoute+a.GrWidth))
						Where a.CompCode=@CmCode
						Group by a.GrRoute+a.GrWidth, a.GroupName, a.GroupCode
				End
		/*	
			Delete @RetTable
			Where OpBalance=0 and DrAmt=0 and CrAmt=0 and ClosingBalance=0
		*/


			If @RptType='S'		--Single Level Expand
				Begin
					Delete @RetTable
					Where  (Type = 'Ledger'  and Len(Path) > 2) or (Type='Group' and Len(Path) > 4)	
				End
			Else
				If @RptType<>'M'	--If it is not multi level expand then it should be Abstract Report
					Begin 
						Delete @RetTable
							Where  Not ((Type='Group' and Len(Path) = 2) or (Type='Ledger' and Path in ('00', 'ZZ')))
					End
		
		End

	Insert into @RetTable

		Select '', 'ZZ', 'Group', 0, 'Diff. in Opening Balance', Isnull(-Sum(OpBalance), 0) as Amt1, 0, 0, IsNull(-Sum(OpBalance), 0)
		from dbo.fn_FAS_AllOpBalance(@Start, '0', '1', @CmCode)

/*
	Delete @RetTable
	Where OpBalance=0 and DrAmt=0 and CrAmt=0 and ClosingBalance=0
*/



	Update @RetTable Set Master=Case When Left(Path, 2)  in ('02', '09', '0A', '0C') Then '00' When Left(Path, 2) in ('01', '03', '04', '0B', '0F') Then '01'
						When Left(Path, 2) in ('06', '08', '0E') Then '02' When Left(Path, 2) in ('05', '07', '0D') Then '03' Else '04' End


	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Rpt_ScheduleMonthly]    Script Date: 17/06/2026 11:38:46 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Rpt_ScheduleMonthly] (@RptType Char(2)='', @Start datetime, @NoofPeriod int, @CmCode varchar(12))  


RETURNS @RetTable TABLE
	([MthName] [varchar](3),
	[Master] [varchar](10),
	[Path] [varchar](42),
	[Type] [varchar] (10),
	[Code] [int],
	[Particulars] [varchar] (100),
	[OpBalance] [money],
	[DrAmt] [money],
	[CrAmt] [money],
	[ClosingBalance] [money],
	[SortOrder] [int]
	)

 AS  

BEGIN 
	
	Declare @CompCode varchar(12)
	Declare @StartDate datetime
	Declare @EndDate datetime
	Declare @Cnt int

	Select @Cnt=1

	While @Cnt <=@NoofPeriod
	
		Begin			

			If @Cnt=1		
				Begin 
					Select @StartDate=@Start
					Select @EndDate=DateAdd(d, -1, (DateAdd(m, 1, @StartDate)))
					
				End
			Else
				Begin
					Select @StartDate=DateAdd(m, 1, @StartDate)
					Select @EndDate=DateAdd(m, 1, @EndDate)
				End


			Select distinct top 1 @CompCode=CompCode From FAS_VoucherTranMast Where DocDate between @StartDate and @EndDate and CompCode  like Left(@CMCode, 4) + '%'
					
			/* Insert All Ledgers */				
			Insert into @RetTable
		
				Select  Month(MnCode) MthName,  '', LrRoute, 'Ledger', LedgerCode, LedgerName, OBAmt, DrAmt, CrAmt, (OBAmt+DrAmt-CrAmt) as CBAmt, @Cnt as SortOrder
				from  
					(Select  Convert(varchar(6), b.DocDate, 112) MnCode, a.LrRoute, a.LedgerCode, a.LedgerName, a.OpBalance as OBAmt, 
					isNull(Sum(DrAmt), 0) as DrAmt, isNull(Sum(CrAmt), 0) as CrAmt
					from dbo.fn_FAS_AllOpBalance(@StartDate, '0', '0', @CompCode) a Left Outer Join FAS_VoucherTranSub b
					On a.LedgerCode=b.LrCode and a.CompCode=b.CompCode and b.DocDate between @StartDate and @EndDate					
					Group by Convert(varchar(6), b.DocDate, 112), a.LrRoute, a.LedgerCode, a.LedgerName, a.OpBalance
					) x


			/* Insert All Groups */			
			Insert into @RetTable
		
				Select b.MthName, '', a.GrRoute+a.GrWidth, 'Group', a.GroupCode, a.GroupName, isNull(Sum(b.OpBalance), 0) as OBAmt,
					 isNull(Sum(b.DrAmt), 0) as DrAmt, isNull(Sum(b.CrAmt), 0) as CrAmt, isNull(Sum(ClosingBalance), 0) as CBAmt, @Cnt as SortOrder
				from FAS_GroupMaster a Left Outer Join @RetTable b
				On a.GrRoute+a.GrWidth = Left(b.Path, Len(a.GrRoute+a.GrWidth))
				Where a.CompCode=@CmCode 
				Group by  b.MthName,a.GrRoute+a.GrWidth, a.GroupName, a.GroupCode


			/* Insert Diff in OB */	
			Insert into @RetTable

				Select '' MthName, '', 'ZZ', 'Group', 0, 'Diff. in Opening Balance', Isnull(-Sum(OpBalance), 0) as Amt1, 0, 0, IsNull(-Sum(OpBalance), 0), @Cnt as SortOrder
				from dbo.fn_FAS_AllOpBalance(@StartDate, '0', '0', @CmCode) 


			Select @Cnt=@Cnt+1

		End


		/* Delete If OB, Dr, Cr & CB EqualTo zero*/

		Delete @RetTable
		Where OpBalance=0 and DrAmt=0 and CrAmt=0 and ClosingBalance=0

		/* Balance Sheet */	
		If @RptType='B'
			Delete From @RetTable Where  Left(Path, 2) in ('01', '02', '03', '04', '09', '0A', '0B', '0C', '0F', 'ZZ')  and (Path Not Like '0205%')

		/* Profit And Loss */
		If @RptType='P'
			Delete From @RetTable Where Left(Path, 2) in ('0E', '0D', '05', '06', '07', '08')   
	
		/* Update Master Value */
		Update @RetTable Set Master=Case When Left(Path, 2)  in ('02', '09', '0A', '0C') Then '00' When Left(Path, 2) in ('01', '03', '04', '0B', '0F') Then '01'
							When Left(Path, 2) in ('06', '08', '0E') Then '02' When Left(Path, 2) in ('05', '07', '0D') Then '03' Else '04' End
	


	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Rpt_ScheduleYearly]    Script Date: 17/06/2026 11:38:46 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Rpt_ScheduleYearly] (@RptType Char(2), @Start datetime, @NoofPeriod int, @CmCode varchar(12))  


RETURNS @RetTable TABLE
	([Master] [varchar](10),
	[Path] [varchar](42),
	[Type] [varchar] (10),
	[Code] [int],
	[Particulars] [varchar] (100),
	[OpBalance] [money],
	[DrAmt] [money],
	[CrAmt] [money],
	[ClosingBalance] [money],
	[SortOrder] [int]
	)

 AS  

BEGIN 
	
	Declare @CompCode varchar(12)
	Declare @StartDate datetime
	Declare @EndDate datetime
	Declare @Cnt int

	Select @Cnt=1

	While @Cnt <=@NoofPeriod
	
		Begin			

			If @Cnt=1		
				Begin 
					Select @StartDate=@Start
					Select @EndDate=DateAdd(d, -1, (DateAdd(yy, 1, @StartDate)))
					
				End
			Else
				Begin
					Select @StartDate=DateAdd(yy, 1, @StartDate)
					Select @EndDate=DateAdd(yy, 1, @EndDate)
				End


			Select distinct top 1 @CompCode=CompCode From FAS_VoucherTranMast Where DocDate between @StartDate and @EndDate and CompCode  like Left(@CMCode, 4) + '%'
					
			/* Insert All Ledgers */				
			Insert into @RetTable
		
				Select '', LrRoute, 'Ledger', LedgerCode, LedgerName, OBAmt, DrAmt, CrAmt, (OBAmt+DrAmt-CrAmt) as CBAmt, @Cnt as SortOrder
				from
					(Select a.LrRoute, a.LedgerCode, a.LedgerName, a.OpBalance as OBAmt, 
					isNull(Sum(DrAmt), 0) as DrAmt, isNull(Sum(CrAmt), 0) as CrAmt
					from dbo.fn_FAS_AllOpBalance(@StartDate, '0', '0', @CompCode) a Left Outer Join FAS_VoucherTranSub b
					On a.LedgerCode=b.LrCode and a.CompCode=b.CompCode and b.DocDate between @StartDate and @EndDate
					--Where a.LrRoute in (Select Path From  FAS_ScheduleRpt_Tmp Where UserKey=@UserKey)
					Group by a.LrRoute, a.LedgerCode, a.LedgerName, a.OpBalance
					) x


			/* Insert All Groups */			
			Insert into @RetTable
		
				Select '', a.GrRoute+a.GrWidth, 'Group', a.GroupCode, a.GroupName, isNull(Sum(b.OpBalance), 0) as OBAmt,
					 isNull(Sum(b.DrAmt), 0) as DrAmt, isNull(Sum(b.CrAmt), 0) as CrAmt, isNull(Sum(ClosingBalance), 0) as CBAmt, @Cnt as SortOrder
				from FAS_GroupMaster a Left Outer Join @RetTable b
				On a.GrRoute+a.GrWidth = Left(b.Path, Len(a.GrRoute+a.GrWidth))
				Where a.CompCode=@CmCode --and (a.GrRoute+a.GrWidth) in (Select Path From  FAS_ScheduleRpt_Tmp Where UserKey=@UserKey)
				Group by a.GrRoute+a.GrWidth, a.GroupName, a.GroupCode

			/* Insert Diff in OB */	
			Insert into @RetTable

				Select '', 'ZZ', 'Group', 0, 'Diff. in Opening Balance', Isnull(-Sum(OpBalance), 0) as Amt1, 0, 0, IsNull(-Sum(OpBalance), 0), @Cnt as SortOrder
				from dbo.fn_FAS_AllOpBalance(@StartDate, '0', '0', @CmCode) 


			Select @Cnt=@Cnt+1
		End


		/* Delete If OB, Dr, Cr & CB EqualTo zero*/

		Delete @RetTable
		Where OpBalance=0 and DrAmt=0 and CrAmt=0 and ClosingBalance=0

		/* Balance Sheet */	
		If @RptType='B'
			Delete From @RetTable Where  Left(Path, 2) in ('01', '02', '03', '04', '09', '0A', '0B', '0C', '0F', 'ZZ')  and (Path Not Like '0205%')

		/* Profit And Loss */
		If @RptType='P'
			Delete From @RetTable Where Left(Path, 2) in ('0E', '0D', '05', '06', '07', '08')   
	
		/* Update Master Value */
		Update @RetTable Set Master=Case When Left(Path, 2)  in ('02', '09', '0A', '0C') Then '00' When Left(Path, 2) in ('01', '03', '04', '0B', '0F') Then '01'
							When Left(Path, 2) in ('06', '08', '0E') Then '02' When Left(Path, 2) in ('05', '07', '0D') Then '03' Else '04' End
	


	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Rpt_TrialBalance]    Script Date: 17/06/2026 11:38:46 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Rpt_TrialBalance] (@RptType char(1), @Start datetime, @End datetime, @CmCode varchar(12))            
--@RptType Takes Value 'M' for Expand to All Levels, 'S' for Single Level,  'L' for Ledgers only, All Other for Abstract - only top level groups - you may use 'A'          
-- 'T' for Expand All Ledgers with Top Level Groups Only          
RETURNS @RetTable TABLE          
 (    
     [Master] [varchar](10),          
     [Path] [varchar](42),          
     [Type] [varchar] (10),          
     [Code] [int],          
     [Particulars] [varchar] (100),          
     [OpBalance] [money],          
     [DrAmt] [money],          
     [CrAmt] [money],          
     [ClosingBalance] [money]          
 )          
 AS            
BEGIN           
    Insert into @RetTable          
        Select '', LrRoute, 'Ledger', LedgerCode, LedgerName, OBAmt, DrAmt, CrAmt, (OBAmt+DrAmt-CrAmt) as CBAmt          
        from          
            (      
                Select a.LrRoute, a.LedgerCode, a.LedgerName, a.OpBalance as OBAmt,           
                isNull(Sum(DrAmt), 0) as DrAmt, isNull(Sum(CrAmt), 0) as CrAmt          
                from dbo.fn_FAS_AllOpBalance(@Start, '0', '1', @CmCode) a   
                Left Outer Join FAS_VoucherTranSub b          
                    On a.LedgerCode=b.LrCode and a.CompCode=b.CompCode and (b.DocDate between @Start and @End)  
                Group by a.LrRoute, a.LedgerCode, a.LedgerName, a.OpBalance          
            ) x      
      
     /* To Insert Difference in Opening Balance Value - Inserted at the End of the Batch*/    
     Declare @OBDiff money  
     Select @OBDiff=Sum(OpBalance) From @RetTable  
              
          
    If @RptType<>'L' --For Ledgers Only options no need to update the groups          
        BEGIN          
            If @RptType='T'  --For this Option Group Total will be the sum of direct ledgers only          
                BEGIN          
                    Insert into @RetTable          
                        Select '', a.GrRoute+a.GrWidth, 'Group', a.GroupCode, a.GroupName, isNull(Sum(b.OpBalance), 0) as OBAmt,          
                            isNull(Sum(b.DrAmt), 0) as DrAmt, isNull(Sum(b.CrAmt), 0) as CrAmt, isNull(Sum(ClosingBalance), 0) as CBAmt          
                        from FAS_GroupMaster a       
                        Left Outer Join @RetTable b          
                            On a.GrRoute+a.GrWidth = b.Path          
                        Where a.CompCode=@CmCode          
                        Group by a.GrRoute+a.GrWidth, a.GroupName, a.GroupCode          
                END          
            Else          
                BEGIN          
                    Insert into @RetTable          
                        Select '', a.GrRoute+a.GrWidth, 'Group', a.GroupCode, a.GroupName, isNull(Sum(b.OpBalance), 0) as OBAmt,          
                            isNull(Sum(b.DrAmt), 0) as DrAmt, isNull(Sum(b.CrAmt), 0) as CrAmt, isNull(Sum(ClosingBalance), 0) as CBAmt          
                        from FAS_GroupMaster a       
                        Left Outer Join @RetTable b          
                            On a.GrRoute+a.GrWidth = Left(b.Path, Len(a.GrRoute+a.GrWidth))          
                        Where a.CompCode=@CmCode          
                        Group by a.GrRoute+a.GrWidth, a.GroupName, a.GroupCode          
                END          
            /*           
            Delete @RetTable          
            Where OpBalance=0 and DrAmt=0 and CrAmt=0 and ClosingBalance=0          
            */          
      
      
            If @RptType='S'  --Single Level Expand          
                BEGIN          
                    Delete @RetTable          
         Where  (Type = 'Ledger'  and Len(Path) > 2) or (Type='Group' and Len(Path) > 4)           
                END          
            Else          
                If @RptType<>'M' --If it is not multi level expand then it should be Abstract Report          
                    BEGIN           
                        Delete @RetTable          
                        Where  Not ((Type='Group' and Len(Path) = 2) or (Type='Ledger' and Path in ('00', 'ZZ')))          
                    END          
        END          
         
     /* To Insert Difference in Opening Balance Value */     
     --Insert into @RetTable                                      
     --   Select '', 'ZZ', 'Group', 0, 'Diff. in Opening Balance',                                   
     --   Isnull(-Sum(OpBalance), 0) as Amt1, 0, 0, IsNull(-Sum(OpBalance), 0)                                  
     --   From dbo.fn_FAS_AllOpBalance(@Start, '0', '1', @CmCode)  a   
          
     /* To Insert Difference in Opening Balance Value */  
     If (@OBDiff<>0)     
         Insert into @RetTable                                      
            Select '', 'ZZ', 'Group', 0, 'Diff. in Opening Balance', @OBDiff, 0, 0, @OBDiff                                  
          
    /*          
     Delete @RetTable          
     Where OpBalance=0 and DrAmt=0 and CrAmt=0 and ClosingBalance=0          
    */          
          
     Update @RetTable Set Master=Case When Left(Path, 2)  in ('02', '09', '0A', '0C') Then '00' When Left(Path, 2) in ('01', '03', '04', '0B', '0F') Then '01'          
          When Left(Path, 2) in ('06', '08', '0E') Then '02' When Left(Path, 2) in ('05', '07', '0D') Then '03' Else '04' End          
          
          
    RETURN           
          
END  
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Rpt_TrialBalance_PL]    Script Date: 17/06/2026 11:38:46 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Rpt_TrialBalance_PL] (@RptType char(1), @Start datetime, @End datetime, @CmCode varchar(12))                          
--@RptType Takes Value 'M' for Expand to All Levels, 'S' for Single Level,  'L' for Ledgers only, All Other for Abstract - only top level groups - you may use 'A'                        
-- 'T' for Expand All Ledgers with Top Level Groups Only                        
RETURNS @RetTable TABLE                        
 (          
 [Master] [varchar](10),                        
 [Path] [varchar](42),                        
 [Type] [varchar] (10),                        
 [Code] [int],                        
 [Particulars] [varchar] (100),                        
 [OpBalance] [money],                        
 [DrAmt] [money],                        
 [CrAmt] [money],                        
 [ClosingBalance] [money]                        
 )                        
 AS                          
BEGIN      
                      
    Insert into @RetTable                        
        Select '', LrRoute, 'Ledger', LedgerCode, LedgerName,                       
            OBAmt, DrAmt, CrAmt, (OBAmt+DrAmt-CrAmt) as CBAmt                             
        From                        
        (                      
            Select a.LrRoute, a.LedgerCode, a.LedgerName, 0 as OBAmt,                      
                isNull(Sum(b.DrAmt*b.ExchRate), 0) as DrAmt, isNull(Sum(b.CrAmt*b.ExchRate), 0) as CrAmt                        
            From FAS_LedgerMaster_AuthTbl a                         
            Left Outer Join FAS_VoucherCurrency b                       
            On a.LedgerCode=b.LrCode and a.CompCode=b.CompCode and b.DocDate between @Start and @End                        
            Where Left(a.LrRoute, 2) in ('0E', '0D', '05', '06', '07', '08')           
                and a.CompCode=@CmCode                        
            Group by a.LrRoute, a.LedgerCode, a.LedgerName                        
                      
            Union All                        
                      
            Select b.LrRoute, a.LedgerCode, b.LedgerName, a.OpeningStock, 0, 0                        
            From dbo.fn_FAS_StockValue (@Start, @End, @CmCode) a                        
            Left Outer Join FAS_LedgerMaster_AuthTbl b                        
            On a.LedgerCode=b.LedgerCode and a.CompCode=b.CompCode and b.EffStatus='AA'                        
            Where b.LrRoute Like '0205%'                           
        ) x                       
                          
 If @RptType<>'L' --For Ledgers Only options no need to update the groups                        
  Begin                        
                        
   If @RptType='T'  --For this Option Group Total will be the sum of direct ledgers only                        
    Begin                        
     Insert into @RetTable                        
                           
      Select '', a.GrRoute+a.GrWidth, 'Group', a.GroupCode, a.GroupName, isNull(Sum(b.OpBalance), 0) as OBAmt,                        
        isNull(Sum(b.DrAmt), 0) as DrAmt, isNull(Sum(b.CrAmt), 0) as CrAmt, isNull(Sum(ClosingBalance), 0) as CBAmt                        
      From FAS_GroupMaster a                       
      Left Outer Join @RetTable b                        
      On a.GrRoute+a.GrWidth = b.Path                        
      Where a.CompCode=@CmCode                        
       and Left(a.GrRoute+a.GrWidth, 2) in ('0E', '0D', '05', '06', '07', '08')                         
      Group by a.GrRoute+a.GrWidth, a.GroupName, a.GroupCode                        
    End                       
                           
   Else                        
    Begin                      
                            
     Insert into @RetTable                        
                            
      Select '', a.GrRoute+a.GrWidth, 'Group', a.GroupCode, a.GroupName, isNull(Sum(b.OpBalance), 0) as OBAmt,                        
   isNull(Sum(b.DrAmt), 0) as DrAmt, isNull(Sum(b.CrAmt), 0) as CrAmt, isNull(Sum(ClosingBalance), 0) as CBAmt             
      From FAS_GroupMaster a                       
      Left Outer Join @RetTable b                   
      On a.GrRoute+a.GrWidth = Left(b.Path, Len(a.GrRoute+a.GrWidth))                        
      Where a.CompCode=@CmCode                        
      and Left(a.GrRoute+a.GrWidth, 2) in ('0E', '0D', '05', '06', '07', '08')                         
      Group by a.GrRoute+a.GrWidth, a.GroupName, a.GroupCode                        
    End                        
  /*                         
   Delete @RetTable                 
   Where OpBalance=0 and DrAmt=0 and CrAmt=0 and ClosingBalance=0                        
  */                     
                         
   If @RptType='S'  --Single Level Expand                        
    Begin                        
     Delete @RetTable                   
     Where  (Type = 'Ledger'  and Len(Path) > 2) or (Type='Group' and Len(Path) > 4)                  
    End                        
   Else                        
    If @RptType<>'M' --If it is not multi level expand then it should be Abstract Report                        
     Begin                         
        Delete @RetTable                        
       Where  Not ((Type='Group' and Len(Path) = 2) or (Type='Ledger' and Path in ('00', 'ZZ')))                        
     End                        
                          
  End                      
                        
 Update @RetTable Set Master=Case When Left(Path, 2)  in ('02', '09', '0A', '0C') Then '00' When Left(Path, 2) in ('01', '03', '04', '0B', '0F') Then '01'                        
      When Left(Path, 2) in ('06', '08', '0E') Then '02' When Left(Path, 2) in ('05', '07', '0D') Then '03' Else '04' End                        
                          
 RETURN                     
                         
END  
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Schedule_BSPLGroup_Rpt]    Script Date: 17/06/2026 11:38:46 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [dbo].[fn_FAS_Schedule_BSPLGroup_Rpt] (@isBalanceSheet bit, @PeriodStart datetime, @PeriodEnd datetime, @isExpandAll bit, @isShowZeroCB bit, @SuppliedClosingStock money, @CmCode Varchar(12))
		
RETURNS @Schedule TABLE

	([SchLrCode] int,
		[SchPath] varchar(42),
		[SchLrName] varchar(50),
		[Amount] money,
		[isDebit] bit,
		[isExpand] bit,
		[Seq] int,
		[EntryType] [varchar](3))

 AS  

BEGIN

	Insert into @Schedule
		Select * From dbo.fn_FAS_ScheduleGroup_Rpt(@PeriodStart, @PeriodEnd,'1', '1', @SuppliedClosingStock, @CmCode)

		UPDATE @Schedule Set Amount=isNull((Select Sum(Amount) From @Schedule b Where b.SchPath Like a.SchPath+'%' and b.EntryType='LED'), 0)
		From @Schedule a 
		Where a.EntryType='SCH'

		UPDATE @Schedule Set Amount=-Amount
		Where SchPath Like '0H%'
		
		Delete @Schedule Where Not (Len(SchPath)=2 and EntryType='SCH')
	
		If @isBalanceSheet='1'
			Insert into @Schedule
				Select x.SchCode, x.SchPath, x.GroupName, x.CurrentCB as Amount, x.isDebit, x.isExpand, x.SubGrpSeq, x.EntryType 
				From 
					(
					Select (a.SubGrpRoute+a.SubGrpWidth) as SubGrpPath, a.Seq as SubGrpSeq, b.SchCode, d.SchLrName as GroupName, d.Amount as CurrentCB, d.isDebit, d.isExpand, d.EntryType, d.SchPath
					From FAS_BSPLGroupMaster_vw a
					Left Outer Join  FAS_BSPLGroup b
						On a.SubGrpCode= b.SubGrpCode and a.CompCode = b.CompCode
					Left Outer Join @Schedule d 
						On d.SchLrCode = b.SchCode 
					Where a.SubGrpRoute Like '01%' and a.EffStatus='AA' and a.ByParentStatus='1' and a.CompCode=@CmCode and b.SchCode is Not Null
					---Order By SubGrpPath Desc, SubGrpSeq
				)x
				Order By SubGrpSeq
	

				/*Select (a.SubGrpRoute+a.SubGrpWidth) as SubGrpPath, a.Seq as SubGrpSeq, b.SchCode, d.SchLrName as GroupName, d.Amount as CurrentCB, d.isDebit, d.isExpand, d.EntryType, d.SchPath
				From FAS_BSPLGroupMaster_vw a
				Left Outer Join  FAS_BSPLGroup b
					On a.SubGrpCode= b.SubGrpCode and a.CompCode = b.CompCode
				Left Outer Join @Schedule d 
					On d.SchLrCode = b.SchCode 
				Where a.SubGrpRoute Like '01%' and a.EffStatus='AA' and a.ByParentStatus='1' and a.CompCode=@CmCode and b.SchCode is Not Null
				Order By SubGrpPath Desc, SubGrpSeq*/
	
			Else
		
					Insert into @Schedule
						Select  x.SchCode, x.SchPath, x.GroupName,x.CurrentCB, x.isDebit, x.isExpand, x.SubGrpSeq, x.EntryType
						From
							(
								Select (a.SubGrpRoute+a.SubGrpWidth) as SubGrpPath, a.Seq as SubGrpSeq, b.SchCode, d.SchLrName as GroupName, d.Amount as CurrentCB, d.isDebit, d.isExpand, d.EntryType, d.SchPath
								From FAS_BSPLGroupMaster_vw a
								Left Outer Join  FAS_BSPLGroup b
									On a.SubGrpCode= b.SubGrpCode and a.CompCode = b.CompCode
								Left Outer Join @Schedule d 
									On d.SchLrCode = b.SchCode 
								Where a.SubGrpRoute Like '02%' and a.EffStatus='AA' and a.ByParentStatus='1' and a.CompCode=@CmCode and b.SchCode is Not Null
								---Order By SubGrpPath Desc, SubGrpSeq
							)x
							Order by SubGrpSeq
						

					/*Select (a.SubGrpRoute+a.SubGrpWidth) as SubGrpPath, a.Seq as SubGrpSeq, b.SchCode, d.SchLrName as GroupName, d.Amount as CurrentCB, d.isDebit, d.isExpand, d.EntryType, d.SchPath
					From FAS_BSPLGroupMaster_vw a
					Left Outer Join  FAS_BSPLGroup b
						On a.SubGrpCode= b.SubGrpCode and a.CompCode = b.CompCode
					Left Outer Join @Schedule d 
						On d.SchLrCode = b.SchCode 
					Where a.SubGrpRoute Like '02%' and a.EffStatus='AA' and a.ByParentStatus='1' and a.CompCode=@CmCode and b.SchCode is Not Null
					Order By SubGrpPath Desc, SubGrpSeq*/
		
	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_ScheduleGroup_Dtl]    Script Date: 17/06/2026 11:38:46 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_ScheduleGroup_Dtl] ( @AsOnDate datetime, @RptDate datetime, @CompCode Varchar(10))  

RETURNS @RetTable TABLE
	(SchCode	int,
	LrCode 		int,
	EffDate		datetime,
	EffStatus	bit,
	CreatedDate	datetime,
	CompCode	varchar(12),
	TranStamp	datetime
	)


 AS  

BEGIN 
	Insert @RetTable
		Select * from FAS_ScheduleGroup_Dtl a
		Where a.CreatedDate = (Select Max(b.CreatedDate) from FAS_ScheduleGroup_Dtl b where b.CreatedDate <= @AsOnDate 
			and b.SchCode=a.SchCode and b.CompCode = a.CompCode
			)
		and ((a.EffStatus='1' and a.EffDate <= @RptDate) or (a.EffStatus='0' and a.EffDate > @RptDate))
			and a.CompCode = @CompCode

	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_ScheduleGroup_Hdr]    Script Date: 17/06/2026 11:38:46 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_ScheduleGroup_Hdr] ( @AsOnDate datetime, @RptDate datetime, @CompCode Varchar(10))  

RETURNS @RetTable TABLE
	(SchCode	int,
	SchName	varchar(50),
	Status		bit,
	EffDate		datetime,
	EffStatus	bit,
	CreatedDate	datetime,
	CompCode	varchar(12),
	TranStamp	datetime
	)


 AS  

BEGIN 
	Insert @RetTable
		Select * from FAS_ScheduleGroup_Hdr a
		Where a.CreatedDate = (Select Max(b.CreatedDate) from FAS_ScheduleGroup_Hdr b where b.CreatedDate <= @AsOnDate 
			and b.SchCode=a.SchCode and b.CompCode = a.CompCode
			)
		and ((a.EffStatus='1' and a.EffDate <= @RptDate) or (a.EffStatus='0' and a.EffDate > @RptDate))
			and a.CompCode = @CompCode

	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_ScheduleGroup_Rpt]    Script Date: 17/06/2026 11:38:46 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [dbo].[fn_FAS_ScheduleGroup_Rpt] (@PeriodStart datetime, @PeriodEnd datetime, @isExpandAll bit, @isShowZeroCB bit, @SuppliedClosingStock money, @CmCode varchar(12))
	
RETURNS @Schedule TABLE

	([SchLrCode] int,
	[SchPath] varchar(42),
	[SchLrName] varchar(50),
	[Amount] money,
	[isDebit] bit,
	[isExpand] bit,
	[Seq] int,
	[EntryType] [varchar](3))

 AS  

BEGIN

	INSERT INTO @Schedule
	Select 0, 'zz', 'UNGROUPED', 0, '1', '1', 1, 'SCH'
 
	INSERT INTO @Schedule
	Select a.SchCode, a.SchRoute+a.SchWidth as SchPath, a.SchLongName, 0, isDebitBalance, isExpand, a.Seq, 'SCH'
			From FAS_ScheduleMaster_vw a
			Where a.EffStatus='AA' and a.ByParentStatus='1' and a.CompCode=@CmCode
				--and a.SchRoute+a.SchWidth Not Like '05%' --'Fixed Assets'
 
	INSERT INTO @Schedule
	Select a.LedgerCode, isNull(d.SchPath, 'zz') as SchPath, a.LedgerName, isNull(b.ClosingBalance, 0) as CurrentCB, 
			isNull(d.isDebit, '1'), isNull(d.isExpand, '1'), isNull(d.Seq, 0), 'LED'
		From (
				Select LedgerCode, LedgerName, CompCode 
				From FAS_LedgerMaster 
				Where (LrRoute Not Like '0205%' and LedgerCode<>2) and LrRoute Not Like '09%' and CompCode = @CmCode 
				Union All 
				Select -1, 'P & L OPENING BALANCE', @CmCode 
				Union All 
				Select -2, 'P & L CURRENT PERIOD', @CmCode
				Union All 
				Select -3, 'P & L TRANSFERED', @CmCode
				Union All
				Select -4, 'OPENING STOCK', @CmCode
				Union All 
				Select -5, 'CLOSING STOCK', @CmCode 
				Union All 
				Select -6, 'DEPRECIATION CURRENT PERIOD', @CmCode 
				Union All 
				Select -7, 'DEPRECIATION CUMULATIVE', @CmCode
				Union All 
				Select -8, 'FIXED ASSET GROSS BLOCK', @CmCode
				) a 
		Left Outer Join dbo.fn_FAS_Rpt_TrialBalance('L', @PeriodStart, @PeriodEnd, @CmCode) b On b.Code = a.LedgerCode  
		Full Outer Join FAS_ScheduleGroup c On a.LedgerCode=c.LrCode and a.CompCode=c.CompCode
		Left Outer Join @Schedule d On c.SchCode =d.SchLrCode
		Where a.CompCode =@CmCode --and d.ClosingBalance <> 0  
		
		Declare @Amt1 money, @Amt2 money
		
		/* To insert Profit & Loss A/c Details */
		/* Opening Balance */
		Update @Schedule Set Amount=isNull(dbo.fn_FAS_Profit_Loss_OB_SCH(@PeriodStart, @SuppliedClosingStock, @CmCode) , 0)
		Where SchLrCode=-1 and EntryType='LED'
		
		/* Current Period */
		Update @Schedule Set Amount=isNull(dbo.fn_FAS_Profit_Loss_Period_SCH(@PeriodStart, @PeriodEnd, @SuppliedClosingStock, @CmCode), 0)
		Where SchLrCode=-2 and EntryType='LED'
		
		/* Less Transferred */
		Select @Amt1=(sum(DrAmt)-sum(CrAmt))
			from FAS_VoucherTranSub 
			where (DocDate between @PeriodStart and  @PeriodEnd) and LrCode=2 and Compcode = @CmCode
		
		Update @Schedule Set Amount=isNull(@Amt1, 0)
		Where SchLrCode=-3 and EntryType='LED'
	
		
		/* Opening Stock and Closing Stock Update */
		Select @Amt1=Sum(OpeningStock), @Amt2=Sum(-ClosingStock) From dbo.fn_FAS_StockValue (@PeriodStart, @PeriodEnd, @CmCode)

		Update @Schedule Set Amount=isNull(@Amt1, 0)
		Where SchLrCode=-4 and EntryType='LED'
	
		If @SuppliedClosingStock >= 0
			Update @Schedule Set Amount=isNull(-@SuppliedClosingStock, 0)
			Where SchLrCode=-5 and EntryType='LED'
		Else
			Update @Schedule Set Amount=isNull(@Amt2, 0)
			Where SchLrCode=-5 and EntryType='LED'
		
		
		/* Depreciation Value Update */		
		
		/* DEPRECIATION CURRENT PERIOD */
		Select @Amt1=Sum(CurrentDepreciation) From FAS_DepreciationProcess 
		Where Left(CompCode, 4)=Left(@CmCode, 4) and ((FromDate Between @PeriodStart and @PeriodEnd) and (ToDate Between @PeriodStart and @PeriodEnd))
		
		Update @Schedule Set Amount=isNull(@Amt1, 0)
		Where SchLrCode=-6 and EntryType='LED'
		
		/* DEPRECIATION CUMULATIVE */
		Select @Amt2=Sum(CurrentDepreciation) From FAS_DepreciationProcess 
		Where Left(CompCode, 4)=Left(@CmCode, 4) and ToDate < @PeriodStart
		
		Update @Schedule Set Amount=-(isNull(@Amt1, 0)+isNull(@Amt2, 0))
		Where SchLrCode=-7 and EntryType='LED'
		
		
		/* FIXED ASSET GROSS BLOCK */
		Select @Amt1=Sum(OpBalance) From FAS_DepreciationMaster
		Where Left(CompCode, 4)=Left(@CmCode, 4) and OpBalDate <= @PeriodEnd
		
		Update @Schedule Set Amount=isNull(@Amt1, 0)
		Where SchLrCode=-8 and EntryType='LED'		
		

	UPDATE @Schedule Set Amount=isNull((Select Sum(Amount) From @Schedule b Where b.SchPath Like a.SchPath+'%' and b.EntryType='LED'), 0)
	From @Schedule a 
	Where a.EntryType='SCH'	
	
	
	/* Delete the Non-Expandable Entries */
	If @isExpandAll='0'
		BEGIN
			Declare @sPath varchar(42)
			
			Declare curSch CURSOR FOR	
				Select SchPath from @Schedule a 
				Where isExpand='0' 
				and Not Exists (Select * from @Schedule b 
								Where b.isExpand='0' and Len(b.SchPath)<Len(a.SchPath) and a.SchPath like Left(b.SchPath, 2)+'%')
			
			OPEN curSch
			FETCH NEXT FROM curSch into @sPath

			WHILE @@FETCH_STATUS =  0 
				Begin
					Delete From @Schedule Where SchPath Like @sPath+'%' and ((SchPath<>@sPath and EntryType='SCH') OR EntryType='LED')
					
					FETCH NEXT FROM curSch into @sPath
				End
		END
	
	/* Delete Zero Closing Balance Entries Based On the Option @@isShowZeroCB */
	If @isShowZeroCB=Convert(bit, '0')
		Delete From @Schedule Where Amount=0

	/* Select * from @Schedule Where (@isShowZeroCB='1' OR Amount<>0) Order By SchPath, EntryType Desc */
	
		
	/* Update the Amount to Zero for Expandable Item */
	Update @Schedule Set Amount=0 
	Where EntryType='SCH' and isExpand='1'	
		

	---Select * from @Schedule Order By SchPath+case when EntryType='LED' Then 'ZZ' Else '' End, SchLrName --, EntryType Desc
	
	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_StockFAS_OBCB]    Script Date: 17/06/2026 11:38:46 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_StockFAS_OBCB] (@OBDate datetime, @CBDate datetime, @CmCode varchar(12))    
  
RETURNS @Stock TABLE  
 (  
 LedgerCode  int,  
 LedgerName  varchar(50),  
 OpeningStock money,  
 ClosingStock money,  
 CompCode  varchar(12)  
 )  
    
AS  
  
BEGIN   
  
 If (@OBDate IS NOT NULL) AND (@CBDate IS NOT NULL) /* Both Opening Stock & Closing Stock Required */  
  Insert Into @Stock  
   Select a.LedgerCode, a.LedgerName, isNull(b.StockValue, 0) as OBStock, isNull(c.StockValue, 0) as CBStock, a.CompCode  
   From FAS_LedgerMaster_AuthTbl a  
   Left Outer Join FAS_StockEntry b  
    On a.LedgerCode=b.LedgerCode and a.CompCode=b.CompCode   
     /*and b.DataOF='FAS'*/ and b.StockDate=(Select Max(b2.StockDate) From FAS_StockEntry b2  
         Where b2.StockDate < @OBDate and b2.CompCode=@CmCode --and b2.DataOF='FAS'  
          and b2.LedgerCode=b.LedgerCode  
         )  
   Left Outer Join FAS_StockEntry c  
    On a.LedgerCode=c.LedgerCode and a.CompCode=c.CompCode  
     /*and c.DataOF='FAS'*/ and c.StockDate=(Select Max(c2.StockDate) From FAS_StockEntry c2  
         Where c2.StockDate <= @CBDate and c2.CompCode=@CmCode --and c2.DataOF='FAS'  
          and c2.LedgerCode=c.LedgerCode  
         )  
   Where a.LrRoute Like '0205%' and a.CompCode=@CmCode and a.EffStatus='AA'    
  
 Else  
 If (@OBDate IS NOT NULL)  /* Only Opening Stock Required */  
  BEGIN  
   Declare @tmpOBDate datetime  
   Select @tmpOBDate = DateAdd(day, -1, @OBDate)  
    
   Insert Into @Stock  
    SELECT a.LedgerCode, a.LedgerName, b.StockValue, 0, @CmCode  
     FROM FAS_LedgerMaster_AuthTbl a  
     Left Outer Join dbo.fn_FAS_StockFAS_AsOnDate(@tmpOBDate, @CmCode) b  
      On a.LedgerCode=b.LedgerCode  
     WHERE a.LrRoute Like '0205%' and a.Compcode=@CmCode and a.EffStatus='AA'  
  END  
      
 Else       /* Only Closing Stock Required */  
  Insert Into @Stock  
   SELECT a.LedgerCode, a.LedgerName, 0, b.StockValue, @CmCode  
    FROM FAS_LedgerMaster_AuthTbl a  
    Left Outer Join dbo.fn_FAS_StockFAS_AsOnDate(@CBDate, @CmCode) b  
     On a.LedgerCode=b.LedgerCode  
    WHERE a.LrRoute Like '0205%' and a.Compcode=@CmCode and a.EffStatus='AA'  
   
 RETURN  
  
END  
  
GO

