CREATE FUNCTION [dbo].[fn_INV_AsOnDate_Stock] (@StockDate datetime, 
	@BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))          
RETURNS @RetTable TABLE    
 ([ItemCode]   [varchar] (20),     
  [WarehouseCode] [varchar] (6),    
  [RackCode]  [varchar] (10),    
  [CBQty]   [float],    
  [BranchID]   [varchar] (3),    
  [CompID]   [varchar] (3)    
 )    
AS          
BEGIN     
   Insert @RetTable
    Select b.TransactionItem, c.WarehouseCode, '' as RackCode,    
      IsNull(Sum(Case When b.ToWarehouseCode = c.WarehouseCode Then b.TransactionQty Else -b.TransactionQty End), 0) as CbQty,      
      b.BranchID, b.CompID         
    From Inv_MaterialTran_Dtl b          
    Full Outer Join INV_Warehouse_Master_All c     
    On c.BranchID = b.BranchID and c.CompID = b.CompID         
    Where c.WarehouseCode <>'WIP' and c.WarehouseCode in (b.FromWarehouseCode, b.ToWarehouseCode)  
	   and convert(varchar(10),b.TransactionDate,120) + ' ' + convert(varchar(8),b.TransactionTime,108) <= @StockDate         
	   and b.BranchID = @BranchID and b.CompID = @CompID  --and b.Finyear = @Finyear           
    group by b.TransactionItem, c.WarehouseCode, b.BranchID, b.CompID        
   Return         
END
GO

