CREATE FUNCTION [dbo].[fn_INV_AsOnDate_Stock_AllWhs] (@StockDate datetime,  @BranchID varchar(3),  
	@CompID varchar(3),  @Finyear varchar(15))    
-- It Returns data equal fn_INV_AsOnDate_Stock and additionally it returns Stock for 'Under Inspection' Warehouse  
RETURNS @RetTable TABLE  
 ([ItemCode] [varchar] (20),  
 [WarehouseCode] [varchar] (6),  
 [RackCode] [varchar] (10),  
 [RackBinCode] [varchar] (10),
 [CBQty] [float],  
 [BranchID] [varchar] (3),  
 [CompID] [varchar] (3)  
 )    
AS      
BEGIN   
  Insert @RetTable    
   Select a.ItemCode, c.WarehouseCode, '' as RackCode, '' as RackBinCode, 
    IsNull(Sum(Case When b.ToWarehouseCode = c.WarehouseCode Then b.TransactionQty Else -b.TransactionQty End), 0) as CbQty,  
    a.BranchID, a.CompID  
   From Inv_Material_Master_all a   
   Full Outer Join Inv_MaterialTran_Dtl b   
    On a.ItemCode = b.TransactionItem and a.BranchID = b.BranchID and a.CompID = b.CompID  
   Full Outer Join  Inv_Warehouse_Master_All c  
    On c.BranchID = b.BranchID and c.CompID = b.CompID  
   Where c.WarehouseCode in (b.FromWarehouseCode, b.ToWarehouseCode)  
    and b.TransactionDate <= @StockDate    
    and c.WarehouseCode Not in (Select WarehouseCode from INV_WarehouseTemp_Master c1 Where c1.WarehouseCode<>'UI' and c1.BranchID=@BranchID and c1.CompID=@CompID)  
    and a.BranchID = @BranchID and a.CompID = @CompID  
	/* and b.Finyear = @Finyear */     
   Group by a.Itemcode, c.WarehouseCode, a.BranchID, a.CompID  
  
  Return     
END
GO

