CREATE FUNCTION [dbo].[fn_INV_AsOnDate_Stock_Item] (@ItemCode Varchar(20), @AsOnDate datetime,  
@RptDate datetime, @BranchID varchar(3),  @CompID varchar(3),  @Finyear varchar(20))    
RETURNS @RetTable TABLE  
  ([WarehouseCode] [varchar] (6),  
	[WarehouseNature] [varchar] (20),   
  [RackBinCode] [varchar] (6),  
  [CBQty] [float],  
  [BranchID] [varchar] (3),  
  [CompID] [varchar] (3)  
  )      
AS        
BEGIN   
    Insert @RetTable  
			Select  c.WarehouseCode, c.WarehouseNature, c.RackBinCode,  
					 IsNull(Sum(Case When (b.ToWarehouseCode=c.WarehouseCode and b.ToRackBinCode=c.RackBinCode) Then b.TransactionQty   
													 When (b.FromWarehouseCode=c.WarehouseCode and b.FromRackBinCode=c.RackBinCode) Then -b.TransactionQty  
													 Else 0 End), 0) as CbQty,  
      
					 b.BranchID, b.CompID  		          
			From Inv_MaterialTran_Dtl b         
			Full Outer Join dbo.fn_INV_Warehouse_Master_Get_All('1', @AsonDate, @RptDate, @BranchiD, @CompID, @Finyear) c   
				On c.WarehouseCode In(b.FromWarehouseCode, b.ToWarehouseCode) 
						and c.BranchID=b.BranchID and c.CompID=b.CompID        
			Where  b.TransactionItem = @ItemCode  and c.WarehouseCode In(b.FromWarehouseCode, b.ToWarehouseCode)  
							and b.TransactionDate<=@AsOnDate and b.BranchID=@BranchID and b.CompID=@CompID 
							and b.Finyear = @Finyear        
			Group by b.TransactionItem, c.WarehouseCode, c.WarehouseNature, c.RackBinCode, b.BranchID, b.CompID  
		     
   Return   
END  
GO

