 CREATE FUNCTION [dbo].[fn_INV_AsOnDate_Stock_Sub] (@StockDate datetime,  @BranchID varchar(3),  @CompID varchar(3),  @Finyear varchar(15))    
  
RETURNS @RetTable TABLE  
 ([ItemCode] [varchar] (20),  
 [WarehouseCode] [varchar] (6),  
 [RackCode] [varchar] (10),  
 [CBQty] [float],  
 [BranchID] [varchar] (3),  
 [CompID] [varchar] (3)  
 )  
  
 AS    
  
 BEGIN   
  Insert @RetTable  
  
   Select a.ItemCode, c.WarehouseCode, '' as RackCode,  
    IsNull(Sum(Case When b.ToWarehouseCode = c.WarehouseCode Then b.TransactionQty Else -b.TransactionQty End), 0) as CbQty,  
  
    a.BranchID, a.CompID  
  
   From Inv_Material_Master a  
     
   Full Outer Join Inv_MaterialTran_Dtl b On a.ItemCode = b.TransactionItem and a.BranchID = b.BranchID and a.CompID = b.CompID  
  
   Full Outer Join (select * from Inv_Warehouse_Master  
     union  
     SELECT  CONVERT(varchar, PartyCode)Code,CONVERT(varchar, PartyCode)Name,'' n,''l,'1' s,''u,'00' b,'01',@StockDate c FROM    
     FAS_Party_MAster WHERE IsSubContractor = 1) c On c.BranchID = b.BranchID and c.CompID = b.CompID  
  
   Where c.WarehouseCode not in (select WarehouseCode from Inv_Warehouse_Master) --and b.ToWarehouseCode  not in (select WarehouseCode from Inv_Warehouse_Master)   
    and b.TransactionDate <= @StockDate  and a.BranchID = @BranchID and a.CompID = @CompID  
    ---and b.Finyear = @Finyear   
   
   group by a.Itemcode, c.WarehouseCode, a.BranchID, a.CompID  
  
  Return   
  
 END
GO

