		Insert @RetTable

			Select a.ItemCode, '' as RackCode,
				IsNull(Sum(Case When b.ToWarehouseCode = @WHSCode Then b.TransactionQty Else -b.TransactionQty End), 0) as CbQty,
				a.BranchID, a.CompID
			From Inv_Material_Master a	
			Full Outer Join Inv_MaterialTran_Dtl b 
				On a.ItemCode = b.TransactionItem and a.BranchID = b.BranchID and a.CompID = b.CompID
			Where @WHSCode in (b.FromWarehouseCode, b.ToWarehouseCode)
				and b.TransactionDate <= @StockDate  and a.BranchID = @BranchID and a.CompID = @CompID
/*				and b.Finyear = @Finyear	*/
	
			group by a.Itemcode, a.BranchID, a.CompID

		Return 

	END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_INV_AsOnDate_Stock_WHSRackBin]    Script Date: 17/06/2026 11:38:46 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_INV_AsOnDate_Stock_WHSRackBin](@WHSCode varchar(6), @RackBinCode VARCHAR(6), 
	@StockDate datetime, @BranchID varchar(3),  @CompID varchar(3),  @Finyear varchar(15))                      
RETURNS @RetTable TABLE    
 ([ItemCode]        [varchar] (20),     
  [CBQty]           [float],    
  [BranchID]        [varchar] (3),    
  [CompID]          [varchar] (3)    
 )                    
AS                      
BEGIN                  
    Insert @RetTable    
     Select b.TransactionItem as ItemCode,           
		IsNull(Sum(Case When (b.ToWarehouseCode = @WHSCode and b.ToRackBinCode=@RackBinCode) Then b.TransactionQty       
        When (b.FromWarehouseCode = @WHSCode and b.FromRackBinCode=@RackBinCode) Then -b.TransactionQty      
			Else 0 End), 0) as CBQty,          
		b.BranchID, b.CompID          
     From Inv_MaterialTran_Dtl b        
     Where @WHSCode in (b.FromWarehouseCode, b.ToWarehouseCode)  and @RackBinCode in (b.FromRackBinCode, b.ToRackBinCode)    
      and b.TransactionDate <= @StockDate  and b.BranchID = @BranchID and b.CompID = @CompID          
      --and b.Finyear = @Finyear           
    Group by b.TransactionItem, b.BranchID, b.CompID          
          
 Return    
END
GO

