CREATE FUNCTION [dbo].[fn_INV_AsOnDate_Stock_WIP] (@StockDate datetime, 
	@BranchID varchar(3), @CompID varchar(3),  @Finyear varchar(15))            
RETURNS @RetTable TABLE            
 ([ItemCode] [varchar] (20),            
 [WarehouseCode] [varchar] (6),            
 [RackCode] [varchar] (10),            
 [CBQty] [float],            
 [BranchID] [varchar] (3),            
 [CompID] [varchar] (3)            
 )                        
AS                          
BEGIN             
  Insert @RetTable                        
	Select b.TransactionItem as ItemCode, c.WarehouseCode, '' as RackCode,            
		IsNull(ROUND(Sum(Case When b.ToWarehouseCode = c.WarehouseCode Then (b.TransactionQty/Norms) Else (-b.TransactionQty/Norms) End),0), 0) as CbQty, 
		b.BranchID, b.CompID            
	From Inv_WIPTran_Dtl b                        
	Full Outer Join (Select 'WIP' as WarehouseCode, @BranchID as BranchID,  @CompID as CompID) c     
		On c.BranchID = b.BranchID and c.CompID = b.CompID                        
	Where c.WarehouseCode in (b.FromWarehouseCode, b.ToWarehouseCode)            
		--and b.TransactionDate <= @StockDate      
	  and b.TransactionDate <= convert(varchar(10), @StockDate,120) and convert(varchar(8),b.TransactionTime,108) <= convert(varchar(8), @StockDate,108)  
	  and b.BranchID = @BranchID and b.CompID = @CompID            
		--and b.Finyear = @Finyear                         
	Group by b.TransactionItem, c.WarehouseCode, b.BranchID, b.CompID
   
  Return                         
END
