  [CBQty]   [float],    
  [BranchID]   [varchar] (3),    
  [CompID]   [varchar] (3)    
 )    
 AS      
 BEGIN     
   Insert @RetTable   
    Select b.ItemCode, c.WarehouseCode, '' as RackCode, b.LotID,  
      IsNull(Sum(Case When b.ToWarehouseCode = c.WarehouseCode Then b.Qty Else -b.Qty End), 0) as CbQty,         
      b.BranchID, b.CompID    
    From COM_Trace_MaterialTran_TmpQty b     
     
    Full Outer Join INV_Warehouse_Master_All c     
    On c.BranchID = b.BranchID and c.CompID = b.CompID    

	--Left outer Join COM_Trace_MaterialTran_TmpQty d
