/****** Object:  UserDefinedFunction [dbo].[fn_INV_ToolissueStatus]    Script Date: 17/06/2026 11:38:46 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_INV_ToolissueStatus] (@AsOnDate datetime, @ItemCode varchar(20),@MachineCode varchar(20),@ToolCode varchar(20), @ToolAssetCode Varchar(20),@Type char(1),@BranchID varchar(3), @CompID varchar(3))  

RETURNS @RefTbl Table (	
			Code int,
			Description varchar(20)
		 ) 

 AS  

BEGIN 

	Declare @Regrind int
	Declare @Reform int
	Declare @Corner int

	Select @Regrind= isnull(Regrind,0),
		@Corner=isnull(Corner,0),
		@Reform=isnull(Reform,0)
		 from dbo.fn_BOM_Stagewisetoolmaster_dtl( @AsOnDate,@BranchID, @CompID) a
		left outer join BOM_ToolType b on b.ToolTypeCode=a.Typeoftool and b.Branchid=a.Branchid and b.Compid=a.Compid
		where MachineCode=@MachineCode and ItemCode=@ItemCode and ToolCode=@ToolCode

		if not exists(Select * from INV_Tooltran_Dtl where Toolassetcode=@ToolAssetCode and Branchid=@BranchID and Compid=@CompID) 
			Begin 
				insert into  @RefTbl
					Select Code ,Description from INV_ToolStatus_master where Code in (1)
			End 
		Else
			Begin
				if (@Regrind=1) 
					Begin
						if (@Type='R')
							Begin
								insert into  @RefTbl
									Select Code, Description from INV_ToolStatus_master where Code in (6,7,8,9,12)
							End
						Else
		
							Begin
								insert into  @RefTbl
									Select Code ,Description from INV_ToolStatus_master where Code in (2,5)
									and Code not in (Select Case When Rdballife <=0 then 5 else 0 end from dbo.fn_INV_ToolLogStatus(@AsOnDate,@BranchID,@CompID)where MachineCode=@MachineCode and ItemCode=@ItemCode and ToolCode=@ToolCode and @ToolAssetCode=@ToolAssetCode )
									--and Code not in (Select case when Exists (Select * from INV_Tooltran_Dtl where Toolassetcode=@ToolAssetCode and Branchid=@BranchID and Compid=@CompID) then 1 else 0 end )
							End
					End
		
				if (@Reform=1) 
					Begin
						if (@Type='R')
							Begin
								insert into  @RefTbl
									Select Code, Description from INV_ToolStatus_master where Code in (6,7,8,10,12)
							End
						Else
							Begin
								insert into  @RefTbl
									Select Code,Description from INV_ToolStatus_master where Code in (3,5)
									and Code not in (Select Case When Rfmballife <=0 then 5 else 0 end from dbo.fn_INV_ToolLogStatus(@AsOnDate,@BranchID,@CompID)where MachineCode=@MachineCode and ItemCode=@ItemCode and ToolCode=@ToolCode and @ToolAssetCode=@ToolAssetCode )
									--and Code not in (Select case when Exists (Select * from INV_Tooltran_Dtl where Toolassetcode=@ToolAssetCode and Branchid=@BranchID and Compid=@CompID) then 1 else 0 end )
							End
					End
		
				if (@Corner=1) 
					Begin
						if (@Type='R')
							Begin
								insert into  @RefTbl
									Select Code, Description from INV_ToolStatus_master where Code in (6,7,8,11,12)
							End
						Else
							Begin
								insert into  @RefTbl
									Select Code ,Description from INV_ToolStatus_master where Code in (4,5)
									and Code not in (Select Case When Rdballife <=0 then 5 else 0 end from dbo.fn_INV_ToolLogStatus(@AsOnDate,@BranchID,@CompID)where MachineCode=@MachineCode and ItemCode=@ItemCode and ToolCode=@ToolCode and @ToolAssetCode=@ToolAssetCode )
									--and Code not in (Select case when Exists (Select * from INV_Tooltran_Dtl where Toolassetcode=@ToolAssetCode and Branchid=@BranchID and Compid=@CompID) then 1 else 0 end )
							End
					End
				if (@Regrind=0 and @Reform=0 and @Corner=0)
					Begin
						if (@Type='R')
							Begin 
								insert into  @RefTbl
								Select Code, Description from INV_ToolStatus_master where Code in (6,7,8,12)
							End
						Else
							Begin
								insert into  @RefTbl
								Select Code, Description from INV_ToolStatus_master where Code in (5)
							End
							
					End
			End
	Return

End
GO

/****** Object:  UserDefinedFunction [dbo].[fn_INV_TrayBase_ToolStatus]    Script Date: 17/06/2026 11:38:47 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_INV_TrayBase_ToolStatus] (@AsOnDate datetime, @ItemCode varchar(20),@MachineCode varchar(20),@Qty  int,@BranchID varchar(3), @CompID varchar(3))  

RETURNS @RefTbl Table (	
			Qno int,
			ToolCode varchar(20),
			Description varchar(20)

		 ) 

 AS  

BEGIN 
	Declare @TCode varchar(20)
	Declare @Totallife int
	Declare @Regrindlife int
	Declare @Reformlife int
	Declare @ballife int
	Declare @Rdballife int
	Declare @Rfmballife int
	Declare @RegQty int
	Declare @RfmQty int

	Declare tmpCur Cursor for
		Select a.Toolcode,Totallife,Regrindlife,Reformlife,ballife,Rdballife,Rfmballife from dbo.fn_INV_ToolTran_Dtl(@AsOnDate, @BranchID, @CompID)a 
			left outer join dbo.fn_INV_ToolLogStatus(@AsOnDate, @BranchID, @CompID)b
				on b.MachineCode=a.MachineCode and b.ItemCode=a.StageCode and b.ToolCode=a.ToolCode and b.ToolAssetCode=a.ToolAssetcode
			and b.Branchid=a.Branchid and b.Compid=a.Compid
			Where  a.MachineCode=@MachineCode and a.StageCode=@ItemCode 
	Open tmpCur

		FETCH NEXT FROM tmpCur into @TCode,@Totallife, @Regrindlife,@Reformlife,@ballife,@Rdballife,@Rfmballife
	
		WHILE @@FETCH_STATUS = 0				
			Begin			
				Select @RegQty=@Rdballife
				Select @RfmQty=@Rfmballife

				If (@Regrindlife<>-1) --Regrind
					Begin
						While @RegQty<=@Qty
							Begin
								Insert into @RefTbl
									Select @RegQty,@TCode,'REGRIND'

								Select @RegQty=@RegQty+@Regrindlife	
								
							End
					End
				
				If (@Reformlife<>-1) --Reform
					Begin
						While @RfmQty<=@Qty
							Begin
								--if @Rfmballife
								Insert into @RefTbl
									Select @RfmQty,@TCode,'REFORM'

								Select @RfmQty=@RfmQty+@Reformlife	
							End
					End

				if (@Regrindlife=-1)  and  (@Reformlife=-1)
					Begin
						While @ballife<=@Qty
							Begin
								Insert into @RefTbl
									Select @ballife,@TCode,'NEW'

								Select @ballife=@ballife+@Totallife	
							End
					End
				FETCH NEXT FROM tmpCur into @TCode,@Totallife, @Regrindlife,@Reformlife,@ballife,@Rdballife,@Rfmballife
			End
		
	Close tmpCur
	Deallocate tmpCur 	

	Return

End
GO

/****** Object:  UserDefinedFunction [dbo].[fn_ItemGroupKey]    Script Date: 17/06/2026 11:38:47 ******/
SET ANSI_NULLS OFF
GO

