GO

CREATE Function [dbo].[fn_ItemGroupKey](@ToItemCode varchar(20),@Branchid varchar(3),@compid varchar(3))

Returns @RetTbl Table
		(ItemGroupKey int,
		FromCode varchar(8000),
		ToCode varchar(20),
		RelationType varchar(5),
		Branchid varchar(3),
		Compid varchar(3)
		)
as
begin

	Declare @ItemGroupKey int
	Declare	@ToCode varchar(20)
	Declare	@FromCode varchar(20)
	Declare	@strFromCode varchar(8000)
	Declare	@RelationType varchar(5)
	
	if @ToItemCode<>'ALL' 	
		Begin
			Declare curRec cursor for
				select distinct  ItemGroupKey,ToCode from ITemGroupKey_Dtl where ToCode=@ToItemCode
				and Branchid=@Branchid and Compid=@compid
				group by ItemGroupKEy,ToCode order by ItemGroupKey
		end
	else
		Begin
			Declare curRec cursor for
				select distinct  ItemGroupKey,ToCode from ITemGroupKey_Dtl where  Branchid=@Branchid and Compid=@compid
				group by ItemGroupKEy,ToCode order by ItemGroupKey
		end

	open curRec
	
	Fetch next from curRec into @ItemGroupKey,@ToCode
	
	while @@Fetch_Status=0
		begin
			Declare curFrom cursor for

				select distinct FromCode ,RelationType from ITemGroupKey_Dtl where ItemGroupKey=@ItemGroupKey
				order by FromCode

			open curFrom

				Fetch next from curFrom into @FromCode,@RelationType
				select @strFromCode=''
				while @@Fetch_Status=0
					begin
						select @strFromCode=@strFromCode+@FromCode
						Fetch next from curFrom into @FromCode,@RelationType
					end
				close curFrom
				Deallocate curFrom
				
			insert into @RetTbl (ItemGroupKey,FromCode,ToCode,RelationType,Branchid,Compid)
									values (@ItemGroupKey,@strFromCode,@ToCode,@RelationType,@Branchid,@compid)

			Fetch next from curRec into @ItemGroupKey,@ToCode
		end
		
    Close curRec
    Deallocate curRec
 
	return
end
GO

/****** Object:  UserDefinedFunction [dbo].[fn_ItemWiseChild]    Script Date: 17/06/2026 11:38:47 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE  FUNCTION [dbo].[fn_ItemWiseChild] (@BranchID varchar(3), @CompID varchar(3))  

RETURNS @RetTable TABLE

	(ParentCode varchar(20),
	 ChildCode varchar(20),
	 Norms	float,	
	 Rate	float		
	)

 AS  

BEGIN    
	
	Declare @Item varchar(20)
	Declare @Child varchar(20)
	Declare @Norms float
	Declare @Rate float	
	
	  
	  Declare curItem Cursor For
	
		Select Distinct Itemcode from SAL_Invoice_Dtl where Branchid=@BranchID and Compid=@CompID
  
	   Open curItem
	   
	   FETCH NEXT FROM curItem into  @Item
	   
	   	WHILE @@FETCH_STATUS = 0
	
	    		Begin
	       			Declare CurChild Cursor For	
	    			 	Select Distinct @Item,a.ItemCode,a.Qty,dbo.fn_WtAvgRate(a.ItemCode,'2007-01-01','2008-11-01',a.Branchid,a.Compid,'04-2008 03-2009')From dbo.fn_BOM_GetBottomMostChild(@Item, @BranchID, @CompID)a
		     			
					 Open CurChild

	      				       FETCH NEXT FROM CurChild into  @Item,@Child,@Norms,@Rate
	   
			 			  WHILE @@FETCH_STATUS = 0
			
			    				Begin
					   			insert into @RetTable
									Select @Item,@Child,@Norms,@Rate
										Where not exists (Select * from @RetTable where ParentCode=@Item and ChildCode=@Child)

								FETCH NEXT FROM CurChild into  @Item,@Child,@Norms,@Rate
			   				 End

				Close CurChild
	   			Deallocate CurChild
				
				 FETCH NEXT FROM curItem into  @Item
			End
	   
	   Close curItem
	   Deallocate curItem
	 
	 Return 		

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_ENG_BOMVsConsumptionValueReport]    Script Date: 17/06/2026 11:38:47 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

/****** Object:  User Defined Function dbo.fn_MIS_ENG_BOMVsConsumptionValueReport    Script Date: 05/11/2008 5:15:51 PM ******/

CREATE   FUNCTION [dbo].[fn_MIS_ENG_BOMVsConsumptionValueReport] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

 (YearMonth varchar(7),
  DataValue1  float
 )

 AS  

BEGIN    	

	  Declare @Start as datetime, @End as datetime
	
	  Select @Start=Convert(datetime, @FromDate+'-01', 120)
	
	  Select @End=DateAdd(day, -1, DateAdd(mm, 1,  Convert(datetime, @ToDate+'-01', 120)))
	
	
	  Declare @Period as varchar(7), @Item as varchar(30), @InvQty as float
	  Declare @TotValue as money, @BOMvalue as money 
	  
	  
	  Declare curItem Cursor For
	
	   Select convert(varchar(7), a.InvoiceDate, 120) InvoiceMonth , a.ItemCode, sum(a.InvoiceQty) as InvQty
	   From SAL_Invoice_Dtl a 
	   Where a.InvoiceDate between @Start and @End and a.Branchid=@BranchID and a.Compid=@CompID 
	   Group by convert(varchar(7), a.InvoiceDate, 120), a.ItemCode 
	   Order by a.ItemCode,  1	
	  
	   Open curItem
	   
	   FETCH NEXT FROM curItem into @Period, @Item, @InvQty 
	   
	   WHILE @@FETCH_STATUS = 0
	
	    Begin
	       
	
	     Select @BOMValue=(a.Qty*b.Rate) 
	     From dbo.fn_BOM_GetBottomMostChild(@Item, @BranchID, @CompID)a
	      Left Outer Join INV_Material_Master b
	       On a.ItemCode=b.ItemCode and a.Branchid=b.Branchid and a.Compid=b.Compid
	     
	     If Exists (Select * from @RetTable Where YearMonth=@Period)

		      Begin

			       Update @RetTable Set DataValue1=DataValue1 + (isNull(@BOMValue, 0) * @InvQty)
			       Where YearMonth=@Period

		      End

	     Else

		      Begin

			       Insert @RetTable
			       Select @Period, (isNull(@BOMValue, 0) * @InvQty)

		      End
	  
	     FETCH NEXT FROM curItem into @Period, @Item, @InvQty 
	   
	    End
	   
	   
	   Close curItem
	   Deallocate curItem			
	 
	 Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_ENG_BOMVsSaleAsPercentageReport]    Script Date: 17/06/2026 11:38:47 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

/****** Object:  User Defined Function dbo.fn_MIS_ENG_BOMVsSaleAsPercentageReport    Script Date: 05/11/2008 5:15:51 PM ******/

CREATE  FUNCTION [dbo].[fn_MIS_ENG_BOMVsSaleAsPercentageReport] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth	varchar(7),
	 DataValue1	float		--Percentage
	)

 AS  

BEGIN    
	
	  Declare @Start as datetime, @End as datetime
	
	  Select @Start=Convert(datetime, @FromDate+'-01', 120)
	
	  Select @End=DateAdd(day, -1, DateAdd(mm, 1,  Convert(datetime, @ToDate+'-01', 120)))
	
	
	  Declare @Period as varchar(7), @Item as varchar(30), @SalVal as float
	  Declare @TotValue as money, @BOMvalue as money 
	  
	  
	  Declare curItem Cursor For
	
	Select Convert(VarChar(7),s.InvoiceDate,126) As YearMonth,  s.ItemCode,
		IsNull(sum(s.InvoiceQty*s.Rate),0)  As SalesValue
	From SAL_Invoice_Dtl s 
	Where Convert(VarChar(7),s.InvoiceDate,126) Between @FromDate and @ToDate		
		and s.Branchid=@BranchID and s.Compid=@CompID 
	Group by Convert(VarChar(7),s.InvoiceDate,126), s.ItemCode 
	Order by s.ItemCode,  1
  
	   Open curItem
	   
	   FETCH NEXT FROM curItem into @Period, @Item, @SalVal 
	   
	   WHILE @@FETCH_STATUS = 0
	
	    Begin
	       
	
	     Select @BOMValue=(a.Qty*b.Rate) 
	     From dbo.fn_BOM_GetBottomMostChild(@Item, @BranchID, @CompID)a
	      Left Outer Join SAL_Invoice_Dtl b
	       On a.ItemCode=b.ItemCode and a.Branchid=b.Branchid and a.Compid=b.Compid
	     
	     If Exists (Select * from @RetTable Where YearMonth=@Period)

		      Begin

			       Update @RetTable Set DataValue1=DataValue1 + (isNull(@BOMValue, 0)/IsNull(@SalVal,0))*100
			       Where YearMonth=@Period

		      End

	     Else

		      Begin

			       Insert @RetTable
			       Select @Period,  (isNull(@BOMValue, 0)/IsNull(@SalVal,0))*100

		      End
	  
	     FETCH NEXT FROM curItem into @Period, @Item, @SalVal 
	   
	    End
	   
	   
	   Close curItem
	   Deallocate curItem
	 
	 Return 		

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_FAM_DepreciationReport]    Script Date: 17/06/2026 11:38:47 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

/****** Object:  User Defined Function dbo.fn_MIS_FAM_DepreciationReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_FAM_DepreciationReport    Script Date: 24/09/2008 4:21:15 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_FAM_DepreciationReport] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float		--Depreciation
	)

 AS  

BEGIN 			

		Insert @RetTable
	
		Select y.YearMonth, Sum(y.Depreciation) As DataValue1 	
		From ( 
			Select x.AssetCode, x.ItemCode, x.DeprDate As YearMonth, x.Depreciation, x.Rate 
			From ( 
				Select a.AssetCode, a.ItemCode, IsNull(Convert(VarChar(7),d.DepreciationPeriod,126),'') As DeprDate, 
					d.DepreciationValue As Depreciation, 
					IsNull((Select Top 1 CActSLM From FAM_AssetDepreciation_Master 
					           Where ClassificationCode = A.ClassificationCode and SubClassificationCode=a.SubClassificationCode 
							and BranchID=a.BranchID and CompID=a.CompID
					),'0.0') As Rate 
				From FAM_Asset_Master a 
				Left Outer Join FAM_DepreciationProcess d 
				On a.AssetCode=d.AssetCode and a.ItemCode=d.ItemCode and a.BranchID=d.BranchID and a.CompID=d.CompID 
				Where Convert(VarChar(7),d.DepreciationPeriod,126) Between @FromDate and @ToDate
					and a.Branchid=@BranchID and a.Compid=@CompID
			) x 
		) y 
		Group By y.YearMonth 
		Having Sum(y.Depreciation) <> 0				
	
	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_FAM_GrossBlockReport]    Script Date: 17/06/2026 11:38:47 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

/****** Object:  User Defined Function dbo.fn_MIS_FAM_GrossBlockReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_FAM_GrossBlockReport    Script Date: 24/09/2008 4:21:15 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_FAM_GrossBlockReport] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float	--GrossBlock
	)

 AS  

BEGIN 			

		Insert @RetTable
	
		Select y.YearMonth, Sum(y.AsOnGrossBlock) As DataValue1 	
		From ( 
			Select x.AssetCode, x.ItemCode, x.ClassificationCode,
				x.InvDate As YearMonth, ((x.CostasOn+x.Addition)-x.SoldValue) As AsOnGrossBlock, 
				x.Rate From (
						Select a.AssetCode, a.ItemCode, a.ClassificationCode, 
							IsNull(Convert(VarChar(7),c.InvoiceDate,126),'') As InvDate, 
							Case When Convert(VarChar(7),a.RealiseDate,126) < @FromDate  Then a.TotalValue Else 0 End As CostAsOn, 
							Case When Convert(VarChar(7),a.RealiseDate,126) Between @FromDate and @ToDate Then a.TotalValue Else 0 End As Addition, 
							Case When Convert(VarChar(7),c.InvoiceDate,126) Between @FromDate and @ToDate Then c.TotalAmount Else 0 End As SoldValue, 
							IsNull((Select Top 1 CActSLM 
								From FAM_AssetDepreciation_Master 
								Where ClassificationCode=a.ClassificationCode and SubClassificationCode=a.SubClassificationCode 
									and BranchID=a.BranchID and CompID=a.CompID
							          ),'0.0') As Rate 
						From FAM_Asset_Master a 
						Left Outer Join SalesInvoice c 
						On c.ItemCode=a.ItemCode and c.Branchid=a.Branchid and c.Compid=a.Compid 
						Where a.Branchid=@BranchID and a.Compid=@CompID
					        ) x 
		) y 
		Group By y.YearMonth 
		Having Sum(y.AsOnGrossBlock)<>0					
	
	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_FAM_NetBlockReport]    Script Date: 17/06/2026 11:38:47 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

/****** Object:  User Defined Function dbo.fn_MIS_FAM_NetBlockReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_FAM_NetBlockReport    Script Date: 24/09/2008 4:21:15 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_FAM_NetBlockReport] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float		--NetBlock 
	)

 AS  

BEGIN 			

		Insert @RetTable
	
		Select y.YearMonth, Sum((y.AsOnGrossBlock-y.UpToEnd)) As DataValue1	
		From ( 
			Select x.AssetCode, x.ItemCode, x.ClassificationCode, x.InvDate As YearMonth, 
				((x.CostasOn+x.Addition)-x.SoldValue) As AsOnGrossBlock, (x.PrevDeprUpTo+x.CurrDepr) As UpToEnd, x.Rate 
			From ( 
				Select a.AssetCode, a.ItemCode, a.ClassificationCode, 
					IsNull(Convert(VarChar(7),a.RealiseDate,126),'') As RealDate, 
					IsNull(Convert(VarChar(7),c.InvoiceDate,126),'') As InvDate, 
					IsNull(Convert(VarChar(7),d.DepreciationPeriod,126),'') As DeprDate, 
					Case When Convert(VarChar(7),a.RealiseDate,126)<@FromDate Then a.TotalValue Else 0 End As CostAsOn, 
					Case When Convert(VarChar(7),a.RealiseDate,126) Between @FromDate and @ToDate Then a.TotalValue Else 0 End As Addition,
					Case When Convert(VarChar(7),c.InvoiceDate,126) Between @FromDate and @ToDate Then c.TotalAmount Else 0 End As SoldValue, 
					Case When Convert(VarChar(7),d.DepreciationPeriod,126)<@FromDate Then d.DepreciationValue Else 0 End As PrevDeprUpTo, 
					Case When Convert(VarChar(7),d.DepreciationPeriod,126) Between @FromDate and @ToDate Then d.DepreciationValue Else 0 End as CurrDepr, 
					IsNull((Select Top 1 CActSLM 
					           From FAM_AssetDepreciation_Master 
					           Where ClassificationCode = A.ClassificationCode and SubClassificationCode=a.SubClassificationCode 
							and BranchID=a.BranchID and CompID = a.CompID
					          ),'0.0') As Rate 
				From FAM_Asset_Master a 
				Left Outer Join SalesInvoice c 
				On c.ItemCode=a.ItemCode and c.Branchid=a.Branchid and c.Compid=a.Compid 
				Left Outer Join FAM_DepreciationProcess d 
				On a.AssetCode=d.AssetCode and a.ItemCode=d.ItemCode and a.BranchID=d.BranchID and a.CompID=d.CompID 
				Where a.Branchid=@BranchID and a.Compid=@CompID
			     ) x 
		) y 
		Group By y.YearMonth
		Having Sum((y.AsOnGrossBlock-y.UpToEnd))<>0	
	
	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_HRD_HeadCountReport]    Script Date: 17/06/2026 11:38:47 ******/
SET ANSI_NULLS OFF
GO

