GO

/****** Object:  User Defined Function dbo.fn_MIS_HRD_HeadCountReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_HRD_HeadCountReport    Script Date: 24/09/2008 4:21:15 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_HRD_HeadCountReport] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float		--HeadCount
	)

 AS  

BEGIN 			

		Insert @RetTable
	
		select convert(VarChar(7),b.ProcessMonth,126) as YearMonth,Count(distinct b.EmployeeCode) As DataValue1
		from PAY_ProcessResult b 
		where convert(VarChar(7),b.ProcessMonth,126) between @FromDate
			and @ToDate and b.Branchid = @BranchID and b.Compid = @CompID
		group by convert(VarChar(7),ProcessMonth,126),ProcessMonth
	
	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_HRD_TurnOverPerEmployeeReport]    Script Date: 17/06/2026 11:38:47 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

/****** Object:  User Defined Function dbo.fn_MIS_HRD_TurnOverPerEmployeeReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_HRD_TurnOverPerEmployeeReport    Script Date: 24/09/2008 4:21:15 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_HRD_TurnOverPerEmployeeReport] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float		--TurnOverPerEmp
	)

 AS  

BEGIN 			

		Insert @RetTable
	
		select x.YearMonth, (x.TotalAmount/y.HeadCount) as DataValue1 
		from 		
			(  select convert(VarChar(7),a.InvoiceDate,126) As YearMonth, sum(a.TotalAmount) as TotalAmount 
			   from SAL_Invoice_Hdr a 
			   where convert(VarChar(7),a.InvoiceDate,126) between @FromDate and @ToDate 
				and Branchid = @BranchID and Compid = @CompID and Finyear = @Finyear
			   group by convert(VarChar(7),a.InvoiceDate,126)
			) x
		
		full outer join
		
			(select convert(VarChar(7),b.ProcessMonth,126) as YearMonth,Count(distinct b.EmployeeCode) HeadCount
			 from PAY_ProcessResult b 
			 where convert(VarChar(7),b.ProcessMonth,126) between @FromDate and @ToDate 
				and b.Branchid = @BranchID and b.Compid = @CompID
			group by convert(VarChar(7),ProcessMonth,126)
			) y
		
		on x.YearMonth = y.YearMonth
	
	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_INV_ConsumptionAsaPercentageofSalesReport]    Script Date: 17/06/2026 11:38:47 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

/****** Object:  User Defined Function dbo.fn_MIS_INV_ConsumptionAsaPercentageofSalesReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_INV_ConsumptionAsaPercentageofSalesReport    Script Date: 24/09/2008 4:21:16 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_INV_ConsumptionAsaPercentageofSalesReport] (@FromDate varchar(10), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float		--PerSale
	)

 AS  

BEGIN 			


		Insert @RetTable

		Select y.YearMonth, Case When SalesValue<>0 Then (ConsValue/SalesValue)*100 Else 0 End As DataValue1 
		From (
			Select Convert(varchar(7),@ToDate, 126) As YearMonth, IsNull(Sum(x.ConsValue),0) As ConsValue, 
			IsNull(Sum(x.SalesValue),0) As SalesValue 
			From ( 
				Select s.ItemCode, m.ItemDescription, s.WarehouseCode, s.CBQty, m.Rate, 
				(IsNull(s.CBQty,0)*m.Rate) ConsValue, s.Branchid, s.Compid, IsNull(v.SalesValue,0) As SalesValue 
				From fn_INV_AsOnDate_Stock (@FromDate,@BranchID,@CompID,@Finyear) s 
				Left Outer Join INV_WAREHOUSE_MASTER w 
				On s.WarehouseCode=w.WarehouseCode and w.WarehouseStatus=1  
				and w.Branchid=s.Branchid and w.Compid=s.Compid 
				Left Outer Join MATERIAL_MASTER m 
				On s.ItemCode=m.ItemCode and s.Branchid=m.Branchid and s.Compid=m.Compid 
				Full Outer Join ( 
						 Select i.Itemcode, IsNull(Sum(i.SalesValue),0) As SalesValue, i.Branchid, i.Compid 
						 From (
							Select i.ItemCode, (IsNull(i.InvoiceQty,0)*m.Rate) As SalesValue, i.Branchid, i.Compid 
							From SAL_Invoice_Dtl i 
							Left Outer Join Material_Master m 
							On i.ItemCode=m.ItemCode and i.Branchid=m.Branchid and i.Compid=m.Compid 
							Where m.Status=1 and Convert(varchar(7),i.InvoiceDate,126)=Convert(varchar(7),@ToDate,126)
								and i.Branchid=@BranchID and i.Compid=@CompID	--'and i.Finyear=@Finyear
						      ) i Group by i.ItemCode, i.Branchid, i.Compid 
						) v 
				On s.ItemCode=v.ItemCode and s.Branchid=v.Branchid and s.Compid=v.Compid 
				Where m.Status=1 and w.WarehouseNature In('InHouse') 
					and s.Branchid=@BranchID and s.Compid=@CompID	--'and s.Finyear=@Finyear
			     ) x 
		) y 
		Order by y.YearMonth

	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_INV_ConsumptionReport]    Script Date: 17/06/2026 11:38:47 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

/****** Object:  User Defined Function dbo.fn_MIS_INV_ConsumptionReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_INV_ConsumptionReport    Script Date: 24/09/2008 4:21:16 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_INV_ConsumptionReport] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float,		--RecQty
	 DataValue2	float		--IssQty
	)

 AS  

BEGIN 			

		Insert @RetTable

		Select x.YearMonth, Sum(x.ReceivedQty) As DataValue1,Sum(x.IssuedQty) As DataValue2 
		From ( Select m.ItemCode, Convert(varchar(7),t1.DocDate,126)As YearMonth, 
				(IsNull(t1.TransactionQty,0)*m.Rate) As ReceivedQty, 
				(IsNull(t2.TransactionQty,0)*m.Rate) As IssuedQty 
			From Material_Master m 
			Left Outer Join Inv_MaterialTran_Dtl t1 
			On t1.Doctype In (Select Documenttype From COM_DOCUMENTTYPE_MASTER 
					   Where PertainingTo='R' and ModuleName='REC' 
						 and Branchid=@BranchID and Compid=@CompID 	--and Finyear=@Finyear
					 ) 
			      and Convert(varchar(7),t1.DocDate,126)  Between @FromDate and @ToDate
			      and IsNumeric(t1.FromwarehouseCode)=1 and t1.TowarehouseCode ='UI' and t1.TransactionItem=m.ItemCode 
			      and m.Branchid=t1.Branchid and m.Compid=t1.Compid 
			Left Outer Join Inv_MaterialTran_Dtl t2 
			On t2.Doctype In (Select Documenttype From COM_DOCUMENTTYPE_MASTER 
			   		   Where PertainingTo='R' and ModuleName='REC' 
						 and Branchid=@BranchID and Compid=@CompID 	--and Finyear=@Finyear
					 ) 
			     and Convert(varchar(7),t2.DocDate,126) Between @FromDate and @ToDate
			     and t2.ToWarehouseCode In('WIP') and t2.TransactionItem=m.ItemCode 
			     and m.Branchid=t2.Branchid and m.Compid=t2.Compid 
		Where m.Branchid=@BranchID and m.Compid=@CompID 		--and m.Finyear=@Finyear
		) x 
		Group by x.YearMonth
		Order by x.YearMonth
			         	
	Return 

END
GO

