/****** Object:  User Defined Function dbo.fn_MIS_INV_StockReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_INV_StockReport    Script Date: 24/09/2008 4:21:16 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_INV_StockReport] (@FromDate varchar(10), @ToDate varchar(8), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float		--Value
	)

 AS  

BEGIN 			

		Insert @RetTable
	
		Select Convert(varchar(7),@ToDate, 126) As YearMonth, Sum(x.Value) As DataValue1
		From (
		Select s.ItemCode, m.ItemDescription, s.WarehouseCode,
			s.CBQty, m.Rate, (s.CBQty*m.Rate) As Value
		From fn_INV_AsOnDate_Stock (@FromDate,@BranchID,@CompID,@Finyear) s
		Left Outer Join INV_WAREHOUSE_MASTER w
		On s.WarehouseCode=w.WarehouseCode and w.WarehouseStatus=1
			and w.Branchid=s.Branchid and w.Compid=s.Compid
		Left Outer Join MATERIAL_MASTER m
		On s.ItemCode=m.ItemCode and s.Branchid=m.Branchid and s.Compid=m.Compid
		Where m.Status=1 and w.WarehouseNature In('InHouse')
			and s.Branchid=@BranchID and s.Compid=@CompID	--'and s.Finyear=@Finyear
		) x

	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_MAINT_BreakDownHoursReport]    Script Date: 17/06/2026 11:38:47 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

/****** Object:  User Defined Function dbo.fn_MIS_MAINT_BreakDownHoursReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_MAINT_BreakDownHoursReport    Script Date: 24/09/2008 4:21:16 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_MAINT_BreakDownHoursReport] (@CurrDate datetime, @EquipCode varchar(20), @FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 TotHrs		float
	)

 AS  

BEGIN 			

		Insert @RetTable

		Select y.YearMonth, Sum(y.TotHrs) As TotHrs
		From
		(
			Select x.YearMonth, Datediff(hh,x.BRDate,x.STDate) As TotHrs				
			From (
			Select Convert(varchar(7),m.BreakdownDate,126) As YearMonth,
			( Convert(varchar(10),m.BreakdownDate,126)+' '+Convert(varchar(8),m.BreakdownTime,108)) As BRDate,
				Case When IsNull(CompletedDate,0)=0 Then @CurrDate
			 Else
				(Convert(varchar(10),m.CompletedDate,126)+' '+Convert(varchar(8),m.CompletedDate,108)) 
			 End As STDate
			 From MAINT_BreakdownRegistration m
			 Where m.EquipmentCode=@EquipCode
				and Convert(varchar(7),m.BreakdownDate,126) Between @FromDate and @ToDate
				and m.Branchid=@BranchID and m.Compid=@CompID and m.Finyear=@Finyear
			) x
		) y
		Group by y.YearMonth
		Order by y.YearMonth		
	
	Return 

END
GO

