CREATE FUNCTION [dbo].[fn_MIS_MAINT_PreventiveMaintenanceCostReport] (@CurrDate datetime, @EquipCode varchar(20), @FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 PMValue		float
	)

 AS  

BEGIN 			

		Insert @RetTable
		
		Select Convert(varchar(7),s.StoreRequestDate,126) As YearMonth, Sum(s.IssuedQty) As PMValue
		From INV_STOREREQUEST_DTL s
		Where Convert(varchar(7),s.StoreRequestDate,126) Between  @FromDate and @ToDate
			and s.ReturnQty=0
		and s.Branchid=@BranchID and s.Compid=@CompID and s.Finyear=@Finyear
		Group by Convert(varchar(7),s.StoreRequestDate,126)
	
	Return 

END
