/****** Object:  UserDefinedFunction [dbo].[fn_MIS_MAINT_PreventiveMaintenanceHoursReport]    Script Date: 17/06/2026 11:38:47 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

/****** Object:  User Defined Function dbo.fn_MIS_MAINT_PreventiveMaintenanceHoursReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_MAINT_PreventiveMaintenanceHoursReport    Script Date: 24/09/2008 4:21:16 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_MAINT_PreventiveMaintenanceHoursReport] (@CurrDate datetime, @EquipCode varchar(20), @FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 TotHrs		float
	)

 AS  

BEGIN 			

		Insert @RetTable

		Select y.YearMonth, Sum(y.TotHrs) As TotHrs
		From
		(
			Select x.YearMonth, Datediff(hh,x.ActDate,x.STDate) As TotHrs	
			From (
				Select Convert(varchar(7),m.ActivityStartDate,126) As YearMonth,
					m.ActivityStartDate As ActDate,
				
				Case When IsNull(s.CompletedDate,0)=0 Then 
					@CurrDate
				Else
					(Convert(varchar(10),s.CompletedDate,126)+' '+Convert(varchar(8),s.CompletedDate,108)) 
				End As STDate
				From MAINT_EquipmentActivity_Master m
				Left Outer Join MAINT_EquipmentActivity_Schedule s
				On m.EquipmentCode=s.EquipmentCode and m.Branchid=s.Branchid and m.Compid=s.Compid
				Where m.EquipmentCode=@EquipCode
					and Convert(varchar(7),m.ActivityStartDate,126) Between @FromDate and @ToDate
					and m.Branchid=@BranchID and m.Compid=@CompID
			) x
		) y
		Group by y.YearMonth
		Order by y.YearMonth


	
	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_PAY_AbsanteesmAsaPercentageReport]    Script Date: 17/06/2026 11:38:47 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

/****** Object:  User Defined Function dbo.fn_MIS_PAY_AbsanteesmAsaPercentageReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_PAY_AbsanteesmAsaPercentageReport    Script Date: 24/09/2008 4:21:16 PM ******/

CREATE  FUNCTION [dbo].[fn_MIS_PAY_AbsanteesmAsaPercentageReport] (@EmpCode As varchar(10), @FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float		--AbsPerc
	)

 AS  

BEGIN 			
	If @EmpCode<>''
		
		Begin

			Insert @RetTable
		
			Select x.YearMonth, Case When x.TotWkDays<>0 Then ((x.AbsentDays/x.TotWkDays)*100) Else 0 End As DataValue1
			From (
				Select  Convert(varchar(7),e.DateIn,120) As YearMonth,
				Sum(IsNull(Case When e.Present Not In('Absent','Holiday') Then
					Case When e.Present = 'Full Day' Then 1 Else 0.5 End
				End,0)) As TotWkDays,
				
				Sum(IsNull(Case When e.Present In('Absent') Then
					Case When e.Present = 'Full Day' Then 1 Else 0.5 End
				End,0)) As AbsentDays
				
				From PAY_Time_Entry e 
				Where Convert(varchar(7),e.DateIn,120) Between @FromDate and @ToDate
					and e.Branchid=@BranchID and e.Compid=@CompID
					and e.EmployeeCode=@EmpCode
				Group by Convert(varchar(7),e.DateIn,120)
			) x
			Order by x.YearMonth

		End

	Else

		Begin

			Insert @RetTable
		
			Select x.YearMonth, Case When x.TotWkDays<>0 Then ((x.AbsentDays/x.TotWkDays)*100) Else 0 End As DataValue1
			From (
				Select  Convert(varchar(7),e.DateIn,120) As YearMonth,
				Sum(IsNull(Case When e.Present Not In('Absent','Holiday') Then
					Case When e.Present = 'Full Day' Then 1 Else 0.5 End
				End,0)) As TotWkDays,
				
				Sum(IsNull(Case When e.Present In('Absent') Then
					Case When e.Present = 'Full Day' Then 1 Else 0.5 End
				End,0)) As AbsentDays
				
				From PAY_Time_Entry e 
				Where Convert(varchar(7),e.DateIn,120) Between @FromDate and @ToDate
					and e.Branchid=@BranchID and e.Compid=@CompID
				Group by Convert(varchar(7),e.DateIn,120)
			) x
			Order by x.YearMonth

		End
	
	Return 

END
GO

