/****** Object:  UserDefinedFunction [dbo].[fn_MIS_PAY_DirectEmployeeCostReport]    Script Date: 17/06/2026 11:38:47 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

/****** Object:  User Defined Function dbo.fn_MIS_PAY_DirectEmployeeCostReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_PAY_DirectEmployeeCostReport    Script Date: 24/09/2008 4:21:16 PM ******/

CREATE  FUNCTION [dbo].[fn_MIS_PAY_DirectEmployeeCostReport] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float		--SalaryAmt
	)

 AS  

BEGIN 			

		Insert @RetTable
	
		select YearMonth, sum(SalaryAmt) as DataValue1 
		from
			( select convert(VarChar(7),a.ProcessMonth,126) As YearMonth,  
				case when a.GrandTotalFlag = 1 then ResultValue else -ResultValue End SalaryAmt
			  from PAY_ProcessResult a left outer join PAY_Employee_Master b 
			  on a.EmployeeCode = b.EmployeeCode and a.Branchid = b.Branchid and a.Compid=b.Compid
			  where a.GrandTotalFlag <> 0 and b.CadreCode In (select Code from TermsMaster Where TypeFlg = 'Cadre'
				and Description = 'Worker'
			)
		Union
		select convert(VarChar(7),a.ProcessMonth,126) As YearMonth, ResultValue as SalaryAmt
		from PAY_ProcessResult a 
		left outer join PAY_Employee_Master b 
		on a.EmployeeCode = b.EmployeeCode and a.Branchid = b.Branchid and a.Compid=b.Compid
		where a.GrandTotalFlag <> 0 
			and b.CadreCode In(select Code from TermsMaster Where TypeFlg = 'Cadre'
						and Description = 'Worker') and ExprGroupId in (select ExprGroupId from PAY_PFESIGrouping 
						where Description in ('EPF Amount Employer','FPF Amount Employer','ESI Amount Employer'))
					     ) x
		where YearMonth between @FromDate and @ToDate group by x.YearMonth
	
	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_PAY_EmployeeCostAsaPercentageofSalesReport]    Script Date: 17/06/2026 11:38:47 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

/****** Object:  User Defined Function dbo.fn_MIS_PAY_EmployeeCostAsaPercentageofSalesReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_PAY_EmployeeCostAsaPercentageofSalesReport    Script Date: 24/09/2008 4:21:16 PM ******/


CREATE  FUNCTION [dbo].[fn_MIS_PAY_EmployeeCostAsaPercentageofSalesReport] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float		--PercSale
	)

 AS  

BEGIN 			

		Insert @RetTable
	
		select x.YearMonth, (x.SalaryAmt/y.TotalAmount) * 100 as DataValue1 from 
		(select YearMonth, sum(SalaryAmt) as SalaryAmt from
		(select convert(VarChar(7),a.ProcessMonth,126) As YearMonth,  
			case when a.GrandTotalFlag = 1 then ResultValue else -ResultValue End SalaryAmt
		from PAY_ProcessResult a where a.GrandTotalFlag <> 0
		Union
		select convert(VarChar(7),a.ProcessMonth,126) As YearMonth, ResultValue as SalaryAmt
		from PAY_ProcessResult a 
		where ExprGroupId in(select ExprGroupId 
					from PAY_PFESIGrouping 
					where Description in ('EPF Amount Employer','FPF Amount Employer','ESI Amount Employer'))) x
		where YearMonth between @FromDate and @ToDate
		group by x.YearMonth) x
		
		full outer join
		
			(select convert(VarChar(7),a.InvoiceDate,126) As YearMonth, sum(a.TotalAmount) as TotalAmount from
			SAL_Invoice_Hdr a 
			where convert(VarChar(7),a.InvoiceDate,126) between @FromDate and @ToDate 
				and Branchid=@BranchID and Compid =@CompID and Finyear = @Finyear
			group by convert(VarChar(7),a.InvoiceDate,126)) y
		on x.YearMonth = y.YearMonth	
	
	Return 

END
GO

