CREATE FUNCTION [dbo].[fn_MIS_PAY_EmployeeTurnOverReport] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float		--SalaryAmt
	)

 AS  

BEGIN 			

		Insert @RetTable

/*
		alter Procedure MisPayRoll_EmpoyeeTurnOver (@Start DateTime, @End DateTime, @Branchid varchar(3),@Compid VarChar(3)) 
		As
		Begin 
		Set NoCount On
		
		Select Period, Round((((ResEmps+JoinEmps) / cast(NOE as float) )*100),2) as NOP ,
		SubString(Period,6,2) as [Month], ResEmps,JoinEmps,  NOE
		from (
			Select Isnull(RejJoin.Period,PaySum.Period) as Period, isnull(RejJoin.ResEmps,0) as ResEmps, isnull(RejJoin.JoinEmps,0) as JoinEmps , IsNull(PaySum.NOE,0) as NOE from (
				(Select isnull(Res.Period, Joined.Period) as Period, Res.ResEmps ,Joined.JoinEmps from (
					(select  Convert(VarChar(7),RelievedDate,126) as Period,count(EmployeeCode) as ResEmps from PAY_Employee_Master 
					where RelievedDate between Convert(DateTime,@Start,111) and Convert(DateTime,@End,111) 
					and not RelievedDate is null 
					group by Convert(VarChar(7),RelievedDate,126)) Res
				Full Outer Join
					(select Convert(VarChar(7),DateofJoining,126) as Period,count(EmployeeCode) as JoinEmps from PAY_Employee_Master 
					where DateofJoining between Convert(DateTime,@Start,111) and Convert(DateTime,@End,111) 
					and not RelievedDate is null group by Convert(VarChar(7),DateofJoining,126) ) Joined
				On Res.Period=Joined.Period
				)) RejJoin
			Full Outer Join
			 (select convert(VarChar(7),ProcessMonth,126)  as Period,count(EmployeeCode) as NOE from PAY_ProcessResult 
				where convert(VarChar(7),ProcessMonth,126)  between @Start and  @End 
				and ResultValue > 0 and Branchid = @Branchid and Compid = @Compid  group by convert(VarChar(7),ProcessMonth,126) ) PaySum
			on RejJoin.Period=PaySum.Period
			)
		) EmpTurn where resemps+JoinEmps > 0
		
		End
		GO
*/


	
		select YearMonth, sum(SalaryAmt) as DataValue1 
		from
			(select convert(VarChar(7),a.ProcessMonth,126) As YearMonth,  
			case when a.GrandTotalFlag = 1 then ResultValue else -ResultValue End SalaryAmt
			from PAY_ProcessResult a where a.GrandTotalFlag <> 0
			Union
			select convert(VarChar(7),a.ProcessMonth,126) As YearMonth, ResultValue as SalaryAmt
			from PAY_ProcessResult a where ExprGroupId in
			(select ExprGroupId from PAY_PFESIGrouping where Description 
			in ('EPF Amount Employer','FPF Amount Employer','ESI Amount Employer'))
		) x
		where YearMonth between @FromDate and @ToDate
		group by x.YearMonth
	
	Return 

END
