/****** Object:  User Defined Function dbo.fn_MIS_PAY_IncentiveReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_PAY_IncentiveReport    Script Date: 25/09/2008 6:32:38 AM ******/


CREATE  FUNCTION [dbo].[fn_MIS_PAY_IncentiveReport] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float		---InsCost
	)

 AS  

BEGIN 			

	Insert @RetTable
			
		Select Convert(varchar(7),a.DocDate,126) As YearMonth, IsNull(Sum(a.DrAmt-a.CrAmt),0) As InsCost
			From FAS_VoucherTranSub a
				Where Convert(varchar(7),a.DocDate,126)  between @FromDate and @ToDate 
					and a.LrCode=(Select b.LedgerCode From FAS_LedgerMaster b
					Where b.LedgerName = 'PRODUCTIVE INCENTIVE'  and a.CompCode=b.CompCode
						) 
		Group by Convert(VarChar(7),a.DocDate,126)
	
	Return 

END
GO

