/****** Object:  User Defined Function dbo.fn_MIS_PAY_PreventiveMaintenanceCostReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_PAY_PreventiveMaintenanceCostReport    Script Date: 24/09/2008 4:21:16 PM ******/

CREATE  FUNCTION [dbo].[fn_MIS_PAY_PreventiveMaintenanceCostReport] (@FromDate varchar(7), @ToDate varchar(7), @CmCode varchar(12), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1		float		--CostVal
	)

 AS  

BEGIN 			

		Insert @RetTable

		Select Convert(varchar(7),s.StoreRequestDate,126), Sum(s.RequiredQty*m.Rate) As DataValue1
		From INV_STOREREQUEST_DTL s
		Left Outer Join INV_Material_Master m
		On s.ItemCode=m.ItemCode and s.Branchid=m.Branchid and s.compid=m.Compid
		Where Convert(varchar(7),s.StoreRequestDate,126) Between @FromDate and @ToDate
			and s.ReturnQty=0 
			and s.Branchid=@BranchID and s.Compid=@CompID and s.Finyear=@Finyear 
		Group by Convert(VarChar(7),s.StoreRequestDate,126)
	
	Return 

END
GO

