CREATE  FUNCTION [dbo].[fn_MIS_PAY_SuperVisionCostReport] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float		--OverTimeCost
	)

 AS  

BEGIN 			

		Insert @RetTable

		select convert(VarChar(7),a.ProcessMonth,126) as YearMonth, sum(ResultValue) as DataValue1 
		from PAY_ProcessResult a where a.ExprGroupName = 'OT AMOUNT'
			and convert(VarChar(7),a.ProcessMonth,126) between @FromDate  and @ToDate
			and a.Branchid = @BranchID and a.Compid = @CompID
		group by convert(VarChar(7),a.ProcessMonth,126)

	Return 

END
