/****** Object:  User Defined Function dbo.fn_MIS_PAY_WelfareCostAsaPercentageofSalesReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_PAY_WelfareCostAsaPercentageofSalesReport    Script Date: 24/09/2008 4:21:16 PM ******/



CREATE   FUNCTION [dbo].[fn_MIS_PAY_WelfareCostAsaPercentageofSalesReport] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float		--WCPerc
	)

 AS  

BEGIN 			

		Insert @RetTable

		Select x.YearMonth, Case When Sum(SalesValue)<>0 Then ((Sum(WelCost)/Sum(SalesValue))*100) Else 0 End As DataValue1
		From (
			Select Convert(varchar(7),v.DocDate,126) As YearMonth, IsNull(Sum(v.DrAmt-v.CrAmt),0) As WelCost, 0 As SalesValue
			From FAS_VoucherTranSub v
			Where Convert(varchar(7),v.DocDate,126) Between @FromDate and @ToDate
			and v.LrCode=(Select l.LedgerCode From FAS_LedgerMaster l
					Where l.LedgerName='STAFF WELFARE' and v.CompCode=l.CompCode
				     )
			Group by Convert(VarChar(7),v.DocDate,126)
			
			Union All
			
			Select Convert(VarChar(7),a.InvoiceDate,126) As YearMonth, 0 As WelCost, IsNull(Sum(a.InvoiceQty*a.Rate),0) As SalesValue
			From SalesInvoice a Where Convert(varchar(7),a.InvoiceDate,126) Between @FromDate and @ToDate
				and a.Type In('OE','Labour','VAT','EOU')
				and a.Branchid=@BranchID and a.Compid=@CompID and a.Finyear=@Finyear 
			Group by Convert(VarChar(7),a.InvoiceDate,126)
		) x
		Group by x.YearMonth
		Order by x.YearMonth		
	
	Return 

END
GO

