/****** Object:  User Defined Function dbo.fn_MIS_PPC_CapacityUtilisationPercentageReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_PPC_CapacityUtilisationPercentageReport    Script Date: 24/09/2008 4:21:16 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_PPC_CapacityUtilisationPercentageReport] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float,		--PnMin
	 DataValue2	float,		--ReaMin
	 DataValue3	float		--MacCnt
	)

 AS  

BEGIN 			

		Insert @RetTable		

		Select x.YearMonth, sum(x.PnMin) As DataValue1, Sum(x.ReaMin) As DataValue2, Count(x.MachineCode) As DataValue3
		From (
			Select Convert(varchar(7),q.StartDate,126) As YearMonth, Sum(DateDiff(n,q.Starttime,q.EndTime)) As PnMin, 
			Sum(c.ReaMin) As ReaMin, q.MachineCode
			From PPC_QuickProductionplan_Dtl q
			Full Outer Join
				( 	Select DateDiff(n,c.ReasonStartTime,c.ReasonEndTime) As ReaMin,		
					c.RefType, c.RefNo, c.RefDate, c.Branchid, c.Compid, c.Finyear,
					c.MachineCode, c.Shift, c.ItemCode
					From QC_Inspection_Criteria c		
					Where ((c.Type Not In('R','LR')) or (c.Type In('R','LR') 
					and c.CriteriaCode=14))
					and Convert(varchar(7),c.InspectionDate,126) Between  @FromDate and @ToDate
					and c.Branchid=@BranchID and c.CompId=@CompID and c.Finyear=@Finyear
					
				) c
			On q.DocType=c.RefType and q.DocNo=c.RefNo and q.DocDate=c.RefDate and q.Shift=c.Shift
			and q.MachineCode=c.MachineCode and q.StageCode=c.ItemCode and q.Branchid=c.Branchid 
			and q.Compid=c.Compid and q.Finyear=c.Finyear
			
			Where Convert(varchar(7),q.StartDate,126) Between  @FromDate and @ToDate
				and q.RevisionNo=( Select Max(q1.RevisionNo) 
				From PPC_QuickProductionplan_Dtl q1 
				Where q.DocNo=q1.DocNo and q.DocType=q1.DocType and q.DocDate=q1.DocDate 
				and q.StartDate=q1.StartDate and q.StageCode=q1.StageCode and q.MachineCode=q1.MachineCode  
				and q.OperationName=q1.OperationName ) and q.Status=1 
				and q.Branchid=@BranchID and q.CompId=@CompID and q.Finyear=@Finyear
			
			Group by Convert(varchar(7),q.StartDate,126), q.MachineCode
		) x
		Group by  x.YearMonth
	
	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_PPC_DownTimePercentageReport]    Script Date: 17/06/2026 11:38:47 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

/****** Object:  User Defined Function dbo.fn_MIS_PPC_DownTimePercentageReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_PPC_DownTimePercentageReport    Script Date: 24/09/2008 4:21:16 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_PPC_DownTimePercentageReport] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float,		--PlanMint
	 DataValue2	float		--DTMint
	)

 AS  

BEGIN 			

		Insert @RetTable		

/*		Select y.YearMonth, Case When y.PlanMint<>0 Then (y.DTMint/y.PlanMint)*100 
		Else 0 End As DTPerc From (	*/
		Select x.YearMonth, IsNull(Sum(x.PlanMint),0) As DataValue1, 
		IsNull(Sum(x.DTMint),0) As DataValue2
		From (
		
		Select Convert(varchar(7),q.StartDate,126) As YearMonth,
			IsNull(DateDiff(n,q.Starttime,q.EndTime),0) As PlanMint, c.DTMint
		From PPC_QuickProductionplan_Dtl q
		Full Outer Join
			( 	Select Convert(varchar(7),c.InspectionDate,126) As YearMonth, 
				IsNull(DateDiff(n,c.ReasonStartTime,c.ReasonEndTime),0) As DTMint,	
				c.RefType, c.RefNo, c.RefDate, c.Shift, c.MachineCode, c.ItemCode, 
				c.Branchid, c.Compid, c.Finyear
					
				From QC_Inspection_Criteria c
				Left Outer Join PPC_Reason_Master r
				On c.CriteriaCode=r.ReasonCode and c.Branchid=r.Branchid and c.Compid=r.Compid
				Where c.Type In('R','LR') and r.ReasonCode Not In(12,13,14,15,16,20)
				and Convert(varchar(7),c.InspectionDate,126) Between @FromDate and @ToDate
				and c.Branchid=@BranchID and c.Compid=@CompID
			) c
		On q.DocType=c.RefType and q.DocNo=c.RefNo and q.DocDate=c.RefDate and q.Shift=c.Shift
		and q.MachineCode=c.MachineCode and q.StageCode=c.ItemCode and q.Branchid=c.Branchid 
		and q.Compid=c.Compid and q.Finyear=c.Finyear
		Where Convert(varchar(7),q.StartDate,126) Between @FromDate and @ToDate
			and q.RevisionNo=( Select Max(q1.RevisionNo) 
		From PPC_QuickProductionplan_Dtl q1 
		Where q.DocNo=q1.DocNo and q.DocType=q1.DocType and q.DocDate=q1.DocDate 
			and q.StartDate=q1.StartDate and q.StageCode=q1.StageCode and q.MachineCode=q1.MachineCode  
			and q.OperationName=q1.OperationName ) and q.Status=1 
			and q.Branchid=@BranchID and q.CompId=@CompID and q.Finyear=@Finyear
		) x
		Group by x.YearMonth
	/*	) y
		Order by y.YearMonth		*/
	
	Return 

END
GO

