/****** Object:  User Defined Function dbo.fn_MIS_PPC_ProcessScrapAsaPercentageSalesReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_PPC_ProcessScrapAsaPercentageSalesReport    Script Date: 24/09/2008 4:21:16 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_PPC_ProcessScrapAsaPercentageSalesReport] (@FinStartDate datetime, @CurrDate datetime, @FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float		--ScrapPerc
	)

 AS  

BEGIN 			

		Insert @RetTable	

		Select x.YearMonth, Case When Sum(x.SalesValue)<>0 Then (Sum(x.ScrapValue)/Sum(x.SalesValue))*100 Else 0 End As DataValue1
		From ( 
			Select Convert(varchar(7),a.InwardGoodsReceiptDate,126) As YearMonth, a.ItemCode, 
				i.SalesValue, (a.ScrapQty*(dbo.fn_WtAvgRate(a.ItemCode, @FinStartDate, @CurrDate, @BranchID, @CompID, @Finyear))) As ScrapValue
			From PPC_InwardGoodsReceipt a 	
			Left Outer Join	(Select i.ItemCode, (i.InvoiceQty*i.Rate) As SalesValue,
						i.Branchid, i.Compid, i.Finyear
					 From SalesInvoice i	
					 Where Convert(varchar(7),i.InvoiceDate,126) Between @FromDate and @ToDate
						and i.BranchID=@BranchID and i.CompID=@CompID and i.Finyear=@Finyear
					) i
			On a.ItemCode=i.ItemCode and a.Branchid=i.Branchid and a.Compid=i.Compid and a.Finyear=i.Finyear
			Where Convert(varchar(7),a.InwardGoodsReceiptDate,126) Between @FromDate and @ToDate
			and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear
			
		) x
		Group by x.YearMonth
		Order by x.YearMonth
	
	Return 

END
GO

