/****** Object:  User Defined Function dbo.fn_MIS_PPC_ProcessScrapValueReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_PPC_ProcessScrapValueReport    Script Date: 24/09/2008 4:21:16 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_PPC_ProcessScrapValueReport] (@FinStartDate datetime, @CurrDate datetime, @FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float		--ScrapValue
	)

 AS  

BEGIN 			

		Insert @RetTable		
	
		Select x.YearMonth, Sum(x.ScrapValue) As DataValue1
		From ( 
			Select Convert(varchar(7),a.InwardGoodsReceiptDate,126) As YearMonth, a.ItemCode,
				(a.ScrapQty*
				(dbo.fn_WtAvgRate(a.ItemCode, @FinStartDate, @CurrDate, @BranchID, @CompID, @Finyear))) As ScrapValue
			From PPC_InwardGoodsReceipt a 	
			Where Convert(varchar(7),a.InwardGoodsReceiptDate,126) Between @FromDate and @ToDate
			and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear		
			
		) x
		Group by x.YearMonth
		Order by x.YearMonth
			
	
	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_PPC_ProductivityPercentageReport]    Script Date: 17/06/2026 11:38:47 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

/****** Object:  User Defined Function dbo.fn_MIS_PPC_ProductivityPercentageReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_PPC_ProductivityPercentageReport    Script Date: 24/09/2008 4:21:16 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_PPC_ProductivityPercentageReport] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float		--ProdPerc
	)

 AS  

BEGIN 			

		Insert @RetTable		
	
		Select x.YearMonth,  Case When Sum(x.PlanQty)<>0 Then (Sum(x.AccQty)/Sum(x.PlanQty)*100) 
			Else 0 End As DataValue1
		from (
			Select Convert(varchar(7),c.DocDate,126) As YearMonth,  Date1 as PlanQty,
			Case When a.CriteriaCode In(1,14) Then a.Qty Else '0' End AccQty		
			From PPC_QuickProductionplan_Dtl c 
			Left Outer Join QC_Inspection_Criteria a 
			On c.DocType=a.RefType and c.Docno=a.Refno and c.DocDate=a.RefDate 
				and c.StageCode=a.ItemCode and c.MachineCode=a.MachineCode 
				and c.Starttime=a.Starttime and c.Branchid = A.Branchid And c.Compid = A.Compid 
			Left Outer Join INV_Material_Master d 
			On c.StageCode=d.ItemCode and c.Branchid=d.Branchid and c.Compid=d.Compid 			
			Where Convert(varchar(7),c.DocDate,126) Between @FromDate and @ToDate
				and c.Revisionno=(Select Max(Revisionno) From PPC_QuickProductionplan_Dtl 
						    Where c.DocType=DocType and c.Docno=DocNo and c.DocDate=DocDate
							and c.Branchid=Branchid and c.Compid=Compid) and c.Status<>0 
							and c.OperationName<>'SETTING' 
							and (a.Type Not In('R','LR') or (a.Type In ('R','LR') and CriteriaCode=14)
						   )
				and c.Branchid=@BranchID and c.Compid=@CompID --and c.Finyear=@Finyear
		
		)x 
		Group by x.YearMonth
		Order by x.YearMonth
			
	
	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_PPC_UtilisedCapacityPercentageReport]    Script Date: 17/06/2026 11:38:48 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

/****** Object:  User Defined Function dbo.fn_MIS_PPC_UtilisedCapacityPercentageReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_PPC_UtilisedCapacityPercentageReport    Script Date: 24/09/2008 4:21:16 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_PPC_UtilisedCapacityPercentageReport] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),
	 DataValue1		float,	--ActMin
	 DataValue2		float	--TotMin
	)

 AS  

BEGIN 			

		Insert @RetTable		

		Select y.YearMonth, Sum(y.ActMin) As DataValue1, (Count(y.MachineCode)*Sum(y.ReaMin)) As DataValue2
		From (
			Select x.YearMonth, Sum(x.ActMin) AS ActMin, Sum(x.ReaMin) As ReaMin, x.MachineCode
			From (
				Select Convert(varchar(7),c1.InspectionDate,126) As YearMonth, DateDiff(n,c1.ReasonStartTime,c1.ReasonEndTime) As ActMin,		
				Case When ((c1.Type Not In('R','LR')) or (c1.Type In('R','LR') 
				and c1.CriteriaCode=14)) Then DateDiff(n,c1.ReasonStartTime,c1.ReasonEndTime) Else 0 End As ReaMin,
				c1.MachineCode
				From QC_Inspection_Criteria c1		
				Where Convert(varchar(7),c1.InspectionDate,126) Between @FromDate and @ToDate
				and c1.Branchid=@BranchID and c1.CompId=@CompID and c1.Finyear=@Finyear
			) x
			Group by x.YearMonth, x.MachineCode
		) y
		Group by y.YearMonth
	
	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_PPC_YieldPercentageReport]    Script Date: 17/06/2026 11:38:48 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

/****** Object:  User Defined Function dbo.fn_MIS_PPC_YieldPercentageReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_PPC_YieldPercentageReport    Script Date: 24/09/2008 4:21:16 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_PPC_YieldPercentageReport] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float		--YeildPerc
	)

 AS  

BEGIN 			

		Insert @RetTable		
	
		Select z.YearMonth, (z.IGRQty/(z.WorkOrderQty-z.PendingWoOrd))*100 As DataValue1
		From (
			Select y.YearMonth,y.IGRQty, y.RejectionQty, y.WorkOrderQty, 
			(y.TobeProducedQty-(y.IGRQty+y.RejectionQty)) As PendingWoOrd
			From (
				Select x.YearMonth, Sum(x.TobeProducedQty) As TobeProducedQty, Sum(x.IGRQty) As IGRQty, 
					Sum(x.RejectionQty) As RejectionQty, Sum(x.WorkOrderQty) As WorkOrderQty
				From ( 
					Select Convert(varchar(7),a.ProcessWorkOrderDate,126) As YearMonth, Round((a.IssuedQty/a.Norms), 0) As TobeProducedQty,
						IsNull((Select Sum(c.InwardGoodsReceiptQty) 
					From PPC_InwardGoodsReceipt c 
					Where c.WorkOrderType = A.ProcessWorkOrderType 
						and c.WorkOrderNo = A.ProcessWorkOrderNo and c.WorkOrderDate = a.ProcessWorkOrderDate 
						and c.BranchID = a.BranchID and c.CompID = a.CompID and c.Finyear = a.Finyear
						), 0) As IGRQty, 
					a.RejectionQty, a.WorkOrderQty 
					From PPC_ProcessWorkOrder a 
					Left Outer Join Material_Master b 
					On a.ToStageCode = b.ItemCode and a.BranchID = b.BranchiD and a.CompID = b.CompID 
					Where a.IssuedQty>0 And a.CompletedStatus=0 
					and Convert(varchar(7),a.ProcessWorkOrderDate,126) Between @FromDate and @ToDate 
					and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear	
				)x 
				Group by x.YearMonth
			)y
		) z
		Order by z.YearMonth
			
	
	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_PPC_YieldPercentageReportCorrection]    Script Date: 17/06/2026 11:38:48 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

/****** Object:  User Defined Function dbo.fn_MIS_PPC_YieldPercentageReportCorrection    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_PPC_YieldPercentageReportCorrection    Script Date: 25/09/2008 6:32:38 AM ******/

CREATE FUNCTION [dbo].[fn_MIS_PPC_YieldPercentageReportCorrection] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float		--YeildPerc
	)

 AS  

BEGIN 			

		Insert @RetTable				
			Select Convert(varchar(7),x.WoDate,126),sum(AcceptQty)/sum(IssuedQty)*100 from (
				Select a.WoQty,a.WoNo,a.WoDate,b.IssuedQty/a.Norms as IssuedQty,sum(isnull(AcceptQty,0))AcceptQty from PPC_Vw_WorkOrder a
					left outer join StoreRequest b 
					on a.WoType=b.WoType and a.WoNo=b.WoNo and a.WoDate=b.WoDate and a.ItemCode=b.ItemCode and a.Branchid=b.Branchid and a.Compid=b.Compid
				left outer join PPC_InwardGoodsReceipt c 
				on c.WorkOrderType = a.WoType and c.WorkOrderNo = a.WoNo and c.WorkOrderDate = a.WoDate and c.BranchID = a.BranchID and c.CompID = a.CompID 
			where CompletedStatus=1 and a.Branchid=@Branchid and a.Compid=@Compid
			group by a.WoQty,a.WoNo,a.WoDate,b.IssuedQty,a.Norms having (b.IssuedQty/a.Norms) < sum(isnull(AcceptQty,0))
			 )x
			where Convert(varchar(7),x.WoDate,126) Between @FromDate and @ToDate
			Group by  Convert(varchar(7),x.WoDate,126)
	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_PUR_PurchaseNewProductReport]    Script Date: 17/06/2026 11:38:48 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

/****** Object:  User Defined Function dbo.fn_MIS_PUR_PurchaseNewProductReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_PUR_PurchaseNewProductReport    Script Date: 24/09/2008 4:21:16 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_PUR_PurchaseNewProductReport] (@Cust varchar(10), @PurType varchar(10), @FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	 
	 DataValue1	int,	--NoofProducts
	 DataValue2	float	--PuchaseValue
	)

 AS  

BEGIN 			

		Insert @RetTable

		Select Convert(VarChar(7),x.DocDate,126) As YearMonth, Count(x.ItemCode) As DataValue1,
		Sum(x.InvQty*x.Rate) As DataValue2
		From (
			Select p.ItemCode, p.DocDate, Sum(p.Qty) InvQty, p.Rate
			From PurchaseInvoice p
			Where Convert(VarChar(7),p.DocDate,126) Between @FromDate and @ToDate
				and Convert(VarChar(10),DocDate,126)=
				(
					Select Top 1 Convert(VarChar(10),DocDate,126)
					From PurchaseInvoice
					Where p.ItemCode=ItemCode and Branchid=@BranchID and Compid=@CompID
					Order by ItemCode, DocDate, Convert(VarChar(7),DocDate,126)
				)
				and p.Branchid=@BranchID and p.Compid=@CompID and p.Finyear=@Finyear
			Group by p.ItemCode, p.DocDate, p.Rate
		) x 
		Group by Convert(VarChar(7),x.DocDate,126)
	
	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_PUR_PurchaseReturnReport]    Script Date: 17/06/2026 11:38:48 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

/****** Object:  User Defined Function dbo.fn_MIS_PUR_PurchaseReturnReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_PUR_PurchaseReturnReport    Script Date: 24/09/2008 4:21:16 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_PUR_PurchaseReturnReport] (@Cust varchar(10), @PurType varchar(10), @FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),		 
	 DataValue1	float,		--PurchaseGross
	 DataValue2	float,		--ReturnValue
	 DataValue3	float		--GoodsValue
	)

 AS  

BEGIN 			

	If @Cust<>''

		Begin 
			Insert @RetTable		
	
			Select y.YearMonth,  Sum(y.PurGross) As DataValue1, Sum(y.RetVal) As DataValue2,
				Case When Sum(y.GdsVal)<>'0' Then IsNull((Sum(IsNull(y.RetVal,'0'))/Sum(y.GdsVal))*100,'0')
				Else '0' End As DataValue3 
			From ( 
			Select x.RefType, x.RefNo, x.VendorCode, x.ItemCode, 
				IsNull(x.RefMonth,'') As YearMonth, (IsNull(x.InvQty,'0')*IsNull(x.Rate,'0')) As GdsVal, 
				(IsNull(b.RetQty,'0')*IsNull(x.Rate,'0')) As RetVal, 
				IsNull(((IsNull(x.InvQty,'0')*IsNull(x.Rate,'0'))-(IsNull(b.RetQty,'0')*IsNull(x.Rate,'0'))),'0') As PurGross, 
				x.Rate From( 
						Select a.RefType, a.RefNo, a.vendorCode, a.ItemCode, Cast(a.Rate As Decimal(25,2)) As Rate, 
							Convert(VarChar(7),a.RefDate,126) As RefMonth, Sum(a.Qty) As InvQty 
						From PurchaseInvoice a Where Convert(VarChar(7),a.RefDate,126) Between @FromDate and @ToDate
							and a.DocType=@PurType and a.VendorCode=@Cust
							and a.Branchid=@BranchID and a.Compid=@CompID and a.Finyear=@Finyear and a.Type In('P', 'L') 
						Group by Convert(VarChar(7),a.RefDate,126), a.RefType, a.RefNo,  a.vendorCode, a.ItemCode, a.Rate 
					     ) x
			Full Outer Join ( 
					Select b.RefType, b.RefNo, b.VendorCode, b.ItemCode, 
						Convert(VarChar(7),b.RefDate,126) As RefMonth, Sum(b.AcceptedQty) As AccQty, 
						Sum(b.RejectionQty) As RetQty From ReceiptEntry b 
					Where b.InwardType = 'R' and b.RefType='POR'
						and Convert(VarChar(7),b.RefDate,126) Between @FromDate and @ToDate
						and b.VendorCode=@Cust 
						and b.Branchid=@BranchID and b.Compid=@CompID and b.Finyear=@Finyear
					Group by Convert(VarChar(7),b.RefDate,126), b.RefType, b.RefNo, b.VendorCode, b.ItemCode 
				         ) b 
			On x.RefType=b.RefType and x.RefNo=b.RefNo and x.RefMonth=b.RefMonth 
			      and x.ItemCode=b.ItemCode and x.VendorCode=b.VendorCode 
			) y 
			Group by y.YearMonth 
			Order by y.YearMonth
	
		End

	Else

		Begin
			Insert @RetTable	

			Select y.YearMonth, Sum(y.PurGross) As DataValue1, Sum(y.RetVal) As DataValue2,
				Case When Sum(y.GdsVal)<>'0' Then IsNull((Sum(IsNull(y.RetVal,'0'))/Sum(y.GdsVal))*100,'0')
				Else '0' End As DataValue3 
			From ( 
			Select x.RefType, x.RefNo, x.VendorCode, x.ItemCode, 
				IsNull(x.RefMonth,'') As YearMonth, (IsNull(x.InvQty,'0')*IsNull(x.Rate,'0')) As GdsVal, 
				(IsNull(b.RetQty,'0')*IsNull(x.Rate,'0')) As RetVal, 
				IsNull(((IsNull(x.InvQty,'0')*IsNull(x.Rate,'0'))-(IsNull(b.RetQty,'0')*IsNull(x.Rate,'0'))),'0') As PurGross, 
				x.Rate From( 
						Select a.RefType, a.RefNo, a.vendorCode, a.ItemCode, Cast(a.Rate As Decimal(25,2)) As Rate, 
							Convert(VarChar(7),a.RefDate,126) As RefMonth, Sum(a.Qty) As InvQty 
						From PurchaseInvoice a Where Convert(VarChar(7),a.RefDate,126) Between @FromDate and @ToDate
							and a.DocType=@PurType
							and a.Branchid=@BranchID and a.Compid=@CompID and a.Finyear=@Finyear and a.Type In('P', 'L') 
						Group by Convert(VarChar(7),a.RefDate,126), a.RefType, a.RefNo,  a.vendorCode, a.ItemCode, a.Rate 
					     ) x
			Full Outer Join ( 
					Select b.RefType, b.RefNo, b.VendorCode, b.ItemCode, 
						Convert(VarChar(7),b.RefDate,126) As RefMonth, Sum(b.AcceptedQty) As AccQty, 
						Sum(b.RejectionQty) As RetQty From ReceiptEntry b 
					Where b.InwardType = 'R' and b.RefType='POR'
						and Convert(VarChar(7),b.RefDate,126) Between @FromDate and @ToDate
						and b.Branchid=@BranchID and b.Compid=@CompID and b.Finyear=@Finyear
					Group by Convert(VarChar(7),b.RefDate,126), b.RefType, b.RefNo, b.VendorCode, b.ItemCode 
				         ) b 
			On x.RefType=b.RefType and x.RefNo=b.RefNo and x.RefMonth=b.RefMonth 
			      and x.ItemCode=b.ItemCode and x.VendorCode=b.VendorCode 
			) y 
			Group by y.YearMonth 
			Having Sum(y.RetVal) <>0
			Order by y.YearMonth
		
		End	
	
	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_PUR_PurchaseValueReport]    Script Date: 17/06/2026 11:38:48 ******/
