/****** Object:  User Defined Function dbo.fn_MIS_PUR_PurchaseValueReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_PUR_PurchaseValueReport    Script Date: 24/09/2008 4:21:16 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_PUR_PurchaseValueReport] (@Cust varchar(10), @PurType varchar(10), @FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float,		--PurGross
	 DataValue2	float		--PurNetExcise
	)

 AS  

BEGIN 			

	If @Cust<>''

		Begin
			Insert @RetTable		
	
			Select x.YearMonth, Sum(x.PurGross) As DataValue1, 
				Sum(x.PurNetExcise) As DataValue2 
			From ( 
				Select Convert(VarChar(7),a.DocDate,126) As YearMonth, 
				(a.Qty*a.Rate) As PurGross, a.InvoiceAmount As PurNetExcise
			From PurchaseInvoice a Where a.DocType=@PurType  
				and Convert(VarChar(7),a.DocDate,126) Between @FromDate and @ToDate
				and a.VendorCode=@Cust
				and a.Branchid=@BranchID and a.Compid=@CompID and a.Finyear=@Finyear
			         ) x 
			Group by x.YearMonth 
			Order by x.YearMonth

		End

	Else

		Begin
			Insert @RetTable		
	
			Select x.YearMonth, Sum(x.PurGross) As DataValue1, 
				Sum(x.PurNetExcise) As DataValue2 
			From ( 
				Select Convert(VarChar(7),a.DocDate,126) As YearMonth, 
				(a.Qty*a.Rate) As PurGross, a.InvoiceAmount As PurNetExcise
			From PurchaseInvoice a Where a.DocType=@PurType 
				and Convert(VarChar(7),a.DocDate,126) Between @FromDate and @ToDate
				and a.Branchid=@BranchID and a.Compid=@CompID and a.Finyear=@Finyear
			         ) x 
			Group by x.YearMonth 
			Order by x.YearMonth
		End
	
	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_QC_CostofPersonnelReport]    Script Date: 17/06/2026 11:38:48 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

/****** Object:  User Defined Function dbo.fn_MIS_QC_CostofPersonnelReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_QC_CostofPersonnelReport    Script Date: 24/09/2008 4:21:16 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_QC_CostofPersonnelReport] (@DeptCode As varchar(10), @FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float		--SalaryAmt
	)

 AS  

BEGIN 			
	If @DeptCode<>''

		Begin

			Insert @RetTable
	
			select YearMonth, sum(SalaryAmt) as DataValue1 
			from
				( 	select convert(VarChar(7),a.ProcessMonth,126) As YearMonth,
					case When a.GrandTotalFlag = 1 then ResultValue else -ResultValue End SalaryAmt
					From PAY_ProcessResult a 
					Left Outer Join PAY_Employee_Master e
					On a.EmployeeCode = e.EmployeeCode and a.Branchid = e.Branchid and a.Compid = e.Compid
					Left Outer Join TermsMaster t
					On TypeFlg = 'Department' and e.DepartmentCode = t.Code and e.EmployeeCode=a.EmployeeCode 
					and a.Branchid = e.Branchid and a.Compid = e.Compid
					where a.GrandTotalFlag <> 0 and e.DepartmentCode In(@DeptCode)
						and a.Branchid=@BranchID and a.Compid=@CompID
					Union
					select  convert(VarChar(7),a.ProcessMonth,126) As YearMonth, ResultValue as SalaryAmt
					from PAY_ProcessResult a where ExprGroupId in
					(select ExprGroupId from PAY_PFESIGrouping 
					where Description in ('EPF Amount Employer','FPF Amount Employer','ESI Amount Employer'))
						and a.Branchid=@BranchID and a.Compid=@CompID
			) x
			where YearMonth Between  @FromDate and @ToDate
			group by x.YearMonth
	
		End		
	Else
		Begin

			Insert @RetTable
	
			select YearMonth, sum(SalaryAmt) as DataValue1 
			from
				( 	select convert(VarChar(7),a.ProcessMonth,126) As YearMonth,
					case When a.GrandTotalFlag = 1 then ResultValue else -ResultValue End SalaryAmt
					From PAY_ProcessResult a 
					Left Outer Join PAY_Employee_Master e
					On a.EmployeeCode = e.EmployeeCode and a.Branchid = e.Branchid and a.Compid = e.Compid
					Left Outer Join TermsMaster t
					On TypeFlg = 'Department' and e.DepartmentCode = t.Code and e.EmployeeCode=a.EmployeeCode 
					and a.Branchid = e.Branchid and a.Compid = e.Compid
					where a.GrandTotalFlag <> 0 --and e.DepartmentCode In(@DeptCode)
						and a.Branchid=@BranchID and a.Compid=@CompID
					Union
					select  convert(VarChar(7),a.ProcessMonth,126) As YearMonth, ResultValue as SalaryAmt
					from PAY_ProcessResult a where ExprGroupId in
					(select ExprGroupId from PAY_PFESIGrouping 
					where Description in ('EPF Amount Employer','FPF Amount Employer','ESI Amount Employer'))
						and a.Branchid=@BranchID and a.Compid=@CompID
			) x
			where YearMonth Between  @FromDate and @ToDate
			group by x.YearMonth
	
		End	
				
	Return 

END
GO

