/****** Object:  UserDefinedFunction [dbo].[fn_MIS_QC_CustomerEndPPMReport]    Script Date: 17/06/2026 11:38:48 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

/****** Object:  User Defined Function dbo.fn_MIS_QC_CustomerEndPPMReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_QC_CustomerEndPPMReport    Script Date: 24/09/2008 4:21:16 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_QC_CustomerEndPPMReport] (@CustCode varchar(20), @FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float	--PPMVal
	)

 AS  

BEGIN 			

	If @CustCode<>''
		
		Begin

			Insert @RetTable
	
			Select x.YearMonth, Case When x.AccQty<>0 Then ((x.RejQty/x.AccQty)*1000000) Else 0 End As PPMVal
			From (
				Select Convert(varchar(7),a.ComplaintReceivedDate,126) As YearMonth, Sum(b.ReceivedQty) As RecQty, 
					Sum(b.AcceptedQty) As AccQty, Sum(b.RejectedQty) As RejQty 
				From QC_CustomerComplaintRegister a
				Left Outer Join QC_CustomerComplaintRegister_Quantity b 
				On a.ComplaintRegisterType=b.ComplaintRegisterType and a.ComplaintRegisterNo=b.ComplaintRegisterNo
					and a.ComplaintRegisterDate=b.ComplaintRegisterDate and a.Branchid=b.Branchid and a.Compid=b.Compid
					and a.Finyear=b.Finyear
				Where a.ComplaintRegisterType='CCR' 
					and a.ItemCode In(Select d.StageCode From SAL_Customer_ItemMaster c 
								Left Outer Join MpsMaster d On c.ItemCode=d.ItemCode 
									and c.Branchid=d.Branchid and c.Compid=d.Compid 
								Where c.Branchid=@BranchID and c.Compid=@CompID
									and c.CustomerCode=@CustCode and IsNull(d.StageCode,'')<>'' 
								)
					and Convert(varchar(7),a.ComplaintReceivedDate,126) Between @FromDate and @ToDate 
					 and a.Branchid=@BranchID and a.Compid=@CompID and a.Finyear=@Finyear
				Group by Convert(varchar(7),a.ComplaintReceivedDate,126) 
				
			) x
			Order by x.YearMonth

		End

	Else

		Begin

			Insert @RetTable

			Select x.YearMonth, Case When x.AccQty<>0 Then ((x.RejQty/x.AccQty)*1000000) Else 0 End As PPMVal
			From (
				Select Convert(varchar(7),a.ComplaintReceivedDate,126) As YearMonth, Sum(b.ReceivedQty) As RecQty, 
					Sum(b.AcceptedQty) As AccQty, Sum(b.RejectedQty) As RejQty 
				From QC_CustomerComplaintRegister a
				Left Outer Join QC_CustomerComplaintRegister_Quantity b 
				On a.ComplaintRegisterType=b.ComplaintRegisterType and a.ComplaintRegisterNo=b.ComplaintRegisterNo
					and a.ComplaintRegisterDate=b.ComplaintRegisterDate and a.Branchid=b.Branchid and a.Compid=b.Compid
					and a.Finyear=b.Finyear
				Where a.ComplaintRegisterType='CCR' 					
					and Convert(varchar(7),a.ComplaintReceivedDate,126) Between @FromDate and @ToDate 
					 and a.Branchid=@BranchID and a.Compid=@CompID and a.Finyear=@Finyear
				Group by Convert(varchar(7),a.ComplaintReceivedDate,126) 
				
			) x
			Order by x.YearMonth
			
		End


	
	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_QC_InComingPPMReport]    Script Date: 17/06/2026 11:38:48 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

/****** Object:  User Defined Function dbo.fn_MIS_QC_InComingPPMReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_QC_InComingPPMReport    Script Date: 24/09/2008 4:21:16 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_QC_InComingPPMReport] (@CustCode varchar(20), @FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float		--PPMVal	
	)

 AS  

BEGIN 			

	If @CustCode<>''
		
		Begin

			Insert @RetTable

			Select y.YearMonth, Case When y.AccQty<>0 Then ((y.ScrQty/y.AccQty)*1000000) Else 0 End As DataValue1
			From (
				Select x.YearMonth, (Sum(x.AccQty2)+Sum(x.HopQty2)) As AccQty,  
					(Sum(x.ScrQty2)+Sum(x.RewQty2)) As ScrQty 
				From (	
				
					Select Convert(varchar(7),a.InspectionDate,126) As YearMonth, 
						Case When a.CriteriaCode='1' Then Qty Else 0 End As AccQty2, 
						Case When a.CriteriaCode='2' Then Qty Else 0 End As RejQty2, 
						Case When a.CriteriaCode='3' Then Qty Else 0 End As RewQty2, 
						Case When a.CriteriaCode='4' Then Qty Else 0 End As ScrQty2, 
						Case When a.CriteriaCode='14' Then Qty Else 0 End As HopQty2 
					From QC_Inspection_Criteria1 a 
					Left Outer Join QC_Inspection_Hdr1 b 
					On a.InspectionType=b.InspectionType and a.InspectionNo=b.InspectionNo 
						and a.InspectionDate=b.InspectionDate and a.Branchid=b.Branchid and a.Compid=b.Compid 
					Where a.InspectionType In('RIR') 
						and Convert(varchar(7),a.InspectionDate,126) Between @FromDate and @ToDate 
						and b.ItemCode In(Select d.StageCode From SAL_Customer_ItemMaster c 
					Left Outer Join MpsMaster d On c.ItemCode=d.ItemCode 
						and c.Branchid=d.Branchid and c.Compid=d.Compid 
					Where c.Branchid=@BranchID and c.Compid=@CompID
						and c.CustomerCode=@CustCode and IsNull(d.StageCode,'')<>''
					)
					and a.Branchid=@BranchID and a.Compid=@CompID	
				) x 
				Group by x.YearMonth
			) y
			Order by y.YearMonth
				
		End

	Else

		Begin
			Insert @RetTable

			Select y.YearMonth, Case When y.AccQty<>0 Then ((y.ScrQty/y.AccQty)*1000000) Else 0 End As PPMVal
			From (
				Select x.YearMonth, (Sum(x.AccQty2)+Sum(x.HopQty2)) As AccQty,  
					(Sum(x.ScrQty2)+Sum(x.RewQty2)) As ScrQty 
				From (	
				
					Select Convert(varchar(7),a.InspectionDate,126) As YearMonth, 
						Case When a.CriteriaCode='1' Then Qty Else 0 End As AccQty2, 
						Case When a.CriteriaCode='2' Then Qty Else 0 End As RejQty2, 
						Case When a.CriteriaCode='3' Then Qty Else 0 End As RewQty2, 
						Case When a.CriteriaCode='4' Then Qty Else 0 End As ScrQty2, 
						Case When a.CriteriaCode='14' Then Qty Else 0 End As HopQty2 
					From QC_Inspection_Criteria1 a 
					Left Outer Join QC_Inspection_Hdr1 b 
					On a.InspectionType=b.InspectionType and a.InspectionNo=b.InspectionNo 
						and a.InspectionDate=b.InspectionDate and a.Branchid=b.Branchid and a.Compid=b.Compid 
					Where a.InspectionType In('RIR') 
						and Convert(varchar(7),a.InspectionDate,126) Between @FromDate and @ToDate 						
						and a.Branchid=@BranchID and a.Compid=@CompID	
				) x 
				Group by x.YearMonth
			) y
			Order by y.YearMonth
		End
	
	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_QC_InProcessPPMReport]    Script Date: 17/06/2026 11:38:48 ******/
