GO

/****** Object:  User Defined Function dbo.fn_MIS_QC_InternalCarsPendingReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_QC_InternalCarsPendingReport    Script Date: 24/09/2008 4:21:16 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_QC_InternalCarsPendingReport] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float		--PendCars
	)

 AS  

BEGIN 			

		Insert @RetTable

		Select x.YearMonth, (Count(x.TotNoofCars)-Count(x.PendCars)) As DataValue1
		From (
		Select Convert(varchar(7),c.DocDate,126) As YearMonth, 
			c.ItemCode As TotNoofCars,
			Case When  c.DeviationStatus=1 Then c.DeviationStatus End As PendCars
		
		From QC_Car_Hdr c
		Where c.RefType In('PIR','FIN')
			and Convert(varchar(7),c.DocDate,126) Between @FromDate and @ToDate
			and c.Revisionno=(Select Max(Revisionno) From QC_Car_Hdr
			Where DocType=c.DocType and DocNo=c.DocNo and Branchid=c.Branchid 
			and Compid=c.Compid) 
			and c.Branchid=@BranchID and c.Compid=@CompID and c.Finyear=@Finyear
		) x
		Group by x.YearMonth
		Order by x.YearMonth
	
	Return 

END
GO

