/****** Object:  User Defined Function dbo.fn_MIS_QC_RepeatedCarsReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_QC_RepeatedCarsReport    Script Date: 24/09/2008 4:21:16 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_QC_RepeatedCarsReport] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float		--ReptCars
	)

 AS  

BEGIN 			

		Insert @RetTable

		Select Convert(varchar(7),c.DocDate,126) As YearMonth,
		Count(c.DocType) As DataValue1
		From QC_Car_Hdr c
		Where c.RefType In('PIR','FIN')   
			and Convert(varchar(7),c.DocDate,126) Between @FromDate and @ToDate
			and c.Revisionno=(Select Max(Revisionno) From QC_Car_Hdr
			Where DocType=c.DocType and DocNo=c.DocNo and Branchid=c.Branchid 
				and Compid=c.Compid) 
				and c.Branchid=@BranchID and c.Compid=@CompID and c.Finyear=@Finyear			
		Group by Convert(varchar(7),c.DocDate,126)	--, c.ItemCode, c.MParamCode, c.ParameterCode, c.Parameter, c.FromValue, c.ToValue
		Having Count(c.DocType)>=2
		Order by Convert(varchar(7),c.DocDate,126)
	
	Return 

END
GO

