CREATE FUNCTION [dbo].[fn_MIS_QC_RepeatedComplaintsReport] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float		--NoofRepComp
	)

 AS  

BEGIN

		Insert @RetTable

		Select Convert(varchar(7),c.ComplaintRegisterDate,126) As YearMonth, Count(c.ItemCode) As DataValue1 
		From QC_CustomerComplaintRegister c
		Where c.ComplaintRegisterType In('CCR') and ComplaintNature='R'  
			and Convert(varchar(7),c.ComplaintRegisterDate,126) Between @FromDate and @ToDate
		Group by Convert(varchar(7),c.ComplaintRegisterDate,126)
		Order by Convert(varchar(7),c.ComplaintRegisterDate,126)						
	
	Return 

END
