/****** Object:  User Defined Function dbo.fn_MIS_QC_TotalPPMReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_QC_TotalPPMReport    Script Date: 24/09/2008 4:21:16 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_QC_TotalPPMReport] (@CustCode varchar(20), @FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float		--PPMVal
	)

 AS  

BEGIN 			

	If @CustCode<>''	

		Begin

			Insert @RetTable					
					
			Select z.YearMonth, Case When z.AccQty<>0 Then (z.ScrQty/z.AccQty)*1000000 Else 0 End As DataValue1
			From (
			
				Select y.YearMonth, Sum(y.AccQty) As AccQty, Sum(y.Rewqty) As Rewqty, Sum(y.ScrQty) As ScrQty, 
				Sum(y.HopQty) As HopQty 
				From (
					Select x.YearMonth, Sum(x.AccQty1) As AccQty, Sum(x.RewQty1) As RewQty, 
						Sum(x.ScrQty1) As ScrQty, Sum(x.HopQty1) As HopQty 
					From (
						Select Convert(varchar(7),a.InspectionDate,126) YearMonth,
							Case When a.Type='C' and CriteriaCode='1' Then Qty Else 0 End As AccQty1, 
							Case When a.Type='C' and CriteriaCode='2' Then Qty Else 0 End As RejQty1, 
							Case When a.Type='C' and CriteriaCode='3' Then Qty Else 0 End As RewQty1, 
							Case When a.Type='C' and CriteriaCode='4' Then Qty Else 0 End As ScrQty1, 
							Case When a.Type='R' and CriteriaCode='14' Then Qty Else 0 End As HopQty1 
						From QC_Inspection_Criteria a 
						Where a.InspectionType In('SIR','PIR') 
							and Convert(varchar(7),a.InspectionDate,126) between @FromDate and @ToDate 
							and a.ItemCode In(Select d.StageCode From SAL_Customer_ItemMaster c 
								 Left Outer Join MpsMaster d On c.ItemCode=d.ItemCode 
									and c.Branchid=d.Branchid and c.Compid=d.Compid 
								 Where c.BranchID=@BranchID and c.CompID=@CompID
									and c.CustomerCode=@CustCode and IsNull(d.StageCode,'')<>'' 
								)
							and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear	
					) x 
					Group by x.YearMonth 
	
					Union All 
	
					Select x.YearMonth, Sum(x.AccQty2) As AccQty, Sum(x.RewQty2) As RewQty, 
					Sum(x.ScrQty2) As ScrQty, Sum(x.HopQty2) As HopQty 
					From (
						Select Convert(varchar(7),a.InspectionDate,126) YearMonth,
							Case When a.CriteriaCode='1' Then Qty Else 0 End As AccQty2, 
							Case When a.CriteriaCode='2' Then Qty Else 0 End As RejQty2, 
							Case When a.CriteriaCode='3' Then Qty Else 0 End As RewQty2, 
							Case When a.CriteriaCode='4' Then Qty Else 0 End As ScrQty2, 
							Case When a.CriteriaCode='14' Then Qty Else 0 End As HopQty2 
						From QC_Inspection_Criteria1 a 
						Left Outer Join QC_Inspection_Hdr1 b On a.InspectionType=b.InspectionType 
							and a.InspectionNo=b.InspectionNo and a.InspectionDate=b.InspectionDate 
							and a.Branchid=b.Branchid and a.Compid=b.Compid 
						Where a.InspectionType In('FIN','RIR') 
							and Convert(varchar(7),a.InspectionDate,126) between @FromDate and @ToDate 
							and b.ItemCode In(Select d.StageCode From SAL_Customer_ItemMaster c 
								 Left Outer Join MpsMaster d On c.ItemCode=d.ItemCode 
									and c.Branchid=d.Branchid and c.Compid=d.Compid 
								 Where c.BranchID=@BranchID and c.CompID=@CompID
									and c.CustomerCode=@CustCode and IsNull(d.StageCode,'')<>'' 
								)
								and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear
					) x 
					Group by x.YearMonth
	
					Union All 
	
					Select x.YearMonth, x.AccQty, x.Rework, x.ScrQty, x.HopQty 
					From (
						Select Convert(varchar(7),a.ComplaintReceivedDate,126) As YearMonth, --Sum(b.ReceivedQty) As RecQty, 
							Sum(b.AcceptedQty) As AccQty, 0 As ReWork, Sum(b.RejectedQty) As ScrQty, 0 As HopQty
						From QC_CustomerComplaintRegister a 
						Left Outer Join QC_CustomerComplaintRegister_Quantity b 
						On a.ComplaintRegisterType=b.ComplaintRegisterType and a.ComplaintRegisterNo=b.ComplaintRegisterNo
							and a.ComplaintRegisterDate=b.ComplaintRegisterDate and a.Branchid=b.Branchid and a.Compid=b.Compid
							and a.Finyear=b.Finyear
						Where a.ComplaintRegisterType='CCR' 
							and a.ItemCode In(Select d.StageCode From SAL_Customer_ItemMaster c 
										Left Outer Join MpsMaster d On c.ItemCode=d.ItemCode 
											and c.Branchid=d.Branchid and c.Compid=d.Compid 
										Where c.BranchID=@BranchID and c.CompID=@CompID
											and c.CustomerCode=@CustCode and IsNull(d.StageCode,'')<>'' 
										)
							and Convert(varchar(7),a.ComplaintReceivedDate,126) Between @FromDate and @ToDate 
							and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear	
						Group by Convert(varchar(7),a.ComplaintReceivedDate,126) 
					) x
			
				) y Group by y.YearMonth 
			) z Order by z.YearMonth

		End

	Else

		Begin

			Insert @RetTable					
					
			Select z.YearMonth, Case When z.AccQty<>0 Then (z.ScrQty/z.AccQty)*1000000 Else 0 End As PPMVal
			From (
			
				Select y.YearMonth, Sum(y.AccQty) As AccQty, Sum(y.Rewqty) As Rewqty, Sum(y.ScrQty) As ScrQty, 
				Sum(y.HopQty) As HopQty 
				From (
					Select x.YearMonth, Sum(x.AccQty1) As AccQty, Sum(x.RewQty1) As RewQty, 
						Sum(x.ScrQty1) As ScrQty, Sum(x.HopQty1) As HopQty 
					From (
						Select Convert(varchar(7),a.InspectionDate,126) YearMonth,
							Case When a.Type='C' and CriteriaCode='1' Then Qty Else 0 End As AccQty1, 
							Case When a.Type='C' and CriteriaCode='2' Then Qty Else 0 End As RejQty1, 
							Case When a.Type='C' and CriteriaCode='3' Then Qty Else 0 End As RewQty1, 
							Case When a.Type='C' and CriteriaCode='4' Then Qty Else 0 End As ScrQty1, 
							Case When a.Type='R' and CriteriaCode='14' Then Qty Else 0 End As HopQty1 
						From QC_Inspection_Criteria a 
						Where a.InspectionType In('SIR','PIR') 
							and Convert(varchar(7),a.InspectionDate,126) between @FromDate and @ToDate 
							and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear	
					) x 
					Group by x.YearMonth 
	
					Union All 
	
					Select x.YearMonth, Sum(x.AccQty2) As AccQty, Sum(x.RewQty2) As RewQty, 
					Sum(x.ScrQty2) As ScrQty, Sum(x.HopQty2) As HopQty 
					From (
						Select Convert(varchar(7),a.InspectionDate,126) YearMonth,
							Case When a.CriteriaCode='1' Then Qty Else 0 End As AccQty2, 
							Case When a.CriteriaCode='2' Then Qty Else 0 End As RejQty2, 
							Case When a.CriteriaCode='3' Then Qty Else 0 End As RewQty2, 
							Case When a.CriteriaCode='4' Then Qty Else 0 End As ScrQty2, 
							Case When a.CriteriaCode='14' Then Qty Else 0 End As HopQty2 
						From QC_Inspection_Criteria1 a 
						Left Outer Join QC_Inspection_Hdr1 b On a.InspectionType=b.InspectionType 
							and a.InspectionNo=b.InspectionNo and a.InspectionDate=b.InspectionDate 
							and a.Branchid=b.Branchid and a.Compid=b.Compid 
						Where a.InspectionType In('FIN','RIR') 
							and Convert(varchar(7),a.InspectionDate,126) between @FromDate and @ToDate 
								and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear
					) x 
					Group by x.YearMonth
	
					Union All 
	
					Select x.YearMonth, x.AccQty, x.Rework, x.ScrQty, x.HopQty 
					From (
						Select Convert(varchar(7),a.ComplaintReceivedDate,126) As YearMonth, --Sum(b.ReceivedQty) As RecQty, 
							Sum(b.AcceptedQty) As AccQty, 0 As ReWork, Sum(b.RejectedQty) As ScrQty, 0 As HopQty
						From QC_CustomerComplaintRegister a 
						Left Outer Join QC_CustomerComplaintRegister_Quantity b
						On a.ComplaintRegisterType=b.ComplaintRegisterType and a.ComplaintRegisterNo=b.ComplaintRegisterNo
							and a.ComplaintRegisterDate=b.ComplaintRegisterDate and a.Branchid=b.Branchid and a.Compid=b.Compid
							and a.Finyear=b.Finyear
						Where a.ComplaintRegisterType='CCR' 
							and Convert(varchar(7),a.ComplaintReceivedDate,126) Between @FromDate and @ToDate 
							and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear	
						Group by Convert(varchar(7),a.ComplaintReceivedDate,126) 
					) x
			
				) y Group by y.YearMonth 
			) z Order by z.YearMonth

		End
	
	Return 

END
GO

