/****** Object:  User Defined Function dbo.fn_MIS_REC_ExciseMODVATInputReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_REC_ExciseMODVATInputReport    Script Date: 24/09/2008 4:21:16 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_REC_ExciseMODVATInputReport] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float	--EDValue
	)

 AS  

BEGIN 			

		Insert @RetTable

		Select Convert(varchar(7),a.DocDate,126) As YearMonth, Sum(a.DrAmt) As DataValue1			
		From FAS_VoucherTranSub a 		
		Where a.vrRoute = '0B' and a.LrCode In(6,7,512) 
			and Convert(varchar(7),a.DocDate,126) between @FromDate and @ToDate
		Group by Convert(varchar(7),a.DocDate,126)
		Order by Convert(varchar(7),a.DocDate,126)
	
	Return 

END
