/****** Object:  UserDefinedFunction [dbo].[fn_MIS_REC_InternalCarsReport]    Script Date: 17/06/2026 11:38:48 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

/****** Object:  User Defined Function dbo.fn_MIS_REC_InternalCarsReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_REC_InternalCarsReport    Script Date: 24/09/2008 4:21:16 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_REC_InternalCarsReport] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float		--NoofCars
	)

 AS  

BEGIN 			

		Insert @RetTable

		Select Convert(varchar(7),c.DocDate,126) As YearMonth, Count(c.ItemCode) As DataValue1 
		From QC_Car_Hdr c
		Where c.RefType In('PIR','FIN')   
			and Convert(varchar(7),c.DocDate,126) Between @FromDate and @ToDate
			and c.Revisionno=(Select Max(Revisionno) From QC_Car_Hdr
			Where DocType=c.DocType and DocNo=c.DocNo and Branchid=c.Branchid 
			and Compid=c.Compid) 
			and c.Branchid=@BranchID and c.Compid=@CompID and c.Finyear=@Finyear
		Group by Convert(varchar(7),c.DocDate,126)
		Order by Convert(varchar(7),c.DocDate,126)
	
	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_REC_NetExciseOutFlowReport]    Script Date: 17/06/2026 11:38:48 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

/****** Object:  User Defined Function dbo.fn_MIS_REC_NetExciseOutFlowReport    Script Date: 05/11/2008 5:15:51 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_REC_NetExciseOutFlowReport    Script Date: 24/09/2008 4:21:16 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_REC_NetExciseOutFlowReport] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float		--NEOutFlow
	)

 AS  

BEGIN 			

		Insert @RetTable

		Select x.YearMonth, (x.SalEDValue-x.PurEDValue) As DataValue1
		From (
			Select  s.YearMonth, IsNull(s.SalEDValue,0) As SalEDValue, IsNull(p.PurEDValue,0) As PurEDValue
			From (	
				Select Convert(varchar(7),a.DocDate,126) As YearMonth, Sum(a.CrAmt) As SalEDValue 
				From FAS_VoucherTranSub a 
					Left Outer Join FAS_VoucherTranSub b
					On a.Doctype=b.Doctype and a.DocNo=b.DocNo and a.DocDate=b.DocDate 
					and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode
				Where a.vrRoute = '0K' and a.LrCode In(6,7,512) 
					and Convert(varchar(7),a.DocDate,126) between @FromDate and @ToDate
				Group by Convert(varchar(7),a.DocDate,126)
			) s
			Full Outer Join 
				( Select Convert(varchar(7),a.DocDate,126) As YearMonth, Sum(a.DrAmt) As PurEDValue 
					From FAS_VoucherTranSub a 
					Left Outer Join FAS_VoucherTranSub b
					On a.Doctype=b.Doctype and a.DocNo=b.DocNo and a.DocDate=b.DocDate 
					and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode
				 Where a.vrRoute = '0B' and a.LrCode In(6,7,512) 
					and Convert(varchar(7),a.DocDate,126) between @FromDate and @ToDate
				 Group by Convert(varchar(7),a.DocDate,126)
			) p
			On s.YearMonth=p.YearMonth
			
		) x
		Order by x.YearMonth		
		
	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_REC_NetVATOutFlowReport]    Script Date: 17/06/2026 11:38:48 ******/
