/****** Object:  User Defined Function dbo.fn_MIS_REC_NetVATOutFlowReport    Script Date: 05/11/2008 5:15:52 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_REC_NetVATOutFlowReport    Script Date: 24/09/2008 4:21:16 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_REC_NetVATOutFlowReport] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float		--NVOutFlow
	)

 AS  

BEGIN 			

		Insert @RetTable
	
		Select x.YearMonth, (x.SalVATValue-x.PurVATValue) As DataValue1
		From (
			Select  s.YearMonth, IsNull(s.SalVATValue,0) As SalVATValue, IsNull(p.PurVATValue,0) As PurVATValue
			From (	
				
			 Select Convert(varchar(7),a.DocDate,126) As YearMonth, Sum(a.CrAmt) As SalVATValue 
				From FAS_VoucherTranSub a 
					Left Outer Join FAS_VoucherTranSub b
					On a.Doctype=b.Doctype and a.DocNo=b.DocNo and a.DocDate=b.DocDate 
					and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode
				Where a.vrRoute = '0K' and a.LrCode In(505,514,568,578) 
					and Convert(varchar(7),a.DocDate,126) between @FromDate and @ToDate
				Group by Convert(varchar(7),a.DocDate,126)
			) s
			Full Outer Join 
				( Select Convert(varchar(7),a.DocDate,126) As YearMonth, Sum(a.DrAmt) As PurVATValue 
					From FAS_VoucherTranSub a 
					Left Outer Join FAS_VoucherTranSub b
					On a.Doctype=b.Doctype and a.DocNo=b.DocNo and a.DocDate=b.DocDate 
					and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode
				 Where a.vrRoute = '0B' and a.LrCode In(505,514,568,578) 
					and Convert(varchar(7),a.DocDate,126) between @FromDate and @ToDate
				 Group by Convert(varchar(7),a.DocDate,126)
			) p
			On s.YearMonth=p.YearMonth
		) x
		Order by x.YearMonth

	Return 

END
GO

