/****** Object:  User Defined Function dbo.fn_MIS_REC_ReceiptsPendingReport    Script Date: 24/09/2008 4:21:16 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_REC_ReceiptsPendingReport] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float		--PendTag
	)

 AS  

BEGIN 			

		Insert @RetTable

		Select Convert(varchar(7),r.ReceiptEntryDate,126) As YearMonth, Count(r.DCNo) As DataValue1 
		From ReceiptEntry r 
		Where r.ReceiptQty=0 and Convert(varchar(7),r.ReceiptEntryDate,126) Between @FromDate and @ToDate
			and r.Branchid=@BranchID and r.Compid=@CompID and r.Finyear=@Finyear
		Group by Convert(varchar(7),r.ReceiptEntryDate,126)
		Order by Convert(varchar(7),r.ReceiptEntryDate,126)
	
	Return 

END
GO

