CREATE  FUNCTION [dbo].[fn_MIS_Review_Dtl] (@AsOnDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE
	(DocType	varchar(3),
	 DocNo		int,
	 DocDate	datetime,
	 ModuleName	varchar(50),
	 MenuName	varchar(50),	 
	 SeqNo		int,
	 YearMonth	varchar(10),
	 Data1		float,
	 Data2		float,
	 ReviewDate	datetime,
	 RevNo		int,
	 RevDate	datetime,
	 EffStatus	char(1),
	 EffDate		datetime,
	 TranStamp	datetime,
	 UserId		varchar(10),
	 BranchId	varchar(3),
	 CompId		varchar(3),
	 Finyear		varchar(20)
	)

 AS  

BEGIN 
	Insert @RetTable
		Select * from MIS_Review_Dtl a
		Where a.TranStamp = (Select Max(b.TranStamp) from MIS_Review_Dtl b where b.TranStamp <= @AsOnDate 
		and b.DocType=a.DocType and b.DocNo=a.DocNo and b.DocDate=a.DocDate and b.SeqNo=a.SeqNo
		and b.BranchID=a.BranchID and b.CompID=a.CompID)	--and b.Finyear=a.Finyear)
		and a.BranchID=@BranchID and a.CompID=@CompID --and a.Finyear=@Finyear

	Return 

END
GO

