/****** Object:  UserDefinedFunction [dbo].[fn_MIS_SAL_SalesNewProductReport]    Script Date: 17/06/2026 11:38:48 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

/****** Object:  User Defined Function dbo.fn_MIS_SAL_SalesNewProductReport    Script Date: 05/11/2008 5:15:52 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_SAL_SalesNewProductReport    Script Date: 24/09/2008 4:21:16 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_SAL_SalesNewProductReport] (@Cust varchar(10), @CurrDateTime datetime, @CurrDate datetime, @FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),		 
	 DataValue1	int,		--Products
	 DataValue2	float		--SalesValue
	)

 AS  

BEGIN 			

		Insert @RetTable	

		Select Convert(VarChar(7),x.InvoiceDate,126) As YearMonth, Count(x.ItemCode) As DataValue1,
			Sum(x.SalesValue) As DataValue2
		From (
			Select s.ItemCode, s.InvoiceDate, s.InvoiceTime, (s.InvoiceQty*s.Rate) As SalesValue
			From SalesInvoice s
			Where Convert(VarChar(7),s.InvoiceDate,126) Between @FromDate and @ToDate
				and s.Type In('OE','Labour','VAT','EOU') 
				and Convert(VarChar(10),InvoiceDate,126)+' '+Convert(VarChar(8),InvoiceTime,108)=
				(
					Select Top 1 Convert(VarChar(10),InvoiceDate,126)+' '+Convert(VarChar(8),InvoiceTime,108)
					From SalesInvoice
					Where s.ItemCode=ItemCode and Type In('OE','Labour','VAT','EOU')
						and Branchid=@BranchID and Compid=@CompID
					Order by ItemCode, InvoiceDate, Convert(VarChar(8),InvoiceTime,108)
				)
				and s.Branchid=@BranchID and s.Compid=@CompID and s.Finyear=@Finyear
		) x 
		Group by Convert(VarChar(7),x.InvoiceDate,126)			
	
	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_SAL_SalesReturnReport]    Script Date: 17/06/2026 11:38:48 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

/****** Object:  User Defined Function dbo.fn_MIS_SAL_SalesReturnReport    Script Date: 05/11/2008 5:15:52 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_SAL_SalesReturnReport    Script Date: 24/09/2008 4:21:16 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_SAL_SalesReturnReport] (@Cust varchar(10), @CurrDateTime datetime, @CurrDate datetime, @FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float,		---SalesValue
	 DataValue2	float		---ReturnValue
	)

 AS  

BEGIN 		
	
	If @Cust<>''

		Begin	
			Insert @RetTable	

			Select x.YearMonth, IsNull(x.SalesValue,0) As DataValue1, IsNull(y.ReturnValue,0) As DataValue2 
			from 
				(Select Convert(VarChar(7),a.InvoiceDate,126) As YearMonth, Sum(a.TotalAmount) SalesValue
				 From SAL_Invoice_Hdr a Where Convert(varchar(7),a.InvoiceDate,126) Between @FromDate and @ToDate 
					and a.CustomerCode=@Cust
					and a.Branchid=@BranchID and a.Compid=@CompID 
					and a.Finyear=@Finyear Group by Convert(VarChar(7),a.InvoiceDate,126)
				) x
			
			Full Outer Join
				(Select Convert(VarChar(7),b.ReceiptEntryDate,126) As YearMonth, IsNull(Sum(RejectionQty * c.Rate),0) As ReturnValue
				 From ReceiptEntry b 
				Left Outer Join dbo.fn_SAL_Order_Dtl(@CurrDate, @CurrDateTime, @BranchID, @CompID, @Finyear) c
				On b.RefType = c.OrderType and b.RefNo = c.OrderNo and b.RefDate = c.OrderDate and  b.ItemCode=c.ItemCode 
					and b.Branchid = c.Branchid and b.Compid = c.Compid 
				Where b.ReceiptEntryType = 'RR' and b.InwardType='R' and b.Branchid=@BranchID and b.Compid=@CompID
					and b.Finyear=@Finyear
				Group by Convert(VarChar(7),b.ReceiptEntryDate,126)
				) y
			On x.YearMonth = y.YearMonth
			Order by x.YearMonth

		End

	Else

		Begin

			Insert @RetTable	

			select x.YearMonth, IsNull(x.SalesValue,0) as SalesValue, IsNull(y.ReturnValue,0) as ReturnValue 
			from 
				(Select Convert(VarChar(7),a.InvoiceDate,126) As YearMonth, Sum(a.TotalAmount) SalesValue
				 From SAL_Invoice_Hdr a Where Convert(varchar(7),a.InvoiceDate,126) 
					Between @FromDate and @ToDate and a.Branchid=@BranchID and a.Compid=@CompID 
					and a.Finyear=@Finyear Group by Convert(VarChar(7),a.InvoiceDate,126)
				) x
			
			Full Outer Join
				(Select Convert(VarChar(7),b.ReceiptEntryDate,126) As YearMonth, IsNull(Sum(RejectionQty * c.Rate),0) as ReturnValue
				 From ReceiptEntry b 
				Left Outer Join dbo.fn_SAL_Order_Dtl(@CurrDateTime, @CurrDate, @BranchID, @CompID, @Finyear) c
				On b.RefType = c.OrderType and b.RefNo = c.OrderNo and b.RefDate = c.OrderDate and  b.ItemCode=c.ItemCode 
					and b.Branchid = c.Branchid and b.Compid = c.Compid 
				Where b.ReceiptEntryType = 'RR'  and b.InwardType = 'R' and b.Branchid=@BranchID and b.Compid=@CompID
					and b.Finyear=@Finyear
				Group by Convert(VarChar(7),b.ReceiptEntryDate,126)
				) y
			On x.YearMonth = y.YearMonth
			Order by x.YearMonth
		End	

	Return 

END

GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_SAL_SalesValueReport]    Script Date: 17/06/2026 11:38:48 ******/
SET ANSI_NULLS OFF
GO

