/****** Object:  User Defined Function dbo.fn_MIS_SAL_SalesValueReport    Script Date: 05/11/2008 5:15:52 PM ******/

/****** Object:  User Defined Function dbo.fn_MIS_SAL_SalesValueReport    Script Date: 24/09/2008 4:21:16 PM ******/
CREATE FUNCTION [dbo].[fn_MIS_SAL_SalesValueReport] (@Cust varchar(10), @CurrDateTime datetime, @CurrDate datetime, @FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(YearMonth 	varchar(7),	
	 DataValue1	float,		--SalesValue
	 DataValue2	 float		--SalesNetExcise
	)

 AS  

BEGIN 			

	If @Cust<>''

		Begin
			Insert @RetTable		
	
			Select x.YearMonth, Sum(x.TotalAmount) As DataValue1, Sum(x.SalesNetExcise) As DataValue2
			From (
		
			Select Convert(VarChar(7),a.InvoiceDate,126) As YearMonth, 
				a.InvoiceQty*a.Rate As SalesNetExcise, a.TotalAmount, 
				a.CustomerCode
			From SalesInvoice a	
			Where Convert(varchar(7),a.InvoiceDate,126) Between @FromDate and @ToDate
				and CustomerCode=@Cust
				and a.Branchid=@BranchID and a.Compid=@CompID and a.Finyear=@Finyear
			) x
			 Group by x.YearMonth
			Order by x.YearMonth
		End

	Else

		Begin
			Insert @RetTable		
	
			Select x.YearMonth, Sum(x.TotalAmount) As DataValue1, Sum(x.SalesNetExcise) As DataValue2
			From (
		
			Select Convert(VarChar(7),a.InvoiceDate,126) As YearMonth, 
			a.InvoiceQty*a.Rate As SalesNetExcise, a.TotalAmount
			From SalesInvoice a	
			Where Convert(varchar(7),a.InvoiceDate,126) Between @FromDate and @ToDate
				and a.Branchid=@BranchID and a.Compid=@CompID and a.Finyear=@Finyear
			) x
			 Group by x.YearMonth
			Order by x.YearMonth
		End
	
	Return 

END
GO

