CREATE FUNCTION [dbo].[fn_PAP_RPN] (@TranStamp datetime, @Branchid varchar(3), @Compid varchar(3))  

RETURNS @RPN TABLE
	(ItemCode	varchar(20),
	RPN		int,
	RevisionNo	int,
	RevisionDate	datetime,
	EffDate		datetime,
	EffStatus	char(1),
	TranStamp	datetime,
	Userid		varchar(10),
	Branchid	varchar(3),
	Compid		varchar(3))
		
AS  

BEGIN 

	Insert into @RPN	

		Select * from PAP_RPN a where TranStamp<=@TranStamp
			and TranStamp=(Select Max(TranStamp) from PAP_RPN b where a.ItemCode=b.ItemCode and a.BRanchid=b.Branchid
			and a.Compid=b.Compid and TranStamp<=@TranStamp)
			and Branchid=@Branchid and Compid=@Compid
 
	Return

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_PAY_ApplicableWeeklyHolidays]    Script Date: 17/06/2026 11:38:48 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_PAY_ApplicableWeeklyHolidays] (@EmployeeCode varchar(10),@FromDate datetime, @ToDate datetime, @Branchid varchar(3), @Compid varchar(3))      
RETURNS @WeekOff TABLE    
 (WeeklyOff datetime,    
  HolidayType varchar(2),    
  HolidayReason varchar(30))    
  
AS      
  
BEGIN     
     Declare @WH int    
     Declare @RH varchar(30)    
     Declare @EffDate datetime    
     Declare @FDate datetime    
     Declare @TDate datetime    
     Declare @WDate datetime  
         
     Declare curRec cursor FOR    
        Select WeeklyHoliday, RoutineHoliday, EffDate    
        From PAY_Holiday_Hdr Where Branchid = @Branchid and Compid = @Compid     
  
        Union All    
  
        Select WeeklyHoliday, RoutineHoliday, EffDate      
        From PAY_Holiday_Hdr
        Where (EffDate Between  @FromDate and @ToDate) and Branchid = @Branchid and Compid = @Compid     
        Order by EffDate DESC    
     
    Open curRec    
     
    Fetch next from curRec into @WH,@RH, @EffDate    
     
          
    Select @TDate = @ToDate    
  
        
    While @@Fetch_Status=0    
        BEGIN    
          
            If @EffDate <= @FromDate    
                Select @FDate = @FromDate    
            Else    
                Select @FDate = Convert(varchar(10), @EffDate, 120)  
          
            Select @WDate=dbo.fn_PAY_NthOccurrenceOfDay(@FDate, @WH, 1)  
              
            While @WDate <= @TDate    
                BEGIN    
                    If Not Exists (Select * from @WeekOff Where WeeklyOff=@WDate)    
                        Insert into @WeekOff   
                            Select @WDate, 'W', ''    
                      
                    Select @WDate = DateAdd(dd, 7, @WDate)  
                END    
      
            Select @TDate = @FDate --Previous FromDate to be assigned current ToDate    
            Select @WDate = @TDate  
                
            Fetch Next from curRec into @WH, @RH, @EffDate    
        END    
     
     
    Close curRec    
    Deallocate curRec    
       
    Update @WeekOff Set WeeklyOff=(Select CompensationDate From dbo.PAY_HolidayException_Master a2    
                                   Where a2.ExceptionDate = a1.WeeklyOff    
                                   )    
    From @WeekOff a1     
    Where Exists (Select * From dbo.PAY_HolidayException_Master a2    
                   Where a2.ExceptionDate = a1.WeeklyOff    
                   )    
           
           
    Delete From @WeekOff    
    Where WeeklyOff in (Select ExceptionDate From dbo.PAY_HolidayException_Master a2    
                           Where a2.ExceptionDate  Between @FromDate and @ToDate    
                        )    
           
    Delete From @WeekOff    
    Where WeeklyOff in (Select LeaveDate from PAY_Attendance_Entry a1    
                           Where a1.EmployeeCode=@EmployeeCode and a1.LeaveDate  Between @FromDate and @ToDate and a1.LeaveType in ('LOP','ESL')     
                            and a1.BranchID=@BranchID and a1.CompID=@CompID    
                        )    
  
   RETURN     
END


GO

/****** Object:  UserDefinedFunction [dbo].[fn_PAY_ApplicableWeeklyHolidays_Unicorn]    Script Date: 17/06/2026 11:38:48 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_PAY_ApplicableWeeklyHolidays_Unicorn] (@FromDate datetime, @ToDate datetime, @Branchid varchar(3), @Compid varchar(3))    
  
RETURNS @WeekOff TABLE  
 (WeeklyOff datetime)  
  
AS    
  
BEGIN   
  
 Declare @WH int  
 Declare @RH int  
 Declare @EffDate datetime  
 Declare @FDate datetime  
 Declare @TDate datetime  
 Declare @WDate datetime  
  
   
 Declare curRec cursor FOR  
   
  Select WeeklyHoliday, RoutineHoliday, EffDate  
  From PAY_Holiday_Hdr   
  Where EffDate = (Select Max(EffDate) from PAY_Holiday_Hdr Where EffDate<@FromDate and Branchid = @Branchid and Compid = @Compid)  
   and Branchid = @Branchid and Compid = @Compid   
   
  Union All  
   
  Select WeeklyHoliday, RoutineHoliday, EffDate    
  From PAY_Holiday_Hdr   
  Where (EffDate Between  @FromDate and @ToDate) and Branchid = @Branchid and Compid = @Compid   
  
  Order by EffDate Desc  
   
 Open curRec  
   
 Fetch next from curRec into @WH,@RH, @EffDate  
   
 If @EffDate <= @FromDate  
  Select @FDate = @FromDate  
 Else  
  Select @FDate = @EffDate  
   
    
 Select @TDate = @ToDate  
 Select @WDate = @TDate  
  
  While @@Fetch_Status=0  
    BEGIN  
  
   Select @WDate=dbo.fn_PAY_NthOccurrenceOfDay(@FDate, @WH, 1)       
  
       While @WDate <= @TDate  
    BEGIN  
     Insert into @WeekOff Select @WDate  
  
     Select @WDate = @WDate + 7  
    END  
    
    
      Fetch Next from curRec into @WH,@RH, @EffDate  
  
  
   Select @TDate = @FDate --Previous FromDate to be assigned current ToDate  
   Select @WDate = @TDate  
  
   If @EffDate <= @FromDate  
    Select @FDate = @FromDate  
   Else  
    Select @FDate = @EffDate      
     
  
    
    END  
   
   
   Close curRec  
   Deallocate curRec  
    
   RETURN   
  
END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_PAY_BalanceLeaveDays]    Script Date: 17/06/2026 11:38:48 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION  [dbo].[fn_PAY_BalanceLeaveDays] (@AsOnDate datetime, @BranchID Varchar(3), @CompID varchar(3))  

RETURNS @LeaveDtl TABLE
	(EmployeeCode		varchar(10),
	LeaveYear		varchar(4),
	LeaveCode		varchar(5),
	InitialLeaveDays 	float,			
	BalanceLeaveDays	float,
	TotalDaysPassed	float,			
	BranchID		varchar(3),
	CompID			varchar(3))

 AS  


BEGIN 

		Insert into @LeaveDtl
	

		Select EmployeeCode, Year(@AsOnDate), LeaveCode, LeaveDays, 
				Case when x.CreditPolicy = 'E' then
	---				(round((x.TotalDays - x.AbsentDays)/ x.NoofDaysworked,-1)* x.NoofDaysCredited) - LeaveTakenDays

				(dbo.fn_RoundOff((x.TotalDays - x.AbsentDays)/ x.NoofDaysworked, 0.5, 1, 'D') * x.NoofDaysCredited) - LeaveTakenDays


					else x.LeaveDays - x.LeaveTakenDays end BalanceLeave ,
			TotalDays, @BranchID, @CompID
		From (
			
			Select a.EmployeeCode, b.LeaveCode, a.LeaveDays, b.NoofDaysworked, b.NoofDaysCredited, b.CreditPolicy,
			Case When Year(c.DateofJoining) = Year(@AsOnDate) Then DateDiff(d,c.DateofJoining, @AsOnDate) 
				Else DatePart(dy, @AsOnDate) End TotalDays,

				isNull((Select Sum(e.LeaveDays) from PAY_Attendance_Entry e 
					Where Year(e.LeaveDate) =  Year(@AsOnDate) 	and e.AbsentType = 'A'   
						and LeaveDate <= @AsOnDate and e.EmployeeCode = a.EmployeeCode 
						and e.Branchid = a.Branchid and e.Compid = a.Compid),0) AbsentDays,
				
				isNull((Select Sum(e.LeaveDays) from PAY_Attendance_Entry e 
					Where Year(e.LeaveDate) =  Year(@AsOnDate) 	and e.AbsentType = 'A' and e.LeaveType = a.LeaveCode  
						and LeaveDate <= @AsOnDate and e.EmployeeCode = a.EmployeeCode 
						and e.Branchid = a.Branchid and e.Compid = a.Compid),0) LeaveTakenDays
			
			From PAY_Leave_Details a 

			Left Outer Join PAY_Leave_Master b 
				On a.LeaveCode = b.LeaveCode and a.Branchid = b.Branchid and a.Compid = b.Compid
			Left Outer Join PAY_Employee_Master c 
				On a.EmployeeCode = c.EmployeeCode and a.Branchid = c.Branchid and a.Compid = c.Compid
			Where a.LeaveYear =  Year(@AsOnDate) and c.DateOfJoining <= @AsOnDate and a.Branchid = @Branchid and a.Compid = @CompID
			) x 


	return 

END
GO

