/****** Object:  UserDefinedFunction [dbo].[fn_Pay_BalanceLeaveDays_AllEmployees]    Script Date: 17/06/2026 11:38:48 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION  [dbo].[fn_Pay_BalanceLeaveDays_AllEmployees] (@LeaveAsOnDate datetime,  @Branchid Varchar(3), @CompID varchar(3))  

RETURNS @RetTable TABLE

	(EmployeeCode 		Varchar(10),
	 EmployeeName		Varchar(50),
	 LeaveCode		Varchar(10),
	 LeaveDescription	Varchar(50),
	 BalanceLeaveDays	Float	)

 AS  


BEGIN 

	Insert into @RetTable		

	Select  EmployeeCode, EmployeeName, LeaveCode, LeaveDescription, BalanceLeave 
	from (
		Select EmployeeCode, EmployeeName, LeaveCode, LeaveDescription, case when x.CreditPolicy = 'E' then
				(round((x.TotalDays - x.AbsentDays)/ x.NoofDaysworked,-1)* x.NoofDaysCredited) - LeaveTakenDays
			else x.LeaveDays - x.LeaveTakenDays End BalanceLeave 
		from (			
		
			select a.EmployeeCode, c.EmployeeName, a.LeaveCode, b.LeaveDescription, a.LeaveDays, b.NoofDaysworked, b.NoofDaysCredited, b.CreditPolicy,
			case when Year(c.DateofJoining) =  year(@LeaveAsOnDate) then DateDiff(d,c.DateofJoining,@LeaveAsOnDate) 
				else DateDiff(d, convert(varchar,year(@LeaveAsOnDate))+'-01-01',@LeaveAsOnDate) end TotalDays,		
			isNull((select sum(d.LeaveDays) from PAY_Attendance_Entry d 
			where d.AbsentType = 'A' and d.EmployeeCode = a.EmployeeCode and d.Branchid = a.Branchid and d.Compid = a.Compid), 0) AbsentDays,
		
			isnull((select sum(e.LeaveDays) from PAY_Attendance_Entry e 
				where Year(e.LeaveDate) =  year(@LeaveAsOnDate) and e.AbsentType = 'A' and e.LeaveType = a.LeaveCode  
					and LeaveDate <= @LeaveAsOnDate and e.EmployeeCode = a.EmployeeCode 
					and e.Branchid = a.Branchid and e.Compid = a.Compid),0) LeaveTakenDays	
	
			from PAY_Leave_Details a 
			left outer join PAY_Leave_Master b 
				on a.LeaveCode = b.LeaveCode and a.Branchid = b.Branchid and a.Compid = b.Compid
			left outer join PAY_Employee_Master c 
				on a.EmployeeCode = c.EmployeeCode and a.Branchid = c.Branchid and a.Compid = c.Compid
			where a.LeaveYear =  year(@LeaveAsOnDate) --and a.EmployeeCode = @EmployeeCode and a.LeaveCode =@LeaveCode
				and a.Branchid = @Branchid and a.Compid = @CompID
			) x 
		) y

	return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_PAY_CommonSalary_Master]    Script Date: 17/06/2026 11:38:49 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION  [dbo].[fn_PAY_CommonSalary_Master](@AsOnDate datetime, @BranchID Varchar(3), @CompID varchar(3))  

RETURNS @CommonSalary TABLE
	(EmploymentNature	char(1),
	CadreCode		int,
	DesignationCode		int,
	GradeCode		int,
	ExprGroupID		int,
	Amount			float,
	CadreAll		char(1),
	DesignationAll		char(1),
	GradeAll		char(1),
	Period			int,
	PeriodExprId		int,
	EffDate			datetime,
	Userid			varchar(10),
	Branchid		varchar(3),
	Compid			varchar(3))
 AS  


BEGIN 

		Insert into @CommonSalary
	

		Select a.EmploymentNature, a.CadreCode, a.DesignationCode, a.GradeCode, a.ExprGroupID, a.Amount, 
		a.CadreAll, a.DesignationAll, a.GradeAll, a.Period, a.PeriodExprId, a.EffDate, a.Userid, a.Branchid, 
		a.Compid 
		from PAY_CommonSalary_Master a
			where a.EffDate = (select Max(b.EffDate) from PAY_CommonSalary_Master b
		      	where b.EmploymentNature = a.EmploymentNature and b.CadreCode = a.CadreCode and b.DesignationCode = b.DesignationCode
		      	and b.GradeCode = a.GradeCode and b.CadreAll = a.CadreAll and b.DesignationAll = a.DesignationAll
			and b.GradeAll = a.GradeAll and b.Branchid = a.Branchid and b.Compid = a.Compid and b.EffDate <= @AsOnDate)


	return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_PAY_EmployeeShiftProcess]    Script Date: 17/06/2026 11:38:49 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION  [dbo].[fn_PAY_EmployeeShiftProcess](@Type As char(1), @RptFromDate datetime, @RptToDate datetime, @mEmp varchar(10), @BranchID varchar(3), @CompID varchar(3))

RETURNS @RetTable TABLE
	( EmployeeCode		varchar(10), 
	  EmployeeName	varchar(50), 
	  ShiftGroupCode	varchar(10), 	
	  ShiftShortName	varchar(10), 
	  ShiftLongName		varchar(20), 	
	  ShiftGroupDesc	varchar(50),
	  ShiftSequence 		int,
	  ShiftCode		varchar(10), 
	  WeekGroupCode	varchar(10), 	
	  WeekShortName	varchar(10), 
	  WeekLongName	varchar(20), 	
	  PeriodValue		int,
	  PeriodType		char(1),   
	  MSeq			int,	 
	  IsWOffInclusive	char(3),
	  DDay			int,
	  DMon			int,
	  DYer			int,
	  TotPerVal		int,
 	  Remarks		varchar(50), 
	  EffDate		datetime,
	  TranStamp		datetime,
	  FTDate		datetime	 
	)

 AS  

BEGIN 

		If @Type='1' 	/*  RptDate & With EmployeeCode  */

			Begin
		
				Insert into @RetTable
			
				Select a.EmployeeCode, e.EmployeeName, a.ShiftGroupCode, b.ShiftShortName, b.ShiftLongName, 
					b.ShiftGroupDesc, c.ShiftSequence, c.ShiftCode, a.WeekGroupCode,  w.WeekShortName, w.WeekLongName,
					c.PeriodValue, c.PeriodType, u.MSeq,  
					Case When c.IsWOffInclusive='1' Then 'INC' Else 'EXC' End As IsWOffInclusive,				
					Case When c.PeriodType='D' or c.PeriodType='W' Then  DateDiff(dd, a.EffDate,@RptToDate)+1 Else 0 End As DDay,
					Case When c.PeriodType='M' Then  DateDiff(mm, a.EffDate,@RptToDate)+1 Else 0 End As DMon,
					Case When c.PeriodType='Y' Then  DateDiff(yy, a.EffDate,@RptToDate)+1 Else 0 End As DYer,
					u.TotPerVal, b.Remarks, a.EffDate, @RptToDate As FTDate, a.TranStamp
				From (Select * from PAY_Employee_Master Where EmployeeCode=@mEmp and BranchID=@BranchID and CompID=@CompID and Status='W') e 			
				Left Outer Join PAY_AssignedGroup_Master a 	
					On a.EmployeeCode=e.EmployeeCode and a.Branchid=e.Branchid and a.Compid=e.Compid 
				Left Outer Join PAY_ShiftGroupMaster_Hdr b 
					On a.ShiftGroupCode=b.ShiftGroupCode and a.Branchid=b.Branchid and a.Compid=b.Compid 
				Left Outer Join PAY_ShiftGroupMaster_Dtl c 
					On a.ShiftGroupCode=c.ShiftGroupCode and a.Branchid=c.Branchid and a.Compid=c.Compid 
				Left Outer Join PAY_WeekGroupMaster_Hdr w 
					On a.WeekGroupCode=w.WeekGroupCode and a.Branchid=w.Branchid and a.Compid=w.Compid 				
				Full Outer Join (Select a.ShiftGroupCode, a.EmployeeCode, Max(c.ShiftSequence) As MSeq,	Sum(c.PeriodValue) As TotPerVal
						From PAY_AssignedGroup_Master a 
				   		Left Outer Join PAY_ShiftGroupMaster_Hdr b 
				   			On a.ShiftGroupCode=b.ShiftGroupCode and a.Branchid=b.Branchid and a.Compid=b.Compid 
				   		Left Outer Join PAY_ShiftGroupMaster_Dtl c 
				   			On a.ShiftGroupCode=c.ShiftGroupCode and a.Branchid=c.Branchid and a.Compid=c.Compid
						Where  b.EffStatus='1'  and a.EmployeeCode=@mEmp
							and a.EffDate=(Select Max(m.EffDate) As EffDate 
									From PAY_AssignedGroup_Master m 
									Where a.ShiftGroupCode=m.ShiftGroupCode and m.EmployeeCode=@mEmp
										and m.EffDate<=@RptToDate and m.Branchid=@BranchID and m.Compid=@CompID
									)
							and a.Branchid=@BranchID and a.Compid=@CompID
						Group by a.ShiftGroupCode, a.EmployeeCode, a.EffDate
						) u
					On a.ShiftGroupCode=u.ShiftGroupCode and a.EmployeeCode=u.EmployeeCode 
				
				Where b.EffStatus='1' 
					and a.EffDate=(Select Max(m.EffDate) As EffDate From PAY_AssignedGroup_Master m
							Where m.EmployeeCode=@mEmp and a.ShiftGroupCode=m.ShiftGroupCode
								and m.EffDate<=@RptToDate and m.Branchid=@BranchID and m.Compid=@CompID
							)
					and a.Branchid=@BranchID and a.Compid=@CompID
				Order by a.EffDate, a.ShiftGroupCode, a.EmployeeCode, c.ShiftSequence		
			
			End

		If @Type='2' 	/*  FromDate-ToDate & With EmployeeCode  */

			Begin
		
				Insert into @RetTable
			
				Select a.EmployeeCode, e.EmployeeName, a.ShiftGroupCode, b.ShiftShortName, b.ShiftLongName, 
					b.ShiftGroupDesc, c.ShiftSequence, c.ShiftCode, a.WeekGroupCode,  w.WeekShortName, w.WeekLongName,
					c.PeriodValue, c.PeriodType, u.MSeq,  
					Case When c.IsWOffInclusive='1' Then 'INC' Else 'EXC' End As IsWOffInclusive,				
					Case When c.PeriodType='D' or c.PeriodType='W' Then  DateDiff(dd, a.EffDate,@RptToDate)+1 Else 0 End As DDay,
					Case When c.PeriodType='M' Then  DateDiff(mm, a.EffDate,@RptToDate)+1 Else 0 End As DMon,
					Case When c.PeriodType='Y' Then  DateDiff(yy, a.EffDate,@RptToDate)+1 Else 0 End As DYer,
					u.TotPerVal, b.Remarks, a.EffDate, @RptToDate As FTDate, a.TranStamp
				From (Select * from PAY_Employee_Master Where EmployeeCode=@mEmp and BranchID=@BranchID and CompID=@CompID and Status='W') e 			
				Left Outer Join PAY_AssignedGroup_Master a 	
					On a.EmployeeCode=e.EmployeeCode and a.Branchid=e.Branchid and a.Compid=e.Compid 
				Left Outer Join PAY_ShiftGroupMaster_Hdr b 
					On a.ShiftGroupCode=b.ShiftGroupCode and a.Branchid=b.Branchid and a.Compid=b.Compid 
				Left Outer Join PAY_ShiftGroupMaster_Dtl c 
					On a.ShiftGroupCode=c.ShiftGroupCode and a.Branchid=c.Branchid and a.Compid=c.Compid 
				Left Outer Join PAY_WeekGroupMaster_Hdr w 
					On a.WeekGroupCode=w.WeekGroupCode and a.Branchid=w.Branchid and a.Compid=w.Compid 				
				Full Outer Join (Select a.ShiftGroupCode, a.EmployeeCode, Max(c.ShiftSequence) As MSeq,	Sum(c.PeriodValue) As TotPerVal
						From PAY_AssignedGroup_Master a 
				   		Left Outer Join PAY_ShiftGroupMaster_Hdr b 
				   			On a.ShiftGroupCode=b.ShiftGroupCode and a.Branchid=b.Branchid and a.Compid=b.Compid 
				   		Left Outer Join PAY_ShiftGroupMaster_Dtl c 
				   			On a.ShiftGroupCode=c.ShiftGroupCode and a.Branchid=c.Branchid and a.Compid=c.Compid
						Where  b.EffStatus='1'  and a.EmployeeCode=@mEmp
							and a.EffDate=(Select Max(m.EffDate) As EffDate 
									From PAY_AssignedGroup_Master m 
									Where a.ShiftGroupCode=m.ShiftGroupCode and m.EmployeeCode=@mEmp
										and m.EffDate Between @RptFromDate and @RptToDate and m.Branchid=@BranchID and m.Compid=@CompID
									)
							and a.Branchid=@BranchID and a.Compid=@CompID
						Group by a.ShiftGroupCode, a.EmployeeCode, a.EffDate
						) u
					On a.ShiftGroupCode=u.ShiftGroupCode and a.EmployeeCode=u.EmployeeCode 
				
				Where b.EffStatus='1' 
					and a.EffDate=(Select Max(m.EffDate) As EffDate From PAY_AssignedGroup_Master m
							Where m.EmployeeCode=@mEmp and a.ShiftGroupCode=m.ShiftGroupCode
								and m.EffDate Between @RptFromDate and @RptToDate and m.Branchid=@BranchID and m.Compid=@CompID
							)
					and a.Branchid=@BranchID and a.Compid=@CompID
				Order by a.EffDate, a.ShiftGroupCode, a.EmployeeCode, c.ShiftSequence		
			
			End
		
		Else If @Type='3' 	/*  RptDate & Without EmployeeCode  */

			Begin
		
				Insert into @RetTable
			
				Select a.EmployeeCode, e.EmployeeName, a.ShiftGroupCode, b.ShiftShortName, b.ShiftLongName, 
					b.ShiftGroupDesc, c.ShiftSequence, c.ShiftCode, a.WeekGroupCode,  w.WeekShortName, w.WeekLongName,
					c.PeriodValue, c.PeriodType, u.MSeq,  
					Case When c.IsWOffInclusive='1' Then 'INC' Else 'EXC' End As IsWOffInclusive,				
					Case When c.PeriodType='D' or c.PeriodType='W' Then  DateDiff(dd, a.EffDate,@RptToDate)+1 Else 0 End As DDay,
					Case When c.PeriodType='M' Then  DateDiff(mm, a.EffDate,@RptToDate)+1 Else 0 End As DMon,
					Case When c.PeriodType='Y' Then  DateDiff(yy, a.EffDate,@RptToDate)+1 Else 0 End As DYer,
					u.TotPerVal, b.Remarks, a.EffDate, @RptToDate As FTDate, a.TranStamp
				From (Select * from PAY_Employee_Master Where BranchID=@BranchID and CompID=@CompID and Status='W') e 			
				Left Outer Join PAY_AssignedGroup_Master a 	
					On a.EmployeeCode=e.EmployeeCode and a.Branchid=e.Branchid and a.Compid=e.Compid 
				Left Outer Join PAY_ShiftGroupMaster_Hdr b 
					On a.ShiftGroupCode=b.ShiftGroupCode and a.Branchid=b.Branchid and a.Compid=b.Compid 
				Left Outer Join PAY_ShiftGroupMaster_Dtl c 
					On a.ShiftGroupCode=c.ShiftGroupCode and a.Branchid=c.Branchid and a.Compid=c.Compid 
				Left Outer Join PAY_WeekGroupMaster_Hdr w 
					On a.WeekGroupCode=w.WeekGroupCode and a.Branchid=w.Branchid and a.Compid=w.Compid 				
				Full Outer Join (Select a.ShiftGroupCode, a.EmployeeCode, Max(c.ShiftSequence) As MSeq,	Sum(c.PeriodValue) As TotPerVal
						From PAY_AssignedGroup_Master a 
				   		Left Outer Join PAY_ShiftGroupMaster_Hdr b 
				   			On a.ShiftGroupCode=b.ShiftGroupCode and a.Branchid=b.Branchid and a.Compid=b.Compid 
				   		Left Outer Join PAY_ShiftGroupMaster_Dtl c 
				   			On a.ShiftGroupCode=c.ShiftGroupCode and a.Branchid=c.Branchid and a.Compid=c.Compid
						Where  b.EffStatus='1'  
							and a.EffDate=(Select Max(m.EffDate) As EffDate 
									From PAY_AssignedGroup_Master m 
									Where a.ShiftGroupCode=m.ShiftGroupCode
										and a.EmployeeCode=m.EmployeeCode
										and m.EffDate<=@RptToDate and m.Branchid=@BranchID and m.Compid=@CompID
									)
							and a.Branchid=@BranchID and a.Compid=@CompID
						Group by a.ShiftGroupCode, a.EmployeeCode, a.EffDate
						) u
					On a.ShiftGroupCode=u.ShiftGroupCode and a.EmployeeCode=u.EmployeeCode 
				
				Where b.EffStatus='1' 
					and a.EffDate In (Select Max(m.EffDate) As EffDate From PAY_AssignedGroup_Master m
							Where a.ShiftGroupCode=m.ShiftGroupCode
								and a.EmployeeCode=m.EmployeeCode
								and m.EffDate<=@RptToDate and m.Branchid=@BranchID and m.Compid=@CompID
							Group by m.ShiftGroupCode, m.EmployeeCode
							)
					and a.Branchid=@BranchID and a.Compid=@CompID
				Order by a.EffDate, a.ShiftGroupCode, a.EmployeeCode, c.ShiftSequence		
			
			End


		Else If @Type='4' 	/*  FromDate-ToDate &  Without EmployeeCode*/

			Begin
		
				Insert into @RetTable
			
				Select a.EmployeeCode, e.EmployeeName, a.ShiftGroupCode, b.ShiftShortName, b.ShiftLongName, 
					b.ShiftGroupDesc, c.ShiftSequence, c.ShiftCode, a.WeekGroupCode,  w.WeekShortName, w.WeekLongName,
					c.PeriodValue, c.PeriodType, u.MSeq,  
					Case When c.IsWOffInclusive='1' Then 'INC' Else 'EXC' End As IsWOffInclusive,				
					Case When c.PeriodType='D' or c.PeriodType='W' Then  DateDiff(dd, a.EffDate,@RptToDate)+1 Else 0 End As DDay,
					Case When c.PeriodType='M' Then  DateDiff(mm, a.EffDate,@RptToDate)+1 Else 0 End As DMon,
					Case When c.PeriodType='Y' Then  DateDiff(yy, a.EffDate,@RptToDate)+1 Else 0 End As DYer,
					u.TotPerVal, b.Remarks, a.EffDate, @RptToDate As FTDate, a.TranStamp
				From (Select * from PAY_Employee_Master Where BranchID=@BranchID and CompID=@CompID and Status='W') e 			
				Left Outer Join PAY_AssignedGroup_Master a 	
					On a.EmployeeCode=e.EmployeeCode and a.Branchid=e.Branchid and a.Compid=e.Compid 
				Left Outer Join PAY_ShiftGroupMaster_Hdr b 
					On a.ShiftGroupCode=b.ShiftGroupCode and a.Branchid=b.Branchid and a.Compid=b.Compid 
				Left Outer Join PAY_ShiftGroupMaster_Dtl c 
					On a.ShiftGroupCode=c.ShiftGroupCode and a.Branchid=c.Branchid and a.Compid=c.Compid 
				Left Outer Join PAY_WeekGroupMaster_Hdr w 
					On a.WeekGroupCode=w.WeekGroupCode and a.Branchid=w.Branchid and a.Compid=w.Compid 				
				Full Outer Join (Select a.ShiftGroupCode, a.EmployeeCode, Max(c.ShiftSequence) As MSeq,	Sum(c.PeriodValue) As TotPerVal
						From PAY_AssignedGroup_Master a 
				   		Left Outer Join PAY_ShiftGroupMaster_Hdr b 
				   			On a.ShiftGroupCode=b.ShiftGroupCode and a.Branchid=b.Branchid and a.Compid=b.Compid 
				   		Left Outer Join PAY_ShiftGroupMaster_Dtl c 
				   			On a.ShiftGroupCode=c.ShiftGroupCode and a.Branchid=c.Branchid and a.Compid=c.Compid
						Where  b.EffStatus='1'  
							and a.EffDate=(Select Max(m.EffDate) As EffDate 
									From PAY_AssignedGroup_Master m 
									Where a.ShiftGroupCode=m.ShiftGroupCode
										and a.EmployeeCode=m.EmployeeCode
										and m.EffDate Between @RptFromDate and @RptToDate and m.Branchid=@BranchID and m.Compid=@CompID
									)
							and a.Branchid=@BranchID and a.Compid=@CompID
						Group by a.ShiftGroupCode, a.EmployeeCode, a.EffDate
						) u
					On a.ShiftGroupCode=u.ShiftGroupCode and a.EmployeeCode=u.EmployeeCode 
				
				Where b.EffStatus='1' 
					and a.EffDate In (Select Max(m.EffDate) As EffDate From PAY_AssignedGroup_Master m
							Where a.ShiftGroupCode=m.ShiftGroupCode
								and a.EmployeeCode=m.EmployeeCode
								and m.EffDate Between @RptFromDate and @RptToDate and m.Branchid=@BranchID and m.Compid=@CompID
							Group by m.ShiftGroupCode, m.EmployeeCode
							)
					and a.Branchid=@BranchID and a.Compid=@CompID
				Order by a.EffDate, a.ShiftGroupCode, a.EmployeeCode, c.ShiftSequence		
			
			End

	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_PAY_Get_PFESILimit]    Script Date: 17/06/2026 11:38:49 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_PAY_Get_PFESILimit](@EmpIDKey varchar(36), @EmployeeCode varchar(10), @AsOnDate datetime, @BranchID varchar(3), @CompID varchar(3))     
RETURNS     
    @Result TABLE     
                (    
                 EmployeeCode    varchar(10),    
                 PFApplicable    bit,    
                    PFMaxLimit   money,    
                    ESIApplicable   bit,    
                    ESIMaxLimit     money    
                )    
AS    
BEGIN    
        
    Insert Into @Result    
        Select a.EmployeeCode, isNull(b.PFApplicable, c.PFApplicable), isNull(b.PFMaxLimit, c.PFMaxLimit),     
            isNull(b.ESIApplicable, c.ESIApplicable), isNull(b.ESIMaxLimit, c.ESIMaxLimit)    
        From PAY_Employee_Master a    
        Left Outer Join PAY_PFESILimit_vw b    
            On a.EmployeeCode=b.EmployeeCode and a.BranchID=b.BranchID and a.CompID=b.CompID    
        Left Outer Join    
                (Select * From PAY_PFESILimit_vw Where EmployeeCode='' and BranchID=@BranchID and CompID=@CompID) c    
            On a.CompID=c.CompID    
        Where (    
                    (@EmployeeCode<>'' AND a.EmployeeCode=@EmployeeCode)    
                    OR    
                    (@EmployeeCode='' AND    
                                (@EmpIDKey='' OR     
                                    EXISTS (Select * From COM_SelectList s1    
                                            Where s1.UserKey=@EmpIDKey and s1.SelectInt=a.EmployeeCode    
                                                and s1.CompID=@CompID and s1.BranchID=@BranchID    
                                            )    
                                   )    
                    )    
                )    
     
 RETURN     
END 
GO

/****** Object:  UserDefinedFunction [dbo].[fn_PAY_Salary_Master]    Script Date: 17/06/2026 11:38:49 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION  [dbo].[fn_PAY_Salary_Master](@AsOnDate datetime, @BranchID Varchar(3), @CompID varchar(3))  

RETURNS @Salary TABLE
	 (EmployeeCode	varchar(10),
		ExprGroupID	int,
		Amount	float,
		EDate	datetime,
		SalaryFormula	int,
		OTFormula	int,
		Period	int,
		PeriodExprID	int,
		Status	bit,
		CreatedDate	datetime,
		Userid	varchar(10),
		Branchid	varchar(3),
		Compid	varchar(10))
 AS  


BEGIN 

		Insert into @Salary
	
		Select a.EmployeeCode, a.ExprGroupID, a.Amount, a.EDate, a.SalaryFormula, a.OTFormula, a.Period, a.PeriodExprID, 
		a.Status, a.CreatedDate, a.Userid, a.Branchid, a.Compid
		from PAY_Salary_Master a
			where a.EDate = (select Max(b.EDate) from PAY_Salary_Master b
		      	where b.EmployeeCode = a.EmployeeCode and b.Branchid = a.Branchid and b.Compid = a.Compid 
						and b.EDate <= @AsOnDate) and a.BranchID=@BranchID and a.CompID=@CompID

	return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_PAY_ShiftGroup_Master]    Script Date: 17/06/2026 11:38:49 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_PAY_ShiftGroup_Master] (@SGC varchar(10), @BranchID varchar(3), @CompID varchar(3))  

RETURNS @RetTable TABLE
	(ShiftGroupCode		varchar(10),
	 ShiftShortName	varchar(10),
	 ShiftLongName	varchar(20),
	 ShiftGroupDesc		varchar(50),
	 ShiftSequence		int,
	 ShiftCode		varchar(10),
	 PeriodValue		int,
	 PeriodType		char(1),
	 IsWOffInclusive		bit,
	 Remarks		varchar(50), 
	 EffDate			datetime,
	 EffStatus		bit,
	 UserId 			varchar(10),
	 Branchid 		varchar(3),
	 Compid			varchar(3),
	 TranStamp		datetime
	)


 AS  

BEGIN 


	If @SGC<>'0'

		Begin
			Insert into @RetTable

			Select a.ShiftGroupCode, a.ShiftShortName, a.ShiftLongName, a.ShiftGroupDesc,
			           b.ShiftSequence, b.ShiftCode, b.PeriodValue, b.PeriodType, b.IsWOffInclusive,
			           a.Remarks, b.EffDate, a.EffStatus, a.Userid, a.Branchid, a.Compid, a.TranStamp 
			from PAY_ShiftGroup_Master_Hdr a
			Left Outer Join PAY_ShiftGroup_Master_Dtl b
			On a.ShiftGroupCode=b.ShiftGroupCode and a.Branchid=b.Branchid and a.Compid=b.Compid
			Where a.EffStatus='1' and  a.ShiftGroupCode=@SGC and a.BranchID=@BranchID and a.CompID=@CompID			          
		End	

	Else

		Begin
			Insert into @RetTable

			Select a.ShiftGroupCode, a.ShiftShortName, a.ShiftLongName, a.ShiftGroupDesc,
			           b.ShiftSequence, b.ShiftCode, b.PeriodValue, b.PeriodType, b.IsWOffInclusive,
			           a.Remarks, b.EffDate, a.EffStatus, a.Userid, a.Branchid, a.Compid, a.TranStamp 
			from PAY_ShiftGroup_Master_Hdr a
			Left Outer Join PAY_ShiftGroup_Master_Dtl b
			On a.ShiftGroupCode=b.ShiftGroupCode and a.Branchid=b.Branchid and a.Compid=b.Compid
			Where a.EffStatus='1' and a.BranchID=@BranchID and a.CompID=@CompID			          
		End	
	
	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_PAY_ShiftGroupCycle]    Script Date: 17/06/2026 11:38:49 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION  [dbo].[fn_PAY_ShiftGroupCycle](@RptDate datetime, @BranchID varchar(3), @CompID varchar(3))

RETURNS @RetTable TABLE
	( EmployeeCode		varchar(10), 
	  EmployeeName	varchar(50), 
	  ShiftGroupCode	varchar(10), 		
	  ShiftShortName	varchar(10), 
 	  ShiftLongName 	varchar(20), 
	  ShiftGroupDesc	varchar(50),
	  ShiftSequence 		int,
	  ShiftCode		varchar(10), 
	  ShiftDescription	varchar(50), 
	  StartTime 		datetime,
	  ShiftMinutes 		int, 
	  LunchStartTime 	datetime, 
	  LunchMinutes 		int,   
	  WeekGropupCode	varchar(10), 
	  WHName		varchar(10),
	  PeriodValue		int,
	  PeriodType		char(1),   
	  IsWOffInclusive	bit,
	  Remarks		varchar(50), 
	  EffDate		datetime,
	  TranStamp		datetime,
	  TotPerVal		int,
	  DDay			int,
	  DMon			int,
	 -- DYer			int,
	  FTDate		datetime,
	  WkDayNumb		int,
	  WkDayName		varchar(10),
	  Rem			int	 
	)

 AS  

BEGIN 
		Declare @RecCnt As int
		Declare @TotPerVal As int
		Declare @ActDate As Datetime
		Declare @mDay As int
		Declare @mSGCode As nvarchar(20)
		Declare @mEnter As bit


	--Details
		Insert into @RetTable

		Select *, 
		DatePart(dw,x.FTDate) As WkDayNumb,
		DateName(dw,x.FTDate) As WkDayName,

		IsNull(Case When x.PeriodType='D' Then  
			Case When x.DDay>=x.TotPerVal Then
				Case When (x.DDay % x.TotPerVal)=0 Then
					x.TotPerVal
				Else
					(x.DDay % x.TotPerVal) 
				End
			Else
				x.DDay 
			End
		Else 
			Case When x.PeriodType='W' Then  
				Case When x.DDay>=(x.TotPerVal*7) Then
					Case When (x.DDay % (x.TotPerVal*7))=0 Then
						x.TotPerVal
					Else
						(x.DDay % (x.TotPerVal*7)) 
					End
				Else
					x.DDay 
				End
		/*	Else
				Case When x.PeriodType='M' Then  
					'0'
				Else
					Case When x.PeriodType='Y' Then  
						'0'	*/
		End End,'0') As Rem
		
		From (

		Select a.EmployeeCode, e.EmployeeName, a.ShiftGroupCode, b.ShiftShortName, b.ShiftLongName, 
		b.ShiftGroupDesc,  c.ShiftSequence, c.ShiftCode, s.ShiftDescription, 
		s.StartTime As ShiftStartTime, s.ShiftMinutes As ShiftMinutes, 
		s.LunchStartTime As ShiftLunchStartTime, s.LunchMinutes As ShiftLunchMinutes, a.WeekGroupCode, 
	/*	IsNull((Select h.WHName From PAY_WeekHoliday h Where a.WHCode=h.WHCode),'') As WHName, 	*/
		c.PeriodValue, c.PeriodType, c.IsWOffInclusive, b.Remarks, a.EffDate, a.TranStamp, TotPerVal,

		Case When c.PeriodType='D' or c.PeriodType='W' Then  
		DateDiff(dd, a.EffDate,@RptDate)+1 Else 0 End As DDay,
		Case When c.PeriodType='M' Then  
		DateDiff(mm, a.EffDate,@RptDate)+1 Else 0 End As DMon,
		Case When c.PeriodType='Y' Then  
		DateDiff(yy, a.EffDate,@RptDate)+1 Else 0 End As DYer,

	/*	Case When c.PeriodType='D' or c.PeriodType='W' Then  
		DateAdd(dd,DateDiff(dd, a.EffDate,@RptDate),a.EffDate) 
		Else
		Case When c.PeriodType='M' Then  
		DateAdd(mm,DateDiff(mm, a.EffDate,@RptDate),a.EffDate) 
		Else
		Case When c.PeriodType='Y' Then  
		DateAdd(yy,DateDiff(yy, a.EffDate,@RptDate),a.EffDate) 
		End End End As FTDate,   */

		@RptDate As FTDate
		
		From PAY_AssignedGroup_Master a 

		Left Outer Join PAY_Employee_Master e 
		On a.EmployeeCode=e.EmployeeCode and a.Branchid=e.Branchid and a.Compid=e.Compid 
		Left Outer Join PAY_ShiftGroupMaster_Hdr b 
		On a.ShiftGroupCode=b.ShiftGroupCode and a.Branchid=b.Branchid and a.Compid=b.Compid 
		Left Outer Join PAY_ShiftGroupMaster_Dtl c 
		On a.ShiftGroupCode=c.ShiftGroupCode and a.Branchid=c.Branchid and a.Compid=c.Compid 
		Left Outer Join PAY_Shift_Master s 
		On c.ShiftCode=s.ShiftCode and a.Branchid=s.Branchid and a.Compid=s.Compid 

		Full Outer Join (Select a.ShiftGroupCode, a.EmployeeCode, Sum(c.PeriodValue) As TotPerVal
		From PAY_AssignedGroup_Master a 
		   Left Outer Join PAY_ShiftGroupMaster_Hdr b 
		   On a.ShiftGroupCode=b.ShiftGroupCode and a.Branchid=b.Branchid and a.Compid=b.Compid 
		   Left Outer Join PAY_ShiftGroupMaster_Dtl c 
		   On a.ShiftGroupCode=c.ShiftGroupCode and a.Branchid=c.Branchid and a.Compid=c.Compid 
		Where  b.EffStatus='1' and a.EffDate<=@RptDate and  a.Branchid=@BranchID and a.Compid=@CompID
		Group by a.ShiftGroupCode, a.EmployeeCode, a.EffDate
		) u
		On a.ShiftGroupCode=u.ShiftGroupCode and a.EmployeeCode=u.EmployeeCode 

		Where b.EffStatus='1' and e.Status='W' and a.EffDate<=@RptDate
		            and  a.Branchid=@BranchID and a.Compid=@CompID 
		) x
		Order by x.ShiftGroupCode, x.EmployeeCode, x.ShiftSequence					

	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_PAY_WeekGroup_Master]    Script Date: 17/06/2026 11:38:49 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION  [dbo].[fn_PAY_WeekGroup_Master](@mWGC varchar(10), @BranchID varchar(3), @CompID varchar(3))

RETURNS @RetTable TABLE
	( WeekGroupCode	varchar(10), 	
	  WeekShortName	varchar(10), 
	  WeekLongName	varchar(20),
	  WeekGroupDesc  	varchar(50), 
  	  WHcode		varchar(10), 
	  WHName		varchar(50), 
	  WeekNo		int,
	  OffValue		int,	
 	  Remarks		varchar(50), 
	  EffDate		datetime,
	  TranStamp		datetime
	)


 AS  

BEGIN 
		

		Insert into @RetTable
	
		Select a.WeekGroupCode, a.WeekShortName, a.WeekLongName, a.WeekGroupDesc, 
		b.WHcode, c.WHName, b.WeekNo, b.OffValue,
		a.Remarks, a.EffDate, a.TranStamp From PAY_WeekGroupMaster_Hdr a
		Left Outer Join PAY_WeekGroupMaster_Dtl b 
		On a.WeekGroupCode=b.WeekGroupCode and a.Branchid=b.Branchid and a.Compid=b.Compid
		Left Outer Join PAY_WeekHoliday c
		On b.WHCode=c.WHCode
		Where a.EffStatus='1' and a.WeekGroupCode=@mWGC
		and a.Branchid=@BranchID and a.Compid=@CompID
		Order by a.WeekGroupCode, b.WHCode, b.WeekNo


	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[Fn_PPC_MCAnalysis]    Script Date: 17/06/2026 11:38:49 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[Fn_PPC_MCAnalysis](@PlanMonth varchar(7), @PlanPeriod Datetime,  @Branchid varchar(3), @Compid varchar(3), @FinYear varchar(20))

	RETURNS @RetTable TABLE
		(ItemCode 					varchar(20),
		 StageCode 					varchar(20),
		 PartNo	 					varchar(20),
		 PlanQty	 				float,
                            invoiceqty	 				int,
		 GReqQty	 				float,
		 RMStockQty					float,
		 Rate		 				float,
		 RmRate					float,
		 Norms 						float,	
		 CustomerCode					int,
 		 OperationSequence				int,
		 Branchid 					varchar(3),
		 Compid 					varchar(3),
		 FinYear						varchar(20))
	AS  
	
	Begin
	    Insert @RetTable
		Select distinct a.Itemcode,b.Stagecode as sCode, g.PartNo,a.PlanQty,isnull((select sum(k.invoiceqty)
                                        from salesinvoice k where  e.itemcode=k.itemcode and e.compid=k.compid and e.Finyear=k.Finyear
                                       and e.CustomerCode=k.CustomerCode and month(k.invoicedate)=substring(convert(varchar(7),@PlanPeriod,126),6,7) and 
                                        year(k.invoicedate)= convert(varchar(4),@PlanPeriod,126)),0)invoiceqty, (a.PlanQty*b.Norms) as GrossReq,
			isnull(CBQty,0) as RMStockQty,case when e.Rate > 0 then e.Rate else g.Rate end as CRate,
                                        
			i.Rate as RMRate,b.Norms,a.CustomerCode,b.OperationSequence
			,a.Branchid,a.Compid,a.FinYear
		From  dbo.fn_SAL_SalesPlan (@PlanPeriod,@PlanPeriod,@Branchid,@Compid,@Finyear) a 
		Left Outer Join MPS_Process b 
			On a.Itemcode = b.Itemcode and a.Branchid=b.Branchid and a.Compid=b.Compid 
		Left Outer Join fn_INV_AsOnDate_Stock (@PlanPeriod,@Branchid,@Compid,@Finyear)c 
			--On a.Itemcode = c.Itemcode and a.Branchid=c.Branchid and a.Compid=c.Compid-- and c.WarehouseCode in (@WhsCode)
                                       On b.stagecode = c.Itemcode and a.Branchid=c.Branchid and a.Compid=c.Compid-- and c.WarehouseCode in (@WhsCode)
		Left Outer Join INV_MATERIAL_MASTER d 
			On b.Stagecode = d.Itemcode and a.Branchid=d.Branchid 	and a.Compid=d.Compid and b.OperationSequence =0
		Left Outer Join SalesOrder e 
			On a.CustomerCode=e.CustomerCode and a.ItemCode=e.ItemCode and a.Branchid=e.Branchid
				and a.Compid=e.Compid and a.Finyear=e.Finyear
		Left Outer Join SAL_CUSTOMER_ITEMMASTER g 
			On a.CustomerCode=g.CustomerCode and b.Itemcode = g.Itemcode and a.Branchid=g.Branchid and a.Compid=g.Compid 
                         Left Outer Join PUR_PurchaseOrder_Dtl i on  i.itemcode=b.stagecode
 
			Where a.PlanFor=2 and convert(varchar(7),a.PlanPeriod,126)= @PlanMonth and b.OperationSequence = '0'
                                                    and  e.createddate= (select max(h.createddate) from SalesOrder h where
                                                    a.CustomerCode=h.CustomerCode and a.ItemCode=h.ItemCode and a.Branchid=h.Branchid
				and a.Compid=h.Compid and a.Finyear=h.Finyear)
                                                     and e.itemstatus='m' 
                                                    and i.createddate=(select max(j.createddate) from PUR_PurchaseOrder_Dtl j where
                                                    j.itemcode=b.stagecode and j.Compid=a.Compid and j.Finyear=a.Finyear)
				--------and a.Branchid=@Branchid and a.Compid=@Compid and a.Finyear=@Finyear and c.WarehouseCode <> '' and CBQty > 0
                                                            and a.Branchid=@Branchid and a.Compid=@Compid and a.Finyear=@Finyear and c.WarehouseCode in( 'RMS','fgs','csf')  and CBQty > 0
			--Group By a.Itemcode,b.Stagecode , g.PartNo,a.PlanQty,g.Rate,e.Rate,d.Rate,b.Norms,
				--a.CustomerCode,b.OperationSequence,c.WarehouseCode,a.Branchid,a.Compid,a.FinYear
			Order by a.Itemcode, b.OperationSequence
	    Return
	End






















GO

/****** Object:  UserDefinedFunction [dbo].[Fn_PPC_MCAnalysis_Display]    Script Date: 17/06/2026 11:38:49 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[Fn_PPC_MCAnalysis_Display](@PriodMonth varchar(7),@Period Datetime,@Branchid varchar(3),@Compid varchar(3),@FinYear varchar(20))

	RETURNS @RetTable TABLE
		(ItemCode 		varchar(20),
		 StageCode 		varchar(20),
		 PartNo	 		varchar(20),
		 PlanQty	 	float,
                            InvoiceQty	 	int,
		 GReqQty	 	float,
		 StockQty		float,
		 RMQty			float,
		 WIPQty		float,
		 SubQty			float,
		 Rate		 	float,
		 RmRate		float,
		 SubRate		float,
		 Norms			float,
		 Branchid 		varchar(3),
		 Compid 		varchar(3),
		 FinYear			varchar(20))
	AS  
	
	Begin
		Insert @RetTable

			Select distinct a.ItemCode,a.StageCode,a.PartNo,a.PlanQty,a.InvoiceQty,a.GReqQty,
			isnull(c.StockQty,0) as StockQty,isnull(sum(a.RMStockQty),0) as RMQty,
			isnull(b.StockQty,0) as WIPQty,isnull(d.StockQty,0) as SubQty,
			a.Rate,a.RmRate,isnull(d.Rate,0) as SubRate,a.Norms,
			a.Branchid,a.Compid,a.FinYear 
			From dbo.Fn_PPC_MCAnalysis(@PriodMonth,@Period,@BranchID, @CompID,@FinYear) a
			Left Outer Join dbo.Fn_PPC_MCAnalysis_Stage(@Period,@BranchID, @CompID,@FinYear)b
			On b.Itemcode = a.Itemcode and a.Branchid=b.Branchid and a.Compid=b.Compid 
			Left Outer Join dbo.Fn_PPC_MCAnalysis_StageAll(@Period,@BranchID, @CompID,@FinYear)c
			On a.Itemcode = c.Itemcode and a.Branchid=c.Branchid and a.Compid=c.Compid 
			Left Outer Join dbo.Fn_PPC_MCAnalysis_SubStage(@Period,@BranchID, @CompID,@FinYear)d
			On a.Itemcode = d.Itemcode and a.Branchid=d.Branchid and a.Compid=d.Compid 
			Where a.Branchid= @BranchID and a.Compid= @CompID and a.Finyear= @FinYear
			Group By a.ItemCode,a.StageCode,a.PartNo,a.PlanQty,a.InvoiceQty,a.GReqQty,b.StockQty,c.StockQty,d.StockQty,a.Rate,a.RmRate,a.Norms,
			d.Rate,a.Branchid,a.Compid,a.FinYear

	 	Return
	End
GO

/****** Object:  UserDefinedFunction [dbo].[Fn_PPC_MCAnalysis_Stage]    Script Date: 17/06/2026 11:38:49 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[Fn_PPC_MCAnalysis_Stage](@Period Datetime,@Branchid varchar(3),@Compid varchar(3),@FinYear varchar(20))

	RETURNS @RetTable TABLE
		(ItemCode 		varchar(20),
		 StockQty		float,
		 Branchid 		varchar(3),
		 Compid 		varchar(3))
	AS  	
	Begin

	    Insert @RetTable
				Select distinct a.Itemcode, isnull(sum(CBQty),0) as StockQty,
					a.Branchid,a.Compid
				From  MPS_Process a
				Left Outer Join fn_INV_AsOnDate_Stock_WIP(@Period,@Branchid,@Compid,@Finyear)c 
					on a.Stagecode = c.Itemcode and a.Branchid=c.Branchid and a.Compid=c.Compid  
					Where a.OperationSequence <> '0' and CBQty > 0 and a.Branchid=@Branchid and a.Compid=@Compid 
				Group By  a.Itemcode,a.Branchid,a.Compid
				order by a.Itemcode
	    Return
	End
GO

/****** Object:  UserDefinedFunction [dbo].[Fn_PPC_MCAnalysis_StageAll]    Script Date: 17/06/2026 11:38:49 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[Fn_PPC_MCAnalysis_StageAll](@Period Datetime,@Branchid varchar(3),@Compid varchar(3),@FinYear varchar(20))

	RETURNS @RetTable TABLE
		(ItemCode 		varchar(20),
		 StockQty		float,
		 Branchid 		varchar(3),
		 Compid 		varchar(3))
	AS  	
	Begin

	    Insert @RetTable
				Select distinct b.Itemcode, isnull(sum(CBQty),0) as StockQty,
					a.Branchid,a.Compid
				From  PPC_MCAnalysis_Tmp a
				Left Outer Join fn_INV_AsOnDate_Stock(@Period,@Branchid,@Compid,@Finyear)b 
					On  a.WHCode = b.WareHouseCode and a.Branchid=b.Branchid and a.Compid=b.Compid  
				Left Outer Join Inv_Material_Master c
					On  b.ItemCode =c.ItemCode and b.Branchid=c.Branchid and b.Compid=c.Compid  
					Where  CBQty >= 0 and a.Branchid=@Branchid and a.Compid=@Compid  and c.ItemNature  Not In ('R','CR')
				Group By b.Itemcode,a.Branchid,a.Compid
				Order by b.Itemcode
	    Return
	End
GO

/****** Object:  UserDefinedFunction [dbo].[Fn_PPC_MCAnalysis_SubStage]    Script Date: 17/06/2026 11:38:49 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[Fn_PPC_MCAnalysis_SubStage](@Period Datetime,@Branchid varchar(3),@Compid varchar(3),@FinYear varchar(20))

	RETURNS @RetTable TABLE
		(ItemCode 		varchar(20),
		 StockQty		float,
		 Rate			float,
		 Branchid 		varchar(3),
		 Compid 		varchar(3))
	AS  	
	Begin
	
	    Insert @RetTable
		Select distinct a.Itemcode, isnull(sum(CBQty),0) as StockQty,b.Rate,a.Branchid,a.Compid
		From  MPS_Process a
		Left Outer Join (Select  *  from PUR_LaborOrder_Dtl a1
			Where a1.CreatedDate = (Select Max(b1.CreatedDate) from PUR_LaborOrder_Dtl b1 
					Where b1.CreatedDate <=@Period
					and b1.SentItemCode=a1.SentItemCode and b1.RecdItemCode=a1.RecdItemCode and b1.BranchID=a1.BranchID 
					and b1.CompID=a1.CompID)
				and ((a1.EffStatus='1' and a1.EffDate <=@Period) or (a1.EffStatus='0' and a1.EffDate > @Period))
				and a1.BranchID=@Branchid  and a1.CompID=@Compid ) b
			On a.Stagecode = b.SentItemcode and a.Branchid=b.Branchid and a.Compid=b.Compid 
		Left Outer Join fn_INV_AsOnDate_Stock_Sub(@Period,@Branchid,@Compid,@Finyear)c 
			On b.SentItemcode = c.Itemcode and a.Branchid=c.Branchid and a.Compid=c.Compid  
			Where b.SentItemcode <> ''  and CBQty > 0 and a.OperationSequence <> '0' and a.Branchid=@Branchid 
			and a.Compid=@Compid and IsActive = 1
		Group By a.Itemcode,b.Rate,a.Branchid,a.Compid
		Order By a.Itemcode
	    Return
	End
GO

