CREATE FUNCTION [dbo].[fn_PPC_MRP] (@AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE
	(DocType	varchar(3),
	DocNo		int,
	DocDate		datetime,
	MRPFor		int,
	MRPPeriod	datetime,
	ItemCode	varchar(20),
	Store		float,
	UI		float,
	WIp		float,
	IStore		float,
	IUI		float,
	IWIp		float,
	ReqQty		float,
	RevNo		int,
	EffStatus	bit,
	EffDate		datetime,
	CreatedDate	datetime,
	Userid		varchar(10),
	Branchid	varchar(3),
	Compid		varchar(3),
	Finyear		varchar(20),
	TranStamp	datetime
	)


 AS  

BEGIN 
	Insert @RetTable
		Select * from PPC_MRP a
		Where a.CreatedDate = (Select Max(b.CreatedDate) from PPC_MRP b where b.CreatedDate <= @AsOnDate 
			and b.DocType=a.DocType and b.DocNo=a.DocNo and b.DocDate=a.DocDate 
			and a.MRPFor = b.MRPFor and a.MRPPeriod = b.MRPPeriod
			and b.BranchID=a.BranchID and b.CompID=a.CompID 
/*			and b.Finyear=a.Finyear		*/
			)
		and ((a.EffStatus='1' and a.EffDate <= @RptDate) or (a.EffStatus='0' and a.EffDate > @RptDate))
			and a.BranchID=@BranchID and a.CompID=@CompID 
/*			and a.Finyear=@Finyear		*/

	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_PPC_PlanAvailable_Stock]    Script Date: 17/06/2026 11:38:49 ******/
