GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_PPC_PlanAvailable_Stock] (@ItemCode varchar(20),  @BranchID varchar(3), @CompID varchar(3))  

RETURNS @Item TABLE (
	Itemcode varchar(20),
	Norms float
) 
		AS  
			BEGIN 
				insert @Item
				select StageCode , isnull((select dbo.fn_ItemNorms (StageCode,@Itemcode, @BranchID, @CompID)),1)Norms  
				from MPS_Process a where ItemCode = (select Top 1 ItemCode from mpsmaster where StageCode = @Itemcode
				and Branchid = @BranchID and Compid = @CompID)
				and OperationSequence = (select Top 1 OperationSequence -1
				from mpsmaster where StageCode = @Itemcode and Branchid = @BranchID and Compid = @CompID)
				return
			END
GO

