CREATE FUNCTION [dbo].[fn_PPC_ProductionPlan_Dtl_V2] (@AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(15))              
RETURNS @RetTable TABLE            
(
     DocType varchar(3),            
     DocNo  int,            
     DocDate datetime,            
     PlanFor  int,            
     PlanPeriod datetime,            
     ItemCode varchar(20),            
     PlanQty  float,      
     RevisionNo int,            
     EffStatus bit,            
     EffDate  datetime,            
     CreatedDate datetime,            
     Userid  varchar(10),            
     Branchid varchar(3),            
     Compid  varchar(3),            
     Finyear  varchar(20),            
     TranStamp datetime            
 )            
AS              
BEGIN             
    Insert @RetTable            
        Select * from PPC_ProductionPlan a            
        Where a.CreatedDate = (Select Max(b.CreatedDate) from PPC_ProductionPlan b where b.CreatedDate <= @AsOnDate             
                and b.DocNo=a.DocNo and b.DocDate=a.DocDate and b.DocType=a.DocType             
                and a.ItemCode = b.ItemCode             
                and a.PlanFor = b.PlanFor and a.PlanPeriod = b.PlanPeriod            
                and b.BranchID=a.BranchID and b.CompID=a.CompID             
                and b.Finyear=a.Finyear           
            )            
            and ((a.EffStatus='1' and a.EffDate <= @RptDate) or (a.EffStatus='0' and a.EffDate > @RptDate))            
            and a.BranchID=@BranchID and a.CompID=@CompID  and a.Finyear=@Finyear           
          
            
    RETURN             
END   
  
GO

