@ShiftUserkey3 varchar(36)='', @RptOpt as varchar(1), @FromDate datetime, @ToDate datetime,  @AsOnDate datetime,         
@RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))                    
                                              
RETURNS @RetTbl TABLE        
  ( [ItemCode] varchar(20),        
  [ItemDesc] varchar(50)        
 )               
