				and (@ShiftUserkey2='' OR Exists (Select * From COM_SelectList s2    
						Where s2.UserKey=@ShiftUserkey2 and Convert(datetime,s2.SelectStr,120)>=a.StartTime    
							and s2.BranchID=@BranchID and s2.CompID=@CompID))    
							and (@ShiftUserkey3='' OR Exists (Select * From COM_SelectList s3    
						Where s3.UserKey=@ShiftUserkey3 and a.TranStamp<=Convert(datetime,s3.SelectStr,120)             
			and s3.BranchID=@BranchID and s3.CompID=@CompID))    
			and a.BranchID = @BranchID and a.CompID = @CompID       
                
			UNION        
           
			Select Distinct a.ItemCode,b1.ItemDesc As ItemDescription            
			From QC_Inspection_Hdr a					-- (Not in used) QC_Inspection_Hdr1 a           
			Left Outer Join QC_Inspection_Criteria1 a1               -- (Not in used) QC_Inspection_Criteria    
			On a1.InspectionType =a.InspectionType and a1.InspectionNo = a.InspectionNo         
				and a.InspectionDate=a1.InspectionDate           
				and a.BranchID=a1.BranchID and a.CompID=a1.CompID           
			Left Outer Join dbo.fn_BOM_Material_Master('A', @AsOnDate, @RptDate, @BranchID, @CompID) b1            
			On a.ItemCode=b1.ItemCode and a.BranchID=b1.BranchID and a.CompID=b1.CompID           
			Where a1.InspectionDate between @FromDate and @ToDate        
				and (@ShiftUserkey2='' OR Exists (Select * From COM_SelectList s2                                                                           
			Where s2.UserKey=@ShiftUserkey2 and Convert(datetime,s2.SelectStr,120)>=a1.TranStamp     
				and s2.BranchID=@BranchID and s2.CompID=@CompID))    
				and (@ShiftUserkey3='' OR Exists (Select * From COM_SelectList s3                                                                           
						Where s3.UserKey=@ShiftUserkey3 and a.TranStamp<=Convert(datetime,s3.SelectStr,120)    
							and s3.BranchID=@BranchID and s3.CompID=@CompID))    
				and a.BranchID = @BranchID and a.CompID = @CompID          
			Order by a.ItemCode          
  End                  
 Else         
  Begin          
*/	        
	 --Insert Data        
		Insert Into @RetTbl         
             
		Select Distinct x2.Itemcode, IsNull(b1.ItemDesc,'') As ItemDescription            
		From (          
				 select a.StageCode as Itemcode  
				 From PPC_Vw_QuickProductionplan_Dtl a                     -- (Not in used) PPC_Vw_QuickProductionplan_Dtl_His        
				 Left Outer Join QC_Inspection_Criteria b                   -- (Not in used) QC_Inspection_Criteria1
					On a.DocNo=b.RefNo and a.DocDate=b.RefDate and a.DocType=b.RefType and a.Shift=b.Shift and a.StartTime=b.StartTime    
						and a.MachineCode=b.MachineCode /* and a.Assetcode=b.Assetcode */ and a.Stagecode=b.ItemCode   				    
					Where a.StartTime >= @Fromdate and a.EndTime <= @Todate         
						and (@ShiftUserkey1='' OR Exists (Select * From COM_SelectList s1    
								Where s1.UserKey=@ShiftUserkey1 and s1.SelectStr=a.Shift    
									and s1.BranchID=@BranchID and s1.CompID=@CompID))    
						and (@ShiftUserkey2='' OR Exists (Select * From COM_SelectList s2    
								Where s2.UserKey=@ShiftUserkey2 and Convert(datetime,s2.SelectStr,121)>=b.StartTime    
									and s2.BranchID=@BranchID and s2.CompID=@CompID))    
						/* and (@ShiftUserkey3='' OR Exists (Select * From COM_SelectList s3    
								Where s3.UserKey=@ShiftUserkey3 /* and a.TranStamp<=Convert(datetime,s3.SelectStr,121) */
									and s3.BranchID=@BranchID and s3.CompID=@CompID)) */            
						and [Type] In('LR','R') and CriteriaCode<>14 and a.OperationName<>'Setting' 
						and a.BranchID=@BranchID and a.CompID=@CompID  
			) x2          
		Left Outer Join dbo.fn_BOM_Material_Master('A', @AsOnDate, @RptDate, @BranchID, @CompID) b1            
			On x2.ItemCode=b1.ItemCode          
		Order by x2.ItemCode                   
  --End        

 RETURN
END 
GO

/****** Object:  UserDefinedFunction [dbo].[fn_Pur_Advance_Order]    Script Date: 17/06/2026 11:38:49 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO



CREATE FUNCTION [dbo].[fn_Pur_Advance_Order] (@ItemCode varchar(20),@Price  Float,@OrderType varchar(3), @OrderNo int, @OrderDate datetime, @BranchID varchar(3), @CompID varchar(3))  

RETURNS @ItemStructure TABLE
	(Itemcode	varchar(20),
	StageDesc	varchar(20),
	AdvancePerc	float,
	AdvanceAmt 	float,
	Stage		int,
	BranchID	varchar(3),
	CompID		varchar(3))

AS  

BEGIN 


	Insert into @ItemStructure	
		
		select c.ItemCode, d.stage, isnull(d.AdvancePerc, 0) as AdvancecPerc, ((AdvancePerc/100)*@Price) as AdvanceAmt, c.Stage , c.Branchid, c.Compid 
		from
		(		Select case when a.challanQty <> 0 and a.Receiptdate is NULL then '110' when a.AcceptedDate is NULL then '120' when a.AcceptedDate is not NULL then '130' else '0' end as Stage,
/*				select case when a.challanQty <> 0 and a.Receiptdate is NULL then '110' else
				case when a.AcceptedDate is NULL then '120' else 
				case when a.AcceptedDate is not NULL then '130' else '0' end end end as Stage, */
					a.ItemCode, b.OrderType, b.OrderNo, b.OrderDate, b.Branchid, b.Compid 
				from REC_RECEIPTENTRY_Dtl a
				
				left Outer join
					(
						select DcsrType, DcsrNo, DcsrDate, OrderType, OrderNO, OrderDate, Branchid, Compid  from Pur_Dcsr_Hdr
							
						union all
							
						select ScheduleType, ScheduleNo, ScheduleDate, OrderType, OrderNo, Orderdate, Branchid, Compid from Pur_Schedule
							
					) b 
				on b.DcsrType=a.RefType and b.DcsrNo=a.RefNo  and b.DcsrDate=a.RefDate and b.Branchid=a.Branchid and b.Compid=a.Compid
				where a.Branchid=@Branchid and a.Compid=@Compid
		) c
		
		left outer join  Pur_Order_Advance d 
		on c.OrderType=d.OrderType and c.OrderNo=d.OrderNo and c.OrderDate=d.OrderDate and c.Stage=d.WorkPerc and d.Branchid=c.Branchid and d.Compid=c.Compid
		where c.OrderType=@OrderType and c.OrderNo=@OrderNo and c.OrderDate=@OrderDate and c.Branchid=@Branchid and c.Compid=@Compid


	Return

/*

		Declare @Qty float
		Declare @Rate float


		While @Level >= 1
			Begin
				Declare curItem Cursor For
				
					Select ParentCode, ItemCode, Itemtype, Qty, StructureLevel, Seq, Rate from @ItemStructure Where StructureLevel=@Level
		
		
				Open curItem
		
				Fetch Next From curItem into @Parent, @Item, @ItemType, @Qty, @StructureLevel, @Seq, @Rate
		
				While @@Fetch_Status = 0
					Begin
						if @ItemType='C'
							Begin
								If exists (Select * from @ItemStructure Where ParentCode=@Item and StructureLevel = @Level+1)
									Begin
										Select @Rate =  isNull((Select Sum(CumRate) from @ItemStructure where ParentCode=@Item and StructureLevel=@Level+1), 0)
									End

								Update @ItemStructure Set CumRate = CumRate + @Rate
								Where ParentCode=@Parent and ItemCode=@Item and StructureLevel=@Level

								Update @ItemStructure Set CumRate = CumRate + @Rate
								Where ParentCode = (Select ParentCode from @ItemStructure Where ItemCode=@Parent and StructureLevel=@Level-1)
								and StructureLevel=@Level-1
							End
						else
							Begin
								Update @ItemStructure Set CumRate = CumRate +
									 isNull((Select Sum(Rate) from @ItemStructure where Seq <= @Seq and StructureLevel=@Level and ParentCode=@Parent), 0)
								Where ParentCode=@Parent and ItemCode=@Item and @StructureLevel=@Level

							End

							
						Fetch Next From curItem into @Parent, @Item, @ItemType, @Qty, @StructureLevel, @Seq, @Rate
					End

				Close curItem
				Deallocate curItem

*/
END




GO

/****** Object:  UserDefinedFunction [dbo].[fn_PUR_DCSR]    Script Date: 17/06/2026 11:38:49 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_PUR_DCSR] ( @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))        
      
RETURNS @RetTable TABLE      
 (DCSRType varchar(3),      
 DCSRNo int,      
 DCSRDate datetime,      
 OrderType varchar(3),      
 OrderNo int,      
 OrderDate datetime,      
 VendorCode int,      
 ItemGroupKey int,      
 SentItemCode varchar(20),       
 RecdItemCode varchar(20),      
 Norms  float,      
 DCSRQty float,      
 PendingQty float,      
 Branchid varchar(3),      
 Compid  varchar(3),      
 Finyear  varchar(20)      
 )      
      
      
 AS        
      
BEGIN       
 Insert @RetTable      
  Select distinct a.DCSRType, a.DCSRNo, a.DCSRDate, a.OrderType, a.OrderNo, a.OrderDate, a.VendorCode,c.ItemGroupKey,      
   c.SentItemCode,b.RecdItemCode,c.Norms,      
    (select sum(d.ScheduleQty) from dbo.fn_PUR_DCSR_Schedule (@AsonDate,@RptDate,@Branchid,@Compid,@Finyear) d      
     where d.DcsrType=c.DcsrType and d.DcsrNo=c.DcsrNo and d.DcsrDate=c.DcsrDate and d.Branchid=c.Branchid and Status<>'C'      
      and d.Compid=c.Compid and d.ItemGroupKey=c.ItemGroupKey and d.Finyear=c.Finyear       
     Group by d.DCSRType, d.DCSRNo, d.DCSRDate,d.ItemGroupKey,       
      d.BranchID, d.CompID, d.Finyear) as DcsrQty,      
    (select sum(d.ScheduleQty) from dbo.fn_PUR_DCSR_Tran_min  (@AsonDate,@RptDate,@Branchid,@Compid,@Finyear) d      
     where d.DcsrType=c.DcsrType and d.DcsrNo=c.DcsrNo and d.DcsrDate=c.DcsrDate and d.Branchid=c.Branchid       
      and d.Compid=c.Compid and d.ItemGroupKey=c.ItemGroupKey and d.SentItemCode=c.SentItemCode and d.Finyear=c.Finyear       
     Group by d.DCSRType, d.DCSRNo, d.DCSRDate,d.ItemGroupKey, d.SentItemCode,      
      d.Norms, d.BranchID, d.CompID, d.Finyear) as PendingQty,      
   a.BranchID, a.CompID, a.Finyear       
  from PUR_DCSR_Hdr a      
  left outer join dbo.fn_PUR_DCSR_Schedule (@AsonDate,@RptDate,@Branchid,@Compid,@Finyear)b      
  On a.DCSRType=b.DCSRType and a.DCSRNo=b.DCSRNo and a.DCSRDate=b.DCSRDate       
   and b.ItemGroupKey=b.ItemGroupKey and a.BranchID=b.BranchID and a.CompID=b.CompID      
  left outer join dbo.fn_PUR_DCSR_Tran  (@AsonDate,@RptDate,@Branchid,@Compid,@Finyear) c      
  On c.DCSRType=b.DCSRType and c.DCSRNo=b.DCSRNo and c.DCSRDate=b.DCSRDate       
   and c.ItemGroupKey=b.ItemGroupKey and c.SchDate=b.RequiredDate and c.BranchID=b.BranchID and c.CompID=b.CompID      
  Where b.Status <> 'C'      
      
 Return       
      
END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_PUR_DCSR_Schedule]    Script Date: 17/06/2026 11:38:49 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_PUR_DCSR_Schedule] ( @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))      
    
RETURNS @RetTable TABLE    
 (DCSRType varchar(3),    
 DCSRNo int,    
 DCSRDate datetime,    
 ItemGroupKey int,    
 RecdItemCode varchar(20),    
 RequiredDate datetime,    
 ScheduleQty float,    
 Status  char(1),    
 StatusDate datetime,    
 EffStatus bit,    
 EffDate  datetime,    
 CreatedDate datetime,    
 Userid  varchar(10),    
 Branchid varchar(3),    
 Compid  varchar(3),    
 Finyear  varchar(20),    
 TranStamp datetime    
 )    
    
    
 AS      
    
BEGIN     
 Insert @RetTable    
  Select * from PUR_DCSR_Schedule a    
  Where a.CreatedDate = (Select Max(b.CreatedDate) from PUR_DCSR_Schedule b where b.CreatedDate <= @AsOnDate     
   and b.DCSRNo=a.DCSRNo and b.DCSRDate=a.DCSRDate and b.DCSRType=a.DCSRType     
   and a.ItemGroupKey=b.ItemGroupKey and b.RecdItemCode=a.RecdItemCode and b.RequiredDate=a.RequiredDate    
   and b.BranchID=a.BranchID and b.CompID=a.CompID    
   )    
  and ((a.EffStatus='1' and a.EffDate <= @RptDate) or (a.EffStatus='0' and a.EffDate > @RptDate))    
   and a.BranchID=@BranchID and a.CompID=@CompID --and a.Finyear=@Finyear    
    
 Return     
    
END 
GO

