CREATE FUNCTION [dbo].[fn_PUR_DCSR_Schedule_FromTo] (@FromDate datetime, @ToDate datetime, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

