GO

CREATE FUNCTION [dbo].[fn_PUR_DCSR1] ( @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE
	(DCSRType	varchar(3),
	DCSRNo	int,
	DCSRDate	datetime,
	OrderType	varchar(3),
	OrderNo	int,
	OrderDate	datetime,
	VendorCode	int,
	ItemGroupKey	int,
	SentItemCode	varchar(20),	
	RecdItemCode	varchar(20),
	Norms		float,
	DCSRQty	float,
	PendingQty	float,
	Branchid	varchar(3),
	Compid		varchar(3),
	Finyear		varchar(20)
	)


 AS  

BEGIN 
	Insert @RetTable
		Select a.DCSRType, a.DCSRNo, a.DCSRDate, a.OrderType, a.OrderNo, a.OrderDate, a.VendorCode,
			b.ItemGroupKey, b.SentItemCode, c.RecdItemCode, b.Norms, Sum(ScheduleQty) as DCSRQty,  Sum(b.Qty) as PendingQty, a.BranchID, a.CompID, a.Finyear
		from PUR_DCSR_Hdr a Left Outer Join PUR_DCSR_Tran b
		On a.DCSRType=b.DCSRType and a.DCSRNo=b.DCSRNo and a.DCSRDate=b.DCSRDate and a.BranchID=b.BranchID and a.CompID=b.CompID
		Left Outer Join (Select * from dbo.fn_PUR_DCSR_Schedule ( @AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) where Status='A') c
		On a.DCSRType=c.DCSRType and a.DCSRNo=c.DCSRNo and a.DCSRDate=c.DCSRDate and b.ItemGroupKey=c.ItemGroupKey and a.BranchID=c.BranchID and a.CompID=c.CompID
		Group by a.DCSRType, a.DCSRNo, a.DCSRDate, a.OrderType, a.OrderNo, a.OrderDate, a.VendorCode, b.ItemGroupKey, b.SentItemCode, c.RecdItemCode, b.Norms, a.BranchID, a.CompID, a.Finyear



	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_PUR_DismantlingOrder_Advance]    Script Date: 17/06/2026 11:38:49 ******/
SET ANSI_NULLS OFF
