GO

CREATE FUNCTION [dbo].[fn_PUR_DismantlingOrder_Advance] ( @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE
	(OrderType	varchar(3),
	OrderNo	int,
	OrderDate	datetime,
	Stage		varchar(30),
	WorkPerc	int,
	AdvancePerc	money,
	EffStatus	bit,
	EffDate		datetime,
	CreatedDate	datetime,
	Userid		varchar(10),
	Branchid	varchar(3),
	Compid		varchar(3),
	Finyear		varchar(20),
	TranStamp	datetime
	)


 AS  

BEGIN 
	Insert @RetTable
		Select * from PUR_DismantlingOrder_Advance a
		Where a.CreatedDate = (Select Max(b.CreatedDate) from PUR_DismantlingOrder_Advance b where b.CreatedDate <= @AsOnDate 
			and b.OrderType=a.OrderType and b.OrderNo=a.OrderNo and b.OrderDate=a.OrderDate
			and b.WorkPerc=a.WorkPerc and b.AdvancePerc=a.AdvancePerc
			and b.BranchID=a.BranchID and b.CompID=a.CompID 
			)
		and ((a.EffStatus='1' and a.EffDate <= @RptDate) or (a.EffStatus='0' and a.EffDate > @RptDate))
			and a.BranchID=@BranchID and a.CompID=@CompID

	Return 

END
