GO

CREATE FUNCTION [dbo].[fn_PUR_DO_Terms] (@AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE
	(OrderType	varchar(3),
	OrderNo	int,
	OrderDate	datetime,
	VendorCode	int,
	PackingCode	int,
	PackingDesc	varchar(50),
	InsuranceCode	int,
	InsuranceDesc	varchar(50),
	DeliveryCode	int,
	DeliveryDesc	varchar(50),
	PaymentCode	int,
	PaymentDesc	varchar(50),
	Freightcode	int,
	FreightDesc	varchar(50),
	ModeCode	int,
	ModeDesc	varchar(50),
	FormCode	int,
	FormDesc	varchar(50),
	FormulaCode	int,
	FormulaName	varchar(50),
	PostingAcCode	int,
	PostingAcName	varchar(50),
	Branchid	varchar(3),
	Compid		varchar(3),
	Finyear		varchar(20)
	)


 AS  

BEGIN 
	Insert @RetTable

	Select a.OrderType, a.OrderNo, a.OrderDate, a.VendorCode,
		a.PackingCode,
			isNull((select b1.Description from TERMSMASTER b1 
			where b1.TypeFlg='Packing & Forwarding' and b1.Code=a.PackingCode and b1.Branchid=a.Branchid and b1.Compid=a.Compid), '') PackingDesc,
		a.InsuranceCode,
			isNull((select b2.Description from TERMSMASTER b2 
			where b2.TypeFlg='Insurance' and b2.Code=a.InsuranceCode and b2.Branchid=a.Branchid and b2.Compid=a.Compid), '') InsuranceDesc,
		a.DeliveryCode,
			isNull((select b3.Description from TERMSMASTER b3 
			where b3.TypeFlg='Delivery Instruction' and b3.Code=a.DeliveryCode and b3.Branchid=a.Branchid and b3.Compid=a.Compid), '') DeliveryDesc,
		a.PaymentCode,
			isNull((select b4.Description from TERMSMASTER b4 
			where b4.TypeFlg='Payment Terms' and b4.Code=a.PaymentCode and b4.Branchid=a.Branchid and b4.Compid=a.Compid), '') PaymentDesc,
		a.Freightcode,
			isNull((select b5.Description from TERMSMASTER b5 
			where b5.TypeFlg='Freight' and b5.Code=a.FreightCode and b5.Branchid=a.Branchid and b5.Compid=a.Compid), '') FreightDesc,
		a.ModeCode,
			isNull((select b6.Description from TERMSMASTER b6 
			where b6.TypeFlg='Mode' and b6.Code=a.ModeCode and b6.Branchid=a.Branchid and b6.Compid=a.Compid), '') ModeDesc,
		a.FormCode,
			isNull((select b7.Description from TERMSMASTER b7 
			where b7.TypeFlg='Form' and b7.Code=a.FormCode and b7.Branchid=a.Branchid and b7.Compid=a.Compid), '') FormDesc, 
		a.FormulaCode,
			isNull((Select b8.FrmLName from Com_FormulaMast_Hdr b8
			where  b8.ModuleCode=9  and  b8.FrmID=a.FormulaCode and b8.BranchID=a.BranchID and b8.CompID=a.CompID), '') FormulaName,
		a.PostingAc as PostingAcCode,
			isNull((Select b9.LedgerName from FAS_LedgerMaster b9
			where b9.LedgerCode=a.PostingAc and b9.CompCode=a.CompID+a.BranchID), '') PostingAcName,
		a.BranchID, a.CompID, a.Finyear
	from PUR_DismantlingOrder_Hdr a
	Where a.CreatedDate = (Select Max(b.CreatedDate) from PUR_DismantlingOrder_Hdr b where b.CreatedDate <= @AsOnDate 
		and b.OrderType=a.OrderType and b.OrderNo=a.OrderNo and b.OrderDate=a.OrderDate
		and b.BranchID=a.BranchID and b.CompID=a.CompID
		)
	and ((a.EffStatus='1' and a.EffDate <= @RptDate) or (a.EffStatus='0' and a.EffDate > @RptDate))
		and a.BranchID=@BranchID and a.CompID=@CompID

	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_PUR_Get_DCSR_Valid_Vendor]    Script Date: 17/06/2026 11:38:49 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_PUR_Get_DCSR_Valid_Vendor] (@AsOnDate datetime, @RptDate datetime,  @BranchID varchar(3),  @CompID varchar(3),  @Finyear varchar(15))  

RETURNS @RetTable TABLE
	([PartyName] [varchar] (50),
	[VendorCode] [int])

 AS  

	BEGIN 
		Insert @RetTable

		Select Distinct  (Select c2.PartyName from FAS_Party_Master c2 where c2.PartyCode=c1.VendorCode and c2.BranchID=@BranchID and c2.CompID=@CompID) as VendorName, c1.VendorCode
	from
	(Select b2.VendorCode, b2.OrderType, b2.OrderNo, b2.OrderDate, b2.ItemGroupKey, b2.RecdItemCode,
		b2.OrderingType, isNull(b2.OrderQty, 0) as OrderQty, isNull(Sum(b1.DCSRQty), 0) as DCSRQty, isNull(Sum(b1.CompQty), 0) as CompQty
	from
		(Select a6.VendorCode, a6.OrderType, a6.OrderNo, a6.OrderDate, a6.OrderingType, a6.ItemGroupKey, a6.RecdItemCode, Sum(a6.ToBeRecdQty) as OrderQty
 		from dbo.fn_PUR_LaborOrder_Vw (@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) a6
		Where a6.ValidFrom <= @RptDate and a6.ValidTo >= @RptDate and a6.isActive='1' and a6.Status='A'
			and a6.BranchID=@BranchID and a6.CompID=@CompID
		Group By a6.VendorCode, a6.OrderType, a6.OrderNo, a6.OrderDate, a6.OrderingType, a6.ItemGroupKey, a6.RecdItemCode
		)b2

		Left Outer Join 

		(Select k.DCSRType, k.DCSRNo, k.DCSRDate, k.ItemGroupKey, m.RecdItemCode, a1.OrderType, a1.OrderNo, a1.OrderDate,
			Case    When exists (Select distinct * from PUR_DCSR_Tran b where b.DCSRType=k.DCSRType and b.DCSRNo=k.DCSRNo and b.DCSRDate=k.DCSRDate
						and Mode='SC' and b.BranchID=@BranchID and b.CompID=@CompID) 
				Then Round(Min(k.CompQty), n.PurchaseUOMDecimal, 1) 
				Else Round(Min(k.DCSRQty-k.CompQty), n.PurchaseUOMDecimal, 1) 
			End as DCSRQty, 
			Round(Min(k.CompQty), n.PurchaseUOMDecimal, 1) as CompQty
		from 
			(Select a.DCSRType, a.DCSRNo, a.DCSRDate, a.ItemGroupKey, a.SentItemCode, 
				isNull(Sum(Case When a.Mode='NW' then a.Qty Else 0 End), 0) / a.Norms as DCSRQty, 
				-1 * isnull(Sum(Case When a.Mode='CM' then a.Qty Else 0 End), 0) / a.Norms as CompQty
			from PUR_DCSR_Tran a 
			Where Mode in ('NW', 'CM')
			Group by a.DCSRType, a.DCSRNo, a.DCSRDate, a.ItemGroupKey, a.SentItemCode, a.Norms
			) k 
		
			Left Outer Join dbo.fn_PUR_DCSR_Schedule (@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) m
			On k.DCSRType=m.DCSRType and k.DCSRNo=m.DCSRNo and k.DCSRDate=m.DCSRDate
				Left Outer Join Material_Master n
				On m.RecdItemCode=n.ItemCode and m.BranchID=n.BranchID and m.CompID=n.CompID
					Left Outer Join PUR_DCSR_Hdr a1
					On k.DCSRType=a1.DCSRType and k.DCSRNo=a1.DCSRNo and k.DCSRDate=a1.DCSRDate
						and a1.BranchID=m.BranchID and a1.CompID=m.CompID
		Where m.BranchID=@BranchID and m.CompID=@CompID
		Group by k.DCSRType, k.DCSRNo, k.DCSRDate, k.ItemGroupKey, m.RecdItemCode, n.PurchaseUOMDecimal, a1.OrderType, a1.OrderNo, a1.OrderDate
		) b1
		On b1.OrderType=b2.OrderType and b1.OrderNo=b2.OrderNo and b1.OrderDate=b2.OrderDate and b1.ItemGroupKey=b2.ItemGroupKey and b1.RecdItemCode=b2.RecdItemCode
		Group by b2.VendorCode, b2.OrderType, b2.OrderNo, b2.OrderDate, b2.OrderingType, b2.ItemGroupKey, b2.RecdItemCode, b2.OrderQty
	) c1
Where (c1.OrderingType='Open') or (c1.OrderingType='Specific' and ((c1.DCSRQty=0) or (c1.OrderQty-c1.DCSRQty) > 0))			

		Return 

	END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_PUR_Get_SubcontractRating_Item_Rate]    Script Date: 17/06/2026 11:38:49 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

  
CREATE Function [dbo].[fn_PUR_Get_SubcontractRating_Item_Rate](@AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))    
  
RETURNS @tmpTable TABLE  
 (VendorCode int,  
 ItemGroupKey int,  
 RecdItemCode [varchar](30),  
 ItemRate money,  
 RateSeq int,  
 RatingPercentage money)  
  
AS    
  
BEGIN   
 Insert into @tmpTable  
  
 Select  VendorCode,ItemGroupKey, RecdItemCode,  Min(Rate), 0, 0  
 From  
 (  
  Select b.ItemGroupKey, b.RecdItemCode, a.VendorCode, b.Rate, Max(a.orderdate) as OrderDate  
  From dbo.fn_PUR_LaborOrder_Hdr (@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear)  a   
  Left Outer Join dbo.fn_PUR_LaborOrder_Dtl (@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) b  
  On b.OrderNo=a.OrderNo and b.OrderDate=a.OrderDate and b.OrderType=a.OrderType and b.BranchID=a.BranchID and b.CompID=a.CompID  
  Where a.Finyear = @Finyear  
  Group By b.ItemGroupKey, b.RecdItemCode, a.VendorCode, b.Rate  
 ) m  
 Group By ItemGroupKey, RecdItemCode, VendorCode  
 Order By 1, 2 ,3  
   
 Update @tmpTable Set RateSeq=(Select Count(distinct ItemRate)   
         From @tmpTable b   
         Where b.RecdItemCode=a.RecdItemCode and b.ItemRate<=a.ItemRate)  
  From @tmpTable a  
   
 Update @tmpTable Set RatingPercentage=isNull((Select b.Percentage   
             From dbo.fn_PUR_VendorRating_Price('A',@AsonDate,@RptDate,@BranchID,@CompID) b   
             Where a.RateSeq between b.FromRank and b.ToRank  
              and Exists  
               (  
                Select * From fn_PUR_VendorRating_Master('A',@AsonDate,@RptDate,@BranchID,@CompID)s  
                Where s.RatingCode=b.RatingCode and s.IsSubcontract='1'  
               )  
             ), 0)  
 From @tmpTable a  
  
 Return   
  
END  
  
GO

