   From dbo.fn_PUR_PurchaseOrder_Hdr (@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear)  a         
   Left Outer Join dbo.fn_PUR_PurchaseOrder_Dtl (@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) b        
    On  b.OrderNo=a.OrderNo and b.OrderDate=a.OrderDate and b.OrderType=a.OrderType and b.BranchID=a.BranchID and b.CompID=a.CompID        
   Where a.Finyear = @Finyear        
