/****** Object:  UserDefinedFunction [dbo].[fn_PUR_LaborOrder_Dtl]    Script Date: 17/06/2026 11:38:49 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_PUR_LaborOrder_Dtl] ( @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE
	(OrderType	varchar(3),
	OrderNo	int,
	OrderDate	datetime,
	Seq		int,
	ItemGroupKey	int,
	SentItemCode	varchar(20),
	RecdItemCode	varchar(20),
	ToBeRecdQty	float,
	RatePer		float,
	Rate		money,
	AssRate	money,
	RateEffDate	datetime,
	QuotationType	varchar(3),
	QuotationNo	int,
	QuotationDate	datetime,
	isActive		bit,
	Status		char(1),
	StatusDate	datetime,
	EffStatus	bit,
	EffDate		datetime,
	CreatedDate	datetime,
	Userid		varchar(10),
	Branchid	varchar(3),
	Compid		varchar(3),
	Finyear		varchar(20),
	TranStamp	datetime
	)


 AS  

BEGIN 
	Insert @RetTable
		Select OrderType,OrderNo,OrderDate,Seq,ItemGroupKey,SentItemCode,RecdItemCode,ToBeRecdQty,RatePer,

		(select  top 1  Rate  from PUR_LaborOrder_Dtl x where 
			x.RateEffDate = (Select Max(y.RateEffDate) from PUR_LaborOrder_Dtl y where y.RateEffDate <= @AsOnDate 
			and y.OrderType=x.OrderType and y.OrderNo=x.OrderNo and y.OrderDate=x.OrderDate
			and y.SentItemCode=x.SentItemCode and y.RecdItemCode=x.RecdItemCode
			and y.BranchID=x.BranchID and y.CompID=x.CompID
			)and x.OrderType=a.OrderType and x.OrderNo=a.OrderNo and x.OrderDate=a.OrderDate
			and x.SentItemCode=a.SentItemCode and x.RecdItemCode=a.RecdItemCode
			and x.BranchID=a.BranchID and x.CompID=a.CompID order by CreatedDate desc)Rate,
		(select top 1  AssRate  from PUR_LaborOrder_Dtl x where 
			x.RateEffDate = (Select Max(y.RateEffDate) from PUR_LaborOrder_Dtl y where y.RateEffDate <= @AsOnDate 
			and y.OrderType=x.OrderType and y.OrderNo=x.OrderNo and y.OrderDate=x.OrderDate
			and y.SentItemCode=x.SentItemCode and y.RecdItemCode=x.RecdItemCode
			and y.BranchID=x.BranchID and y.CompID=x.CompID
			)and x.OrderType=a.OrderType and x.OrderNo=a.OrderNo and x.OrderDate=a.OrderDate
			and x.SentItemCode=a.SentItemCode and x.RecdItemCode=a.RecdItemCode
			and x.BranchID=a.BranchID and x.CompID=a.CompID  order by CreatedDate desc)AssRate,RateEffDate,QuotationType,
			QuotationNo,QuotationDate,isActive,Status,StatusDate,EffStatus,EffDate,CreatedDate,UserID,BranchID,CompID,Finyear,TranStamp
		 from PUR_LaborOrder_Dtl a
