/****** Object:  UserDefinedFunction [dbo].[fn_PUR_MultiPurchaseOrder_Validate]    Script Date: 17/06/2026 11:38:50 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_PUR_MultiPurchaseOrder_Validate] (@Modulecode int, @LeftOrdType varchar(3), @LeftOrdNo int, @LeftOrdDate Datetime, @RightOrdType varchar(3), @RightOrdNo int, @RightOrdDate Datetime,  @BranchID varchar(3), @CompID Varchar(3))  

RETURNS @RetTable TABLE 

	([LeftFrmID] int,	
	[LeftDocType] [varchar] (3),
	[LeftDocNo] int,
	[LeftDocDate] datetime,
	[LeftParamID] [varchar] (20),	
	[LeftValueUsed] Float,
	[LeftisTypePercentage] bit,
	[RightFrmID] int,	
	[RightDocType] [varchar] (3),
	[RightDocNo] int,
	[RightDocDate] datetime,
	[RightParamID] [varchar] (20),
	[RightValueUsed] Float,
	[RightisTypePercentage] bit,
	[BranchID] [varchar] (3),
	[CompID] [varchar] (3)
	) 

As

BEGIN 

	Insert into @RetTable 
		Select LeftFrmID,  LeftDocType, LeftDocNo, LeftDocDate, LeftBlock, LeftisTypePercentage, LeftValueUsed, 
	                        RightFrmID, RightDocType, RightDocNo, RightDocDate, RightBlock, RightisTypePercentage, RightValueUsed, @BranchID, @CompID
		from
			(Select a.FrmID as LeftFrmID, a.DocType as LeftDocType, a.DocNo as LeftDocNo, a.DocDate as LeftDocDate,  a.Block as LeftBlock, a.isTypePercentage as LeftisTypePercentage, a.ValueUsed as LeftValueUsed, 
			b.FrmID as RightFrmID, b.DocType as RightDocType, b.DocNo as RightDocNo, b.DocDate as RightDocDate,  b.Block as RightBlock, b.isTypePercentage as RightisTypePercentage, b.ValueUsed as RightValueUsed
			From 
				(Select * From Com_FormulaCalc_Dtl 
				Where DocType = @LeftOrdType and DocNo = @LeftOrdNo and DocDate = @LeftOrdDate 
				and BlockType='Param' and isValueEditable = 0  and isTypeEditable = 0 and Modulecode=@Modulecode 
				and BranchID =@BranchID and CompID = @CompID
				)  a		
			Full Outer Join 
				(Select * From Com_FormulaCalc_Dtl 
				Where DocType = @RightOrdType and DocNo = @RightOrdNo and DocDate = @RightOrdDate 
				and BlockType='Param' and isValueEditable = 0  and isTypeEditable = 0 and Modulecode=@Modulecode 
				and BranchID = @BranchID and CompID = @CompID
				)b
			On a.FrmID = b.FrmID and a.Block = b.Block  and a.KeyCol = b.KeyCol
			Where a.ValueUsed=b.ValueUsed and a.isTypePercentage = b.isTypePercentage					 
			) e
		Where LeftDocType is Null or RightDocType is Null


	Return

END

GO

