CREATE FUNCTION [dbo].[fn_PUR_PurchaseOrder_Dtl] ( @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE
	(OrderType	varchar(3),
	OrderNo	int,
	OrderDate	datetime,
	Seq		int,
	ItemCode	varchar(20),
	Qty		float,
	RatePer		float,
	Rate		money,
	AssRate	money,
	RateEffDate	datetime,
	Remarks	varchar(250),
	QuotationType	varchar(3),
	QuotationNo	int,
	QuotationDate	datetime,
	isActive		bit,
	Status		char(1),
	StatusDate	datetime,
	EffStatus	bit,
	EffDate		datetime,
	CreatedDate	datetime,
	Userid		varchar(10),
	Branchid	varchar(3),
	Compid		varchar(3),
	Finyear		varchar(20),
	TranStamp	datetime
	)


 AS  

BEGIN 
	Insert @RetTable
		Select * from PUR_PurchaseOrder_Dtl a
		Where a.CreatedDate = (Select Max(b.CreatedDate) from PUR_PurchaseOrder_Dtl b where b.CreatedDate <= @AsOnDate 
			and b.OrderType=a.OrderType and b.OrderNo=a.OrderNo and b.OrderDate=a.OrderDate
			and b.ItemCode=a.ItemCode
			and b.BranchID=a.BranchID and b.CompID=a.CompID ----and b.Finyear=a.Finyear
			)
		and ((a.EffStatus='1' and a.EffDate <= @RptDate) or (a.EffStatus='0' and a.EffDate > @RptDate))
