			and b.OrderType=a.OrderType and b.OrderNo=a.OrderNo and b.OrderDate=a.OrderDate
			and b.BranchID=a.BranchID and b.CompID=a.CompID
			)
		and ((a.EffStatus='1' and a.EffDate <= @RptDate) or (a.EffStatus='0' and a.EffDate > @RptDate))
			and a.BranchID=@BranchID and a.CompID=@CompID

	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_Pur_RFC_Advance]    Script Date: 17/06/2026 11:38:51 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_Pur_RFC_Advance] (@VendorCode int, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @FinYear varchar(15))  

RETURNS @ItemOrder Table
	(
		OrderType 	varchar(3),
		OrderNo 	int,
		OrderDate 	datetime,
		MaxAdvance 	float,
		PreAdvance 	float,
		SortOrder	int
	)
As

BEGIN  
--For Labor, Rework Order,Dismantling Order

	insert into @ItemOrder

	select z.OrderType, z.OrderNo, z.OrderDate,isnull(z. MaxAdvance,0) as  MaxAdvance,
	isnull(c.PreAdvance,0) as PreAdvance,  2 as  SortOrder
	from
	(
			select x.OrderType, x.OrderNo, x.OrderDate,x.AdvPerc,sum(x.ItemAdvValue) as MaxAdvance			
			from			
			(		
					select a.OrderType, a.OrderNo, a.OrderDate, a.ItemCode, a.Qty, 
					a.WorkPerc,((a.AdvPerc/100)*a.Qty* dbo.fn_Pur_Item_Rate(a.ItemCode,@VendorCode,a.OrderType, a.OrderNo, a.OrderDate, @AsOnDate , @RptDate , @BranchID , @CompID , @Finyear)) as ItemAdvValue,
					a.AdvPerc
					from
					(
						Select OrderType, OrderNo, OrderDate, ItemCode, Qty, WorkPerc,
							isNull((Select Sum(m.AdvancePerc) from dbo.fn_PUR_Order_Advance(@AsOnDate , @RptDate , @BranchID , @CompID , @Finyear) m
								where m.OrderType=y.OrderType and m.OrderNo=y.OrderNo and m.OrderDate=y.OrderDate
									and m.WorkPerc<=y.WorkPerc and m.BranchID=@BranchID and m.CompID=@CompID), 0) as AdvPerc
						from
							(Select OrderType, OrderNo, OrderDate, ItemCode,
							Sum(Case WorkPerc when 110 then ChallanQty when 120 then ReceiptQty when 130 then AcceptedQty else 0 end) as Qty, WorkPerc
							from
								(Select a.OrderType, a.OrderNo, a.OrderDate,  
								c.ItemCode, c.ChallanQty, c.ReceiptQty, c.AcceptedQty,
								Case when c.ItemCode is Null then -20 when ReceiptDate is Null then 110 when AcceptedDate is Null then 120 else 130 end as WorkPerc
								from 
										(
										Select * from dbo.fn_PUR_LaborOrder_Hdr(@AsOnDate , @RptDate , @BranchID , @CompID , @Finyear)
											where VendorCode=@VendorCode 
										Union All
										Select * from dbo.fn_PUR_ReworkOrder_Hdr(@AsOnDate , @RptDate , @BranchID , @CompID , @Finyear)
											where VendorCode=@VendorCode 
										Union All
										Select * from dbo.fn_PUR_DismantlingOrder_Hdr(@AsOnDate , @RptDate , @BranchID , @CompID , @Finyear)
											where VendorCode=@VendorCode 
						
										) a 

								Left Outer Join PUR_DCSR_Hdr b
									On a.OrderType=b.OrderType and a.OrderNo=b.OrderNo and a.OrderDate=b.OrderDate
										and a.BranchID=b.BranchID and a.CompID=b.CompID
								Left Outer Join REC_ReceiptEntry_Dtl c
									On b.DCSRType=c.RefType and b.DCSRNo=c.RefNo and b.DCSRDate=c.RefDate
										and a.BranchID=b.BranchID and a.CompID=b.CompID
								Where a.VendorCode=@VendorCode and a.BranchID=@BranchID and a.CompID=@CompID
								) x
							Group by OrderType, OrderNo, OrderDate, ItemCode, WorkPerc
							) y
						
						Union All
						
						--For Purchase Order
						
						Select OrderType, OrderNo, OrderDate, ItemCode, Qty, WorkPerc,
							isNull((Select Sum(m.AdvancePerc) from dbo.fn_PUR_Order_Advance(@AsOnDate , @RptDate , @BranchID,  @CompID,  @Finyear) m
									where m.OrderType=y.OrderType and m.OrderNo=y.OrderNo and m.OrderDate=y.OrderDate
										and m.WorkPerc<=y.WorkPerc and m.BranchID=@BranchID and m.CompID=@CompID), 0) as AdvPerc
						from
							(Select OrderType, OrderNo, OrderDate, ItemCode,
							Sum(Case WorkPerc when 110 then ChallanQty when 120 then ReceiptQty when 130 then AcceptedQty else 0 end) as Qty, WorkPerc
							from
								(Select a.OrderType, a.OrderNo, a.OrderDate,  c.ItemCode, c.ChallanQty, c.ReceiptQty, c.AcceptedQty,
									Case when c.ItemCode is Null then -20 when ReceiptDate is Null then 110 when AcceptedDate is Null then 120 else 130 end as WorkPerc
								from dbo.fn_PUR_PurchaseOrder_Hdr(@AsOnDate , @RptDate , @BranchID , @CompID , @Finyear) a 
								Left Outer Join dbo.fn_PUR_Schedule(@AsOnDate , @RptDate , @BranchID , @CompID , @Finyear) b
								On a.OrderType=b.OrderType and a.OrderNo=b.OrderNo and a.OrderDate=b.OrderDate and a.BranchID=b.BranchID and a.CompID=b.CompID
								Left Outer Join REC_ReceiptEntry_Dtl c
								On b.ScheduleType=c.RefType and b.ScheduleNo=c.RefNo and b.ScheduleDate=c.RefDate and a.BranchID=b.BranchID and a.CompID=b.CompID
								Where a.VendorCode=@VendorCode and a.BranchID=@BranchID and a.CompID=@CompID
								) x
							Group by OrderType, OrderNo, OrderDate, ItemCode, WorkPerc
							) y
					
					)a
			
			)x 

			Group by x.OrderType,x.OrderNo,x.OrderDate,x.AdvPerc
	)z
	
	left outer join 
	
	(
		select RefNo, RefType, RefDate, BranchID, CompID, FinYear, Sum(AdvAmount) as PreAdvance 
		from PUR_RequestForCheque_Dtl
		where RefType <> 'AdH' and RefNo > 0 and BillDate is Null and AdvAmount > 0
	  group by RefNo,RefType,RefDate,BranchID, CompID, FinYear
	) c 
	
	on c.RefNo=z.OrderNo and c.RefType= z.OrderType 
			and c.RefDate=z.OrderDate and c.BranchID=@BranchID 
			and c.CompID=@CompID

--	where  isnull(z. MaxAdvance,0) - isnull(c. PreAdvance,0)  <>0 
	where  isnull(z. MaxAdvance,0)<>0 and isnull(z. MaxAdvance,0) - isnull(c. PreAdvance,0)  <>0 


	Union All

	select f.RefType, f.RefNo, f.RefDate, 0 as MaxAdvance,sum(f.AdvAmount) as PreAdvance , 1 as  SortOrder
	from PUR_RequestForCheque_Dtl f inner join PUR_RequestForCheque_hdr g
	
	 on  g.RFCType=f.RFCType and f.RFCNo=g.RFCNo and f.RFCDate=g.RFCDate and f.BranchID=g.BranchID 
			and f.CompID=g.CompID

	where  g.PartyCode=@VendorCode and  f.RefType='AdH'  and f.RefNo=0 and f.BillDate is Null and f.AdvAmount>0 and f.BranchID=@BranchId and f.CompID=@CompID
					
	group by f.RefNo, f.RefType, f.RefDate 


	Return
END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_Pur_RFC_Bill]    Script Date: 17/06/2026 11:38:51 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO



CREATE FUNCTION [dbo].[fn_Pur_RFC_Bill] (@VendorCode int, @CmCode char(12), @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @OrderBill Table
	(
		OrderType	varchar(3),
		OrderNo	int,
		OrderDate	datetime,
		BillType 	varchar(3),
		BillNo 		int,
		BillDate 		datetime,
		Amount	 	float,
		BillAmount	float,
		OverDue	datetime
		 
	)
As

BEGIN  

	Declare @MastCmCode char(4)
	Select @MastCmCode=Left(@CmCode, 4)


	insert into @OrderBill

	select z.BatchType, z.BatchNo, z.BatchDate, z.RefType, z.RefNo,z.RefDate, (z.Amount+isNull(z1.Amount, 0)) as Amount, (z.BillAmount) as BillAmount, z.OverDue
	
	from
	(
		
		Select x.RefType,  x.RefNo, x.RefDate, y.InvoiceNo, y.Amount,y.BillAmount, y.Overdue, x.BatchType, x.BatchNo, x.BatchDate 
		from FAS_VoucherTranRef x
		
		Right Outer join
		(
		Select DocNo,VrRoute, RefNo as [InvoiceNo], Convert(varchar(10), RefDate, 105) as [InvoiceDate], Amount, BillAmount, Convert(datetime,  DueDate, 105) as [Due Date], DateDiff(day, [DueDate],  @RptDate ) as Overdue
			from 
				(Select DocNo,VrRoute,RefNo, RefDate, Dateadd(day, isNull(CreditDays, 0), RefDate) as DueDate,  Amount, BillAmount
					from 
						(Select y.DocNo,y.VrRoute,isNull(y.RefNo, z.RefNo) as RefNo, 
							isNull(y.RefDate, (Select Min(x.RefDate) from FAS_BillDetails x where x.RefNo=z.RefNo and x.RefDate <=  @RptDate and x.LrCode=@VendorCode and x.CompCode= @MastCmCode )) as RefDate, 
							isNull(y.CreditDays, 0) CreditDays, z.Amount ,y.BillAmount
						from 
							(Select DocNo, VrRoute, RefNo, RefDate,  Amount as BillAmount, CreditDays 
							from FAS_BillDetails 
							where LrCode=@VendorCode and Type in ('New Ref', 'Advance') and CompCode=@MastCmCode
							) y 
						Right Outer Join
							(Select RefNo, Sum(Amount) as Amount 
							from FAS_BillDetails
							where Type <> 'On Acct' and RefDate <= @RptDate and LrCode=@VendorCode and CompCode=@MastCmCode
							group by RefNo having sum(Amount) <> 0 
							) z 
						On y.RefNo=z.RefNo 
						) d
		
				) b
		
		) y on y.DocNo=x.DocNo and y.VrRoute=x.VrRoute
		
	) z

	Left Outer Join 
		(Select m1.RefType, m1.RefNo, m1.RefDate, m1.BillType, m1.BillNo, m1.BillDate, Sum(advamount)  as Amount
		from dbo.fn_PUR_RequestForCheque_Dtl (@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) m1
		Inner Join dbo.fn_PUR_RequestForCheque_Hdr (@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) m2
		On m1.RFCType=m2.RFCType and m1.RFCNo=m2.RFCNo and m1.RFCDate=m2.RFCDate and m1.BranchID=m2.BranchID and m1.CompID=m2.CompID
		where m2.ChequeDate is Null
		Group by m1.RefType, m1.RefNo, m1.RefDate, m1.BillType, m1.BillNo, m1.BillDate) z1
	On z.BatchType=z1.RefType and z.BatchNo=z1.RefNo and z.BatchDate=z1.RefDate and z.RefType=z1.BillType and z.RefNo=z1.BillNo and z.RefDate=z1.BillDate


--	where z.BatchType=@OrderType and z.BatchNo=@OrderNo and z.BatchDate=@OrderDate
	
	Order by z.RefDate, z.RefNo 



	Return

End










GO

