CREATE FUNCTION [dbo].[fn_Pur_RFC_Bill_Advance] (@VendorCode int, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @FinYear varchar(15))  

RETURNS @ItemOrder Table
	(
		OrderType 	varchar(3),
		OrderNo 	int,
		OrderDate 	datetime,
		MaxAdvance 	float,
		PreAdvance 	float,
		SortOrder	int
	)
As

BEGIN  
--For Labor, Rework Order,Dismantling Order

	insert into @ItemOrder

	select z.OrderType, z.OrderNo, z.OrderDate,isnull(z. MaxAdvance,0) as  MaxAdvance
	,isnull(c.PreAdvance,0) as PreAdvance,  2 as  SortOrder
	from
	(
			select x.OrderType, x.OrderNo, x.OrderDate,x.AdvPerc,sum(x.ItemAdvValue) as MaxAdvance
			
			from
			
			(
			
					select a.OrderType, a.OrderNo, a.OrderDate, a.ItemCode, a.Qty, 
					a.WorkPerc,((a.AdvPerc/100)*a.Qty*(dbo.fn_Pur_Item_Rate(a.ItemCode,@VendorCode, a.OrderType, a.OrderNo, a.OrderDate, @AsOnDate , @RptDate , @BranchID , @CompID , @Finyear))) as ItemAdvValue,
					a.AdvPerc
					from
					(
						Select OrderType, OrderNo, OrderDate, ItemCode, Qty, WorkPerc,
							isNull((Select Sum(m.AdvancePerc) 
							from dbo.fn_PUR_Order_Advance(@AsOnDate , @RptDate , @BranchID , @CompID , @Finyear) m
							where m.OrderType=y.OrderType and m.OrderNo=y.OrderNo and m.OrderDate=y.OrderDate
							and m.WorkPerc<=y.WorkPerc and m.BranchID=@BranchID and m.CompID=@CompID), 0) as AdvPerc
						from
							(Select OrderType, OrderNo, OrderDate, ItemCode,
							Sum(Case WorkPerc when 110 then ChallanQty when 120 then ReceiptQty when 130 then AcceptedQty else 0 end) as Qty, WorkPerc
							from
								(Select a.OrderType, a.OrderNo, a.OrderDate,  
								c.ItemCode, c.ChallanQty, c.ReceiptQty, c.AcceptedQty,
								Case when c.ItemCode is Null then -20 when ReceiptDate is Null then 110 when AcceptedDate is Null then 120 else 130 end as WorkPerc
								from 
										(
										Select * from dbo.fn_PUR_LaborOrder_Hdr(@AsOnDate , @RptDate , @BranchID , @CompID , @Finyear)
											where VendorCode=@VendorCode 
										Union All
										Select * from dbo.fn_PUR_ReworkOrder_Hdr(@AsOnDate , @RptDate , @BranchID , @CompID , @Finyear)
											where VendorCode=@VendorCode 
										Union All
										Select * from dbo.fn_PUR_DismantlingOrder_Hdr(@AsOnDate , @RptDate , @BranchID , @CompID , @Finyear)
											where VendorCode=@VendorCode 
						
										) a 
								Left Outer Join PUR_DCSR_Hdr b
								On a.OrderType=b.OrderType and a.OrderNo=b.OrderNo and a.OrderDate=b.OrderDate
								and a.BranchID=b.BranchID and a.CompID=b.CompID
								Left Outer Join REC_ReceiptEntry_Dtl c
								On b.DCSRType=c.RefType and b.DCSRNo=c.RefNo and b.DCSRDate=c.RefDate
								and a.BranchID=b.BranchID and a.CompID=b.CompID
								Where a.VendorCode=@VendorCode and a.BranchID=@BranchID and a.CompID=@CompID 
								) x
							Group by OrderType, OrderNo, OrderDate, ItemCode, WorkPerc
							) y
						
						Union All
						
						--For Purchase Order
						
						Select OrderType, OrderNo, OrderDate, ItemCode, Qty, WorkPerc,
							isNull((Select Sum(m.AdvancePerc) 
							from dbo.fn_PUR_Order_Advance(@AsOnDate , @RptDate , @BranchID,  @CompID,  @Finyear) m
							where m.OrderType=y.OrderType and m.OrderNo=y.OrderNo and m.OrderDate=y.OrderDate
							and m.WorkPerc<=y.WorkPerc and m.BranchID=@BranchID and m.CompID=@CompID), 0) as AdvPerc
						from
							(Select OrderType, OrderNo, OrderDate, ItemCode,
							Sum(Case WorkPerc when 110 then ChallanQty when 120 then ReceiptQty when 130 then AcceptedQty else 0 end) as Qty, WorkPerc
							from
								(Select a.OrderType, a.OrderNo, a.OrderDate,  c.ItemCode, c.ChallanQty, c.ReceiptQty, c.AcceptedQty,
									Case when c.ItemCode is Null then -20 when ReceiptDate is Null then 110 when AcceptedDate is Null then 120 else 130 end as WorkPerc
								from dbo.fn_PUR_PurchaseOrder_Hdr(@AsOnDate , @RptDate , @BranchID , @CompID , @Finyear) a 
								Left Outer Join dbo.fn_PUR_Schedule(@AsOnDate , @RptDate , @BranchID , @CompID , @Finyear) b
								On a.OrderType=b.OrderType and a.OrderNo=b.OrderNo and a.OrderDate=b.OrderDate and a.BranchID=b.BranchID and a.CompID=b.CompID
								Left Outer Join REC_ReceiptEntry_Dtl c
								On b.ScheduleType=c.RefType and b.ScheduleNo=c.RefNo and b.ScheduleDate=c.RefDate and a.BranchID=b.BranchID and a.CompID=b.CompID
								Where a.VendorCode=@VendorCode and a.BranchID=@BranchID and a.CompID=@CompID 
								) x
							Group by OrderType, OrderNo, OrderDate, ItemCode, WorkPerc
							) y
					
					)a
			
			)x 

			Group by x.OrderType,x.OrderNo,x.OrderDate,x.AdvPerc
	)z
	
	left outer join 
	
	(
		select RefNo, RefType, RefDate, BranchID, CompID, FinYear, Sum(AdvAmount) as PreAdvance 
		from PUR_RequestForCheque_Dtl
		where RefType <> 'AdH' and RefNo > 0 and BillDate is Null
	  group by RefNo,RefType,RefDate,BranchID, CompID, FinYear
	) c 
	
	on c.RefNo=z.OrderNo and c.RefType= z.OrderType 
			and c.RefDate=z.OrderDate and c.BranchID=@BranchID 
			and c.CompID=@CompID 

	
	where  isnull(z. MaxAdvance,0) - isnull(c. PreAdvance,0)  <>0 


	Union All

	select f.RefType, f.RefNo, f.RefDate, 0 as MaxAdvance,sum(f.AdvAmount) as PreAdvance , 1 as  SortOrder
	from PUR_RequestForCheque_Dtl f inner join PUR_RequestForCheque_hdr g
	
	 on  g.RFCType=f.RFCType and f.RFCNo=g.RFCNo and f.RFCDate=g.RFCDate and f.BranchID=g.BranchID 
			and f.CompID=g.CompID


	where  g.PartyCode=@VendorCode and  f.RefType='AdH'  and f.RefNo=0 and f.BillDate is Null and  f.BranchID=@BranchId and f.CompID=@CompID
					
	group by f.RefNo, f.RefType, f.RefDate 


	Return
END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_Pur_Rpt_VendorAnalysis]    Script Date: 17/06/2026 11:38:51 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_Pur_Rpt_VendorAnalysis] (@ASOnDate datetime, @RptDate datetime, @From datetime, @To datetime, @BranchID varchar(2), @CompID varchar(2), @Finyear Varchar(20))  

RETURNS @RetTable TABLE
	([VendorCode] [varchar](10),
	[VendorName] [varchar](50),
	[ScheduleQty] Float,
	[ReceiptQty] Float,
	[AcceptedQty] Float,
	[Quality] Float,
	[Delivery] Float,
	[Delaydates] Float,
	[Price] Float
	)

 AS  

BEGIN 
	
	Insert into @RetTable
		Select VendorCode, '', ScheduleQty,  0, 0, 0, 0, 0, 0
		From (Select VendorCode, Sum(ScheduleQty) as ScheduleQty
			From dbo.fn_PUR_Schedule(@ASOnDate, @RptDate, @BranchID, @CompID, @Finyear)
			Where Status not in ('C','S') and OrderDate between @From and @To
			Group by VendorCode 
		          )x


	Update @RetTable Set ReceiptQty = z.ReceiptQty, AcceptedQty = z.AcceptedQty, Quality=z.Quality, Delivery=z.Delivery, Delaydates = z.DelayDates, Price = z.Price 
		From (Select m.VendorCode, y.ReceiptQty, y.AcceptedQty, 
				Case When y.ReceiptQty = 0 then 0 When m.ScheduleQty < y.AcceptedQty Then y.Quality Else ((y.AcceptedQty / y.ReceiptQty) * y.Quality) end Quality, 
				Case when y.DelayDates = 0 then y.Delivery else ((250.0-y.AvgDelayDates)/10.0) end Delivery, 
				y.Delaydates, y.Price 
			From  @RetTable m
			Left Outer Join
				(Select x.VendorCode, Sum(ReceiptQty) as ReceiptQty, Sum(AcceptedQty) as AcceptedQty, Sum(DelayDates) as DelayDates, Avg(DelayDates) as AvgDelayDates, x.Quality, x.Delivery, x.Price 
				 From 
					(	Select a.VendorCode, IsNull(ReceiptQty, 0) ReceiptQty, IsNull(AcceptedQty, 0) AcceptedQty,
								 Case when DateDiff(d, a.RequiredDate, b.ReceiptEntryDate) > 10 then DateDiff(d, a.RequiredDate, b.ReceiptEntryDate) else 0 end DelayDates,
								 e.Quality, e.Delivery, e.Price 
							from dbo.fn_PUR_Schedule(@ASOnDate, @RptDate, @BranchID, @CompID, @Finyear) a 
						Left outer join 
							     (Select RefNo, RefType, RefDate, VendorCode, ItemCode, ScheduleDate, BranchID, CompID, Max(ReceiptEntryDate) ReceiptEntryDate, 
							      Sum(ReceiptQty) as ReceiptQty, Sum(AcceptedQty) AcceptedQty 
							     from ReceiptEntry Where InwardType = 'P' and BranchId = @BranchID and CompID = @CompID	
							     Group By RefNo, RefType, RefDate, VendorCode, ItemCode, ScheduleDate, BranchID, CompID 
							     ) b 
						On a.ScheduleType = b.RefType and a.ScheduleNo = b.RefNo and a.ScheduleDate = b.RefDate 
							and a.VendorCode = b.VendorCode and a.ItemCode = b.ItemCode and a.RequiredDate = b.ScheduleDate 
							and a.Branchid = b.Branchid and a.Compid = b.Compid 
						Left outer join (Select top 1 RatingType, Quality, Delivery, Price,  Branchid, Compid 
								from PUR_VendorRating_Master Where BranchId = @BranchID and CompID = @CompID) e 
						On e.branchid = a.Branchid and e.Compid = a.Compid 
						Where Status not in ('C','S') and OrderDate between @From and @To
					)x
				Group by x.VendorCode, x.Quality, x.Delivery, x.Price
			)y
			On m.VendorCode = y.VendorCode
		)z
			
				
		Update @RetTable Set VendorName = c.PartyName
		From @RetTable a
		Left Outer Join FAS_Party_Master c 
		On a.VendorCode = c.PartyCode and c.Branchid = @BranchID and c.Compid = @CompID 

	Return 

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_PUR_RWO_Terms]    Script Date: 17/06/2026 11:38:51 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_PUR_RWO_Terms] (@AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE
	(OrderType	varchar(3),
	OrderNo	int,
	OrderDate	datetime,
	VendorCode	int,
	PackingCode	int,
	PackingDesc	varchar(50),
	InsuranceCode	int,
	InsuranceDesc	varchar(50),
	DeliveryCode	int,
	DeliveryDesc	varchar(50),
	PaymentCode	int,
	PaymentDesc	varchar(50),
	Freightcode	int,
	FreightDesc	varchar(50),
	ModeCode	int,
	ModeDesc	varchar(50),
	FormCode	int,
	FormDesc	varchar(50),
	FormulaCode	int,
	FormulaName	varchar(50),
	PostingAcCode	int,
	PostingAcName	varchar(50),
	Branchid	varchar(3),
	Compid		varchar(3),
	Finyear		varchar(20)
	)


 AS  

BEGIN 
	Insert @RetTable

	Select a.OrderType, a.OrderNo, a.OrderDate, a.VendorCode,
		a.PackingCode,
			isNull((select b1.Description from TERMSMASTER b1 
			where b1.TypeFlg='Packing & Forwarding' and b1.Code=a.PackingCode and b1.Branchid=a.Branchid and b1.Compid=a.Compid), '') PackingDesc,
		a.InsuranceCode,
			isNull((select b2.Description from TERMSMASTER b2 
			where b2.TypeFlg='Insurance' and b2.Code=a.InsuranceCode and b2.Branchid=a.Branchid and b2.Compid=a.Compid), '') InsuranceDesc,
		a.DeliveryCode,
			isNull((select b3.Description from TERMSMASTER b3 
			where b3.TypeFlg='Delivery Instruction' and b3.Code=a.DeliveryCode and b3.Branchid=a.Branchid and b3.Compid=a.Compid), '') DeliveryDesc,
		a.PaymentCode,
			isNull((select b4.Description from TERMSMASTER b4 
			where b4.TypeFlg='Payment Terms' and b4.Code=a.PaymentCode and b4.Branchid=a.Branchid and b4.Compid=a.Compid), '') PaymentDesc,
		a.Freightcode,
			isNull((select b5.Description from TERMSMASTER b5 
			where b5.TypeFlg='Freight' and b5.Code=a.FreightCode and b5.Branchid=a.Branchid and b5.Compid=a.Compid), '') FreightDesc,
		a.ModeCode,
			isNull((select b6.Description from TERMSMASTER b6 
			where b6.TypeFlg='Mode' and b6.Code=a.ModeCode and b6.Branchid=a.Branchid and b6.Compid=a.Compid), '') ModeDesc,
		a.FormCode,
			isNull((select b7.Description from TERMSMASTER b7 
			where b7.TypeFlg='Form' and b7.Code=a.FormCode and b7.Branchid=a.Branchid and b7.Compid=a.Compid), '') FormDesc, 
		a.FormulaCode,
			isNull((Select b8.FrmLName from Com_FormulaMast_Hdr b8
			where b8.ModuleCode=9 and b8.FrmID=a.FormulaCode and b8.BranchID=a.BranchID and b8.CompID=a.CompID), '') FormulaName,
		a.PostingAc as PostingAcCode,
			isNull((Select b9.LedgerName from FAS_LedgerMaster b9
			where b9.LedgerCode=a.PostingAc and b9.CompCode=a.CompID+a.BranchID), '') PostingAcName,
		a.BranchID, a.CompID, a.Finyear
	from PUR_ReworkOrder_Hdr a
	Where a.CreatedDate = (Select Max(b.CreatedDate) from PUR_ReworkOrder_Hdr b where b.CreatedDate <= @AsOnDate 
		and b.OrderType=a.OrderType and b.OrderNo=a.OrderNo and b.OrderDate=a.OrderDate
		and b.BranchID=a.BranchID and b.CompID=a.CompID
		)
	and ((a.EffStatus='1' and a.EffDate <= @RptDate) or (a.EffStatus='0' and a.EffDate > @RptDate))
		and a.BranchID=@BranchID and a.CompID=@CompID

	Return 

END
GO

