CREATE FUNCTION [dbo].[fn_PUR_Schedule] ( @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE
	(ScheduleType	varchar(3),
	ScheduleNo	int,
	ScheduleDate	datetime,
	VendorCode	int,
	ItemCode	varchar(20),
	RequiredDate	datetime,
	ScheduleQty	float,
	Location	varchar(30),
	OrderType	varchar(3),
	OrderNo	int,
	OrderDate	datetime,
	Status		char(1),
	StatusDate	datetime,
	EffStatus	bit,
	EffDate		datetime,
	CreatedDate	datetime,
	Userid		varchar(10),
	Branchid	varchar(3),
	Compid		varchar(3),
	Finyear		varchar(20),
	TranStamp	datetime
	)


 AS  

BEGIN 
	Insert @RetTable
		Select * from PUR_Schedule a
		Where a.CreatedDate = (Select Max(b.CreatedDate) from PUR_Schedule b where b.CreatedDate <= @AsOnDate 
			and b.ScheduleType=a.ScheduleType and b.ScheduleNo=a.ScheduleNo and b.ScheduleDate=a.ScheduleDate
			and b.ItemCode=a.ItemCode and b.RequiredDate=a.RequiredDate
			and b.BranchID=a.BranchID and b.CompID=a.CompID 
			)
		and ((a.EffStatus='1' and a.EffDate <= @RptDate) or (a.EffStatus='0' and a.EffDate > @RptDate))
			and a.BranchID=@BranchID and a.CompID=@CompID 
	Return 

END

GO

/****** Object:  UserDefinedFunction [dbo].[fn_PUR_VendorRating_Grp]    Script Date: 17/06/2026 11:38:51 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

 
CREATE FUNCTION [dbo].[fn_PUR_VendorRating_Grp] (@ForOperation varchar(1), @AsOnDate datetime, @BranchID varchar(3), @CompID varchar(3))    
  
RETURNS  @RetTbl TABLE  
 (   
  RatingCode  int,  
  RevNo  int,  
  RevDate  datetime,  
  EffStatus char(2),   
  EffDate  datetime,  
  Branchid varchar(3),   
  Compid  varchar(3),  
  TranStamp  datetime,  
  MinEffDate datetime  
 )  
  
 BEGIN   
   
 Insert into @RetTbl  
  Select m.RatingCode, h.RevNo, h.RevDate, h.EffStatus, h.EffDate,@BranchID, @CompID, m.TranStamp, m.MinEffDate  
   From  
   (  
    Select x.RatingCode, Min(x.MinEffDate) As MinEffDate, Max(x.TranStamp) As TranStamp  
    From  
    (  
  
     Select m.RatingCode, Min(m.EffDate) As MinEffDate, Max(m.TranStamp) As TranStamp  From PUR_VendorRating_Master m  
     Where m.TranStamp<=@AsOnDate and m.BranchID=@BranchID and m.CompID=@CompID  
     Group by m.RatingCode  
       
     UNION ALL  
     --Price Detail  
     Select p.RatingCode, Min(p.EffDate) As MinEffDate, Max(p.TranStamp) As TranStamp From PUR_VendorRating_Price p  
     Where p.TranStamp<=@AsOnDate and p.BranchID=@BranchID and p.CompID=@CompID  
     Group by p.RatingCode  
       
     UNION ALL  
     --PremiumFreight Detail  
     Select f.RatingCode, Min(f.EffDate) As MinEffDate, Max(f.TranStamp) As TranStamp From PUR_VendorRating_PremiumFreight f  
     Where f.TranStamp<=@AsOnDate and f.BranchID=@BranchID and f.CompID=@CompID  
     Group by f.RatingCode  
       
     UNION ALL  
     --FieldComplaint Detail  
     Select c.RatingCode, Min(c.EffDate) As MinEffDate, Max(c.TranStamp) As TranStamp From PUR_VendorRating_FieldComplaint c  
     Where c.TranStamp<=@AsOnDate and c.BranchID=@BranchID and c.CompID=@CompID  
     Group by c.RatingCode  
       
     UNION ALL  
     --DisQualification Detail  
     Select d.RatingCode, Min(d.EffDate) As MinEffDate, Max(d.TranStamp) As TranStamp From PUR_VendorRating_DisQualification d  
     Where d.TranStamp<=@AsOnDate and d.BranchID=@BranchID and d.CompID=@CompID  
     Group by d.RatingCode  
    )x  
    Group by x.RatingCode  
   )m  
   Left Outer Join PUR_VendorRating_Master h   
       On m.RatingCode=h.RatingCode and m.TranStamp=h.TranStamp and h.BranchID=@BranchID and h.CompID=@CompID  
  
  
 --Price Detail Data  
  Update @RetTbl Set RevNo=p.RevNo, RevDate=p.RevDate, EffDate=p.EffDate, EffStatus=p.EffStatus  
  From @RetTbl m   
  Inner Join PUR_VendorRating_Price p On m.RatingCode=p.RatingCode and m.TranStamp=p.TranStamp   
  Where p.BranchID=@BranchID and p.CompID=@CompID   
   and NOT EXISTS (Select * From @RetTbl h1   
         Where h1.RatingCode=p.RatingCode and h1.TranStamp=p.TranStamp   
        and h1.BranchID=p.BranchID and h1.CompID=p.CompID and h1.RevNo is NOT NULL  
        )  
  
 --PremiumFreight Detail Data  
  Update @RetTbl Set RevNo=f.RevNo, RevDate=f.RevDate, EffDate=f.EffDate, EffStatus=f.EffStatus  
  From @RetTbl m   
  Inner Join PUR_VendorRating_PremiumFreight f On m.RatingCode=f.RatingCode and m.TranStamp=f.TranStamp   
  Where f.BranchID=@BranchID and f.CompID=@CompID   
   and NOT EXISTS (Select * From @RetTbl h1   
         Where h1.RatingCode=f.RatingCode and h1.TranStamp=f.TranStamp   
        and h1.BranchID=f.BranchID and h1.CompID=f.CompID and h1.RevNo is NOT NULL  
       )  
  
 --FieldComplaint Detail Data  
  Update @RetTbl Set RevNo=c.RevNo, RevDate=c.RevDate, EffDate=c.EffDate, EffStatus=c.EffStatus  
  From @RetTbl m   
  Inner Join PUR_VendorRating_Price c On m.RatingCode=c.RatingCode and m.TranStamp=c.TranStamp   
  Where c.BranchID=@BranchID and c.CompID=@CompID   
   and NOT EXISTS (Select * From @RetTbl h1   
         Where h1.RatingCode=c.RatingCode and h1.TranStamp=c.TranStamp   
        and h1.BranchID=c.BranchID and h1.CompID=c.CompID and h1.RevNo is NOT NULL  
        )  
  
 --DisQualification Detail Data  
  Update @RetTbl Set RevNo=d.RevNo, RevDate=d.RevDate, EffDate=d.EffDate, EffStatus=d.EffStatus  
  From @RetTbl m   
  Inner Join PUR_VendorRating_PremiumFreight d On m.RatingCode=d.RatingCode and m.TranStamp=d.TranStamp   
  Where d.BranchID=@BranchID and d.CompID=@CompID   
   and NOT EXISTS (Select * From @RetTbl h1   
         Where h1.RatingCode=d.RatingCode and h1.TranStamp=d.TranStamp   
        and h1.BranchID=d.BranchID and h1.CompID=d.CompID and h1.RevNo is NOT NULL  
       )  
  
 /* Delete based on FormOperation */  
  Delete from @RetTbl      
  Where ( (@ForOperation='M' AND EffStatus Like '[AHX]%')  
    OR (@ForOperation='E' AND (EffStatus Like '[NME]%' OR (EffStatus LIKE 'A%' AND  EffStatus Like '_[DX]')))  
    OR (@ForOperation='A' AND EffStatus Like '[AX]%')  
             )  
 Return   
  
 END  
  
  
  
GO

/****** Object:  UserDefinedFunction [dbo].[fn_QC_Calibration_IssueItem]    Script Date: 17/06/2026 11:38:51 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_QC_Calibration_IssueItem] (@AsonDate Datetime, @BranchID varchar(3), @CompID varchar(3))  

RETURNS @Item TABLE
	(ItemCode		varchar(20),
	ItemDescription		varchar(50),
	ScheduleDate		datetime,
	BaseFrequency		varchar(10))

AS  

BEGIN 
	insert Into @Item
	Select Distinct a.ItemCode,c.ItemDescription,b.ScheduleDate,'Schedule' as Baeson from Qc_Calibration_Master a 
		left outer join QC_Calibration_Schedule b on a.ItemCode=b.ItemCode and a.Branchid=b.Branchid and a.Compid=b.Compid
		left outer join Material_Master c on c.ItemCode = left(a.ItemCode,len(a.ItemCode)-4) and c.Branchid = a.Branchid and c.Compid = a.Compid 
		--Left outer join QC_Calibration_Master d on d.ItemCode=b.ItemCode and d.Branchid = a.Branchid and d.Compid = a.Compid
		where a.Status=1 and b.ScheduleDate <= convert(datetime,@AsonDate,111)and b.ActualDate is Null and a.Branchid = @BranchID and a.Compid = @CompID
		
		union
		Select x.ItemCode,x.ItemDescription,convert(varchar(10),@AsonDate,111) as ScheduleDate,'Qty'  as Baeson from (
			Select Distinct a.ItemCode,c.ItemDescription,b.Scheduledate,Max(b.ActualDate)ActualDate from QC_Calibration_Schedule a 
			left outer join QC_Calibration_Schedule b 	on a.ItemCode=b.ItemCode and a.Branchid=b.Branchid and a.Compid=b.Compid
			left outer join Material_Master c on c.ItemCode =  left(a.ItemCode,len(a.ItemCode)-4)  and c.Branchid = a.Branchid and c.Compid = a.Compid
			Where a.Branchid = @BranchID and a.Compid = @CompID and b.ActualDate is not null
			group by a.ItemCode,c.ItemDescription,b.Scheduledate
		)x 

		Left outer join QC_Calibration_Master d on d.ItemCode=x.ItemCode and d.Branchid = @BranchID and d.Compid = @CompID
		where (d.ClibQty-d.CalibAlertPercentage)<=isnull(dbo.Fn_Qc_InstrumentUseQty(x.ItemCode,x.ActualDate,@BranchID,@CompID),0)
		 and d.Status=1 and d.Branchid = @BranchID and d.Compid = @CompID
		and  Not exists (Select * from QC_Calibration_Schedule where ItemCode=x.ItemCode and ScheduleDate=x.ScheduleDate and Branchid=@BranchID and Compid=@CompID)
	Return
END
GO

