/****** Object:  UserDefinedFunction [dbo].[fn_QC_LogEntry_ItemSelect]    Script Date: 17/06/2026 11:38:51 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_QC_LogEntry_ItemSelect] (@PlanType varchar(3), @PlanNo int, @PlanDate datetime, @ShiftCode varchar(3), @BranchID varchar(3), @CompID varchar(3))  

RETURNS @Item TABLE
	(DocType		varchar(3),
	DocNo			int,
	DocDate		Datetime,
	StageCode		varchar(20),
	ItemDescription		varchar(50),
	MachineCode		varchar(20),			
	WorkOrderType		varchar(3),
	WorkOrderNo		int,
	WorkOrderDate		datetime,
	PlanQty			float,
	UOMDesc		varchar(5),
	CycleTime		float,
	StartTime		datetime,
	EndTime		datetime,
	ToBeEnterTime 		datetime,
	DrawingCode		varchar(20),
	Status			int,
	LotSize			int,
	Branchid		varchar(3),
	Compid			varchar(3),
	Nos  int)

AS  

BEGIN 

	Declare @PatrolCode int
	Declare @PatrolDuration int		
	Declare @sEOF int	

	Select @PatrolCode = 15		--Inspection Code for Patrol Inspection Type
	Select @PatrolDuration = val FROM Com_Inspection_Option_dtl where InspectionTypeCode=@PatrolCode and Code=2 and InspectionTypeCode=@PatrolCode	-- In Mintes

	Declare @MaxTime datetime		--Last Entry Time for Current Shift
	Declare @MaxTime1 datetime		--Last Entry Time for Current Shift
	Declare @PrvTime datetime		--Previous Entry Time for Current Shift
	Declare @ToBeEnterCount int		--To Be Entered Count from Production Plan
	Declare @EnteredCount int		--Entered Count from Inspection Details
	Declare @NewPatrolSetEntry bit		--Whether Pending Items or New Set
	Declare @EndTime as datetime		--Shift end  time

		Begin
			Select @MaxTime=DateAdd(n, @PatrolDuration, a.StartDate+convert(varchar(5),b.StartTime,108)) 
			, @EndTime=DateAdd(n,b.ShiftMinutes, a.StartDate+convert(varchar(5),b.StartTime,108)) 
			from 
				(Select top 1 StartDate, BranchID, CompID
					from Dailyplan_Dtl 
				Where DocNo=@PlanNo and DocDate=@PlanDate and DocType=@PlanType and BranchID=@BranchID and CompID=@CompID
				) a
			Left Outer Join PPC_Shift_Master b On a.BranchID=b.BranchID and a.CompID=b.CompID
			Where b.ShiftCode=@ShiftCode

		Select @MaxTime1=dateadd(n,-120,LogTime) from Qc_Maxtime_Tmp where DocType=@PLanType and Docno=@Planno and DocDate=@PlanDate
			if isnull(@Maxtime1,0)<>0 AND @Maxtime1>@Maxtime
				Select @Maxtime=@Maxtime1

			select @PrvTime=DateAdd(minute, -(@PatrolDuration - 1), @MaxTime)
		End

eLoopFirst:	
		
	if @EndTime>= @MaxTime
		Begin
			Insert into @Item
			select * from (
				Select Distinct a.DocType,a.DocNo,a.DocDate,.a.StageCode, b.ItemDescription, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate, a.Date1,
					b.UOMDesc, c.CycleTime, a.StartTime, a.EndTime,@MaxTime as MaxTime, d.DrawingCode, case when exists (select Distinct ItemCode from  Qc_Inspection_MAster e where e.InspectionTypeCode=@PatrolCode and e.Inspect=1 and ItemCode=a.StageCode) then 1 else 0 end Status,
					isnull(((60*@PatrolDuration)/c.CycleTime)-isnull((select sum(Qty) from QC_Inspection_Criteria where InspectionType=e.InspectionType 
					and InspectionNo=e.InspectionNo and InspectionDate = e.InspectionDate And ItemCode = e.ItemCode And MachineCode = e.MachineCode 
					and TobeEnterTime between dateadd(minute,-119,@MaxTime) and @MaxTime),0),0)lotSize,a.Branchid,a.Compid,1 as nn
					from Dailyplan_Dtl a 
					Left Outer Join Material_Master b On a.StageCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID
					Left Outer Join BOM_ItemwiseMachinewiseCycleTime c on a.StageCode=c.ItemCode and a.MachineCode=c.MachineCode and a.Branchid=c.Branchid and a.Compid=c.Compid 
					Left Outer Join BOM_Drawing_Master d on a.StageCode=d.ItemCode and Type='O' and a.Branchid=d.Branchid and a.Compid=d.Compid
					left outer join QC_Inspection_Hdr e on a.DocType=e.RefType and a.DocNo=e.RefNo and a.DocDate=e.RefDate and e.MachineCode=a.MachineCode and e.ItemCode=a.StageCode and a.Branchid=e.Branchid and a.Compid=e.Compid and e.InspectionTypeCode=15 and  a.Starttime=e.Starttime
					inner join (Select Distinct a.ItemCode,a.MachineCode,a.Branchid,a.Compid from Qc_Inspection_Hdr a
							left outer join Qc_Inspection_Dtl b on a.inspectionType=b.inspectionType and a.InspectionNo=b.InspectionNo
							and a.InspectionDate=b.InspectionDate and a.Branchid=b.Branchid and a.Compid=b.Compid
							where a.InspectionTypeCode=@PatrolCode and b.TobeEntertime between dateadd(minute,-@PatrolDuration,@MaxTime) and @MaxTime
							and a.RefType=@PlanType and a.RefNo=@PlanNo and a.RefDate=@PlanDate 
						   UNION
							Select Distinct a.StageCode,a.MachineCode,a.Branchid,a.Compid from Dailyplan_Dtl a
							where (@MaxTime between a.Starttime and a.Endtime or a.Endtime between dateadd(minute,-@PatrolDuration,@MaxTime) and @MaxTime)
							and a.DocType=@PlanType and a.DocNo=@PlanNo and a.DocDate=@PlanDate
							and a.StageCode not in(select Distinct ItemCode from  Qc_Inspection_MAster e 
							where e.InspectionTypeCode=15 and e.Inspect=1))f
					on a.StageCode=f.ItemCode and a.MachineCode=f.MachineCode and a.Branchid=f.Branchid and a.Compid=f.Compid
	
					Where a.DocNo=@PlanNo and a.DocDate=@PlanDate and a.DocType=@PlanType and a.Shift=@ShiftCode and a.BranchID=@BranchID and a.CompID=@CompID and a.Status<>0 and a.Operationname<>'SETTING'
						and (a.StartTime  between dateadd(minute,-119,@MaxTime) and @MaxTime or  a.EndTime  between dateadd(minute,-119,@MaxTime) and @MaxTime or( @MaxTime between a.StartTime  and a.EndTime))
						and Not Exists (Select * 	from QC_Inspection_Criteria g 							
								Where g.RefNo=a.DocNo and g.RefDate=a.DocDate and g.RefType=a.DocType  and g.MachineCode=a.MachineCode and g.ItemCode=a.StageCode and g.Starttime=a.Starttime
									and g.Branchid=a.BranchID and g.Compid=a.CompID and g.ToBeEnterTime=@MaxTime and Type in('C','LR')
							           ) and isnull(e.CompletedStatus,0)=0 and isnull(e.InspectionTypeCode,0)<>16 
							
						and c.CycleTime is not null and isnull(e.CompletedStatus,0)=0)x
				where x.LotSize>=1 --or (x.StageCode not in (select Distinct ItemCode from  Qc_Inspection_MAster e where e.InspectionTypeCode=15 and e.Inspect=1) and x.LotSize>=1)

				select @sEOF=isnull(count(*),0) from @Item     --Record Not then Time To Add
					if @sEOF='0'
						begin
							Select @MaxTime = DateAdd(n, @PatrolDuration, @MaxTime)
							goto eLoopFirst
						End
					else
						begin
						Insert into @Item		--Non Completed Items
							Select * from (Select Distinct a.DocType,a.DocNo,a.DocDate,a.StageCode, b.ItemDescription, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate, a.Date1,
						b.UOMDesc, c.CycleTime, a.StartTime, a.EndTime,@MaxTime as stime, d.DrawingCode, case when exists (select Distinct ItemCode from  Qc_Inspection_MAster e where e.InspectionTypeCode=@PatrolCode and e.Inspect=1 and ItemCode=a.StageCode) then 1 else 0 end Status,
						isnull(((60*@PatrolDuration)/c.CycleTime)-isnull((select sum(Qty) from QC_Inspection_Criteria where InspectionType=e.InspectionType 
						and InspectionNo=e.InspectionNo and InspectionDate = e.InspectionDate And ItemCode = e.ItemCode And MachineCode = e.MachineCode 
						and TobeEnterTime between dateadd(minute,-119,@MaxTime) and @MaxTime),0),0)lotSize,@Branchid as Branchid,@Compid as Compid,0 as nn
					from
						(Select * from (
								select Distinct a.*,(select isnull(Sum(Qty),0) from QC_Inspection_Criteria where (Type not in('R','LR') or (Type in ('R','LR') and CriteriaCode=14))
								and MachineCode=a.MachineCode and ItemCode=a.StageCode and RefType=a.DocType and Refno=a.Docno and RefDate=a.DocDate and Branchid=a.Branchid and Compid=a.Compid and Starttime=a.Starttime )CompletedQty from Dailyplan_Dtl a
								inner join QC_Inspection_Criteria b on b.MachineCode=a.MachineCode and b.ItemCode=a.StageCode and b.RefType=a.DocType and b.Refno=a.Docno and b.RefDate=a.DocDate

								and b.Branchid=a.Branchid and b.Compid=a.Compid and b.Starttime=a.Starttime where b.RefType=@PlanType and b.Refno=@PlanNo and b.RefDate=@PlanDate 
								and Not Exists(Select * 	from QC_Inspection_Criteria g 							
										Where g.RefNo=a.DocNo and g.RefDate=a.DocDate and g.RefType=a.DocType  and g.MachineCode=a.MachineCode and g.ItemCode=a.StageCode  --and g.Starttime=a.Starttime
										and g.Branchid=a.BranchID and g.Compid=a.CompID and g.ToBeEnterTime=@MaxTime and Type in('C','LR'))
								and Endtime<@MaxTime and Status=1 and b.CompletedStatus=0)x 	
								where isnull(Date1,0)>isnull(CompletedQty,0) and x.OperationName<>'SETTING' 
						) a
						Left Outer Join Material_Master b On a.StageCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID
						Left Outer Join BOM_ItemwiseMachinewiseCycleTime c on a.StageCode=c.ItemCode and a.MachineCode=c.MachineCode and a.Branchid=c.Branchid and a.Compid=c.Compid 
						Left Outer Join BOM_Drawing_Master d on a.StageCode=d.ItemCode and Type='O' and a.Branchid=d.Branchid and a.Compid=d.Compid
						left outer join QC_Inspection_Hdr e on a.DocType=e.RefType and a.DocNo=e.RefNo and a.DocDate=e.RefDate and e.MachineCode=a.MachineCode and e.ItemCode=a.StageCode and a.Branchid=e.Branchid and a.Compid=e.Compid and  a.Starttime=e.Starttime
						Where  isnull(e.CompletedStatus,0)=0 and isnull(e.InspectionTypeCode,0)<>16 --and c.CycleTime is not null

								and Not Exists (Select * from @Item n 
										Where a.StageCode=n.StageCode and a.MachineCode=n.MachineCode and a.StartTime=n.StartTime and a.EndTime=n.EndTime 
											and a.WorkOrderType=n.WorkOrderType and a.WorkOrderNo=n.WorkOrderNo and a.WorkOrderDate=n.WorkOrderDate))x where x.LotSize>0
									--and  a.StageCode not in (select Distinct ItemCode from  Qc_Inspection_MAster e where e.InspectionTypeCode=@PatrolCode)
						End
			end
		else
			begin
				Select @MaxTime=@EndTime
				Insert into @Item		--Non Completed Items
					Select * from (Select Distinct a.DocType,a.DocNo,a.DocDate,a.StageCode, b.ItemDescription, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate, a.Date1,
						b.UOMDesc, c.CycleTime, a.StartTime, a.EndTime,@MaxTime as stime, d.DrawingCode, case when exists (select Distinct ItemCode from  Qc_Inspection_MAster e where e.InspectionTypeCode=@PatrolCode and e.Inspect=1 and ItemCode=a.StageCode) then 1 else 0 end Status,
						isnull(((60*@PatrolDuration)/c.CycleTime)-isnull((select isnull(sum(Qty),0) from QC_Inspection_Criteria where InspectionType=e.InspectionType 
						and InspectionNo=e.InspectionNo and InspectionDate = e.InspectionDate And ItemCode = e.ItemCode And MachineCode = e.MachineCode 
						and TobeEnterTime between dateadd(minute,-119,@MaxTime) and @MaxTime),0),0)lotSize,@Branchid as Branchid,@Compid as Compid,0 as nn
					from
						(Select * from (
									select Distinct a.*,(select isnull(Sum(Qty),0) from QC_Inspection_Criteria where (Type not in('R','LR') or (Type in ('R','LR') and CriteriaCode=14))
									and MachineCode=a.MachineCode and ItemCode=a.StageCode and RefType=a.DocType and Refno=a.Docno and RefDate=a.DocDate and Branchid=a.Branchid and Compid=a.Compid and Starttime=a.Starttime )CompletedQty from Dailyplan_Dtl a
									inner join QC_Inspection_Criteria b on b.MachineCode=a.MachineCode and b.ItemCode=a.StageCode and b.RefType=a.DocType and b.Refno=a.Docno and b.RefDate=a.DocDate
									and b.Branchid=a.Branchid and b.Compid=a.Compid and b.Starttime=a.Starttime where b.RefType=@PlanType and b.Refno=@PlanNo and b.RefDate=@PlanDate --and a.Revisionno=(Select max(Revisionno) from Dailyplan_Dtl where DocType=a.DocType and DocNo=a.Docno and DocDate=a.DocDate
									--and Branchid=a.Branchid and Compid=a.Compid) 
									and Not Exists(Select * 	from QC_Inspection_Criteria g 							
												Where g.RefNo=a.DocNo and g.RefDate=a.DocDate and g.RefType=a.DocType  and g.MachineCode=a.MachineCode and g.ItemCode=a.StageCode  --and g.Starttime=a.Starttime
												and g.Branchid=a.BranchID and g.Compid=a.CompID and g.ToBeEnterTime=@MaxTime and Type in('C','LR'))
									and Endtime<@MaxTime and Status=1 and isnull(b.CompletedStatus,0)=0)x 
														where  isnull(Date1,0)>isnull(CompletedQty,0) and x.OperationName<>'SETTING' 
						) a
						Left Outer Join Material_Master b On a.StageCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID
						Left Outer Join BOM_ItemwiseMachinewiseCycleTime c on a.StageCode=c.ItemCode and a.MachineCode=c.MachineCode and a.Branchid=c.Branchid and a.Compid=c.Compid 
						Left Outer Join BOM_Drawing_Master d on a.StageCode=d.ItemCode and Type='O' and a.Branchid=d.Branchid and a.Compid=d.Compid
						left outer join QC_Inspection_Hdr e on a.DocType=e.RefType and a.DocNo=e.RefNo and a.DocDate=e.RefDate and e.MachineCode=a.MachineCode and e.ItemCode=a.StageCode and a.Branchid=e.Branchid and a.Compid=e.Compid and  a.Starttime=e.Starttime
						Where  isnull(e.CompletedStatus,0)=0 and isnull(e.InspectionTypeCode,0)<>16 --and c.CycleTime is not null

						and Not Exists (Select * from @Item n 
								Where a.StageCode=n.StageCode and a.MachineCode=n.MachineCode and a.StartTime=n.StartTime and a.EndTime=n.EndTime 
									and a.WorkOrderType=n.WorkOrderType and a.WorkOrderNo=n.WorkOrderNo and a.WorkOrderDate=n.WorkOrderDate))x where x.LotSize>0
							--and  a.StageCode not in (select Distinct ItemCode from  Qc_Inspection_MAster e where e.InspectionTypeCode=@PatrolCode)
				End
		
	Return


END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_QC_LogItemSelect]    Script Date: 17/06/2026 11:38:51 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

  
CREATE FUNCTION [dbo].[fn_QC_LogItemSelect] (@PlanType varchar(3), @PlanNo int, @PlanDate datetime, @ShiftCode varchar(3), @BranchID varchar(3), @CompID varchar(3))                    
                  
RETURNS @Item TABLE                  
 (DocType  varchar(3),                  
 DocNo   int,                  
 DocDate  Datetime,                  
 StageCode  varchar(20),                  
 ItemDescription  varchar(50),                  
 MachineCode  varchar(20),                     
 WorkOrderType  varchar(3),                  
 WorkOrderNo  int,                  
 WorkOrderDate  datetime,                  
 PlanQty   float,                  
 UOMDesc  varchar(5),                  
 CycleTime  float,                  
 StartTime  datetime,                  
 EndTime  datetime,                  
 ToBeEnterTime   datetime,                  
 DrawingCode  varchar(20),                  
 Status   int,                  
 LotSize   int,                  
 Branchid  varchar(3),                  
 Compid   varchar(3),                  
 Nos  int)                  
                  
AS                    
                  
BEGIN                   
                  
 Declare @PatrolCode int                  
 Declare @PatrolDuration int                    
 Declare @sEOF int                   
                  
 Select @PatrolCode = 8  --Inspection Code for Patrol Inspection Type                  
 Select @PatrolDuration = val FROM Com_Inspection_Option_dtl where InspectionTypeCode=8 and Code=2           
 --and InspectionTypeCode=@PatrolCode -- In Mintes                  
                  
 Declare @MaxTime datetime  --Last Entry Time for Current Shift                  
 Declare @MaxTime1 datetime  --Last Entry Time for Current Shift                  
 Declare @StartTime datetime  --Previous Entry Time for Current Shift                  
 Declare @ToBeEnterCount int  --To Be Entered Count from Production Plan                  
 Declare @EnteredCount int  --Entered Count from Inspection Details                  
 Declare @NewPatrolSetEntry bit  --Whether Pending Items or New Set                  
 Declare @EndTime as datetime  --Shift end  time                  
 Declare @PrdDate as datetime   --Production Filter Date for Time out Expired Problem   --Ref Somu, Doss              
  Begin                  
                  
                   
        Set @PrdDate = Dateadd(d,-5,Convert(Varchar(10),getdate(),126))                 
              
        Select @MaxTime=DateAdd(n, @PatrolDuration, a.StartDate+convert(varchar(5),b.StartTime,108)) ,              
        @StartTime=a.StartDate+convert(varchar(5),b.StartTime,108),               
        @EndTime=DateAdd(n,b.ShiftMinutes, a.StartDate+convert(varchar(5),b.StartTime,108))                   
        From                   
            (Select top 1 StartDate, BranchID, CompID                  
             From Dailyplan_Dtl                   
             Where DocNo=@PlanNo and DocDate=@PlanDate and DocType=@PlanType and BranchID=@BranchID and CompID=@CompID                  
            ) a                  
        Left Outer Join PPC_Shift_Master b On a.BranchID=b.BranchID and a.CompID=b.CompID                  
        Where b.ShiftCode=@ShiftCode                  
              
        Select @MaxTime1=LogTime from Qc_Maxtime_Tmp where DocType=@PlanType and Docno=@Planno and DocDate=@PlanDate              
                          
        If isnull(@Maxtime1,0)<>0 AND @Maxtime1>@Maxtime                  
            Begin                  
                Select @Maxtime=DateAdd(n, @PatrolDuration, @Maxtime1)                  
            End                  
  End                  
                  
eLoopFirst:                   
                    
 If @EndTime>= @MaxTime                  
  Begin          
           
   Insert into @Item                  
    Select a.DocType,a.DocNo,a.DocDate,a.StageCode, e.ItemDescription, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate,       
 Date1, g.sdesc as UOMDesc, b.CycleTime, a.StartTime, a.EndTime,@MaxTime as MaxTime, '' as DrawingCode,                  
    Case when Exists (Select Distinct ItemCode From Qc_Inspection_MAster f Where f.InspectionTypeCode=@PatrolCode and f.Inspect=1            
 and f.ItemCode=a.StageCode) Then 1 Else 0 End Status,          
    round(((Case when a.Starttime<=dateadd(n,-(@PatrolDuration-1),@MaxTime) then @PatrolDuration               
    Else (@PatrolDuration-datediff(n,dateadd(n,-(@PatrolDuration-1),@MaxTime),a.Starttime)) End *60)/b.CycleTime),0)              
        -Sum(isnull(c.Qty,0))LotSize,a.Branchid,a.Compid,12 as nn                
                        
    From PPC_QuickProductionplan_Dtl a                  
              
    Left Outer Join BOM_ItemwiseMachinewiseCycleTime b                   
    On b.ItemCode=a.StageCode and b.MachineCode=a.MachineCode and b.Branchid=a.Branchid and b.Compid=a.Compid                   
                   
    Left outer join QC_Inspection_Criteria c                   
    On c.RefNo=a.DocNo and c.RefDate=a.DocDate and c.RefType=a.DocType and c.MachineCode=a.MachineCode and c.ItemCode=a.StageCode                  
        and c.Branchid=a.Branchid and c.Compid=a.Compid and c.Finyear = a.Finyear               
        and c.TobeEnterTime between dateadd(n,-(@PatrolDuration-1),@MaxTime) and @MaxTime               
        /*and CriteriaCode not in (Select Case when c1.ItemCode=a.StageCode then 0 else 20 end from QC_Inspection_Criteria c1              
                            Where c1.RefNo=c.RefNo and c1.RefDate=c.RefDate and c1.RefType=c.RefType and c1.MachineCode=c.MachineCode               
                            and c1.ItemCode=c.ItemCode and c1.Branchid=c.Branchid and c1.Compid=c.Compid               
                            and c1.TobeEnterTime between dateadd(n,-(@PatrolDuration-1),@MaxTime) and @MaxTime and c1.CriteriaCode=20) */                   
    Left outer join (Select RefType,RefNo,RefDate,ItemCode,MachineCode,Starttime,Branchid,Compid,Type,Sum(Qty)Qty               
                    From QC_Inspection_Criteria Where Type='C'               
                    Group by RefType,RefNo,RefDate,ItemCode,MachineCode,Starttime,Branchid,Compid,Type)d                  
    On d.RefNo=a.DocNo and d.RefDate=a.DocDate and d.RefType=a.DocType and d.ItemCode=a.StageCode and d.MachineCode=a.MachineCode                   
    and d.Starttime=a.Starttime and d.Branchid=a.Branchid and d.Compid=a.Compid and c.Finyear = a.Finyear                   
                   
    Left Outer Join Inv_Material_Master e               
    On e.ItemCode=a.StageCode and e.BranchID=a.BranchID and e.CompID=a.CompID                  
              
    Left outer join Qc_Inspection_Hdr f                    
    On a.DocType=f.RefType and a.DocNo=f.RefNo and A.DocDate = f.RefDate and f.InspectionTypeCode=@PatrolCode               
    and a.Starttime=f.Starttime And A.StageCode = f.ItemCode And A.MachineCode = f.MachineCode               
    and f.BranchID=a.BranchID and f.CompID=a.CompID              
                  
    Left Outer Join Inv_Uom_Master g               
    On g.Code=e.Uom and g.Branchid=e.Branchid and g.Compid=e.Compid                
                   
    Where a.DocNo=@PlanNo and a.DocDate=@PlanDate and a.DocType=@PlanType and a.Shift = @ShiftCode and a.Status<>0         
    and a.StartTime<@MaxTime and a.OperationName<>'SETTING' and a.ShortClose=0 and isnull(f.CompletedStatus,0)=0                
    and a.RevisionNo=(Select Max(RevisionNo) From PPC_QuickProductionplan_Dtl a1                   
        Where a.DocNo = a1.DocNo and a.DocType = a1.DocType and a.DocDate = a1.DocDate and a1.StartDate = a.StartDate and a1.StageCode=a.StageCode and a1.MachineCode=a.MachineCode   
				/*and a1.Starttime=a.Starttime*/ and a1.Shift = a.Shift and a.Branchid=a1.BranchID and a.Compid=a1.CompID and a.Finyear = a1.Finyear)                   
              
    and Not Exists (Select * from QC_Inspection_Criteria g Where g.RefNo=a.DocNo and g.RefDate=a.DocDate and g.RefType=a.DocType and g.ItemCode=a.StageCode and g.MachineCode=a.MachineCode and g.Starttime=a.Starttime and g.Branchid=a.Branchid    
  
    and g.Compid=a.Compid and CompletedStatus=1)                  
              
    Group by a.DocType,a.DocNo,a.DocDate,a.StageCode, e.ItemDescription, a.MachineCode, a.WorkOrderType, a.WorkOrderNo,               
    a.WorkOrderDate, a.Date1, g.sdesc, b.CycleTime, a.StartTime, a.EndTime,d.Qty ,a.Branchid,a.Compid                  
              
    Having Round(((Case when a.Starttime<=dateadd(n,-(@PatrolDuration-1),@MaxTime) then @PatrolDuration               
    Else (@PatrolDuration-datediff(n,dateadd(n,-(@PatrolDuration-1),@MaxTime),a.Starttime)) end *60)/b.CycleTime),0)              
    > Sum(isnull(c.Qty,0))+1 and a.Date1>Sum(isnull(d.Qty,0))                  
              
    Select @sEOF=isnull(count(*),0) From @Item     --Record Not then Time To Add                  
    If @sEOF='0'                  
        Begin                  
            Select @MaxTime = DateAdd(n, @PatrolDuration, @MaxTime)                  
            goto eLoopFirst                  
        End           
   End                
 Else                  
   Begin               
                   
    Insert into @Item               
                     
    Select a.DocType,a.DocNo,a.DocDate,a.StageCode, e.ItemDescription, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate,              
     Date1, g.sdesc as UOMDesc, b.CycleTime, a.StartTime, a.EndTime,@EndTime as MaxTime, '' as DrawingCode,                   
     Case when Exists (Select Distinct ItemCode From Qc_Inspection_MAster f               
     Where f.InspectionTypeCode=@PatrolCode and f.Inspect=1 and f.ItemCode=a.StageCode) then 1 else 0 end Status,                  
     round(((Case when a.Starttime<=dateadd(n,-(@PatrolDuration-1),@MaxTime) then @PatrolDuration else               
     (@PatrolDuration-datediff(n,dateadd(n,-(@PatrolDuration-1),@MaxTime),a.Starttime)) end  *60)/b.CycleTime),0)              
     -Sum(isnull(c.Qty,0))LotSize,a.Branchid,a.Compid,1 as nn               
                      
    From PPC_QuickProductionplan_Dtl a                  
              
    Left Outer Join BOM_ItemwiseMachinewiseCycleTime b                   
    On b.ItemCode=a.StageCode and b.MachineCode=a.MachineCode and b.Branchid=a.Branchid and b.Compid=a.Compid                   
                   
    Left outer join QC_Inspection_Criteria c                   
    On c.RefNo=a.DocNo and c.RefDate=a.DocDate and c.RefType=a.DocType and c.MachineCode=a.MachineCode and c.ItemCode=a.StageCode                  
        and c.Branchid=a.Branchid and c.Compid=a.Compid and c.Finyear = a.Finyear               
        and c.TobeEnterTime between dateadd(n,-(@PatrolDuration-1),@MaxTime) and @MaxTime               
        and CriteriaCode not in (Select Case when c1.ItemCode=a.StageCode then 0 else 20 end from QC_Inspection_Criteria c1              
                            Where c1.RefNo=c.RefNo and c1.RefDate=c.RefDate and c1.RefType=c.RefType and c1.MachineCode=c.MachineCode               
                            and c1.ItemCode=c.ItemCode and c1.Branchid=c.Branchid and c1.Compid=c.Compid               
                            and c1.TobeEnterTime between dateadd(n,-(@PatrolDuration-1),@MaxTime) and @MaxTime and c1.CriteriaCode=20)                    
    Left outer join (Select RefType,RefNo,RefDate,ItemCode,MachineCode,Starttime,Branchid,Compid,Type,Sum(Qty)Qty               
                    From QC_Inspection_Criteria                  
                    Where Type='C'               
                    Group by RefType,RefNo,RefDate,ItemCode,MachineCode,Starttime,Branchid,Compid,Type)d                  
    On d.RefNo=a.DocNo and d.RefDate=a.DocDate and d.RefType=a.DocType and d.ItemCode=a.StageCode and d.MachineCode=a.MachineCode                   
    and d.Starttime=a.Starttime and d.Branchid=a.Branchid and d.Compid=a.Compid and c.Finyear = a.Finyear                   
                   
    Left Outer Join Inv_Material_Master e               
    On e.ItemCode=a.StageCode and e.BranchID=a.BranchID and e.CompID=a.CompID                  
              
    Left outer join Qc_Inspection_Hdr f                    
    On a.DocType=f.RefType and a.DocNo=f.RefNo and A.DocDate = f.RefDate and f.InspectionTypeCode=@PatrolCode               
    and a.Starttime=f.Starttime And A.StageCode = f.ItemCode And A.MachineCode = f.MachineCode               
    and f.BranchID=a.BranchID and f.CompID=a.CompID              
                  
    Left Outer Join Inv_Uom_Master g               
    On g.Code=e.Uom and g.Branchid=e.Branchid and g.Compid=e.Compid                      
                   
    Where a.DocNo=@PlanNo and a.DocDate=@PlanDate and a.DocType=@PlanType and a.Status<>0 and a.StartTime<@MaxTime               
    and a.OperationName<>'SETTING' and a.ShortClose=0 and isnull(f.CompletedStatus,0)=0                
    and a.RevisionNo=(Select Max(RevisionNo) From PPC_QuickProductionplan_Dtl a1                   
        Where a.DocNo = a1.DocNo and a.DocType = a1.DocType and a.DocDate = a1.DocDate and a1.StartDate = a.StartDate and a1.StageCode=a.StageCode and a1.MachineCode=a.MachineCode   
				/*and a1.Starttime=a.Starttime*/ and a1.Shift = a.Shift and a.Branchid=a1.BranchID and a.Compid=a1.CompID and a.Finyear = a1.Finyear)            
                
      and Not Exists (Select * from QC_Inspection_Criteria g Where g.RefNo=a.DocNo and g.RefDate=a.DocDate and g.RefType=a.DocType                   
      and g.ItemCode=a.StageCode and g.MachineCode=a.MachineCode and g.Starttime=a.Starttime and g.Branchid=a.Branchid               
      and g.Compid=a.Compid and CompletedStatus=1)                 
                  
     Group by a.DocType,a.DocNo,a.DocDate,a.StageCode, e.ItemDescription, a.MachineCode, a.WorkOrderType, a.WorkOrderNo,               
     a.WorkOrderDate, a.Date1, g.sdesc, b.CycleTime, a.StartTime, a.EndTime,d.Qty ,a.Branchid,a.Compid                  
                   
     Having a.Date1>Sum(isnull(d.Qty,0))                  
  End                 
                   
 Return                  
                  
END   
GO

/****** Object:  UserDefinedFunction [dbo].[fn_QC_LogItemSelect_tobeDeleted_tmp]    Script Date: 17/06/2026 11:38:52 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_QC_LogItemSelect_tobeDeleted_tmp] (@PlanType varchar(3), @PlanNo int, @PlanDate datetime, @ShiftCode varchar(3), 
	@BranchID varchar(3), @CompID varchar(3))                      
                    
RETURNS @Item TABLE                    
 (DocType  varchar(3),                    
 DocNo   int,                    
 DocDate  Datetime,                    
 StageCode  varchar(20),                    
 ItemDescription  varchar(50),                    
 MachineCode  varchar(20),                       
 WorkOrderType  varchar(3),                    
 WorkOrderNo  int,                    
 WorkOrderDate  datetime,                    
 PlanQty   float,                    
 UOMDesc  varchar(5),                    
 CycleTime  float,                    
 StartTime  datetime,                    
 EndTime  datetime,                    
 ToBeEnterTime   datetime,                    
 DrawingCode  varchar(20),                    
 Status   int,                    
 LotSize   int,                    
 Branchid  varchar(3),                    
 Compid   varchar(3),                    
 Nos  int)                    
                    
AS                      
                    
BEGIN                     
                    
 Declare @PatrolCode int                    
 Declare @PatrolDuration int                      
 Declare @sEOF int                     
                    
 Select @PatrolCode = 8  --Inspection Code for Patrol Inspection Type                    
 Select @PatrolDuration = val FROM Com_Inspection_Option_dtl where InspectionTypeCode=8 and Code=2             
 --and InspectionTypeCode=@PatrolCode -- In Mintes                    
                    
 Declare @MaxTime datetime  --Last Entry Time for Current Shift                    
 Declare @MaxTime1 datetime  --Last Entry Time for Current Shift                    
 Declare @StartTime datetime  --Previous Entry Time for Current Shift                    
 Declare @ToBeEnterCount int  --To Be Entered Count from Production Plan                    
 Declare @EnteredCount int  --Entered Count from Inspection Details                    
 Declare @NewPatrolSetEntry bit  --Whether Pending Items or New Set                    
 Declare @EndTime as datetime  --Shift end  time                    
 Declare @PrdDate as datetime   --Production Filter Date for Time out Expired Problem   --Ref Somu, Doss                
  Begin                    
                    
                     
        Set @PrdDate = Dateadd(d,-5,Convert(Varchar(10),getdate(),126))                   
                
        Select @MaxTime=DateAdd(n, @PatrolDuration, a.StartDate+convert(varchar(5),b.StartTime,108)) ,                
        @StartTime=a.StartDate+convert(varchar(5),b.StartTime,108),                 
        @EndTime=DateAdd(n,b.ShiftMinutes, a.StartDate+convert(varchar(5),b.StartTime,108))                     
        From                     
            (Select top 1 StartDate, BranchID, CompID                    
             From Dailyplan_Dtl                     
             Where DocNo=@PlanNo and DocDate=@PlanDate and DocType=@PlanType and BranchID=@BranchID and CompID=@CompID                    
            ) a                    
        Left Outer Join PPC_Shift_Master b On a.BranchID=b.BranchID and a.CompID=b.CompID                    
        Where b.ShiftCode=@ShiftCode                    
                
        Select @MaxTime1=LogTime from Qc_Maxtime_Tmp where DocType=@PlanType and Docno=@Planno and DocDate=@PlanDate                
                            
        If isnull(@Maxtime1,0)<>0 AND @Maxtime1>@Maxtime                    
            Begin                    
                Select @Maxtime=DateAdd(n, @PatrolDuration, @Maxtime1)                    
            End                    
  End                    
                    
eLoopFirst:                     
                      
 If @EndTime>= @MaxTime                    
  Begin            
             
   Insert into @Item                    
    Select a.DocType,a.DocNo,a.DocDate,a.StageCode, e.ItemDescription, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate,         
 Date1, g.sdesc as UOMDesc, b.CycleTime, a.StartTime, a.EndTime,@MaxTime as MaxTime, '' as DrawingCode,                    
    Case when Exists (Select Distinct ItemCode From Qc_Inspection_MAster f Where f.InspectionTypeCode=@PatrolCode and f.Inspect=1              
 and f.ItemCode=a.StageCode) Then 1 Else 0 End Status,            
    round(((Case when a.Starttime<=dateadd(n,-(@PatrolDuration-1),@MaxTime) then @PatrolDuration                 
    Else (@PatrolDuration-datediff(n,dateadd(n,-(@PatrolDuration-1),@MaxTime),a.Starttime)) End *60)/b.CycleTime),0)                
        -Sum(isnull(c.Qty,0))LotSize,a.Branchid,a.Compid,12 as nn                  
                          
    From PPC_QuickProductionplan_Dtl a                    
                
    Left Outer Join BOM_ItemwiseMachinewiseCycleTime b                     
    On b.ItemCode=a.StageCode and b.MachineCode=a.MachineCode and b.Branchid=a.Branchid and b.Compid=a.Compid                     
                     
    Left outer join QC_Inspection_Criteria c                     
    On c.RefNo=a.DocNo and c.RefDate=a.DocDate and c.RefType=a.DocType and c.MachineCode=a.MachineCode and c.ItemCode=a.StageCode                    
        and c.Branchid=a.Branchid and c.Compid=a.Compid and c.Finyear = a.Finyear                 
        and c.TobeEnterTime between dateadd(n,-(@PatrolDuration-1),@MaxTime) and @MaxTime                 
        /*and CriteriaCode not in (Select Case when c1.ItemCode=a.StageCode then 0 else 20 end from QC_Inspection_Criteria c1                
                            Where c1.RefNo=c.RefNo and c1.RefDate=c.RefDate and c1.RefType=c.RefType and c1.MachineCode=c.MachineCode                 
                            and c1.ItemCode=c.ItemCode and c1.Branchid=c.Branchid and c1.Compid=c.Compid                 
                            and c1.TobeEnterTime between dateadd(n,-(@PatrolDuration-1),@MaxTime) and @MaxTime and c1.CriteriaCode=20) */                     
    Left outer join (Select RefType,RefNo,RefDate,ItemCode,MachineCode,Starttime,Branchid,Compid,Type,Sum(Qty)Qty                 
                    From QC_Inspection_Criteria Where Type='C'                 
                    Group by RefType,RefNo,RefDate,ItemCode,MachineCode,Starttime,Branchid,Compid,Type)d                    
    On d.RefNo=a.DocNo and d.RefDate=a.DocDate and d.RefType=a.DocType and d.ItemCode=a.StageCode and d.MachineCode=a.MachineCode                     
    and d.Starttime=a.Starttime and d.Branchid=a.Branchid and d.Compid=a.Compid and c.Finyear = a.Finyear                     
                     
    Left Outer Join Inv_Material_Master e                 
    On e.ItemCode=a.StageCode and e.BranchID=a.BranchID and e.CompID=a.CompID                    
                
    Left outer join Qc_Inspection_Hdr f                      
    On a.DocType=f.RefType and a.DocNo=f.RefNo and A.DocDate = f.RefDate and f.InspectionTypeCode=@PatrolCode                 
    and a.Starttime=f.Starttime And A.StageCode = f.ItemCode And A.MachineCode = f.MachineCode                 
    and f.BranchID=a.BranchID and f.CompID=a.CompID                
                    
    Left Outer Join Inv_Uom_Master g                 
    On g.Code=e.Uom and g.Branchid=e.Branchid and g.Compid=e.Compid                  
                     
    Where a.DocNo=@PlanNo and a.DocDate=@PlanDate and a.DocType=@PlanType and a.Shift = @ShiftCode and a.Status<>0           
    and a.StartTime<@MaxTime and a.OperationName<>'SETTING' and a.ShortClose=0 and isnull(f.CompletedStatus,0)=0                  
    and a.RevisionNo=(Select Max(RevisionNo) From PPC_QuickProductionplan_Dtl a1                     
        Where a.DocNo = a1.DocNo and a.DocType = a1.DocType and a.DocDate = a1.DocDate and a1.StartDate = a.StartDate and a1.StageCode=a.StageCode and a1.MachineCode=a.MachineCode     
    /*and a1.Starttime=a.Starttime*/ and a1.Shift = a.Shift and a.Branchid=a1.BranchID and a.Compid=a1.CompID and a.Finyear = a1.Finyear)                     
                
    and Not Exists (Select * from QC_Inspection_Criteria g Where g.RefNo=a.DocNo and g.RefDate=a.DocDate and g.RefType=a.DocType and g.ItemCode=a.StageCode and g.MachineCode=a.MachineCode and g.Starttime=a.Starttime and g.Branchid=a.Branchid      
    
    and g.Compid=a.Compid and CompletedStatus=1)                    
                
    Group by a.DocType,a.DocNo,a.DocDate,a.StageCode, e.ItemDescription, a.MachineCode, a.WorkOrderType, a.WorkOrderNo,                 
    a.WorkOrderDate, a.Date1, g.sdesc, b.CycleTime, a.StartTime, a.EndTime,d.Qty ,a.Branchid,a.Compid                    
                
    Having Round(((Case when a.Starttime<=dateadd(n,-(@PatrolDuration-1),@MaxTime) then @PatrolDuration                 
    Else (@PatrolDuration-datediff(n,dateadd(n,-(@PatrolDuration-1),@MaxTime),a.Starttime)) end *60)/b.CycleTime),0)                
    > Sum(isnull(c.Qty,0))+1 and a.Date1>Sum(isnull(d.Qty,0))                    
                
    Select @sEOF=isnull(count(*),0) From @Item     --Record Not then Time To Add                    
    If @sEOF='0'                    
        Begin                    
            Select @MaxTime = DateAdd(n, @PatrolDuration, @MaxTime)                    
            goto eLoopFirst                    
        End             
   End                  
 Else                    
   Begin                 
                     
    Insert into @Item                 
                       
    Select a.DocType,a.DocNo,a.DocDate,a.StageCode, e.ItemDescription, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate,                
     Date1, g.sdesc as UOMDesc, b.CycleTime, a.StartTime, a.EndTime,@EndTime as MaxTime, '' as DrawingCode,                     
     Case when Exists (Select Distinct ItemCode From Qc_Inspection_MAster f                 
     Where f.InspectionTypeCode=@PatrolCode and f.Inspect=1 and f.ItemCode=a.StageCode) then 1 else 0 end Status,                    
     round(((Case when a.Starttime<=dateadd(n,-(@PatrolDuration-1),@MaxTime) then @PatrolDuration else                 
     (@PatrolDuration-datediff(n,dateadd(n,-(@PatrolDuration-1),@MaxTime),a.Starttime)) end  *60)/b.CycleTime),0)                
     -Sum(isnull(c.Qty,0))LotSize,a.Branchid,a.Compid,1 as nn                 
                        
    From PPC_QuickProductionplan_Dtl a                    
                
    Left Outer Join BOM_ItemwiseMachinewiseCycleTime b                     
    On b.ItemCode=a.StageCode and b.MachineCode=a.MachineCode and b.Branchid=a.Branchid and b.Compid=a.Compid                     
                     
    Left outer join QC_Inspection_Criteria c                     
    On c.RefNo=a.DocNo and c.RefDate=a.DocDate and c.RefType=a.DocType and c.MachineCode=a.MachineCode and c.ItemCode=a.StageCode                    
        and c.Branchid=a.Branchid and c.Compid=a.Compid and c.Finyear = a.Finyear                 
        and c.TobeEnterTime between dateadd(n,-(@PatrolDuration-1),@MaxTime) and @MaxTime                 
        and CriteriaCode not in (Select Case when c1.ItemCode=a.StageCode then 0 else 20 end from QC_Inspection_Criteria c1                
                            Where c1.RefNo=c.RefNo and c1.RefDate=c.RefDate and c1.RefType=c.RefType and c1.MachineCode=c.MachineCode                 
                            and c1.ItemCode=c.ItemCode and c1.Branchid=c.Branchid and c1.Compid=c.Compid                 
                            and c1.TobeEnterTime between dateadd(n,-(@PatrolDuration-1),@MaxTime) and @MaxTime and c1.CriteriaCode=20)                      
    Left outer join (Select RefType,RefNo,RefDate,ItemCode,MachineCode,Starttime,Branchid,Compid,Type,Sum(Qty)Qty                 
                    From QC_Inspection_Criteria                    
                    Where Type='C'                 
  Group by RefType,RefNo,RefDate,ItemCode,MachineCode,Starttime,Branchid,Compid,Type)d                    
    On d.RefNo=a.DocNo and d.RefDate=a.DocDate and d.RefType=a.DocType and d.ItemCode=a.StageCode and d.MachineCode=a.MachineCode                     
    and d.Starttime=a.Starttime and d.Branchid=a.Branchid and d.Compid=a.Compid and c.Finyear = a.Finyear                     
                     
    Left Outer Join Inv_Material_Master e                 
    On e.ItemCode=a.StageCode and e.BranchID=a.BranchID and e.CompID=a.CompID                    
                
    Left outer join Qc_Inspection_Hdr f                      
    On a.DocType=f.RefType and a.DocNo=f.RefNo and A.DocDate = f.RefDate and f.InspectionTypeCode=@PatrolCode                 
    and a.Starttime=f.Starttime And A.StageCode = f.ItemCode And A.MachineCode = f.MachineCode                 
    and f.BranchID=a.BranchID and f.CompID=a.CompID                
                    
    Left Outer Join Inv_Uom_Master g                 
    On g.Code=e.Uom and g.Branchid=e.Branchid and g.Compid=e.Compid                        
                     
    Where a.DocNo=@PlanNo and a.DocDate=@PlanDate and a.DocType=@PlanType and a.Status<>0 and a.StartTime<@MaxTime                 
    and a.OperationName<>'SETTING' and a.ShortClose=0 and isnull(f.CompletedStatus,0)=0                  
    and a.RevisionNo=(Select Max(RevisionNo) From PPC_QuickProductionplan_Dtl a1                     
        Where a.DocNo = a1.DocNo and a.DocType = a1.DocType and a.DocDate = a1.DocDate and a1.StartDate = a.StartDate and a1.StageCode=a.StageCode and a1.MachineCode=a.MachineCode     
    /*and a1.Starttime=a.Starttime*/ and a1.Shift = a.Shift and a.Branchid=a1.BranchID and a.Compid=a1.CompID and a.Finyear = a1.Finyear)              
                  
      and Not Exists (Select * from QC_Inspection_Criteria g Where g.RefNo=a.DocNo and g.RefDate=a.DocDate and g.RefType=a.DocType                     
      and g.ItemCode=a.StageCode and g.MachineCode=a.MachineCode and g.Starttime=a.Starttime and g.Branchid=a.Branchid                 
      and g.Compid=a.Compid and CompletedStatus=1)                   
                    
     Group by a.DocType,a.DocNo,a.DocDate,a.StageCode, e.ItemDescription, a.MachineCode, a.WorkOrderType, a.WorkOrderNo,                 
     a.WorkOrderDate, a.Date1, g.sdesc, b.CycleTime, a.StartTime, a.EndTime,d.Qty ,a.Branchid,a.Compid                    
                     
     Having a.Date1>Sum(isnull(d.Qty,0))                    
  End                   
                     
 Return                    
                    
END 
GO

/****** Object:  UserDefinedFunction [dbo].[fn_QC_LogItemSelect_V2]    Script Date: 17/06/2026 11:38:52 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_QC_LogItemSelect_V2] (@PlanType varchar(3), @PlanNo int, @PlanDate datetime,       
 @ShiftCode varchar(3), @BranchID varchar(3), @CompID varchar(3))                            
                          
RETURNS @Item TABLE                          
 (DocType  varchar(3),                          
 DocNo   int,                          
 DocDate  Datetime,                          
 StageCode  varchar(20),                          
 ItemDescription  varchar(50),                          
 MachineCode  varchar(20),                             
 WorkOrderType  varchar(3),                          
 WorkOrderNo  int,                          
 WorkOrderDate  datetime,                          
 PlanQty   float,                          
 UOMDesc  varchar(5),                          
 CycleTime  float,                          
 StartTime  datetime,                          
 EndTime  datetime,                          
 ToBeEnterTime   datetime,                          
 DrawingCode  varchar(20),                          
 Status   int,                          
 LotSize   int,                          
 Branchid  varchar(3),                          
 Compid   varchar(3),                          
 Nos  int)                          
                          
AS                            
                          
BEGIN                                                 
 Declare @PatrolCode int;                          
 Declare @PatrolDuration int;                            
 Declare @IsVal int;     
 Declare @sEOF int;       
                          
 Select @PatrolCode = 8  -- Inspection Code for Patrol Inspection Type       
       
 /* PATROL INSPECTION - LOG ENTRY AT SHIFT END */      
 Select @IsVal = a.isVal FROM Com_Inspection_Option_dtl a       
 Where a.InspectionTypeCode=@PatrolCode and a.Code=7;      
      
 If IsNull(@IsVal,0) = 1 /* LOG ENTRY AT SHIFT END -> True */      
  Begin      
   /* Get Shift Minutes */      
   Select @PatrolDuration = a.ShiftMinutes From PPC_Shift_Master a         
   Where a.ShiftCode=@ShiftCode and a.BranchID=@BranchID and a.CompID=@CompID              
  End      
 Else      
  Begin      
   /* PATROL INSPECTION - LOG FREQUENCY */        
   Select @PatrolDuration = a.val       
   From Com_Inspection_Option_dtl a      
   Where a.InspectionTypeCode=@PatrolCode and a.Code=2;         
  End      
      
  SET @PatrolDuration = IsNull(@PatrolDuration,0);      
        
 --and InspectionTypeCode=@PatrolCode -- In Mintes                          
                          
 Declare @MaxTime datetime  --Last Entry Time for Current Shift                          
 Declare @MaxTime1 datetime  --Last Entry Time for Current Shift                          
 Declare @StartTime datetime  --Previous Entry Time for Current Shift                          
 Declare @ToBeEnterCount int  --To Be Entered Count from Production Plan                          
 Declare @EnteredCount int  --Entered Count from Inspection Details                          
 Declare @NewPatrolSetEntry bit  --Whether Pending Items or New Set                          
 Declare @EndTime as datetime  --Shift end  time                          
 Declare @PrdDate as datetime   --Production Filter Date for Time out Expired Problem   --Ref Somu, Doss                      
  Begin                                                                   
    Set @PrdDate = Dateadd(d,-5,Convert(Varchar(10),getdate(),126))                         
                      
    Select @MaxTime=DateAdd(n, @PatrolDuration, a.StartDate+convert(varchar(5),b.StartTime,108)) ,                      
    @StartTime=a.StartDate+convert(varchar(5),b.StartTime,108),                       
    @EndTime=DateAdd(n,b.ShiftMinutes, a.StartDate+convert(varchar(5),b.StartTime,108))                           
    From                           
        (Select top 1 StartDate, BranchID, CompID                          
            From Dailyplan_Dtl                           
            Where DocNo=@PlanNo and DocDate=@PlanDate and DocType=@PlanType and BranchID=@BranchID and CompID=@CompID                          
        ) a                          
    Left Outer Join PPC_Shift_Master b On a.BranchID=b.BranchID and a.CompID=b.CompID                          
    Where b.ShiftCode=@ShiftCode       
                      
    Select @MaxTime1=LogTime from Qc_Maxtime_Tmp where DocType=@PlanType and Docno=@Planno and DocDate=@PlanDate                      
                                  
    If isnull(@Maxtime1,0)<>0 AND @Maxtime1>@Maxtime                          
    Begin                          
        Select @Maxtime=DateAdd(n, @PatrolDuration, @Maxtime1)                          
    End                          
  End                          
                          
eLoopFirst:                           
                            
 If @EndTime>= @MaxTime                          
  Begin                  
                   
   Insert into @Item                          
    Select a.DocType,a.DocNo,a.DocDate,a.StageCode, e.ItemDescription, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate,               
 Date1, g.sdesc as UOMDesc, b.CycleTime, a.StartTime, a.EndTime,@MaxTime as MaxTime, '' as DrawingCode,                          
    Case when Exists (Select Distinct ItemCode From Qc_Inspection_MAster f Where f.InspectionTypeCode=@PatrolCode and f.Inspect=1                    
 and f.ItemCode=a.StageCode) Then 1 Else 0 End Status,                  
    round(((Case when a.Starttime<=dateadd(n,-(@PatrolDuration-1),@MaxTime) then @PatrolDuration                       
    Else (@PatrolDuration-datediff(n,dateadd(n,-(@PatrolDuration-1),@MaxTime),a.Starttime)) End *60)/b.CycleTime),0)                      
        -Sum(isnull(c.Qty,0))LotSize,a.Branchid,a.Compid,12 as nn                        
                                
    From PPC_QuickProductionplan_Dtl a                          
                      
    Left Outer Join BOM_ItemwiseMachinewiseCycleTime b                           
    On b.ItemCode=a.StageCode and b.MachineCode=a.MachineCode and b.Branchid=a.Branchid and b.Compid=a.Compid                           
                           
    Left outer join QC_Inspection_Criteria c                           
    On c.RefNo=a.DocNo and c.RefDate=a.DocDate and c.RefType=a.DocType and c.MachineCode=a.MachineCode and c.ItemCode=a.StageCode                          
        and c.Branchid=a.Branchid and c.Compid=a.Compid and c.Finyear = a.Finyear                       
        and c.TobeEnterTime between dateadd(n,-(@PatrolDuration-1),@MaxTime) and @MaxTime                       
        /*and CriteriaCode not in (Select Case when c1.ItemCode=a.StageCode then 0 else 20 end from QC_Inspection_Criteria c1                      
                            Where c1.RefNo=c.RefNo and c1.RefDate=c.RefDate and c1.RefType=c.RefType and c1.MachineCode=c.MachineCode                       
                            and c1.ItemCode=c.ItemCode and c1.Branchid=c.Branchid and c1.Compid=c.Compid                       
                            and c1.TobeEnterTime between dateadd(n,-(@PatrolDuration-1),@MaxTime) and @MaxTime and c1.CriteriaCode=20) */                           
    Left outer join (Select RefType,RefNo,RefDate,ItemCode,MachineCode,Starttime,Branchid,Compid,Type,Sum(Qty)Qty                       
                    From QC_Inspection_Criteria Where Type='C'                       
                    Group by RefType,RefNo,RefDate,ItemCode,MachineCode,Starttime,Branchid,Compid,Type)d                          
    On d.RefNo=a.DocNo and d.RefDate=a.DocDate and d.RefType=a.DocType and d.ItemCode=a.StageCode and d.MachineCode=a.MachineCode                           
    and d.Starttime=a.Starttime and d.Branchid=a.Branchid and d.Compid=a.Compid and c.Finyear = a.Finyear                           
                           
    Left Outer Join Inv_Material_Master e                       
    On e.ItemCode=a.StageCode and e.BranchID=a.BranchID and e.CompID=a.CompID                          
                      
    Left outer join Qc_Inspection_Hdr f                            
    On a.DocType=f.RefType and a.DocNo=f.RefNo and A.DocDate = f.RefDate and f.InspectionTypeCode=@PatrolCode                       
    and a.Starttime=f.Starttime And A.StageCode = f.ItemCode And A.MachineCode = f.MachineCode                       
    and f.BranchID=a.BranchID and f.CompID=a.CompID                      
                          Left Outer Join Inv_Uom_Master g                       
    On g.Code=e.Uom and g.Branchid=e.Branchid and g.Compid=e.Compid                        
                           
    Where a.DocNo=@PlanNo and a.DocDate=@PlanDate and a.DocType=@PlanType and a.Shift = @ShiftCode and a.Status<>0                 
    and a.StartTime<@MaxTime and a.OperationName<>'SETTING' and a.ShortClose=0 and isnull(f.CompletedStatus,0)=0                        
    and a.RevisionNo=(Select Max(RevisionNo) From PPC_QuickProductionplan_Dtl a1                           
        Where a.DocNo = a1.DocNo and a.DocType = a1.DocType and a.DocDate = a1.DocDate and a1.StartDate = a.StartDate and a1.StageCode=a.StageCode and a1.MachineCode=a.MachineCode           
    /*and a1.Starttime=a.Starttime*/ and a1.Shift = a.Shift and a.Branchid=a1.BranchID and a.Compid=a1.CompID and a.Finyear = a1.Finyear)                           
                      
    and Not Exists (Select * from QC_Inspection_Criteria g Where g.RefNo=a.DocNo and g.RefDate=a.DocDate and g.RefType=a.DocType and g.ItemCode=a.StageCode and g.MachineCode=a.MachineCode and g.Starttime=a.Starttime and g.Branchid=a.Branchid            
          
    and g.Compid=a.Compid and CompletedStatus=1)                          
                      
    Group by a.DocType,a.DocNo,a.DocDate,a.StageCode, e.ItemDescription, a.MachineCode, a.WorkOrderType, a.WorkOrderNo,                       
    a.WorkOrderDate, a.Date1, g.sdesc, b.CycleTime, a.StartTime, a.EndTime,d.Qty ,a.Branchid,a.Compid                          
                      
    Having Round(((Case when a.Starttime<=dateadd(n,-(@PatrolDuration-1),@MaxTime) then @PatrolDuration                       
    Else (@PatrolDuration-datediff(n,dateadd(n,-(@PatrolDuration-1),@MaxTime),a.Starttime)) end *60)/b.CycleTime),0)                      
    > Sum(isnull(c.Qty,0))+1 and a.Date1>Sum(isnull(d.Qty,0))                          
                      
    Select @sEOF=isnull(count(*),0) From @Item     --Record Not then Time To Add                          
    If @sEOF='0'                          
        Begin                          
            Select @MaxTime = DateAdd(n, @PatrolDuration, @MaxTime)                          
            goto eLoopFirst                          
        End                   
   End                        
 Else                          
   Begin                       
                           
    Insert into @Item                       
                             
    Select a.DocType,a.DocNo,a.DocDate,a.StageCode, e.ItemDescription, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate,                      
     Date1, g.sdesc as UOMDesc, b.CycleTime, a.StartTime, a.EndTime,@EndTime as MaxTime, '' as DrawingCode,                           
     Case when Exists (Select Distinct ItemCode From Qc_Inspection_MAster f                       
     Where f.InspectionTypeCode=@PatrolCode and f.Inspect=1 and f.ItemCode=a.StageCode) then 1 else 0 end Status,                          
     round(((Case when a.Starttime<=dateadd(n,-(@PatrolDuration-1),@MaxTime) then @PatrolDuration else                       
     (@PatrolDuration-datediff(n,dateadd(n,-(@PatrolDuration-1),@MaxTime),a.Starttime)) end  *60)/b.CycleTime),0)                      
     -Sum(isnull(c.Qty,0))LotSize,a.Branchid,a.Compid,1 as nn                       
                              
    From PPC_QuickProductionplan_Dtl a                          
                      
    Left Outer Join BOM_ItemwiseMachinewiseCycleTime b                           
    On b.ItemCode=a.StageCode and b.MachineCode=a.MachineCode and b.Branchid=a.Branchid and b.Compid=a.Compid                           
                           
    Left outer join QC_Inspection_Criteria c                           
    On c.RefNo=a.DocNo and c.RefDate=a.DocDate and c.RefType=a.DocType and c.MachineCode=a.MachineCode and c.ItemCode=a.StageCode                          
        and c.Branchid=a.Branchid and c.Compid=a.Compid and c.Finyear = a.Finyear                       
        and c.TobeEnterTime between dateadd(n,-(@PatrolDuration-1),@MaxTime) and @MaxTime                       
        and CriteriaCode not in (Select Case when c1.ItemCode=a.StageCode then 0 else 20 end from QC_Inspection_Criteria c1                      
                            Where c1.RefNo=c.RefNo and c1.RefDate=c.RefDate and c1.RefType=c.RefType and c1.MachineCode=c.MachineCode                       
                            and c1.ItemCode=c.ItemCode and c1.Branchid=c.Branchid and c1.Compid=c.Compid                       
                            and c1.TobeEnterTime between dateadd(n,-(@PatrolDuration-1),@MaxTime) and @MaxTime and c1.CriteriaCode=20)                            
    Left outer join (Select RefType,RefNo,RefDate,ItemCode,MachineCode,Starttime,Branchid,Compid,Type,Sum(Qty)Qty                       
                    From QC_Inspection_Criteria                          
                    Where Type='C'                       
  Group by RefType,RefNo,RefDate,ItemCode,MachineCode,Starttime,Branchid,Compid,Type)d                          
    On d.RefNo=a.DocNo and d.RefDate=a.DocDate and d.RefType=a.DocType and d.ItemCode=a.StageCode and d.MachineCode=a.MachineCode                           
    and d.Starttime=a.Starttime and d.Branchid=a.Branchid and d.Compid=a.Compid and c.Finyear = a.Finyear                           
                           
    Left Outer Join Inv_Material_Master e                       
    On e.ItemCode=a.StageCode and e.BranchID=a.BranchID and e.CompID=a.CompID                          
                      
    Left outer join Qc_Inspection_Hdr f                            
    On a.DocType=f.RefType and a.DocNo=f.RefNo and A.DocDate = f.RefDate and f.InspectionTypeCode=@PatrolCode                       
    and a.Starttime=f.Starttime And A.StageCode = f.ItemCode And A.MachineCode = f.MachineCode                       
    and f.BranchID=a.BranchID and f.CompID=a.CompID                      
                          
    Left Outer Join Inv_Uom_Master g                       
    On g.Code=e.Uom and g.Branchid=e.Branchid and g.Compid=e.Compid                              
                           
    Where a.DocNo=@PlanNo and a.DocDate=@PlanDate and a.DocType=@PlanType and a.Status<>0 and a.StartTime<@MaxTime                       
    and a.OperationName<>'SETTING' and a.ShortClose=0 and isnull(f.CompletedStatus,0)=0                        
    and a.RevisionNo=(Select Max(RevisionNo) From PPC_QuickProductionplan_Dtl a1                           
        Where a.DocNo = a1.DocNo and a.DocType = a1.DocType and a.DocDate = a1.DocDate and a1.StartDate = a.StartDate and a1.StageCode=a.StageCode and a1.MachineCode=a.MachineCode           
    /*and a1.Starttime=a.Starttime*/ and a1.Shift = a.Shift and a.Branchid=a1.BranchID and a.Compid=a1.CompID and a.Finyear = a1.Finyear)                    
                        
      and Not Exists (Select * from QC_Inspection_Criteria g Where g.RefNo=a.DocNo and g.RefDate=a.DocDate and g.RefType=a.DocType                           
      and g.ItemCode=a.StageCode and g.MachineCode=a.MachineCode and g.Starttime=a.Starttime and g.Branchid=a.Branchid                       
      and g.Compid=a.Compid and CompletedStatus=1)                         
                          
     Group by a.DocType,a.DocNo,a.DocDate,a.StageCode, e.ItemDescription, a.MachineCode, a.WorkOrderType, a.WorkOrderNo,                       
     a.WorkOrderDate, a.Date1, g.sdesc, b.CycleTime, a.StartTime, a.EndTime,d.Qty ,a.Branchid,a.Compid                          
                           
     Having a.Date1>Sum(isnull(d.Qty,0))                          
  End                         
                           
 RETURN                          
END   
GO

/****** Object:  UserDefinedFunction [dbo].[fn_Qc_LogTime]    Script Date: 17/06/2026 11:38:52 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_Qc_LogTime] (@PlanType varchar(3), @PlanNo int, @PlanDate datetime, @ShiftCode varchar(3),@ItemCode varchar(20),@MachineCode varchar(20),@StartTime datetime, @InsType varchar(3), @InsNo int, @InsDate datetime,@PatrolCode int, @BranchID varchar(3), @CompID varchar(3))  

RETURNS @Item TABLE
	(PreviousTime	datetime,
	LogTime	datetime,
	LogLagTime	datetime
	)

AS  

BEGIN 

	Declare @MaxTime  datetime
	Declare @LagTime datetime
	Declare @PreviousTime datetime


	if exists(select * from QC_Inspection_Criteria where InspectionType=@InsType and InspectionNo=@InsNo and InspectionDate=@InsDate )
		begin 
			select @MaxTime=max(TobeEntertime) from QC_Inspection_Criteria where InspectionType=@InsType and InspectionNo=@InsNo and InspectionDate=@InsDate and Branchid=@Branchid and Compid=@Compid 
			
			Select @Previoustime=@MaxTime
			Select @LagTime=Dateadd(n,(select top 1 convert(int,Val) from COm_Inspection_Option_Dtl where Code=2 and InspectionTypeCode=@PatrolCode),@MaxTime)
			Select @MaxTime=Dateadd(n,(select top 1 convert(int,Val) from COm_Inspection_Option_Dtl where Code=3 and InspectionTypeCode=@PatrolCode),@LagTime)
		end 
	else
		begin 
			select top 1 @MaxTime=Logtime from QC_Logtime where convert(varchar,Logtime,120)>convert(varchar(10),Logtime,120)+' '+convert(varchar(8),(select top 1 a.Starttime from PPC_QuickProductionPlan_Dtl a where DocType=@PlanType
			and DocNo=@PlanNo and DocDate=@PlanDate and Branchid=@Branchid and Compid=@Compid and StageCode=@ItemCode and MachineCode=@MachineCode and Starttime=@StartTime
			and a.RevisionNo=(Select Max(RevisionNo) From PPC_QuickProductionplan_Dtl  
						Where a.DocNo = DocNo and a.DocType = DocType and a.DocDate = DocDate and a.StartDate=StartDate 
						and a.StageCode=StageCode and a.MachineCode=MachineCode and a.OperationName=OperationName and a.WorkOrderNo=WorkOrderNo 
						and a.Branchid=BranchID and a.Compid=CompID)
						),108)
			 order by Logtime

			Select @LagTime=@MaxTime
			Select @Previoustime=Dateadd(n,(select top 1 -convert(int,Val) from COm_Inspection_Option_Dtl where Code=2 and InspectionTypeCode=@PatrolCode),@MaxTime)
			Select @MaxTime=Dateadd(n,(select top 1 convert(int,Val) from COm_Inspection_Option_Dtl where Code=3 and InspectionTypeCode=@PatrolCode),@LagTime)
		end
	

		
		insert into @Item select @Previoustime,@LagTime,@MaxTime

	Return

END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_QC_PatrolInspectionItemSelect]    Script Date: 17/06/2026 11:38:52 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_QC_PatrolInspectionItemSelect] (@PlanType varchar(3), @PlanNo int, @PlanDate datetime,   
 @ShiftCode varchar(3), @BranchID varchar(3), @CompID varchar(3))            
RETURNS @Item TABLE      
(	DocType  varchar(3),      
	DocNo   int,      
	DocDate  Datetime,      
	StageCode  varchar(20),      
	ItemDescription  varchar(50),      
	MachineCode  varchar(20),         
	WorkOrderType  varchar(3),      
	WorkOrderNo  int,      
	WorkOrderDate  datetime,      
	UOMDesc  varchar(5),      
	CycleTime  float,      
	StartTime  datetime,      
	EndTime  datetime,      
	ToBeEnterTime   datetime,      
	Status   varchar(10),      
	DrawingCode  varchar(20),      
	Branchid  varchar(3),      
	Compid   varchar(3)  
)          
AS            
BEGIN       
      
 Declare @PatrolCode int      
 Declare @PatrolDuration int        
 Declare @sEOF int       
      
 Select @PatrolCode=8;  --Inspection Code for Patrol Inspection Type
 
 Select @PatrolDuration=a.Val From COM_Inspection_Option_Dtl a 
 Where a.InspectionTypeCode=@PatrolCode and a.Code=1		-- In Mintes      
      
 Declare @MaxTime datetime  --Last Entry Time for Current Shift      
 Declare @MaxTime1 datetime        
 Declare @ToBeEnterCount int  --To Be Entered Count from Production Plan      
 Declare @EnteredCount int  --Entered Count from Inspection Details      
 Declare @NewPatrolSetEntry bit  --Whether Pending Items or New Set      
 Declare @EndTime as datetime  --Shift end  time      
      
 Begin      
  Select @MaxTime=DateAdd(n, @PatrolDuration, a.StartDate+convert(varchar(5),b.StartTime,108)), 
		@EndTime=DateAdd(n,b.ShiftMinutes, a.StartDate+convert(varchar(5),b.StartTime,108))       
  From (Select Top 1 a1.StartDate, a1.BranchID, a1.CompID      
				From PPC_QuickProductionplan_Dtl a1       
				Where a1.DocNo=@PlanNo and a1.DocDate=@PlanDate and a1.DocType=@PlanType 
					and a1.BranchID=@BranchID and a1.CompID=@CompID      
   ) a      
  Left Outer Join PPC_Shift_Master b 
		On a.BranchID=b.BranchID and a.CompID=b.CompID      
  Where b.ShiftCode=@ShiftCode      
      
  /* To Be implemented  
  Select @MaxTime1=dateadd(n,-@PatrolDuration,a.MaxTime) From QC_Maxtime_Tmp a  
 Where a.Docno=@PlanNo and a.DocDate=@PlanDate and a.DocType=@PlanType */  
  
 Select @MaxTime1=a.MaxTime From Qc_Maxtime_Tmp a  
 Where a.DocNo=@PlanNo and a.DocDate=@PlanDate and a.DocType=@PLanType 
      
  If isnull(@Maxtime1,0)<>0       
  Begin  
    Select @Maxtime=@Maxtime1          
  End  
 End        
      
eLoopFirst:       
	If @EndTime>= @MaxTime      
   Begin      
	  /* Insert Data Into Temp Table */
    Insert into @Item      

    Select Distinct a.DocType,a.DocNo,a.DocDate, a.StageCode, b.ItemDescription, a.MachineCode, a.WorkOrderType, 
			a.WorkOrderNo, a.WorkOrderDate, b.UOMDesc, c.CycleTime, a.StartTime, a.EndTime,@MaxTime, 'Current',
			d.DrawingCode, a.BranchID, a.CompID
		From PPC_QuickProductionplan_Dtl a       
     Left Outer Join Material_Master b 
			On a.StageCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID      
     Left Outer Join BOM_ItemwiseMachinewiseCycleTime c 
			On a.StageCode=c.ItemCode and a.MachineCode=c.MachineCode and a.BranchID=c.BranchID and a.CompID=c.CompID       
     Left Outer Join BOM_Drawing_Master d 
			On a.StageCode=d.ItemCode and Type='O' and a.BranchID=d.BranchID and a.CompID=d.CompID      
     Left Outer Join QC_Inspection_Hdr e 
			On a.DocType=e.RefType and a.DocNo=e.RefNo and a.DocDate=e.RefDate and e.MachineCode=a.MachineCode     
				and e.ItemCode=a.StageCode and e.Starttime=a.Starttime and a.BranchID=e.BranchID and a.CompID=e.CompID       
				and e.InspectionTypeCode=@PatrolCode       
     Where a.DocNo=@PlanNo and a.DocDate=@PlanDate and a.DocType=@PlanType and a.Shift=@ShiftCode and a.BranchID=@BranchID and a.CompID=@CompID      
      --and (@MaxTime between a.StartTime and dateadd(n,59,a.Endtime))   
			-- (@MaxTime between  a.StartTime and a.Endtime)  /* This MaxTime between statement   
			and ((@MaxTime>a.StartTime and @MaxTime<=a.Endtime) or (a.StartTime<@MaxTime and Datediff(minute,a.StartTime,a.EndTime)<@PatrolDuration))     
			and a.OperationName<>'SETTING'	--between a.StartTime and a.EndTime
			and a.RevisionNo=(Select Max(q1.RevisionNo) From PPC_QuickProductionplan_Dtl q1      
												Where q1.DocNo=a.DocNo and q1.DocType=a.DocType and q1.DocDate=a.DocDate 
													and q1.BranchID=a.BranchID and q1.CompID=a.CompID and q1.Finyear=a.Finyear    
											 )     
      and Not Exists (Select * From QC_Inspection_Hdr g 
											Left Outer Join QC_Inspection_Dtl h 
												On g.InspectionNo=h.InspectionNo and g.InspectionDate=h.InspectionDate     
													and g.InspectionType=h.InspectionType and g.BranchID=h.BranchID and g.CompID=h.CompID        
											Where g.RefNo=a.DocNo and g.RefDate=a.DocDate and g.RefType=a.DocType 
												and g.MachineCode=a.MachineCode --and g.Starttime=a.Starttime      
												and g.BranchID=a.BranchID and g.CompID=a.CompID and h.ToBeEnterTime=@MaxTime      
           )      
      and Exists (Select * From QC_Inspection_Master i1 
									Where i1.InspectiontypeCode=@PatrolCode and i1.ItemCode=a.StageCode 
										and i1.Inspect=1 and i1.Branchid=@Branchid and i1.Compid=@Compid 
								)      
      and (e.CompletedDate Is Null) and a.Status<>0       
                   
    Select @sEOF=IsNull(count(*),0) From @Item     --Record Not then Time To Add      
    If IsNull(@sEOF,0)=0      
      Begin      
       Select @MaxTime=DateAdd(n, @PatrolDuration, @MaxTime);      
       goto eLoopFirst      
      End        
     Else      
      Begin      
       Insert into @Item  --Non Completed Items      
        Select Distinct a.DocType,a.DocNo,a.DocDate, a.StageCode, b.ItemDescription, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate,       
         b.UOMDesc, c.CycleTime, a.StartTime, a.EndTime,@MaxTime,'Balance' ,d.DrawingCode,@Branchid,@Compid      
        from      
         (Select Distinct a.DocType,a.DocNo,a.DocDate,a.StageCode, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate, a.StartTime, a.EndTime, @BranchID as BranchID, @CompID as CompID      
         from      
          (Select Distinct a.DocType,a.DocNo,a.DocDate,a.StageCode, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate, a.StartTime, a.EndTime, Sum(Date1) as PlannedQty      
          from PPC_QuickProductionplan_Dtl a Where a.DocNo=@PlanNo and a.DocDate=@PlanDate and a.DocType=@PlanType and a.Shift=@ShiftCode and a.OperationName<>'SETTING' and a.BranchID=@BranchID and a.CompID=@CompID and  a.Status<>0      
          and a.RevisionNo=(Select Max(RevisionNo) From PPC_QuickProductionplan_Dtl        
            Where a.DocNo = DocNo and a.DocType = DocType and a.DocDate = DocDate and a.Branchid=BranchID and a.Compid=CompID      
            )       
          Group By  a.DocType,a.DocNo,a.DocDate, a.StageCode, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate, a.StartTime, a.EndTime      
          ) a      
         Left Outer Join      
          (Select g.ItemCode, g.MachineCode, Sum(j.Qty) as CompletedQty from QC_Inspection_Hdr g       
          Left Outer Join (Select * from QC_Inspection_Criteria Where Type='C' or (Type in('R','LR') and CriteriaCode=14)) j      
           On g.InspectionNo=j.InspectionNo and g.InspectionDate=j.InspectionDate and g.InspectionType=j.InspectionType and g.ItemCode=j.ItemCode and g.MachineCode=j.MachineCode and g.Branchid=j.Branchid and g.Compid=j.Compid         
          Where g.RefNo=@PlanNo and g.RefDate=@PlanDate and g.RefType=@PlanType and g.Branchid=@BranchID and g.Compid=@CompID        
          Group by g.ItemCode, g.MachineCode) b On a.StageCode=b.ItemCode and a.MachineCode=b.MachineCode      
         Where isNull(a.PlannedQty, 0) > isNull(b.CompletedQty, 0)      
         ) a      
         Left Outer Join Material_Master b On a.StageCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID      
         Left Outer Join BOM_ItemwiseMachinewiseCycleTime c on a.StageCode=c.ItemCode and a.MachineCode=c.MachineCode and a.Branchid=c.Branchid and a.Compid=c.Compid       
         Left Outer Join BOM_Drawing_Master d on a.StageCode=d.ItemCode and Type='O' and a.Branchid=d.Branchid and a.Compid=d.Compid      
         left outer join QC_Inspection_Hdr e on a.DocType=e.RefType and a.DocNo=e.RefNo and a.DocDate=e.RefDate and e.MachineCode=a.MachineCode and e.ItemCode=a.StageCode     
     and e.Starttime=a.Starttime and a.Branchid=e.Branchid and a.Compid=e.Compid and  e.InspectionTypeCode=@PatrolCode       
              
         Where Not Exists (Select * from @Item n       
           Where a.StageCode=n.StageCode and a.MachineCode=n.MachineCode and a.StartTime=n.StartTime and a.EndTime=n.EndTime       
            and a.WorkOrderType=n.WorkOrderType and a.WorkOrderNo=n.WorkOrderNo and a.WorkOrderDate=n.WorkOrderDate) and isnull(e.CompletedStatus,0)=0 and e.InspectionType is Not NUll      
         and Not Exists (Select *  from QC_Inspection_Hdr g       
           Left Outer Join QC_Inspection_Dtl h On g.InspectionNo=h.InspectionNo and g.InspectionDate=h.InspectionDate and g.InspectionType=h.InspectionType and g.Branchid=h.Branchid and g.Compid=h.Compid        
           Where g.RefNo=a.DocNo and g.RefDate=a.DocDate and g.RefType=a.DocType  and g.MachineCode=a.MachineCode and g.Starttime=a.Starttime      
            and g.Branchid=a.BranchID and g.Compid=a.CompID and h.ToBeEnterTime=@MaxTime) and CompletedDate is null       
       End        
   End      
  Else        
   Begin      
       Insert into @Item  --Non Completed Items      
        Select Distinct a.DocType,a.DocNo,a.DocDate, a.StageCode, b.ItemDescription, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate,       
         b.UOMDesc, c.CycleTime, a.StartTime, a.EndTime,@MaxTime,'Balance' ,d.DrawingCode,@Branchid,@Compid      
        from      
         (Select Distinct a.DocType,a.DocNo,a.DocDate,a.StageCode, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate, a.StartTime, a.EndTime, @BranchID as BranchID, @CompID as CompID      
         from      
          (Select Distinct a.DocType,a.DocNo,a.DocDate,a.StageCode, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate, a.StartTime, a.EndTime, Sum(Date1) as PlannedQty      
          from PPC_QuickProductionplan_Dtl a Where a.DocNo=@PlanNo and a.DocDate=@PlanDate and a.DocType=@PlanType and a.Shift=@ShiftCode and a.OperationName<>'SETTING' and a.BranchID=@BranchID and a.CompID=@CompID and  a.Status<>0      
          and a.RevisionNo=(Select Max(RevisionNo) From PPC_QuickProductionplan_Dtl        
            Where a.DocNo = DocNo and a.DocType = DocType and a.DocDate = DocDate and a.Branchid=BranchID and a.Compid=CompID      
            )       
          Group By  a.DocType,a.DocNo,a.DocDate,a.StageCode, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate, a.StartTime, a.EndTime      
          ) a      
         Left Outer Join      
          (Select g.ItemCode, g.MachineCode, Sum(j.Qty) as CompletedQty from QC_Inspection_Hdr g       
          Left Outer Join (Select * from QC_Inspection_Criteria Where Type='C' or (Type in('R','LR') and CriteriaCode=14)) j      
           On g.InspectionNo=j.InspectionNo and g.InspectionDate=j.InspectionDate and g.InspectionType=j.InspectionType and g.ItemCode=j.ItemCode and g.MachineCode=j.MachineCode and g.Branchid=j.Branchid and g.Compid=j.Compid         
          Where g.RefNo=@PlanNo and g.RefDate=@PlanDate and g.RefType=@PlanType and g.Branchid=@BranchID and g.Compid=@CompID        
          Group by g.ItemCode, g.MachineCode) b On a.StageCode=b.ItemCode and a.MachineCode=b.MachineCode      
         Where isNull(a.PlannedQty, 0) > isNull(b.CompletedQty, 0)      
         ) a      
         Left Outer Join Material_Master b On a.StageCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID      
         Left Outer Join BOM_ItemwiseMachinewiseCycleTime c on a.StageCode=c.ItemCode and a.MachineCode=c.MachineCode and a.Branchid=c.Branchid and a.Compid=c.Compid       
         Left Outer Join BOM_Drawing_Master d on a.StageCode=d.ItemCode and Type='O' and a.Branchid=d.Branchid and a.Compid=d.Compid      
         left outer join QC_Inspection_Hdr e on a.DocType=e.RefType and a.DocNo=e.RefNo and a.DocDate=e.RefDate and e.MachineCode=a.MachineCode and e.ItemCode=a.StageCode     
     and e.Starttime=a.Starttime and a.Branchid=e.Branchid and a.Compid=e.Compid and  e.InspectionTypeCode=@PatrolCode      
              
         Where Not Exists (Select * from @Item n       
           Where a.StageCode=n.StageCode and a.MachineCode=n.MachineCode and a.StartTime=n.StartTime and a.EndTime=n.EndTime       
            and a.WorkOrderType=n.WorkOrderType and a.WorkOrderNo=n.WorkOrderNo and a.WorkOrderDate=n.WorkOrderDate)  
       and isnull(e.CompletedStatus,0)=0 and e.InspectionType is Not NUll      
            and Not Exists (Select *  from QC_Inspection_Hdr g                  
      Left Outer Join QC_Inspection_Dtl h On g.InspectionNo=h.InspectionNo and g.InspectionDate=h.InspectionDate and g.InspectionType=h.InspectionType     
      and g.Branchid=h.Branchid and g.Compid=h.Compid        
           Where g.RefNo=a.DocNo and g.RefDate=a.DocDate and g.RefType=a.DocType  and g.MachineCode=a.MachineCode and g.Starttime=a.Starttime      
        and g.Branchid=a.BranchID and g.Compid=a.CompID and h.ToBeEnterTime=@MaxTime) and CompletedDate is null       
       End          
 Return      
END  
GO

/****** Object:  UserDefinedFunction [dbo].[fn_QC_SetUpInspectionItemSelect]    Script Date: 17/06/2026 11:38:52 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_QC_SetUpInspectionItemSelect] (@PlanType varchar(3), @PlanNo int, @PlanDate datetime, 
	@ShiftCode varchar(3), @BranchID varchar(3), @CompID varchar(3))          
RETURNS @Item TABLE    
(	DocType  varchar(3),    
	DocNo   int,    
	DocDate  Datetime,    
	StageCode  varchar(20),    
	ItemDescription  varchar(50),    
	MachineCode  varchar(20),       
	WorkOrderType  varchar(3),    
	WorkOrderNo  int,    
	WorkOrderDate  datetime,    
	UOMDesc  varchar(5),    
	CycleTime  float,    
	StartTime  datetime,    
	EndTime  datetime,    
	ToBeEnterTime   datetime,    
	Status   varchar(10),    
	DrawingCode  varchar(20),    
	Branchid  varchar(3),    
	Compid   varchar(3)
)        
AS      
BEGIN     
    
 Declare @PatrolCode int    
 Declare @PatrolDuration int      
 Declare @sEOF int     
    
 Select @PatrolCode=9;  --Inspection Code for Setup Inspection Type    

 Select @PatrolDuration=a.Val FROM COM_Inspection_Option_Dtl a
 Where a.InspectionTypeCode=@PatrolCode and a.Code=1	-- In Mintes    
    
 Declare @MaxTime datetime  --Last Entry Time for Current Shift    
 Declare @ToBeEnterCount int  --To Be Entered Count from Production Plan    
 Declare @EnteredCount int  --Entered Count from Inspection Details    
 Declare @NewPatrolSetEntry bit  --Whether Pending Items or New Set    
 Declare @EndTime as datetime  --Shift end  time    
 
 Begin    
  Select @MaxTime=DateAdd(n, @PatrolDuration, a.StartDate+convert(varchar(5),b.StartTime,108)), 
		@EndTime=DateAdd(n,b.ShiftMinutes, a.StartDate+convert(varchar(5),b.StartTime,108))     
  From ( Select Top 1 a1.StartDate, a1.BranchID, a1.CompID    
				From PPC_QuickProductionplan_Dtl a1     
				Where a1.DocNo=@PlanNo and a1.DocDate=@PlanDate and a1.DocType=@PlanType 
					and a1.BranchID=@BranchID and a1.CompID=@CompID    
   ) a    
  Left Outer Join PPC_Shift_Master b 
		On a.BranchID=b.BranchID and a.CompID=b.CompID    
  Where b.ShiftCode=@ShiftCode        
 End    
     
eLoopFirst:     
	If @EndTime>=@MaxTime    
   Begin    
		/* Insert Data Into Temp Table */		
		Insert Into @Item    

		Select Distinct a.DocType,a.DocNo,a.DocDate,a.StageCode, b.ItemDescription, a.MachineCode, a.WorkOrderType, 
			a.WorkOrderNo, a.WorkOrderDate, b.UOMDesc, c.CycleTime, a.StartTime, a.EndTime,@MaxTime,'Current', 
			d.DrawingCode, a.BranchID, a.CompID 
		From PPC_QuickProductionplan_Dtl a     
    Left Outer Join Material_Master b 
			On a.StageCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID    
    Left Outer Join BOM_ItemwiseMachinewiseCycleTime c 
			On a.StageCode=c.ItemCode and a.MachineCode=c.MachineCode and a.BranchID=c.BranchID and a.CompID=c.CompID     
    Left Outer Join BOM_Drawing_Master d 
			On a.StageCode=d.ItemCode and Type='O' and a.BranchID=d.BranchID and a.CompID=d.CompID    
    Left Outer Join QC_Inspection_Hdr e 
			On a.DocType=e.RefType and a.DocNo=e.RefNo and a.DocDate=e.RefDate and e.MachineCode=a.MachineCode 
				and e.ItemCode=a.StageCode and e.Starttime=a.Starttime and a.BranchID=e.BranchID and a.CompID=e.CompID 
				and e.InspectionTypeCode=@PatrolCode    
    Where a.DocNo=@PlanNo and a.DocDate=@PlanDate and a.DocType=@PlanType and a.Shift=@ShiftCode 
			--and a.EndTime<=@MaxTime  
			and (@MaxTime>a.StartTime and @MaxTime<=a.Endtime)
			and a.OperationName='SETTING' and a.BranchID=@BranchID and a.CompID=@CompID
			and a.RevisionNo=(Select Max(q1.RevisionNo) From PPC_QuickProductionplan_Dtl q1      
												Where q1.DocNo=a.DocNo and q1.DocType=a.DocType and q1.DocDate=a.DocDate 
													and q1.BranchID=a.BranchID and q1.CompID=a.CompID and q1.Finyear=a.Finyear    
											) 
			and Not Exists (Select * From Qc_Inspection_Hdr e     
             Left Outer Join Qc_Inspection_Dtl b 
							On b.InspectionType=e.InspectionType and b.InspectionNo=e.InspectionNo    
								and b.InspectionDate=e.InspectionDate and b.BranchID=e.BranchID and b.CompID=e.CompID    
              Where e.RefNo=a.DocNo and e.RefDate=a.DocDate	and e.RefType=a.DocType		-- And A.StageCode = e.ItemCode     
								and e.MachineCode=a.MachineCode and e.BranchID=a.BranchID and e.CompID=a.CompID 
								and e.InspectionTypeCode=@PatrolCode and b.ToBeEnterTime=@MaxTime)    
			and Exists (Select * From QC_Inspection_Master i1 
									Where i1.InspectiontypeCode=@PatrolCode and i1.Inspect=1 and i1.ItemCode=a.StageCode 
										and i1.BranchID=@BranchID and i1.CompID=@CompID
								)     
			and (e.CompletedDate Is Null) and a.Status<>0  and IsNull(e.SetupApprovel,1)=1 
			and a.StageCode In(Select Distinct ItemCode From Qc_Inspection_MAster e 
													Where e.InspectionTypeCode=@PatrolCode and e.Inspect=1
											 )    
    
    Select @sEOF=IsNull(count(*),0) From @Item     --Record Not then Time To Add    
    If IsNull(@sEOF,0)=0    
     begin    
       Select @MaxTime=DateAdd(n, @PatrolDuration, @MaxTime);    
       goto eLoopFirst    
    End     
		Else    
     Begin    
       Insert into @Item -- Start Setting time     
        Select Distinct a.DocType,a.DocNo,a.DocDate,a.StageCode, b.ItemDescription, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate,     
         b.UOMDesc, c.CycleTime, a.StartTime, a.EndTime,@MaxTime,'Later', d.DrawingCode,a.Branchid,a.Compid    
        from PPC_QuickProductionplan_Dtl a     
        Left Outer Join Material_Master b On a.StageCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID    
        Left Outer Join BOM_ItemwiseMachinewiseCycleTime c on a.StageCode=c.ItemCode and a.MachineCode=c.MachineCode and a.Branchid=c.Branchid and a.Compid=c.Compid     
        Left Outer Join BOM_Drawing_Master d on a.StageCode=d.ItemCode and Type='O' and a.Branchid=d.Branchid and a.Compid=d.Compid    
        left outer join QC_Inspection_Hdr e on a.DocType=e.RefType and a.DocNo=e.RefNo and a.DocDate=e.RefDate and e.MachineCode=a.MachineCode and e.ItemCode=a.StageCode    
      and e.Starttime=a.Starttime and a.Branchid=e.Branchid and a.Compid=e.Compid  and e.InspectionTypeCode=@PatrolCode    
            Where a.DocNo=@PlanNo and a.DocDate=@PlanDate and a.DocType=@PlanType and a.Shift=@ShiftCode and a.BranchID=@BranchID and a.CompID=@CompID and a.OperationName='SETTING'    
         and a.StartTime<=@MaxTime     
          and a.RevisionNo=(Select Max(RevisionNo) From PPC_QuickProductionplan_Dtl      
            Where a.DocNo = DocNo and a.DocType = DocType and a.DocDate = DocDate and a.Branchid=BranchID and a.Compid=CompID    
            )     
         and not Exists (Select * from Qc_Inspection_Hdr e     
                 left outer join Qc_Inspection_Dtl b on b.InspectionType=e.InspectionType and b.InspectionNo=e.InspectionNo    
                 and b.InspectionDate=e.InspectionDate and b.Branchid=e.Branchid and b.Compid=e.Compid    
                  Where A.DocType = e.RefType And A.DocNo = e.RefNo And A.DocDate = e.RefDate-- And A.StageCode = e.ItemCode     
                 and a.MachineCode=e.MachineCode and a.Branchid=e.Branchid and a.Compid=e.Compid  and  e.InspectionTypeCode=@PatrolCode    
            and b.ToBeEnterTime=@MaxTime)    
         and Exists (Select *     
           from QC_Inspection_Master  where InspectiontypeCode=@PatrolCode and Inspect=1 and ItemCode=a.StageCode and Branchid=@Branchid and Compid=@Compid       
              )     
         and e.CompletedDate is null   and a.Status<>0  and isnull(e.SetupApprovel,1)=1 and a.StageCode  in (select Distinct ItemCode from  Qc_Inspection_MAster e where e.InspectionTypeCode=@PatrolCode and e.Inspect=1)    
        
         and Not Exists (Select * from @Item n     
            Where a.StageCode=n.StageCode and a.MachineCode=n.MachineCode and a.StartTime=n.StartTime and a.EndTime=n.EndTime     
            and a.WorkOrderType=n.WorkOrderType and a.WorkOrderNo=n.WorkOrderNo and a.WorkOrderDate=n.WorkOrderDate    
                    )     
         and isnull(e.CompletedStatus,0)=0 --and e.InspectionType is  NUll    
      End    
  End    
    
 Return        
END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_QC_Tray_PatrolStatus]    Script Date: 17/06/2026 11:38:52 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_QC_Tray_PatrolStatus] (@WorkingDate datetime,@Shift Varchar(3),@Cycletime float,@Qty  int,@BranchID varchar(3), @CompID varchar(3))  

RETURNS @RefTbl Table (	
			Qno int,
			ToolCode varchar(20),
			Description varchar(20)

		 ) 

 AS  

BEGIN 
	Declare @EnterLogQty int
	Declare @LogQty int
	Declare @QtyCnt int
	Declare @cnt int

	Select @cnt=1
	Select @LogQty=(60 * 30) / @Cycletime
	Select @QtyCnt=(60 * 30) / @Cycletime

	Select @EnterLogQty=DateDiff(n,(DateAdd(n,0,@WorkingDate+convert(varchar(5),StartTime,108))) , DateAdd(n,ShiftMinutes,@WorkingDate+convert(varchar(5),StartTime,108)))/30  
		from PPC_Shift_Master where ShiftCode=@Shift and BranchId =@BranchID and CompID =@CompID

	
		While @cnt<=@EnterLogQty and @QtyCnt<=@Qty
			Begin
				insert into @RefTbl
					Select @QtyCnt,'','PATROL'

					Select @QtyCnt=@QtyCnt+@LogQty
					Select @cnt=1+@cnt
			End

	Return

End
GO

