CREATE FUNCTION [dbo].[fn_QMS_CenterTable] (@DType varchar(3), @DNo int, @DDate datetime, @AsOnDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE
	(CCode	int,
	CDescp varchar(50),
	CSeq	int)


 AS  

BEGIN 
	Insert @RetTable
		select 100 as Code, 'Process Risk For' as Descp, 100 as Seq
		union  
		select 101 as Code, 'Company, System, Product, Interfaces' as Descp, 101 as Seq
		union  
		select Distinct Code+101 as Code, Process, Seq+101 as Seq from fn_QMS_ProcessAnalysis_Process(@AsOnDate,@BranchID,@CompID,@Finyear) a where a.EffStatus = 'Y' and a.PAType = @DType and a.PANo = @DNo and a.PADate = @DDate

		Update @RetTable Set CSeq=(Select Count(*) from @RetTable b Where b.CCode <= a.CCode) From @RetTable a

	Return 

END






GO

