GO



CREATE FUNCTION [dbo].[fn_QMS_LeftTable] (@DType varchar(3), @DNo int, @DDate datetime, @AsOnDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE
	(LCode	int,
	LDescp varchar(50),
	LSeq	int)


 AS  

BEGIN 
	Insert @RetTable
		select 100 as Code, 'Material Resources :' as Descp, 100 as Seq
		union 
		Select Distinct a.Code+100, a.MaterialResources, Seq+100 from fn_QMS_ProcessAnalysis_MR(@AsOnDate,@BranchID,@CompID,@Finyear) a where a.EffStatus = 'Y' and a.PAType = @DType and a.PANo = 1 and a.PADate = @DDate
		union 
		select 200 as Code, 'Inputs :' as Descp, 200 as Seq
		union 
		Select Distinct a.Code+200, a.Inputs, Seq+200 from fn_QMS_ProcessAnalysis_Inputs(@AsOnDate,@BranchID,@CompID,@Finyear) a where a.EffStatus = 'Y' and a.PAType = @DType and a.PANo = @DNo and a.PADate = @DDate
		union
		select 300 as Code, 'Process Indicators and Measures :' as Descp, 300 as Seq
		union 
		Select Distinct a.Code+300, a.ProcessIndicators, Seq+300 from fn_QMS_ProcessAnalysis_PIM(@AsOnDate,@BranchID,@CompID,@Finyear) a where a.EffStatus = 'Y' and a.PAType = @DType and a.PANo = @DNo and a.PADate = @DDate

		 Update @RetTable Set LSeq=(Select Count(*) from @RetTable b Where b.LCode <= a.LCode) From @RetTable a

	Return 

END






GO

