CREATE FUNCTION [dbo].[fn_QMS_RightTable] (@DType varchar(3), @DNo int, @DDate datetime, @AsOnDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE
	(RCode	int,
	RDescp varchar(50),
	RSeq	int)


 AS  

BEGIN 
	Insert @RetTable
		select 100 as Code, 'Human Resources :' as Descp, 100 as Seq
		union 
		Select Distinct a.Code+100, a.HR, Seq+100 from fn_QMS_ProcessAnalysis_HR(@AsOnDate,@BranchID,@CompID,@Finyear) a where a.EffStatus = 'Y' and a.PAType = @DType and a.PANo = @DNo and a.PADate = @DDate
		union 
		select 200 as Code, 'Outputs :' as Descp, 200 as Seq
		union 
		Select Distinct a.Code+200, a.Outputs, Seq+200 from fn_QMS_ProcessAnalysis_Outputs(@AsOnDate,@BranchID,@CompID,@Finyear) a where a.EffStatus = 'Y' and a.PAType = @DType and a.PANo = @DNo and a.PADate = @DDate
		union
		select 300 as Code, 'Documentation, Records, Tools :' as Descp, 300 as Seq
		union 
		Select Distinct a.Code+300, a.Documents, Seq+300 from fn_QMS_ProcessAnalysis_Doc(@AsOnDate,@BranchID,@CompID,@Finyear) a where a.EffStatus = 'Y' and a.PAType = @DType and a.PANo = @DNo and a.PADate = @DDate

		Update @RetTable Set RSeq=(Select Count(*) from @RetTable b Where b.RCode <= a.RCode) From @RetTable a

	Return 

END





GO

