/****** Object:  UserDefinedFunction [dbo].[fn_Rec_UpdateWtAvgRate]    Script Date: 17/06/2026 11:38:53 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_Rec_UpdateWtAvgRate] (@AsOnDate datetime,  @FinStart datetime, @BranchID varchar(3),  @CompID varchar(3),  @Finyear varchar(15))  

RETURNS @RetTable TABLE
	([ItemCode] [varchar] (20),	
	[Rate] [float],
	[BranchID] [varchar] (3),
	[CompID] [varchar] (3)
	)

 AS  

	BEGIN 
		
		Declare @ParentCode varchar(20)
		Declare @ItemCode varchar(20)
		Declare @Rate float
		Declare @RptDate datetime

		Select @RptDate = Convert(datetime, @AsOnDate, 111)

		Declare curParent Cursor for	

			Select distinct itemcode from dbo.fn_Pur_PurchaseOrder_Dtl (@AsOnDate ,  @RptDate ,  @BranchID ,  @CompID , @Finyear )
		
		Open curParent		

		FETCH NEXT FROM curParent into @ParentCode 		

		While @@Fetch_Status = 0

			Begin 

				Declare curItem Cursor For					
	
					   Select ItemCode, isNull(Rate,0) Rate From fn_BOM_ProductImplosion
	  					 (@ParentCode,  '',  @FinStart,  @RptDate,  @BranchID,  @CompID,  @Finyear)
			 
				Open curItem		
			
					FETCH NEXT FROM curItem into @ItemCode, @Rate 		
			
					While @@Fetch_Status = 0
	
						Begin
							--Update Inv_Material_Master Set Rate = @Rate
							--Where ItemCode = @ItemCode and BranchID = @BranchID and CompID = @CompID	
						
							FETCH NEXT FROM curItem into @ItemCode, @Rate
						End
						
					Close curItem
					Deallocate curItem

				FETCH NEXT FROM curParent into @ParentCode 

			End

			Close curParent
			Deallocate curParent

		Return 

	END
GO

