/****** Object:  UserDefinedFunction [dbo].[fn_SAL_BankInformation]    Script Date: 17/06/2026 11:38:53 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO


/****** Object:  User Defined Function dbo.fn_SAL_BankInformation    Script Date: 23/03/2010 12:53:26 PM ******/

CREATE FUNCTION [dbo].[fn_SAL_BankInformation] (@AsOnDate datetime,@RptDate datetime, @WarehoseCode varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(ItemCode	varchar(20),
	 ItemDescription varchar(50),
	 CBQty float, 
	 Rate float
	)

	 AS  
	
	BEGIN 			
		---BankStockProcess
		Insert @RetTable
		
			Select distinct a.ItemCode, b.ItemDesc, a.CBQty, 
			      Case When isNull(c.Rate,0) = 0 then isnull(b.Rate,0) Else c.Rate end as Rate
			from dbo.fn_INV_AsOnDate_Stock_Bank (@AsOnDate,@AsOnDate,@RptDate,@BranchID, @CompID, @Finyear)  a 
			    
			     left outer join dbo.fn_BOM_Get_Material_Master('A', @AsOnDate, @RptDate, @BranchID, @CompID) b
			           On b.ItemCode = a.ItemCode and a.Branchid = b.Branchid and a.CompID=b.CompID 
			    left outer join SalBankInformation c 
			           On c.ItemCode = a.ItemCode and WarehouseCode = WhCode and c.Branchid = a.Branchid and c.CompID=a.CompID
			Where a.BranchID = @BranchID and a.CompID = @CompID and WarehouseCode = @WarehoseCode and RackCode = ''  and CBQty > 0 
			Order By a.ItemCode
		Return 
	
	END













GO

/****** Object:  UserDefinedFunction [dbo].[fn_SAL_BankProcess]    Script Date: 17/06/2026 11:38:53 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO


/****** Object:  User Defined Function dbo.fn_SAL_BankProcess    Script Date: 23/03/2010 12:53:27 PM ******/
CREATE FUNCTION [dbo].[fn_SAL_BankProcess] (@Date Char(8),@AsOnDate datetime,@RptDate datetime, @WarehoseCode varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE

	(ItemCode	varchar(20),
	 ItemDescription varchar(50),
	 CBQty float, 
	 Rate float
	)

	 AS  
	
	BEGIN 			
	
		Insert @RetTable
			
			Select distinct a.ItemCode, b.ItemDescription,a.Qty as CBQty,a.Rate
			From dbo.fn_SAL_BankStockProcess(@Date,@BranchID,@CompID) a 
			Left Outer Join Inv_Material_Master b 
				On a.ItemCode = b.ItemCode and a.Branchid = b.Branchid and a.CompID=b.CompID 
			Where a.BranchID = @BranchID and a.CompID = @CompID and WhCode = @WarehoseCode and Qty > 0
			Order By a.ItemCode
			
		Return 
	
	END



GO

