/****** Object:  UserDefinedFunction [dbo].[fn_SAL_EInvoice_CustomerDtl_New]    Script Date: 17/06/2026 11:38:53 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE  FUNCTION [dbo].[fn_SAL_EInvoice_CustomerDtl_New] (@Userkey varchar(42), @ModuleCode int, @FromDate datetime, @ToDate datetime, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))                  
          
RETURNS @RetTable TABLE                                            
(                              
InvoiceType   Varchar(3),                              
InvoiceNo   Varchar(30),               
ERPInvNo    int,                         
InvoiceDate   datetime,                              
CustomerCode  int,                             
Type        varchar(20),                         
SupplyTypeCode  Varchar(10),                                
ReverseCharge  Varchar(3),                              
eCommGSTIN   Varchar(15),                              
IgstOnIntra   Varchar(3),                              
DocumentType  Varchar(20),                                
DocumentNumber  Varchar(20) ,                               
DocumentDate  datetime,                                 
BuyerGSTIN   Varchar(15),                                
BuyerLegalName  Varchar(100),                                
BuyerTradeName  Varchar(100),                                
BuyerPOS   Varchar(100),                                
BuyerAddr1   Varchar(100),                               
BuyerAddr2   Varchar(300),                               
BuyerLocation  Varchar(100),                                
BuyerPinCode  Varchar(10),                               
BuyerStateCode   Varchar(10),                                
BuyerPhoneNumber Varchar(30),                               
BuyerEmailId  Varchar(100),                               
DispatchName  Varchar(100),                               
DispatchAddr1   Varchar(100),                              
DispatchAddr2  Varchar(300),                              
DispatchLocation  Varchar(100),                              
DispatchPinCode  Varchar(10),                              
DispatchState   Varchar(100),                              
ShippingGSTIN  Varchar(15),                              
ShippingLegalName  Varchar(100),                              
ShippingTradeName  Varchar(100),                      
ShippingPOS        Varchar(100),                      
ShippingAddr1   Varchar(100),                              
ShippingAddr2  Varchar(300),                              
ShippingLocation Varchar(100),                               
ShippingPinCode  Varchar(10),                              
ShippingStateCode   Varchar(10),                              
BranchID   varchar(3),                              
CompID   varchar(3),                              
Finyear   varchar(20)                              
)                              
                              
AS                              
                              
BEGIN                              
          
 Declare @InvNoWithPrefixSuffixCutOffDate datetime;              
 Select @InvNoWithPrefixSuffixCutOffDate = '2017-02-22'              
      
 if (@ModuleCode=4)      
    Begin      
        Set @ModuleCode=@ModuleCode;      
    End      
 else      
    Begin      
        Set @ModuleCode=4;      
    End      
  
  
Declare @CompCode As varchar(5);        
 Declare @PertainingToID As int, @VerticalID As int; --, @ModuleCode As int;       
 Declare @NoWidth As bit;                 
                                
 SET @CompCode=(@Compid+@BranchID);      
 SET @PertainingToID=1  
 SET @VerticalID=5  
 SET @ModuleCode=4  
 SET @NoWidth='0'  
                         
 ; WITH CTE_InvLst                               
 AS                              
 (                              
 Select a.Type, a.InvoiceType, a.InvoiceNo, a.InvoiceDate, a.CustomerCode,  Case When a.Type='Rejection' Then 9 Else 4 End as Modulecode,       
    a.BranchID, a.CompID, a.Finyear,  a.InvoiceDate + ' ' + a.InvoiceTime as Transtamp       --a.Locationcode,                        
 From SalesInvoice a        
 Where Exists (Select * From SAL_Invoice_JSONGen_Tmp Where Userkey =@Userkey and InvoiceType=a.InvoiceType and InvoiceNo=a.InvoiceNo and InvoiceDate=a.InvoiceDate                              
  and CustomerCode=a.CustomerCode and BranchID=a.BranchID and CompID=a.CompID and Finyear=a.Finyear)                              
 )                              
 --LocationCode, a.IsExportInvoice,             
                              
 , CTE_CustDtl                               
 AS                              
 (                              
 Select 'B2B' as SupplyTypeCode, 'N' as ReverseCharge, '' as eCommGSTIN, 'N' as IGSTOnIntra, 'Tax Invoice' as DocumentType,                
  a.InvoiceNo as DocumentNumber, a.InvoiceDate as DocumentDate, e.GSTRegNo as BuyerGSTIN, b.PartyName as BuyerLegalName, b.PartyName as BuyerTradeName,                               
  j.TypeCode as BuyerPOS, e.Add1 as BuyerAddr1, e.Add2 + '' +  e.Add3 as BuyerAddr2, e.City  as BuyerCity, e.State as BuyerLocation,                           
  e.Pincode  as BuyerPinCode, j.TypeCode as BuyerStateCode, IsNull(e.Phone, '') as BuyerPhoneNumber, IsNull(e.EMail, '') as BuyerEMailID,                                  
  '' as DispatchName, '' as DispatchAddr1, ''  as DispatchAddr2, '' as DispatchLocation, '' as DispatchPinCode, ''  as DispatchState,                   
                                
   --e.GSTRegNo as ShippingGSTIN, b.PartyName as ShippingLegalName, b.PartyName as ShippingTradeName, j.TypeCode as ShippingPOS, --e.State as ShippingPOS,                          
   --e.Add1 as ShippingAddr1,  e.Add2 + '' +  e.Add3 as ShippingAddr2, e.City as ShippingCity,  e.State as ShippingLocation, e.Pincode as ShippingPinCode,                           
   --j.TypeCode as ShippingStateCode, --e.State as ShippingState,                          
                     
   --IsNull(m.GSTRegNo, e.GSTRegNo) as ShippingGSTIN,             
   e.GSTRegNo as ShippingGSTIN,            
   IsNull(m.Name, b.PartyName) as ShippingLegalName,  IsNull(m.Name, b.PartyName) as ShippingTradeName,                   
   Case When IsNull(m.Name, '') <> '' and IsNull(m.Address1, '') <> '' Then  IsNull(m1.TypeCode, '')  Else IsNull(j1.TypeCode, '') End as ShippingPOS,                    
   IsNull(m.Address1, e1.Add1) as ShippingAddr1, IsNull(m.Address2, e1.Add2) + '' +  IsNull(m.Address3, e1.Add3) as ShippingAddr2,                       
   IsNull(m.City, e1.City) as ShippingCity,  IsNull(m.State, e1.State) as ShippingLocation,  IsNull(m.PinCode, e1.Pincode) as ShippingPinCode,                   
   Case When IsNull(m.Name, '') <> '' and IsNull(m.Address1, '') <> '' Then  IsNull(m1.TypeCode, '')  Else IsNull(j1.TypeCode, '') End as ShippingStateCode,                                 
    --IsNull(m.GSTRegDate, IsNull(e.GSTRegDate, '')) as ShippingGSTRegDate,                                        
  a.InvoiceType, a.InvoiceNo, a.InvoiceDate, a.CustomerCode, a.Type, a.ModuleCode, a.BranchID, a.CompID, a.Finyear, a.Transtamp                               
 From CTE_InvLst a                              
 Left Outer Join FAS_PARTY_Master b                                                                                     
  On b.PartyCode = a.CustomerCode and b.BranchID = a.BranchID and b.CompId = a.CompId                               
 Left Outer Join FAS_PARTY_ADDRESS e                                                  
  On a.CustomerCode = e.PartyCode and a.BranchID=e.BranchID and a.CompId=e.CompId                              
 Left Outer Join dbo.fn_Com_Countrycity_Master ('A', @AsonDate, @RptDate, @BranchID, @CompID) j                                                          
  On j.ChildName=e.State  and j.ParentCode<>0                       
  Left Outer Join FAS_LrAddress_AuthTbl e1                                    
   On --a.LocationCode=e1.LocationCode and             
    a.CustomerCode=e1.LrCode and e1.CompCode=a.CompId+a.BranchID                                 
  Left Outer Join dbo.fn_Com_Countrycity_Master ('A', @AsOnDate, @RptDate, @BranchID, @CompID) j1                                                
   On j1.ChildName=e1.State and j1.ParentCode<>0                                 
  Left Outer Join (Select * from SAL_PACKINGLIST_ADDRESS                                 
           Where Orderflag='I' and Type='Consignee' --and OrderNo=a.InvoiceNo and OrderType=a.InvoiceType and OrderDate=a.InvoiceDate                             
       and BranchID=@BranchID and CompId=@CompID                              
     ) m                              
  On a.InvoiceNo=m.OrderNo and a.InvoiceType=m.OrderType and a.InvoiceDate=m.OrderDate and a.BranchId=m.BranchId and a.CompID=m.CompID                              
  Left Outer Join dbo.fn_Com_Countrycity_Master ('A', @AsOnDate, @RptDate, @BranchID, @CompID) m1                                                
   On m1.ChildName=m.State and m1.ParentCode<>0                                   
 Where a.InvoiceDate between @FromDate and @ToDate                              
 )                              
                              
 Insert into @RetTable              
  Select a.InvoiceType,           
 IsNull(dbo.fn_COM_Get_DocNoWithPrefixSuffix( a.InvoiceType,a.InvoiceNo, a.InvoiceDate, @PertainingToID, @NoWidth, @VerticalID, a.ModuleCode, @AsOnDate,          
     a.Transtamp, a.Branchid,a.Compid,a.Finyear),a.InvoiceNo) as InvoiceNo,  
  
    --Case When a.InvoiceDate>=@InvNoWithPrefixSuffixCutOffDate Then IsNull(dbo.fn_COM_Get_DocNoWithPrefixSuffix('0', a.ModuleCode, a.InvoiceType,a.InvoiceNo, a.InvoiceDate,@AsOnDate,            
    -- a.Transtamp, a.Branchid,a.Compid,a.Finyear),0) Else Convert(Varchar,IsNull(a.InvoiceNo,0)) End as InvoiceNo,          
  --IsNull(dbo.GetFormatedDocNoWithPrefixSuffix(a.InvoiceDate, a.InvoiceNo, b.WidthNo, b.Prefix, b.Suffix),  Convert(varchar, a.InvoiceNo)) as InvoiceNo,           
    a.InvoiceNo as ERPInvNo, a.InvoiceDate, a.CustomerCode, a.Type, a.SupplyTypeCode, a.ReverseCharge, a.eCommGSTIN, a.IgstOnIntra, a.DocumentType,               
  a.DocumentNumber, a.DocumentDate, a.BuyerGSTIN, a.BuyerLegalName,                                
   a.BuyerTradeName, a.BuyerPOS, a.BuyerAddr1, a.BuyerAddr2, a.BuyerLocation, a.BuyerPinCode, a.BuyerStateCode, a.BuyerPhoneNumber, a.BuyerEmailId,                               
   a.DispatchName, a.DispatchAddr1, a.DispatchAddr2, a.DispatchLocation, a.DispatchPinCode, a.DispatchState, a.ShippingGSTIN,
    IsNull(a.ShippingLegalName, a.BuyerLegalName) AS ShippingLegalName,                              
   IsNull(a.ShippingTradeName,  a.BuyerTradeName) AS ShippingTradeName, IsNull(a.ShippingPOS, a.BuyerPOS) AS ShippingPOS, IsNull(a.ShippingAddr1, a.BuyerAddr1)AS ShippingAddr1,  
    IsNull(a.ShippingAddr2, a.BuyerAddr2) AS ShippingAddr2, IsNull(a.ShippingLocation, a.BuyerLocation) AS ShippingLocation, 
    IsNull(a.ShippingPinCode, a.BuyerPinCode) AS ShippingPinCode, IsNull(a.ShippingStateCode, a.BuyerStateCode ) AS ShippingStateCode, @BranchID, @CompID, @Finyear                               
  From CTE_CustDtl   a              
  --Left Outer Join dbo.fn_COM_DocumentType_Master('M', @AsOnDate, @RptDate, @BranchID, @CompID) b               
  --On  InvoiceType=b.DocumentType                            
                              
 Return;                              
END 
GO

/****** Object:  UserDefinedFunction [dbo].[fn_SAL_EInvoice_GetExprResults_Saved]    Script Date: 17/06/2026 11:38:53 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

    
CREATE FUNCTION [dbo].[fn_SAL_EInvoice_GetExprResults_Saved] (@Doctype varchar(3), @DocNo int, @DocDate datetime, @ModuleCode int, @AsonDate datetime,@RptDate datetime,@BranchID varchar(3), @CompID varchar(3), @Finyear varchar(15))                        
                        
RETURNS @ExprResults TABLE                        
(                         
ExprName varchar(50),                      
ExprAmount money,                        
PostingAc int,              
ExprSeq int,      
FrmId int,      
Seq int,      
BranchID varchar(3),      
CompID varchar(3)                     
)                         
                          
AS                          
                        
BEGIN                         
                        
 Insert into @ExprResults            
         
         
  Select ExprName, Sum(ExprAmount) as ExprAmount, PostingAc, ExprSeq, FrmID, Seq, @BranchID,  @CompID      
 From        
 (                       
    Select              
     Case  When  ExprName='GOODS VALUE' Then 'GV'            
       When  ExprName='FREIGHT' Then 'Others'            
       When  ExprName='PACKING & FORWARDING' Then 'Others'            
       When  ExprName='INSURANCE' Then 'Others'            
       When  Left(ExprName, 4)='CGST' Then 'CGST'            
       When  Left(ExprName, 4)='SGST' Then 'SGST'            
       When  Left(ExprName, 4)='IGST' Then 'IGST'            
       When  Left(ExprName, 3)='TCS' Then 'TCS'            
       When  Left(ExprName, 8)='ROUNDOFF' Then 'ROUNDOFF'            
       END ExprName, ExprAmount,         
    Case When Seq=2 then 0 Else PostingAc End PostingAc,       
 Case When Seq=2 then 0 Else ExprSeq End ExprSeq, FrmID,  Seq    
   From (Select distinct  a.PostingAc, a.ExprName,            
       Case  When  ExprName='GOODS VALUE' Then 1            
       When  ExprName='FREIGHT' Then 2            
       When  ExprName='PACKING & FORWARDING' Then 2            
       When  ExprName='INSURANCE' Then 2            
       When  Left(ExprName, 4)='CGST' Then 3            
       When  Left(ExprName, 4)='SGST' Then 4            
       When  Left(ExprName, 4)='IGST' Then 5            
       When  Left(ExprName, 3)='TCS' Then 6            
       When  Left(ExprName, 8)='ROUNDOFF' Then 7           
       END Seq,    (a.Resultvalue*GrandTotalFlag) as ExprAmount, ExprSeq, FrmID        
     --Sum(a.Resultvalue) as ExprAmount            
   From dbo.fn_COM_GetExprResults_Saved (@Doctype,@DocNo, @DocDate, @ModuleCode, @BranchID, @CompID , @Finyear) a              
   Where a.GrandTotalFlag <> 0            
        
   ) x           
   )y         
   Group by PostingAc, ExprName, ExprSeq, FrmID, Seq        
   Order by Seq            
                
    Return                        
                        
END 
GO

/****** Object:  UserDefinedFunction [dbo].[fn_SAL_EInvoice_ItemDtl]    Script Date: 17/06/2026 11:38:53 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO



      
CREATE FUNCTION [dbo].[fn_SAL_EInvoice_ItemDtl] (@Userkey varchar(42), @FromDate datetime, @ToDate datetime, @ModuleCode int, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))                           
  
    
      
RETURNS @RetTable TABLE                                          
(                            
InvoiceType    Varchar(3),                              
InvoiceNo    int,                             
InvoiceDate    datetime,                               
CustomerCode   int,                            
Type  varchar(20),                
SlNo     Varchar(6),                             
ProductDescription  Varchar(100),                            
IsService    Varchar(3),                            
HSNcode     Varchar(8),                             
Barcode     Varchar(300),                            
Quantity    float,                             
FreeQuantity   float,                            
Unit     Varchar(8),                             
UnitPrice    decimal(12, 3),                            
GrossAmount    decimal(12, 2),                             
Discount    decimal(12, 2),                             
PreTaxValue    decimal(12, 2),                             
Taxablevalue   decimal(12, 2),                             
--TaxName     Varchar(15),                            
GSTRate     float,                             
SgstAmt     decimal(12, 2),                             
CgstAmt     decimal(12, 2),                             
IgstAmt     decimal(12, 2),                    
RoundoffAmt         decimal(12, 2),                
--TCSAmount     decimal(12, 2),                
OtherCharges   decimal(12, 2),                       
CessRate decimal(12, 2),                       
CessAmt decimal(12, 2),                       
CessNonAdvlAmt decimal(12, 2),                       
StateCessRate decimal(12, 2),                      
StateCessAmt decimal(12, 2),                       
StateCessNonAdvlAmt decimal(12, 2),                            
TotalItemValue    decimal(12, 2),                         
TotalTaxablevalue  decimal(12, 2),                            
TotalSgstAmt   decimal(12, 2),                            
TotalCgstAmt   decimal(12, 2),                            
TotalIgstAmt   decimal(12, 2),                       
--TotalTCSAmount     decimal(12, 2),                  
TotalOthercharges  decimal(12, 2),                            
TotalRoundoffAmt    decimal(12, 2),                            
TotalInvoicevalue   decimal(12, 2),                            
BranchID   varchar(3),                            
CompID   varchar(3),                            
Finyear   varchar(20)                            
)                            
                              
AS                            
                            
BEGIN                            
                            
Declare @Discount as float                            
Set @Discount=0                          
                        
                        
 --    if (@ModuleCode=13)                      
 -- Begin                          
 --  Set @ModuleCode = 4;                               
 -- End                          
 --Else                            
 --IF (@ModuleCode=6)              
 -- BEGIN            
 --  Set @ModuleCode = 9;             
 -- END            
 --ELSE            
 --  Begin                              
 --   Set @ModuleCode = @ModuleCode;                           
 --  End                 
            
; WITH CTE_InvLst                       
 AS                      
 (                      
 Select distinct a.Type, a.InvoiceType, a.InvoiceNo, a.InvoiceDate, a.CustomerCode,  a.FormulaCode, a.BranchID, a.CompID, a.Finyear, Count(a.ItemCode) as ItemCount,  
  Case When Type='Rejection' Then 9 Else 4 End as Modulecode                      
 --a.IsExportInvoice,    
 From SalesInvoice a                      
 Where Exists (Select * From SAL_Invoice_JSONGen_tmp Where Userkey=@Userkey and InvoiceType=a.InvoiceType and InvoiceNo=a.InvoiceNo and InvoiceDate=a.InvoiceDate                      
  and CustomerCode=a.CustomerCode and BranchID=a.BranchID and CompID=a.CompID and Finyear=a.Finyear)                      
  and a.InvoiceDate between @FromDate and @ToDate                
 Group by a.Type, a.InvoiceType, a.InvoiceNo, a.InvoiceDate, a.CustomerCode, a.FormulaCode, a.BranchID, a.CompID, a.Finyear       
 --a.IsExportInvoice,        
 )                      
                       
 , CTE_ItemDtl                      
 AS                      
 (Select distinct a.CustomerCode,  a.InvoiceType, a.InvoiceNo, a.InvoiceDate, a.Type, a.ItemCode,                      
 ROW_NUMBER() OVER (PARTITION BY a.InvoiceNo, a.InvoiceDate ORDER BY a.InvoiceNo, a.InvoiceDate) as SlNo,                       
 IsNull(f.ItemDescription, '') as ProductDescription,  --IsNull(f.ItemDesc, k.ItemDesc) as ProductDescription,     
 Case a.Type When 'Labour' then 'Y' Else 'N' End as IsService,IsNull(i.HSNNo,'') as HSNNo, '' as Barcode,                       
  a.InvoiceQty  as Quantity, 0 as FreeQuantity, IsNull(f.UOMDesc, '') as Unit, --IsNull(f.UOMDesc,l.UOMDesc) as Unit,     
  a.Rate as UnitPrice, (a.InvoiceQty*a.Rate)as GrossAmount, 0 as Discount,-- 0 as PreTaxValue,           
  ((a.InvoiceQty*a.Rate) - 0) as TaxableValue,   a.TotalAmount as TotalInvAmtHdr,                    
  a1.ItemCount, a1.ModuleCode, a.BranchID, a.CompID, a.Finyear                      
 From CTE_InvLst a1                      
 Left Outer Join SalesInvoice a                       
  On a.InvoiceNo=a1.InvoiceNo and a.InvoiceType=a1.InvoiceType and a.InvoiceDate=a1.InvoiceDate and a1.CustomerCode=a.CustomerCode --and a1.ItemCode=a.ItemCode                     
    and a.BranchId=a1.BranchId and a.CompID=a1.CompID                   
 Left Outer Join Material_Master f --dbo.fn_BOM_Get_MATERIAL_INV('A', @AsonDate, @RptDate, @BranchID, @CompID) f                                                          
  On a.ItemCode=f.ItemCode and a.BranchID=f.BranchID and a.CompID=f.CompID                                                              
 --Left Outer Join dbo.fn_BOM_Get_Material_AssetItem_MasterCode('A', @AsonDate, @RptDate, @BranchID, @CompID) k                                         
 -- On (a.ItemCode+a.AssetCode)=(k.ItemCode+k.AssetCode)                                              
 --Left Outer Join dbo.fn_BOM_Get_MATERIAL_INV('A', @AsonDate, @RptDate, @BranchID, @CompID) l                                                    
 --On k.ItemCode=l.ItemCode                                                    
     Left Outer Join fn_BOM_HSNNo_Master('A', @AsonDate, @RptDate, @BranchID, @CompID) i                                      
  On i.HSNId=isnull(f.HSNId,'')      
  --On i.HSNId=isnull(f.HSNId,l.HSNId)     
                            
 Where                       
 a.InvoiceDate between @FromDate and @ToDate                  
 )                      
                      
 , CTE_ItemWithExprValue                      
 AS                      
 (                      
 Select InvoiceType, InvoiceNo, InvoiceDate, ItemCode, Sum(TaxRate) as GSTRate,           
  Sum(GV) GV, Sum(OtherCharges) as PreTaxValue, Sum(CGSTAmount) CGSTAmount, Sum(CGSTAmount) as SGSTAmount, Sum(IGSTAmount) IGSTAmount,                 
  Sum(TCSAmount) TCSAmount, Sum(RoundOffAmount)  RoundOffAmount, BranchID, CompID                     
 From (                      
 Select a1.InvoiceType, a1.InvoiceNo, a1.InvoiceDate, a1.ItemCode, a1.BranchID, a1.CompID,                      
   IsNull((Case When ExprName='GV' then c.ExprAmount End), 0) as GV,                      
   IsNull((Case When ExprName='Others' then c.ExprAmount End),0) as OtherCharges,                         
   IsNull((Case When ExprName='CGST' then c.ExprAmount End),0) as CGSTAmount,                      
   IsNull((Case When ExprName='SGST' then c.ExprAmount End),0) as SGSTAmount,                      
   IsNull((Case When ExprName='IGST' then c.ExprAmount End),0) as IGSTAmount,                      
IsNull((Case When ExprName='TCS' then c.ExprAmount End),0) as TCSAmount,                      
   IsNull((Case When ExprName='ROUNDOFF' then c.ExprAmount End),0) as RoundOffAmount,           
   Case When ExprName in ('CGST', 'SGST', 'IGST') Then IsNull(d.Valueused, 0) Else 0 End as TaxRate                      
from CTE_ItemDtl a1 --CTE_InvLst a1                     
Outer Apply (Select * From [fn_SAL_EInvoice_GetExprResults_Saved] (a1.InvoiceType, a1.InvoiceNo, a1.InvoiceDate,   a1.ModuleCode, @AsonDate, @RptDate, @BranchID, @CompID, @Finyear ) o                
 ) c                 
 Left Outer Join Com_FormulaMast_Block_Dtl d                
 On d.ModuleCode=a1.ModuleCode and d.frmID=c.frmID and d.ExprSeq=c.ExprSeq and d.ValueUsed>0 and d.BranchId=c.BranchId and d.CompId=c.CompID                 
) m                      
group by InvoiceType, InvoiceNo, InvoiceDate, ItemCode, BranchID, CompID                
 )                      
          
--Select * from CTE_ItemWithExprValue            
          
 , CTE_ItemWithTaxDtl                   
 AS                        
 (                        
 SElect x.InvoiceType, x.InvoiceNo, x.InvoiceDate,  x.Type, x.CustomerCode, x.SlNo, x.ProductDescription, x.IsService, x.HSNNo, x.Barcode,                        
  x.Quantity, x.FreeQuantity, x.Unit, x.UnitPrice, x.GrossAmount, x.Discount, x.PreTaxValue, (x.TaxableValue+x.PreTaxValue) TaxableValue,  x.GSTRate,      --x.TaxableValue,                   
  (x.GrossAmount+x.PreTaxValue+x.CGSTAmount+x.SGSTAmount+x.IGSTAmount) TotalItemValue, x.SGSTAmount, x.CGSTAmount, x.TCSAmount, x.IGSTAmount, x.PreTaxValue as OtherCharges,           --(x.GrossAmount+x.CGSTAmount+x.SGSTAmount+x.IGSTAmount) TotalItemValue,
    
             
  x.RoundOffAmount as RoundoffAmt, x.BranchID, x.CompID, x.Finyear                          
 FROM                        
 (                        
 Select a.InvoiceType, a.InvoiceNo, a.InvoiceDate, a.Type, a.CustomerCode, a.ItemCode, a.SlNo, a.ProductDescription, a.IsService, a.HSNNo, a.Barcode,                        
  a.Quantity, a.FreeQuantity, a.Unit, a.UnitPrice, a.GrossAmount, a.Discount,  a.TaxableValue, a1.GSTRate, --a1.SGSTAmount, a1.CGSTAmount,             
   Case When a1.SGSTAmount > 0 then (((a.TaxableValue+a1.PreTaxValue)*(a1.GSTRate/2))/100) Else 0 End as SGSTAmount,        
  Case When a1.CGSTAmount > 0 then (((a.TaxableValue+a1.PreTaxValue)*(a1.GSTRate/2))/100) Else 0 End as CGSTAmount,        
  Case When a1.IGSTAmount > 0 then (((a.TaxableValue+a1.PreTaxValue)*a1.GSTRate)/100) Else 0 End as IGSTAmount,         
  --Case When a1.SGSTAmount > 0 then (a1.SGSTAmount/a.ItemCount) Else 0 End as SGSTAmount,          
  --Case When a1.CGSTAmount > 0 then (a1.CGSTAmount/a.ItemCount) Else 0 End as CGSTAmount,          
  --Case When a1.IGSTAmount > 0 then (a1.IGSTAmount/a.ItemCount) Else 0 End as IGSTAmount,         
          
  a1.TCSAmount, a1.PreTaxValue as PreTaxValue, a1.GV,        
  --(a.GrossAmount+(a1.CGSTAmount/a.ItemCount)+(a1.SGSTAmount/a.ItemCount)+a1.IGSTAmount) TotalItemValue,                 
  a1.RoundOffAmount,  a.TotalInvAmtHdr as TotalInvAmtHdr,  a.BranchID, a.CompID, a.Finyear                     
 From CTE_ItemDtl a                        
 Left Outer Join CTE_ItemWithExprValue a1                        
 On a.InvoiceNo=a1.InvoiceNo and a.InvoiceType=a1.InvoiceType and a.InvoiceDate=a1.InvoiceDate                         
   and a1.ItemCode=a.ItemCode --and a.BranchId=a1.BranchId and a.CompID=a1.CompID                         
 ) x                        
                 
 )                        
      --Select * from CTE_ItemWithTaxDtl              
           
 , CTE_InvWithTotalTaxDtl                        
 AS                        
 (                        
     Select x.InvoiceType, x.InvoiceNo, x.InvoiceDate, x.CustomerCode,  x.TotalDiscount,  TotalTaxableValue, TotalSGSTAmount,                          
      TotalCGSTAmount, TotalIGSTAmount, TotalTCSAmount, TotalPreTaxValue, TotalRoundoffAmt,                  
      (x.TotalTaxableValue+x.TotalCGSTAmount+x.TotalSGSTAmount+x.TotalIGSTAmount+x.TotalTCSAmount+x.TotalRoundoffAmt) TotalInvValue,                 
      x.BranchID, x.CompID, x.Finyear                        
        --x.TotalInvValue, b.RoundOffAmount as RoundoffAmt,, (b.GV+b.CGSTAmount+b.SGSTAmount+b.IGSTAmount+b.TCSAmount+b.OtherCharges) TotalItemValue,                 
     FROM                        
     (                        
     Select a.InvoiceType, a.InvoiceNo, a.InvoiceDate, a.CustomerCode,  (Sum(a.TaxableValue)+ a1.PreTaxValue) as TotalTaxableValue, a.Discount AS TotalDiscount,                
      a1.SGSTAmount as TotalSGSTAmount, a1.CGSTAmount as TotalCGSTAmount, a1.IGSTAmount as TotalIGSTAmount,                         
      a1.TCSAmount TotalTCSAmount, a1.PreTaxValue as TotalPreTaxValue, a1.RoundOffAmount as TotalRoundoffAmt,                          
       --(a1.GV+a1.CGSTAmount+a1.SGSTAmount+a1.IGSTAmount+a1.TCSAmount+a1.OtherCharges+a1.RoundOffAmount) TotalInvValue,                 
      a.BranchID, a.CompID, a.Finyear                        
     From CTE_ItemDtl a                        
     Left Outer Join CTE_ItemWithExprValue a1                        
     On a.InvoiceNo=a1.InvoiceNo and a.InvoiceType=a1.InvoiceType and a.InvoiceDate=a1.InvoiceDate                         
       and a1.ItemCode=a.ItemCode --and a.BranchId=a1.BranchId and a.CompID=a1.CompID                  
       group by a.InvoiceType, a.InvoiceNo, a.InvoiceDate, a.CustomerCode, a.Discount,  a1.SGSTAmount, a1.CGSTAmount, a1.IGSTAmount,             
   a1.TCSAmount, a1.PreTaxValue, a1.RoundOffAmount, a.BranchID, a.CompID, a.Finyear                          
 ) x                        
 )                        
                    
   --SElect * From CTE_InvWithTotalTaxDtl          
                
  Insert into  @RetTable                
   SElect a.InvoiceType, a.InvoiceNo, a.InvoiceDate, a.CustomerCode,  a.Type, a.SlNo, a.ProductDescription, a.IsService, IsNull(a.HSNNo, 0) as HSNNO, 0 as Barcode,                        
   IsNull(a.Quantity, 0) as Quantity, IsNull(a.FreeQuantity, 0) as FreeQuantity, IsNull(a.Unit, '') as Unit, IsNull(a.UnitPrice, 0) as UnitPrice,                 
   IsNull(a.GrossAmount, 0) as GrossAmount, IsNull(a.Discount, 0) as Discount, IsNull(a.PreTaxValue, 0) as PreTaxValue, IsNull(a.TaxableValue, 0) as TaxableValue,                 
   a.GSTRate, IsNull(a.SGSTAmount, 0) as SGSTAmount, IsNull(a.CGSTAmount, 0) as CGSTAmount, IsNull(a.IGSTAmount, 0) as IGSTAmount, IsNull(RoundoffAmt, 0) as RoundoffAmt,                 
   --IsNull(a.TCSAmount, 0) as TCSAmount,                 
   IsNull(a.OtherCharges, 0) as OtherCharges, 0 as CessRate, 0 as CessAmt, 0 as CessNonAdvlAmt, 0 as StateCessRate, 0 as StateCessAmt, 0 as StateCessNonAdvlAmt,                 
   IsNull(a.TotalItemValue, 0) as TotalItemValue, IsNull(b.TotalTaxableValue, 0) as TotalTaxableValue, IsNull(b.TotalSGSTAmount, 0) as TotalSGSTAmount,                     
   IsNull(b.TotalCGSTAmount, 0) as TotalCGSTAmount, IsNull(b.TotalIGSTAmount, 0) as TotalIGSTAmount, IsNull(b.TotalTCSAmount, 0) as TotalOthercharges,                  
    IsNull(b.TotalRoundoffAmt, 0) as TotalRoundoffAmt, IsNull(b.TotalInvValue, 0) as TotalInvValue,                 
   a.BranchID, a.CompID, a.Finyear                
   From CTE_ItemWithTaxDtl  a                
   Left Outer Join  CTE_InvWithTotalTaxDtl b                
   On   a.InvoiceNo=b.InvoiceNo and a.InvoiceType=b.InvoiceType and a.InvoiceDate=b.InvoiceDate                         
   and a.CustomerCode=b.CustomerCode and a.BranchId=b.BranchId and a.CompID=b.CompID                  
                     
   Return;                        
END 
GO

/****** Object:  UserDefinedFunction [dbo].[fn_SAL_JobWorkOrder]    Script Date: 17/06/2026 11:38:53 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_SAL_JobWorkOrder] (@AsOnDate datetime,@RptDate datetime,@BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE
	(OrderType	varchar(3),
	OrderNo	int,
	OrderDate	datetime,
	OrderSource	varchar(1),	
	CustomerCode	int,
	ReferenceNo	varchar(20),
	ReferenceDate  datetime,
	ValidFrom	datetime,
	ValidTo		datetime,
	OrderingType 	varchar(10),
	Remarks	varchar(50),
	FormCode	int,
	PackingCode	int,
	DeliveryCode	int,
	PaymentCode	int,
	InsuranceCode	int,
	ModeCode	int,
	Freightcode	int,
	FormulaCode	int,
	TotalAmount 	float,
	PostingAc	int,
	ItemGroupKey 	int,
	ReceivedItemCode varchar(20),
	SentItemCode 	varchar(30),
	OrderQty	 float,
	RatePer		 int,
	Rate		 float,
	AssRate	 float,
 	ItemStatus 	varchar(20),
	Status		varchar(20),
	CreatedDate	datetime,
	OrderAuthorizationBy	varchar(10),
	Userid		varchar(10),
	Branchid	varchar(3),
	Compid		varchar(3),
	Finyear		varchar(20)
	)
	

 AS  
		

BEGIN 

	Insert @RetTable
		select distinct x.OrderType,x.OrderNo,x.OrderDate,x.OrderSource,x.CustomerCode,x.ReferenceNo,x.ReferenceDate,x.ValidFrom,x.ValidTo,x.OrderingType,
			x.Remarks,x.FormCode,x.PackingCode,x.DeliveryCode,x.PaymentCode,x.InsuranceCode,x.ModeCode,x.Freightcode,x.FormulaCode,x.TotalAmount,
			x.PostingAc,z.ItemGroupKey,z.ReceivedItemCode,z.SentItemCode,z.OrderQty,
			z.Rateper,z.Rate,z.AssRate,z.Status as ItemStatus,
			x.Status as Status,x.CreatedDate,x.OrderAuthorizationBy,x.Userid,x.Branchid,x.Compid, x.Finyear from (
				Select * from SAL_JOBWORKORDER_HDR a
				Where a.CreatedDate = (Select Max(b.CreatedDate) from SAL_JOBWORKORDER_Hdr b where b.CreatedDate <= @AsOnDate 
				and b.OrderType=a.OrderType and b.OrderNo=a.OrderNo and b.OrderDate=a.OrderDate
				and b.BranchID=a.BranchID and b.CompID=a.CompID
			)
		and a.BranchID=@BranchID and a.CompID=@CompID)x
		inner join (Select * from SAL_JOBWORKORDER_DTL a
			Where a.CreatedDate = (Select Max(b.CreatedDate) from SAL_JOBWORKORDER_DTL b where b.CreatedDate <= @AsOnDate 
			and b.OrderType=a.OrderType and b.OrderNo=a.OrderNo and b.OrderDate=a.OrderDate
			and b.ReceivedItemCode=a.ReceivedItemCode and b.SentITemCode=a.SentItemCode and a.ItemGroupKey=b.ItemGroupKey
			and b.BranchID=a.BranchID and b.CompID=a.CompID
			)
		and a.BranchID=@BranchID and a.CompID=@CompID )z
	on x.OrderType=z.OrderType and x.OrderNo=z.OrderNo and x.OrderDate=z.OrderDate
	Return 

END
GO

