CREATE FUNCTION [dbo].[fn_SAL_SalesOrder] (@AsOnDate datetime,@RptDate datetime,@BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE
	(OrderType		varchar(3),
	OrderNo		int,
	OrderDate		datetime,
	OrderSource		varchar(1),	
	CustomerCode		int,
	ReferenceNo		varchar(20),
	ReferenceDate 		datetime,
	ValidFrom		datetime,
	ValidTo			datetime,
	OrderingType 		varchar(10),
	Remarks		varchar(50),
	FormCode		int,
	PackingCode		int,
	DeliveryCode		int,
	PaymentCode		int,
	InsuranceCode		int,
	ModeCode		int,
	Freightcode		int,
	FormulaCode		int,
	TotalAmount 		float,
	PostingAc		int,
	RevisionLevel 		varchar(10),
	GeneralDetails		varchar(3000),
	ItemCode	 	varchar(20),
	ItemDescription 		varchar(300),
	PartNo		 	varchar(30),
	RevisionNo	 	varchar(20),
	UOM 			varchar(3),
	OrderQty 		float,
	Rate 			float,
	AssessableRate		 float,
 	ItemStatus 		char(1),
	Status			char(1),
	CreatedDate		datetime,
	OrderAuthorizationBy	varchar(10),
	Userid			varchar(10),
	Branchid		varchar(3),
	Compid			varchar(3),
	Finyear			varchar(20)
	)
	

 AS  
		

BEGIN 

	Insert @RetTable
		select distinct x.OrderType,x.OrderNo,x.OrderDate,x.OrderSource,x.CustomerCode,x.ReferenceNo,x.ReferenceDate,x.ValidFrom,x.ValidTo,x.OrderingType,
			x.Remarks,x.FormCode,x.PackingCode,x.DeliveryCode,x.PaymentCode,x.InsuranceCode,x.ModeCode,x.Freightcode,x.FormulaCode,x.TotalAmount,
			x.PostingAc,x.RevisionLevel,x.GeneralDetails,z.ItemCode,z.ItemDescription,z.PartNo,z.RevisionNo,z.UOM,z.OrderQty,
			z.Rate,z.AssessableRate,z.Status as ItemStatus,x.Status,x.CreatedDate,x.OrderAuthorizationBy,x.Userid,x.Branchid,x.Compid,
			x.Finyear	 from (Select * from SAL_Order_Hdr a
			Where a.CreatedDate = (Select Max(b.CreatedDate) from SAL_Order_Hdr b where b.CreatedDate <= @AsOnDate 
			and b.OrderType=a.OrderType and b.OrderNo=a.OrderNo and b.OrderDate=a.OrderDate
			and b.BranchID=a.BranchID and b.CompID=a.CompID
			)
		and a.BranchID=@BranchID and a.CompID=@CompID)x
		inner join (Select * from SAL_Order_Dtl a
			Where a.CreatedDate = (Select Max(b.CreatedDate) from SAL_Order_Dtl b where b.CreatedDate <= @AsOnDate 
			and b.OrderType=a.OrderType and b.OrderNo=a.OrderNo and b.OrderDate=a.OrderDate
			and b.ItemCode=a.ItemCode
			and b.BranchID=a.BranchID and b.CompID=a.CompID
			)
		and a.BranchID=@BranchID and a.CompID=@CompID )z
	on x.OrderType=z.OrderType and x.OrderNo=z.OrderNo and x.OrderDate=z.OrderDate
	Return 

END
GO

