CREATE  FUNCTION [dbo].[fn_SAL_SalesPlan] (@AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE
	(DocType	varchar(3),
	DocNo		int,
	DocDate	datetime,
	PlanFor		int,
	PlanPeriod	datetime,
	CustomerCode	int,
	ItemCode	varchar(20),
	PlanQty		float,
	RevisionNo	int,
	EffStatus	bit,
	EffDate		datetime,
	CreatedDate	datetime,
	Userid		varchar(10),
	Branchid	varchar(3),
	Compid		varchar(3),
	Finyear		varchar(20),
	TranStamp	datetime
	)


 AS  

BEGIN 
	Insert @RetTable
		Select * from SAL_SalesPlan a
		Where a.RevisionNo = (Select Max(b.RevisionNo) from SAL_SalesPlan b where b.CreatedDate <= @AsOnDate 
			and b.DocType=a.DocType and b.DocNo=a.DocNo and b.DocDate=a.DocDate 
			and a.PlanFor = b.PlanFor and a.PlanPeriod = b.PlanPeriod
			and b.BranchID=a.BranchID and b.CompID=a.CompID and a.Finyear = b.finyear
			)
		and ((a.EffStatus='1' and a.EffDate <= @RptDate) or (a.EffStatus='0' and a.EffDate >= @RptDate))
			and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear = @finyear

	Return 

END
GO

