CREATE FUNCTION [dbo].[fn_SAL_SalesPlan_Dtl_v2] (@AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(15))          
RETURNS @RetTable TABLE        
 (DocType varchar(3),        
  DocNo  int,        
  DocDate datetime,        
  PlanFor  int,        
  PlanPeriod datetime,        
  CustomerCode int,        
  ItemCode varchar(20),        
  PlanQty float,        
