 )        
        
        
 AS          
        
BEGIN         
 Insert @RetTable        
  Select * From SAL_SalesPlan a        
  Where a.CreatedDate = (Select Max(b.CreatedDate) From SAL_SalesPlan b Where b.CreatedDate <= @AsOnDate         
   and a.DocNo=b.DocNo and b.DocDate=a.DocDate and a.DocType=b.DocType         
   and a.PlanFor = b.PlanFor and a.PlanPeriod = b.PlanPeriod and a.ItemCode=b.ItemCode and a.CustomerCode=b.CustomerCode         
