/****** Object:  UserDefinedFunction [dbo].[fn_SAL_SalesPlanRevision]    Script Date: 17/06/2026 11:38:53 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_SAL_SalesPlanRevision] (@DocType  varchar(3),@DocNo int, @DocDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS @RetTable TABLE
	(DocType	varchar(3),
	DocNo		int,
	DocDate	datetime,
	PlanFor		int,
	PlanPeriod	datetime,
	CustomerCode	int,
	ItemCode	varchar(20),
	PlanQty		float,
	RevisionNo	int,
	EffStatus	bit,
	EffDate		datetime,
	CreatedDate	datetime,
	Userid		varchar(10),
	Branchid	varchar(3),
	Compid		varchar(3),
	Finyear		varchar(20),
	Status		varchar(10)
	)



 AS  

BEGIN 

	Declare @RecCount as int
	Declare @sCount as int
	Declare @PrvCount as int
	Declare @CurCount as int
	
		Select @RecCount=max(Revisionno) from SAL_SalesPlan where DocType=@DocType and Docno=@DocNo and DocDate=@DocDate and BranchID=@BranchID and CompID=@CompID and Finyear=@Finyear
		Select @sCount=1

		Insert @RetTable
		Select *,'INITIAL STATE' from SAL_SalesPlan where DocType=@DocType and Docno=@DocNo and DocDate=@DocDate and Revisionno=0 and BranchID=@BranchID and CompID=@CompID and Finyear=@Finyear	

		While @RecCount>=@sCount
			Begin
				Select @PrvCount=Count(*) from SAL_SalesPlan where DocType=@DocType and Docno=@DocNo and DocDate=@DocDate and Revisionno=@sCount-1 and BranchID=@BranchID and CompID=@CompID and Finyear=@Finyear	
			
				Select @CurCount=Count(*) from SAL_SalesPlan where DocType=@DocType and Docno=@DocNo and DocDate=@DocDate and Revisionno=@sCount and BranchID=@BranchID and CompID=@CompID and Finyear=@Finyear
				
				if @PrvCount<@CurCount
					Begin
						Insert @RetTable
						select *,'NEW' as Status from SAL_SalesPlan where ItemCode not in (
							select a.ItemCode from 
							(select * from SAL_SalesPlan a where Revisionno=@sCount-1and DocType=@DocType and Docno=@DocNo and DocDate=@DocDate and BranchID=@BranchID and CompID=@CompID and Finyear=@Finyear)a
							inner join (select * from SAL_SalesPlan a where Revisionno=@sCount and DocType=@DocType and Docno=@DocNo and DocDate=@DocDate and BranchID=@BranchID and CompID=@CompID and Finyear=@Finyear)b
							on a.DocType=b.DocType and a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.PlanFor=b.PlanFor and a.PlanPeriod=b.PlanPeriod and a.CustomerCode=a.CustomerCode 
							and a.ItemCode=b.ItemCode and a.PlanQty=b.PlanQty and a.Branchid=b.Branchid and a.CompID=b.CompID and a.Finyear=b.Finyear )  and Revisionno=@sCount
							and DocType=@DocType and Docno=@DocNo and DocDate=@DocDate and BranchID=@BranchID and CompID=@CompID and Finyear=@Finyear
					End			
				else
					Begin
						Insert @RetTable
						select *,'MODIFIED' as Status from SAL_SalesPlan where ItemCode not in (
							select a.ItemCode from 
							(select * from SAL_SalesPlan a where Revisionno=@sCount-1and DocType=@DocType and Docno=@DocNo and DocDate=@DocDate and BranchID=@BranchID and CompID=@CompID and Finyear=@Finyear)a
							inner join (select * from SAL_SalesPlan a where Revisionno=@sCount and DocType=@DocType and Docno=@DocNo and DocDate=@DocDate and BranchID=@BranchID and CompID=@CompID and Finyear=@Finyear)b
							on a.DocType=b.DocType and a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.PlanFor=b.PlanFor and a.PlanPeriod=b.PlanPeriod and a.CustomerCode=a.CustomerCode 
							and a.ItemCode=b.ItemCode and a.PlanQty=b.PlanQty and a.Branchid=b.Branchid and a.CompID=b.CompID and a.Finyear=b.Finyear )  and Revisionno=@sCount
							and DocType=@DocType and Docno=@DocNo and DocDate=@DocDate and BranchID=@BranchID and CompID=@CompID and Finyear=@Finyear
					End
	
				Select @sCount=@sCount+1
			End

	Return 

END
GO

