CREATE FUNCTION [dbo].[fn_SEC_Users] ( @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3))  

RETURNS @RetTable TABLE
	(UserID		varchar(10),
	UserName	varchar(50),
	[Password]	varchar(15),
	UserGroupID	char(1),
	EffStatus	bit,
	EffDate		datetime,
	CreatedDate	datetime,
	BranchID	varchar(3),
	CompId		varchar(3),
	ActiveStatus	bit,
	LoginStatus	bit,
	TranStamp	datetime
	)


 AS  

BEGIN 
	Insert @RetTable
		Select * from SEC_Users a
		Where a.CreatedDate = (Select Max(b.CreatedDate) from SEC_Users b where b.CreatedDate <= @AsOnDate 
			and b.UserID=a.UserID 
			and b.BranchID=a.BranchID and b.CompID=a.CompID
			)
		and ((a.EffStatus='1' and a.EffDate <= @RptDate) or (a.EffStatus='0' and a.EffDate > @RptDate))
			and a.BranchID=@BranchID and a.CompID=@CompID

	Return 

END

GO

/****** Object:  UserDefinedFunction [dbo].[fn_SplitString]    Script Date: 17/06/2026 11:38:53 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_SplitString]
(
    @String VARCHAR(MAX),
    @Delimiter CHAR(1)
)
RETURNS @Result TABLE (Value VARCHAR(50))
AS
BEGIN
    DECLARE @Start INT, @End INT

    SET @Start = 1

    IF SUBSTRING(@String, LEN(@String), 1) <> @Delimiter
        SET @String = @String + @Delimiter

    SET @End = CHARINDEX(@Delimiter, @String, @Start)

    WHILE @End > 0
    BEGIN
        INSERT INTO @Result(Value)
        VALUES(SUBSTRING(@String, @Start, @End - @Start))

        SET @Start = @End + 1
        SET @End = CHARINDEX(@Delimiter, @String, @Start)
    END

    RETURN
END
GO

/****** Object:  UserDefinedFunction [dbo].[fn_Table_Structure]    Script Date: 17/06/2026 11:38:54 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [dbo].[fn_Table_Structure] (@TableName varchar(30))  

RETURNS @TableField TABLE
	(FieldName	varchar(80))
AS  

BEGIN 
	Declare @TableID int
	Declare @DLen int
	Declare @FName varchar(30)
	Declare @FType varchar(30)
	Declare @Seq int

	Select @TableID=id from sysobjects where name=@TableName

	Select @DLen= max(len(a.name)) from syscolumns a where a.id=@TableID

	Declare FList_Cursor cursor for

		select a.name, (select name from systypes where xtype=a.xtype) + 
			Case when a.xtype in (167,175) then '(' + convert(varchar, a.length) + '),' else ',' end as FieldName,  a.colorder
		from syscolumns a
		where a.id=@TableID
		order by a.colorder

		OPEN FList_Cursor

		FETCH NEXT FROM FList_cursor  into @FName, @FType, @Seq
	
	
		WHILE @@FETCH_STATUS = 0
		BEGIN
		
			Insert into @TableField values (@FName + Space(@DLen-Len(@FName) + 2)+',')	

			FETCH NEXT FROM FList_cursor  into @FName,@FType, @Seq 

		End

		Close FList_Cursor
		Deallocate FList_Cursor

	Return

END





















GO

/****** Object:  UserDefinedFunction [dbo].[fn_Test_COM_Trace_AsOnDate_Stock]    Script Date: 17/06/2026 11:38:54 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_Test_COM_Trace_AsOnDate_Stock] (@ItemCode Varchar(30), @StockDate datetime,    
																	@AsonDate datetime, @RptDate datetime, @BranchID varchar(3),  @CompID varchar(3),  @Finyear varchar(20))      
RETURNS @RetTable TABLE                    
	(
		[ItemCode]			[varchar] (30),                     
		[WarehouseCode]		[varchar] (6),                   
		[WarehouseNature]	[varchar] (20),                 
		[RackBinCode]		[varchar] (10),              
		[LotID]				[int],                
		[CBQty]				[float],                    
		[BranchID]			[varchar] (3),                    
		[CompID]			[varchar] (3)    
		-- , RunningTotal [float]  
	)                    
AS                      
BEGIN                     
	WITH ItemList_CTE    
	AS               
	(    
		Select *    
		From    
		(    
			Select b.TransactionItem as ItemCode, c.WarehouseCode, c.WarehouseNature, c.RackBinCode, IsNull(d.LotID,0) as LotID,                    
				IsNull(Sum(Case When (b.ToWarehouseCode = c.WarehouseCode and b.ToRackBinCode=c.RackBinCode) Then d.Qty                
				When (b.FromWarehouseCode = c.WarehouseCode and b.FromRackBinCode=c.RackBinCode) Then -d.Qty      
				Else 0 End), 0) as CbQty,                  
				b.BranchID, b.CompID 
			From                          
			(
				
				Select ICode, DOCType, DOCNo, DOCDate, Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) as TransactionDate, 
                    TransactionItem, TransactionQty, Norms, FromWarehouseCode, FromRackBinCode, ToWarehouseCode, ToRackBinCode, ItemGroupKey, 
                    FromItem, ToItem, Justification, LIFO, FIFO, WA, Userid, Branchid, Compid, Finyear 
                From INV_MaterialTran_Dtl a              
				Where a.TransactionItem=@ItemCode and Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) <= @StockDate                    
					and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear = @Finyear     

				Union All

                Select b.ICode, b.DOCType, b.DOCNo, b.DOCDate, Convert(Varchar(10),b.TransactionDate,121) + ' ' + Convert(Varchar(8),b.TransactionTime, 108) as TransactionDate, 
                    a.ItemCode as TransactionItem, b.TransactionQty, b.Norms, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode, b.ItemGroupKey, 
                    b.FromItem, b.ToItem, b.Justification, b.LIFO, b.FIFO, b.WA, b.Userid, b.Branchid, b.Compid, b.Finyear
                From Test_COM_Trace_MaterialTran_TmpQty a              
                Left Outer Join INV_MaterialTran_Dtl b
                    On a.TranID=b.ICode and a.BranchID=b.BranchId and a.CompID=b.CompID and a.Finyear=b.Finyear  
			    Where a.ItemCode=@ItemCode and a.Transtamp <= @StockDate                  
				    and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear = @Finyear and IsNumeric(a.FromWarehouseCode)='1' and a.ToWarehouseCode='DUM'

                Union All

                Select a.TranID as ICode, 'OPB' as DOCType, 1 as DOCNo, '2019-04-01' as DOCDate, '2019-03-31 23:59:59' as TransactionDate, a.ItemCode as TransactionItem, 
                    a.Qty, 1 as Norms, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode, 0 as ItemGroupKey, 
                    a.ItemCode as FromItem, a.ItemCode as ToItem, 'DCSR Pending' as Justification, 0 as LIFO, 0 as FIFO, 0 as WA, a.Userid, a.Branchid, a.Compid, a.Finyear
                From Test_COM_Trace_MaterialTran_TmpQty a  
                Where  a.ItemCode=@ItemCode and a.Transtamp <= @StockDate  and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear = @Finyear   
                    and a.FromWarehouseCode='OPB' and IsNumeric(a.ToWarehouseCode)='1'


                Union All

				Select -(ICode), DOCType, DOCNo, DOCDate, Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) as TransactionDate, 
                    TransactionItem, TransactionQty, Norms, FromWarehouseCode, FromRackBinCode, ToWarehouseCode, ToRackBinCode, ItemGroupKey, 
                    FromItem, ToItem, Justification, LIFO, FIFO, WA, Userid, Branchid, Compid, Finyear 
				From INV_WIPTRAN_DTL a              
				Where a.TransactionItem=@ItemCode and Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) <= @StockDate                    
					and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear = @Finyear                    
					and not exists
						(
							Select * From INV_MaterialTran_Dtl s
							Where s.DocNo=a.DocNo and s.DocDate=a.DocDate and s.DocType=a.DocType and s.TransactionDate=a.TransactionDate 
								and s.TransactionTime=a.TransactionTime and s.TransactionItem=a.TransactionItem and s.FromwarehouseCode=a.FromWarehouseCode
								and s.FromRackBinCode=a.FromRackBinCode and s.TowarehouseCode=a.TowarehouseCode and s.ToRackBinCode=a.ToRackBinCode 
								and s.ItemGroupKey=a.ItemGroupKey and s.FromItem=a.FromItem and s.ToItem=a.ToItem 
								and s.BranchID=a.BranchID and s.CompID=a.CompID and s.Finyear=a.Finyear
						) 
			)b
			Left Outer Join Test_COM_Trace_MaterialTran_TmpQty d          
				On b.ICode=d.TranID and b.BranchID=d.BranchID and b.CompID=d.CompID and b.Finyear=d.Finyear        
                  
			Full Outer Join 
				(
					Select WarehouseCode, '' as RackBinCode, WarehouseNature, BranchID, CompID
					From INV_Warehouse_Master_All c   
		
                    Union all

                    Select 'DUM' as WarehouseCode, '' as RackBinCode, 'DUMMY' as WarehouseNature, @BranchID as BranchID, @CompID as CompID

					Union all

					Select Convert(Varchar,LedgerCode), '' as RackBinCode, 'Ledger' as WarehouseNature, @BranchID as BranchID, @CompID as CompID
					From FAS_LedgerMaster_AuthTbl
					Where Left(LrRoute,4) in ('0303', '0206') and CompCode=@CompID+@BranchID              
				)c 
				On c.BranchID = b.BranchID and c.CompID = b.CompID                    
                    
			Where b.TransactionItem=@ItemCode     
				and c.WarehouseCode in (b.FromWarehouseCode, b.ToWarehouseCode)                    
				and b.TransactionDate <= @StockDate                    
				and b.BranchID = @BranchID and b.CompID = @CompID and b.Finyear = @Finyear 
				--and c.WarehouseCode=@WarehouseCode         
			group by b.TransactionItem, c.WarehouseCode, c.WarehouseNature, c.RackBinCode, d.LotID, b.BranchID, b.CompID                    
		) a    
		Where a.CBQty>0    
	)    
     
	INSERT INTO @RetTable  -- Select * from ItemList_CTE     
	    Select ItemCode, WarehouseCode, WarehouseNature, RackBinCode, LotID, CBQty, BranchID, CompID
	    From ItemList_CTE    
		
    
	RETURN;    
END 

GO

/****** Object:  UserDefinedFunction [dbo].[fn_Test_COM_Trace_AsOnDate_Stock_ItemWHS_LotQty]    Script Date: 17/06/2026 11:38:54 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_Test_COM_Trace_AsOnDate_Stock_ItemWHS_LotQty] (@ItemCode Varchar(30), @WarehouseCode Varchar(6), @ReqQty decimal(15, 5), @StockDate datetime,    
																	    @AsonDate datetime, @RptDate datetime, @BranchID varchar(3),  @CompID varchar(3),  @Finyear varchar(20))      
RETURNS @RetTable TABLE                    
	(
		[ItemCode]			[varchar] (30),                     
		[WarehouseCode]		[varchar] (6),                   
		[WarehouseNature]	[varchar] (20),                 
		[RackBinCode]		[varchar] (10),              
		[LotID]				[int],                
		[CBQty]				[float],                    
		[BranchID]			[varchar] (3),                    
		[CompID]			[varchar] (3)    
		-- , RunningTotal [float]  
	)                    
AS                      
BEGIN                     
	WITH ItemList_CTE    
	AS               
	(    
		Select * , ROW_NUMBER() OVER(ORDER BY a.LotID) as Seq --CONVERT(DECIMAL(15,5),SUM(CbQty) OVER(ORDER BY LotID ROWS UNBOUNDED PRECEDING)) AS RunningTotal    
		From    
		(    
			Select b.TransactionItem as ItemCode, c.WarehouseCode, c.WarehouseNature, c.RackBinCode, IsNull(d.LotID,0) as LotID,                    
				IsNull(Sum(Case When (b.ToWarehouseCode = c.WarehouseCode and b.ToRackBinCode=c.RackBinCode) Then d.Qty                
				When (b.FromWarehouseCode = c.WarehouseCode and b.FromRackBinCode=c.RackBinCode) Then -d.Qty      
				Else 0 End), 0) as CbQty,                  
				b.BranchID, b.CompID 
			From                          
			(
				
				Select '0' as ReverseEntryFlg, ICode, DOCType, DOCNo, DOCDate, Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) as TransactionDate, 
                    TransactionItem, TransactionQty, Norms, FromWarehouseCode, FromRackBinCode, ToWarehouseCode, ToRackBinCode, ItemGroupKey, 
                    FromItem, ToItem, Justification, LIFO, FIFO, WA, Userid, Branchid, Compid, Finyear 
                From INV_MaterialTran_Dtl a              
				Where a.TransactionItem=@ItemCode and Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) <= @StockDate                    
					and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear = @Finyear     

                Union All

                 Select a.ReverseEntryFlg, a.TranID as ICode, 'DUM' as DOCType, 1 as DOCNo, Convert(Varchar(10),a.Transtamp,121) as DOCDate, a.Transtamp as TransactionDate, 
                    a.ItemCode as TransactionItem, a.Qty as TransactionQty, 1 as Norms, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode, 0 as ItemGroupKey, 
                    a.ItemCode as FromItem, a.ItemCode as ToItem, 'DUMMY' as Justification, 0 as LIFO, 0 as FIFO, 0 as WA, a.Userid, a.Branchid, a.Compid, a.Finyear
                From 
                    (
                        Select * From Test_COM_Trace_MaterialTran_TmpQty a       
                        Where a.ItemCode=@ItemCode and a.Transtamp <= @StockDate                
			                and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear = @Finyear  and IsNumeric(a.FromWarehouseCode)='1' and a.ToWarehouseCode='DUM'    
                
                        Union   

                        Select * From Test_COM_Trace_MaterialTran_TmpQty a       
                        Where a.ItemCode=@ItemCode and a.Transtamp <= @StockDate                  
                            and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear = @Finyear and a.FromWarehouseCode='DUM'  and IsNumeric(a.ToWarehouseCode)='1'              
                    )a

                --Select b.ICode, b.DOCType, b.DOCNo, b.DOCDate, Convert(Varchar(10),b.TransactionDate,121) + ' ' + Convert(Varchar(8),b.TransactionTime, 108) as TransactionDate, 
                --    a.ItemCode as TransactionItem, b.TransactionQty, b.Norms, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode, b.ItemGroupKey, 
                --    b.FromItem, b.ToItem, b.Justification, b.LIFO, b.FIFO, b.WA, b.Userid, b.Branchid, b.Compid, b.Finyear
                --From 
                --    (
                --        Select * From Test_COM_Trace_MaterialTran_TmpQty a       
                --        Where a.ItemCode=@ItemCode and a.Transtamp <= @StockDate                
			             --   and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear = @Finyear  and IsNumeric(a.FromWarehouseCode)='1' and a.ToWarehouseCode='DUM'    
                
                --        Union   

                --        Select * From Test_COM_Trace_MaterialTran_TmpQty a       
                --        Where a.ItemCode=@ItemCode and a.Transtamp <= @StockDate                  
                --            and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear = @Finyear and a.FromWarehouseCode='DUM'  and IsNumeric(a.ToWarehouseCode)='1'              
                --    )a
                --Left Outer Join INV_MaterialTran_Dtl b
                --    On a.TranID=b.ICode and a.BranchID=b.BranchId and a.CompID=b.CompID and a.Finyear=b.Finyear  

                Union All

                Select a.ReverseEntryFlg, a.TranID as ICode, 'OPB' as DOCType, 1 as DOCNo, '2019-04-01' as DOCDate, '2019-03-31 23:59:59' as TransactionDate, a.ItemCode as TransactionItem, 
                    a.Qty, 1 as Norms, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode, 0 as ItemGroupKey, 
                    a.ItemCode as FromItem, a.ItemCode as ToItem, 'Opening Balance' as Justification, 0 as LIFO, 0 as FIFO, 0 as WA, a.Userid, a.Branchid, a.Compid, a.Finyear
                From Test_COM_Trace_MaterialTran_TmpQty a  
                Where  a.ItemCode=@ItemCode and a.Transtamp <= @StockDate  and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear = @Finyear   
                    and a.FromWarehouseCode='OPB' and a.ReverseEntryFlg='1' --and IsNumeric(a.ToWarehouseCode)='1'

				Union All

				Select '0' as ReverseEntryFlg, -(ICode), DOCType, DOCNo, DOCDate, Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) as TransactionDate, 
                    TransactionItem, TransactionQty, Norms, FromWarehouseCode, FromRackBinCode, ToWarehouseCode, ToRackBinCode, ItemGroupKey, 
                    FromItem, ToItem, Justification, LIFO, FIFO, WA, Userid, Branchid, Compid, Finyear 
				From INV_WIPTRAN_DTL a              
				Where a.TransactionItem=@ItemCode and Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) <= @StockDate                    
					and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear = @Finyear        
					and not exists
						(
							Select * From INV_MaterialTran_Dtl s
							Where s.DocNo=a.DocNo and s.DocDate=a.DocDate and s.DocType=a.DocType and s.TransactionDate=a.TransactionDate 
								and s.TransactionTime=a.TransactionTime and s.TransactionItem=a.TransactionItem and s.FromwarehouseCode=a.FromWarehouseCode
								and s.FromRackBinCode=a.FromRackBinCode and s.TowarehouseCode=a.TowarehouseCode and s.ToRackBinCode=a.ToRackBinCode 
								and s.ItemGroupKey=a.ItemGroupKey and s.FromItem=a.FromItem and s.ToItem=a.ToItem 
								and s.BranchID=a.BranchID and s.CompID=a.CompID and s.Finyear=a.Finyear
						) 
			)b
			Left Outer Join Test_COM_Trace_MaterialTran_TmpQty d          
				On b.ICode=d.TranID and b.ReverseEntryFlg=d.ReverseEntryFlg and b.BranchID=d.BranchID and b.CompID=d.CompID and b.Finyear=d.Finyear        
                  
			Full Outer Join 
				(
					Select WarehouseCode, '' as RackBinCode, WarehouseNature, BranchID, CompID
					From INV_Warehouse_Master_All c   
		
					Union all

                    Select 'DUM' as WarehouseCode, '' as RackBinCode, 'DUMMY' as WarehouseNature, @BranchID as BranchID, @CompID as CompID

					Union all

					Select Convert(Varchar,LedgerCode), '' as RackBinCode, 'Ledger' as WarehouseNature, @BranchID as BranchID, @CompID as CompID
					From FAS_LedgerMaster_AuthTbl
					Where Left(LrRoute,4) in ('0303', '0206') and CompCode=@CompID+@BranchID              
				)c 
				On c.BranchID = b.BranchID and c.CompID = b.CompID                    
                    
			Where b.TransactionItem=@ItemCode     
				and c.WarehouseCode in (b.FromWarehouseCode, b.ToWarehouseCode)                    
				and b.TransactionDate <= @StockDate                    
				and b.BranchID = @BranchID and b.CompID = @CompID and b.Finyear = @Finyear 
				and c.WarehouseCode=@WarehouseCode         
			group by b.TransactionItem, c.WarehouseCode, c.WarehouseNature, c.RackBinCode, d.LotID, b.BranchID, b.CompID                    
		) a    
		Where a.CBQty>0    
	)    
    ,Item_CTE
	As
	(
		Select a.ItemCode, a.WarehouseCode, a.WarehouseNature, a.RackBinCode, a.LotID, a.CBQty, IsNull(Sum(b.CbQty),0) as RunningTotal, a.BranchID, a.CompID
		From ItemList_CTE a
		Left Outer Join ItemList_CTE b
			On a.Seq>=b.Seq and a.BranchID=b.BranchID and a.CompID=b.CompID
		Group by a.ItemCode, a.WarehouseCode, a.WarehouseNature, a.RackBinCode, a.LotId, a.CbQty, a.BranchID, a.CompID, a.Seq
	)

	INSERT INTO @RetTable  -- Select * from ItemList_CTE     
		Select ItemCode, WarehouseCode, WarehouseNature, RackBinCode, LotID,      
			Case When RunningTotal<@ReqQty Then CBQty Else CBQty-(RunningTotal-@ReqQty) End as CBQty, BranchID, CompID -- , RunningTotal  
		From Item_CTE    
		Where LotID<=(Select Top 1 LotID From Item_CTE Where RunningTotal>=@ReqQty Order By RunningTotal)    
    
	RETURN;    
END 
GO

/****** Object:  UserDefinedFunction [dbo].[fn_TEST20240716_COM_Trace_AsOnDate_Stock]    Script Date: 17/06/2026 11:38:54 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_TEST20240716_COM_Trace_AsOnDate_Stock] (@ItemCode Varchar(30), @StockDate datetime,    
																	@AsonDate datetime, @RptDate datetime, @BranchID varchar(3),  @CompID varchar(3),  @Finyear varchar(20))      
RETURNS @RetTable TABLE                    
	(
		[ItemCode]			[varchar] (30),                     
		[WarehouseCode]		[varchar] (6),                   
		[WarehouseNature]	[varchar] (20),                 
		[RackBinCode]		[varchar] (10),              
		[LotID]				[int],                
		[CBQty]				[float],                    
		[BranchID]			[varchar] (3),                    
		[CompID]			[varchar] (3)    
		-- , RunningTotal [float]  
	)                    
AS                      
BEGIN                     
	DECLARE @PrevFinyear Varchar(20)
        Select @PrevFinyear = '04-' + Convert(Varchar,RIGHT(RTRIM(LTRIM( LEFT(@Finyear,CHARINDEX(' ', @Finyear)))),4) - 1)  
                                + ' ' + '03-' + Convert(Varchar,RIGHT(RTRIM(LTRIM(RIGHT(@Finyear,CHARINDEX(' ', REVERSE(@Finyear))))),4) - 1)

    ;WITH ItemList_CTE    
	AS               
	(    
		Select *    
		From    
		(    
			Select b.TransactionItem as ItemCode, c.WarehouseCode, c.WarehouseNature, c.RackBinCode, IsNull(d.LotID,0) as LotID,                    
				IsNull(Sum(Case When (b.ToWarehouseCode = c.WarehouseCode and b.ToRackBinCode=c.RackBinCode) Then d.Qty                
				When (b.FromWarehouseCode = c.WarehouseCode and b.FromRackBinCode=c.RackBinCode) Then -d.Qty      
				Else 0 End), 0) as CbQty,                  
				b.BranchID, b.CompID 
			From                          
			(
				
				Select ICode, DOCType, DOCNo, DOCDate, Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) as TransactionDate, 
                    TransactionItem, TransactionQty, Norms, FromWarehouseCode, FromRackBinCode, ToWarehouseCode, ToRackBinCode, ItemGroupKey, 
                    FromItem, ToItem, Justification, LIFO, FIFO, WA, Userid, Branchid, Compid, Finyear 
                From INV_MaterialTran_Dtl a              
				Where a.TransactionItem=@ItemCode and Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) <= @StockDate                    
					and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear in (@PrevFinyear,@Finyear)     

				Union All

                Select b.ICode, b.DOCType, b.DOCNo, b.DOCDate, Convert(Varchar(10),b.TransactionDate,121) + ' ' + Convert(Varchar(8),b.TransactionTime, 108) as TransactionDate, 
                    a.ItemCode as TransactionItem, b.TransactionQty, b.Norms, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode, b.ItemGroupKey, 
                    b.FromItem, b.ToItem, b.Justification, b.LIFO, b.FIFO, b.WA, b.Userid, b.Branchid, b.Compid, b.Finyear
                From TEST20240716_COM_Trace_MaterialTran_TmpQty a              
                Left Outer Join INV_MaterialTran_Dtl b
                    On a.TranID=b.ICode and a.BranchID=b.BranchId and a.CompID=b.CompID and a.Finyear=b.Finyear  
			    Where a.ItemCode=@ItemCode and a.Transtamp <= @StockDate                  
				    and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear in (@PrevFinyear,@Finyear) and IsNumeric(a.FromWarehouseCode)='1' and a.ToWarehouseCode='DUM'

                Union All

                Select a.TranID as ICode, 'OPB' as DOCType, 1 as DOCNo, '2019-04-01' as DOCDate, '2019-03-31 23:59:59' as TransactionDate, a.ItemCode as TransactionItem, 
                    a.Qty, 1 as Norms, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode, 0 as ItemGroupKey, 
                    a.ItemCode as FromItem, a.ItemCode as ToItem, 'DCSR Pending' as Justification, 0 as LIFO, 0 as FIFO, 0 as WA, a.Userid, a.Branchid, a.Compid, a.Finyear
                From TEST20240716_COM_Trace_MaterialTran_TmpQty a  
                Where  a.ItemCode=@ItemCode and a.Transtamp <= @StockDate  and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear  in (@PrevFinyear,@Finyear)  
                    and a.FromWarehouseCode='OPB' and IsNumeric(a.ToWarehouseCode)='1'


                Union All

				Select -(ICode), DOCType, DOCNo, DOCDate, Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) as TransactionDate, 
                    TransactionItem, TransactionQty, Norms, FromWarehouseCode, FromRackBinCode, ToWarehouseCode, ToRackBinCode, ItemGroupKey, 
                    FromItem, ToItem, Justification, LIFO, FIFO, WA, Userid, Branchid, Compid, Finyear 
				From INV_WIPTRAN_DTL a              
				Where a.TransactionItem=@ItemCode and Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) <= @StockDate                    
					and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear  in (@PrevFinyear,@Finyear)                    
					and not exists
						(
							Select * From INV_MaterialTran_Dtl s
							Where s.DocNo=a.DocNo and s.DocDate=a.DocDate and s.DocType=a.DocType and s.TransactionDate=a.TransactionDate 
								and s.TransactionTime=a.TransactionTime and s.TransactionItem=a.TransactionItem and s.FromwarehouseCode=a.FromWarehouseCode
								and s.FromRackBinCode=a.FromRackBinCode and s.TowarehouseCode=a.TowarehouseCode and s.ToRackBinCode=a.ToRackBinCode 
								and s.ItemGroupKey=a.ItemGroupKey and s.FromItem=a.FromItem and s.ToItem=a.ToItem 
								and s.BranchID=a.BranchID and s.CompID=a.CompID and s.Finyear=a.Finyear
						) 
			)b
			Left Outer Join TEST20240716_COM_Trace_MaterialTran_TmpQty d          
				On b.ICode=d.TranID and b.BranchID=d.BranchID and b.CompID=d.CompID and b.Finyear=d.Finyear        
                  
			Full Outer Join 
				(
					Select WarehouseCode, '' as RackBinCode, WarehouseNature, BranchID, CompID
					From INV_Warehouse_Master_All c   
		
                    Union all

                    Select 'DUM' as WarehouseCode, '' as RackBinCode, 'DUMMY' as WarehouseNature, @BranchID as BranchID, @CompID as CompID

					Union all

					Select Convert(Varchar,LedgerCode), '' as RackBinCode, 'Ledger' as WarehouseNature, @BranchID as BranchID, @CompID as CompID
					From FAS_LedgerMaster_AuthTbl
					Where Left(LrRoute,4) in ('0303', '0206') and CompCode=@CompID+@BranchID              
				)c 
				On c.BranchID = b.BranchID and c.CompID = b.CompID                    
                    
			Where b.TransactionItem=@ItemCode     
				and c.WarehouseCode in (b.FromWarehouseCode, b.ToWarehouseCode)                    
				and b.TransactionDate <= @StockDate                    
				and b.BranchID = @BranchID and b.CompID = @CompID and b.Finyear  in (@PrevFinyear,@Finyear) 
				--and c.WarehouseCode=@WarehouseCode         
			group by b.TransactionItem, c.WarehouseCode, c.WarehouseNature, c.RackBinCode, d.LotID, b.BranchID, b.CompID                    
		) a    
		Where a.CBQty>0    
	)    
     
	INSERT INTO @RetTable  -- Select * from ItemList_CTE     
	    Select ItemCode, WarehouseCode, WarehouseNature, RackBinCode, LotID, CBQty, BranchID, CompID
	    From ItemList_CTE    
		
    
	RETURN;    
END 
GO

/****** Object:  UserDefinedFunction [dbo].[fn_TEST20240716_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty]    Script Date: 17/06/2026 11:38:54 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_TEST20240716_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty] (@ItemCode Varchar(30), @WarehouseCode Varchar(6), @ReqQty decimal(15, 5), @StockDate datetime, @AsonDate datetime, @RptDate datetime, @BranchID varchar(3),  @CompID varchar(3),  @Finyear varchar(20))          
RETURNS @RetTable TABLE                        
    (    
        [ItemCode]   [varchar] (30),                         
        [WarehouseCode]  [varchar] (6),                       
        [WarehouseNature] [varchar] (20),                     
        [RackBinCode]  [varchar] (10),                  
        [LotID]    [bigint],      
        [SubLotID]    [int],                    
        [CBQty]    [float],        
        [Seq]		[int],                
        [BranchID]   [varchar] (3),                        
        [CompID]   [varchar] (3)        
        -- , RunningTotal [float]      
    )                        
AS                          
BEGIN 
    
    DECLARE @PrevFinyear Varchar(20)
        Select @PrevFinyear = '04-' + Convert(Varchar,RIGHT(RTRIM(LTRIM( LEFT(@Finyear,CHARINDEX(' ', @Finyear)))),4) - 1)  
                                + ' ' + '03-' + Convert(Varchar,RIGHT(RTRIM(LTRIM(RIGHT(@Finyear,CHARINDEX(' ', REVERSE(@Finyear))))),4) - 1)

    DECLARE @TraceReImportFinStart Varchar(20)
        Select @TraceReImportFinStart='04-2024 03-2025'

    ;WITH ItemList_CTE        
    AS                   
    (        
        Select * , ROW_NUMBER() OVER(ORDER BY a.LotID, a.SubLotId) as Seq --CONVERT(DECIMAL(15,5),SUM(CbQty) OVER(ORDER BY LotID ROWS UNBOUNDED PRECEDING)) AS RunningTotal        
        From        
        (        
            Select b.TransactionItem as ItemCode, c.WarehouseCode, c.WarehouseNature, c.RackBinCode, IsNull(d.LotID,0) as LotID,  IsNull(d.SubLotID,0) as SubLotID,                     
                CONVERT(DECIMAL(15,5),IsNull(Sum(Case When (b.ToWarehouseCode = c.WarehouseCode and b.ToRackBinCode=c.RackBinCode) Then d.Qty                    
                When (b.FromWarehouseCode = c.WarehouseCode and b.FromRackBinCode=c.RackBinCode) Then -d.Qty          
                Else 0 End), 0)) as CbQty,                      
                b.BranchID, b.CompID     
            From                              
            (    
        
                Select '0' as ReverseEntryFlg, ICode, DOCType, DOCNo, DOCDate, Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) as TransactionDate,     
                    TransactionItem, TransactionQty, Norms, FromWarehouseCode, FromRackBinCode, ToWarehouseCode, ToRackBinCode, ItemGroupKey,     
                    FromItem, ToItem, Justification, LIFO, FIFO, WA, Userid, Branchid, Compid, Finyear     
                From INV_MaterialTran_Dtl a                  
                Where a.TransactionItem=@ItemCode and Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) <= @StockDate                        
                    and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear>=@TraceReImportFinStart  --and a.Finyear in (@PrevFinyear,@Finyear)         
    
                Union All    
    
                Select a.ReverseEntryFlg, a.TranID as ICode, 'DUM' as DOCType, 1 as DOCNo, Convert(Varchar(10),a.Transtamp,121) as DOCDate, a.Transtamp as TransactionDate,     
                    a.ItemCode as TransactionItem, a.Qty as TransactionQty, 1 as Norms, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode, 0 as ItemGroupKey,     
                    a.ItemCode as FromItem, a.ItemCode as ToItem, 'DUMMY' as Justification, 0 as LIFO, 0 as FIFO, 0 as WA, a.Userid, a.Branchid, a.Compid, a.Finyear    
                From     
                (    
                    Select a.ReverseEntryFlg, a.TranID, a.Transtamp, a.ItemCode,  Sum(a.Qty) as Qty, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode,
						a.Userid, a.Branchid, a.Compid, a.Finyear  
					From TEST20240716_COM_Trace_MaterialTran_TmpQty a           
                    Where a.ItemCode=@ItemCode and a.Transtamp <= @StockDate                  
                        and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear>=@TraceReImportFinStart --and a.Finyear in (@PrevFinyear,@Finyear)  
                        and IsNumeric(a.FromWarehouseCode)='1' and a.ToWarehouseCode='DUM'        
                    Group by a.ReverseEntryFlg, a.TranID, a.Transtamp, a.ItemCode, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode,
						a.Userid, a.Branchid, a.Compid, a.Finyear 

                    Union       
    
                    Select a.ReverseEntryFlg, a.TranID, a.Transtamp, a.ItemCode,  Sum(a.Qty) as Qty, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode,
						a.Userid, a.Branchid, a.Compid, a.Finyear  
					From TEST20240716_COM_Trace_MaterialTran_TmpQty a           
                    Where a.ItemCode=@ItemCode and a.Transtamp <= @StockDate                      
                        and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear>=@TraceReImportFinStart --and a.Finyear in (@PrevFinyear,@Finyear) 
                        and a.FromWarehouseCode='DUM'  and IsNumeric(a.ToWarehouseCode)='1'  
					Group by a.ReverseEntryFlg, a.TranID, a.Transtamp, a.ItemCode, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode,
						a.Userid, a.Branchid, a.Compid, a.Finyear 
                )a    
    
                Union All    
    
                Select a.ReverseEntryFlg, a.TranID as ICode, 'OPB' as DOCType, 1 as DOCNo, '2024-04-01' as DOCDate, '2024-03-31 23:59:59' as TransactionDate, a.ItemCode as TransactionItem,     
                    a.Qty, 1 as Norms, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode, 0 as ItemGroupKey,     
                    a.ItemCode as FromItem, a.ItemCode as ToItem, 'Opening Balance' as Justification, 0 as LIFO, 0 as FIFO, 0 as WA, a.Userid, a.Branchid, a.Compid, a.Finyear    
                From TEST20240716_COM_Trace_MaterialTran_TmpQty a      
                Where  a.ItemCode=@ItemCode and a.Transtamp <= @StockDate  and a.BranchID = @BranchID and a.CompID = @CompID  and a.Finyear>=@TraceReImportFinStart
                    --and a.Finyear in (@PrevFinyear,@Finyear)      
                    and a.FromWarehouseCode='OPB' and a.ReverseEntryFlg='1' --and IsNumeric(a.ToWarehouseCode)='1'    
    
                Union All    
    
                Select '0' as ReverseEntryFlg, -(ICode), DOCType, DOCNo, DOCDate, Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) as TransactionDate,     
                TransactionItem, TransactionQty, Norms, FromWarehouseCode, FromRackBinCode, ToWarehouseCode, ToRackBinCode, ItemGroupKey,     
                FromItem, ToItem, Justification, LIFO, FIFO, WA, Userid, Branchid, Compid, Finyear     
                From INV_WIPTRAN_DTL a                  
                Where a.TransactionItem=@ItemCode and Convert(Varchar(10),a.TransactionDate,121) + ' ' + Convert(Varchar(8),a.TransactionTime, 108) <= @StockDate                        
                and a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear>=@TraceReImportFinStart  --and a.Finyear in (@PrevFinyear,@Finyear)            
                and not exists    
                    (    
                        Select * From INV_MaterialTran_Dtl s    
                        Where s.DocNo=a.DocNo and s.DocDate=a.DocDate and s.DocType=a.DocType and s.TransactionDate=a.TransactionDate     
                        and s.TransactionTime=a.TransactionTime and s.TransactionItem=a.TransactionItem and s.FromwarehouseCode=a.FromWarehouseCode    
                        and s.FromRackBinCode=a.FromRackBinCode and s.TowarehouseCode=a.TowarehouseCode and s.ToRackBinCode=a.ToRackBinCode     
                        and s.ItemGroupKey=a.ItemGroupKey and s.FromItem=a.FromItem and s.ToItem=a.ToItem     
                        and s.BranchID=a.BranchID and s.CompID=a.CompID and s.Finyear=a.Finyear    
                    )  
					
				Union All    

				Select a.ReverseEntryFlg, a.TranID as ICode, 'OPB' as DOCType, -3 as DOCNo, Convert(Varchar(10),a.Transtamp,121) as DOCDate, a.Transtamp as TransactionDate, a.ItemCode as TransactionItem,     
                    a.Qty, 1 as Norms, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode, 0 as ItemGroupKey,     
                    a.ItemCode as FromItem, a.ItemCode as ToItem, 'Missing Stock' as Justification, 0 as LIFO, 0 as FIFO, 0 as WA, a.Userid, a.Branchid, a.Compid, a.Finyear    
                From TEST20240716_COM_Trace_MaterialTran_TmpQty a      
                Where  a.ItemCode=@ItemCode and a.Transtamp <= @StockDate  and a.BranchID = @BranchID and a.CompID = @CompID  and a.Finyear>=@TraceReImportFinStart
                    and a.FromWarehouseCode='SV' and a.ReverseEntryFlg='1' and a.UserID=-3  
            )b    
            Left Outer Join TEST20240716_COM_Trace_MaterialTran_TmpQty d              
                On b.ICode=d.TranID and b.ReverseEntryFlg=d.ReverseEntryFlg and b.BranchID=d.BranchID and b.CompID=d.CompID and b.Finyear=d.Finyear            
                      
            Full Outer Join     
            (    
                Select WarehouseCode, RackBinCode, WarehouseNature, BranchID, CompID		--'' as RackBinCode
                From fn_INV_Warehouse_Master_Get_All('1',@AsonDate,@RptDate,@BranchID,@CompID,@Finyear)c	--INV_Warehouse_Master_All c       
      
                Union all    
    
                Select 'DUM' as WarehouseCode, '' as RackBinCode, 'DUMMY' as WarehouseNature, @BranchID as BranchID, @CompID as CompID    
    
                Union all    
    
                Select Convert(Varchar,LedgerCode), '' as RackBinCode, 'Ledger' as WarehouseNature, @BranchID as BranchID, @CompID as CompID    
				From FAS_LedgerMaster_AuthTbl    
                Where Left(LrRoute,4) in ('0303', '0206') and CompCode=@CompID+@BranchID                  
            )c     
            On c.BranchID = b.BranchID and c.CompID = b.CompID                        
                        
            Where b.TransactionItem=@ItemCode         
                and c.WarehouseCode in (b.FromWarehouseCode, b.ToWarehouseCode)                        
                and b.TransactionDate <= @StockDate                        
                and b.BranchID = @BranchID and b.CompID = @CompID and b.Finyear>=@TraceReImportFinStart --and b.Finyear in (@PrevFinyear,@Finyear)   
                and c.WarehouseCode=@WarehouseCode             
            group by b.TransactionItem, c.WarehouseCode, c.WarehouseNature, c.RackBinCode, d.LotID, d.SubLotID, b.BranchID, b.CompID                        
            ) a        
        Where a.CBQty>0        
    )        
    ,Item_CTE    
    As 
    (    
        Select a.ItemCode, a.WarehouseCode, a.WarehouseNature, a.RackBinCode, a.LotID, a.SubLotID, 
			a.CBQty, IsNull(Sum(b.CbQty),0) as RunningTotal, a.BranchID, a.CompID, a.Seq    
        From ItemList_CTE a    
        Left Outer Join ItemList_CTE b    
            On a.Seq>=b.Seq and a.BranchID=b.BranchID and a.CompID=b.CompID    
        Group by a.ItemCode, a.WarehouseCode, a.WarehouseNature, a.RackBinCode, a.LotId, a.SubLotID, a.CbQty, a.BranchID, a.CompID, a.Seq    
    )    
    
    INSERT INTO @RetTable  -- Select * from ItemList_CTE         
        Select ItemCode, WarehouseCode, WarehouseNature, RackBinCode, LotID, SubLotID,        
            Case When RunningTotal<@ReqQty Then CBQty Else CBQty-(RunningTotal-@ReqQty) End as CBQty, Seq,  BranchID, CompID  -- , RunningTotal      
        From Item_CTE        
        Where LotID<=(Select Top 1 LotID From Item_CTE Where RunningTotal>=@ReqQty Order By RunningTotal)        
        
 RETURN;        
END     
GO

/****** Object:  UserDefinedFunction [dbo].[fn_QC_BaseDoc_RR_WholeLotRejected]    Script Date: 17/06/2026 11:38:54 ******/
