GO

CREATE Function [dbo].[fn_QC_BaseDoc_RR_WholeLotRejected] (@BranchID Varchar(3), @CompID Varchar(3), @Finyear Varchar(20))            
            
Returns Table            
            
Return            
            
 (
	Select a.BaseDocumentType as ReceiptEntryType, a.BaseDocumentNo as ReceiptEntryNo, a.BaseDocumentDate as ReceiptEntryDate, a.InspectionType, a.InspectionNo, a.InspectionDate,  a.ItemCode, 
			a.LotSize, a.ReceivedQty, b.Qty as CriteriaQty, a.ReInspected, a.BranchID, a.CompId, a.Finyear
	from QC_Inspection_Hdr1 a
	Left Outer Join QC_Inspection_Criteria1 b
	On a.InspectionType=b.InspectionType and a.InspectionNo=b.InspectionNo and a.InspectionDate=b.InspectionDate and a.BranchId=b.BranchId and a.CompID=b.CompID and a.Finyear=b.Finyear
	Where DocType='RE' and b.CriteriaCode=2 and a.BranchId=@BranchID and a.CompId=@CompID and a.Finyear=@Finyear  
		and Exists (Select * from REC_RECEIPTENTRY_HDR m
						Where m.Finyear=@Finyear and m.InwardType='P' and a.BaseDocumentType=m.ReceiptEntryType and a.BaseDocumentNo=m.ReceiptEntryNo and a.BaseDocumentDate=m.ReceiptEntryDate
								and a.BranchID=m.BranchId and a.CompId=m.CompID
					)
)
GO

