SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

 CREATE Function [dbo].[fn_REC_Get_RRDocument_WholeLotRejected] (@BranchID Varchar(3), @CompID Varchar(3), @Finyear Varchar(20))              
              
Returns Table              
              
Return              
              
 (  
     Select a.InwardType, a.ReceiptEntryType, a.ReceiptEntryNo, a.ReceiptEntryDate, a.VendorCode, b.RefType, b.RefNo, b.RefDate, b.Scheduledate,   
         b.ItemGroupKey, b.ItemCode, b.ChallanQty, b.ReceiptQty, b.AcceptedQty, b.RejectionQty, b.ScrapQty, b.AcceptedQty as InspectionQty, /*c.CriteriaQty as InspectionQty,*/ 
         a.BranchID, a.CompId, a.Finyear  
     From REC_RECEIPTENTRY_HDR a  
     Left Outer Join REC_RECEIPTENTRY_Dtl b  
        On a.ReceiptEntryType=b.ReceiptEntryType and a.ReceiptEntryNo=b.ReceiptEntryNo and a.ReceiptEntryDate=b.ReceiptEntryDate   
        and a.BranchID=b.BranchID and a.CompID=b.CompID and a.Finyear=b.Finyear  
     Left Outer Join [fn_QC_BaseDoc_RR_WholeLotRejected] (@BranchID, @CompID, @Finyear) c  
        On c.ReceiptEntryType=b.ReceiptEntryType and c.ReceiptEntryNo=b.ReceiptEntryNo and c.ReceiptEntryDate=b.ReceiptEntryDate   
        and c.ItemCode=b.ItemCode and c.BranchID=b.BranchID and c.CompID=b.CompID and c.Finyear=b.Finyear  
     Where a.InwardType='P' and b.Rejectionqty>0 and b.AcceptedQty=0 and a.Finyear=@Finyear and a.BranchId=@BranchID and a.CompId=@CompID and b.ReceiptQty=b.RejectionQty  
        and b.RejectionQty=c.CriteriaQty  
 )
GO

