CREATE Function [dbo].[fn_BOM_ECN](@AsOnDate datetime, @RptDate datetime, @BranchID Varchar(3), @CompID Varchar(3), @Finyear Varchar(20))  
  
Returns Table  
  
Return  
  
 (    
  
 Select a.DocType, a.DocNo, a.DocDate, a.ItemCode, a.Source, a.TargetDate, a.ModificationDetails, a.ModificationReason,   
 b.Fields, b.BackEndField, b.Remarks, IsNull(c.ReqStatus,'') as ReqStatus, a.EffStatus, a.EffDate, a.branchid,a.compid, a.TranStamp  
 From dbo.fn_BOM_ECN_Hdr(@AsOnDate,@RptDate,@BranchID,@CompID, @Finyear)a  
 Left Outer Join dbo.fn_BOM_ECN_Dtl(@AsOnDate,@RptDate,@BranchID,@CompID, @Finyear)b  
 On a.DocNo = b.DocNo and a.DocDate = b.DocDate and a.DocType = b.DocType and a.BranchID = b.BranchID and a.CompID = b.CompID  
 Left Outer Join dbo.fn_BOM_ECN_Status(@AsOnDate,@RptDate,@BranchID,@CompID, @Finyear)c  
 On a.DocNo = c.DocNo and a.DocDate = c.DocDate and a.DocType = c.DocType and a.ItemCode= c.ItemCode   
 and a.BranchID = c.BranchID and a.CompID = c.CompID  
  
)  
GO

