/****** Object:  UserDefinedFunction [dbo].[fn_INV_ToolLogStatus]    Script Date: 17/06/2026 11:38:54 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE FUNCTION [dbo].[fn_INV_ToolLogStatus] ( @AsOnDate datetime, @BranchID varchar(3), @CompID varchar(3))  


RETURNS   TABLE
		

AS

Return


	 (Select ItemCode,MachineCode,ToolCode,Toolassetcode,Totallife,
		Case when z.Regrind=1 then RegrindLife else -1 end RegrindLife,Case when z.Reform=1 then Reformlife else -1 end Reformlife,Case when z.Corner=1 then Noofcorner else -1 end Noofcorner,
		Ballife,Case when z.Regrind=1 then RdbalLife else -1 end RdbalLife,Case when z.Reform=1 then RfmbalLife else -1 end RfmbalLife,y.Branchid,y.Compid
		from (
			Select ITemCode,MachineCode,ToolCode,TypeofTool,Toolassetcode,Totallife,RegrindLife,Reformlife,Noofcorner,
				Case when RdLife=0 and RfmLife=0  then Totallife-LogQty else Totallife-(Case when RdLife<RfmLife then RfmLife else RdLife end) - (Case when RdLife<RfmLife then RfmbalLife else RdbalLife end)  end  as Ballife ,
				Case when RdLife=0 and RfmLife=0  then RegrindLife-LogQty else RegrindLife-RdbalLife  end  as RdbalLife ,
				Case when RdLife=0 and RfmLife=0  then Reformlife-LogQty else Reformlife- RfmbalLife  end  as RfmbalLife ,Branchid,Compid
			from (
				Select Distinct b.ITemCode,b.MachineCode,b.ToolCode,b.TypeofTool,a.ToolCode+a.AssetCode as Toolassetcode,b.Totallife,RegrindLife,Reformlife,Noofcorner,
					(Select isnull(Count(*),0)  from INV_ToolTran_Dtl where ToolassetCode=a.ToolCode+a.AssetCode and isReceipt=0 and ToolStatus in (2,4) and Branchid=a.Branchid and Compid=a.Compid and Transactiontime<=@AsOnDate)*RegrindLife as RdLife,
					(Select  isnull(Count(*),0) from INV_ToolTran_Dtl where ToolassetCode=a.ToolCode+a.AssetCode and isReceipt=0 and ToolStatus=3 and Branchid=a.Branchid and Compid=a.Compid and Transactiontime<=@AsOnDate)*Reformlife as RfmLife,
		
					isnull(
						(
							Select Sum(TranQty) from INV_ToolTran_Dtl x where ToolassetCode=a.ToolCode+a.AssetCode and Branchid=a.Branchid and Compid=a.Compid and Transactiontime<=@AsOnDate
						),0)LogQty,

					isnull(
						(
							Select Sum(TranQty) from INV_ToolTran_Dtl x where ToolassetCode=a.ToolCode+a.AssetCode and TransactionTime>=(
							Select top 1 Transactiontime from INV_ToolTran_Dtl where ToolAssetcode=x.ToolassetCode and isReceipt=0 and ToolStatus in(2,4) and Transactiontime<=@AsOnDate and Branchid=a.Branchid and Compid=a.Compid order by Transactiontime desc
						)
						and Branchid=a.Branchid and Compid=a.Compid and Transactiontime<=@AsOnDate
						),0)RdbalLife,
		
					isnull(
						(
							Select Sum(TranQty) from INV_ToolTran_Dtl x where ToolassetCode=a.ToolCode+a.AssetCode and TransactionTime>=(
							Select top 1 Transactiontime from INV_ToolTran_Dtl where ToolAssetcode=x.ToolassetCode	and isReceipt=0 and ToolStatus=3 and Transactiontime<=@AsOnDate and Branchid=a.Branchid and Compid=a.Compid order by Transactiontime desc
						)
						and Branchid=a.Branchid and Compid=a.Compid and Transactiontime<=@AsOnDate
						),0)RfmbalLife,
					a.Branchid,a.Compid
		
		 	from BOM_ToolAssetMaster a 
				left outer join  dbo.fn_BOM_Stagewisetoolmaster_dtl(@AsOnDate,@BranchID ,@CompID) b
					on b.ToolCode=a.ToolCode and b.branchid=a.branchid and b.compid=a.compid
			)x
		)y
		Left outer join BOM_ToolType z
			on z.ToolTypeCode = y.TypeofTool and z.Branchid=y.Branchid and z.Compid=y.Compid
			
)
GO

/****** Object:  UserDefinedFunction [dbo].[fn_INV_ToolLog_ID_Status]    Script Date: 17/06/2026 11:38:54 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE FUNCTION [dbo].[fn_INV_ToolLog_ID_Status] ( @AsOnDate datetime, @MachineCode Varchar(20),@ItemCode Varchar(20),@ToolAssetCode Varchar(20),@BranchID varchar(3), @CompID varchar(3))  


RETURNS   TABLE
		

AS

Return


	 (Select ItemCode,MachineCode,ToolCode,Toolassetcode,Totallife,
		Case when z.Regrind=1 then RegrindLife else -1 end RegrindLife,Case when z.Reform=1 then Reformlife else -1 end Reformlife,Case when z.Corner=1 then Noofcorner else -1 end Noofcorner,
		Ballife,Case when z.Regrind=1 or z.Corner=1 then RdbalLife else -1 end RdbalLife,Case when z.Reform=1 then RfmbalLife else -1 end RfmbalLife,y.Branchid,y.Compid, z.Regrind, z.Corner,z.Reform,TypeofTool
		from (
			Select Distinct ITemCode,MachineCode,ToolCode,TypeofTool,Toolassetcode,Totallife,RegrindLife,Reformlife,Noofcorner,
				Case when RdLife=0 and RfmLife=0  then Totallife-LogQty else Totallife-(Case when RdLife<RfmLife then RfmLife else RdLife end) - (Case when RdLife<RfmLife then RfmbalLife else RdbalLife end)  end  as Ballife ,
				Case when RdLife=0 and RfmLife=0  then RegrindLife-LogQty else RegrindLife-RdbalLife  end  as RdbalLife ,
				Case when RdLife=0 and RfmLife=0  then Reformlife-LogQty else Reformlife- RfmbalLife  end  as RfmbalLife ,Branchid,Compid
			from (
				Select Distinct b.ITemCode,b.MachineCode,b.ToolCode,b.TypeofTool,a.ToolCode+a.AssetCode as Toolassetcode,b.Totallife,RegrindLife,Reformlife,Noofcorner,
					(Select isnull(Count(*),0)  from INV_ToolTran_Dtl where ToolassetCode=a.ToolCode+a.AssetCode and isReceipt=0 and ToolStatus in (2,4) and Branchid=a.Branchid and Compid=a.Compid and Transactiontime<=@AsOnDate)*RegrindLife as RdLife,
					(Select  isnull(Count(*),0) from INV_ToolTran_Dtl where ToolassetCode=a.ToolCode+a.AssetCode and isReceipt=0 and ToolStatus=3 and Branchid=a.Branchid and Compid=a.Compid and Transactiontime<=@AsOnDate)*Reformlife as RfmLife,
		
					isnull(
						(
							Select Sum(TranQty) from INV_ToolTran_Dtl x where ToolassetCode=a.ToolCode+a.AssetCode and Branchid=a.Branchid and Compid=a.Compid and Transactiontime<=@AsOnDate
						),0)LogQty,

					isnull(
						(
							Select Sum(TranQty) from INV_ToolTran_Dtl x where ToolassetCode=a.ToolCode+a.AssetCode and TransactionTime>=(
							Select top 1 Transactiontime from INV_ToolTran_Dtl where ToolAssetcode=x.ToolassetCode and isReceipt=0 and ToolStatus in(2,4) and Transactiontime<=@AsOnDate and Branchid=a.Branchid and Compid=a.Compid order by Transactiontime desc
						)
						and Branchid=a.Branchid and Compid=a.Compid and Transactiontime<=@AsOnDate
						),0)RdbalLife,
		
					isnull(
						(
							Select Sum(TranQty) from INV_ToolTran_Dtl x where ToolassetCode=a.ToolCode+a.AssetCode and TransactionTime>=(
							Select top 1 Transactiontime from INV_ToolTran_Dtl where ToolAssetcode=x.ToolassetCode	and isReceipt=0 and ToolStatus=3 and Transactiontime<=@AsOnDate and Branchid=a.Branchid and Compid=a.Compid order by Transactiontime desc
						)
						and Branchid=a.Branchid and Compid=a.Compid and Transactiontime<=@AsOnDate
						),0)RfmbalLife,
					a.Branchid,a.Compid
		
		 	from BOM_ToolAssetMaster a 
				left outer join  dbo.fn_BOM_Stagewisetoolmaster_dtl(@AsOnDate,@BranchID ,@CompID) b
					on b.ToolCode=a.ToolCode and b.branchid=a.branchid and b.compid=a.compid
					Where a.ToolCode+a.AssetCode=@ToolAssetCode and b.MachineCode=@MachineCode and b.ItemCode=@ItemCode 
			)x
		)y
		Left outer join BOM_ToolType z
			on z.ToolTypeCode = y.TypeofTool and z.Branchid=y.Branchid and z.Compid=y.Compid
			
)
GO

/****** Object:  UserDefinedFunction [dbo].[fn_INV_Tool_Monitor]    Script Date: 17/06/2026 11:38:54 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE FUNCTION [dbo].[fn_INV_Tool_Monitor] ( @AsOnDate datetime, @BranchID varchar(3), @CompID varchar(3))  


RETURNS  TABLE

AS

RETURN
	 (Select x.ToolCode,r.ItemDescription,x.ToolAssetCode,z.Regrindlife,z.Reformlife,z.Totallife,x.StageCode,x.MachineCode,x.TransactionTime as IssueTime,m.Description as IssueStatus,
		y.TransactionTime as ReceivedTime,n.Description as ReceivedStatus,isnull(y.TranQty,0)LogQty,
		x.Branchid,x.Compid,x.Finyear from 
		
		(	Select *,(Select Count(*) from INV_ToolTran_Dtl where ToolCode=a.ToolCode and MachineCode=a.MachineCode 
				and StageCode=a.StageCode and Branchid=a.Branchid and Compid=a.Compid and IsReceipt=a.Isreceipt 
				and Transtamp<=a.Transtamp)Sno
			from INV_ToolTran_Dtl a where IsReceipt=0
		)x
		
		left outer join 
		
		(	Select *,(Select Count(*) from INV_ToolTran_Dtl where ToolCode=a.ToolCode and MachineCode=a.MachineCode 
				and StageCode=a.StageCode and Branchid=a.Branchid and Compid=a.Compid and IsReceipt=a.Isreceipt 
				and Transtamp<=a.Transtamp)Sno
			from INV_ToolTran_Dtl a where IsReceipt=1
		)y
			
			on y.ToolCode=x.ToolCode and y.MachineCode=x.MachineCode and y.StageCode=x.StageCode and y.Sno=x.Sno
				and y.Branchid=x.Branchid and y.Compid=x.Compid  and y.Finyear=x.Finyear
		
		Left outer join INV_ToolStatus_Master m
			on m.Code=x.ToolStatus and m.Type='I'
		
		Left outer join INV_ToolStatus_Master n
			on n.Code=y.ToolStatus and n.Type='R'

		Left outer join INV_Material_Master r
			on r.ItemCode=x.Toolcode and r.Branchid=x.Branchid and r.Compid=x.Compid

		Left outer join  dbo.fn_BOM_Stagewisetoolmaster_dtl(@AsOnDate,@BranchID ,@CompID) z
					on z.ToolCode=x.ToolCode  and z.MachineCode=x.MachineCode and z.ItemCode=x.StageCode and z.branchid=x.branchid and z.compid=x.compid
		
		where x.Branchid=@Branchid and x.Compid=@Compid)
GO

