CREATE Function [dbo].[fn_INV_Get_Warehouse_Master_Virtual](@fOpration Char(1), @AsOnDate datetime, @RptDate datetime, 
	@BranchID Varchar(3), @CompID Varchar(3), @Finyear Varchar(20))        
Returns Table        
Return    
(     
   Select * from   
	(  
	 Select Distinct FromwarehouseCode From INV_Materialtran_dtl  
	 WHERE ISNUMERIC(FromwarehouseCode)=0 and Branchid = @BranchID and compid=@CompID and Finyear = @Finyear  
	 union  
	 Select Distinct TowarehouseCode From INV_Materialtran_dtl  
	 Where ISNUMERIC(TowarehouseCode)=0 and Branchid = @BranchID and compid=@CompID and Finyear = @Finyear  
	) x  
	where x.FromwarehouseCode Not In(Select WarehouseCode From INV_Warehouse_Master		-- dbo.fn_INV_Warehouse_Master(@fOpration, @AsOnDate, @RptDate, @BranchID, @CompID)             
									Union            
									Select WarehouseCode From INV_WarehouseTemp_Master    
								)       
)  
GO

/****** Object:  UserDefinedFunction [dbo].[fn_INV_Get_Warehouse_Master_All]    Script Date: 17/06/2026 11:38:54 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE Function [dbo].[fn_INV_Get_Warehouse_Master_All](@fOpration Char(1), @AsOnDate datetime, @RptDate datetime, 
 @BranchID Varchar(3), @CompID Varchar(3),@Finyear varchar(20))          
Returns Table          
Return          
  (           
      
    Select a.WarehouseCode, a.WarehouseName, a.WarehouseNature, a.WarehouseLocation, 0 As RevNo, NULL As RevDate, a.WarehouseStatus As EffStatus, NULL As EffDate,      
        isNull(b.RackBinCode, '') as RackBinCode, isNull(b.Description, '') as RackBinDesc,       
        Null as RBRevNo, Null as RBRevDate, Null as RBEffStatus, NULL as RBEffDate,      
        a.BranchID, a.CompID      
  From INV_Warehouse_Master a		--dbo.fn_INV_Warehouse_Master(@fOpration, @AsOnDate, @RptDate, @BranchID, @CompID) a      
  Left Outer Join INV_RackBin_Master b		--dbo.fn_INV_Get_RackBin_Master(@fOpration, @AsOnDate, @RptDate, @BranchID, @CompID) b      
	On a.WarehouseCode=b.WarehouseCode and a.BranchID=b.BranchID and a.CompID=b.CompID      
                  
  UNION ALL  
                  
  Select m.WarehouseCode, m.WarehouseName, m.WarehouseNature, m.WarehouseLocation, 0 As RevNo, NULL As RevDate, m.WarehouseStatus As EffStatus, NULL As EffDate,      
        '' as RackBinCode, '' as RackBinDesc, Null as RevNo,  Null as RevDate, Null as EffStatus, Null as EffDate,      
        m.BranchID, m.CompID      
  From INV_WarehouseTemp_Master m     
    
  UNION ALL  
        
  Select FromWarehouseCode,FromWarehouseCode+'-VIRTUAL','INHOUSE','INFANT',0 RevNo, NULL, 'A',NULL,  
    '' as RackBinCode, '' as RackBinDesc, Null as RevNo,  Null as RevDate, Null as EffStatus, Null as EffDate,    
    @BranchID, @CompID   
  From dbo.fn_INV_Get_Warehouse_Master_Virtual(@fOpration, @AsOnDate, @RptDate, @BranchID, @CompID, @Finyear)            
)  
GO

/****** Object:  UserDefinedFunction [dbo].[fn_COM_CountryCity_Master]    Script Date: 17/06/2026 11:38:54 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [dbo].[fn_COM_CountryCity_Master] (@Filter char(1)='A', @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3))          
--@Filter = ('1', 'M') returns Max Transtamp Data; @Filter=('0', 'A') returns Max Authorised Data, @Filter='H'/'D'/'X' returns Max Hold/Delete/Cancel Data        
        
RETURNS TABLE        
         
 AS          
        
Return         
        
  (        
   Select *          
  From COM_CountryCity_Master a        
  Where a.TranStamp = (Select Max(b.TranStamp) from COM_CountryCity_Master b         
               Where b.TranStamp <= @AsOnDate         
      and ((@Filter in ('1', 'M'))         
       OR (b.isTranLock='1'         
        AND Not Exists (Select * from COM_CountryCity_Master c         
          Where c.TranStamp>b.TranStamp and c.EffStatus Like 'X%'         
           and b.ChildCode = c.ChildCode        
            and b.ParentCode=c.ParentCode        
          )        
         )         
       OR (@Filter Not in ('1', 'M') and b.EffStatus Like 'A%' and b.EffDate<=@RptDate)        
       )         
               and b.ChildCode = a.ChildCode and b.ParentCode=a.ParentCode                    
             )        
   and a.EffStatus Like Case When @Filter in ('1', 'M') Then '%' When @Filter in ('0', 'A') Then 'AA' When @Filter='H' Then 'AH' When @Filter='D' Then 'AD' When @Filter='X' Then 'AX' Else 'A%' End        
           
  )
GO

/****** Object:  UserDefinedFunction [dbo].[fn_COM_Get_CountryStateCity_Dtl]    Script Date: 17/06/2026 11:38:54 ******/
SET ANSI_NULLS ON
