GO


CREATE FUNCTION [dbo].[fn_COM_Get_CountryStateCity_Dtl](@AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3))    
RETURNS TABLE             
 AS               
Return           
          
  (          
  Select Isnull(a.ChildCode,0) as CountryCode, Isnull(a.ChildName,'') as CountryName,     
   Isnull(b.ChildCode,0) as StateCode, Isnull(b.ChildName,'') as StateName,  IsNull(b.TypeCode,'') as StateTypeCode,    
   Isnull(c.ChildCode,0) as CityCode,  c.ChildName as CityName         
  From dbo.fn_COM_COUNTRYCITY_MASTER('A',@AsOnDate, @RptDate, @BranchID, @CompID) a          
  Left Outer Join dbo.fn_COM_COUNTRYCITY_MASTER('A',@AsOnDate, @RptDate, @BranchID, @CompID) b          
  On b.ParentCode =a.ChildCode          
  Left Outer Join dbo.fn_COM_COUNTRYCITY_MASTER('A', @AsOnDate, @RptDate, @BranchID, @CompID) c          
  On c.ParentCode =b.ChildCode         
  Where a.ParentCode=0    
)
GO

/****** Object:  UserDefinedFunction [dbo].[fn_BOM_Get_Material_AssetItem_MasterCode]    Script Date: 17/06/2026 11:38:54 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_BOM_Get_Material_AssetItem_MasterCode] (@Filter char(1), @AsOnDate datetime, @RptDate datetime,
    @BranchID varchar(3), @CompID varchar(3))            
RETURNS TABLE          
RETURN          
(          
 WITH Item_CTE(/*ItemID,*/ ItemCode, AssetCode, ItemDesc, ItemNatureCode, UOMCode, /*PurUOMCode,                  
    PurConversionFactor, Rate,*/ RevNo, RevDate, BranchID, CompID)          
 AS          
 (          
   Select /* a.ItemID,*/ a.ItemCode, '' As AssetCode, a.ItemDescription As ItemDesc, a.ItemNature As ItemNatureCode, 
    a.UOM As UOMCode, /*a.PurUOMCode,                  
    a.PurConversionFactor, a.Rate,*/ a.RevisionNo As RevNo, a.RevisionDate As RevDate, a.BranchID, a.CompID                  
   From INV_Material_Master a  --dbo.fn_BOM_Material_Master(@Filter, @AsOnDate, @RptDate, @BranchID, @CompID) a  
  -- where a.ItemCode In('1U0201100H','2U020531T0','2U020532T0','2U020533T0','2U020534T0','2U020530T0')
 )          
          
    /* Output (Result) */
    Select * From Item_CTE a          
    Union All          
    Select /*b.ItemID,*/ a.ItemCode, a.AssetCode, IsNull(b.ItemDesc,'') /*IsNull(a.AssetDesc, b.ItemDesc)*/ As ItemDesc, b.ItemNatureCode, b.UOMCode,                  
        /*b.PurUOMCode, b.PurConversionFactor, b.Rate,*/ b.RevNo, b.RevDate, b.BranchID, b.CompID                  
    From FAM_Asset_Master a  -- dbo.fn_FAM_Asset_Master(@Filter, @AsOnDate, @RptDate, @BranchID, @CompID) a              
    Left Outer Join Item_CTE b              
        On a.ItemCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID               
    Where a.AssetCode<>'' and Not Exists ( Select * From Item_CTE c              
            Where (a.ItemCode+a.AssetCode)=c.ItemCode and a.BranchID=c.BranchID and a.CompID=c.CompID)            
) 
GO

