CREATE Function [dbo].[fn_BOM_Get_Material_INV](@fOpration Char(1), @AsOnDate datetime, @RptDate datetime, @BranchID Varchar(3), @CompID Varchar(3))                            
Returns Table                        
Return                        
 (             
            
 Select /*a.ItemID,*/ a.ItemCode, a.ItemDesc, a.ItemNatureCode, a.UOMCode, b.SDesc as UOMDesc, b.NoofDecimals as UOMDecimal, --a.PurUOMCode,          
  0 as Rate, '' As TariffNo, 0 As HSNId, a.RevNo, a.RevDate, a.EffStatus, a.EffDate, a.UserID, a.BranchID, a.CompID, a.TranStamp              
 From BOM_Material_Master a		--dbo.fn_BOM_Material_Master(@fOpration, @AsOnDate, @RptDate, @BranchID, @CompID) a                
             
 Left Outer Join INV_UOM_Master b --fn_BOM_UOM_Master(@fOpration, @AsOnDate, @RptDate, @BranchID, @CompID)b              
  On a.UOMCode=b.Code and a.BranchID=b.BranchID and a.CompID=b.CompID                            
)  
