/****** Object:  UserDefinedFunction [dbo].[fn_BOM_Get_Material_Master_HSNSummary]    Script Date: 17/06/2026 11:38:54 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_BOM_Get_Material_Master_HSNSummary](@fOpration Char(1), @ItemCode Varchar(20), 
	@AsOnDate datetime, @RptDate datetime, @BranchId Varchar(3), @CompId Varchar(3))        
RETURNS TABLE                        
Return                
(   
 Select a.ItemCode, a.ItemDesc, a.ItemNatureCode, a.UOMCode, d.SDesc As UOMDesc, d.NoofDecimals As UOMDecimal,    
   a.PurUOMCode, e.SDesc As PurchaseUOMDesc, e.NoofDecimals As PurchaseUOMDecimal,   
   a.IssUOMCode, f.SDesc As IssueUOMDesc, f.NoofDecimals As IssueUOMDecimal,   
   a.Rate, a.isAsset, a.TariffNo, a.HSNId, h.HSNNo    
 From (  
  Select x.ItemCode, x.ItemDescription As ItemDesc, x.ItemNature As ItemNatureCode, x.UOM As UOMCode, 
			x.PurchaseUOM As PurUOMCode, x.IssueUOM As IssUOMCode, x.Rate, x.isAsset, x.TariffNo, x.HSNId, 
			x.BranchID, x.CompID        
  From INV_Material_Master x
  Where x.ItemCode=@ItemCode and  IsNull(x.ItemDescription,'') <> ''
	    
  UNION      

  Select  z.ItemCode, x.ItemDescription As AssetDesc, x.ItemNature As ItemNatureCode, x.UOM As UOMCode, 
		x.PurchaseUOM As PurUOMCode, x.IssueUOM As IssUOMCode, x.Rate, x.isAsset, x.TariffNo, x.HSNId, 
		z.BranchID, z.CompID       
  From FAM_Asset_Master z
  Left Outer Join INV_Material_Master x
		On z.ItemCode=x.ItemCode and z.BranchID=x.BranchID and z.CompID=x.CompID  					
	Where (x.ItemCode=@ItemCode or (z.ItemCode+z.AssetCode)=@ItemCode) 
			and IsNull(x.ItemDescription,'')<>'' and z.BranchID=@BranchID and z.CompID=@CompID    
 ) a  
 Left Outer Join INV_UOM_Master d        
 On a.UOMCode=d.Code and a.BranchID=d.BranchID and a.CompID=d.CompID       
        
 Left Outer Join INV_UOM_Master e        
 On a.PurUOMCode=e.Code and a.BranchID=e.BranchID and a.CompID=e.CompID        
        
 Left Outer Join INV_UOM_Master f        
 On a.IssUOMCode=f.Code and a.BranchID=f.BranchID and a.CompID=f.CompID      
      
 Left Outer Join BOM_HSNNo_Master h      
	On h.HSNId=a.HSNId and a.BranchID=h.BranchID and a.CompID=h.CompID    
)
GO

/****** Object:  UserDefinedFunction [dbo].[fn_BOM_Get_MpsMaster]    Script Date: 17/06/2026 11:38:54 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE Function [dbo].[fn_BOM_Get_MpsMaster](@fOpration char(1), @AsOnDate datetime, @RptDate datetime, @BranchID Varchar(3), @CompID Varchar(3))    
RETURNS TABLE    
AS    
RETURN     
(  

 WITH MPS_CTE(Itemcode, StageCode, OperationCode, OperationSequence)  
 AS  
 (  
  Select a.ItemCode, a.StageCode, a.OperationCode, a.OperationSequence
  From dbo.fn_BOM_MPS_Master(@fOpration, @AsOnDate, @RptDate, @BranchID, @CompID) a  
 )  

 Select a.ItemCode, a.StageCode, a.OperationCode,  IsNull(b.OperationName,'') As OperationName,     
  IsNull(b.OperationSpecification,'') As OperationSpecification,    
  Case When a.OperationSequence = 0 then e.FGOperationSeq  
   Else a.OperationSequence End As OperationSeq,     
  @BranchID as BranchID, @CompID as CompID    
 From MPS_CTE a      
 Left outer join BOM_Operation_Master b     
  On a.OperationCode=b.OperationCode  --and a.Branchid = b.Branchid and a.Compid = b .Compid     
 Left Outer Join (Select e2.ItemCode, Max(e2.OperationSequence)+1 As FGOperationSeq    
      From MPS_CTE e2        
      Group by e2.ItemCode  
      ) e    
 On a.StageCode=e.ItemCode     
)  
GO

/****** Object:  UserDefinedFunction [dbo].[fn_BOM_HSNNo_Master]    Script Date: 17/06/2026 11:38:54 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [dbo].[fn_BOM_HSNNo_Master] (@Filter char(1)='A', @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3))          
--@Filter = ('1', 'M') returns Max Transtamp Data; @Filter=('0', 'A') returns Max Authorised Data, @Filter='H'/'D'/'X' returns Max Hold/Delete/Cancel Data,  
-- @Filter='R' returns revno >= 0 for reporting purpose        
RETURNS TABLE        
         
 AS          
Return            
  (        
   Select *  From BOM_HSNNo_Master a        
  Where a.TranStamp = (Select Max(b.TranStamp) from BOM_HSNNo_Master b        
               where b.TranStamp <= @AsOnDate         
      and (  
  (@Filter in ('1', 'M') OR (@Filter='R' and RevNo>=0))         
       OR (b.isTranLock='1'         
        AND Not Exists (Select * from BOM_HSNNo_Master c         
          Where c.TranStamp>b.TranStamp and c.EffStatus Like 'X%'         
           and b.HSNId=c.HSNId        
            and c.BranchID=b.BranchID and c.CompID=b.CompID         
          )        
         )         
       OR (@Filter Not in ('1', 'M') and b.EffStatus Like 'A%' and b.EffDate<=@RptDate)        
       )         
      and b.HSNId=a.HSNId         
      and b.BranchID=a.BranchID and b.CompID=a.CompID        
            )        
   and a.EffStatus Like Case When @Filter in ('1', 'M', 'R') Then '%' When @Filter in ('0', 'A') Then 'AA' When @Filter='H' Then 'AH' When @Filter='D' Then 'AD' When @Filter='X' Then 'AX' Else 'A%' End and a.BranchID=@BranchID and a.CompID=@CompID        

 
  )     
  
GO

/****** Object:  UserDefinedFunction [dbo].[fn_BOM_Material_Master]    Script Date: 17/06/2026 11:38:54 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_BOM_Material_Master] (@Filter char(1)='A', @AsOnDate datetime, @RptDate datetime,     
	@BranchID varchar(3), @CompID varchar(3))   
	/*  Returns Max TranStamp Data; @Filter not used / BOM_Material_Master Table available but recrods not found */  
RETURNS TABLE          
AS            
Return           
(       
	Select a.ItemID, a.ItemCode, a.ItemDescription, a.ItemNature, a.ProductCategoryCode, a.ProductSubCategoryCode, a.PurchaseNature,   
		a.Origin, a.Boughtout, a.ItemSpecification, a.IsHeatNoApp, a.PostingAccount, a.PostingAccountEditable, a.CostCenter,   
		a.UOM, a.PurchaseUOM, a.PurConversionFactor, a.IssueUOM, a.IssConversionFactor, a.AlternateUOM, a.AlternateConvFactor,   
		a.MinimumStock, a.MaximumStock, a.ReOrderLevel, a.ReOrderQty, a.SafetyStock, a.MinLeadTime, a.MaxLeadTime,   
		a.IsShelfLifePeriodApp, a.SelfLifePeriod, a.Rate, a.Modvat, a.TariffNo, a.HSNId, a.isAsset, a.TolerancePlusApplicable,   
		a.PurchaseTolerancePlus, a.ToleranceMinusApplicable, a.PurchaseToleranceMinus, a.PackingType, a.StdPackingQty,   
		a.DrawingNo, a.DrawingDescription, a.RevisionNo, a.RevisionDate, a.DrawingPath, a.TrayTypeCode,   
		a.[Status], a.UserID, a.BranchID, a.CompID, a.Transtamp   
	From INV_Material_Master a          
	Where a.TranStamp=(Select Max(b.TranStamp) From INV_Material_Master b          
				Where b.TranStamp <= @AsOnDate and b.ItemCode=a.ItemCode   
				and b.BranchID=a.BranchID and b.CompID=a.CompID          
			)          
		and a.BranchID=@BranchID and a.CompID=@CompID           
)  
GO

