/****** Object:  UserDefinedFunction [dbo].[fn_BOM_ProductStructure_Get_Child]    Script Date: 17/06/2026 11:38:54 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_BOM_ProductStructure_Get_Child] (@ItemCode varchar(20), @AsOnDate datetime, @RptDate datetime, 
		@BranchID varchar(3), @CompID varchar(3)) 
	RETURNS TABLE                               
	 As    
	Return   
	(  
		Select Distinct a.ParentCode, a.ChildCode, a.Qty
		From BOM_Structure_Dtl a 
		Where Exists(Select * From BOM_Structure_hdr h1
						Where h1.ParentCode=a.ParentCode and h1.Status = 1 
							and Exists(Select * From MpsMaster mp1 
									Where mp1.ItemCode=@ItemCode and mp1.StageCode = h1.ParentCode and mp1.BranchId = h1.BranchID and mp1.CompID = h1.CompID
								)				
							and a.BranchID = @BranchID and a.CompID = @CompID
					)		
				and a.Status = 1
		Union 
		Select Distinct a.ItemCode As ParentCode, a.ItemCode As ChildCode, 0 As Qty
		From Material_Master a 
		where a.ItemCode=@ItemCode and a.ItemNature in ('T') 
			and a.BranchID = @BranchID and a.CompID = @CompID and a.Status = 1 	
	)
GO

