CREATE FUNCTION [dbo].[fn_COM_Company_Master] (@Filter char(1)='A', @AsOnDate datetime, @RptDate datetime)  --, @BranchID varchar(3), @CompID varchar(3)) 
--@Filter = ('1', 'M') returns Max Transtamp Data; @Filter=('0', 'A') returns Max Authorised Data, @Filter='H'/'D'/'X' returns Max Hold/Delete/Cancel Data

RETURNS TABLE

 AS  

Return 

(

	Select * from COM_Company_Master a
	Where a.TranStamp = (Select Max(b.TranStamp) from COM_Company_Master b
			           Where b.TranStamp <= @AsOnDate 
						and ((@Filter in ('1', 'M')) 
							OR (b.isTranLock='1' 
								AND Not Exists (Select * from COM_Company_Master c 
										Where c.TranStamp>b.TranStamp and c.EffStatus Like 'X%' 
											 and c.BranchID=b.BranchID and c.CompID=b.CompID 
										)
								 ) 
							OR (@Filter Not in ('1', 'M') and b.EffStatus Like 'A%' and b.EffDate<=@RptDate)
							) 
					and b.BranchID=a.BranchID and b.CompID=a.CompID --and b.BranchID=a.BranchID and b.CompID=a.CompID
			         )
		and a.EffStatus Like Case When @Filter in ('1', 'M') Then '%' When @Filter in ('0', 'A') Then 'AA' When @Filter='H' Then 'AH' When @Filter='D' Then 'AD' When @Filter='X' Then 'AX' Else 'A%' End
		--and a.BranchID=@BranchID and a.CompID=@CompID
 )
GO

