CREATE FUNCTION [dbo].[fn_COM_TermsMaster_FinyearBased] (@Filter char(1)='A', @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3))          
--@Filter = ('M') returns Max Transtamp Data; @Filter=('0', 'A') returns Max Authorised Data, @Filter='H'/'D'/'X' returns Max Hold/Delete/Cancel Data        
RETURNS TABLE        
AS    
RETURN            
  (       
   Select *  From COM_TermsMaster_FinyearBased a        
   Where a.TranStamp = (Select Max(b.TranStamp) from COM_TermsMaster_FinyearBased b        
                            Where b.TranStamp <= @AsOnDate         
                                and ((@Filter in ('M')) OR (@Filter Not in ('M') and b.EffStatus Like 'A%' and b.EffDate<=@RptDate))          
                                and b.Finyear=a.Finyear and b.ModuleCode=a.ModuleCode and b.TypeFlg=a.TypeFlg  
                                and b.TermsCode=a.TermsCode and b.BranchID=a.BranchID and b.CompID=a.CompID        
                        )        
       and a.EffStatus Like Case When @Filter in ('M') Then '%'   
                                   When @Filter in ('A') Then 'AA'   
                                   When @Filter='H' Then 'AH'   
                                   When @Filter='D' Then 'AD'   
                                   When @Filter='X' Then 'AX' Else 'A%'   
                            End        
       and a.BranchID=@BranchID and a.CompID=@CompID         
  )
GO

