CREATE FUNCTION [dbo].[fn_FAS_Bank] (@BankCode int, @RptDate datetime, @CmCode varchar(4))  

RETURNS TABLE


 AS  

RETURN 
	(

	Select * from (
		Select 
			0 as DocNo, 0 as VCode, 'OpBal-'+Convert(varchar, @BankCode) as Route,
			a.ChqNo,  Case R.DrAmt When 0 then a.ChqDate Else b.DocDate End as cDate,
			@BankCode as ChqBank, '1' as isBankCode,
			Case isLrCode When 1 then (Select LedgerName from FAS_LedgerMaster Where LedgerCode=a.ChqFavor and CompCode=@CmCode) 
				Else a.ChqFavor End as ChqFavor, isLrCode,
			Case R.DrAmt When 0 Then isNull(R.CrAmt, 0) Else  isNull(R.DrAmt, 0) End as Amount,
			'0' as isReceipt, BankDate, '0004' as CompCode
		from FAS_VoucherTranPay a Join FAS_VoucherTranMast b 
		On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
				Join FAS_VoucherTranSub R
				On R.DocNo=a.DocNo and R.DocDate=a.DocDate and R.VrRoute=a.VrRoute and R.CompCode=a.CompCode
		Where R.LrCode=@BankCode and a.CompCode=@CmCode
				and (a.BankDate is Null or a.BankDate > Convert(datetime, @RptDate, 111)) and b.DocDate <= Convert(datetime, @RptDate, 111) 
	
		Union All
	
		Select 0 as DocNo, 0 as VCode, 'OpBal-'+Convert(varchar, @BankCode) as Route,
			ChqNo, ChqDate, 
			@BankCode as ChqBank, '1' as isBankCode,
		
			Case isLrCode When 1 then (Select LedgerName from FAS_LedgerMaster Where LedgerCode=ChqFavor and CompCode=@CmCode) 
				Else ChqFavor End as ChqFavor, isLrCode,
			ChqAmount as Amount,
			'0' as isReceipt, BankDate, '0004' as CompCode
		from FAS_VoucherTranPay
		Where DocNo=0 and Convert(int, Substring(VrRoute, 7, Len(VrRoute)-6))=@BankCode and CompCode=@CmCode
			and (BankDate is Null or BankDate > Convert(datetime, @RptDate, 111))
		) x

	)

GO

