CREATE FUNCTION [dbo].[fn_FAS_BRS] (@BankCode int, @AsOnDate datetime, @ClearedStatus char(1), @RestictDateType char(1), @isAnyFromDate bit, @FromDate datetime, @isAnyToDate bit, @ToDate datetime, @PrStart datetime, @PrEnd datetime, @FinStart datetime, @CmCode varchar(12))
		--@RestictDateType is 'B'-BankDate; 'C'-Cheque Date; 'V'-VoucherDate; 'D'-Deposited or Issued Date
		--@ClearedStatus is 'B'-Both; 'C'-Cleared; 'N'-NotCleared;

RETURNS TABLE

 AS  

RETURN

	(
		Select 2 as SortOrder, a.ChqNo, Case b.DrAmt When 0 Then a.ChqDate Else b.DocDate End as CDate, 
			Case isNull(b.DrAmt, 0) When 0 then 'Issue' Else 'Rcpt' End  as PayType,
			Case isNull(b.DrAmt, 0) When 0 Then isNull(b.CrAmt, 0) Else b.DrAmt End as Amount,
			Case a.isLrCode When 1 then isNull((Select LedgerName from FAS_LedgerMaster Where LedgerCode=a.ChqFavor and CompCode=@CmCode), '')								
						Else a.ChqFavor 
			End as ChqFavor, 
			a.DocNo, a.VrRoute, b.DocDate, a.ChqDate, a.BankDate
		from FAS_VoucherTranSub b
		Left Outer Join (Select * from FAS_VoucherTranPay where (VrRoute Not Like  'OpBal-%') and CompCode=@CmCode) a 
			On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode
		Where  b.DocDate <= @AsOnDate and b.LrCode=@BankCode and a.CompCode=@CmCode

		Union All

		Select 2 as SortOrder, a.ChqNo, a.ChqDate as CDate, Case When a.isReceipt='1' then 'Rcpt' else 'Issue' End as PayType, a.ChqAmount,
				Case a.isLrCode When 1 then (Select LedgerName from FAS_LedgerMaster Where LedgerCode=a.ChqFavor and CompCode=@CmCode) 								
						Else a.ChqFavor End as ChqFavor, a.DocNo, a.VrRoute, a.DocDate, a.ChqDate, a.BankDate
		from FAS_VoucherTranPay a 
		Where a.DocNo=0 and VrRoute= 'OpBal-'+Convert(varchar, @BankCode) and CompCode=@CmCode

	)	

/*

	--Insert all Transactions First
	Insert into @Bank

		Select 2 as SortOrder, a.ChqNo, Case b.DrAmt When 0 Then a.ChqDate Else b.DocDate End as CDate, 
			Case isNull(b.DrAmt, 0) When 0 then 'Issue' Else 'Rcpt' End  as PayType,
			Case isNull(b.DrAmt, 0) When 0 Then isNull(b.CrAmt, 0) Else b.DrAmt End as Amount,
			Case a.isLrCode When 1 then isNull((Select LedgerName from FAS_LedgerMaster Where LedgerCode=a.ChqFavor and CompCode=@CmCode), '')								
						Else a.ChqFavor 
			End as ChqFavor, 
			a.DocNo, a.VrRoute, b.DocDate, a.ChqDate, a.BankDate
		from FAS_VoucherTranSub b
		Left Outer Join (Select * from FAS_VoucherTranPay where (VrRoute Not Like  'OpBal-%') and CompCode=@CmCode) a 
			On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode
		Where  b.DocDate <= @AsOnDate and b.LrCode=@BankCode and a.CompCode=@CmCode

		Union All

		Select 2 as SortOrder, a.ChqNo, a.ChqDate as CDate, Case When a.isReceipt='1' then 'Rcpt' else 'Issue' End as PayType, a.ChqAmount,
				Case a.isLrCode When 1 then (Select LedgerName from FAS_LedgerMaster Where LedgerCode=a.ChqFavor and CompCode=@CmCode) 								
						Else a.ChqFavor End as ChqFavor, a.DocNo, a.VrRoute, a.DocDate, a.ChqDate, a.BankDate
		from FAS_VoucherTranPay a 
		Where a.DocNo=0 and VrRoute= 'OpBal-'+Convert(varchar, @BankCode) and CompCode=@CmCode



	--Already commented the following code
	--Update Opening Balance Entries
	Insert into @Bank

		Select 1 as SortOrder, '0' as ChqNo, Null as CDate, PayType,  Sum(Amount) as Amount, 'Opening Balance' as ChqFavor, 0 as DocNo, '' as VrRoute, Null as DocDate, Null as ChqDate, Null as BankDate
		from
			(Select Case b.DrAmt When 0 then 'Issue' Else 'Rcpt' End as PayType,
					Case b.DrAmt When 0 Then  isNull(b.CrAmt, 0) Else  isNull(b.DrAmt, 0) End as Amount
			from FAS_VoucherTranPay a 
			Left Outer Join FAS_Voucher_vw b
				On a.DocNo=b.DocNo and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
			Where a.DocNo<>0 and b.LrCode=@BankCode and Left(a.CompCode, 4)=@CmCode and a.BankDate <= @AsOnDate and a.ChqDate < @FromDate
		
			Union All
			
			Select Case a.isReceipt When 0 then 'Issue' Else 'Rcpt' End as PayType, a.ChqAmount as Amount
				from FAS_VoucherTranPay a
			Where DocNo=0 and Convert(int, Substring(VrRoute, 7, Len(VrRoute)-6))=@BankCode and CompCode=@CmCode
				and a.BankDate <= @AsOnDate
			) x
		Group by PayType


	--Update Closing Balance Entries
	Insert into @Bank

		Select 3 as SortOrder, '0' as ChqNo, Null as CDate,  PayType, Sum(Amount) as Amount, 'Closing Balance' as ChqFavor, 0 as DocNo, '' as VrRoute, Null as DocDate, Null as ChqDate, Null as BankDate
		from
			(Select Case b.DrAmt When 0 then 'Issue' Else 'Rcpt' End as PayType,
					Case b.DrAmt When 0 Then  isNull(b.CrAmt, 0) Else  isNull(b.DrAmt, 0) End as Amount
			from FAS_VoucherTranPay a 
			Left Outer Join FAS_Voucher_vw b
				On a.DocNo=b.DocNo and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
			Where b.LrCode=@BankCode and a.CompCode=@CmCode and a.BankDate <= @AsOnDate and a.ChqDate > @ToDate
			) y
		Group by PayType

*/


















GO

