CREATE FUNCTION [dbo].[fn_FAS_Budget_StockEntry] (@ActualsCutOff datetime, @CmCode varchar(12))  

RETURNS TABLE

AS  

RETURN 
	
	(Select LedgerCode, StockDate, StockValue, CompCode
	From FAS_StockEntry
	Where StockDate<=@ActualsCutOff and CompCode=@CmCode
	
	Union All

	Select LedgerCode, StockDate, StockValue, CompCode
	From FAS_Budget_StockEntry m
	Where m.StockDate>@ActualsCutOff and m.CompCode=@CmCode
	)
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Budget_VoucherTranMast]    Script Date: 17/06/2026 11:38:55 ******/
