GO

CREATE FUNCTION [dbo].[fn_FAS_Budget_VoucherTranMast] (@ActualsCutOff datetime, @CmCode varchar(12))  

RETURNS TABLE

AS  

RETURN 
	
	(Select DocType, DocNo, DocDate, VrRoute, Ref, FileRef, Amount, PayMode, Narration, isCancelled, CompCode
	From FAS_VoucherTranMast
	Where DocDate<=@ActualsCutOff and CompCode=@CmCode
	
	Union All

	Select 'BT'+Convert(varchar, m.PlanFor) as DocType, VrNo as DocNo, m.PlanDate as DocDate, VrRoute,
		'' as Ref, 0 as FileRef,  
		isNull(Sum(m.Amount), 0) as Amount, 'Cash' as PayMode, '' as Narration, '0' as isCancelled, m.CompCode
	From FAS_Budget_Dtl m
	Where m.DrCode Like 'L%' and m.PlanDate>@ActualsCutOff and m.CompCode=@CmCode
	Group By m.PlanPeriod, m.PlanFor, m.PlanDate, m.VrRoute, m.VrNo, m.CompCode
	
	)
GO

