CREATE FUNCTION [dbo].[fn_FAS_Budget_VoucherTranMast_Period_VrSub] (@VrRoute varchar(42), @PrStart datetime, @PrEnd datetime, @ActualsCutOff datetime, @CmCode varchar(12))  

RETURNS TABLE

AS  

RETURN 
	
	(Select DocType, DocNo, DocDate, VrRoute, Ref, FileRef, Amount, PayMode, Narration, isCancelled, CompCode
	From FAS_VoucherTranMast a
	Where (DocDate <= @ActualsCutOff and DocDate Between @PrStart and @PrEnd) and VrRoute Like @VrRoute+'%' and CompCode=@CmCode
	
	Union All

	Select 'BT'+Convert(varchar, m.PlanFor) as DocType, VrNo as DocNo, m.PlanDate as DocDate, VrRoute,
		'' as Ref, 0 as FileRef,  
		isNull(Sum(m.Amount), 0) as Amount, 'Cash' as PayMode, '' as Narration, '0' as isCancelled, m.CompCode
	From FAS_Budget_Dtl m
