CREATE FUNCTION [dbo].[fn_FAS_Budget_VoucherTranSub_UpTo_LrVr] (@LrCode int, @UpTo datetime, @ActualsCutOff datetime, @CmCode varchar(12))  

RETURNS TABLE

AS  

RETURN 

	(Select DocType, DocNo, DocDate, VTSNo, VrRoute, LrCode, DrAmt, CrAmt, CompCode
	From FAS_VoucherTranSub a
	Where (DocDate<=@ActualsCutOff and DocDate<=@UpTo) and CompCode=@CmCode
		and Exists (Select * From FAS_VoucherTranSub b
					Where a.DocDate=b.DocDate and a.DocNo=b.DocNo and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode
						and b.LrCode=@LrCode) 

	Union All

	Select 'BT'+Convert(varchar, m.PlanFor) as DocType, VrNo as DocNo, m.PlanDate as DocDate, VTSNo, VrRoute,
		m.LrCode, m.DrAmt, m.CrAmt, m.CompCode
	From
		(Select b.PlanPeriod, b.PlanFor, b.PlanDate, b.VrRoute, b.VrNo, 1 as VTSNo, 
			@LrCode as LrCode, b.Amount as Dramt, 0 as CrAmt, CompCode
		from FAS_Budget_Dtl b
		where b.DrCode = 'L'+Convert(varchar, @LrCode) and (b.PlanDate>@ActualsCutOff and b.PlanDate<=@UpTo) and b.CompCode=@CmCode

		Union All

		Select b2.PlanPeriod, b2.PlanFor, b2.PlanDate, b2.VrRoute, b2.VrNo, 2 as VTSNo, 
			Substring(b2.CrCode, 2, Len(b2.CrCode)) as LrCode, 0 as DrAmt, b2.Amount as CrAmt, b2.CompCode
		from FAS_Budget_Dtl b2
		where b2.DrCode = 'L'+Convert(varchar, @LrCode) and (b2.PlanDate>@ActualsCutOff and b2.PlanDate<=@UpTo) and b2.CompCode=@CmCode

		Union All

		Select c.PlanPeriod, c.PlanFor, c.PlanDate, c.VrRoute, c.VrNo, 2 as VTSNo, 
			@LrCode as LrCode, 0 as DrAmt, c.Amount as CrAmt, CompCode
		from FAS_Budget_Dtl c
		where c.CrCode = 'L'+Convert(varchar, @LrCode) and (c.PlanDate>@ActualsCutOff and c.PlanDate<=@UpTo) and c.CompCode=@CmCode

		Union All

		Select c2.PlanPeriod, c2.PlanFor, c2.PlanDate, c2.VrRoute, c2.VrNo, 1 as VTSNo, 
			Substring(c2.DrCode, 2, Len(c2.DrCode))  as LrCode, c2.Amount as DrAmt, 0 as CrAmt, CompCode
		from FAS_Budget_Dtl c2
		where c2.CrCode = 'L'+Convert(varchar, @LrCode) and (c2.PlanDate>@ActualsCutOff and c2.PlanDate<=@UpTo) and c2.CompCode=@CmCode	
		) m
	)
GO

