	Where DocDate<=@ActualsCutOff and LrCode=@LrCode and VrRoute=@VrRoute and CompCode=@CmCode

	Union All

	Select 'BT'+Convert(varchar, m.PlanFor) as DocType, VrNo as DocNo, m.PlanDate as DocDate, VTSNo, VrRoute,
		m.LrCode, m.DrAmt, m.CrAmt, m.CompCode
	From
		(Select b.PlanPeriod, b.PlanFor, b.PlanDate, b.VrRoute, b.VrNo, 1 as VTSNo,  Substring(b.DrCode, 2, Len(b.DrCode)) as LrCode, b.Amount as Dramt, 0 as CrAmt, CompCode
		from FAS_Budget_Dtl b
		where b.DrCode='L'+Convert(varchar, @LrCode) and b.PlanDate>@ActualsCutOff and b.VrRoute=@VrRoute and b.CompCode=@CmCode

		Union All

		Select c.PlanPeriod, c.PlanFor, c.PlanDate, c.VrRoute, c.VrNo, 2 as VTSNo, Substring(c.CrCode, 2, Len(c.CrCode)), 0, c.Amount as CrAmt, CompCode
		from FAS_Budget_Dtl c
		where c.CrCode='L'+Convert(varchar, @LrCode) and c.PlanDate>@ActualsCutOff and c.VrRoute=@VrRoute and c.CompCode=@CmCode
		) m
	)
GO

