CREATE FUNCTION [dbo].[fn_FAS_Cheques_Cleared] (@BankCode int, @FromDate datetime, @ToDate datetime, @CmCode varchar(12))  

RETURNS TABLE

 AS  

RETURN 


	(
		Select a.ChqNo,  Case R.DrAmt When 0 then a.ChqDate Else b.DocDate End as CDate,
			Case R.DrAmt When 0 then 'Issue' Else 'Rcpt' End as PayType,
			Case R.DrAmt When 0 Then  isNull(R.CrAmt, 0) Else  isNull(R.DrAmt, 0) End as Amount,
			Case isLrCode When 1 then (Select LedgerName from FAS_LedgerMaster Where LedgerCode=a.ChqFavor and CompCode=@CmCode) 
				Else a.ChqFavor End as ChqFavor, 
			a.DocNo, a.VrRoute, a.BankDate, b.DocDate, @CmCode as CompCode
		from FAS_VoucherTranPay a Join FAS_VoucherTranMast b 
		On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
				Join FAS_VoucherTranSub R
				On R.DocNo=a.DocNo and a.DocDate=R.DocDate and R.VrRoute=a.VrRoute and R.CompCode=a.CompCode
		Where R.LrCode=@BankCode and a.CompCode=@CmCode
				and (a.BankDate is Not Null or a.BankDate <= Convert(datetime, @ToDate, 111)) and b.DocDate <= Convert(datetime, @ToDate, 111) 
	
		Union All
	
		Select ChqNo, ChqDate, Case isReceipt When 0 then 'Issue' Else 'Rcpt' End as PayType, ChqAmount as Amount,
			Case isLrCode When 1 then (Select LedgerName from FAS_LedgerMaster Where LedgerCode=ChqFavor and CompCode=@CmCode) 
				Else ChqFavor End as ChqFavor, 
			DocNo, VrRoute, BankDate, ChqDate, @CmCode
		from FAS_VoucherTranPay
		Where DocNo=0 and Convert(int, Substring(VrRoute, 7, Len(VrRoute)-6))=@BankCode and CompCode=@CmCode
			and (BankDate is Not Null or BankDate <= Convert(datetime, @ToDate, 111))

	)
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Dis_Ageing_BillwiseDetails]    Script Date: 17/06/2026 11:38:55 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO


CREATE FUNCTION [dbo].[fn_FAS_Dis_Ageing_BillwiseDetails] (@LrCode int, @RptDate datetime, @CmCode varchar(12))  
--FAS_Dis_AA_1
RETURNS TABLE

 AS  

RETURN 	
	
	(

		Select [InvoiceNo], [InvoiceDate], Amount, [DueDate], OverDue,	Less1 as  [x < 1],  Amount1to30 as [1 <= x <= 30],  Amount31to60 as [31 <= x <= 60],  Amount61to90 as [61 <= x <= 90],  Amount90 as [x > 90], 
		(Less1+Amount1to30+Amount31to60+Amount61to90+Amount90) as PendingAmt
		From (
			Select InvoiceNo, InvoiceDate, Amount, DueDate, Convert(varchar, OverDue) + space(4) as OverDue,	
											Case when Overdue < 1 then Amount else 0 End as Less1,
											Case when Overdue between 1 and 30 then Amount else 0 End as Amount1to30,
											Case when Overdue between 31 and 60 then Amount else 0 End as Amount31to60,
											Case when Overdue between 61 and 90 then Amount else 0 End as Amount61to90,
											Case when Overdue > 90 then Amount else 0 End as Amount90
			from 
				(Select RefNo as InvoiceNo, Convert(Datetime,  RefDate, 105) as InvoiceDate, Convert(Datetime,  Dateadd(day, isNull(CreditDays, 0), RefDate) , 105) as DueDate, 
					Amount, --(Convert(varchar, Abs(Amount)) + ' ' + Case sign(Amount) when 1 then 'Dr' When -1 then 'Cr' End + '     ') as Amount,
					DateDiff(day, Dateadd(day, isNull(CreditDays, 0), RefDate), @RptDate) as OverDue
				from 
					(
					Select isNull(y.RefNo, z.RefNo) as RefNo, 
							isNull(y.RefDate, (Select Min(x.RefDate) from FAS_BillDetails x where x.RefNo=z.RefNo and x.RefDate <= @RptDate and x.LrCode=@LrCode and x.CompCode=@CmCode)) as RefDate, 
							isNull(y.CreditDays, 0) CreditDays, z.Amount 
						from 
							(Select RefNo, RefDate, CreditDays from fas_billdetails where LrCode=@LrCode and Type in ('New Ref', 'Advance') and CompCode=@CmCode
							) y 
						Right Outer Join
							(Select RefNo, Sum(Amount) as Amount from fas_billdetails
							where Type <> 'On Acct' and RefDate <= @RptDate and LrCode=@LrCode and CompCode=@CmCode
							group by RefNo having sum(Amount) <> 0 ) z 
						On y.RefNo=z.RefNo 
					) d
				) b
				
		)m
	
	)
GO

