CREATE FUNCTION [dbo].[fn_FAS_Dis_OB_BillIncludeVouchers] (@LrCode int, @RefNo varchar(50), @RefDate datetime, @FinStart datetime, @AcPrEnd datetime, @CmCode varchar(12))    
--FAS_Dis_OB_3  
RETURNS TABLE  
  
 AS    
  
RETURN    
   
 (  
  Select VrRoute, Case VrRoute When 'OpBal' then 'Opening Balance'   
       Else (Select VoucherName from FAS_VoucherMaster b where b.VrRoute+b.VrWidth=a.VrRoute and b.CompCode=@CmCode)   
      End as VName,  
   Case VrRoute  When 'OpBal' then '' Else Convert(varchar, DocNo) End as VrNo,   
   Case VrRoute When 'OpBal' then @FinStart   
    Else a.DocDate --(Select DocDate from FAS_VoucherTranMast c where c.DocNo=a.DocNo and c.VrRoute=a.VrRoute and c.CompCode=@CmCode)  
   End as VTDate, Amount  
--   Case Sign(Amount) When -1 then Convert(varchar, -Amount) + ' Cr'  When 1 then Convert(varchar, Amount) + ' Dr' Else '' End as Amount  
  From FAS_BillDetails a  
  Where RefNo=@RefNo and LrCode=@LrCode and (DocDate Between @RefDate and @AcPrEnd) and CompCode=@CmCode   
--  Order by 4  
  
 )  
GO

