CREATE FUNCTION [dbo].[fn_FAS_Dis_OB_BillwiseDetails] (@LrCode int, @RptDate datetime, @AcPrEnd datetime, @CmCode varchar(12))  
--FAS_Dis_OB_1
RETURNS TABLE

 AS  

RETURN 	
	
	(

		Select RefNo as InvoiceNo,  RefDate as InvoiceDate,  Amount,			
				Convert(datetime,  DueDate, 105) as DueDate, DateDiff(day, [DueDate], @RptDate) as Overdue
		from 
			(Select RefNo, RefDate, Dateadd(day, isNull(CreditDays, 0), RefDate) as DueDate, Amount			
				from 
					(Select isNull(y.RefNo, z.RefNo) as RefNo, 
						isNull(y.RefDate, (Select Min(x.RefDate) from FAS_BillDetails x where x.RefNo=z.RefNo and x.RefDate <= @RptDate and x.LrCode=@LrCode and x.CompCode=@CmCode)) as RefDate, 
						isNull(y.CreditDays, 0) CreditDays, z.Amount 
					from 
						(Select RefNo, RefDate, CreditDays 
						from FAS_BillDetails 
						where LrCode=@LrCode and Type in ('New Ref', 'Advance') and RefDate<=@RptDate and DocDate<=@AcPrEnd and CompCode=@CmCode
						) y 
					Right Outer Join
						(Select RefNo, Sum(Amount) as Amount 
						from FAS_BillDetails
						where Type <> 'On Acct' and DocDate<=@AcPrEnd and LrCode=@LrCode and CompCode=@CmCode
						group by RefNo having sum(Amount) <> 0 
						) z 
					On y.RefNo=z.RefNo 
					) d
			) b 
		
--		Order by RefDate, RefNo

	)

GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Dis_Vouchers_Ledgers]    Script Date: 17/06/2026 11:38:55 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO


CREATE FUNCTION [dbo].[fn_FAS_Dis_Vouchers_Ledgers] (@LrCode varchar(42), @MnCode varchar(6), @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))  

RETURNS TABLE

 AS  

RETURN 
	
	(

		Select DocDate,  DocNo, RefNo, VrRoute, VoucherName, n1.LedgerName as Particulars, Debit, Credit, 0.0 as ClosingBalance
		from
		
			(Select m.VrRoute, m.DocDate, m.VoucherName, m.DocNo, m.RefNo, 
				isNull((Select Top 1 m1.LrCode from FAS_VoucherTranSub m1 
						Where m1.DocNo=m.DocNo and m1.DocDate=m.DocDate and m1.VrRoute=m.VrRoute and m1.LrCode<>m.LrCode 
							and ((m1.DrAmt=0 AND m.Debit>0) OR (m1.CrAmt=0 AND m.Credit>0)) and m1.CompCode=@CmCode), m.LrCode) as Particulars,
				m.Debit, m.Credit, m.LrCode--,
			from	
				(Select top 100 Percent  a.VrRoute, a.DocDate, c.VoucherName, a.DocNo,
					Case When LTrim(RTrim(a.Ref))='' then b.RefType+':'+Convert(varchar, b.RefNo) else a.Ref end as RefNo,  
					a.DrAmt as Debit, a.CrAmt as Credit, a.LrCode, a.CompCode
				from FAS_Voucher_vw a Left Outer Join FAS_VoucherTranRef b
				On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode
				Left Outer Join FAS_VoucherMaster c On a.VrRoute=c.VrRoute+c.VrWidth and a.CompCode=c.CompCode
				Where a.LrCode = @LrCode and Convert(varchar(6), a.DocDate, 112)=@MnCode and a.CompCode=@CmCode 
				Order by a.DocDate,  a.DocNo
				)  m 
			) n 
		Left Outer Join FAS_LedgerMaster n1 On n.Particulars=n1.LedgerCode 
		Where n1.CompCode=@CmCode
--		Order by DocDate, VrRoute, DocNo					

	)
GO

