CREATE FUNCTION [dbo].[fn_FAS_LedgerMaster] (@AsOnDate datetime, @RptDate datetime, @CompCode varchar(4))  --@isMaxData bit='0', 
--@isMaxData = '1' returns Max Transtamp Data; @isMaxData='0' returns Max Authorised Data
RETURNS TABLE
 AS  
Return 
(
	Select * from FAS_LedgerMaster a
		Where a.TranStamp = (Select Max(b.TranStamp) from FAS_LedgerMaster b
				           where b.TranStamp <= @AsOnDate ---and ((@isMaxData='0' AND b.EffStatus Like 'A%') OR (@isMaxData='1'))
						and b.LedgerCode=a.LedgerCode and b.CompCode=a.CompCode
				        )
		---and ((@isMaxData='0' AND ((Right(a.EffStatus,1)='A' and a.EffDate <= @RptDate) or (Left(a.EffStatus,1)='H' and a.EffDate > @RptDate))) OR @isMaxData='1')
		and a.CompCode=@CompCode 
 )
GO

