CREATE FUNCTION [dbo].[fn_FAS_PartyMaster_AuthTbl_Rep] (@Filter char(1)='A', @AsOnDate datetime, @RptDate datetime,     
@BranchID varchar(3), @CompID varchar(3))            
--@Filter = ('1', 'M') returns Max Transtamp Data; @Filter=('A') returns Max Authorised Data; @Filter=('0','H') returns Max Hold Data @Filter='D'/'X' returns Max Delete/Cancel Data          
RETURNS TABLE
 AS                      
Return
(          
		Select PartyCode, a.VendorCode, a.SuplierCode, a.PartyName, a.AcType, a.FormCode, a.PackingCode, a.DeliveryCode, a.PaymentCode, 
				a.InsuranceCode, a.ModeCode, a.Freightcode, a.IsSubcontractor, a.AliasName,  
				a.CreditDays, a.CreditDaysPeriod, a.CurrencyCode, a.CustomerFormulaCode, a.VendorFormulaCode, 
				a.TinNo, a.PANNo, a.RevNo, a.RevDate, a.EffStatus, a.EffDate, a.UserID, a.BranchID, a.CompID, 
				a.TranStamp  
		From FAS_PartyMaster_AuthTbl_Rep a          
		Where a.RevDate=(	Select Max(b.RevDate) From FAS_PartyMaster_AuthTbl_Rep b          
												Where b.TranStamp<=@AsOnDate and ((@Filter In('1','M') and b.EffStatus Like '%' and b.EffDate<=@RptDate) 
															or (@Filter In('A') and b.EffStatus='A' and b.EffDate<=@RptDate)
															or (@Filter In('0','H') and b.EffStatus='H' and b.EffDate<=@RptDate)
															)																											
													and b.PartyCode=a.PartyCode 			
													and b.BranchID=a.BranchID and b.CompID=a.CompID    
													and a.TranStamp In(Select Max(b2.TranStamp) From FAS_PartyMaster_AuthTbl_Rep b2          
																					Where b.TranStamp<=@AsOnDate and ((@Filter In('1','M') and b2.EffStatus Like '%' and b2.EffDate<=@RptDate) 
																								or (@Filter In('A') and b2.EffStatus='A' and b2.EffDate<=@RptDate)
																								or (@Filter In('0','H') and b2.EffStatus='H' and b2.EffDate<=@RptDate)
																								)																											
																						and b2.PartyCode=b.PartyCode 			
																						and b2.BranchID=b.BranchID and b2.CompID=b.CompID
																				)     
											)				         
		and a.EffStatus Like Case When @Filter In('1', 'M') Then '%' When @Filter In('A') Then 'A' When @Filter In('0', 'H') Then 'H' When @Filter='D' Then 'D' When @Filter='X' Then 'X' Else '%' End  
		and a.BranchID=@BranchID and a.CompID=@CompID
------------------------------   	 
/*  ERP Acutal Function Query:       
  Select *  From FAS_PartyMaster_AuthTbl_Rep a          
  Where a.TranStamp = (Select Max(b.TranStamp) From FAS_PartyMaster_AuthTbl_Rep b          
               where b.TranStamp <= @AsOnDate           
      and ((@Filter in ('1', 'M'))           
       or (b.isTranLock='1'           
        and Not Exists (Select * From FAS_PartyMaster_AuthTbl_Rep c           
          Where c.TranStamp>b.TranStamp and c.EffStatus Like 'X%'           
           and b.ItemCode=c.ItemCode          
            and c.BranchID=b.BranchID and c.CompID=b.CompID           
          )          
         )           
       OR (@Filter Not in ('1', 'M') and b.EffStatus Like 'A%' and b.EffDate<=@RptDate)          
       )           
      and b.ItemCode=a.ItemCode           
      and b.BranchID=a.BranchID and b.CompID=a.CompID          
   )          
   and a.EffStatus Like Case When @Filter in ('1', 'M') Then '%' When @Filter in ('0', 'A') Then 'AA' When @Filter='H' Then 'AH' When @Filter='D' Then 'AD' When @Filter='X' Then 'AX' Else 'A%' End          
   and a.BranchID=@BranchID and a.CompID=@CompID
*/	                 	         
)
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Rpt_GST_Sales_tmp2]    Script Date: 17/06/2026 11:38:56 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_FAS_Rpt_GST_Sales_tmp2]
(
    @StartDate  DATETIME,
    @EndDate    DATETIME,
    @AsonDate   DATETIME,
    @RptDate    DATETIME,
    @CompCode   VARCHAR(12)
)
RETURNS TABLE
AS
RETURN
(

WITH Params AS
(
    SELECT
        LEFT(@CompCode,4)  AS CompCode4,
        LEFT(@CompCode,2)  AS CompID,
        SUBSTRING(@CompCode,3,2) AS BranchID
),

DocList AS
(
    SELECT
        a.VrRoute,
        a.DocNo,
        a.DocDate,
        a.Amount AS InvoiceValue,
        'INR' AS CurrencyCode,
        a.CompCode AS TranCompCode,
        a.CompCode
    FROM FAS_VoucherTranMast a
    CROSS JOIN Params p
    WHERE a.CompCode = p.CompCode4
      AND a.DocDate BETWEEN @StartDate AND @EndDate
      AND LEFT(a.VrRoute,2) IN ('0K','02','03')
      AND a.IsCancelled='0'
),

BaseTranSub AS
(
    SELECT *
    FROM FAS_VoucherTranSub s
    CROSS JOIN Params p
    WHERE s.CompCode = p.CompCode4
      AND s.DocDate BETWEEN @StartDate AND @EndDate
      AND LEFT(s.VrRoute,2) IN ('0K','02','03')
),

InvoiceLedger AS
(
    SELECT
        s.VrRoute,
        s.DocNo,
        s.DocDate,
        l.LrRoute,
        l.LedgerCode AS LrCode,
        l.LedgerName,
        r.RefType AS InvoiceType,
        r.RefNo AS InvoiceNo,
        r.RefDate AS InvoiceDate,
        s.CompCode
    FROM BaseTranSub s
    JOIN FAS_LedgerMaster_AuthTbl l
        ON l.LedgerCode = s.LrCode
       AND l.CompCode = s.CompCode
       AND (l.LrRoute LIKE '0206%' OR l.LrRoute LIKE '0303%')
    LEFT JOIN FAS_VoucherTranRef r
        ON r.DocNo=s.DocNo
       AND r.DocDate=s.DocDate
       AND r.VrRoute=s.VrRoute
       AND r.CompCode=s.CompCode
),

TaxLedger AS
(
    SELECT
        LrCode,
        TaxName,
        TaxRate,
        TypeFlg,
        CompCode
    FROM FAS_LedgerMaster_Tax
    WHERE GroupFlg='OUTPUT'
      AND CompCode=@CompCode
),

TaxAmounts AS
(
    SELECT
        s.VrRoute,
        s.DocNo,
        s.DocDate,

        CASE
            WHEN t.TaxName IN ('CGST','SGST')
            THEN 'IntraState'
            ELSE 'InterState'
        END AS TaxName,

        SUM(t.TaxRate) AS TaxRate,

        SUM(CASE WHEN t.TaxName='CGST'
            THEN (s.DrAmt-s.CrAmt) ELSE 0 END) AS CGSTTaxAmount,

        SUM(CASE WHEN t.TaxName='SGST'
            THEN (s.DrAmt-s.CrAmt) ELSE 0 END) AS SGSTTaxAmount,

        SUM(CASE WHEN t.TaxName='IGST'
            THEN (s.DrAmt-s.CrAmt) ELSE 0 END) AS IGSTTaxAmount,

        s.CompCode
    FROM BaseTranSub s
    JOIN TaxLedger t
        ON t.LrCode=s.LrCode
       AND t.TypeFlg='Tax'
    GROUP BY
        s.VrRoute,
        s.DocNo,
        s.DocDate,
        CASE
            WHEN t.TaxName IN ('CGST','SGST')
            THEN 'IntraState'
            ELSE 'InterState'
        END,
        s.CompCode
),

GoodsValue AS
(
    SELECT
        VrRoute,
        DocNo,
        DocDate,
        SUM(CrAmt-DrAmt) AS TaxableValue,
        CompCode
    FROM BaseTranSub
    WHERE VTSNo = 2
    GROUP BY
        VrRoute,
        DocNo,
        DocDate,
        CompCode
),

FirstTaxLine AS
(
    SELECT
        s.VrRoute,
        s.DocNo,
        s.DocDate,
        MIN(s.VTSNo) AS FirstTaxVTS
    FROM BaseTranSub s
    JOIN TaxLedger t
        ON t.LrCode=s.LrCode
       AND t.TypeFlg='Tax'
    GROUP BY
        s.VrRoute,
        s.DocNo,
        s.DocDate
),

OtherCharges AS
(
    SELECT
        s.VrRoute,
        s.DocNo,
        s.DocDate,
        SUM(s.CrAmt-s.DrAmt) AS OtherTaxAmount,
        s.CompCode
    FROM BaseTranSub s
    JOIN FirstTaxLine f
        ON f.DocNo=s.DocNo
       AND f.DocDate=s.DocDate
       AND f.VrRoute=s.VrRoute
    WHERE s.VTSNo > 2
      AND s.VTSNo < f.FirstTaxVTS
    GROUP BY
        s.VrRoute,
        s.DocNo,
        s.DocDate,
        s.CompCode
)

SELECT
    d.VrRoute,
    vm.VoucherName AS VoucherType,
    t.TaxName,
    i.LrCode,
    i.LedgerName,
    ISNULL(addr.GSTRegNo,'') AS GSTRegNo,
    d.DocNo,
    d.DocDate,
    i.InvoiceType,
    i.InvoiceNo,
    i.InvoiceDate,

    ISNULL(d.InvoiceValue,0) AS InvoiceValue,

    UPPER(addr.State) AS PlaceOfSupply,

    CASE
        WHEN ISNULL(addr.GSTRegNo,'')<>'' THEN 'N'
        ELSE 'Y'
    END AS ReverseCharge,

    'Regular' AS TypeOfInvoice,
    '' AS ECommerceGSTRegNo,

    ISNULL(t.TaxRate,0) AS TaxRate,

    ABS(ISNULL(g.TaxableValue,0)) AS TaxableValue,

    ABS(ISNULL(t.CGSTTaxAmount,0)) AS CGSTTaxAmount,
    ABS(ISNULL(t.SGSTTaxAmount,0)) AS SGSTTaxAmount,
    ABS(ISNULL(t.IGSTTaxAmount,0)) AS IGSTTaxAmount,

    ABS(ISNULL(o.OtherTaxAmount,0)) AS OtherTaxAmount,

    0 AS CessAmount,

    CASE
        WHEN d.CurrencyCode='INR'
        THEN 0 ELSE 1
    END AS IsExportSales,

    d.TranCompCode,
    d.CompCode

FROM DocList d

LEFT JOIN InvoiceLedger i
    ON d.DocNo=i.DocNo
   AND d.DocDate=i.DocDate
   AND d.VrRoute=i.VrRoute

LEFT JOIN TaxAmounts t
    ON d.DocNo=t.DocNo
   AND d.DocDate=t.DocDate
   AND d.VrRoute=t.VrRoute

LEFT JOIN GoodsValue g
    ON d.DocNo=g.DocNo
   AND d.DocDate=g.DocDate
   AND d.VrRoute=g.VrRoute

LEFT JOIN OtherCharges o
    ON d.DocNo=o.DocNo
   AND d.DocDate=o.DocDate
   AND d.VrRoute=o.VrRoute

LEFT JOIN FAS_LrAddress addr
    ON addr.LrCode=i.LrCode
   AND addr.CompCode=i.CompCode

LEFT JOIN FAS_VoucherMaster vm
    ON d.VrRoute = vm.VrRoute + vm.VrWidth
   AND vm.CompCode = d.CompCode

);
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_Rpt_GST_Sales_V1]    Script Date: 17/06/2026 11:38:56 ******/
SET ANSI_NULLS ON
