CREATE FUNCTION [dbo].[fn_FAS_Rpt_GST_Sales_V1]
(
    @StartDate  DATETIME,
    @EndDate    DATETIME,
    @AsonDate   DATETIME,
    @RptDate    DATETIME,
    @CompCode   VARCHAR(12)
)
RETURNS TABLE
AS
RETURN
(

WITH Params AS
(
    SELECT
        LEFT(@CompCode,4)  AS CompCode4,
        LEFT(@CompCode,2)  AS CompID,
        SUBSTRING(@CompCode,3,2) AS BranchID
),

DocList AS
(
    SELECT
        a.VrRoute,
        a.DocNo,
        a.DocDate,
        a.Amount AS InvoiceValue,
        'INR' AS CurrencyCode,
        a.CompCode AS TranCompCode,
        a.CompCode
    FROM FAS_VoucherTranMast a
    CROSS JOIN Params p
    WHERE a.CompCode = p.CompCode4
      AND a.DocDate BETWEEN @StartDate AND @EndDate
      AND LEFT(a.VrRoute,2) IN ('0K','02','03')
      AND a.IsCancelled='0'
),

BaseTranSub AS
(
    SELECT *
    FROM FAS_VoucherTranSub s
    CROSS JOIN Params p
    WHERE s.CompCode = p.CompCode4
      AND s.DocDate BETWEEN @StartDate AND @EndDate
      AND LEFT(s.VrRoute,2) IN ('0K','02','03')
),

InvoiceLedger AS
(
    SELECT
        s.VrRoute,
        s.DocNo,
        s.DocDate,
        l.LrRoute,
        l.LedgerCode AS LrCode,
        l.LedgerName,
        r.RefType AS InvoiceType,
        r.RefNo AS InvoiceNo,
        r.RefDate AS InvoiceDate,
        s.CompCode
    FROM BaseTranSub s
    JOIN FAS_LedgerMaster_AuthTbl l
        ON l.LedgerCode = s.LrCode
       AND l.CompCode = s.CompCode
       AND (l.LrRoute LIKE '0206%' OR l.LrRoute LIKE '0303%')
    LEFT JOIN FAS_VoucherTranRef r
        ON r.DocNo=s.DocNo
       AND r.DocDate=s.DocDate
       AND r.VrRoute=s.VrRoute
       AND r.CompCode=s.CompCode
),

TaxLedger AS
(
    SELECT
        LrCode,
        TaxName,
        TaxRate,
        TypeFlg,
        CompCode
    FROM FAS_LedgerMaster_Tax
    WHERE GroupFlg='OUTPUT'
      AND CompCode=@CompCode
),

TaxAmounts AS
(
    SELECT
        s.VrRoute,
        s.DocNo,
        s.DocDate,

        CASE
            WHEN t.TaxName IN ('CGST','SGST')
            THEN 'IntraState'
            ELSE 'InterState'
        END AS TaxName,

        SUM(t.TaxRate) AS TaxRate,

        SUM(CASE WHEN t.TaxName='CGST'
            THEN (s.DrAmt-s.CrAmt) ELSE 0 END) AS CGSTTaxAmount,

        SUM(CASE WHEN t.TaxName='SGST'
            THEN (s.DrAmt-s.CrAmt) ELSE 0 END) AS SGSTTaxAmount,

        SUM(CASE WHEN t.TaxName='IGST'
            THEN (s.DrAmt-s.CrAmt) ELSE 0 END) AS IGSTTaxAmount,

        s.CompCode
    FROM BaseTranSub s
    JOIN TaxLedger t
        ON t.LrCode=s.LrCode
       AND t.TypeFlg='Tax'
    GROUP BY
        s.VrRoute,
        s.DocNo,
        s.DocDate,
        CASE
            WHEN t.TaxName IN ('CGST','SGST')
            THEN 'IntraState'
            ELSE 'InterState'
        END,
        s.CompCode
),

GoodsValue AS
(
    SELECT
        VrRoute,
        DocNo,
        DocDate,
        SUM(CrAmt-DrAmt) AS TaxableValue,
        CompCode
    FROM BaseTranSub
    WHERE VTSNo = 2
    GROUP BY
        VrRoute,
        DocNo,
        DocDate,
        CompCode
),

FirstTaxLine AS
(
    SELECT
        s.VrRoute,
        s.DocNo,
        s.DocDate,
        MIN(s.VTSNo) AS FirstTaxVTS
    FROM BaseTranSub s
    JOIN TaxLedger t
        ON t.LrCode=s.LrCode
       AND t.TypeFlg='Tax'
    GROUP BY
        s.VrRoute,
        s.DocNo,
        s.DocDate
),

OtherCharges AS
(
    SELECT
        s.VrRoute,
        s.DocNo,
        s.DocDate,
        SUM(s.CrAmt-s.DrAmt) AS OtherTaxAmount,
        s.CompCode
    FROM BaseTranSub s
    JOIN FirstTaxLine f
        ON f.DocNo=s.DocNo
       AND f.DocDate=s.DocDate
       AND f.VrRoute=s.VrRoute
    WHERE s.VTSNo > 2
      AND s.VTSNo < f.FirstTaxVTS
    GROUP BY
        s.VrRoute,
        s.DocNo,
        s.DocDate,
        s.CompCode
)

SELECT
    d.VrRoute,
    vm.VoucherName AS VoucherType,
    t.TaxName,
    i.LrCode,
    i.LedgerName,
    ISNULL(addr.GSTRegNo,'') AS GSTRegNo,
    d.DocNo,
    d.DocDate,
    i.InvoiceType,
    i.InvoiceNo,
    i.InvoiceDate,

    ISNULL(d.InvoiceValue,0) AS InvoiceValue,

    UPPER(addr.State) AS PlaceOfSupply,

    CASE
        WHEN ISNULL(addr.GSTRegNo,'')<>'' THEN 'N'
        ELSE 'Y'
    END AS ReverseCharge,

    'Regular' AS TypeOfInvoice,
    '' AS ECommerceGSTRegNo,

    ISNULL(t.TaxRate,0) AS TaxRate,

    ABS(ISNULL(g.TaxableValue,0)) AS TaxableValue,

    ABS(ISNULL(t.CGSTTaxAmount,0)) AS CGSTTaxAmount,
    ABS(ISNULL(t.SGSTTaxAmount,0)) AS SGSTTaxAmount,
    ABS(ISNULL(t.IGSTTaxAmount,0)) AS IGSTTaxAmount,

    ABS(ISNULL(o.OtherTaxAmount,0)) AS OtherTaxAmount,

    0 AS CessAmount,

    CASE
        WHEN d.CurrencyCode='INR'
        THEN 0 ELSE 1
    END AS IsExportSales,

    d.TranCompCode,
    d.CompCode

FROM DocList d

LEFT JOIN InvoiceLedger i
    ON d.DocNo=i.DocNo
   AND d.DocDate=i.DocDate
   AND d.VrRoute=i.VrRoute

LEFT JOIN TaxAmounts t
    ON d.DocNo=t.DocNo
   AND d.DocDate=t.DocDate
   AND d.VrRoute=t.VrRoute

LEFT JOIN GoodsValue g
    ON d.DocNo=g.DocNo
   AND d.DocDate=g.DocDate
   AND d.VrRoute=g.VrRoute

LEFT JOIN OtherCharges o
    ON d.DocNo=o.DocNo
   AND d.DocDate=o.DocDate
   AND d.VrRoute=o.VrRoute

LEFT JOIN FAS_LrAddress addr
    ON addr.LrCode=i.LrCode
   AND addr.CompCode=i.CompCode

LEFT JOIN FAS_VoucherMaster vm
    ON d.VrRoute = vm.VrRoute + vm.VrWidth
   AND vm.CompCode = d.CompCode

);
GO

/****** Object:  UserDefinedFunction [dbo].[fn_FAS_StockValue]    Script Date: 17/06/2026 11:38:56 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO


CREATE FUNCTION [dbo].[fn_FAS_StockValue] (@PrStart datetime, @RptDate datetime, @CmCode varchar(12))  

RETURNS TABLE
		
AS  

RETURN 

	(
			Select isNull(m.LedgerCode, n.LedgerCode) as LedgerCode, isNull(m.StockValue, 0) as OpeningStock, isNull(n.StockValue, isNull(m.StockValue, 0)) as ClosingStock, @CmCode as CompCode
			from
				(Select a.LedgerCode, a.StockValue, a.CompCode
				from FAS_StockEntry a
				Inner Join
					(Select LedgerCode,  Max(StockDate) as StockDate, CompCode
					from FAS_StockEntry  
					Where StockDate < @PrStart and CompCode=@CmCode
					Group by LedgerCode, CompCode
					) b
				On a.LedgerCode=b.LedgerCode and a.StockDate=b.StockDate and a.CompCode=b.CompCode
				Where a.CompCode=@CmCode
				) m
		
			Full Outer Join
		
				(Select a.LedgerCode, a.StockValue, a.CompCode
				from FAS_StockEntry a
				Inner Join
					(Select LedgerCode,  Max(StockDate) as StockDate, CompCode
					from FAS_StockEntry  
					Where StockDate <= @RptDate and CompCode=@CmCode
					Group by LedgerCode, CompCode
					) b
				On a.LedgerCode=b.LedgerCode and a.StockDate=b.StockDate and a.CompCode=b.CompCode
				Where a.CompCode=@CmCode
				) n
		
			On m.LedgerCode=n.LedgerCode and m.CompCode=n.CompCode

	)



GO

