CREATE FUNCTION [dbo].[fn_INV_ToolTran_Dtl] ( @AsOnDate datetime, @BranchID varchar(3), @CompID varchar(3))  


RETURNS  TABLE

AS

RETURN
	 (Select *,(Select top 1 Groupcode from BOM_StagewisetoolMaster_dtl Where ItemCode=a.StageCode and MachineCode=a.MachineCode and Toolcode=a.ToolCode and Branchid=a.Branchid and Compid=a.Compid )GroupCode from INV_ToolTran_Dtl a
		  Where a.Transtamp = (Select max(b.Transtamp) from INV_ToolTran_Dtl b where b.Transtamp <= @AsOnDate 
		   and b.StageCode=a.StageCode and b.MachineCode=a.MachineCode and b.ToolCode=a.ToolCode and b.BranchID=a.BranchID and b.CompID=a.CompID 
		   )
		   and a.BranchID=@BranchID and a.CompID=@CompID AND IsReceipt=0 )
