/****** Object:  UserDefinedFunction [dbo].[fn_INV_Warehouse_Master_Get_All]    Script Date: 17/06/2026 11:38:56 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE Function [dbo].[fn_INV_Warehouse_Master_Get_All](@WhStatus bit='1', @AsOnDate datetime, 
	@RptDate datetime, @BranchID Varchar(3), @CompID Varchar(3),@Finyear varchar(20))          
Returns Table     
Return          
(
  Select a.WarehouseCode, a.WarehouseName, a.WarehouseNature, a.WarehouseLocation, 
				IsNull(b.RackBinCode, '') As RackBinCode, IsNull(b.Description, '') As RackBinDesc, 
				IsNull(a.WarehouseStatus, '0') As WarehouseStatus, a.BranchID, a.CompID      
  From INV_Warehouse_Master a      
  Left Outer Join INV_RackBin_Master b      
		On a.WarehouseCode=b.WarehouseCode and a.BranchID=b.BranchID and a.CompID=b.CompID
	Where a.WarehouseStatus=@WhStatus and a.BranchID=@BranchId and a.CompID=@CompID				                  
  UNION                                  
  Select m.WarehouseCode, m.WarehouseName, m.WarehouseNature, m.WarehouseLocation,       
        '' As RackBinCode, '' As RackBinDesc, IsNull(m.WarehouseStatus, '0') As WarehouseStatus,       
        m.BranchID, m.CompID      
  From INV_WarehouseTemp_Master m 
  Where m.WarehouseStatus=@WhStatus and m.BranchID=@BranchId and m.CompID=@CompID
)
GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_HRD_ManDaysLostReport]    Script Date: 17/06/2026 11:38:56 ******/
