GO

CREATE FUNCTION [dbo].[fn_MIS_HRD_ManDaysLostReport] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS TABLE

 AS  

Return 	(
	Select convert(VarChar(7),a.LeaveDate,126) as YearMonth, sum(LeaveDays) As DataValue1 
		from PAY_Attendance_Entry a 
		Where convert(VarChar(7),a.LeaveDate,126) between @FromDate and @ToDate
		and a.AbsentType='A' and a.Branchid = @BranchID and a.Compid = @CompID
	group by convert(VarChar(7),a.LeaveDate,126)
	)

GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_PUR_OnTimeDeliveryReport]    Script Date: 17/06/2026 11:38:56 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE  FUNCTION [dbo].[fn_MIS_PUR_OnTimeDeliveryReport] (@Cust varchar(10), @CurrDateTime datetime, @CurrDate datetime, @FromDate varchar(7), @ToDate varchar(7),@AsonDate datetime,@RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS  TABLE

	
 AS  

Return (
	Select Convert(VarChar(7),b.RequiredDate,126) As YearMonth, (100-Avg(DateDiff(day, 
				 b.RequiredDate, IsNull(a.RefDocDate, @CurrDate)))) As DataValue1 
	From dbo.fn_PUR_Schedule(@CurrDateTime, @CurrDate, @BranchID, @Compid, @Finyear) b 
	Left Outer Join (Select * From PUR_Schedule_Receive_Dtl Where AcceptedQty > 0) a    
	    On a.ScheduleType = b.ScheduleType and a.ScheduleNo = b.ScheduleNo and a.ScheduleDate = b.ScheduleDate  
		and a.ItemCode = b.ItemCode and a.RequiredDate = b.RequiredDate  and a.Branchid = b.Branchid and a.Compid = b.Compid  
	Left Outer Join FAS_Party_Master c  
	    On b.VendorCode = c.PartyCode and b.Branchid = c.Branchid and b.Compid = c.Compid 
/*
	Left Outer Join dbo.fn_BOM_Material_Master('A',@AsonDate,@RptDate,@BranchID,@CompID) d 
	  On b.ItemCode = d.ItemCode and b.Branchid = d.Branchid and b.Compid = d.Compid 
	Left Outer Join dbo.fn_BOM_Get_Material_Master('A',@AsonDate,@RptDate,@BranchID,@CompID) d1 
	  On b.ItemCode = d1.ItemCode and b.Branchid = d1.Branchid and b.Compid = d1.Compid 
*/
	Where Convert(VarChar(7),b.RequiredDate,126) Between @FromDate and @ToDate and a.Branchid = @BranchID and a.Compid = @Compid 
	Group by Convert(VarChar(7),b.RequiredDate,126)	
)

GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_QC_CostofPoorQualityReport]    Script Date: 17/06/2026 11:38:56 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_MIS_QC_CostofPoorQualityReport] (@FromDate varchar(7), @ToDate varchar(7),@AsonDate datetime,@RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS TABLE

 AS  

Return 	(
		Select Convert(VarChar(7),x.InspectionDate,126) As YearMonth, Sum(Qty*d.Rate) As DataValue1 From 
			(
				Select Distinct InspectionDate,Inspectionno,ItemCode,Qty,Branchid,Compid From Qc_Inspection_Criteria Where Type='C' and CriteriaCode in (4)
				Union
				Select a.InspectionDate,a.Inspectionno,b.ItemCode,a.Qty,a.Branchid,a.Compid From Qc_Inspection_Criteria1 a
					Left Outer Join Qc_Inspection_Hdr1 b
						On a.InspectionType=b.InspectionType and a.Inspectionno=b.Inspectionno and a.Inspectiondate=b.InspectionDate
						and a.Branchid=b.Branchid and a.Compid=b.Compid Where CriteriaCode In (4)
			) x
		Left Outer Join BOM_MPS_Master c
		    On c.StageCode=x.ItemCode and c.Branchid=x.Branchid and c.Compid=x.Compid
		
		Left Outer Join ( Select ItemCode, Max(Rate)Rate,Branchid,Compid From SAL_Invoice_Dtl 
				Group by ItemCode,Branchid,Compid ) d
		    On d.ItemCode=c.ItemCode and d.Branchid=c.Branchid and d.Compid=c.Compid
		
		Where Convert(VarChar(7),x.InspectionDate,126) Between @FromDate and @ToDate
			and x.Branchid=@Branchid and x.Compid=@Compid
		Group by Convert(VarChar(7),x.InspectionDate,126)
		-- Order by Convert(VarChar(7),x.InspectionDate,126)
	)
GO

/****** Object:  UserDefinedFunction [dbo].[fn_MIS_SAL_SalesDeliveryComplianceReport]    Script Date: 17/06/2026 11:38:56 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_MIS_SAL_SalesDeliveryComplianceReport] (@FromDate varchar(7), @ToDate varchar(7), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  

RETURNS Table

As		
	
	Return 
	(
		Select IsNull(x.YearMonth,y.YearMonth) As YearMonth, IsNull((Sum(y.InvoiceQty)/Sum(x.PlanQty))*100,0) As Datavalue1
		From (
				Select Convert(VarChar(7),a.PlanPeriod,126)yearMonth,ItemCode, Sum(PlanQty) As PlanQty
				 From SAL_SalesPlan a 
				 Where Convert(VarChar(7),a.PlanPeriod,126)Between  @FromDate and @ToDate
					and a.Branchid =@BranchiD and a.CompID= @CompID
					and a.RevisionNo=(Select Max(a1.RevisionNo) From Sal_SalesPlan a1 
							Where a1.DocType = a.DocType and a1.DocNo = a.DocNo and a1.DocDate = a.DocDate 
								and Convert(VarChar(7),a1.PlanPeriod,126) Between  @FromDate and @ToDate
								and a1.BranchID=a.BranchID and a1.CompID=a.CompID
						       ) and a.PlanFor=2
				Group by Convert(VarChar(7),a.PlanPeriod,126),ItemCode
			) x
			
			Full outer join 
				(
					Select Convert(VarChar(7),InvoiceDate,126)YearMonth,ItemCode, Sum(InvoiceQty) As InvoiceQty 
					From SalesInvoice
				 	Where Convert(VarChar(7),InvoiceDate,126) Between @FromDate and @ToDate
						 and Branchid =@BranchiD and Compid =  @Compid and Type in ('OE', 'Labour','VAT')
					Group by Convert(VarChar(7),InvoiceDate,126),ItemCode
				) y 
			
			On x.YearMonth=y.YearMonth and x.ItemCode=y.ItemCode
			Group by IsNull(x.YearMonth, y.YearMonth)
			--Order by IsNull(x.YearMonth,y.YearMonth)
	)


GO

