/****** Object:  UserDefinedFunction [dbo].[fn_PPC_AssemblyWorkOrder]    Script Date: 17/06/2026 11:38:56 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_PPC_AssemblyWorkOrder](@BranchID varchar(3),  @CompID varchar(3))

RETURNS TABLE

AS

RETURN

(
select a.AssemblyWorkOrderType, a.AssemblyWorkOrderNo, a.AssemblyWorkOrderDate, a.ParentCode, a.WorkOrderQty, 

isnull((select sum(f.InwardGoodsReceiptQty) from PPC_InwardGoodsReceipt f where f.WorkOrderType = a.AssemblyWorkOrderType 
and f.WorkOrderNo = a.AssemblyWorkOrderNo and f.WorkOrderDate = a.AssemblyWorkOrderDate and f.ItemCode=a.ParentCode and f.Branchid = a.Branchid 
and f.Compid = a.Compid),0) as CompletedQty, 

a.CompletedStatus, a.WOShortClose, a.StoreRequestStatus, a.RejectionQty, a.ScrapQty, b.ItemCode, b.RequiredQty, b.Norms,

(isNull((select sum(d.TransactionQty) from INV_MaterialTran_dtl d where d.DOCType=c.StoreRequestType and d.DOCNo=c.StoreRequestNo
and d.DOCDate=c.StoreRequestDate and d.TransactionItem=c.ItemCode and d.Branchid=c.Branchid and d.Compid=c.Compid),0) -

isnull((select sum(e.ReturnQty) from MaterialReturnNote e where  e.StoreRequestType=c.StoreRequestType 
and e.StoreRequestNo=c.StoreRequestNo  and e.StoreRequestDate=c.StoreRequestDate and e.ItemCode=c.ItemCode 
and e.Branchid=c.Branchid and e.Compid=c.Compid),0)) as IssuedQty,
b.MRNStatus, a.Branchid, a.Compid, b.Finyear
from PPC_ASSEMBLYWORKORDER_HDR a 
	Inner Join PPC_ASSEMBLYWORKORDER_DTL b 
		On a.AssemblyWorkOrderNo=b.AssemblyWorkOrderNo and a.AssemblyWorkOrderDate=b.AssemblyWorkOrderDate
		and a.AssemblyWorkOrderType=b.AssemblyWorkOrderType and a.Branchid=b.Branchid and a.Compid=b.Compid
	left outer join StoreRequest c 
		on c.WOType=a.AssemblyWorkOrderType and c.WONo=a.AssemblyWorkOrderNo and c.WODate=a.AssemblyWorkOrderDate 
		and c.ItemCode=b.ItemCode and c.Branchid=a.Branchid and c.Compid=a.Compid
	where a.Branchid = @BranchID and a.Compid = @CompID
)
GO

/****** Object:  UserDefinedFunction [dbo].[fn_PPC_ProcessWorkOrder]    Script Date: 17/06/2026 11:38:56 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_PPC_ProcessWorkOrder](@BranchID varchar(3),  @CompID varchar(3))

RETURNS TABLE

AS

RETURN

(
	Select distinct a.ProcessWorkOrderType, a.ProcessWorkOrderNo, a.ProcessWorkOrderDate, a.ParentCode, a.FromStageCode, 
	a.ToStageCode, a.RequiredQty, a.WorkOrderQty, a.Norms, 
	
	(isNull((select sum(d.TransactionQty) from INV_MaterialTran_dtl d where d.DOCType=c.StoreRequestType  
	and d.DOCNo=c.StoreRequestNo and d.DOCDate=c.StoreRequestDate and d.TransactionItem=c.ItemCode  and d.Branchid=c.Branchid
	and d.Compid=c.Compid),0) - 
	
	isnull((select sum(e.ReturnQty) from MaterialReturnNote e where  e.StoreRequestType=c.StoreRequestType 
	and e.StoreRequestNo=c.StoreRequestNo  and e.StoreRequestDate=c.StoreRequestDate and e.ItemCode=c.ItemCode 
	and e.Branchid=c.Branchid and e.Compid=c.Compid),0)) IssuedQty, 
	
	isnull((select sum(f.InwardGoodsReceiptQty) from PPC_InwardGoodsReceipt f where  f.WorkOrderType = a.ProcessWorkOrderType
	 and f.WorkOrderNo = a.ProcessWorkOrderNo  and f.WorkOrderDate = a.ProcessWorkOrderDate and f.ItemCode=a.ToStageCode 
	and f.Branchid = a.Branchid and f.Compid = a.Compid),0) as CompletedQty, 
	
	a.CompletedStatus, WOShortClose, a.Branchid, a.Compid, a.Finyear
	
	from PPC_ProcessWorkOrder a 
	left outer join StoreRequest c on c.WOType=a.ProcessWorkOrderType and c.WONo=a.ProcessWorkOrderNo
	and c.WODate=a.ProcessWorkOrderDate and c.ItemCode=a.FromStageCode and c.Branchid=a.Branchid and c.Compid=a.Compid
	where a.Branchid = @BranchID and a.Compid = @CompID  and WOShortClose='0'
)



GO

/****** Object:  UserDefinedFunction [dbo].[fn_PPC_ReworkOrder]    Script Date: 17/06/2026 11:38:56 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_PPC_ReworkOrder](@BranchID varchar(3),  @CompID varchar(3))

RETURNS TABLE

AS

RETURN

(
	Select distinct a.ReworkOrderType, a.ReworkOrderNo, a.ReworkOrderDate, a.StageCode,
	a.WorkOrderQty, a.Norms, a.RequiredQty,
	
	(isNull((select sum(d.TransactionQty) from INV_MaterialTran_dtl d where d.DOCType=c.StoreRequestType  
	and d.DOCNo=c.StoreRequestNo and d.DOCDate=c.StoreRequestDate and d.TransactionItem=c.ItemCode  and d.Branchid=c.Branchid
	and d.Compid=c.Compid),0) - 
	
	isnull((select sum(e.ReturnQty) from MaterialReturnNote e where  e.StoreRequestType=c.StoreRequestType 
	and e.StoreRequestNo=c.StoreRequestNo  and e.StoreRequestDate=c.StoreRequestDate and e.ItemCode=c.ItemCode 
	and e.Branchid=c.Branchid and e.Compid=c.Compid),0)) IssuedQty, 
	
	isnull((select sum(f.InwardGoodsReceiptQty) from PPC_InwardGoodsReceipt f where  f.WorkOrderType = a.ReworkOrderType
	 and f.WorkOrderNo = a.ReworkOrderNo  and f.WorkOrderDate = a.ReworkOrderDate and f.ItemCode=a.StageCode 
	and f.Branchid = a.Branchid and f.Compid = a.Compid),0) as CompletedQty, 
	
	a.CompletedStatus, a.WOShortClose, a.Branchid, a.Compid, a.Finyear
	
	from PPC_ReWorkOrder a 
		left outer join StoreRequest c on c.WOType=a.ReworkOrderType and c.WONo=a.ReworkOrderNo
		and c.WODate=a.ReworkOrderDate and c.ItemCode=a.StageCode and c.Branchid=a.Branchid and c.Compid=a.Compid

	where a.Branchid = @BranchID and a.Compid = @CompID
)
GO

/****** Object:  UserDefinedFunction [dbo].[fn_PUR_Get_BillNotBooked_RRDoc]    Script Date: 17/06/2026 11:38:56 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[fn_PUR_Get_BillNotBooked_RRDoc] (@FromDate datetime, @ToDate datetime, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear Varchar(15))        
      
RETURNS TABLE  
AS    
Return   
 (    
  Select a.BatchType, a.BatchNo, a.BatchDate, a.ItemCode,  
   ( (Case When a.IRRQty=0 Then Case When a.ISVQty =0 then a.GateQty Else a.ISVQty End Else a.IRRQty End) * IsNull(d.Rate, 0)) as BillNotBookedValue  
  From  
  (  
		   Select x.ReceiptEntryType as BatchType, x.ReceiptEntryNo as BatchNo, x.ReceiptEntryDate as BatchDate, x.ItemCode, x.ScheduleDate, 
		   Sum(ChallanQty) as GateQty, Sum(ReceiptQty) as ISVQty , Sum(AcceptedQty) as IRRQty
			--Sum(case when GroupCode='-1' then x.Qty Else 0 end) As GateQty,               
			--Sum(case when GroupCode='-2' then x.Qty Else 0 end) As ISVQty ,               
			--Sum(case when GroupCode not in ('-1','-2','Rejection', 'Scrap') then x.Qty Else 0 end) As IRRQty, s1.InspectionAccQty  
		   from REC_ReceiptEntry_Dtl x    
		   Left outer join REC_RECEIPTENTRY_HDR y             
			On x.ReceiptEntryType=y.ReceiptEntryType and x.ReceiptEntryNo=y.ReceiptEntryNo and x.ReceiptEntryDate=y.ReceiptEntryDate                 
			and x.BranchId=y.BranchID and x.CompID=y.CompID           
		   /*Outer Apply    
			(  
			 Select Sum(d.Accpted) as InspectionAccQty    
			  From dbo.fn_QC_BaseDoc_RR_Rpt (@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) d                    
  
			 Left Outer Join dbo.fn_QC_BaseDoc_RR_Rpt (@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) d1                    
			  On d.INSType=d1.BaseType and d.INSNo=d1.BaseNo and d.INSDate=d1.BaseDate    
			  and d.ItemCode=d1.ItemCode and d1.INSType='RIN'       
  
			 Left Outer Join REC_ReceiptEntry_Dtl d2  
			  On d.BaseNo=d2.DocNo and d.BaseDate=d2.DocDate and d.BaseType=d2.DocType and d.ItemCode=d2.Itemcode   
			  and d2.BatchNo=x.BatchNo and d2.BatchDate=x.BatchDate and d2.Batchtype=x.Batchtype  
			  and d.BranchId=d2.BranchID and d.CompID=d2.CompID  
  
			 Where d.BaseNo=x.DocNo and d.BaseDate=x.DocDate and d.BaseType=x.DocType and d.ItemCode=x.ItemCode     
			  and d.BranchID=x.BranchID and d.CompID=x.CompID and d.INSType<>'RIN' --(RIN -> ReInspection)    
			  and d2.GroupCode='-2'  
			  and d2.ShortClose='0'   
    
			 Having (Sum(d.Accpted)=0 and Sum(d2.Qty)=(Case When sum(d1.Rejected) is Null Then IsNull(sum(d.Rejected),0) Else IsNull(sum(d1.Rejected),0) End     
						 +  Case When sum(d1.Rework) is Null Then IsNull(sum(d.Rework),0) Else IsNull(sum(d1.Rework),0) End ))      
			)s1  */
		   Where y.InwardType ='P'  --and x.ShortClose='0' 
		   and x.ReceiptEntryDate between @FromDate and @ToDate  
			 and x.BranchID=@BranchID and x.CompID=@CompID  
			 and Not Exists  
			  (  
			   Select * From PUR_PurchaseInvoice_Ref s  
			   Where s.RefType=x.ReceiptEntryType and s.RefNo=x.ReceiptEntryNo and s.RefDate=x.ReceiptEntryDate and s.ItemCode=x.ItemCode  
				and s.BranchId=x.BranchID and s.CompID=x.CompID   
			  )   
		   Group by x.ReceiptEntryType, x.ReceiptEntryNo, x.ReceiptEntryDate, x.ItemCode, x.ScheduleDate --, s1.InspectionAccQty  
  )a  
  Left Outer Join REC_ReceiptEntry_Dtl b             
   On a.BatchType=b.ReceiptEntryType and a.BatchNo=b.ReceiptEntryNo and a.BatchDate=b.ReceiptEntryDate                 
   and b.BranchID=@BranchID and b.CompId=@CompId  
  
  Left Outer Join fn_PUR_Schedule(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) c   
   On c.ScheduleType=b.RefType and c.ScheduleNo=b.RefNo and c.ScheduleDate=b.RefDate  and c.ItemCode= a.Itemcode   
   and c.RequiredDate=a.ScheduleDate    
  
  Left Outer Join dbo.fn_PUR_PurchaseOrder_Dtl(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear)d  
   On c.OrderType=d.OrderType and c.OrderNo=d.OrderNo and c.OrderDate=d.OrderDate and c.ItemCode=d.ItemCode  
  
  Where c.Status<>'C' and ((Gateqty>0 and ISVQty=0 and IRRQty=0) Or (GateQty>0 and ISVQty>0 and IRRQty=0) Or (GateQty>0 and ISVQty>0 and IRRQty>0))   
        -- AND (a.InspectionAccQty is Null OR a.InspectionAccQty>0)  
   and Not Exists  
    (  
     Select * From REC_ReceiptEntry_Dtl m   
     Where m.ReceiptEntryType = a.BatchType and m.ReceiptEntryNo = a.BatchNo and m.ReceiptEntryDate = a.BatchDate and m.ItemCode=a.ItemCode --and m.GroupCode='-2'   
      and m.BranchID=@BranchID and m.CompID=@CompID  
     Having Sum(m.ChallanQty) = 0  
    )   
  --Group by a.BatchType, a.BatchNo, a.BatchDate, a.ItemCode  
     
   )  
  
GO

/****** Object:  UserDefinedFunction [dbo].[fn_PUR_VendorRating_DisQualification]    Script Date: 17/06/2026 11:38:56 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


    CREATE FUNCTION [dbo].[fn_PUR_VendorRating_DisQualification] (@Filter char(1)='A', @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3))    
--@Filter = ('1', 'M') returns Max Transtamp Data; @Filter=('0', 'A') returns Max Authorised Data, @Filter='H'/'D'/'X' returns Max Hold/Delete/Cancel Data  
  
RETURNS TABLE  
  
 AS    
  
Return   
  
(  
  
 Select * from PUR_VendorRating_DisQualification a  
  Where a.TranStamp = (Select Max(b.TranStamp) from PUR_VendorRating_DisQualification b  
               Where b.TranStamp <= @AsOnDate and ((@Filter in ('1', 'M'))   
       OR (b.isTranLock='1'   
        AND Not Exists (Select * From PUR_VendorRating_DisQualification c   
          Where c.TranStamp>b.TranStamp and c.EffStatus Like 'X%'   
           and b.RatingCode=c.RatingCode  and b.Grade=c.Grade and b.DisqualificationCount=c.DisqualificationCount   
           and b.BranchID=c.BranchID and b.CompID=c.CompID  
          )  
         )   
       OR (@Filter Not in ('1', 'M') and b.EffStatus Like 'A%' and b.EffDate<=@RptDate)  
       )   
      and b.RatingCode=a.RatingCode  and b.Grade=a.Grade and b.DisqualificationCount=a.DisqualificationCount   
      and b.BranchID=a.BranchID and b.CompID=a.CompID  
             )  
  and a.EffStatus Like Case When @Filter in ('1', 'M') Then '%' When @Filter in ('0', 'A') Then 'AA' When @Filter='H' Then 'AH' When @Filter='D' Then 'AD' When @Filter='X' Then 'AX' Else 'A%' End  
  and a.BranchID=@BranchID and a.CompID=@CompID   
 )  
  
GO

