/****** Object:  UserDefinedFunction [dbo].[fn_PUR_VendorRating_PremiumFreight]    Script Date: 17/06/2026 11:38:56 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


 CREATE FUNCTION [dbo].[fn_PUR_VendorRating_PremiumFreight] (@Filter char(1)='M', @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3))            
--@Filter = ('1', 'M') returns Max Transtamp Data; @Filter=('0', 'A') returns Max Authorised Data, @Filter='H'/'D'/'X' returns Max Hold/Delete/Cancel Data          
RETURNS TABLE          
 AS            
Return           
(          
 Select * from PUR_VendorRating_PremiumFreight a          
  Where a.TranStamp = (Select Max(b.TranStamp) from PUR_VendorRating_PremiumFreight b          
               Where b.TranStamp <= @AsOnDate and ((@Filter in ('1', 'M'))           
       OR (b.isTranLock='1'           
        AND Not Exists (Select * From PUR_VendorRating_PremiumFreight c           
          Where c.TranStamp>b.TranStamp and c.EffStatus Like 'X%'           
           and b.RatingCode=c.RatingCode and b.Seq=c.Seq-- b.FromRank=c.FromRank and b.ToRank=c.ToRank           
           and b.BranchID=c.BranchID and b.CompID=c.CompID          
          )          
         )           
       OR (@Filter Not in ('1', 'M') and b.EffStatus Like 'A%' and b.EffDate<=@RptDate)          
       )           
      and b.RatingCode=a.RatingCode  and b.Seq=a.Seq--b.FromRank=a.FromRank and b.ToRank=a.ToRank           
      and b.BranchID=a.BranchID and b.CompID=a.CompID          
             )          
  and a.EffStatus Like Case When @Filter in ('1', 'M') Then '%' When @Filter in ('0', 'A') Then 'AA' When @Filter='H' Then 'AH' When @Filter='D' Then 'AD' When @Filter='X' Then 'AX' Else 'A%' End          
  and a.BranchID=@BranchID and a.CompID=@CompID           
 ) 

GO

