CREATE FUNCTION [dbo].[fn_QMS_V1_StandardDocument_Dtl_Rep](@AsOnDate datetime, @RptDate datetime, 
@BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))          
RETURNS TABLE        
 AS          
Return         
(        	
	Select a.StdID, a.DocNo, a.DocDate, a.LevelSerialNo, a.MainContent, a.SubContent, a.Parent,
		a.Relation, a.SeqNo, a.SymRef, a.RefValue, a.DocFileID, a.Remarks, a.FromDate, a.ToDate,
		a.EffStatus, a.UserID, a.BranchID, a.CompID, a.Finyear, a.TranStamp 
	From QMS_V1_StandardDocument_Dtl_Rep a 	       
  Where a.TranStamp=(Select Max(b.TranStamp) From QMS_V1_StandardDocument_Dtl_Rep b        
										 Where b.TranStamp<=@AsOnDate and b.DocNo=a.DocNo and b.DocDate=a.DocDate   
												and b.SeqNo=a.SeqNo and b.FromDate=a.FromDate /*and b.ToDate=a.ToDate*/
												and b.BranchID=a.BranchID and b.CompID=a.CompID and b.Finyear=a.Finyear
										)
			and a.BranchID=@BranchID and a.CompID=@CompID and A.Finyear=@Finyear
)    
GO

