/****** Object:  UserDefinedFunction [dbo].[fn_SAL_DCSR_SubContract]    Script Date: 17/06/2026 11:38:56 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE FUNCTION [dbo].[fn_SAL_DCSR_SubContract](@AsOnDate datetime, @RptDate datetime,@BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  
   

RETURNS  TABLE
 

 AS  

Return(
	Select a.RecdItemCode,sum(d.ScheduleQty) as PendingQty,a.BranchID, a.CompID
	from dbo.fn_PUR_DCSR_Schedule(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) a
	Left Outer Join dbo.fn_PUR_DCSR_Tran(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) d
		on d.DCSRType = a.DCSRType and d.DCSRNo = a.DCSRNo and d.DCSRDate = a.DCSRDate 
		and a.ItemGroupkey = d.ItemGroupkey and d.BranchID = a.BranchID and d.CompID = a.CompID
	WHERE a.Status<>'C' and a.Finyear = @Finyear 
	Group By a.RecdItemCode,a.BranchID, a.CompID
	HAVING sum(d.ScheduleQty) >0
)
GO

/****** Object:  UserDefinedFunction [dbo].[fn_SAL_Rpt_TraceabilityReport_Sel]    Script Date: 17/06/2026 11:38:56 ******/
