CREATE FUNCTION [dbo].[fn_SAL_Rpt_TraceabilityReport_Sel](@FromDate datetime, @ToDate datetime, @BranchID varchar(3), @CompID varchar(3), @FinYear Varchar(20))                    
                                            
RETURNS TABLE                                              
                                             
AS                                            
                                        
RETURN                                            
(                           
     
  Select distinct a.TransactionItem as ItemCode, b.ItemDescription     
  From INV_MaterialTran_Dtl a    
  Left Outer Join INV_Material_Master b    
 On a.TransactionItem=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID  
  Where a.DocDate between @FromDate and @ToDate and a.BranchID = @BranchID and a.CompID=@CompID and a.Finyear=@Finyear  
 --and a.DocType not in ('SV','OPBAL', 'OPB') 
 and a.DocType  in ('INV') 
 and Exists   
    (  
     Select * From BOM_TraceableItems t   
     Where t.ItemCode=a.TransactionItem  
    )  
    
     
  /*Select distinct a.ItemCode, b.ItemDescription     
  From SalesInvoice a    
  Left Outer Join INV_Material_Master b    
 On a.ItemCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID  
  where a.InvoiceDate between @FromDate and @ToDate and a.BranchID = @BranchID and a.CompID=@CompID */    
     
)

GO

